local addon = WoWKoreanClient
if not addon.active then return end
local text = addon.worldText.greeting
if not text then
    text = { values = {}, templates = {} }
    addon.worldText.greeting = text
end
local rows = text.values
rows["100:101479624"]="서부 경매소는 바자르의 한가운데서 서쪽 노인 거리에서 발견될 수 있습니다."
rows["100:1113343789"]="다음 화공 공연을 위해 여기 머물러라 6PM, 그들은 시간마다!"
rows["100:1155403110"]="지나가면서 내 옆에 멈추고 싶어 했던 거 다 안다고. 뭘 해 드릴까, 귀여운 친구?"
rows["100:1392318518"]="이 고대 토템은 박쥐 모양을 하고 있습니다. 이 고대 토템은 박쥐 모양을 하고 있습니다. 메이위키가 말한 그 토템이 확실합니다."
rows["100:1576056178"]="넌 내겐 별로 닮지 않지만 누가 알겠어, 어쩌면 어딘가에 마법사가 숨어있지도 몰라!"
rows["100:160139105"]="뛰어난 승마 기술을 가르쳐 드리겠습니다. 단, 수업료는 제대로 내셔야 합니다!"
rows["100:1606634258"]="상업 지구 중간층에서 유니스 버치가... 여기서 \"음식\"이라고 부르는 걸 만들더군. 뭐, 자네가 먹는 거지 내가 먹는 건 아니니까."
rows["100:1702814499"]="이 못생긴 트롤들을 쳐다보는 것보다 에어리 픽에서 집에 있는 것이 낫다"
rows["100:1735629333"]="항상 누군가는 병역 의무에서 면제되지요. 노련한 어부란 유용한 존재랍니다... 사령관도 먹어야 사는 법이니 말입니다."
rows["100:1838499629"]="어딘가 고장 나지 않았다는 말이 고칠 수 없다는 뜻은 아니죠. 뭐 찾으세요, $g멋쟁이:예쁜이;?"
rows["100:184134540"]="흠, 좋아요. 잘난 척하진 마세요! 당신 실력을 입증해 보였으니 이제 시작합시다!"
rows["100:1849401954"]="무슨 일입니까? 바쁜 게 안 보입니까? 어둠의 의회에서는 시간당 수당이나 주면서 저를 고용한 것이 아닙니다!"
rows["100:1878354377"]="흠, 좋아요. 잘난 척하진 마세요! 당신 실력을 입증해 보였으니 이제 시작합시다!"
rows["100:1889804484"]="아, 아주 잘했소. 당신은 내게 배울 자격이 있군. 당신이 나의 제자가 된다는 사실이 아주 흡족하군. 자, 이제 훈련을 시작합시다..."
rows["100:1890098465"]="아, 아주 잘했소. 당신은 내게 배울 자격이 있군. 당신이 나의 제자가 된다는 사실이 아주 흡족하군. 자, 이제 훈련을 시작합시다..."
rows["100:1950081956"]="왜 해적들이 항상 보물을 땅에 파묻는지 도무지 이해 안 된단 말이죠. 난 말입니다... 보물은 내 손이 닿는 데 두고 싶거든요."
rows["100:1970136772"]="로데론의 리들리는 반 브런트들과 함께 전쟁 구역에서 동조를 하고 있습니다. 그는 내부 반지에 있습니다."
rows["100:1976392002"]="그대에게 뛰어난 호랑이 기수가 되는 방법을 가르쳐 드리겠습니다. 그런데 수업료로 낼 골드는 충분한가요?!"
rows["100:2004780717"]="해질 무렵까지도 불길이 활활 타올랐네. 모든 걸 잃었어. 전부 다.$B$B대체 여관을 왜 불태우는 거지?"
rows["100:2145323171"]="기본기를 좀 더 다지고 오셔야겠습니다. 그렇지 않으면 저도 도와드릴 수가 없겠군요. 준비가 되거든 그때 다시 찾아오십시오."
rows["100:216084633"]="<지리 주위의 광채가 푸른 빛을 띱니다. 이 나루가 전장에 함께하는 동맹으로서 당신을 환영하고 있습니다.>"
rows["100:234007524"]="내 주인인 플러거 스파즈링은 좋은 보스이고, 돈도 많이 벌고, 주머니가 터져요!"
rows["100:273255831"]="리치 왕의 은총을 바라는 놈이 또 있군?$b$b자격이 있는 자만이 암흑의 선물을 받을 것이다..."
rows["100:30911001"]="난 더는 가르칠 게 없군요. 가죽세공에 대해 더 많은 것을 배우려면 카롤렉에게 가보세요."
rows["100:344247840"]="< lady Aegya의 눈의 텅 빈 소켓은 어떤 칼보다 더 깊은 눈을 깎아 내린다.>"
rows["100:398348977"]="다라란 북부에서 모든 것을 위한 탱크는 도시의 가장 인기있는 방패와 갑옷 거래자입니다."
rows["100:428303570"]="이 전단의 내용은 당신의 능력으로 감당하기엔 무리가 있습니다.$B$B나중에 다시 확인하는 것이 좋겠습니다."
rows["100:435091633"]="신선한 고기...\010\010<그  ⁇ 은 계속 그 말을 통해 울고 있다.>\010\010죽고, 고기를 먹고...\010\010줄리... 도망..."
rows["100:499411232"]="편안히 침대에 누워 깊은 휴식을 취하고 싶으시면 돌라나르 여관으로 한번 가 보세요. 켈다미르가 운영하고 있습니다."
rows["100:551600549"]="킬리가 자네더러 날 끌고 오라고 했나 본데, 그냥 잊어버리라고. 난 저 황혼의 망치단 놈들을 혼내 줘야 하니까."
rows["100:579598629"]="가장 빠른 늑대가 당신을 타운카르 마을까지 데려다 줄 거요. 용사여, 준비가 끝나면 알려주시오."
rows["100:586394291"]="안녕하신가. 나는 드레나이이자 모든 이의 스승인 수도자 델란이라고 하네. 그런데 자네는 누군가?"
rows["100:670811924"]="상급 도적을 만나고자 하신다면, 구 시가지로 가십시오. 스톰윈드 동쪽 가장자리에 있습니다."
rows["100:690371975"]="경비원 이루바는 전사 테라스의 가장자리에 서 있고, 상인의 나머지 층을 바라보고 있습니다."
rows["100:734596851"]="던 모로에 쌓인 눈이 모두 녹아 없어져 버렸으면 좋겠다오. 항상 내 로브 자락을 적실뿐더러 모든 걸 지저분하게 만든단 말이지!"
rows["100:830205535"]="갈반가르 부대장께서 전사하셨습니다! 쓰러진 갈반가르 님의 뜻을 받들어 얼라이언스를 공격하십시오!"
rows["100:920658922"]="얼음피 보초탑은 남동쪽으로부터 얼음피 주둔지를 방어합니다.$B$B현재 호드가 점령하고 있습니다."
rows["100:99409595"]="사냥의 전술과 전략에 대해 훈련받기 위해 온다면, 당신은 올바른 장소에 왔습니다!"
rows["101:1009493485"]="이봐, 저기 서쪽의 황무지에는 나쁜 녀석들이 득실린다네. 살고 싶으면 이 근처에 얼씬대지 않는 게 좋을 걸세!"
rows["101:1013968754"]="거기 자네, 이리 오게! 먹고, 마시고, 다음 전투를 위해 좀 쉬게나.$B$B하지만, 싸움은 금물일세! 그랬다가는 우리 늑대 먹이로 던져버릴 테니까 말이야."
rows["101:1124020822"]="오크 도시로 가 오그리마명예의 계곡에서 그를 찾아서 전설의 무기를 찾는 가게에서"
rows["101:11641053"]="도시의 최고의  ⁇ 匠들은 달라란 북서부 마구스 무역 거래소에서 있는 탈스마닉 텍스틸입니다."
rows["101:118311888"]="뛰어난 랩터 기수가 되는 법을 가르쳐 드리겠습니다. 그런데 수업료로 낼 골드는 충분하겠지요?!"
rows["101:1297907023"]="우체통은 부싯돌 선술집 옆에 있습니다. 아이언포지 성문에서 북쪽으로 조금만 가면 됩니다."
rows["101:1322815824"]="도시의 정문 바로 밖에 표지판이 있네. 그 표지판을 따라가면 서쪽 비행선 탑승장으로 갈 수 있을 거야."
rows["101:1388375113"]="최선을 다했지만, 나가가 균열을 공격했습니다!$b$b물의 세계를 지켜야 합니다!"
rows["101:1435271263"]="탁자에 있는 물약은 전부 내가 오늘 만든 것이지. 냄비를 쳐다보고 있으면 절대 끓지 않는다고 그러더군. 하하!"
rows["101:1501944408"]="아니, 여기서 초식학을 가르쳐줄 사람이 없는데 아이언포지 하지만"
rows["101:1610541186"]="어느 기술이나, 왕도가 되는 길은 길고도 험하지만 그만큼 큰 보람을 주지요. 어떤 전문가의 길을 걷고 싶으신가요?"
rows["101:1719617596"]="비전 마력을 잃으면 대지, 원소, 심지어는 죽음의 망령에까지 이상한 일이 벌어질 수 있답니다."
rows["101:1753044901"]="그로그주 통입니다. 해적이 죽고 못 산다는 그로그주가 들어 있습니다.$b$b병 입구는 코르크 마개로 살짝 막혀 있습니다."
rows["101:1788598470"]="무슨 연유인지는 모르겠지만 장로 썬더혼은 운고로 분화구의 갈래굽이 구렁으로 갔다네."
rows["101:1825885996"]="드레나이 용사가 우리와 함께하고 있도다. 이것은 하늘안개 섬과 핏빛안개 섬의 구원자를 축하하기 위한 것이니라!"
rows["101:1853395425"]="당신은 많은 것을 배웠소. 이제 내가 더 가르칠 수 있는 게 없군. 제임스 반 브런트에게 가 보시오. 내가 가르칠 수 없는 것을 알려 줄 테니까."
rows["101:1870321559"]="이 작은 녹색 녀석은 광산에서 쓸모가 없었다. 어쨌거나 이 녀석은 전투 전 준비 운동에 적절하게 사용할 수 있을 거다."
rows["101:1893922129"]="저기 저 의사를 상대할 일이 있거든 조심하시오. 뭔지는 몰라도 이상한 짓을 꾸미는 게 분명하오."
rows["101:1944058839"]="빛과 어두움 사이에는 그림자가 있지요... 그 그림자는 당신이 지금껏 보지 못한 힘을 가지고 있어요."
rows["101:1947208302"]="자네 관상을 보아하니 돈이 좀 되겠는데. 고뇌의 투기장에서 한판 해 보는 게 어때?"
rows["101:1987217660"]="<비전 수호병이 도시 중심부의 남동쪽 계단을 가리킵니다.>"
rows["101:2013240964"]="용암? 그런 것에는 신경 쓸 것 없습니다, 친구여... 주위 경관을 둘러보며 자연이 주는 기쁨을 있는 그대로 받아들이세요."
rows["101:2101691799"]="당신 때문에 매우 중요한 일이 방해 받고 있으니 당장 떠나 주십시오. 이런, 어디까지 했지? 다시 처음부터 해야 하는 건가?"
rows["101:211645864"]="이놈은 붉은 과부, 베스틸락의 새끼입니다. 베스틸락의 새끼들은 죽임을 당한 형제의 복수를 하려들 것입니다."
rows["101:249130935"]="전 주문 시전에 필요한 룬 및 여러 가지 재료와 연금술 재료를 세나리온 요새에 공급하고 있습니다."
rows["101:288357373"]="<당신이 다가가자 그론달이 허무하게 당신 쪽을 바라봅니다. 하지만 그의 팔은 생명의 기운이 빠져나가는 듯 털썩 떨어집니다.>"
rows["101:290088644"]="그래? 음식에 대해 불평하지 않았으면 좋겠어요.$B$B우리는 가진 작은 것들로 최선을 다하고 있습니다."
rows["101:294965204"]="밤새 걸리는 쿠난지, 당신이 찾고 있는 사람입니다.$B$B그는 델밸리의 중심 건물에서 북쪽에 있습니다."
rows["101:375856768"]="흑마법사에 대해 내게 묻다니, 간 하나는 크군. 마법 지구 외곽으로 가면 되네. 이제 내 눈앞에서 썩 물러가게."
rows["101:413470195"]="모험가들은 은빛 자치구나 선리버 성소에서 정의로운 업적을 보상받을 수 있습니다."
rows["101:435350971"]="이곳 오그릴라에서는 강철의 수수께끼를 심사숙고할 시간이 있답니다. 시간이 충분한 건 좋지만... 무엇을 도와드릴까요?"
rows["101:512242114"]="용맹전사의 자리를 위한 시험에 응할 준비가 되면, 은빛십자군 일원을 불러 드릴게요."
rows["101:627314749"]="세이크와가 당신의 동물 친구를 돌봐줄 수 있을 겁니다. 여관 앞에서 찾아보십시오."
rows["101:649002612"]="스톰윈드 회계사무소는 스톰윈드 상업 지구의 성문 옆에 있습니다. 돈을 세는 게 지겨워질 때는 꼭 황금 장미 여관에 들러 한잔 하시기 바랍니다."
rows["101:854056814"]="터널 반대편에서 고룡교단 신도들이 몰려들고 있다는 걸 알고 있습니다. 우리는 여기서 방어할 것입니다."
rows["101:862622291"]="안'셰의 빛은 우리 모두를 인도합니다. 어둠이 내려오면, 그녀의 힘으로 우리는 새로운 새벽을 만들 것입니다."
rows["101:883187371"]="색깔을 보니 이게 감독관이 분명합니다.$b$b조각상에는 당신의 졸이 딱 맞을 것 같은 홈이 있습니다."
rows["101:895785909"]="자연은 우리가 필요로 하는 모든 것을 제공합니다. 봉우리 중간층 조화의 약초상점에 있는 코민 윈터후프를 찾아가 보십시오."
rows["101:907895294"]="쇠사슬에 저렇게 매달리는 건 그다지 추천할 일은 아니오만, 솔직히 말하면 덕분에 머리는 꽤 멋있어졌다오."
rows["101:915090665"]="나는 비록 지금 실패했지만, 나의 주인님께서 이 도시에 복수의 비를 내리실 때 다시 날 자유롭게 하시리라."
rows["101:928255120"]="폭탄이랑 로켓 화약 냄새가 여기까지 나요! 출격해서 재미 좀 보시려고요?"
rows["101:988571619"]="우리가 가는 길은 신성하다. 토림을 저버리고 리치 왕과 같은 부류가 되느니 차라리 죽음을 선택하리라."
rows["102:104389091"]="폭풍은 그 용기를 가진 사람들에게 폭풍인도자라고 대답합니다."
rows["102:1120296989"]="볼더크랙의 뒤에는 단결한 토석인의 망치가 버티고 있소. 우리는 로켄의 부하들과 끝까지 싸울 것이오."
rows["102:1236131710"]="신전은 당신의 존재를 알아차리는 것 같습니다. 당신이 당신의 손을 그 표면에 올려서 그 힘에 맞춰서"
rows["102:1297901961"]="마법사 교역소는 달라란 북서쪽에 있습니다. 달라란의 기술 전문가들 대부분이 그곳에 있답니다."
rows["102:1319911772"]="무한의 깊은 곳으로부터 두려움이 끝없이 일고 있습니다. 저에게 보여주지 마십시오! 이미 견딜 수 없을 만큼 봤습니다!"
rows["102:1325415991"]="드디어 손자들에게 들려 줄 얘깃거리가 생겼군... 왕국의 배신자는 우리 가운데 있었소!"
rows["102:1382044091"]="샤일라 루네완더는 타라단 옆에 있는 공예인 테라스의 매혹적인 홀에서 그녀의 루나를 연구합니다."
rows["102:1384547335"]="명예의 골짜기로 들어서서 북서쪽으로 곧장 가보게. 사냥꾼의 전당을 찾을 수 있을 게야."
rows["102:1431409912"]="올  ⁇ 블스는 프랭클린 로이드 근처의 외곽 링에 있는 로그스 구의 엔지니어들과 놀고 있습니다."
rows["102:1481517119"]="야생은 인내심을 가진 눈을 보상하고, 순찰자사냥이 가르쳐준 걸 알려드리겠습니다"
rows["102:1604406742"]="헤... 폭탄? 우리 꽝 좋아해. 그레이엄 반 탈렌 보면 만들기 가르쳐 줘. 도적 지구 외곽에 있다."
rows["102:1618064863"]="할로윈 축제가 끝나면 이 호박들을 다 날려 버릴 겁니다. 제가 아는 한 최고로 멋진 날이 되겠지요!"
rows["102:1633580133"]="헬스크림 님의 명령은 이 왕좌에서 나오네. 그분의 말씀은 삶이자 죽음일세."
rows["102:1652809877"]="석궁이라면 아키발드가 전문이지. 그 무기 전문가는 언더시티의 군사 지구에서 찾을 수 있네."
rows["102:1695584414"]="<비전 수호병이 당신이 어떤 전투모병관인지 자세히 설명해 주길 기다리며 꼼짝 않고 서 있습니다.>"
rows["102:1768687171"]="당신은 아직 쌍둥이 봉우리에서 싸울 수 있을 만큼 강하지 못합니다. 좀 더 경험을 쌓은 후에 다시 오십시오."
rows["102:1779655551"]="상급 도적을 만나고자 하신다면, 구 시가지로 가십시오. 스톰윈드 북동쪽 가장자리에 있습니다."
rows["102:1781418102"]="아, 스톰윈드 회계사무소를 말씀하시나 보군요. 스톰윈드에 들어가면 성문에서 그리 멀지 않은 곳에 있습니다."
rows["102:1866787843"]="아이언스토크는 트로그스가 죽기 전까지 아무도 내보내지 않을거야"
rows["102:1915385694"]="아, 또 불의 힘과 모루를 이용해, 무기를 만들 자가 나타난 것이로군. 물론 가르쳐 드려야죠."
rows["102:1952210635"]="이곳에 비축된 물자를 이용해 사람들을 무장시키겠소.$B$B계속 전진하시오. 저 위에서 봅시다."
rows["102:2034171234"]="얼라이언스 연합에 들어온 신생 종족들은 겨울맞이 축제에서 소란을 피우곤 하지요. 아이언포지 은행은 이번 축제의 중심지랍니다."
rows["102:208497924"]="<이 병사는 나가의 의심을 풀고자 위장했던 것으로 보입니다. 그래서 살 수 있었던 것 같습니다.>"
rows["102:2140511173"]="마법부여라면 달라란 북서쪽, 마법사 교역소의 바로 외곽에 있는 마법부여 전문점에 가 보시기 바랍니다."
rows["102:2146679521"]="당신은 보랏빛 눈의 감시자에 대해 알고 있군요? 나중에 시간을 내보겠습니다.$B$B지금은 일을 해야 해서요."
rows["102:221307721"]="성스러운 빛이 주관하시는 작은 예배당에 오신 걸 환영합니다. 자리를 잡으시고 세상의 죄악으로부터의 휴식을 누리세요."
rows["102:395683442"]="한숨 돌리려고 회피를 쓰다가 그것이 인생에서 마지막으로 행복했던 15초가 될 수도 있다는 사실을 깨달아야 합니다."
rows["102:408831267"]="전 오직 단 한 번만 우리를 그곳으로 순간이동시킬 수 있습니다. 준비 단단히 하세요. 고엘이 바다 밑바닥에서 우리를 기다리고 있습니다..."
rows["102:420153990"]="우리 적은 이 도시 전체를 모래로 덮어버릴 수도 있다. 애석하게도 우리의 역사는 이런 전쟁을 대비할 수 있는 가르침을 주지 않았다."
rows["102:448368280"]="거기서 대체 뭐가 잡히는진 모르겠지만, 하여튼 마법 지구 부두에서 알만드 크롬웰이 낚시를 하고 있네."
rows["102:492527307"]="아직도 피가 흐르고 있나? 안 돼... 오래는 못 버틸 것 같아. 너 혹시 대마법사님 한 분이라도 봤어?"
rows["102:507488826"]="채광 도구는 가져왔길 바랍니다. 여기보다 고대의 보물을 파내기 좋은 곳은 없으니까요."
rows["102:572147719"]="이 괴물들... 너무 많아. 너무 많은 목숨을 잃었어! 불타는 아즈샤라를 봐라. 명가의 일원들은 대체 무슨 짓을 저지른 거지?"
rows["102:627428095"]="이 조각상은 오래된 것이 분명하지만 전혀 손상되지 않은 것 같습니다."
rows["102:637936369"]="프로스트울프 리lief Hut은 프로스트울프 킵에 위치하고 있으며, 프로스트울프 타워의 남쪽에 있습니다.$B$B호드는 통제하고 있습니다."
rows["102:656202979"]="<이 병사는 나가의 의심을 풀고자 위장했던 것으로 보입니다. 그래서 살 수 있었던 것 같습니다.>"
rows["102:685567338"]="때가 되면 가르쳐주겠어. 하지만 지금은 때가 안 됐어. 먼저 기초부터 다지고 와야겠군!"
rows["102:694550471"]="우리는 디멘시우스만큼이나 에테리움도 우리에겐 위험한 존재라고 생각하오. 둘 다 멈추어야 하지..."
rows["102:742132430"]="해냈군요! 대단합니다! 윈저 치안대장님께서 당신이 오시기를 고대하셨지요. 지금 그분께 연락을 취해 드릴까요?"
rows["102:799912238"]="허리에 칼이나  ⁇ 에 독이 없어도 여기서 탈출하는 것은 성취가 될 것입니다."
rows["102:903506452"]="미스터리는 약한 사람들을 망치게 합니다. 훈련에 계속하세요. 그렇지 않으면 비슷한 운명을 발견하실 수도 있습니다."
rows["102:952935135"]="골목길에 마가르의 의류점이 있네. 거대한 나무의 남쪽, 코도 가죽용품점 옆에서 찾을 수 있을 거야."
rows["103:1004234799"]="네? 대드루이드님께서는 쉬고 계십니다.$B$B분명히 그대를 만나면 기뻐하시겠지만, 지금은 그분을 방해하지 않는 편이 좋겠습니다."
rows["103:1009512346"]="바람의 돌로부터 맑은 목소리가 들려옵니다...$B$B신도 계급장은 어디에 있나? 네 녀석의 신분을 증명하지 못하면 군주님과 대화할 수 없다..."
rows["103:1069367617"]="텔드랏실의 창조는 위대한 업적이었지만, 이제 세계는 균형을 되찾기 위해 다시 움직여야 합니다."
rows["103:1069773756"]="오, 너와 나는 즐거운 시간을 보낼거야 사냥꾼들의 방법에 대해 가르쳐 줄 일이 너무 많아요"
rows["103:1074212276"]="연금술 지구 내곽으로 가보게. 거기 있는 마사 알리스타가 약초채집을 가르쳐 줄 걸세."
rows["103:1096543390"]="음, 그를 따라가야 할 것 같군.$b$b이대로 헬스크림 님을 뵙는 것보다야 낫겠지..."
rows["103:1132063302"]="복타르는 이 추락이 불운한 사건이라고 생각하지만, 저는 이 사건으로 우리가 무언가 배우게 될 거라고 믿습니다."
rows["103:1134841492"]="달라란 서쪽에 있는 운명의 실타래에는 달라란에서 가장 유명한 재봉용품 상인과 천 방어구 상인이 있습니다."
rows["103:11449824"]="변신능력을 잊는 것은 가볍게 할 수 있는 일이 아닙니다.$B$B- 확실해?"
rows["103:1193212458"]="이 그리핀은 덫에 걸렸습니다. 하지만 조금만 도와주면 쉽게 덫을 부수고 움직일 수 있을 듯합니다."
rows["103:1196395862"]="<남자는 당신에게 눈길도 한 번 주지 않습니다. 당신과 대화를 나눌 생각이 전혀 없어 보입니다.>"
rows["103:1417169973"]="이 배에 퍼부어진 공격은, 무차별로 이뤄진 것이 아니었습니다.$b$b나가가 여기 온 의도를 밝혀내야 합니다."
rows["103:1446056865"]="길드를 창설하시려고요? 문서 업무를 보셔야겠군요. 다르나서스에 있는 길드 사무관에게 가서 조언을 구하십시오."
rows["103:1669184094"]="아우로의 죽음으로 최후의 방으로 가는 길이 열렸습니다. 원하신다면 그곳으로 보내드릴 수 있습니다."
rows["103:1692196428"]="총기류는 안세크화가 전문이야. 그 타우렌 무기 전문가는 썬더 블러프 중앙의 하층 봉우리에 있지."
rows["103:1808244370"]="언데드 무리의 침략이 언제까지 계속될까요? 구울이나 해골 한 놈을 해치우면 꼭 두 놈이 나타나는 것 같습니다."
rows["103:1851255228"]="선장님이야 멋진 분이지요! 배가 도착하면 쉴 시간이 생깁니다. 제가 가장 고대하는 순간이지요."
rows["103:1923203345"]="지금 우서 경의 방문을 위해 준비하고 있는 게 안 보입니까? 비켜요. 할 일이 태산 같단 말이에요!"
rows["103:1938930037"]="황금골에 거주하는 대장장이라면 아르거스가 있지요. 그라면 분명 대장기술을 가르쳐 줄 수 있을 겁니다."
rows["103:2019991721"]="이봐요, 햇볕에 서 있지 말고 이리 들어오세요.$B$B마실 것이라도 드릴까요? 여기는 정말 아무것도 할 게 없어요."
rows["103:2041692405"]="갈수록... 힘에... 부쳐. 칼리사, 대마법사님들께 다른 계획이 없는 건 아니겠지..."
rows["103:2048322817"]="학생 복장을 갖추는 걸 잊으셨나요? 스컬지의 세계 정복보다 옷맵시가 더 중요하다고 생각하는 겁니까?"
rows["103:2141249576"]="재봉술을 아주 착실하게 배우고 있군. 그건 인정하겠소. 자, 그러면 진짜 솜씨가 어느 정도인지 알아볼까..."
rows["103:217828811"]="이제 가보게, 감독관! 우리 얘기는 끝났다.$B$B지체하지 말고 당장 루안 숲으로 가서 임무를 수행하도록!"
rows["103:26548130"]="지금은 편자를 고치는 중이라 좀 바쁩니다만... 나중에 다시 오시겠습니까?"
rows["103:28061845"]="와우, 넌 완전히 폭파했어 연습이 되겠군?"
rows["103:359622450"]="내게도 한계는 있단 말이야! 계속해서 훈련을 하고 싶다면 언더시티에 있는 라비니아 크로를 찾아가 보게나."
rows["103:508957281"]="우리처럼 제대로 된 전사 훈련을 받고 싶으신가요? 사냥꾼의 전당에 있는 사크 레이지토템을 만나면 도움을 받을 수 있을 겁니다."
rows["103:629368468"]="바로 올라와 모든 아제로스에서 가장 놀라운 공연을 듣게 되세요 - Darkmoon Faire!"
rows["103:698677674"]="이런 일들이 계속 일어나는데 어떻게 여관을 계속 깨끗하게 유지하겠어? 당신이 소인족 문제를 해결해주면 어떨까?"
rows["103:704927814"]="리치 왕이 이 세계에 모습을 드러내려 합니다. 절대로 이를 용납해서는 안 됩니다."
rows["103:733397983"]="우탄 스틸워터를 찾으시는군요. 마을 서쪽에 있는 황소바위 호수에서 낚시를 하고 있을 테니 찾아가 보십시오."
rows["103:861872140"]="오그리마 은행은 힘의 골짜기에 있네. 도시 정문에서 북쪽으로 가서 찾아보게."
rows["103:885805969"]="이 게시판은 진흙톱니 거점에 있는 스팀휘들 대표가 현상 수배를 하거나 직원 모집 공고를 낼 때 사용합니다."
rows["104:1085984659"]="저 비행기는 놈리건의 정신호라고 해요. 멋지지 않나요? 당신이 도와주지 않았다면 고치지 못했을 거예요."
rows["104:1105686604"]="그렇지 않다. 조금만 뜯어먹으려고 했다. 전부 먹지 않는다. 맞다, 그 작은 거라면 모두 먹었을지도 모른다.$B$B그들 정말 맛있다!"
rows["104:1105888598"]="이 유물은 새것처럼 깨끗한 상태이지만, 특별한 점은 없어 보입니다."
rows["104:1113585142"]="기어, 기제, 그리고 건강한 분파물 복용량 - 그게 기술공의 방법입니다. 몇 가지 트릭을 보여드리겠습니다."
rows["104:1155935310"]="비커와 연금술 도구를 사용하여 여러 가지 잠수함 연료를 실험할 수 있습니다."
rows["104:1159509380"]="우리는 해머, 우리는  ⁇ 을 가지고 있습니다.$b$b토큰이 있다면, 해마를 이용해  ⁇ 을 때릴 수 있어."
rows["104:1274420630"]="귀관은 말가니스의 스컬지 군대와 맞서 싸워 준 용감한 병사 중 하나겠군. 잘해줬네."
rows["104:1336149678"]="확실히 솜씨가 괜찮군요! 일을 끝냈으니 이제 수업을 시작합시다!"
rows["104:1338522835"]="칼리사! 서둘러. 대마법사 셀윈 님이 급한 일로 널 보자고 하셨어. 뭔가 좋은 방법이 있으신 거겠지?"
rows["104:1420384068"]="당신을 만나기 위해서라면 대해라도 건넜을 겁니다. 우리는 당신이 우리를 위해 한 일을 잊지 않을 겁니다."
rows["104:1431413149"]="하룻강아지 꼬마들은 왜 만날 루가 라푸 불쌍해하느냐고 물어봐? 라푸 말 많이 하지만 루 친군데."
rows["104:1498269253"]="그림 가즐러가 없었다면, 아마 내가 자유시간을 드래곤 새끼들에게 날개를 뽑아주었을 겁니다."
rows["104:1512825638"]="진정한 장인의 지도를 받아야겠군! 타렌 제분소에 있는 다릴 스택을 찾아가 자네의 운명을 맡기는 게 좋겠어!"
rows["104:1546615814"]="아서 무어라는 자가 가죽세공인일세. 도적 지구 내곽에서 수습생들을 가르치지."
rows["104:1576792550"]="바람의 돌로부터 아련한 속삭임이 들려옵니다...$B$B반갑구나. 기사단에 전할 소식이라도 있는 것이냐?"
rows["104:1643817110"]="매일 우리가 하는 일은 이 광산에서 막노동을 하는 것이 전부요. 블러드 엘프 남자는 이런 육체노동이 체질에 맞지 않는데 말이야."
rows["104:1777054804"]="<운명을 받아들이고 당신의 부탁을 이해했는지 숙연히 고개를 숙이는 보시>"
rows["104:1868240828"]="저는 이곳에 머무르며 대지가 치유되는 과정을 지켜보겠습니다. 남아 있는 생물체들을 조심하십시오."
rows["104:186907559"]="세상에나! 다시 누군가를 볼 수 있으리라곤 생각도 못했어요!$B$B여기서 절 구해주세요!"
rows["104:1932344848"]="이곳은 오염되었어요... 유물을 가지고 최대한 빨리 이곳을 벗어나야 해요."
rows["104:2005152785"]="서쪽 하수도에 있는 마법과 까마귀 선술집 바로 북쪽으로 아래에는 고블린이 운영하는 은행이 있습니다."
rows["104:2021336249"]="그대가 날 감옥에서 구해주지 않았다면, 난 지금쯤 굴복했을 것이다.$b$b나는 잊히지 않았어..."
rows["104:207001587"]="상업 지구 위층으로 가보게. 여관주인 노먼이 소위 \"여관\"이라는 먼지투성이 공간을 관리하더군."
rows["104:282121710"]="왜 나한테 얘기하는 거야? 너, 나만큼 돈이 없잖아?$B$B가서 비슷한 족속들과 어울리라고."
rows["104:319161809"]="난 심리철학자야. 머리로는 자네보다 한 수 위라는 뜻이지. 진단 받기 싫으면 얼른 움직여."
rows["104:429311626"]="호드에 대한 배신과 기타 반역 혐의로 여기 언급된 이들에게 현상금을 건다!$B$B보상은 고르트 경비대장님께서 내리실 것이다."
rows["104:453792128"]="겨울 할아버지는 겨울맞이 축제 기간 동안 아이언포지의 나무 아래에 모든 사람들을 위한 선물을 놓아두십니다!"
rows["104:463206241"]="그 사람이 병영에서 갑자기 비틀거리며 나타났어요.$b$b난 도와달라고 비명을 질렀지만, 경비병들은 쳐다보지도 않더군요!"
rows["104:464576911"]="내가 아주 때맞춰 등장했군!$b$b내 생각엔, 우리와 저 슈노츠라는 친구의 악연이 끝난 것 같지 않소."
rows["104:508598843"]="<바퀴벌레가 칼더의 입에서 스르르 기어나와 텅 빈 눈을 통해 그의 머릿속으로 재빠르게 사라집니다.>"
rows["104:556049984"]="내가 가르쳐 줄 내용은 당신 머리를 어지럽게 만들 겁니다! 충분히 배운 후에 다시 찾아오도록 하세요!"
rows["104:587168454"]="총기류 사용법이라면 안세크화가 가르치지. 썬더 블러프 중앙의 하층 봉우리로 가면 그 타우렌 무기 전문가를 만날 수 있어."
rows["104:650693481"]="우린 위대한 숲에 경이로움을 보내고, 대지모신이 주신 선물의 기적을 누리고자 여기에 왔소이다."
rows["104:676707518"]="카자로 산으로 멋지고 낭만적인 소풍을 가보는 건 어떨까요?$B$B좋아하는 과일 음료는 꼭 챙기시고요!"
rows["104:723281373"]="나즈자르와 그 부하들을 처치하고 싶은 마음은 굴뚝 같지만, 누군가는 당신의 뒤를 봐 줘야 하지 않겠습니까..."
rows["104:929637013"]="용감 한 사람 을 싸우는 것 은 단순 한 과제 일 이라고 생각 하는 것 은 현명 하지 않겠는가?"
rows["105:1031190791"]="저주받은 기사 본 적 있어요? 원장님이 그자가 나타나면 쳐다보지 말래요. 안 그러면 우리를 호박으로 만든대요!"
rows["105:1082443176"]="재봉사가 아니라면 제 도안에 별 관심도 없으시겠죠. 그렇지만, 구경은 마음대로 해도 좋아요!"
rows["105:1133576230"]="비켜, 이 비열한 놈아! 레빌가즈가 교수형은 면하게 해줬지만 아마도 난 그에 못지않은 끔찍한 벌을 받게 될 것 같단 말이야."
rows["105:1206612180"]="불타는 군단이 그렇게 무섭다면, 그냥 물을 확 끼얹으면 되는 거 아니에요? 그럼 그냥 군단이 되잖아요."
rows["105:1315838119"]="\"즐거움과 이익을 위해 요소를 통제하는 것\"$B$B그게 전부야, 맞지?"
rows["105:1328693143"]="< ⁇ 은 타우렌은 위상을 스캔하고 있는 거리에 있는, 성원 모트론과 같은 내면적인 모습입니다.>"
rows["105:137696379"]="정령은 변덕과 편파가 심합니다. 미안하지만 당신에게는 아무런 도움도 줄 수 없군요."
rows["105:1499893723"]="챔피언 을 싸운다는 것 은 단순 한 과제 일 이라고 생각 하는 것 은 현명 하지 않겠는가?"
rows["105:1511336801"]="연금술 실험실 내곽으로 가봐. 마사 알리스타가 꽃 꺾는 법 가르쳐 준다."
rows["105:1528943286"]="다른 일도 많지만, 난 지금 슈노츠 사령관의 전기에 중점을 두고 있소.$b$b미안하지만 실례해야겠소."
rows["105:1686423053"]="라우티키를 찾는군. 남쪽에 있는 센진 마을 바로 외곽에 있는 검은창 해안으로 가. 그곳에서 만날 수 있을 거야."
rows["105:1693377572"]="어둠해안이 텔드랏실의 해안보다 위험하기는 하지만 많은 낚시꾼들이 이곳에서 수익을 올리고 있습니다."
rows["105:1762421584"]="바라루스 기술공미트린디르의 물품 가게 앞의 공예인 테라스에서 일하고 있습니다."
rows["105:1923959200"]="그걸 여관이라고 할 수 있는진 모르겠지만... 어쨌든 상업 지구 위층으로 가보게. 침대도 하나 없는 곳이지."
rows["105:1949183013"]="도적 지구 외곽으로 가면 기술자를 만날 수 있네. 목숨이 아깝지 않거든 맘대로 하게."
rows["105:1990051197"]="스모키우드 파스더스는 오그리마 그리고 아이언포지올해 무슨 꿈을 꾸게 될지 궁금해요"
rows["105:2058614909"]="네메시스와 맞설 준비가 되었습니까? 토템도 준비되었길 바랍니다.$b$b놈을 소환하고자 할 때 제게 알려 주십시오."
rows["105:2077806940"]="암흑방랑자 주루가 도와줄 수 있습니다.$B$B남동쪽에 있는 높은 건물 아래층으로 가보십시오."
rows["105:2082584826"]="전문 요리사는 얼라이언스와 호드 지구에 있는 여관 부엌에서 만나실 수 있습니다."
rows["105:251632473"]="썬더브루 가문에서는 카라노스에 썩 괜찮은 양조장 겸 여관을 하나 운영하고 있습니다. 이름도 자기들 성을 따서 지었더군요. 그곳에 잠시 들러서 맥주도 한잔 하시고 좀 쉬었다 가십시오."
rows["105:267009651"]="나루의 보좌에는 두 개의 우체통이 있는데, 하나는 은행 근처에, 다른 하나는 경매장 밖에 있습니다."
rows["105:343755199"]="어느 기술이나 꼭 배워야 하는 기본기가 있게 마련이죠. 트리안나가 근처에 있을 테니 가서 얘기를 나눠보고 나중에 다시 찾아오도록 하세요."
rows["105:395196948"]="당신 같은 사람을 요새 뭐라고 부르지요? 떡대? 밥통고블린?$B$B짜증나서 두고 볼 수가 없네요. 당장 꺼져요."
rows["105:545567896"]="놈들이 모단 호수에 진흙덩이만 남을 때까지 물을 빼 가든 말든, 우리는 이곳을 지키기 위해 계속 싸울 것이네."
rows["105:624358240"]="주문각인이 되고 싶다고? 이런 외딴곳에는 숙련자가 없어. 가까운 대도시로 가는 게 좋겠군."
rows["105:659046112"]="네 명의 남자가 네 사람의 관심을 놓고 경쟁하는 것이 정말 귀엽다.\010\010감사하고, 힘이 있는 기분이야"
rows["105:794631709"]="당신이 여기저기 주변을 돌아다니는 걸 봤습니다. 혹시 할 일이 없어서 그러는 거라면 무기고에 장비나 갖다놓으실래요?"
rows["105:829405769"]="으스러진 손은 영광스러웠던 호드의 시대를 열 것이다."
rows["105:848993566"]="사령관님, 명령만 내리시면 즉시 출발하겠습니다! 서리늑대 요새까지 이르는 경로를 정찰하겠습니다."
rows["105:89249856"]="마법부여는 우리 가문 대대로 내려온 일이오. 내 아들 녀석처럼 나도 어렸을 때부터 배웠소이다."
rows["105:94684262"]="여기 있는 불리위프보다 도끼에 대해 아는 훌륭한 전문가는 없습니다! 한손은 물론이고 양손 도끼 모두에 대해서 그는 달인이랍니다!"
rows["105:996976764"]="나쁘지 않아. 나쁘지는 않은데... 뭔가 부족해! 전갈 독이라도 좀 섞어 볼까요? 그래, 그거야! 그거면 딱 맞겠어!"
rows["105:997872702"]="안녕! 나 새로 왔어! 날개 달린 크고 하얗고 빛나는 존재가 날 살려줬지! 이제 난 밴시 여왕을 섬겨! 만세!$B$B도와줘!$B$B안녕!"
rows["106:1004795502"]="다음 수업을 받을 준비가 됐나? 좋아, 그렇다면 먼저 긴장을 풀게. 물약을 올바르게 저으려면 긴장하면 안 돼."
rows["106:1054731346"]="선리버 놈들을 믿지 마십시오. 은빛십자군 앞에서 우리를 깎아내리고 싶어 혈안이 된 놈들입니다."
rows["106:1125730554"]="화약을 운반하는 일은 정말 위험한 일이야!$B$B미란은 방금 물건을 전달하러 갔으니 몇 분 후에 돌아올 걸세."
rows["106:1240197326"]="로레나는 스톰윈드의 대사입니다."
rows["106:1315406599"]="클리데 켈렌이라는 농어 전문가가 있지. 그가 제일 좋아하는 낚시터는 브릴 바로 동쪽에 있는 청명 호수니까, 한번 가서 찾아보게."
rows["106:132225947"]="전쟁노래 협곡이라고 말씀이십니까? 전투의 전당에 있는 아름다운 리란드리스와 대화해 보십시오."
rows["106:1376827893"]="이 오크들과 나는 함께 수많은 전투를 치렀지.$b$b여기 들어오는 나가는 후회할 걸세."
rows["106:1429473527"]="이곳에서 기술 한두 가지를 가르치는 이들을 조금 알고 있지요. 그런데 어떤 기술을 배우려고 하십니까?"
rows["106:1429545704"]="푸른용군단이 지키고 있는 홀 파편을 찾고 있나?$B$B<희미한 미소를 짓는 아주어고스>"
rows["106:1513172620"]="스톰윈드는 디프런 트램에서 스톰윈드  ⁇ 까지 많은 관심 지점을 가지고 있습니다.$B$B뭐라 생각했지?"
rows["106:1574352749"]="야수 관리인은 알도르 마루의 드레나이 여관과 점술가 언덕의 블러드 엘프 여관 바로 밖에 있습니다."
rows["106:1576864674"]="정령들이 분노에 차 울부짖고 있네. 나가들이 여기 온 것도 우연의 일치는 아닐세. 무언가를 기다리고 있어."
rows["106:159819303"]="당신이 남쪽에서 피어 오른 사악한 기운을 처리했으나 여전히 그 곳에서 위험이 느껴지는구려."
rows["106:17746520"]="그럴지도. 이제 가보게, 젊은이. 대족장님의 조언을 듣게. 대족장님께서 자네가 발견한 것에 대해 알고 싶어하실 걸세."
rows["106:178481995"]="마이클 크로우, 항구에서, 물고기를 잡는 것과 배기하는 것에 대해 알아야 할 모든 것을 가르쳐 줄 수 있습니다."
rows["106:1824005615"]="여기서 뭐 하는 건가요?$B$B아서스는 지금 스트라솔름 입구에 있다고요. 그와 함께 있어야 해요! 가세요!"
rows["106:1871224147"]="내가 생각해도 정말 기발한 발상이었지... 절대 그 물고기를 찾지 못할 것이다. 하지만 발견될 경우를 대비해 그 작은 물고기에게 약간 특별한 능력을 주었느니라."
rows["106:189696356"]="안녕하십니까? 아웃랜드 구경은 실컷 하셨는지요? 이제 알터랙 계곡으로 돌아가서 호드를 박살낼 준비가 되셨는지요?"
rows["106:1951446531"]="기꺼이 가르쳐 드리죠! 기계공학에 대해서 좀 알고 있는 게 언니 뿐만은 아니라는 걸 보여 주고 말겠어요."
rows["106:1953399747"]="시간이 지나면, 이곳을 재건하여 과거의 영광을 되찾을 걸세. 거슬리는 인간들은 모조리 쓸어버리고 말이야."
rows["106:1966967524"]="마법사, 저주, 그리고 그들을 던지는 불행자 - 마녀사냥꾼 모든 것에 대답."
rows["106:201227020"]="대단한 도전은 아닙니다만, 당신을 받아들이기 전에 구덩이에서의 일을 처리할 수 있는지 알아야겠습니다."
rows["106:2019454125"]="국가를 위해 죽는 일은 군인의 의뭅니다. 하지만 이 전쟁을 어리석다고 말하는 게 반역이라면, 저도 반역자겠군요."
rows["106:2023723788"]="불꽃놀이 후엔, 탁자에 술잔이 가득할 거라 들었습니다. 축배를 들 수 있는 멋진 술잔이지요!"
rows["106:2043503588"]="드루이드의 도움이 필요하신가요? 그렇다면 돌라나르 여관 바로 남쪽에 있는 달샘에서 칼을 찾아보십시오."
rows["106:297264316"]="테라모어가 뛰어난 전사 훈련으로 명성을 떨치고 있긴 하지만, 안타깝게도 당신을 도와드릴 수는 없소."
rows["106:354268853"]="<비전 수호병이 도시 중심부의 북동쪽 계단을 가리킵니다.>"
rows["106:414721481"]="나는 그들이 내 학비를 대 주겠다고 했기 때문에 참여하게 되었습니다. 삼촌 말로는 내가 다음 학기에 들어갈 수 있다는군요!"
rows["106:430258056"]="재봉술이라고? 북쪽에 있는 오그리마로 가면 배울 수 있을지도 모르지. 그곳 그런트에게 물어보게."
rows["106:438197844"]="댐윅이 그걸 타고 건너가는 걸 봤지. 나 같으면 저속 낙하 마법을 썼을 거야, 아직 하는 법은 모르지만."
rows["106:554225487"]="소타르라는 상급 사냥꾼이 있긴 하지. 칼바위 언덕 남서쪽에 있는 지하실 안에서 찾아보게."
rows["106:56536481"]="마법 지구 외곽에 계단이 많은 커다란 건물이 있지. 거기가 마법사들이 숨은 곳일세."
rows["106:624345420"]="바람의 돌로부터 아련한 속삭임이 들려옵니다...$B$B반갑구나. 기사단에 전할 소식이라도 있는 것이냐?"
rows["106:629489149"]="< 시장은 큰 홀 건너편의 타릴라 코나셔를 만나면 미소를 지울 수 없습니다.>"
rows["106:665028764"]="발키르 자매는 참으로 호흡이 잘 맞는군요. 저 둘을 잡는 게 왜 그렇게 어려웠는지 이제 알겠습니다."
rows["106:687799955"]="여어, 낚시꾼 친구로군. 혹시 훈련이 필요한 게 아니오? 내게 기술을 좀 배워보는 게 어떻겠소?"
rows["106:720698792"]="제 비법을 전수해 주기 전에 먼저 당신이 배울 자격이 있다는 걸 보여 주셔야 해요! 아주 적당한 시험이 하나 있죠..."
rows["106:778003684"]="사악한 마력에 의해 알토르의 시체가 공중에 떠 있습니다. 악마들은 심지어 그의 시체에서도 에너지를 뽑아내고 있습니다..."
rows["106:77810599"]="북부 던 발다르 참호는 던 발다르로 진입하는 동쪽 입구를 방어합니다.$B$B현재 얼라이언스가 점령하고 있습니다."
rows["106:847886475"]="바로 이게... 죽는... 느낌이로군요?\010<마브라린의 숨이 멈추더니 질문이 차츰 잦아듭니다.>"
rows["106:90822116"]="이야! 여긴 사방이 반짝이는 것들로 가득합니다!$b$b발굴 작업 중에 제가 뭘 발견했는지 보십시오...$b$b바로 수중 호흡 모자입니다!\010"
rows["106:926321082"]="흐쏜, 어둠의 기둥이 보이지 않는 곳까지 뻗어 가고 있습니다. 흐쏜 마르울 쿠알라. 무한한 밤의 손길이여."
rows["106:947019218"]="<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B나는 배고프다... 고로 나는 존재한다."
rows["106:974569417"]="음... 당신이라면 이전 왕하고 달리 기분 나쁜 명가의 왕자에게서 귀중한 고르독 유물 되찾을 수 있을지도 모르겠군!"
rows["106:979510032"]="그래, 그래, 어서 가서 겨울의 대부에게 겨울의 베일을 위해 원하는 것을 말해줘$B$B빨리 가자"
rows["107:1133736373"]="돌난로 참호는 투쟁의 벌판 동쪽 측면을 방어합니다.$B$B현재는 얼라이언스가 점령하고 있습니다."
rows["107:1149774508"]="이 분노! 이 힘! 평생 내가 이렇게 강하게 느껴지는 건 처음이다.$B$B곧 모든 용아귀 부족이 우리와 같은 것을 느낄 테지."
rows["107:1303378533"]="사냥꾼을 찾는다고요? 교역 지구 2층의 사냥꾼의 성소에서 그들을 찾을 수 있을 겁니다."
rows["107:1314380405"]="북쪽에 있는 보그먼 부인으로부터 모든 레시피를 받았어요"
rows["107:1390993430"]="일은 고된데 보수는 시원치가 않네요. 하지만, 폐허가 된 이 마을은 아킨둔 안으로 잠행하는 자들을 확실히 막아내지요."
rows["107:1392376529"]="여기 역병숲 깊은 곳까지 찾아오는 사람은 별로 없소. 그나마도 대부분은 누더기골렘이지.$b$b내게 부탁할 게 있소?"
rows["107:1460733098"]="전쟁노래 협곡 나이트 엘프들 이빨 갈고 있다. 놈들 완전 씹어줘! 왕실... 쿠르덴 블러드클로한테 가 봐."
rows["107:1664100381"]="저희 에테르 기술자와 호위대가 바시르 영지로 출발하고 있습니다. 그들이 임무를 마칠 수 있게 도와주시기 바랍니다!"
rows["107:1735692533"]="<늙은 얼음지느러미가 모래 위에 그림을 그립니다. 대충 그린 그림이지만 당신이 도와주기를 바란다는 것을 알 수 있습니다.>"
rows["107:1742796656"]="카라즈 다크는 대 동부에서 북쪽으로 조금 떨어진 거리에 있습니다."
rows["107:1894291459"]="당신이 은빛 성기사단처럼 성스러운 빛을 추종하는 건 아니지만, 언제든 저희에게 도움을 청하셔도 좋습니다."
rows["107:1967067881"]="병사에게 비침이 발병해서 침대에 눕혀서 아무것도 말하지 않더라도 그의 눈에는 감사가 나타난다."
rows["107:1976192583"]="칼바위 언덕에 병영 말고 또 다른 커다란 건물이 있네. 그게 바로 여관이지. 그 안으로 들어가 여관주인 그로스크에게 말을 건네보게. 알겠나?"
rows["107:200378443"]="도시를 확보했다. 아즈쉬르들이 네 이름을 승리의 구호로 외치고 있다. 오늘 너는 많은 존경을 받았노라."
rows["107:245478525"]="나는 라스타칸 님의 오른팔이신 무감바 님께서 보내신 파괴자 진로크다!$B$B난 전사와 이교도들을 담당하고 있지."
rows["107:266185711"]="해가 바뀌고 달빛이 환하게 비추는 시간이 왔도다.$B$B고대인이 깨어나면... 우리의 시간이다."
rows["107:337929548"]="비에로 블리츠코그는 그의 루나를 탐구자들의 홀에서 연구하고 있습니다."
rows["107:374680091"]="마을을 집어삼킨 정령들이 벌인 살육의 희생자인 파수꾼의 몸이 여기에 쉬고 있습니다."
rows["107:391580405"]="샤트라스에 있는 자들이 어서 빨리 싸움을 끝냈으면 좋겠네요. 점점 신경이 쓰여서 말이죠.$B$B무엇을 도와 드릴까요?"
rows["107:444798410"]="갈리델이 매날개 광장에서 비전 마법을 가르치고 있소. 여관 2층으로 가면 그녀를 찾을 수 있습니다."
rows["107:562508339"]="어떤 희생을 감수하더라도 스컬지를 막아야 합니다. 놈들이 이곳에서 조직 중인 군대가 공격하도록 놔두어서는 안 됩니다."
rows["107:589242359"]="내 형제인 시니푸스가 잔뜩 가지고 있어요. 북쪽의 푸른 하늘 벌목장에 가서 말해보세요."
rows["107:627555177"]="칩의 뻔뻔한 얼굴에 주먹을 한 방 날려주고 싶어! 캔디의 달콤한 입술에는 뽀뽀를 한 방 날려주고 싶고!"
rows["107:676901025"]="밴스 언더글룸을 찾는군. 브릴 남동쪽에 있는 교수대끝 선술집 위층 방으로 가보게."
rows["107:729539146"]="사냥꾼을 찾는다고요? 교역 지구 2층의 사냥꾼의 성소에서 그들을 찾을 수 있을 겁니다."
rows["107:800277186"]="아직 길니아스 전투에 참전할 만큼 강하지 않습니다. 더욱 많은 경험을 쌓아 다시 돌아오십시오."
rows["107:807610970"]="<비전 수호병이 고난의 거리에서 북서쪽에 있는 지역을 가리킵니다. 바로 샤트라스의 아라코아가 거주하는 곳입니다.>"
rows["107:892662011"]="마법 재료가 필요하신 거라면, 정확히 찾아오셨습니다. 샤트라스 어디에서도 더 좋은 상점은 찾기 어려우실 테니까요."
rows["107:953322678"]="내 태엽 점성장치에 의하면 지난 시합 때보다 20초는 더 빨리 고블린을 이길 수 있을 것 같소!"
rows["107:996796405"]="알레리아 성채가 사방으로 적에게 포위되었으니 우리가 적들을 공격해야 합니다."
rows["1083:1381082218"]="기억이 내 기억을 유지해줬지만 기억은 예전과는 달라졌어$b$b저는 여러분께 지구 어머니에 대해 이야기 할 수 있습니다. 그 눈은 태양과 달입니다. 그 눈은 모든 생명체의 열정을 나타냅니다.$b$b전 전세인들에 대해 말씀드릴 수 있었습니다. 지구 어머니보다 앞서 세상을 돌아다니며, 그 어머니께서 그 육신 아래 묻어놓은 사람들을요. 그 그림자는 깊은 곳에서  ⁇ 어 올라왔고,$b$b그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토메는 그림토는 그림토메는 그림토는 그림토메는 그림토는 그림토메는 그림토는 그림토는 그림토는 그림토는 그림토는 그림토는 그림토는 그림에 그림에 달고$b$b우리는 그 대신, 눈 ⁇ 을  ⁇ 지 않고, 편안함 없이 세상과 함께 걷기를 선택합니다."
rows["108:1010931655"]="진타알로는 우리 것이 될 걸세, 친구. 썩은가지 부족은 쇠약하고 고약한 배신자들이야. 로아의 가호를 받을 자격이 없는 것들이지."
rows["108:1020224443"]="여기 계시면 안전할 것입니다. 듀로 마나괴철로가 공격을 받은 이후 우리는 이곳의 보안을 강화했습니다."
rows["108:1025856450"]="나는 절대 담쟁이 마을을 고향이라 부르지 않겠다. 그런 짓은 우리의 정당한 땅을 되찾으리라는 희망을 포기하는 거나 마찬가지니."
rows["108:1127868893"]="더 높은 지식을 구하고 있군. 테파가 그런 지식을 가지고 있소. 이 근처 어딘가에 서있을 텐데..."
rows["108:1142712204"]="이 순간이동기는 최근 다양한 물품을 광산 안으로 운반하는 데 사용된 듯합니다."
rows["108:1160469003"]="<이 호랑이는 무장을 하고 안장을 얹은 것으로 봐서 전투용입니다. 이렇게 설명하지 않아도 우스꽝스러운 품새로 봐서 충분히 아실 수 있겠죠?>"
rows["108:1213815481"]="마우아리는 자네가 왜 나를 찾아왔는지 알고 있네...$B$B내게 에코를 갖고 오면 자네를 위해 부적으로 만들어 주지."
rows["108:122736261"]="우리 근방에 새로운 적들이 출현한 이 상황을 우리의 오랜 적들이 이용하는 일은 없도록 해야 해요!"
rows["108:1258820548"]="비정상적으로 크게 성장한 벌레라고 해도 저를 장가르 습지대에서 쫓아낼 수는 없어요! 탐험가 연맹이 어떤 조직인지 녀석들에게 제대로 보여주겠어요..."
rows["108:1285425446"]="슬프네요, 해로우의 끝이에요, 병이 나네요. 나 나가서 못 뛸 수 있어 트릭 오브 캔을 놓칠 거예요!"
rows["108:1328760662"]="부족에서 가장 용감하고 명예로운 자만이 붉은 바위 언덕에 잠드는 영예를 누릴 수 있네."
rows["108:1421904960"]="원정순찰대 산장에 오신 것을 환영합니다. 우리 순찰자들은 인근 지역은 물론 아주 먼 지역까지 우리 백성을 보호하기로 맹세했습니다."
rows["108:1455650358"]="불타는 밀짚인형의 재는 마력을 뿜어냅니다. 이미 당신의 얼굴에는 재가 발라져 있습니다."
rows["108:151979795"]="더 배우기를 원한다면 누가 그대를 도와줄지 기꺼이 알려드리겠소. 그래, 어떤 무기가 그대의 관심을 끌었소?"
rows["108:15319636"]="길드를 창설하려면 실버문 안에서 알아보는 게 좋을 거요."
rows["108:1567092552"]="도시의 그 많은 사람 중 여기 있는 몇 명만이 정령들의 경고를 귀담아 듣다니 정말 놀랍군요."
rows["108:1630574351"]="여기서 좋은 이들을 벌써 몇 명이나 잃었네. 이곳이 그럴 가치가 있는지 의심이 들기 시작하는군."
rows["108:1671708597"]="이렇게 빨리 도시를 탈환할 줄은 몰랐다. 공격을 준비할 시간은 충분할 것 같구나."
rows["108:169562206"]="우리 아버지는 항상 덩치가 큰 녀석들은 힘이 좋지만 움직임이 둔하다고 말씀하셨소...$b$b아마 이 녀석은 만나보지 못한 게 분명하오!"
rows["108:1701765040"]="오래된 잿더미 속에서 피어나는 새로운 삶... 이것이 바로 아에시나 님의 선물이네.$B$B그대가 없었으면 이 기적은 일어나지 않았을 걸세."
rows["108:1745136026"]="감독관이라고요?$B$B당신이 감독관이라면 난 스톰윈드의 왕이겠군. 아, 그렇군... 당신이 저들이 말하는 자였군요."
rows["108:1785461633"]="그롬골이 안전할 거란 내 생각이 틀렸을지도 모르겠군.$b$b트롤이라면 어딜 가든 몸조심해야 해."
rows["108:186694316"]="클래스 능력은 자동으로 진행됩니다. 여기 빠진 매력을 복구하고, 캐릭터 진전에서 재능을 선택합니다."
rows["108:208642517"]="죽은 자는 이 세계에 속할 수 없습니다.$B$B그런데 왜 우리는 그들을 안식에 들게 한 뒤에도 계속 찾아 헤매는 것일까요?"
rows["108:250561334"]="파리는 보석세공에 관심이 있는 자들에게 보석세공의 정교함을 알려준답니다. 저기 동굴 근처의 수정 전당에 가면 그를 만날 수 있을 겁니다."
rows["108:265538402"]="기술자 드라론은 에크소다르의 큰 힘 결정에서 작업하고 있습니다."
rows["108:294326931"]="용 학살자 그룰과 그의 일곱 아들을 빼놓고 내가 가장 혐오하는 것이 바로 방해받는 것이다!"
rows["108:30298453"]="저는 이 축제는 동맹국들이 만든 것이 아니라 호드왜 우리가 그 뒤를 따를지 모르겠어요"
rows["108:329812674"]="일전에 수집한 늑대 가죽 무더기가 보입니다. 이 가죽 무더기는 복장 대부분을 구성하는 재료로 쓰일 겁니다."
rows["108:386299400"]="매트렌길 베어워커는 다르나서스 북부 부분의 센라리온 앙클라브에서 원자주의자들을 안내한다."
rows["108:428676863"]="사냥을 나갈 때는 사냥감을 찾아 나서기 전에 사냥감에 대해 누군가에게 물어보는 것이 좋다네."
rows["108:43417671"]="연금술 실험실에 학자 허버트 핼시 있다. 우리 태어난 곳이다. 당신도 우리처럼 잘 꿰매줄 거야."
rows["108:525832318"]="크룸이란 타우렌을 찾아가 보시는 게 좋겠습니다. 썬더 블러프 봉우리 하층 길드사무소에 가면 그를 찾을 수 있을 겁니다."
rows["108:64205690"]="유해를 대충 조사해보니 살갗이 불에 타서 떨어져 나간 것 같습니다. 아주 소름끼치는 광경입니다."
rows["108:738011818"]="아, 그럼 베니크 볼트쉬어를 찾아가셔야겠군요. 베니크는 드워프 지구 중심부에 대장장이들과 함께 있습니다."
rows["108:9287926"]="이제 나를 능가했으니 서로 기술을 시험토록 하라! 대전을 시작하려면 양 진영의 왕을 제어하면 된다."
rows["108:968508258"]="<다음과 같이 손으로 쓴 글씨가 적혀 있습니다.>$B$B          비밀 실험실 보관소$B     X. 니즐벡스 - 실험실장$B$B$B도움이 필요하면 초인종을 누르시오."
rows["109:102325036"]="공기 좋고 경치 좋은 산들바람 마을에 오신 걸 환영합니다. 실버문에서는 우리를 포기하다시피 했지만 우리는 이곳을 떠나지 않을 거예요. 우리 고향이니까요."
rows["109:1036724514"]="우리 나무구렁 일족은 당신이 요새를 무사히 지나갈 수 있도록 허락해 줄 수 있지만, 먼저 당신이 우리의 도움을 받을 자격이 있다는 것을 증명해 보여야 하오."
rows["109:1040169117"]="필요한 게 있으신가요? 물건이 아주 많지는 않지만 손님께서 생각하시는 만큼은 있답니다... 신중하게 생각하고 선별한 물건들이니까요."
rows["109:1101049111"]="낚시는 전장에서 살아남은 이들이 늘그막에 즐기는 최고의 취미지! 명예의 골짜기에 있는 호수에서 루막을 찾아보게."
rows["109:1156823506"]="비록 짧은 순간이지만 덕분에 내 땅에서 다시 녹색을 볼 수 있었구나. 그걸로 충분하다. 나는 평화를 찾았다. 이제 오랜 잠을 잘 준비가 됐어."
rows["109:1183554000"]="난 이 무덤에서 수많은 위험을 보았습니다. 어떤 생물이 경솔한 자들을 습격하려고 자욱한 먼지 속에 아직도 숨어있을지 누가 알겠습니까?"
rows["109:1213163506"]="블러드후프 마을 동쪽에 있는 큰 천막으로 가보십시오. 그곳에서 당신을 기다리고 있는 나름 스카이체이서를 만날 수 있을 겁니다."
rows["109:1269827934"]="상급기사 피레아노르는 지혜의 골짜기에 있는 스랄의 그롬마쉬 요새에 있네."
rows["109:1307034703"]="뛰어난 해골마 기수가 되는 법을 가르쳐 주지. 그런데 자네... 수업료는 충분한가?!"
rows["109:1343961132"]="장로 모닝듀는 버섯구름 봉우리의 피즐과 포직의 쾌속선로 경기를 보러 갔네."
rows["109:139553890"]="진흙톱니 거점에 있는 고블린들이 브록 여기 머물게 해줘서 기쁘지만 말이야. 가끔 브록 비웃는 소리가 들린다고 생각한다."
rows["109:142943405"]="울두아르 안에 숨겨진 그 모든 지혜와 지식을 생각해 보십시오. 생명의 비밀이 바로 그 안에 있습니다!"
rows["109:1443686080"]="자네가 찾는 자들은 연금술 실험실에 있네. 학자 허버트 핼시, 학자 마쉬라고 하지. 그들을 만날 땐 뒤를 조심하게."
rows["109:1490285233"]="은행은 다르나서스의 조용한 도시에서 위치하고 있습니다."
rows["109:1571144505"]="달라란 하수도 아래로 가는 방법엔 최소 3가지가 있답니다. 바로 동쪽, 서쪽, 북쪽에 있는 우물을 통해 하수도로 가는 방법이랍니다."
rows["109:1586064787"]="이세라 님께서는 야생의 정령 아에시나와 접촉하도록 나를 이곳에 보내셨지.$B$B그렇지만 아에시나 님께서는 아직 답이 없으시네."
rows["109:1634096356"]="나는 라스타칸께서 보내신 천리안 알타빔이네.$B$B사제, 마법사, 그리고 흑마법사를 담당하고 있지."
rows["109:1744793087"]="아크니엄의 주인들을 찾고 있소?"
rows["109:1798467162"]="깊은무쇠 광산은 얼라이언스 영토에 있으며 스톰파이크 무덤의 북쪽에 있습니다.$B$B현재 트로그들이 점령하고 있습니다."
rows["109:1799458389"]="와이번 등에 타면 왜 와이번이 강인함과 빠른 속도로 유명한지 알게 될 것이오."
rows["109:1834562288"]="불모의 땅에는 작열하는 태양과 적대적인 생물들이 있어 자네의 강인함과 불굴의 의지를 시험하기에 최적의 장소라네."
rows["109:188845347"]="용아귀 부족이 자유를 찾는 걸 도와주러 온 거요?$B$B잴라와 이야기하시오. 그녀가 저항군을 지휘하고 있소!"
rows["109:1904161877"]="해골더미에서 악한 기운이 풍겨 나옵니다. 아라코아들이 아주 최근까지 해골들을 가져다 놓은 것 같아 두렵습니다."
rows["109:191069238"]="명예의 골짜기에 있는 용사의 전당에서 그레즈 레이지피스트를 찾아 얘기해 보게. 혹시 나에 대해 묻거든 열심히 보초를 서고 있더라고 전하고!"
rows["109:1919999796"]="누군가 이 비커와 연금술 도구를 사용하여 다양한 잠수함 연료를 실험하고 있습니다."
rows["109:2022516440"]="피즈크랭크는 사사건건 간섭이고 장비도 제대로 없는데, 나인들 어떻게 일을 제대로 하겠어요?"
rows["109:2040167402"]="시간의 흐름을 바꾸는 일은 매우 까다롭고 섬세한 작업이지만 오늘 그대는 훌륭하게 해내셨습니다."
rows["109:2130978634"]="신형 병아리저울 6000의 제조가 곧 끝날 거라고 하더군요. 너무 흥분돼서 참을 수가 없어요!"
rows["109:2143257275"]="그녀는 쓰레기 속에 매달려 있고 난 증기압이 떨어졌어$B$B이 문제에서 우리를 풀어줄 수 있어?"
rows["109:296133199"]="이곳에서 일을 할 작정을 했다면 그만큼 자네 자신의 능력에 대해 자신감이 있어야 하네. 저기 그림자추적자는 하는 일이 거의 없거든."
rows["109:297981412"]="너무 안타까운 일입니다!$b$b어서 여길 정리하는 게 어떨까요?$b$b자꾸 쓸데없이 안 좋은 일을 생각나게 하니까요..."
rows["109:341424194"]="대족장님께서 지옥불 성채를 공격하라고 지시하셨네. 우린 외부로 노출된 이곳 성루에서부터 공격을 시작할 계획이야."
rows["109:4266722"]="살아 있다는 게 감사히 느껴지는 멋진 날이로군요! 친구여, 주위에 펼쳐진 아름다운 광경을 한번 보세요. 삶이 우리에게 준 선물을 즐기자고요!"
rows["109:473082215"]="석궁이라면 역시 아키발드가 전문이지. 그 무기 전문가는 언더시티의 군사 지구로 가면 찾을 수 있어."
rows["109:492498967"]="원하는 게 뭔가? 왜 나를 분노의 마타우스라고 부르는지 두 눈으로 확인하고 싶지 않으면 어서 사라져!"
rows["109:503750407"]="연금술이라면 물약 제조 기술을 잘 알고 있는 대달이 적격이지요. 그는 하늘 감시초소의 서쪽에 있는 파티마 옆에서 일하고 있습니다."
rows["109:600663765"]="대도시의 마법부여사를 방문하면 명가의 대마법사가 있습니다. 그곳에서 자신의 방어구나 무기를 재연마할 수 있습니다."
rows["109:61700217"]="베스프리스투스를 찾으시는군요. 그는 보통 텔드랏실 숲 속과 이곳을 오가며 히포그리프들을 보살피지요."
rows["109:647522072"]="내 아들 마리한테 확인해봐요, 그는 좋은 아이예요."
rows["109:706469121"]="그레이 헤어 오크는 다리가 걸려 앉아 있습니다. 오그리마.>"
rows["109:761431882"]="모든 고대정령 중에서도 골드린 님께서 가장 멋지오. 그분의 맹렬함과 단호함이란... 성공하려면 그분을 본받으시오."
rows["109:837780213"]="우리는 광부, 농부, 기술자이지 군인이 아니오. 하지만 필요하다면 우리는 맨주먹으로라도 우리 땅을 지킬 거요."
rows["10:1327063157"]="...주인님?"
rows["10:1475470744"]="네, 용사여?"
rows["10:1927043304"]="쌍둥이 봉우리"
rows["10:2044295021"]="안녕하세요"
rows["10:2049726686"]="맞는 말이다."
rows["10:2139359566"]="뭐 원해?"
rows["10:337799629"]="좋은 생각이네요!"
rows["10:48706781"]="어느 쪽이?"
rows["10:549340897"]="흠... 하?"
rows["10:814753957"]="배고픈"
rows["10:821052807"]="아이스크림 사 주세요!"
rows["110:1017340820"]="라작스를 처치하라는 명령을 받았다. 깔끔하게 마무리하고 싶다면 놈을 제거하라."
rows["110:1043752961"]="<당신이 다가가자 게르샬라가 당신을 보려고 옆으로 몸을 돌립니다. 그의 얼굴에 퍼지는 희망에 찬 미소를 볼 수 있습니다.>"
rows["110:1159483358"]="야외로 나들이 나온 게 아닙니다! 당신은 지금 아웃랜드에 있는 거예요! 열심히 임무를 수행하시든가 아니면 다시 어둠의 문 저편으로 넘어가시란 말입니다."
rows["110:116969450"]="저희 가게에서는 스톰윈드 각지에 싱싱한 꽃을 독점 공급하고 있습니다. 어디에나 잘 어울리고 동부 왕국 어디서도 찾을 수 없는 아름다운 꽃이죠. 천천히 둘러보시면서 꽃 향기에 흠뻑 취해보시는 게 어떨까요?"
rows["110:1172204973"]="파라딘 트레이너의 마스터를 찾고 싶다면 챔피언 바치로 가요"
rows["110:119613716"]="더러운 날름이 친구 같으니. 너는 여기 있을 자격 없다. 광란심장 일족 땅에서 사라지지 않으면 마법이라도 써서 없애버리겠다!"
rows["110:1239959320"]="아, 어서 오세요. 이번만이라도 가죽을 잘 준비하셨다면, 쓸모 있는 물건을 어떻게 만드는지 알려드리도록 하지요."
rows["110:1282879488"]="스미스 아거스를 찾고 있을 거야 보통 훈련이 필요하다면 골드샤이어에서 가공장을 감독해"
rows["110:1314930501"]="이 오래된 드레나이의 게시판은 쿠레나이가 다시 깨끗하게 닦아서 공지 사항과 현상금을 게시하는 데 사용하고 있습니다."
rows["110:1324459270"]="이 일이 끝나고 나면 서리갈기 부족은 트로그들보다 우리를 더 무서워하게 될 거예요. 그리고 이곳을 떠날 수밖에 없게 될 거고요."
rows["110:1354771978"]="물약에 대해 배우러 왔다고? 가르쳐 줄 것이 아주 많다네. 죽은 몸이긴 하지만 아직은 머리까지 죽진 않았네."
rows["110:1359561882"]="<늙은 얼음지느러미가 경계하듯 바라봅니다. 무뚝뚝하게 그만 가 보라는 듯 머리를 꾸벅이면서 물고기 같은 눈을 깜빡입니다.>"
rows["110:1442197827"]="사제나 드루이드가 하나라도 이곳에 있으면 얼마나 좋을까요. 제 다친 곳이 다 아물기 전까지는 공부를 계속할 수가 없으니 말이지요."
rows["110:1486499715"]="버섯구름 봉우리에 그나마 남은 것조차 완전히 파괴되는 걸 보고 싶나?$B$B싫다고?$B$B그렇다면 내 명령을 따르는 게 좋을 걸세."
rows["110:1515172499"]="다들 잘 돌아왔어요. 이제 한 시름 놓게 됐네요.$b$b당신도 함께 돌아오셨다니, 정말 기쁘네요! 저희와 함께 가시겠어요?"
rows["110:1525081719"]="의식이 끝나는 대로 마날 님이 도착하실 거야. 내 동료들이 이 역겨운 괴물의 뒤처리를 도울 거고."
rows["110:154974660"]="내 고기 좀 둘러보게, 친구. 예비 식량을 넉넉하게 챙기지 않고서 불모의 땅에 나가고 싶지는 않을 걸세."
rows["110:1602363632"]="미올로를 보러 가겠다고? 바로 저기 있소. 당신 뒤에 말이오! 아니... 당신 앞이라고 해야 하나? 어쨌든 거대한 모루 근처에 있소!"
rows["110:1642416440"]="새로 얻은 무기 사용법을 배우고 싶은가? 명예의 골짜기에 있는 전설의 무기점으로 가서 하나시와 함께 있는 사요크를 찾아보게."
rows["110:174989995"]="준비가 되면 알려주세요. 좀 빨리 갔으면 좋겠군요. 독이다 뭐다 해서 서서히 죽어 가고 있으니까 말이에요..."
rows["110:1761801620"]="이 많은 입을 누가 다 먹여 살리는지 아세요? 바로 저라고요!$B$B요리하며, 청소하며, 뭐든 다 제 몫이라니까요!"
rows["110:1782578614"]="우선 여명의 설원에 있는 생물들에게서 찾아보는 게 좋겠지.$B$B하지만 다른 곳에서도 찾을 수 있을 걸세."
rows["110:183469261"]="마드리고사가 저와 동행했지만 태양샘 안에서 서로 떨어지고 말았습니다.$b$b부디 그녀가 안전했으면 좋겠군요..."
rows["110:1866777506"]="당신은 잘못 찾아왔군. 난 초보자는 가르치지 않소이다. 저기 있는 우트라는 젊은이에게 가 보시오. 저 친구랑 얘기할 때 긴 단어는 사용하지 마시오."
rows["110:1893603011"]="모벌 더 더크는 칼 가게의 무기 래크에 있는 트레이더의 차원의 뒤쪽의 장갑고리에 있습니다."
rows["110:190758753"]="대용광로가 있는 동쪽 지역에서 약간 북쪽으로 가면 선견자 야바드를 만날 수 있답니다."
rows["110:1971224910"]="싸울 때의 내 우아한 모습은 가르쳐 줄 수 있는 게 아니지만 여러 가지 무기를 다루는 법은 가르쳐 줄 수 있어요."
rows["110:2051619412"]="스톰윈드는 인간의 기둥이며, 의지력과 견고한 칼의 가장자리로 유지됩니다."
rows["110:2065679162"]="난 빵을 팔지만,  ⁇ 셔 빵과 비교할 수 없어"
rows["110:2122488549"]="뭔가 유용한 걸 배우려는 이를 만나니 기분이 좋군. 군사 지구 내곽에 있는 아키발드에게 가보게."
rows["110:335992549"]="자네는 젊은 아라코아로군, 아닌가? 눈이 어두워서 말이야.$B$B아마도 내 별난 책 중 하나를 사러 왔겠지?"
rows["110:360836909"]="하루하루가 다 시험이고, 오늘 역시 예외는 아니죠. 이 시험을 통과하면 내 지식을 좀 전수하도록 하겠어요..."
rows["110:489507726"]="나는 대지 고리회의 운트라그라고 하오. 정령의 옥좌에서 지내는 동안 정령들을 자극하지 마시오."
rows["110:570361837"]="이라라라 젠더보우는 크리스탈 홀의 남쪽 문에서 브레이지어를 돌고, 그 사이에 도로가 지나간다."
rows["110:627142987"]="은행은 성문의 북서쪽 상업 지구에 있습니다. 지도를 통해 위치를 알려드리겠습니다."
rows["110:640132695"]="특성을 새로 구성할 수 있도록 모든 특성을 삭제해 드리겠습니다.$b$b특성 초기화 비용은 횟수를 거듭할수록 늘어납니다."
rows["110:724042002"]="이거 괜찮은데요! 하지만, 왠지 좀 밋밋하군요. 트롤 발가락 때를 넣고 맛을 좀 살려볼까..."
rows["110:73626048"]="뼈가 훤히 다 드러난 내 무릎이 쑤시는 걸 보니, 곧 굉장한 비바람이 불어오겠구먼. 그 폭풍에 갇히지나 않았으면 좋겠네."
rows["110:905974038"]="뾰족창 부족 우두머리가 곧 이곳에 나타날 겁니다. 공격에 가담하고 싶다면, 참고 기다리십시오."
rows["110:90751672"]="기계공학을 알면 적을 산산조각 낼 기술과 지식을 얻을 수 있습니다! 내가 보여주겠습니다."
rows["111:102884660"]="와이번 조련사가 어디에 있겠나? 힘의 골짜기에 있는 하늘탑 꼭대기로 가보게."
rows["111:1087860942"]="흠, 제자로 받아들여도 될 만큼 실력이 있는 분이로군요. 거기 그렇게 가만히 서있지만 마시고 배우고 싶은 게 뭔지 말해보세요."
rows["111:1129463513"]="북쪽으로 난 길을 따라 오그리마로 가게. 그곳 그런트에게 어디로 가면 요리를 배울 수 있는지 다시 한번 물어보게."
rows["111:1172877683"]="남부 던 발다르 참호는 던 발다르의 동쪽과 남쪽 측면을 방어합니다.$B$B현재 얼라이언스가 점령하고 있습니다."
rows["111:1231477612"]="<고서를 뚫어지게 바라는 마스레디스>$B$B결정체 때문에 온 거요? 고서에 적힌 대로 했소?"
rows["111:1265831118"]="이 코도는 애초에 길들인 것과는 전혀 딴판으로 생겼습니다! 코도 유인기가 먹혀 들지 궁금합니다."
rows["111:1275761556"]="가죽을 자르기 전에 항상 치수를 두 번씩 확인하도록 하십시오. 재료를 낭비할 수는 없습니다."
rows["111:13055569"]="맞아요. 예전에 여기서 당신을 만났었어요! 그걸 어떻게 잊어버리겠어요!$B$B원한다면 지금 바로 스트라솔름으로 순간이동시켜 드릴게요."
rows["111:1315875340"]="아, 상냥한 세리아드네 말이군요. 그녀가 보살피는 동물들은 모두 우리 안에 안전하게 살고 있지요. 돌라나르 여관 바로 밖에서 찾을 수 있을 겁니다."
rows["111:1386480159"]="이 난장판을 정리해야 하지만 불평 따위는 하지 않겠네.$B$B호드로서 긍지가 조금이라도 있다면 나를 도와주게!"
rows["111:1425094826"]="제가 기계타조 조종법을 가르쳐 줄 수 있어요. 손에 몇 골드나 쥐었는지 한번 짤랑거려 보세요. 헤헤... 수업료가 충분한지 궁금해서요."
rows["111:1436750417"]="생명의 숲에서 우리 일이 무사히 진행되어야 합니다. 우리의 생존은 숲의 안녕과 성장에 달렸습니다."
rows["111:146024671"]="그록가르는 콜리세움 서쪽에 있는 명예의 계곡에 있는 사냥꾼의 홀의 정원에서 레인저스를 훈련시킵니다."
rows["111:149773145"]="급한 일이 아니라면 이야기할 시간이 없소, 시민이여. 테라모어의 성문을 지키는 건 중대한 임무라오."
rows["111:1516062952"]="게르크, 부르, 다르가스... 모두 가버렸어요. 멕켈라르와 저만 여기 남았지요. 당신이 뭔가 좋은 소식을 가져오신 거라면 좋겠군요."
rows["111:1540593874"]="아이언포지에 노움들이 운영하는 연금술 전문 상점이 있다고 들었습니다. 그곳에 한번 가보십시오."
rows["111:1549726427"]="호드 대사관에 있는 울트런 클랜브링어를 찾는 거로군. 대사관은 힘의 골짜기 서쪽에 있네."
rows["111:1627994035"]="우리 적들은 얼어붙은 황무지에서 우릴 완전히 몰아냈다고 생각한다.$B$B그 무지한 생각이 어떤 결과를 가져오는지 놈들에게 보여주겠다."
rows["111:1679778849"]="아이언포지 한복판에 있는 대용광로로 가 보십시오. 그는 그곳에서 우리 종족의 다른 훌륭한 장인들과 함께 일하고 있습니다."
rows["111:1862152933"]="마법사? 마법 지구 중앙 건물에 있지. 그 정도야 자네도 알아서 찾아낼 줄 알았네만."
rows["111:1907999213"]="무너진 하늘 마루의 하늘에서 떨어진 거대한 수정을 둘러싼 신비를 밝혀내야 합니다."
rows["111:1944805626"]="쿠자리와 장가는 훈련을 시켜주는 인간사냥꾼인데, 골짜기 남동쪽 방면의 작은 섬에 있습니다."
rows["111:1982063868"]="방금 어떤 남자가 저한테 집적댔어요. 어떻게 감히!$B$B가서 좀 혼내주면 안 될까요, 자기? 그래 줄 거죠? 고마워요!"
rows["111:2079444288"]="노스렌드로 가고 싶은 거군요, 그렇죠? 크라켄 호는 여기를 출발해서 북풍의 땅에 있는 용맹의 성채로 간답니다."
rows["111:2084170319"]="우리 성기사 아니다. 여자 엘프 하나 왕실에 있다. 그 엘프 성기사다. 그리 가서 배워라."
rows["111:23315547"]="그가 정답을 모두 알고 있으리라고 생각했어요.$b$b난... 그러길 바랐죠.$b$b그는 자기주장과는 전혀 다른 사람이었어요.$b$b내가 바보였지요."
rows["111:396202932"]="내 전당을 통과하려면 고도의 기술을 요하는 게임에서 날 이겨야 한다! 시작할 준비가 되면 왕을 움직여라..."
rows["111:414516373"]="무슨 수를 써서든, 초갈이 끔찍한 무기를 만들지 못하게 막아야 하오. 우리 자신을 희생해서라도."
rows["111:491067773"]="스톰윈드 왕실 은행은 드워프 지구의 최북단 구석에 있습니다. 바로 북쪽 단 안쪽에 말입니다."
rows["111:67425062"]="<당신을 위아래로 재듯이 바라보며 입을 벌린 채 슬쩍 미소 짓는 사령관>$B$B듣고 싶던 대답이군."
rows["111:693073566"]="와슈 제부얼진은 영의 계곡의 다크브라이어 로지에서 포털 트레이너 툴 근처에 공부합니다."
rows["111:717546174"]="병영에서 자도 좋네. 하지만 내 부하들을 깨우지 않게 조심하게. 그랬다가는 내가 직접 눈밭에 내던져버릴 테니."
rows["111:758993114"]="난 도전이 좋아. 자넨 안 그런가? 그래, 당연히 그래야지. 그러면 내가 시키는 일도 당연히 해주겠지?"
rows["111:809209959"]="우리의 훌륭한 요리사, 뭄만이 도시의 정문 근처 여관 바로 옆에 소박한 상점을 차렸습니다."
rows["111:812663168"]="조화의 약초상점에 있는 코민 윈터후프를 찾아가 보셔야겠습니다. 그는 봉우리 중간층에 가시면 만나실 수 있답니다."
rows["111:923187953"]="당신이 용케 물건을 좀 구해다 놓은 덕에 다시 요리하러 갈 수 있겠군요. 자, 제가 해드릴 일이 있습니까?"
rows["111:965060764"]="약초학은 말론처럼 잘 알려지지 않은 부드러운 감각을 필요로 합니다."
rows["112:1025077134"]="채찍파도 일족이 과거의 영광을 되찾을 수는 없겠지만, 이 더러운 뱃놈들은 녀석들이 저지른 짓의 대가를 치를 것이다... 반드시!"
rows["112:1078020104"]="우리 야수가 많으면 좋겠다. 야수 돌봐주는 거 안야 마울레이가 도와준다. 상업 지구 위층 여관에서 찾아봐라."
rows["112:1103352234"]="정말 끝내줬어요!$B$B물고기들이 겁을 좀 먹었겠지만요.$B$B초특급 대포로 다시 순간이동시켜드릴까요?$B$B물론 돈은 좀 든답니다..."
rows["112:1159973191"]="아, 그래, 맞아. 다단가는 연기를 싫어하지. 하지만 곁에서 냄새를 맡아 보니 목욕하는 것도 싫어하는 모양이던데?"
rows["112:1287692799"]="엄... 요리 말인가? 북쪽에 있는 오그리마로 가야겠군. 그리 멀지는 않지. 그곳에 도착하면 그런트에게 다시 한번 물어봐야 할 거야."
rows["112:131179736"]="아이스크림 제국을 세우도록 도와주셨으니, 저의 다양하고 맛있는 혼합 아이스크림 중 하나는 꼭 맛보고 가세요!"
rows["112:1422198785"]="그래, 자네 좀 아는군! 더 배우고 싶거든 스톰윈드에 있는 조르지오 볼레로를 찾아가 보게."
rows["112:1462754958"]="탐구자 보두로는 고난의 거리 내에 있는 상인의 시장에서 종종 보이곤 합니다. 그곳에서 그를 찾아보시기 바랍니다."
rows["112:1503345126"]="상업 지구에 있는 교역의 전당과 드워프 지구에 있는 스톰윈드 경매장, 두 곳의 경매장이 있습니다."
rows["112:1534876920"]="<볼코르의 몸이 움직이지 않습니다. 당신이 떠나려 하자, 뻗어온 손이 당신의 발목을 잡습니다. 볼코르가 살아 있습니다!>"
rows["112:1579156306"]="모든 동물은 사냥꾼의 친구지요. 수렵의 봉우리 꼭대기에 있는 사냥꾼의 전당으로 가 보십시오."
rows["112:1602227006"]="훈련을 받으러 왔나? 자네의 옷에 묻어 있는 그 먼지부터 털어내고 시작하도록 하지."
rows["112:1665451564"]="여분의 보급품이 많이 있긴 하지만 투쟁의 벌판으로 공격 부대를 보내려면아직 더 많이 필요하오."
rows["112:1681610260"]="힘의 골짜기에 있는 여관주인 그리쉬카를 찾아보게. 여관은 도시 정문에서 북동쪽에 있네."
rows["112:1777010809"]="스카이미스트레스 글로밍은 실버문 근처의 마지스터 게이트 바로 바깥에 서 있으며 드래곤하크를 돌보고 있습니다."
rows["112:1780153461"]="폭풍의 눈에서 전투를 할 만큼 강하지 못해 더 많은 경험을 쌓은 후에 돌아와"
rows["112:1873996380"]="북녘골의 시민이여... 당신 체격이 꽤 좋은 분이로군요. 여기 경비가 좀 부실한데 좀 도와주실 수 있습니까?"
rows["112:1904068693"]="다크문 축제가 시작됐습니다! 모두 아제로스 전체에서 가장 신나는 쇼를 놓치지 마세요!"
rows["112:1913769879"]="저희는 이곳에서 뒤틀린 대지를 치유하기 위해 온 힘을 다하고 있어요. 그렇지 않아도 힘든 상황에, 밤마다 습격을 당하기 시작한 거죠."
rows["112:1943963869"]="<호기심 가득한 눈으로 쳐다보는 핏빛장미>$b$b놈들이 왜 그토록 당신에게 관심을 두는지 궁금하군요.$b$b나쁜 뜻은 없어요..."
rows["112:2000318300"]="동부 역병지대에 있는 티르의 손 수도원에 가면 자물쇠 따는 연습을 하기에 좋은 금고들이 많이 있을 겁니다."
rows["112:2047996097"]="손님의 얼굴과 영혼은 지치고 힘들어 보이는군요. 저희 여관에서 지친 몸을 편히 뉘이시고 꿈속에서 엘룬께 조언을 구하시기 바랍니다."
rows["112:232160333"]="장착 무기라면 오그리마의 무기 전문가인 사요크한테 가서 배우게. 그 오크는 요새 명예의 골짜기에서 지내더군."
rows["112:234708300"]="자물쇠 상인을 찾는다면 하수구로 가보셔야 할 것 같군요. 거기엔 뭐랄까... 질이 좋지 않은 자들이 많거든요."
rows["112:362653603"]="비늘한 나로샤는 크리스탈 홀 너머의 크리스탈 광산에서 숨어 있습니다."
rows["112:374225134"]="휴식을 취할 시간이에요. 아니면 식사를 하고 쉬실 건가요?$B$B글쎄, 누군가 그럴 자격이 있다면 바로 당신이시랍니다!"
rows["112:512928647"]="성기사를 만나려거든 왕실로 가봐야 할 걸세. 자넬 가르쳐줄 수 있는 엘프가 몇 명 있지."
rows["112:611651447"]="불타는 평원은 위험한 곳이지만 나 같은 학자들은 지식을 넓히기 위해서라면 어떤 일이라도 감수하지요."
rows["112:679080149"]="사자무리 여관에 한번 가보시죠? 그곳에서 상급 요리사가 훌륭한 조리법을 몇 가지 가르쳐 줄 겁니다."
rows["112:708303718"]="이 숲은 꼭 유령이 나올 것 같습니다. 얼라이언스보다도 나쁜 기운이 가득하니 조심하십시오."
rows["112:729307965"]="정복 섬에 전투를 할 만큼 강하지 못해 더 많은 경험을 쌓은 후에 돌아와"
rows["112:810391823"]="돈 냄새가 나는군! 아버지가 항상 말씀하신 대로야. 돈을 벌기 가장 좋은 때는 전쟁이 났을 때지."
rows["112:818102550"]="여기서 빠져나가는 일은 생각보다 훨씬 어렵군.$B$B눈에 보이는 거라곤 하늘뿐인 여기서 대체 어디로 갈 수 있겠소?"
rows["112:830546121"]="케이레이와 그녀의 히포그리프들은 이 정령들보다 굉장히 강력했으니 뭔가 다른 것에 목숨을 잃었을 게 분명합니다."
rows["112:857065987"]="로키아 로카는 그녀의 종파들을 모아서 셰이프의 틈에서 모집합니다."
rows["112:862560908"]="이 물건의 조악한 품질로 보아, 한동안 암시장에 넘쳐 흐르던 가짜 유물일 것 같습니다."
rows["112:894466767"]="이 고난을 살아남았기 때문에 다행이군."
rows["112:939650493"]="당신 같이 보석세공에 대한 해박한 지식을 갖춘 분을 보석세공의 최고의 경지로 이끌게 되어서 영광이로군요. 어떤 것을 배우고 싶습니까?"
rows["112:947593726"]="짐마차 안에는 피오나와 동료들의 개인 소지품과 함께 상점에서 팔 물건이 상자에 담겨 있습니다."
rows["113:1045424028"]="페니 파이어위슬은 그레이트 포지에서 화재를 만들고 있습니다."
rows["113:108471298"]="여관주인 카우스가 도와 줄 수 있겠군요. 블러드후프 마을 서쪽에 있는 길쭉한 건물 중 하나에 있을 겁니다."
rows["113:1139493054"]="스칼로맨스라고 알려진 강령술 학교는 서부 역병지대에 폐허가 된 섬 카엘 다로우에 있습니다."
rows["113:1242173637"]="엥? 무슨 일이죠? 이보세요, 전 좀 바쁘거든요!$B$B아, 도와주러 오신거라면 언제나 환영이랍니다."
rows["113:1286949977"]="여기서는 할 일이 끊임없이 생기는 것 같습니다. 정말 이상하게도 매일 새벽 3시면 새로운 임무가 도착하고 있습니다."
rows["113:1301892992"]="무두질을 배우고자 한다면 구 시가지에 있는 태너의 가죽용품점에서 매리스 그랑거를 만나보시기 바랍니다."
rows["113:1393861122"]="아저워치에 캠핑하는 여러 인스트럭터들이 있는데"
rows["113:1393946927"]="여기 제 동생은 무역연합에서 떠오르는 샛별입니다. 물론 동생은 아주 겸손해서 아니라고 하지만요."
rows["113:1422724526"]="저한테 배우기에는 당신의 연금술은 아직 좀 부족합니다. 혹시 나중에 다시 오시면..."
rows["113:1486702245"]="달라란 서쪽, 자매 마술사에서 마법 재료와 다른 물건들을 구입할 수 있습니다.$B$B무어헤드의 검은 고양이만 조심하세요..."
rows["113:1489998616"]="요리사 수련을 받으러 이곳까지 날 찾아오는 이들은 드물지만, 당신이 준비가 되었다면 요리의 기본 정도는 가르쳐드릴 수 있을 듯싶습니다."
rows["113:1513204623"]="탈영병들이 버려진 경비탑을 장악한 까닭에, 북부 경비탑이 테라모어의 최전방 거점이 되었습니다."
rows["113:1524643002"]="군사 지구로 가보게. 거기서 사제들이 사지가 제대로 붙어 있는지 봐주지."
rows["113:1725033739"]="그대의 솜씨를 한번 보도록 할까요? 임무를 완수하면 기꺼이 그대를 훈련시켜 드리도록 하죠."
rows["113:1757554042"]="아가마스, 첫 번째 문, 로헨도르, 두 번째 문은 이제 파괴되었습니다."
rows["113:1766008222"]="정령 군사들은 정말 가차 없군요. 놈들의 침입을 계속 버티기만 할 수는 없어요. 도움이 더 필요하겠어요."
rows["113:1839759978"]="이 가게에 있는 많은 것들을 내가 만들었지. 어떤가? 신중히 대답하지 않으면 목숨을 잃을 수도 있어."
rows["113:1925821436"]="어떡하지! 어떡하지! 당신이 불을 끄고 해적들이 쾌속선에 오르는 걸 막아주실 거죠? 그렇죠?!!"
rows["113:1942062231"]="오그리마 경매장은 힘의 골짜기에 있네. 붐스틱 수입상의 오른쪽 건물이니 한번 찾아가보게."
rows["113:1982662517"]="그런 것을 보고, 그런 일을 해내고도 목숨이 붙어 있다니... 난 정말 운 좋은 노움이야."
rows["113:2049195947"]="용사님, 어서 오십시오! 십자군의 시험장에서 도전하실 힘은 충분히 모으셨습니까?"
rows["113:2117647428"]="<인사하는 구원자 아에솜>$B$B애드미티우스 님과 얘기해 봤습니까? 그분이 당신이 어디 있는지 찾는 것 같았으니 그분을 만나보는 게 좋겠습니다."
rows["113:2144892474"]="솜씨가 좀 있어 보이는군. 몇 가지 더 배울 수 있겠어. 어디 내가 뭘 가르쳐 줄 수 있을지 한번 보지."
rows["113:220448287"]="아이언포지에서 난리가 났을 때 저도 거기 있었답니다.$B$B아버지께서 제가 왕궁을 떠나는 걸 저렇게 꺼리시는 것도 당연해요."
rows["113:312282888"]="<온몸에 상처를 입은 거대한 검은 비룡이 악의 넘치는 눈길로 당신을 내려다봅니다. 눈도 깜빡이지 않습니다.>"
rows["113:435825404"]="잘하셨습니다! 저런 야수들을 상대로 멋진 전투를 벌이셨군요! 다음 도전은 훨씬 더 까다롭다고 합니다!"
rows["113:485165951"]="툴라스는 고귀한 여성으로서 성스러운 빛의 강력한 수호자랍니다. 그녀는 여관에서 드레나이들을 가르치고 있으니 그리로 가 보십시오."
rows["113:568914739"]="그늘수렵 마을에 있는 울란이 \"고급 요리책\"을 팔고 있소. 요리 솜씨를 늘리려면 그 책이 필요할 것이오."
rows["113:616125855"]="은행? 오그리마에 있지. 길을 따라 북쪽으로 가면 된다고. 그런 다음 그곳 그런트 중 한 명에게 다시 물어봐."
rows["113:618601385"]="피는 생명이라오... 피의 흐름을 조종하는 데 익숙해질수록, 우리 적의 생명력 또한 쉽게 다룰 수 있지."
rows["113:710951330"]="너무나도 오래 난 내 형제를 묵인했다. 이제 모든 걸 제자리로 돌려놓을 때이다. 내 형제와 그의 추종자들을 처단할 때란 말이다."
rows["113:717977104"]="바리마트라스라고? 아니, 한동안 그에게서 소식이 없네. 분명히 여왕님을 위해 중요한 일을 하느라 어디 갔겠지."
rows["113:830045792"]="황혼의 망치단이 벌인 교묘한 술책의 희생자인 툰드리스 윈드위버의 시체가 큰 대자로 누워 있습니다."
rows["113:867221558"]="요리라면 가젯잔의 더지 퀵클레이브가 달인입니다. 요리 솜씨를 늘리려면 그자를 찾아가야 할 겁니다."
rows["113:959068454"]="잔달라 놈들을 막아야 하네. 놈들이 아제로스의 모든 트롤을 지배하게 되면, 우리 모두 위험해질 게야."
rows["113:966779270"]="무슨 일이지, 뼈다귀 씨? 누군가 딴 사람을 찾고 있나? 여기서 질문에 대답해 줄 이라곤 나뿐이니, 알고 싶은 게 있거든 빨리 끝내게."
rows["114:102809556"]="무두질이라면 무란타에게 배울 수 있을 겁니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점 앞에서 그녀를 찾을 수 있을 겁니다."
rows["114:1073520007"]="<의심스럽게 당신을 바라보는 투스카르>$b$b오래 머물지는 마십시오. 당신은 저희를 이해할 수 없습니다. 저는 말썽이 생기는 걸 바라지 않습니다."
rows["114:1082073922"]="전통적인 순례자의 감사절 잔치에 대해 자세히 알고자 한다면, 아무 나누미에게 물어보십시오."
rows["114:119296949"]="아, 신비로운 주문을 배우고 싶습니까? 그렇다면, 마법사 지구에 있는 마법사의 성소보다 적당한 곳은 없으니, 그곳을 방문해 보십시오."
rows["114:1221260225"]="이 귀중한 물건들을 구하기 위해 내가 얼마나 고생했는지 상상도 못 할걸. 와서 전부 다 구경하도록!"
rows["114:1361964607"]="달라란 북쪽에 이 도시에 약간의... 모험을 더해주는 우물이 있답니다. 달라란을 방문하는 분들이 이 우물을 통해 하수도로 가신답니다."
rows["114:1442596504"]="야벤 썬더브루가 맥주통을 지키고 있습니다. 야벤이 지하실에 있는 동안에는 맥주통에 손도 댈 수 없습니다."
rows["114:1469904804"]="사람들은 랩터가 사납고 포악하다고 생각합니다만, 사실 랩터들은 놀라울 정도로 충성스럽고 영리하답니다."
rows["114:1472048769"]="난 침대에서 일어나서는 안 된다고 하지만 이 풍경은 정신을 더 높여줍니다."
rows["114:1492747501"]="안녕하세요. 월터와 전 다른 말과 함께 이 늙은말 블랑쉬를 돌보고 있어요."
rows["114:1566401919"]="미안하지만 나는 자네를 가르칠 실력이 안 되네! 오그리마로 가서 노그를 찾아보시게. 그가 자네를 다음 단계로 이끌어 줄 테니까 말이야!"
rows["114:1684689173"]="둘로 갈라졌지만 모이면 하나가 되지요. 이 쌍둥이 검은 줄파락에 묶여 있습니다.$B$B이 두 검을 찾으면 술트라제가 부활할 것입니다."
rows["114:1712149837"]="미안하지만, 로나가 말을 데려다주면 정말 화가 나겠지\013\010\013\010그 릴네아스랑 함께 오르는 사람들만 위한 거야!"
rows["114:1828420360"]="저쪽에 있는 섬에는 흑요암 생물체들이 득실거려요! 제가 직접 가 보고 싶지만, 저는 다리를 건널 수가 없답니다."
rows["114:1926488431"]="구시가지 남동쪽 문 너머에는 정당이 있습니다. 그 곳에서 승마 훈련과 말 키우는 것을 찾을 수 있습니다."
rows["114:2051863538"]="어... 때려서 미안! 왕, 나 죽이지 마, 제발... 알았지!? 이제 네가 왕이니까 내가 더 좋은 공물 받게 돕는다!"
rows["114:2073843082"]="여보게, 친구! 아직 가을 축제 동전을 가지고 있는 것 같은데, 마침 나한테도 가을 축제 상품이 남아있다네."
rows["114:2114486274"]="가죽 벗기는 법을 배우고 싶거든 도적 지구로 가보게. 내곽 쪽에 무두장이가 있지."
rows["114:2117589602"]="그러니까 서쪽 호수 속에서 홍예문을 발견했다는 말이오? 어디로 통하는지 궁금하군. 그 속으로 잠수를 해봐야겠소."
rows["114:278644377"]="자네 출신은 물론, 하늘경비대에 들어오기 전까지 무슨 일을 하고 살았는지 궁금하지도 않지만 여기 있는 동안만큼은 지시사항대로 따라야 할 걸세."
rows["114:288816948"]="고단의 마법상점으로 가게. 골목길의 서쪽 끝, 지혜의 골짜기 옆에 있네."
rows["114:392890843"]="어딘가 있어야지 아제로스 우리는  ⁇ 이 손상되지 않은 스컬지 다른 어떤 것도 없죠."
rows["114:515960959"]="내가 뭘 가르쳐 줄 수 있을 거라 생각하는 건가? 그런 거라면 록시크가 훨씬 더 잘할 걸세. 그 친구는 오그리마에 가면 있을 테니 어서 가 보게!"
rows["114:534099943"]="마을의 남동쪽 끝에 있는 교수대끝 선술집에 있는 간호사 닐라는 모든 이들을 반갑게 맞아주지. 앞으로 모두 자기 손님이 될 거라고 말이야."
rows["114:607635282"]="그러니까 서쪽 호수 속에서 홍예문을 발견했다는 말이오? 어디로 통하는지 궁금하군. 그 속으로 잠수를 해봐야겠소."
rows["114:655299004"]="아이언포지 은행 앞에는 대부인 윈터가 있습니다."
rows["114:700851328"]="지금 한창 바쁜 거 안 보이나? 오그리마로 가서 그곳 그런트에게나 물어 봐. 오그리마는 쉽게 찾을 수 있겠지? 북쪽 길을 따라 가!"
rows["114:780970121"]="보호막을 유지하기 위해 내가 할 수 있는 일은 다 했어. 대마법사님 중 하나를 찾아봐, 칼리사! 난 이제 더는 버티지 못할 것 같아..."
rows["114:824927759"]="저들이 보이는가? 그래, 안 보일 줄 알았네. 멀쩡한 두 눈으로도 보이지 않는 세계가 있지. 축복이자 저주야."
rows["114:84656361"]="북녘골의 시민이여... 당신 체격이 꽤 좋은 분이로군요. 여기 경비가 좀 부실한데 좀 도와주실 수 있습니까?"
rows["114:883214430"]="머리가 없는 말자는 스카르렛 수도원에서 살고 가끔씩 어른들을 겁에 질려나서 나만 겁에 질리지 않아요"
rows["114:8977801"]="지금 당장은 저주받은 기사를 쫓아냈군요. 잠시 숨을 돌릴 수 있겠지만 경계를 늦추지는 말아야 합니다."
rows["114:936721021"]="비행기는 원래 몇 번 떨어져 봐야 제대로 길들일 수 있지.$B$B정신 멀쩡한 고블린이라면 흠집 하나 없는 비행기는 몰지 않아."
rows["114:97410793"]="진홍 벌판의 기이한 성장 현상 배후에 이 바위 트로그가 있네.$B$B여기서는 이상한 기운이 느껴져... 조심하게."
rows["115:1116330440"]="어둠사냥꾼 덴자이는 이 게시판을 사용하여 중요한 공지 사항이나 자브라진의 적에게 걸린 새로운 현상금을 게시하고 있습니다."
rows["115:1191198162"]="아주 오랜 세월 동안 내 운명을 외면해 왔다. 내가 해야만 하는 일이 명백하지 못했다.$B$B로켄은 내 손으로 없애버리리라."
rows["115:1239901391"]="기초도 모르면서 내 기술을 배울 수는 없네. 카마리를 찾아가 더 배우고 오게."
rows["115:124758495"]="그 야만적인 짐승들이 우리 배를 불태웠을 때 우리 가슴도 내려앉았소. 그런 절망은 처음이었소..."
rows["115:1266754864"]="잘하셨습니다. 조금만 더 하면 이 우리에 호드의 기병대가 전투에 타고 나갈 늑대가 넘쳐날 것입니다!"
rows["115:1303355597"]="- 확실해?$B$B내가 당신의 마음에서 배운 재능에 대한 지식을 지워버린 후에는 돌이킬 수 없습니다."
rows["115:1345789081"]="당신 같은 제자만 있다면 좋겠군요. 용기 있게 적진 깊은 곳으로 들어갈 자는 많지 않답니다. 당신의 용기에 경의를 표합니다."
rows["115:1420058701"]="가로쉬의 상륙지와 팔에아 모두 저 안개 때문에 사라져버렸네. 여기에 남을 만큼 정신 나간 자들은 우리밖에 없단 말이야!"
rows["115:16369471"]="기회가 있을 때 내 물건들을 실컷 구경해 두는 게 좋을 거야. 우린 이번 주까지만 여기 있고 멀리 이동할 거니까."
rows["115:1695412236"]="보급품이 좀 있긴 하지만 투쟁의 벌판으로 지상 공격 부대를 보내려면 훨씬 더 많이 필요하오."
rows["115:1781357178"]="내 나이만큼 살면 사랑 잊기 쉽지만 기억이 나가는 게 좋다"
rows["115:1826131559"]="이 서판에는 광기의 구루바시 모조를 만드는 데 필요한 고대 상형 문자와 무시무시한 힘을 지닌 주문이 새겨져 있습니다..."
rows["115:1886583323"]="켈투자드의 지배를 벗어나고 리치 왕의 몰락을 지켜본 지금, 이 희망찬 시기에도 빛의 결사단은 남아 있습니다."
rows["115:1933358485"]="달라란에는 여러 개의 우체통이 있습니다. 여관과 은행 근처 외곽과 여러 구석진 곳, 심지어는 크라서스 착륙장에도 우체통이 있답니다."
rows["115:1974584667"]="영원노래 숲에서 불어 오는 신선한 공기를 마실 때면 종종 뱃속이 뒤집히곤 하지. 무슨 뜻인지 알겠소?"
rows["115:2030466138"]="어떤 모험가들은 마법부여가 무용지물이라고 생각하지만, 내가 싸움을 걸려고 하면 얼른 말을 바꾼단 말이야."
rows["115:2048186663"]="무슨 수를 써서라도 세계 기둥을 원상복구해야 합니다.$B$B그러려면 먼저 세계 기둥 파편을 모두 찾아야 합니다."
rows["115:2089418481"]="신부 콥을 만나보셔야 하겠군요. 정기의 봉우리 아래 예언의 웅덩이 동굴에 있습니다."
rows["115:2137666472"]="차원문이 열렸어요! 당신 덕분에, 이제 스톰윈드와 황혼의 고원을 빠르게 오갈 수 있습니다."
rows["115:269948471"]="장가르 습지대에서 지내는 동안 시간을 내서 낚시 가는 걸 잊지 마십시오. 언제 다시 물을 보게 될지 알 수 없습니다."
rows["115:278939836"]="에스코다르의 스킨 트레이너들은 가죽 노동자들과 함께 트레이더스 튜어에서 발견될 것입니다. 빛 - 안녕하세요"
rows["115:312466773"]="거대한 상자입니다. 포탄으로 가득 차있습니다. 옆에 식용유가 다소곳이 놓여 있습니다."
rows["115:397512828"]="제대로 찾아왔군. 지혜의 골짜기에 있는 스랄의 요새 입구에서 당신의 진리를 찾아보게."
rows["115:405560027"]="자네 실력이 어느 정도 되는지 어디 한번 볼까? 이 임무를 내가 만족할 수 있을 정도로 잘 완수한다면 내 시간을 내서 자네를 가르쳐 주도록 하겠네!"
rows["115:502417871"]="6미터 높이의 칠면조 조리 기계 설계도가 거의 다 완성됐어요! 이제 6미터짜리 칠면조만 있으면 되는데..."
rows["115:585478478"]="마을을 가로지르는 길의 남동쪽 끝에 있는 교수대끝 선술집으로 가게. 여관주인 리니가 기다리고 있을 거야."
rows["115:749217303"]="내가 판매하는 것은 최고의 장비이고, 테스트되고, 진실이고, 가격도 정해져 있어, 거래하고 싶다면"
rows["115:773025964"]="음, 당신은 향상의 여지가 있긴 하네요. 당신이 잠재력을 지니고 있다는 건 인정하죠. 자, 잘 보고 배우도록 하세요!"
rows["115:835425069"]="오그리마에서 십자로로 장비와 식량을 수송하는 일은 원래 일꾼들이 하던 일이었지. 지금은 내 목이 달린 일이 되었지만 말이네."
rows["115:874515351"]="이 세계는 눈에 보이지 않는 방식으로 깊이 상처를 입었습니다. 심지어 시간의 흐름마저 약간 달라진 것 같아요."
rows["115:915634890"]="엑소다르 근처에 가면 히포그리프가 있습니다. 핏빛 감시초소로 날아가고 싶다면 그곳으로 가도록 하십시오."
rows["115:919785742"]="지금부터 일어날 일은 우리 모두에게 영향을 줄 거예요. 그러니 모두의 도움이 필요해요. 이번 침략을 이겨내려면 우리 모두 함께 싸워야 해요."
rows["116:1044521393"]="물러서라. 이 괴물아. 한판 해보자는 건가? 그렇다면 내가 싸워주지.$b$b네놈 같은 괴물이라면 무조건 상대해 주마! 내 말 알아듣겠나?"
rows["116:1053071588"]="저와 형제들이 길니아스 북부로 가는데 며칠이면 될 겁니다. 배만 고칠 수 있다면 말이죠."
rows["116:1082587561"]="물의 원자 중 한 귀족인 히드라시스가 불의 종들과 전쟁을 벌이고 있다고 들었습니다."
rows["116:1129175208"]="아버지께서는 더 큰 사냥감을 찾아 좀 더 특별한 곳으로 갔네. 허나 우린 아직 이곳에서 사냥하고 있으니 걱정하지 말게!"
rows["116:132904671"]="달라란 북쪽에 이 도시에 약간의... 모험을 더해주는 우물이 있답니다. 달라란을 방문하는 분들이 이 우물을 통해 하수도로 가신답니다."
rows["116:1379360205"]="제임스 랜달은  ⁇ 어동 공학장에서 리얼리아ම් 스파크스핀드와 그녀의 연습생들과 함께  ⁇ 어 있습니다."
rows["116:1415171942"]="밖에 나가서는 몸조심하세요. 남쪽바다 해적들이 만에 나타났다고 해요.$B$B음... 제가 직접 확인해보는 게 좋을 것 같네요..."
rows["116:1433300297"]="이제서야 오는군요. 도대체 뭐가 이리 오래 걸린 거죠? 아무튼 날 엄호해요. 요새로 돌아가야 하니까!"
rows["116:1550927187"]="제니아 룬토템의 조언을 구하는 게 좋겠군요. 마을 동쪽에 있는 커다란 천막에서 제니아 룬토템을 만나실 수 있을 겁니다."
rows["116:1562856408"]="무두질을 배우러 이곳까지 날 찾아오는 일은 드문데... 그래도 당신이 준비가 되었다면 쓸만한 기술은 몇 가지 가르쳐줄 수도 있을 것 같군요."
rows["116:1612695472"]="이 동굴 바로 바깥에 나가의 관심이 집중되고 있습니다.$b$b들키지 않고 여기까지 오다니 운이 좋았군요."
rows["116:1646266316"]="하늘 감시초소의 여관 밖에 서 있는 에스비나가 당신의 야수를 잘 돌봐 줄 것입니다."
rows["116:1736686400"]="실버문으로 가면 광부들을 찾을 수 있습니다. 보나 마나 그 냄새 나는 용광로에서 광물을 녹이고 있을 겁니다."
rows["116:1909170111"]="당신이 추구하는 바를 시작할 수 있도록 내 기꺼이 도와드리겠습니다! 내 스피너를 찾은 다음 곧 시작합시다..."
rows["116:1922372335"]="관심을 보여줘 고맙네. 왕실에 가 보면 말로리 휠러 경이 어둠의 여왕님과 함께 있을 거야."
rows["116:1937456479"]="누가 물어보더라도 이 세상에 광부보다 좋은 직업은 없다고 대답하겠습니다. 우리 드워프를 능가하는 광부는 더더욱 없고 말이죠!"
rows["116:1985093353"]="사냥을 배우려는 순찰자들은 매날개 광장의 북동쪽 건물에 머물고 있는 사냥꾼 한노비아에게 교육을 받고 있으니 그리로 가보시오."
rows["116:2103531212"]="오토 그레이하이드는 장로회에서 많은 시간을 보내죠."
rows["116:2117023114"]="조심하게. 불안정해서 금방 효과가 사라져 버린다네. 바로 사용하게! 그리고... 눈이 닿는 범위에서 사용하는 게 좋을 걸세... 그래..."
rows["116:2130559191"]="순찰대가 영원노래 숲 동쪽에 있는 야영지에 아라텔이라는 대장장이 한 명을 데리고 있지요. 그대를 도울 수 있을 겁니다."
rows["116:29207449"]="오셨군요! 문의 원리를 거의 알아냈어요. 금방 열어드릴테니 준비가 되면 알려주세요!"
rows["116:344431665"]="알렉스트라자 님께서는 데스윙에게 정의의 심판을 내리리라 단언하셨습니다. 악몽 같은 그 모든 일이... 바로 여기서 끝나는 걸까요?"
rows["116:385671297"]="경매장과 은행은 골짜기 중앙의 높은 건물 꼭대기에 있습니다.$B$B지지와 마카부를 찾아보십시오."
rows["116:418657122"]=" ⁇ 드린은 실버문의 기일드 마스터입니다. 그녀의 거주지는 마지스터 게이트 근처의 노인 거리를 따라 있습니다."
rows["116:423084558"]="대사제가 죽고 바깥이 안전해지면 알려 주십시오. 하쿠즈 님께 보고서를 가져가겠습니다."
rows["116:498351902"]="여행을 하시다가 얻은 귀중한 물건이나 돈을 보관할 곳을 찾으시는군요. 이 멋진 도시 중앙에 다르나서스 은행이 있으니 그곳으로 가 보시기 바랍니다."
rows["116:52910143"]="이제 죽음의 기사는 훈련하지 않습니다. 어리석은 수습생들의 끝없는 질문 공세에 지쳤습니다.$B$B그만 가보세요."
rows["116:550526431"]="병든 새끼 흑호는 북쪽에서 오는 것 같으니, 나라면 북쪽에서 사냥을 시작하겠네."
rows["116:564362410"]="그리핀 기수들은 10걸음쯤 떨어진 곳에 있습니다. 그들이 토르손의 전초기지까지 태워다 줄 거예요. 그럼 가보십시오!"
rows["116:64065541"]="제 머리가 반백이고 선원 중에 제일 나이가 든 건 사실이지만, 여전히 가장 억센 뱃사람이랍니다! 어때요? 그렇죠? 오우거만한 이 팔뚝 좀 보십시오!"
rows["116:740387211"]="우리 히포그리프 조련사는 스테파노스입니다. 그는 엑소다르의 중심지에 있습니다. 당신의 여행에 성스러운 빛이 함께하기를."
rows["116:794434250"]="개개인의 힘도 중요하다. 하지만 부족 전체의 힘은 더더욱 중요하다. 그렇기에 우리 부족의 힘은 우리 중 가장 약한 전사의 힘과 비례한다고 생각한다."
rows["116:809111094"]="에메랄드의 꿈에서 깨어난 지 얼마 되지 않아 조금 몽롱하군요. 그래도 이부스의 생명력이 느껴져요. 하지만 제 힘이 충분히 회복되지 않아서 아직 접촉하기는 어렵겠습니다."
rows["116:828365395"]="훈련을 받고 싶으신가요? 당연히 도와 드릴 수 있습니다. 나도 수습 과정에 있을 뿐이지만 당신에게 가르쳐 줄 게 뭔가 있을 겁니다."
rows["116:867895013"]="조심하게. 불안정해서 금방 효과가 사라져 버린다네. 바로 사용하게! 그리고... 눈이 닿는 범위에서 사용하는 게 좋을 걸세... 그래..."
rows["116:932182917"]="<폭발하기 전까지는 믿을 수 있는 성능!>$B$B<전문 기술을 배우고 싶거나 자동판매기를 이용하시려면 돈을 넣으십시오.>"
rows["117:1087565958"]="라우르나 모닝라이트라는 여사제가 돌라나르에서 살고 있습니다. 여관의 바로 북쪽에서 찾을 수 있다고 알고 있습니다."
rows["117:1111141505"]="점술가 길드 여관은 샤트라스의 상층, 점술가 언덕에 있습니다. 그곳으로 가는 승강기는 도시 중심의 남서쪽에 있으니 그리로 가보십시오."
rows["117:1233892325"]="절대로 이 뒤틀린 드레나이들의 눈을 똑바로 바라보지 마십시오. 제 생각에 그들은 마음만 먹으면 당신의 영혼을 흡수할 수도 있을 거 같거든요!"
rows["117:1239227220"]="체, 내가 쓸데없는 잡담이나 하고 있을 만큼 한가해 보이나?$B$B응?$B$B용건이 있으면 빨리 말하게. 오우거들을 해치워야 한단 말이야!"
rows["117:1268616283"]="판드랄 스태그헬름이... \"화염의 드루이드\"가 되어 돌아오다니!$B$B나의 용들 중 하나가 이 끔찍한 일과 관련되어 있을 듯해 두렵구나!"
rows["117:1285409295"]="이 지역에서 발굴된 유물에 신비한 힘이 깃들어 있다는 소문이 돌더라고요!$b$b사령관님은 아마 그런 유물에 매력을 느끼시는 것 같아요..."
rows["117:1410024717"]="이 밑에 굉장한 물질이 묻혀 있어요. 굉장하지요! 모든 걸 대체할 수 있어요. 대체품을 대체할 수도 있죠. 뭐든지 가능하답니다!"
rows["117:1535063000"]="숲에 있는 식물로 창조할 수 있는 것들이 정말 놀랍지 않습니까? 실로 엘룬께서 우리를 아낌없이 축복하셨습니다."
rows["117:1573967362"]="야미르 님은 저 에테리움들이 무슨 일을 꾸미고 있나 걱정하실지도 모르지만 난 바로 디멘시우스라는 진정한 위험에 맞서는 일에 집중하고 있소."
rows["117:173809047"]="이 에테리얼 순간이동 장치는 밝은 색깔의 단추와 스위치로 덮여 있습니다. 하지만, 위장이 되어 있는 것 같습니다."
rows["117:1771173401"]="스톰윈드의 가장 유명한 여관은 상업 지구의 황금 장미와 드워프 지구의 황금 술통이랍니다."
rows["117:178878890"]="정말 어리석군요. 내 경고를 무시하지 마십시오. 이 세상에 완벽한 자는 아무도 없답니다. 제 조언을 조금이라도 새겨 듣는 것이 신상에 좋을 겁니다."
rows["117:1793062348"]="아, 루칸 코르델을 찾으시는군요. 지하감옥으로 가는 길, 마법 지구 외곽에서 상점을 운영하고 있답니다."
rows["117:1801695024"]="육지와 연결하기 위해 저희는 루테란 마을과 어둠해안 사이를 왕복하는 히포그리프를 두고 있습니다."
rows["117:185180216"]="남쪽 비행선 탑승장 안에서 이상한 오크들이 노상 수군거리던데요. 제가 가까이 가면 항상 입을 다물고요."
rows["117:1855815248"]="저 빌어먹을 일꾼들은 너무 느려터졌어! 빨리 아이언포지로 돌아가고 싶네. 마누라와 자식들이 얼마나 보고 싶은지 몰라."
rows["117:1920977436"]="잠시만요... 전 수습 재봉사에 불과합니다. 멋진 걸 만들고 싶다면 저기 스톤브라우와 얘기를 나눠 보십시오."
rows["117:1956745645"]="노스렌드로 갈 생각이라면, 울부짖는 협만의 발가드까지 가는 쇄빙선인 북해의 창날호를 타면 될 겁니다."
rows["117:1975257050"]="금강의 목마른 물을 마감하는 모든 샘들 중, 이 곳처럼 순수하고 결정적인 물을 제공하는 곳은 없습니다."
rows["117:2100654042"]="정말 독특한 표본이군요! 가능성이 정말 많아요! 이 지역 동식물에 대한 연구를 더 열심히 진행해봐야겠어요!"
rows["117:2106755167"]="다잘라의 기막힌 사냥 솜씨는 이곳 돌라나르에서 알아준답니다. 그를 찾아가서 가르침을 구해 보세요."
rows["117:2124970796"]="내가 장담하지! 자네는 여기 텔사마에 있는 그리핀보다 더 빠른 녀석을 동부 왕국 어디에서도 찾아볼 수 없을 걸세."
rows["117:219297186"]="우린 불길을 가릴 때까지 아후네의 하위군들을 살아남아야 해"
rows["117:228892935"]="달라란의 북서쪽, 마법사 교역소에 있는 전설의 가죽방어구에서 모든 가죽세공인과 무두장이들을 찾으실 수 있습니다."
rows["117:274610714"]="쉿... 정찰 장소로 나갔을 때 제 위치를 드러내지 말아 주십시오. 마서스 님께서는 여기서 무슨 일이 벌어지는지 알고자 하시니까요."
rows["117:385721831"]="눈사태 무덤은 겨울도끼 요새에서 동쪽, 투쟁의 벌판 언덕 꼭대기에 있습니다.$B$B아무도 이곳을 점령하지 않았습니다."
rows["117:444479651"]="자, 건배합시다, 친구여!$b$b여기 펼쳐진 광경을 눈여겨보십시오.$b$b아시다시피, 이 땅은 여러 세기 동안 감춰져 있었습니다."
rows["117:471008586"]="알도르 사제회 여관은 샤트라스 상층, 알도르 마루에 있습니다. 그곳으로 가는 승강기는 도시 중심의 북서쪽에 있습니다."
rows["117:569410344"]="오, 고맙소! 내 안에 있던 암흑의 기운이 사라졌어! 다시 앞이 보이는군... 나를 구해준 자의 얼굴이 보여!"
rows["117:74613313"]="난 34Kg짜리 농어를 잡을 때까지는 여기 있을 참이오! 당신은 어디 다른 곳으로 가고 싶은 것이겠지... 그렇지 않소?"
rows["117:818463606"]="<버드가 그저 가만히 못 들은 척하고 있습니다. 가까이서 보니 그의 가면 아래로 침이 흘러내리는 것이 보입니다.>"
rows["117:833112356"]="용사의 전당으로 가게. 포세이큰 파멸단의 데제 스노우베인이 아라시 분지로 가는 걸 도와 줄 걸세."
rows["118:1047408606"]="버림받은 잿빛 골짜기의 땅에 성스러운 빛을 인도하는 것이 내가 진정으로 원하는 일이오."
rows["118:1074937539"]="정기의 골짜기에 있는 검은장미 오두막에서 페프레도와 얘기해 보게. 검은장미 오두막은 힘의 골짜기 서쪽을 향해 위로 올라가면 있다네."
rows["118:1099892480"]="제가 왜 이곳에 왔는지 얘기해 드려야 하겠군요.$B$B데스윙이라는 위상이나 그의 자손들인 네파리안이나 오닉시아에 대해서 아십니까?"
rows["118:1127121882"]="대장장이와 그의 조수는 전사의 정원에서 찾으실 수 있습니다. 무기 및 방어구 상인 근처에 있지요."
rows["118:1213835790"]="도끼를 제대로 사용하고 싶으면 적당한 인사도 해줘야 하는 법이지. 농담이 아냐. 날 한번 따라해 보게. \"안녕! 내 작은 친구야? 오늘은 뭘 베고 싶니?!\""
rows["118:1352260469"]="벌레 같은 이 녀석에게 너무 잔인하다고?$B$B이번 달에만 내 부하를 둘이나 죽인 놈들이오! 우리는 버림받은 자들에게 너무 관대했소."
rows["118:1373527808"]="영웅이시어, 안녕하십니까! 양쪽의 대륙은 물론 다른 지역에서 온 최근 소식이 있는데 아마 관심이 있을 겁니다."
rows["118:1411961492"]="마이클 피트루스는 불에 가까이 있어 마블네어 주위의 도금과 옆에 있는 브레이저에서 찾아보죠"
rows["118:1565577201"]="타나리스의 해적단 소굴과 아즈샤라에 있는 폭풍의 만에 자물쇠 따기 연습을 하기에 좋은 금고들이 있습니다."
rows["118:1574107939"]="대장님께서 저랑 의논하고 싶어하시는 문제에 대해 조언을 해 드렸습니다만, 오히려 당신 말을 더 귀 기울여 들으실 것 같군요."
rows["118:1602767838"]="지하 통로를 통해 대도시들 간에 기름을 운송할 방법을 연구하고 있었는데, 다들 뜬구름 잡는 얘기라고 하는군."
rows["118:1673711876"]="북쪽 상업 지구와 대운하 사이에 있는 덴만가 보석상에 당신이 찾는 모든 게 있을 겁니다."
rows["118:1730486045"]="보급품은 거의 다 떨어졌소. 투쟁의 벌판으로 지상 공격 부대를 보내려면 훨씬 더 많은 보급품이 필요하오!"
rows["118:1769574310"]="소중한 시간을 할애하여 월드 오브 워크래프트: 대격변 콘텐츠를 테스트해 주셔서 감사합니다.\010어디로 가고 싶으신가요?"
rows["118:1822669571"]="널 가르치기는 힘들 것 같군. 신비로운 힘에 동화되려면 여러 해 동안 마음의 준비가 필요하니까 말이야."
rows["118:1928739061"]="이제 당신의 기술을 키워줄 수 있는 자는 유명한 그레고리 빅터 의사밖에 없소이다. 아라시 고원에 있는 망치 주둔지에 가면 그 친구를 찾을 수 있을 것이오."
rows["118:2084159845"]="내 불쌍한 비행기. 예비 부품도 없는데 추락하면서 망가져 버렸어요. 다신 고쳐서 날 순 없을 거예요!"
rows["118:218884524"]="우리는 당신의 동맹을 찾아내고 이 지역에서 나가 동기를 발견해야 합니다.$b$b하지만 먼저 더 안전한 장소를 찾아야 합니다."
rows["118:29254278"]="골두니 오우거는 이 땅을 망칠 만큼 망쳐놨네. 우린 호드를 위해 이 땅과 자원을 손에 넣고자 하네."
rows["118:381424495"]="빛의 스피커 샤일란은 전쟁 구역에서 가르치고 있습니다. 동쪽 코디도르에서,"
rows["118:387957959"]="너희는 아직 옛 선조들의 길에서 전투를 할 만큼 강하지 못하니 더 많은 경험을 쌓은 후에 돌아가라"
rows["118:397560436"]="보급품이 있긴 하지만 충분하지 않소. 투쟁의 벌판으로 지상 공격 부대를 보내려면 훨씬 더 많이 있어야 하오."
rows["118:399845547"]="난 대장장이인 버니네이트라네. 어... 그리고... 약간의 음식과 음료 등을 파는 일을 부업으로 하고 있지. 고기 좀 들지 않겠나?"
rows["118:45478046"]="아르거스의 대리인의 일원이 된다는 의미는... 성스러운 빛의 대리자가 된다는 뜻이오. 어떠한 의심도 없이 봉사해야 하며 어떠한 의심도 없이 기꺼이 죽음을 맞이해야 하오."
rows["118:490097438"]="스톰파이크 보급기지는 던 발다르 병영 바로 외곽인 던 발다르에 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다."
rows["118:519049476"]="그대는 아직 기본기를 익히지 못했군요, 방랑자 친구. 내 조수, 랄리나 서머문과 얘기해 보았습니까? 그녀와 얘기해 봐야 할 거요."
rows["118:62940476"]="사방 천지에 폭탄 던지는 원숭이가 가득한 섬에 조난당하다니? 다음엔 또 무슨 일이 벌어질까요... 여기에도 곧 폭발할 화산이 있나요?"
rows["118:710833197"]="다크월 페어는 커튼이 닫히기 전에 짧은 시간 동안만 작동할 것입니다. 오늘 방문할 것을 확신하십시오."
rows["118:793681322"]="파루자를 찾아가 보게. 마지막으로 봤을 때는 마을 북서쪽 끝에 있는 마구간 옆에 서 있었네."
rows["118:860214605"]="수정 안으로 거대한 통로가 굴처럼 뚫려 있는 것이 비춰 보입니다. 직감으로 그곳이 화산 심장부라는 것을 알 수 있습니다."
rows["118:939119098"]="살데릴 경께서 부탁한 목록입니까? 잘 됐군요. 방금 요리한 전채 요리를 꽤 많이 팔 수 있겠습니다."
rows["118:940175494"]="회복의 수정은 구하기 쉽지 않은 물건입니다.$B$B운고로 분화구에서 구할 수 있을 것이니 그리로 가보는 게 제일 좋은 방법일 겁니다."
rows["119:1040548691"]="나그네의 쉼터는 장로의 거리와 시장 사이에 있소이다. 어떤 방향에서 가든지 그곳에 당도할 수 있소."
rows["119:1060037942"]="이곳 던 모로에는 연금술사가 없습니다. 아이언포지로 가보는 게 제일 좋을 겁니다. 땜장이 마을에 있는 노움들에게 한번 물어보시지요."
rows["119:1086622842"]="오, 약초채집가로군요. 흠, 보아하니 당신은 아직 잡초나 캐고 있을 것 같으니, 내 제대로 된 약초채집 기술을 몇 가지 가르쳐 주도록 하겠소."
rows["119:1114599609"]="이럴까진 모르겠지만 연습한 지 오래됐지만 아직도 첫날처럼 느껴지네"
rows["119:1169487889"]="보급 요청 목록을 가져다주셔서 감사합니다! 제 다리도 거의 다 나았으니 이제 추락 지점으로 돌아갈 수 있습니다."
rows["119:1252372426"]="얼음날개 참호는 얼라이언스 영토와 투쟁의 벌판 사이에 통로를 확보하고 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다."
rows["119:1254297825"]="코너 야만전사보기 전에 들리겠지만, 그는 올드타운의 지휘 센터에 있는"
rows["119:1257966734"]="흠... 가는 게 있으면 오는 것도 있어야겠죠. 내가 부탁하는 일을 잘해 준다면 당신 훈련에 관해 얘기해 볼 수 있을 거예요."
rows["119:1295336680"]="잘 나가는 것 같군, 칭구! 부유한 상인 물건 많이 털었? 웬만 좀 뿌리는 게 좋아... 과욕 목 조르는 법!"
rows["119:1325391626"]="지금은 그 지역에 스컬지의 더러운 손이 닿지 않았습니다. 하지만, 스컬지가 돌아오는 것도 시간문제이니 걱정이 아닐 수 없군요."
rows["119:1333360712"]="스톰윈드 은행과 무역 구역의 골든드 로즈 인 사이에 편리하게 위치하고 있는 우편 상자도 있습니다."
rows["119:1391712845"]="드루이드? 오... 샬란니우스, 샬란니우스를 찾으시는군요. 엑소다르 외곽, 발라르의 나루 근처에서 이 나이트 엘프를 찾을 수 있을 겁니다."
rows["119:1486462945"]="지원 병력이 더 올 때까지 여기서 시간을 끌어보겠지만, 그대들은 계속 나아가야 한다. 우리가 여기에 왔음을 곧 아서스가 눈치챌 것이다."
rows["119:1808228975"]="광산의 문제를 도와줘서 얼마나 고마운지 모르겠네. 이제 광부들이 일터로 다시 돌아가도록 설득하는 일만 남았군그래."
rows["119:1833729839"]="호드는 명예와 전쟁을 중요하게 여기지. 하지만 이 연금술사들이 하는 일에 명예라고는 눈곱만큼도 없소."
rows["119:1917127341"]="하이잘 산에 진입하실 수 있도록 설정해 드렸습니다. 준비가 되시면 시간의 동굴로 순간이동시켜 드릴 테니 말씀해 주십시오."
rows["119:1972461884"]="달라란 북서쪽, 마법사 교역소에 달라란 최고의 긴급 치료 중심지인 응급치료의 모든 것이 있습니다."
rows["119:2004083277"]="저주받은 기사의 마음은 광기로 가득해요! 할로윈 기간에는 저주받은 기사가 언제라도 이 마을을 습격해 올 수 있어 불안하답니다."
rows["119:2011056774"]="이 큰 제단은 오래전에 이 땅에 거주하던 나이트 엘프들이 지은 것입니다.$B$B이 사원에는 어떤 비밀이 숨겨져 있을지 아직은 알 수 없습니다."
rows["119:2020660498"]="마법 지구 주 건물 안에 흑마법사들이 있네. 가서 문제를 일으키지는 않아 줬으면 좋겠군."
rows["119:2072174712"]="우리 마법사들은 에크소다르에 하루를 보내고 여러 프로젝트를 진행하고 있습니다."
rows["119:260482097"]="이 호디르의 뿔피리를 닮은 기념비는 천둥 골짜기 전투에서 전사한 아른그림 왕과 다른 모든 병사들을 추모하기 위해 세워졌습니다."
rows["119:282099300"]="왼쪽 모퉁이를 돌아 쭉 내려가면 던컨의 옷가게가 보일 겁니다. 거기서 일하는 로렌스 슈나이더와 얘기해 보십시오. 초보 재봉사들을 아주 잘 가르치는 분입니다."
rows["119:333751774"]="힘으로만 이기는 싸움은 거의 없습니다. 기교가 필요하지요. 재빠른 반사 신경과 무기에 대한 지식이 있어야만 승리할 수 있습니다."
rows["119:394766311"]="어서 오세요, 신기한 장난감 상점입니다!$B$B천천히 둘러보셔도 좋아요. 남녀노소를 불문하고 재미있게 놀 수 있는 장난감이 가득하답니다!"
rows["119:407116375"]="그건 못 해요. 하지만 저기 있는 대지치유사 도로스와 이야기해 보세요. 폐허가 된 황혼의 야영지를 살펴보는 저 덩치 큰 드레나이 보이시죠?"
rows["119:492578288"]="이야, 여기야말로 정말 멋진 곳이 아니겠습니까?$b$b마음이 통하는 사람들과 미지의 세계를 여행한다니...$b$b이보다 나은 일이 어디 있을까요?"
rows["119:665086288"]=" ⁇ 즈케크는 그림자 갈래의 그림자 부부의 가장자리에 있습니다."
rows["119:674921512"]="철벽 알순다르와 다른 상급 전사들은 주조소 근처에서 원정순찰대 광장을 바라보는 곳에서 찾을 수 있습니다."
rows["119:722247630"]="대격변은 우리 모두에게 정말 힘든 일이었지만, 그럭저럭 살아나가고 있습니다.$B$B당신도 소매를 걷어붙이고 주어진 일에만 충실해야 합니다."
rows["119:750082478"]="자네도 사냥꾼인가? 어쨌든, 칼바위 언덕 남서쪽에 있는 어두컴컴한 지하실에서 태양을 피하고 있는 소타르를 찾아가 봐."
rows["119:761363383"]="보급 요청 목록을 가져다주셔서 감사합니다! 제 다리도 거의 다 나았으니 이제 추락 지점으로 돌아갈 수 있습니다."
rows["119:767023335"]="교수대끝 선술집의 식당 안에서 오스틸 드 몽을 찾아보도록. 그 선술집은 브릴의 남동쪽 가장자리에 있다네."
rows["119:85647355"]="얼음송곳니는 수많은 전장을 나와 함께 누볐지.$b$b갑옷이 없다고 얼음송곳니를 과소평가하지 마라. 내가 아는 가장 강한 곰이니까."
rows["119:893765992"]="우리 아름다운 도시에서 우편 상자가 풍부합니다. 로얄 거래소 은행에 있는 상자는 확실히 여러분의 필요에 적합합니다."
rows["119:922048211"]="물론, 이 칼바위 언덕에 광부 하나쯤은 살고 있지. 북서쪽 여관 옆에서 크룬을 찾아보게."
rows["119:969443596"]="서부 프로스트울프 타워는 프로스트울프 마을과 프로스트울프 케이프 사이의 게이트를 보호합니다.$B$B호드에 의해 통제됩니다."
rows["11:1260156794"]="당연하지!"
rows["11:1635349730"]="좀 바쁜데요."
rows["11:1732890226"]="나무가 됐어요!"
rows["11:367414079"]="저는 파이가 세상에서 제일 좋아요."
rows["11:577082516"]="안녕하시오!"
rows["11:592363260"]="뭘 도와드릴까요?"
rows["11:819267740"]="뭐죠?"
rows["120:1123484184"]="안녕하시오. 나는 기억력의 대가인 크로노스라고 하오. 내 기억력은 완벽해서 아무리 사소한 것이라도 모두 정확하게 기억한다오.$B$B믿어도 좋소이다."
rows["120:1143626164"]="나는 우르속의 딸, 코디안이다. 한때는 성스러웠던 이 제단을 보살피고 있지.$B$B여기까지 온 이방인은 아주 오랜만에 보는구나."
rows["120:1179086228"]="엄청난 규모의 지진이 일어난 후, 당신이 가장 원하는 곳은 실내에서야 한다고 생각하겠죠?"
rows["120:122777695"]="지옥방울이라는 이름은 사악한 마법 오염에서 따온 것이오. 서쪽에 있는 나지비안 사티로스 야영지에서 지옥방울버섯을 찾아보시오."
rows["120:1470242144"]="서 있는 모습만 봐도 전사가 아닌 걸 알겠군.$B$B저리 가서 좀 더 안전한 일이나 독서를 하는 게 어떻겠소?"
rows["120:1531400649"]="저는 이 아이디어를 가지고 있습니다. 이번에는 해군 전투를 겪지 않도록 해 얼라이언스 그리고 호드.$B$B그냥 말만 하고 있어요"
rows["120:1579086114"]="명예로운 자여, 장로의 봉우리에 있는 장로의 전당에서 투락 룬토템과 다른 드루이드들이 당신을 기다리고 있습니다."
rows["120:1587758748"]="스톰윈드로 가보시는 게 나을 것 같군요. 그곳에 도착하시면 경비병에게 다시 한번 물어보십시오. 친절하게 가르쳐 줄 겁니다."
rows["120:1691719270"]="안녕하시오, 난 여행 중인 빛의 성기사 구원자 팔란나르라고 하오. 이 잿빛 골짜기엔 나이트 엘프들을 도우러 왔소이다."
rows["120:1703155615"]="이 땅의 영혼은 생명을 제물로 바치는 잔혹함과 어둠의 주술을 더는 용납하지 않을 겁니다.$B$B썩은가지 부족은 반드시 처단해야 합니다!"
rows["120:1723292095"]="지금 썬더 블러프 바로 남서쪽 멀고어 황금빛 초원에서 다크문 축제가 열리고 있습니다. 꼭 구경 가세요!"
rows["120:1830229136"]="달라란 북동쪽에 마법 동물원이 있습니다. 소환수용품, 희귀 탈것과 야수 관리인이 모두 그곳에 있답니다."
rows["120:1924627320"]="도적을 찾으시나요? 잔노크 말씀이로군요. 돌라나르 여관으로 가보십시오."
rows["120:1978712081"]="고블린이었든 아니든, 좀비란 성스러운 빛이 보기에는 혐오스러운 존재일 뿐이에요. 게다가, 그놈들에게선 한 푼도 안 나오거든요.$B$B지금까지는 나온 게 없어요."
rows["120:198287203"]="사악한 갱클리 로튼피스트가 벌을 받아서 정말 기뻐요! 해럴드에게 줄 가죽이 필요하시다면 제게 많이 있답니다."
rows["120:215624581"]="이 거울은 스칼로맨스의 바로브 가가 더 이상 자신들이 소유하지 않는 영혼들을 비춰 보는 데 사용되는 아주 귀중한 유품이다."
rows["120:247058874"]="이 세상에 집에서 갓 구운, 따뜻하고 바삭바삭한 체리 파이만큼 맛있는 게 또 있을까요?!"
rows["120:25226329"]="탐험가 연맹에 잘 왔네. 정보를 찾고 있는 거라면 내가 도와 줄 수 있을지도 모르지. 난 책에는 빠삭하니까."
rows["120:303077696"]="망가진 기계의 선체에서 재활용할 수 있는 부품 몇 개를 찾았습니다. 한 개의 부품만 가져갈 수 있을 것 같습니다."
rows["120:325015411"]="파도가 치고, 햇살이 비치는 이곳에서도 어딘가 도사리는 어둠의 기운이 느껴지는군.$b$b참 흥미롭기도 하지. 안 그렇소?"
rows["120:333109280"]="크러쉬코그의 패배는 그의 주인인 텔마플러그에게 엄청난 충격을 안겨줄 것이네. 놈리건의 노움들은 절대로 멈추지 않을 거야!"
rows["120:368687307"]="여어, 친구. 필요한 물건을 조금만 구하면 당장에라도 자넬 치료해 줄 수 있을 텐데!"
rows["120:414163006"]="로키루스 베인스필러는 알케미아 홀의 열린 입에서 래스맨 테라스의  ⁇ 에  ⁇ 을 기다리고 있습니다."
rows["120:53555433"]="스컬지들의 발을 철저하게 묶어둬야 하네! 수상한 움직임이 보이면 모두 보고하게. 먼저 처치하고, 질문은 나중에 하는 거야!"
rows["120:62569351"]="이봐, 친구. 자네하고 거래를 할 수 있었으면 좋겠어. 정말로 말이야. 하지만 먼저 자네가 빌지워터 무역회사와 확고한 관계가 되어야 할 거야."
rows["120:655363940"]="이 서판에는 고대의 상형 문자와 무시무시한 힘을 지닌 주문이 새겨져 있습니다. 하지만 당신은 아무리 살펴봐도 그 의미를 알아낼 수가 없습니다."
rows["120:705116028"]="랩터들을 조심하십시오. 아주 아주 똑똑하니까요.$B$B지난주에는 세 번째 놈이 나를 막대기로 때리는 동안 두 놈이 무리를 지어 도망가더라니까요."
rows["120:750447413"]="다시 썬더 블러프로 날아가려면 저 같은 일을 하는 타우렌, 분덴 플레인즈윈드와 대화를 하십시오."
rows["120:759708508"]="주문각인 숙련자를 찾고 있나? 이런 외딴곳에는 없으니 가까운 대도시로 가보는 게 좋겠군.\013\010"
rows["120:777705780"]="와일드해머의 고향, 맹금의 봉우리에 오신 것을 환영합니다.$b$b고위 영주 폴스타트 님이 아이언포지에 가 계시니 저와 일하셔야 할 거예요."
rows["120:895126947"]="하라아즈 펠스카르는 상인의 층에 있는 사냥꾼들의 성당의 테라스로 올라와"
rows["120:90098456"]="정복 섬은 우리가 침입할 수 없는 귀중한 자원들로 가득 차 있습니다 호드 - 전투에 참여하겠어?"
rows["121:1001295290"]="넌 강령술사, 그리고 난 너의 쓸모없는 육신에서 그들을 해방하지 않으면 뼈의 힘을 결코 이해하지 못할거야."
rows["121:1049243708"]="다크월 페어 이제 오픈!$b$b작은 수수료로 전장 무대까지 이동할 수 있어요$b$b- 갈래?"
rows["121:1099115484"]="나렛과 브랜트 자스퍼블룸은 작은 가게에서 화학과 식물학을 가르치고 있어, 그들은 당신을 도울 수 있을 겁니다."
rows["121:1129360545"]="에르마가 여기 동물들을 돌봐요, 라이온 프라이드 인 앞에서요"
rows["121:1164990400"]="적막한 해안에 있는 얼라이언스가 전멸하는 것은 시간문제입니다. 포위당한데다 수적으로도 열세니까요."
rows["121:1165900142"]="목숨을 잃게 된 것은 어쩔 수 없는 현실로 받아들였소. 하지만, 이시다를 잃는다는 것은 죽고 난 후에도 도저히 견딜 수 없는 일이외다."
rows["121:1179025817"]="당신에게 함유된 흑마법 소질을 측정해보니, 그 분량이 충분하지 않군요. 제가 더 이상 얘기를 나눌 이유가 없어요. 이만 가보세요."
rows["121:1213986364"]="이 여관은 북쪽의 야만인들이 깨어나기 전에 세워졌죠. 적어도 그거 하나는 다행이랍니다!$B$B오래 묵어가시나요?"
rows["121:1286070123"]="자유연합 추적장치를 다시 따라나갈 수가 없습니다. 가는 길에 살덩이괴물이 너무 많아요. 구조대를 보내 주십시오... 추적장치를 따라오면 됩니다... 이상!"
rows["121:1417306371"]="<이세라의 몸은 당신의 눈앞에 있지만, 그녀의 의식은 이 세상과 다른 세상을 오가는 것 같습니다.>"
rows["121:1507327282"]="전투의 흉터는 위험한 곳이군요. 제아무리 튼튼한 장비도 증기 전차가 대지에 휩쓸리는 걸 막아낼 도리는 없으니까요."
rows["121:1552518980"]="이 야만스러운 놈들이 제가 잠시 없는 틈에 우리 마을을 공격했습니다! 와일드해머의 심판이 어떤 것인지 보여 주겠어요. 아주 똑똑히!"
rows["121:1590649844"]="당신에게 필요한 교육이 거의 다 끝나가는군요. 이제 모든 노력의 완성과 당신 사이에는 마지막 임무 하나만이 남아 있을 뿐이랍니다."
rows["121:1609167419"]="도끼를 제대로 사용하고 싶으면 적당한 인사도 해줘야 하는 법이지. 농담이 아냐. 날 한번 따라해 보게. \"안녕! 내 작은 친구야? 오늘은 뭘 베고 싶니?!\""
rows["121:1677778076"]="칼바위 언덕 동쪽에 있는 병영 안에서 타쇼 재기드스카를 찾아보게. 호드의 젊은이들에게 자부심과 명예를 가져다주기를!"
rows["121:175774399"]="이놈들은 분명히 우리 배를 습격한 놈들이오. 하지만 사라진 내 동료를 찾을 수가 없군. 그들을 어디로 데려갔을까?"
rows["121:1784349151"]="우리 동족은 나를 배신자로 알고 있네. 일리단의 충견으로... 당분간은 그렇게 알고 있는 편이 제일 좋겠지."
rows["121:1786935089"]="봉우리 중간층에 있는 돈스트라이더의 마법부여점을 찾아가 보시기 바랍니다. 테그가 기꺼이 도와줄 겁니다."
rows["121:1828956721"]="크라서스 착륙장은 달라란의 가장 동쪽에 있습니다.$B$B달라란 비행 조련사와 극지 비행 교관도 착륙장에서 만날 수 있답니다."
rows["121:1833550570"]="제가 했던 일은 그다지 큰일도 아닙니다. 발끝에도 못 미치죠. 이 대격변이 아마도 우리에게 일어났던 일 중 가장 멋진 일이 아닐까 싶습니다!"
rows["121:1860829104"]="이방인이여, 달라란에서는 달라란의 법을 존중해 주시기 바랍니다.$B$B길을 잃으셨나요? 제가 도와드릴 일이 있을까요?"
rows["121:1948671362"]="실버문에서 달 축제 행사를 하는 사람들을 발견한다면, 그들은 당신을 무롱라데로 데려가 기념식에 참여 할 수 있습니다."
rows["121:1972468515"]="마법 재연마사를 찾는다면, 마법사 지구 바로 밖에 있는 마법부여 가게 안에서 명가의 마법사가 있을 겁니다."
rows["121:312211362"]="로서의 후예들은 끊임없이 전쟁을 치러왔네. 그런데도 우리 장비가 예전처럼 깨끗한 상태라니 정말 놀랍단 말이야!"
rows["121:31601498"]="이봐요, 잠시만요!$b$b아는 건 다 이야기해 드리겠습니다! 먼저 이 야만인이랑 녀석들이 키우는 식인 곰한테서 좀 구해달라고요.$b$b어떻습니까?"
rows["121:323270890"]="작아질 준비가 되셨나요? 약간 따끔하고 뜨거울 거예요. 고통과 경련은 금방 사라질 테니 걱정 마시고요."
rows["121:36353868"]="안녕하세요. 여명의 설원에는 무슨 일이신가요? 이 춥고 광활한 땅은 정말 황량하지만, 정말로 많은 비밀이 숨어 있답니다."
rows["121:37286263"]="방어구와 무기를 제작하는 크라두 그림블레이드와 줄라 슬래그퓨리는 고난의 거리의 대용광로에서 일을 하고 있으니 그리로 가보십시오."
rows["121:377489727"]="일리타라 스카이렌더는 경매당 앞에 있는 왕립 거래소 정원 광장에서 하늘을 볼 수 있습니다."
rows["121:402810371"]="우리 잔달라 트롤은 현재 이 세계에 닥친 위협을 못 본체 할 수 없어 머나먼 섬에서 이곳으로 건너왔네."
rows["121:536016754"]="폭발물 애호가들에 의해 발견된, 폭발물 애호가들을 위한, 그림 같은 점화등 바닷가마을에 온 걸 환영해, 친구."
rows["121:675204078"]="미알은 엑소다르의 수석 대장장이랍니다. 그녀는 교역 지구의 아래층에 있으니 그리로 가 보십시오. 성스러운 빛이 함께하기를."
rows["121:744911335"]="흐음... 이 근처에는 없고, 제가 아는 마법부여사라면 스톰윈드에서 일하는 이밖에 없습니다. 스톰윈드로 가서 경비병에게 다시 한번 물어보시는 게 어떻겠습니까?"
rows["121:825308743"]="얼마나 많은 배신자 녀석들이 우리 사이에 숨어 있을지 의심스럽군. 저 노움 녀석을 알아온 지 수년이 넘었지만 녀석이 배신자일 거라는 상상은 전혀 못했소이다."
rows["121:84982327"]="이제 혼자서도 요새로 돌아갈 수 있소. 당신이 시간을 벌어 주었으니 여기서 몰래 빠져나갈 수 있을 거요. 뉘신지는 잘 모르겠지만 어쨌든 고맙소이다. 언제나 엘룬의 축복이 함께하기를!"
rows["121:883091977"]="난 구출될 필요가 없네. 그리고 무슨 일이 있어도 너 같은 누더기골렘 따위에게 구출되지 않을 거야!"
rows["121:94281498"]="저 슈노츠라는 친구에게 투자한 것이 현명했음이 드러나고 있습니다.$b$b이 사업에 초창기부터 참가했던 일이 얼마나 다행인지 모르겠군요."
rows["121:974405209"]="대여사제와 대화해 보셨소? 그분께서 당신의 관점에서 본 성지 순례에 대해 무척 듣고 싶어하신다오."
rows["121:986843813"]="이 시체는 오크 여전사의 것입니다.$B$B전사한 것이 분명한데, 아마도 이 부근의 가시멧돼지와 싸우다 죽었나 봅니다."
rows["122:1074294629"]="얼마 전에 유물을 잔뜩 배에 싣고 있는 모습을 봤습니다.$b$b그렇게 많은 황금을 한번에 본 일은 처음이었어요!"
rows["122:1078428321"]="죄송해요, 위습이나 선장님께 제가 찾아낸 내용을 보고하는 것 말고 다른 사람과 얘기할 짬이 전혀 없네요. 이해해 주세요."
rows["122:1164694073"]="대족장님이 주도하고 계시는 개혁의 바람은 분명 호드에게 승리를 안겨 줄 거야! 참, 주술사라고? 마을 동쪽에 있는 병영 안에서 스워트를 찾게."
rows["122:121138351"]="다크문 축제는 엘윈 숲에서 열릴 예정입니다. 다크문 유랑단이 황금골 바로 남쪽에서 여러분을 맞이할 겁니다!"
rows["122:1385107711"]="안녕하세요. 제 상점에 오신 걸 환영해요.$B$B어유, 참 멋지시네요! 하지만 모습을 좀 바꿔보실 생각이라면, 아무 의자에나 그냥 앉으시면 된답니다."
rows["122:1392309675"]="파수꾼을 데리고 나갈 준비가 되면 말씀해 주십시오.$B$B그리고 제게 유휴 병력이 조금 더 있으니 필요하다면 다시 돌아오시기 바랍니다."
rows["122:1481703393"]="길니아스 전투가 한창입니다! 최전선으로 가거나 우리 병사들이 다음 공격을 위해 재정비할 때까지 기다리십시오."
rows["122:1514310052"]="이것이 거대한 비 바위다. 안전하게 지키고 반짝이들을 가져다주면, 우리를 보살펴준다.$B$B혹시 바위에 바칠 반짝이 더 있나?"
rows["122:1548237386"]="그롬골에서 언더시티로 가는 여행은 참 아름답습니다. 조금 지루하긴 해도 말입니다. 그렇다고 근무중에 잠들 수야 없지요."
rows["122:174610254"]="이 감시초소엔 요리사가 없습니다. 그런데 이상한 것은... 남풍에 좋은 냄새가 실려온다는 거랍니다. 냄새가 나는 방향으로 가 보는 게 어떻습니까?"
rows["122:1795114365"]="이야호!$b$b언젠가 한 번 더 해봐야겠소!$b$b자, 나는 연구를 하러 가봐야겠소. 준비되면 다시 얘기하리다."
rows["122:1891820563"]="여기 대장장이는 무기 수요가 가장 많은 군사 지구에서 일하더군. 군사 지구 내곽으로 가보게."
rows["122:2013316382"]="돌난로 무덤은 투쟁의 벌판에 있는 돌난로 전초기지 동쪽에 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다."
rows["122:210171959"]="물건을 보관할 곳을 찾으신다고요? 그렇다면 엑소다르에서 안전한 은행으로 가셔서 은행원에게 도움을 받으시기 바랍니다."
rows["122:2104625946"]="<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B당신이 고기로 요리를 만든다는 게 사실인가요? 궁금하네요."
rows["122:232460987"]="벨라도르미는 달의 성전의 서쪽 기둥으로 달아있는 중성 고고학자 그레이위스커 근처에 있습니다."
rows["122:260860109"]="여분의 보급품이 있긴 하지만 많지는 않소. 투쟁의 벌판으로 지상 공격 부대를 보낼 수 있으려면 훨씬 더 많이 필요하다오."
rows["122:268770857"]="다크문 축제는 멀고어에서 열릴 예정입니다. 썬더 블러프 바로 남서쪽에 여러분을 맞이할 겁니다!"
rows["122:290561172"]="고위집행관 워로스께서 확인 후 보상 지급 예정.$B$B신중하게 생각한 후 문의할 것.$B$B쓸데없는 방문 사절!"
rows["122:360604040"]="아무 일도 일어나지 않습니다. 역병 가마솥의 내용물이 엉망이 되었을 수는 있지만, 눈으로 확인할 수는 없습니다. 어떻게 할까요?"
rows["122:361801575"]="왜 그런지 모르겠어요 포세이큰 하로우의 끝에서 진짜가 아닌 매 밤 빗자루를 태워버리는데,"
rows["122:44299450"]="칼바위 언덕에 전문 기계공학자가 한 명 있지. 머크드락이라고 하는데, 보통 가열로 근처에 볼 수 있다네."
rows["122:489778212"]="둘로 갈라졌지만 모이면 하나가 되지요. 이 쌍둥이 검은 줄파락에 묶여 있습니다.$B$B이 두 검을 찾으면 술트라제가 부활할 것입니다."
rows["122:651259981"]="잔디와 질아야는 골짜기의 가운데 있는 건물 북쪽에서 일합니다.$B$B필요한 일이 무엇이든 간에 도움을 받을 수 있습니다."
rows["122:753845624"]="시체를 조사한 당신은 실패로 끝난 데솔름 공격 작전을 지휘했던 혈기사 돈스타가 틀림없다는 결론을 내립니다."
rows["122:830681051"]="루칸 코르델은 스톰윈드 지하감옥 근처 대운하 가장자리에 작은 상점을 하나 운영하고 있습니다. 장담하건대 그라면 마법부여의 경지가 무엇인지 보여줄 겁니다."
rows["122:92716337"]="우리는 황혼의 망치단에게서 관문을 빼앗았소. 용들이 기회를 제공해 줬다고 할 수 있지. 이 기회를 헛되이 하지 않도록 애써야 하오."
rows["122:95229711"]="정기의 봉우리에 있는 정기의 전당은 주술사에게는 집과 같은 곳입니다. 그곳으로 가시면 훌륭한 주술사들을 만나실 수 있을 겁니다. 선조님의 보살핌이 있으시길."
rows["122:954948131"]="수없이 많은 나가를 처리하였지만 놈들은 아직도 몰려오고 있습니다. 이 처참한 동굴에서 빠져나가려면 어찌해야 하겠습니까?"
rows["123:1038135749"]="그 친구들과 여행한 지는 얼마 되지 않았지만, 벌써 둘 중 하나라도 없으면 여행길이 어떨지 상상할 수도 없네요."
rows["123:107692112"]="그럴리가요!$b$b내 말은, 물론 내 전재산이 여기 달렸긴 하지요... 그리고 솔직히 사람들이 동요한다고 해서 무슨 도움이 되겠습니까?"
rows["123:1077972470"]="찬란한 빛이 당신의 길을 비추고 이끌어 주기를 바랍니다. 이쪽에 있을 테니 구경하시다가 도움이 필요하시면 부르시기 바랍니다."
rows["123:1100076560"]="수정으로 지어진 이 구조물은 마력으로 가득합니다. 눈앞에 이상한 문양의 환영이 나타나더니 빠른 속도로 연속해서 두루마리 모양이 됩니다."
rows["123:1178528340"]="저희는 사회의 그늘에서 움직이는 존재입니다만, 여기 최전선에서는 누구나 저희의 힘을 존중할 수밖에 없죠."
rows["123:1202430080"]="맹세하네... 퀸트가 내게 또 다른 낚시 먹이를 심으려 한다면, 난 내 썩지 않은 칼로 그 나무를 잘라내게 될거야."
rows["123:1496755091"]="드루이드의 길을 걷는 한 타우렌 여성이 실버문에 야영지를 차렸으니 그리로 가보시오. 지금도 그곳에서 분명히 풀을 뜯고 있을 거요."
rows["123:1518190352"]="우리는 은빛십자군 형제들과 나란히 명예, 명성 그리고 스컬지와 싸워야만 하는 정당성을 얻고자 경쟁을 시작했답니다."
rows["123:1579915682"]="솔직히, 이곳에는 우리가 역병지대에서 경험했던 것보다 훨씬 끔찍한 공포가 떠돌고 있지.$b$b게다가 스컬지는 그 어느 때보다도 강력한 상태라네."
rows["123:1657983558"]="이 섬을 가르는 물속에서 찾아보시오. 하지만, 고린뿔작살광포어는 강물 속에 서식한다는 사실을 명심하고 숨을 크게 들이마시는 게 좋을 거요."
rows["123:1662603774"]="마차 안의 어떤 물건이든 마음 놓고 사용하세요. 우리가 쓰는 물건만 아니라면 언제든 빌려 가셔도 좋아요."
rows["123:1708837041"]="라이트워든 모랄라가 템플러스들에게 빛의 백관에서 빛."
rows["123:1727668629"]="놈들의 지도자는 여기서 모든 이교도에게 명령을 내린다오. 녀석이 곧 모습을 드러낼 거요.$B$B절대로 이 기회를 놓쳐서는 안 되오."
rows["123:1744945594"]="성소를 차지하는 데 성공했어요. 파수병을 계속 우리 것으로 개조해서 다른 전략 요충지에 경비병으로 배치할 수 있을 거예요."
rows["123:1867774702"]="우리는 여전히 움직임을 거쳐가고 있지만, 겨울 베일 축제는 이제 빈 느낌입니다. 오그리마 그들은 진정한 축제를 가지고 있습니다."
rows["123:1869997121"]="켈투자드가 수호자의 지팡이인 전설의 아티쉬를 찾고 있다고 합니다.$B$B그렇습니다, 메디브가 지니고 있던 바로 그 지팡이랍니다."
rows["123:1894992944"]="찬란한 빛이 당신의 길을 비추고 이끌어 주기를 바랍니다. 이쪽에 있을 테니 구경하시다가 도움이 필요한 게 있으면 부르도록 하십시오."
rows["123:243038092"]="정복의 섬엔 얼라이언스 손에 넘겨줄 수 없는 귀중한 자원이 가득하네. 자네도 함께 싸우겠나?"
rows["123:369206311"]="너무 외로워요. 이 근처에 제 또래 친구들이 더 많았으면 좋겠어요. 어떤 때는 샤트라스 고아원 시절이 그립답니다."
rows["123:389902106"]="여기까지는 참고 기다렸어. 하지만, 그 로켓 투척기를 빨리 정상적으로 움직이게 하지 않으면 누군가에게 어둠의 화살을 날릴 거야!"
rows["123:398058016"]="무거운 금속 포탄이 온통 식용유 범벅이 되었습니다. 피랠론의 해적들이 이걸 옮기려면 꽤 골치 아플 겁니다."
rows["123:419256538"]="다음 경주에서는 노움의 차를 날려버릴 거라고 그러더군요! 농담이든 진담이든 간에 나 같으면 멀찌감치 떨어져 있을 거예요."
rows["123:447434757"]="스톰윈드 동쪽에 있는 언덕에서 약초채집가 하나가 연금술사와 함께 살고 있습니다. 둘이 같이 살다니 아주 궁합이 잘 맞지 않습니까?"
rows["123:477341939"]="당신에게 필요한 교육이 거의 다 끝나가는군요. 이제 모든 노력의 완성과 당신 사이에는 마지막 임무 하나만이 남아 있을 뿐이랍니다."
rows["123:520276119"]="밤이고 낮이고 제가 하는 일은 여기 앉아서 탄약을 만들고 석궁 활줄을 고치는 겁니다.$B$B제게 맡길 일이 있으신 것 같습니다만?"
rows["123:566244573"]="바람과 나무가 보이지 않는 위험을 알려주는군요. 이 대지는 겉으로는 건강해 보이지만, 눈이 닿지 않는 곳에서는 다른 일이 일어나고 있어요."
rows["123:627170923"]="안녕하신가! 바로 당신 같은 이를 찾고 있었지. 자, 앉아서 잘 들어보라고. 우리 둘 다 떼부자가 될 수 있는 계획이 있으니까 말이야!"
rows["123:650008610"]="나에게 배울 준비가 된 이를 돌려보내는 일은 절대로 없소만, 유감스럽게도 자네는 그런 사람이 아닐세! 아직 배워야 할 게 많이 남아 있단 말일세!"
rows["123:785352939"]="은행은 성문의 북서쪽 상업 지구에 있습니다. 지도를 통해 위치를 알려드리겠습니다."
rows["123:788550951"]="서리늑대 무덤은 서리늑대 마을에서 북쪽으로 그리 멀리 떨어지지 않은 길가에 있습니다.$B$B현재 호드가 점령하고 있습니다."
rows["123:805340328"]="대성당 광장에 있는 빛의 대성당은 스톰윈드 사제들에게 안식처와 같은 곳이랍니다. 그곳에서 대여사제 로레나 님을 만나보도록 하십시오."
rows["123:893210555"]="걸어 다니는 시체도 때로 수선해 줘야지. 메리 에드라스가 그쪽 일을 담당하네. 도적 지구 내곽으로 가보게."
rows["124:1053216545"]="맹금의 봉우리에 있는 와일드해머 드워프들도 빠른 그리핀들을 가지고 있긴 하지만 과연 그 그리핀들이 대용광로의 열기를 견뎌낼 수 있을까요? 어림도 없죠!"
rows["124:1118466552"]="모아키 항구에는 거북배가 둘 있습니다. 파도의 여행자호와 초록섬호라고 하는데, 우누페와 카마구아를 오가는 녀석들이지요."
rows["124:114603406"]="사제의 지식을 원한다면 포나리스를 찾아가십시오. 델라니엘의 여관 2층에서 다른 이들과 사제로서 소임을 다하고 있습니다."
rows["124:1160821647"]="자유연합 추적장치를 다시 따라나갈 수가 없습니다. 가는 길에 살덩이괴물이 너무 많아요. 구조대를 보내 주십시오... 추적장치를 따라오면 됩니다... 이상!"
rows["124:1191958356"]="어디 제 도움이 필요한 꼬꼬마 동물 친구들 없나요?$B$B<동물을 생각하며 두 눈을 반짝이는 마일룬>$B$B지금 당장 토끼를 꼭 껴안아 주고 싶어요!"
rows["124:1206874028"]="아, 돌아온 것을 환영하오, 영웅이여. 다시 한 번 수호자를 지키기 위해 돌아온 것이오? 시간의 봉화를 가져가는 걸 잊지 마시오!"
rows["124:1274359182"]="부대장님께서 병력을 이끌고 그대가 전에 정찰했던 기지 하나를 공격하러 가셨습니다. 그곳으로 가서 부대장님을 만나십시오."
rows["124:1285961555"]="내 이름이 낯익지 않나요? 어쩌면 우린 오래전에 알고 지냈을지도 몰라요...$B$B내 이름은 아주 중요한 인물의 이름을 딴 것 같은데..."
rows["124:1289739127"]="자, 스자보의 솜씨를 좀 보세요. 작품이 따로 없죠!$B$B당신은 이런 옷에 썩 어울리진 않지만 스자보는 돈이 필요하니까요. <한숨을 쉬는 스자보>"
rows["124:1335210575"]="자, 시작해 볼까요! 첫 번째 소절은 사랑스러운 패니에 대한 건데, 왠지 조화롭게 만들 수가 없군요.$B$B\"두 눈\"과 운이 맞는 단어 생각나세요?"
rows["124:147613901"]="제독과 그의 병력들은 이전에 당신이 정찰갔었던 기지를 차지하기 위해 돌격해 나갔습니다. 가서 그들을 만나는 게 좋겠습니다."
rows["124:1491255281"]="스톰파이크 무덤은 던 발다르의 동쪽 다리 건너에 있으며 산을 앞뒤로 만나고 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다."
rows["124:1538429501"]="등에 들고 있는 검은 애쉬브링거라고 불립니다."
rows["124:1538941423"]="탐험가 연맹의 회원으로 오랜 세월을 보내면서 나는 아제로스 전역을 여행했지요. 그러나 핏빛안개 섬과 같은 건 본 적이 없습니다."
rows["124:1547599199"]="저희는 생존자들을 여기로 모아 오염을 제거한답니다. 오염만 제거하면 지상으로 나가는 건 금방이라고요!"
rows["124:1672998846"]="자네는 지금 비전 마법의 대가와 마주한 걸세. 나에게 도전한다면 현명하지 못한 자겠지. 내가 지나온 자리는 불길에 휩싸인 시체만이 남을 뿐이니 말일세."
rows["124:1732317851"]="당신은 아직 나에게 가르침을 받을 수 있는 권리를 얻지 못했어요. 저쪽 탁자 옆에 있는 선드부터 먼저 만나 보시죠. 그가 당신더러 준비가 됐다고 하거든 다시 날 찾아오시고요."
rows["124:1848234881"]="여기 상황은 생각보다 더 끔찍해요! 비행선은 배배 꼬인 금속이랑 불타는 연료를 뭉쳐 놓은 꼴이 돼버렸다고요!"
rows["124:1921112740"]="이 대포는 해안가를 향하고 있습니다. 갓 넣은 화약과 기폭 장치도 준비되어 있습니다.$B$B정말 편리하군요!"
rows["124:1926460913"]="이 부근에 그런 일을 하는 자는 없네. 북쪽에 있는 오그리마에는 있을지도 모르지. 그곳 그런트에게 물어보는 게 제일 좋겠군."
rows["124:194221708"]="그렇다면, 밤의 사나이 오스본을 만나 보셔야겠습니다. 스톰윈드에서 그보다 더 은신에 능숙한 선생은 없답니다. 구 시가지에 가시면 그를 만날 수 있을 겁니다."
rows["124:2031258533"]="세나리온의 드루이드들은 나가와 사악한 그 잃어버린 드레나이로부터 나를 지켜줬소. 그 보답으로 난 드루이드들에게 습지대의 동식물에 대해 가르침을 주고 있소."
rows["124:2110105735"]="강인한 신체와 영혼이 조화를 이뤘을 때 최강의 전사로 다시 태어나게 되는 것입니다! 사냥꾼의 전당에서 사크 레이지토템을 찾아가 전사로서의 당신의 새로운 운명을 발견하십시오."
rows["124:211122067"]="시체의 옷과 장비를 뒤져서 전투와 오염된 환경에 손상되지 않은 휘장을 찾아냅니다."
rows["124:2130386507"]="빠르게 치고 사라지게나. 다른 이들은 자네 이름을 모르지만, 자네의 행적에 대해서는 알게 될 때가 자네가 기술에 통달하기 시작하는 때라는 걸 알게 될 걸세."
rows["124:21655056"]="<그분은 더 가까이 다가옵니다.>$B$B우리 둘 사이에, 이 밤 중 하나를  ⁇ 어내려고 생각 중이야"
rows["124:258503199"]="오랜 시간이 걸리지만 그만한 보람이 있는 일이지요. 상인의 정원에 있는 아스타이아와 얘기를 나눠 보시면 뭔가 쓸 만한 걸 배울 수 있을 겁니다."
rows["124:301309840"]="냉기 돌풍에 오신 걸 환영해요! 어디에서도 찾아볼 수 없는 독특한 아이스크림을 맛보세요! 스톰윈드 최고의 수습 마법사들이 주문받은 바로 그 자리에서 얼려 드립니다!"
rows["124:32556744"]="카엘 다로우에서는 배회, 시비, 욕, 싸움 등 당신이 일으키려는 모든 소동은 용납되지 않습니다."
rows["124:370439223"]="시체의 옷과 장비를 뒤져서 전투와 오염된 환경에 손상되지 않은 휘장을 찾아냅니다."
rows["124:462509235"]="돌주먹 일족 배고프다! 먹을 것 필요하다! 전쟁망치 일족이 돌주먹 일족 산에서 북쪽으로 내쫓았다. 지금 많은 돌주먹 일족 굶주린다."
rows["124:501556554"]="당신도 리치 왕에게 자신을 증명이라 하러 오셨나요?$B$B이건 참 옛날 방식이잖아요. 안 그래요? 싸우고 살아남으라니 말이에요."
rows["124:514184205"]="여보세요! 내가 당신을 알던가요?$b$b아, 맞아요. 프리그몬은 얼굴을 잊지 않는답니다.$b$b당신... 날 쫓아오는 건가요? 뭔지 모르지만, 이 프리그몬은 하지 않았어요!"
rows["124:51423590"]="제가 할 수 있는 대로 모두 가르쳐 드리지요. 각 수업은 엘룬께서 내리시는 선물이랍니다. 엘룬께서 내려주신 선물을 지혜롭게 사용하면 실패하는 일이 없을 거예요."
rows["124:607993636"]="<눈앞에 나타난 이세라의 환영이 마치 꿈에서처럼 흔들립니다. 주위에 이 환영을 볼 수 있는 자는 없지만, 환영은 당신의 존재를 인지하고 있습니다.>"
rows["124:836213458"]="오늘 밤 우리 모두 국경에서 스컬지와 벌어지는 전투를 구경하러 간대요. 정말 재미있는 일이죠?!"
rows["124:865984290"]="조세타라면 새로운 주문 몇 가지 정도는 기꺼이 가르쳐 줄 겁니다. 아마 지금쯤 사자무리 여관에 있는 자기 방 안에 있을 겁니다."
rows["124:872430172"]="제가 드릴 수 있는 건 없습니다.$B$B하지만 헤그리드가 황혼의 보급품을 모아 아군에 지급하고 있습니다. 그녀와 이야기해 보십시오."
rows["124:873993377"]="<고개를 젓는 잊혀진 보병>$B$B더는 버틸 수가 없소. 아서스 왕자님이 빨리 돌아오시지 않으면 우린 모두 죽을 거요."
rows["125:1037806986"]="여기까지 와서 뭐하시는 거죠? 스트라솔름으로 당장 돌아가셔야 해요!$B$B제가 스트라솔름으로 순간이동시켜 드릴까요?"
rows["125:1118617400"]="조르지오 볼레로는 스톰윈드에서 가장 훌륭한 재봉사 중 하나랍니다. 그는 마법사 지구에 있는 던컨의 옷가게에서 근무하고 있으니 그곳으로 가보시기 바랍니다."
rows["125:1136460151"]="<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B안녕하세요. 전 최근에 알에서 태어났습니다. 당신은 어디서 태어나셨나요?"
rows["125:1158911705"]="남쪽에 있는 검은창 해안에서 라우티키라는 트롤이 낚시를 하는 걸 본 적 있네. 센진 마을 바로 외곽에 있지."
rows["125:1274302984"]="엄청나게 간단한 임무였습니다. 크라즈작업장 상자 비행장을 설치하고, 평소 하던 조사 작업을 계속하는 거지요.$B$B그런데 왜 제 주변엔 멍청이만 있는 거냐고요!"
rows["125:133589428"]="조용히 조심스럽게 말해주세요. 잘못된 말이 여러분의 목을 잘라낼 수 있습니다."
rows["125:1396570797"]="거점 보초탑은 남쪽의 호드 영토와 투쟁의 벌판 사이에 통로를 확보하고 있습니다.$B$B현재 호드가 점령하고 있습니다."
rows["125:142704921"]="어서 오세요! 쑥스러워하지 마시고요.$b$b자, 제 자랑이자 기쁨인... 블라스텐하이머 5000 초특급 대포를 소개합니다! 정말 멋지지 않나요?"
rows["125:1472477680"]="당신이 기계 장치, 장식품, 아무개, 소형 부품, 무언가, 거시기나 그거이를 찾고 계신다면, 제대로 오신 겁니다!"
rows["125:1559201514"]="꽃이라고? 이런 황무지에서 말인가? 그런 걸 찾는 법을 가르쳐 줄 이가 호드에 있으려나? 아, 남쪽에 있는 센진 마을로 한번 가보게. 미시키라면 뭔가 알 거야."
rows["125:1615730019"]="저는 여기 서서 가끔 호수 뒤편의 숲을 바라보곤 하는데 그럴 때면 대지도... 한때 생명으로 가득한 녹색이었다는 사실을 문득 깨닫고는 하죠."
rows["125:1622105170"]="자, 어떻게 하는지 보라고요. 스자보는 마술도 한다니까요?$B$B<한숨짓는 스자보>$B$B네, 네. 스자보가 당신에게 해줄 것이 있어요."
rows["125:1730251551"]="그럼, 여기서 무슨 일이 벌어지고 있을까요? $T 민간인: 민간인? 그건 귀여워진 게 아니냐?"
rows["125:173084518"]="여기서 뭐하고 있어? 이 죽은 가족의 먼지를 더 더 더 더 더 더 더 더 더 더 더 더 오염시키고 싶니? 이 곳을 떠나라."
rows["125:1781791383"]="내가 들은 얘기가 정확하다면 그대가 이미 실바나르를 위해 좋은 일을 했더군.$B$B계속 힘써 주면 이곳의 우리 진지를 지켜낼 수 있소."
rows["125:2117302723"]="케일단 스파크라이트는 다뉴와 함께 공학 테라스에서 일합니다."
rows["125:241150037"]="내 병사 대부분이 네페르세트 영토에 침투하다가 목숨을 잃었소.$B$B내게는 그들의 희생이 헛되지 않게 할 책임이 있소."
rows["125:31747103"]="원래 시간대로 돌아갈 준비가 되셨다면, 제가 그대를 순간이동시켜 드리겠습니다."
rows["125:320026029"]="샤트라스 무두질의 대가이자 최고의 장사꾼인 시머는 고난의 거리의 자유 시장에서 만날 수 있습니다."
rows["125:335956385"]="그건 말이지, 하룸. 너희 말로 뭐라고 하더라? 하룸. 그러니까 우린 화장실이 따로 없거든. 무슨 말인지 알겠어?"
rows["125:359166212"]="푸남은 우리의 길드 등록 사무관을 만나시려면 엑소다르로 가십시오. 길을 따라가면 금방 엑소다르에 다다를 것입니다."
rows["125:412115411"]="잔달라 부족 트롤들은 이곳까지 오기 위해 먼 길을 왔고 큰 고통을 겪었소. 하지만 아무것도 하지 않는다면... 멸망을 자초하게 될 뿐이오."
rows["125:465666406"]="조금만 더 있으면 이 우리가 탈것으로 넘쳐나겠어요. 용맹한 얼라이언스의 병사여, 산양들은 이제부터 제가 잘 돌볼 테니 안심하시고 넘기세요."
rows["125:468508796"]="인간들은 찢어진 천막 봉투에서 벗어날 수 없지만, 요리하는 법을 아는 사람이 있다."
rows["125:473962554"]="캐롤라이 아니즈는 마을 북서쪽 끝에 있는 자기 집을 통째로 날려버리려고 애쓰고 있더군. 자네가 가서 좀 거들어 줄 수 있을지 한번 보게."
rows["125:507830067"]="최근 일어난 일들로 우리가 약하다고 생각하는 저들은 어리석었습니다. 저 트롤들에게 더는 희망이란 없습니다. 오늘 우린 끝을 볼 겁니다."
rows["125:530557895"]="노인도락의 남동쪽 끝에 있는 리나리스가 가죽을 만드는 훌륭한 스탠드를 설치해"
rows["125:543839492"]="<그늘한 루나들이 넓은 원으로 땅에 새겨져 있습니다. 그 가장자리에 접힌 노트가 있습니다."
rows["125:581475212"]="이상하지 않나요? 수천 년 전에 우리를 영리하게 만들어줬던 카자마이트가 트롤들에게는 아무런 효과가 없다는 사실이요."
rows["125:660383468"]="사냥의 길에 들어선 젊은 투사들을 시험하는 것이 저의 역할입니다.$B$B지금도 제 역할은 변하지 않았습니다. 오늘의 사냥감은 가시멧돼지라는 점만 다를 뿐이죠."
rows["125:667132475"]="칼드리스 드림시커를 찾는 거로군. 그녀는 다른 주술사들과 함께 지혜의 골짜기에 있는 스랄의 요새 입구에 있지."
rows["125:68228025"]="에두인 오어워드는 크로스로드 에 있는 노인 거리의 거리에 위치하고 있으며, 거리는 바자르와 살인 행로로 가는 길을 만나는 곳이다."
rows["125:714599753"]="<그녀는 더 가까이 다가옵니다.>$B$B우리 둘 사이에, 이 밤 중 하나를  ⁇ 어내려고 생각 중이야"
rows["125:732779779"]="오, 죄송하지만 제가 가죽에 대해 아는 것보다 더 많은 것을 알고 계시는군요. 더 많은 것을 배우고 싶으시다면 저기 있는 팔드론을 만나 보세요."
rows["125:881281801"]="용사의 전당은 구 시가지의 남동쪽 끝에 있습니다.$B$B명예와 정복 병참장교들을 그곳에서 찾을 수 있습니다."
rows["125:945712623"]="저주받은 기사의 마음은 죽지도 못한 채 무언가에 사로잡혀 있어요! 할로윈 기간에는 마을을 자주 습격하는데, 정말 끔찍한 일이 아닐 수 없답니다."
rows["126:106735241"]="내가 가르쳐 줄 수 있는 것들을 네가 모르는 것 같아$B$B진짜로, 뇌가 녹아들면 괜찮아 다른 곳으로 가서 놀아"
rows["126:1111482727"]="도시 정문에서 바라보면 북쪽으로, 힘의 골짜기 오른편의 두 번째 건물이네. 여관주인 그리쉬카를 만나보게."
rows["126:1208335680"]="미렌과 저는 어둠의 문 안팎을 통틀어 최고의 현상금 사냥꾼이지요. 잠시 기다려주시면 한 수 가르쳐드리지요."
rows["126:1255603711"]="실리시드에게 들키지 않고 이렇게 가까이 접근하려면 약간의 훈련이 필요하오. 그대에게 그럴만한 배짱이 있다면 굳이 훈련을 요구하지는 않겠소이다."
rows["126:1286655297"]="크고 번쩍이는 마법책이 주문과 능력을 위한 문양을 만드는 데 도움이 될 거다. 연금술 실험실에 주문각인사 근처에서 마법책 볼 수 있을 거다."
rows["126:1292888862"]="상인의 정원에 경매장이 열렸습니다. 은행에서 남동쪽으로 길을 따라가면 쉽게 찾을 수 있을 겁니다."
rows["126:1363451582"]="반갑네, 친구! 심령체 충전기에 대해 설명을 좀 해 볼까? 아니면 정밀하고도 근사한 무지향성 심령 융화기는 어때?"
rows["126:1389158719"]="지금 농담하는 건가요? 당신이 찾는다는 키 작은 친구는 내가 아니라 토니스 필라스톤인 것 같군요. 아래층에 있을 테니 어서 가 보세요!"
rows["126:1472735967"]="응급치료 기술을 더 배우고 싶다면 존경받는 의사 구스타프 밴하우젠을 찾아가 보십시오. 테라모어 병영에서 부상자를 치료하고 있을 겁니다."
rows["126:159052787"]="필멸의 존재여, 나는 그것을 되찾으려 했소. 아티쉬... 아티쉬로부터 새로운 명가의 시대를 열어보려고 했지. 모든 것을 되돌리려 했소. 심지어 여왕까지도..."
rows["126:1590858539"]="지난밤, 그리고 그 전날 밤에도 약속했었지만, 내일 밤에는 정말 멋진 곳에 당신을 데려갈게요!"
rows["126:1799456232"]="바보나 내 전투 복장을 보고 비웃겠지.$B$B낡은 강철로 만든 이 의복은 지식을 배우던 고대 장소에서 난 것일세!"
rows["126:1854657735"]="잘했네! 다른 사람들이 뭐라고 하든 나는 내가 당신을 제대로 본 줄 알았다니까. 하하! 농담일세! 좋아, 수업을 시작하도록 하지..."
rows["126:1879032630"]="노예가 된 다른 이들을 모아 전투를 준비하겠소. 스컬지군주 티라누스를 상대하기 전에 당신과 합류하겠소."
rows["126:1901457895"]=" ⁇ 어스 스톰스피커는 크리스탈 홀에  ⁇ 이랑  ⁇ 이랑  ⁇ 의 돌의  ⁇ 에 서 있습니다."
rows["126:1918092555"]="달라란의 북서쪽, 마법사 교역소에 있는 전설의 가죽방어구에서 모든 가죽세공사와 무두장이들을 찾으실 수 있습니다."
rows["126:1981162867"]="가죽세공이라면 사이먼 태너가 제대로 가르쳐 줄 겁니다. 구 시가지에 있는 태너의 가죽용품점에 가면 만날 수 있을 겁니다."
rows["126:2026474572"]="반가워요. 저는 아지미라고 해요! 과일과 식수를 팔려고 자주 외출하지요. 혹시 배가 고프거나 목이 마르지는 않으세요?"
rows["126:2027231013"]="이봐, 그롬-그롬 본 적 없나? 한 이 정도 키의 오크 말이야. 없다고?$B$B흠. 최근 아무도 못 봤다고 하던데. 아마 탈영했겠지."
rows["126:2077884675"]="우리는 아무것도 느끼지 못한답니다. 우리 영혼은 살지도, 죽지도 못한 채 이곳에 남아 있지요. 우리 시체를 찾고 영혼이 안식을 찾을 때까지 떠날 수가 없답니다."
rows["126:2111581167"]="다르나서스의 전사의 정원에 있는 나이트 엘프 무기 전문가 일예니아 문파이어가 활 사용법에 대해서 알려 줄 것일세."
rows["126:248869799"]="튼튼한 상자가 잔해와 붉은십자군의 열성적인 추종자들에게 둘러싸인 채로 벌목지 중앙에 놓여 있습니다."
rows["126:671443419"]="이 무기를 어떻게 쓰는지조차도 모르겠어... 하지만 이걸 들고 여기 이렇게 서 있으면 늑대인간이 겁에 질려 다른 곳으로 가버릴지도 몰라."
rows["126:697394379"]="다크문 게임 토큰이 필요해$b$b이 게임 토큰을 파어에서 구매하세요$b$b네 지도에 하나 표시해 줄게"
rows["126:831084658"]="마법 재연마사를 찾는다면, 마법사 지구 바로 밖에 있는 마법부여 가게 안에서 명가의 마법사가 있을 겁니다."
rows["127:1107910558"]="얼음이빨 광산은 호드의 영토에 있으며 서리늑대 무덤에서 북쪽 산맥에 있습니다.$B$B현재 코볼트들이 점령하고 있습니다."
rows["127:1121077110"]="넘겨다보니, 당신이 용암 구덩이에서 모은 흑요석 섞인 진흙이 보입니다. 이 진흙은 당신 변장을 물들이는 데 쓰일 겁니다."
rows["127:1247949569"]="나그란드에 있는 킬소로우 요새의 사물함은 당신 같이 훌륭한 솜씨를 지닌 도적이라도 열기 어려울 겁니다."
rows["127:1260104403"]="아, 호기심이 많은 친구로군요. 아주 좋습니다! 상황이 험악해질 때 당신 목숨을 구할 수 있을지도 모르니까 잘 봐 두십시오!"
rows["127:1294675957"]="언데드에게 야수를 맡겨도 상관없다면, 상업 지구 위층의 여관에 있는 안야 마울레이와 얘기해 보게."
rows["127:1367127668"]="로로케임, 위대한 석사 화학자 그리고 스케티스 추방자, 하위 도시의 북서부 부분에서 다른 아라코아들 사이에서 살고 있습니다."
rows["127:139726560"]="자네가 찾는 자의 이름은 루퍼트 보흐... 마을 남동쪽 끝에 있는 교수대끝 선술집으로 가보게. 위층에 있는 객실에 있을 테니 뒤져 보라고."
rows["127:1491020611"]="아, 그래. 알겠소.$B$B썩 사라지시오. 당신이 우리 일족의 몇몇에게 신뢰를 얻었을지 모르겠지만, 나한테는 그것만으로는 부족하지!"
rows["127:1554901208"]="겨울맞이 축제는 추운 계절에 따뜻함을 느끼게 해주는 원천인데 그 중심지가 바로 오그리마입니다."
rows["127:1892444636"]="명가가 돌아왔고, 그들과 함께 몇백 년 동안 사라졌던 기술이 함께 돌아왔습니다.$b$b제가 분석해 드릴 물건이 있습니까?"
rows["127:2002254336"]="바람의 돌로부터 천둥 같은 고함 소리가 들려옵니다...$B$B반갑네, 지휘관. 심연의 군주님께 전할 실리더스에 관한 새 소식이란 게 뭔가?"
rows["127:2053471611"]="음... 좋아, 좋다고. 그 장비, 어차피 좀 시험해 봐야 하는 거였으니까.$B$B조금만 기다리라고. 연습하러 나오라고 할 테니까.$B$B준비된 거야?"
rows["127:2113945991"]="왜 내가 이 시간을 낭비하고 있는거야? 데피아즈단 검으로 찌꺼기!"
rows["127:2122030045"]="이곳은 용사들이 서로 겨루며 기량을 갈고 닦는 연습장입니다. 용사분들의 연습 전투에 흑기사들을 소환하는 게 제 일이지요."
rows["127:2134108972"]="마을의 북서쪽 구석에 있는 큰 천막 안으로 들어가 보십시오. 피알 사일런트스트라이드를 만날 수 있을 겁니다. 그라면 당신이 원하는 것을 가르쳐 줄 수 있지요."
rows["127:227928092"]="생존이 확인된 유일한 '뒤틀린 드레나이'로서 주술사에 대한 선견자 노분도 님의 가르침을 수행하는 것이 저의 임무이자 명예입니다."
rows["127:299624207"]="불모의 땅에서 배운 교훈은 불타진 땅만이 이 호드 동물들을 물리칠 수 있다는 것입니다."
rows["127:304260951"]="나이트 엘프는 이미 만 년 전에 이곳을 잃었습니다. 지금 우리 손으로 추방하는 건 의례적인 절차일 뿐이죠."
rows["127:308863044"]="이 언덕과 작은 길들은 제집과도 같아요. 수년간 사냥을 하면서 지나다녔죠.$B$B전쟁에 쓰이게 될 줄은 생각도 못했네요."
rows["127:378602641"]="내게 없는 건 키인데 마법으로 높였다. 나는 위대한 안개 바위 잘 관리한다... 대부분 말이다.$B$B바보같은 하룻강아지들 같으니."
rows["127:509819721"]="대드루이드께서는 알터랙 계곡의 파괴적인 상황을 알리면 숲군주 이부스께서 분명 도우러 올 것이라 생각하고 계십니다."
rows["127:636447766"]="타빈은 광장에서 경계를 지켜보고 있습니다."
rows["127:751874429"]="황혼의 망치단이 어디 숨든지 간에 우리는 놈들을 무찌를 겁니다. 정령계도 놈들의 안식처가 되지는 못할 거예요."
rows["127:79764776"]="심연의 틈에서 전투가 발발할 기미가 보이오. 쌍집게발호와 함께 도착한 지원군으로 충분하면 좋겠군."
rows["127:841416937"]="봉화가 켜졌으니 이제 공격할 때이다! 이 전투 깃발을 가지고 가서 호드의 무덤에 꽂아라!"
rows["127:869009478"]="이 비행의 착륙 장소는 멀리 노래하는 마루입니다. 매우 위험한 비행이죠!$B$B이런 비행에는 서명된 각서를 받아둬야 하는데..."
rows["127:925668993"]="무기 사용하는 법을 내 기꺼이 가르쳐 주겠소. 내가 통달한 꼭 그만큼 당신도 능숙하게 무기 다루는 법을 배우게 될 거요."
rows["127:927721365"]="우린 같은 파도 아래 살았고, 같은 물을 마셨고, 같은 신을 섬겼다. 그런데 왜, 나가는 우리에게 등을 돌렸을까?"
rows["127:993875926"]="브란두르 아이언해머를 찾아가십시오. 아이언포지 성문의 북쪽에 위치한 신비의 전당으로 가면 그 친구를 찾을 수 있을 겁니다."
rows["127:999941325"]="그늘 협곡은 좋지 않은 일도 있지만, 이 숲으로 가는 건 마치 집으로 돌아가는 것 같습니다.$B$B언제나 평화롭고 순수하니까요."
rows["128:1014570376"]="언젠가 희망의 빛 예배당에 상점을 내고 싶어요. 저는 비록 전사는 아니지만, 나름대로 예배당에 도움을 줄 수 있는 방법이 있겠죠."
rows["128:1040454040"]="물론, 어떻게 다른 방법으로 그들의 순위에 침투해서 드레네이처럼 지나갈 수 있었을까요? "
rows["128:1070856571"]="사루에게 내 뛰어난 솜씨를 증명해 보이면 자기 딸 중 하나를 내게 줄 수밖에 없을 거야. 어디 최후에 누가 웃게 되는지 한번 보자고."
rows["128:107714628"]="그만! 더 멀리 가지 마시오, 필멸의 존재여. 무한의 용군단에 맞서기에는 아직 준비가 부족하오. 이리 오시오. 내가 돕겠소이다."
rows["128:1077284566"]="어서 오게나! 고블린 기계공학 설계도는 허가 받은 고블린 기술자만이 이용할 수 있다네."
rows["128:1149410791"]="맹금의 봉우리에 있는 와일드해머 드워프들도 빠른 그리핀들을 가지고 있긴 하지만 과연 그 그리핀들이 대용광로의 열기를 견뎌낼 수 있을까요? 어림도 없죠!"
rows["128:1246265765"]="테라제인의 돌난로 공격 계획을 반드시 저지해야 하네.$B$B테라제인이 돌난로를 공격하면 세계 기둥 중간 파편이 그녀의 손에 들어갈 거야."
rows["128:1278999658"]="히포그리프는 긍지를 알고 고결하며 재빠른 짐승으로서 명예를 위해 훈련을 받아왔습니다. 그대를 아주 먼 곳까지 빠르게 데려다 줄 수 있지요."
rows["128:1303922769"]="뭐하고 싶니? 영웅의 계곡에 있는 이상한 드레네이 생물 중 한 마리에 대해 들어봤어요."
rows["128:1375298507"]="드워프 무기 전문가인 불리위프가 한손 도끼와 양손 도끼 사용법 모두를 가르쳐 줄 겁니다. 그 친구는 아이언포지에 있는 잘나가는 무기 상점에서 찾을 수 있답니다."
rows["128:1418405602"]="흐음... 글쎄, 나는 아직 당신에게 큰 도움을 줄 수 없겠네요! 당신은 우선 기본적인 것부터 배워야겠습니다. 스톰윈드로 가서 스프라이트 점프스프로켓을 찾아보시기 바랍니다."
rows["128:1477824803"]="이렇게 생각하고 계시죠? '흑마법사가 있다니! 여기, 선한 기운이 넘치는 테라모어 한복판에!!'\010오, 어쩜 좋아요? 누군가 당장에라도 여군주 프라우드무어 님께 알려야 할 텐데!\010... 훗."
rows["128:1478941227"]="내 생각엔 다른 자들이 오슈군으로 들어갈까 말까 고민하는 동안 돈을 좀 벌 수 있을 거 같소.$B$B시간이 곧 돈이지!"
rows["128:1638652745"]="당신, 직업의 호환성이 저와는 일치하지 않는 문제로 인해, 당신의 능력이 모자라 처한 상황을 수정하도록 도와드릴 수 없군요."
rows["128:1715578367"]="더 많은 배움을 구하러 오셨다면 제 능력을 과대평가하셨습니다. 저쪽에 있는 텔로니스를 만나 보십시오. 그대에게 도움이 될 것입니다."
rows["128:1761651801"]="루테란 마을로 다시 날아가려 하오? 그렇다면 나와 같은 일을 하는 나이트 엘프, 실비아 필나베스와 이야기를 나눠보시오."
rows["128:1808202154"]="네? 아, 제가 좀 정신이 없어서 죄송합니다. 북부감시 요새에 계신 분들이 걱정돼서 말입니다. 제자들을 좀 보내 드릴 걸 잘못했어요..."
rows["128:1808295677"]="바리트라스의 허약한 몸을 물에 돌릴 때 머리에 잔혹한 부상을 입었을 때 왜 살아남지 못했는지 알 수 있습니다."
rows["128:1831816596"]="이 배가 가라앉지 않게 내가 할 수 있는 일은 그게 전부야. 게다가 여기에서 아직 피즐처럼 잘난 체 하는 원숭이들을 처리해야 해!"
rows["128:1885896791"]="너울소나무 요새로 가십시오. 그곳의 펄볼그들은 매우 많은 도움을 주었으며 당신이 원하는 기술의 전문가들이랍니다."
rows["128:1972445821"]="세월에 마모되거나 부식된 흔적은 전혀 없지만, 이 조작대는 고대의 물건인 듯한 분위기를 풍깁니다. 크고 둥그런 원반이 들어갈 법한 홈이 하나 있습니다."
rows["128:1974369771"]="실은 나도 수습생일 뿐이오. 리안논이 진짜 전문가인데, 저기 상자들 옆에 서 있소. 당신은 리안논에게 많은 것을 배울 수 있을 거요."
rows["128:1995529467"]="듣자 하니 스트롬가드에 틀어박혀 지내는 데네브 워커에게 응급치료 기술을 뚜렷이 향상시킬 서적이 있다고 합니다."
rows["128:2073747867"]="잘했네! 다른 사람들이 뭐라고 하든 나는 내가 당신을 제대로 본 줄 알았다니까. 하하! 농담일세! 좋아, 수업을 시작하도록 하지..."
rows["128:2089286098"]="우리 장로들은 세상 사람들과 이야기를 나누고, 조상님에게 간 이들을 반기려고 연초에 잠깐 들른다네."
rows["128:2112620074"]="얼음혈 묘지는 전쟁터 남쪽에 있고 얼음혈 탑 동쪽에 있습니다.$B$B호드는 현재 이 기구를 통제하고 있다."
rows["128:395852173"]="이렇게 외진 곳에서 친구를 만나게 되다니 정말 반갑군. 자, 함께 걸어보세. 서로 체온을 나누면 몸도 따뜻해지고 좋지 않나?!"
rows["128:439728053"]="씩씩이 그 친구를 찾는 거요? 탑 위에 있는 크론크라이더에게 물어보면 말해줄 거요. 내가 가르쳐줬다고는 아무한테도 말하지 말고..."
rows["128:613470683"]="거의 다 됐군! 하지만 아직 좀 부족한데요. 그래, 맞아... 어제 신은 양말을 빨아 볼까요... 으으음, 맛 좋군!"
rows["128:658287380"]="레슨과 기름은 예매크가 가르쳐줄 것 같네요"
rows["128:724141746"]="거점 보초탑은 남쪽의 호드 영토와 투쟁의 벌판 사이에 통로를 확보하고 있습니다.$B$B아무도 이곳을 점령하지 않았습니다."
rows["128:738356243"]="여기 네더가드는 좀 답답하게 돌아가지요. 가끔 드워프는 임무를 잠시라도 잊을 수 있는 한 잔이 필요하답니다."
rows["128:883933838"]="치유의 수정을 보충해줘서 다시 한 번 고맙다는 말을 하고 싶군. 자네가 곳곳에 도움을 주고 있다는 말은 익히 들었네. 계속 힘써주게나!"
rows["128:945904627"]="여기에 틀어박혀 지내는 것도 이제 지긋지긋하네요. 다나스 님의 복귀를 지연시키는 사무원이 누군진 몰라도 제가 주먹으로 세게 한 방 먹여줄 겁니다."
rows["128:963877287"]="우리는 세계를 착취... 아... 아니... 그러니까 탐험하고자 검은바위 나락의 보호와 안락함을 떠나기로 했답니다."
rows["129:1131830279"]="저들이 날 없애라고 당신을 보낸 거로군요? 예상했던 일이지요... 공포를 권력의 무기로 삼는 생물들은 모두 똑같으니까요.$B$B그런데 당신은... 저들의 일원이 아니지 않습니까?"
rows["129:1186211700"]="이리 오시오. 내가 그동안 본 것 중 가장 멋진 탈것을 타는 방법에 대해서 알려 주도록 하겠소. 음... 훈련 비용을 감당할 충분한 소지금이 있는 거요?"
rows["129:1248981343"]="여기에는 거래와 구매인에 대한 정보며 기타 사업과 관계된 여러 가지 사항이 가득 적혀 있는 것 같습니다."
rows["129:1298861054"]="곧 귀가 먹고 말 거야. 그놈의 커다란 초록색 하피는 입을 5초도 쉬지 않을 거라고. 이 배를 어떻게 조종해야 하는 지 정도는 안다니까, 알았어? 난 바보가 아니란 말이야!"
rows["129:1422510966"]="여기 있다, 친구. 이번에는 좀 조심해. 알겠어?$b$b그럼 드락진 폐허로 가서 단상 근처에서 비약을 마셔라!"
rows["129:1545003528"]="소환수는 안심하고 알랏신에게 맡기셔도 좋습니다. 그는 사냥꾼들이 모이는 세나리온 자치령에 살고 있으니 그리로 가서 만나보도록 하십시오."
rows["129:160799895"]="비전 마법을 배우고 싶다면 하늘 감시초소의 동쪽에서 루아다와 함께 제자들을 가르치고 있는 세미드를 찾아가도록 하십시오."
rows["129:1669725838"]="저습지에 있는 메네실 항구 북쪽의 푸른아가미 습지대로 가보게. 난파된 배에서 뭍으로 떠내려온 금고들이 잔뜩 있을 걸세. 물이 빠지고 나니 드러났지 뭔가."
rows["129:1679196439"]="서레리온 트루에쇼트는 레인저들을 훈련용 도미니에서 훈련시키고 있습니다."
rows["129:1704646047"]="리치 왕이 전사했으니 제게 남겨진 것이라고는 저의 본분뿐이군요. 가족도 없고, 친구도 없습니다... 오직 이것뿐이군요.$b$b전쟁 말입니다."
rows["129:1808349004"]="그만! 더 멀리 가지 마시오, 필멸의 존재여. 무한의 용군단에 맞서기에는 아직 준비가 부족하오. 이리 오시오. 내가 돕겠소이다."
rows["129:1917913667"]="어서 오시게, 용사여! 검투사를 정식 직업으로 삼고 싶은 생각은 없나? 우리가 힘을 합치면 돈방석에 올라앉을 수 있단 말이지."
rows["129:1920076547"]="<아직 숨은 붙어 있지만 강력한 진정제 성분에 취해 탁자에 누워있는 블러드 엘프>"
rows["129:1984271009"]="작업을 시작하기 전에 손부터 씻고 오게. 싸움에서 묻은 피나 먼지로 가죽을 더럽히면 그 천연의 아름다움이 사라질 테니까."
rows["129:1990290621"]="우린 절대로 이 배들을 제때 고치지 못할 거요. 겨울이 우리의 최후와 함께 다가오고 있소. 왕자님이 우리 모두를 버린 게 아닌가 싶어 두렵다오..."
rows["129:2038659630"]="에테리얼 중에서 어떤 이들은 살 그리고 살로 이루어진 존재들을 다루곤 하는데 그런 에테리얼들을 살덩이괴물 조련사라고 합니다."
rows["129:277379185"]="여기 있다, 친구. 이번에는 좀 조심해. 알겠어?$b$b그럼 드락진 폐허로 가서 단상 근처에서 비약을 마셔라!"
rows["129:400866306"]="내 구조 계획은 기발하기도 하지. 한 치의 실수도 없어. 이 계획을 방해할 수 있는 건 고블린뿐일 거야. 아가미 달린 고블린 말이야. 지긋지긋해."
rows["129:557873033"]="내 구조 계획은 기발하기도 하지. 한 치의 실수도 없어. 이 계획을 방해할 수 있는 건 고블린뿐일 거야. 아가미 달린 고블린 말이야. 지긋지긋해."
rows["129:618548775"]="스톰윈드에 오신 걸 환영합니다. 이 요새를 재건하는 데 오랜 세월이 걸리긴 했지만, 충분히 가치가 있었습니다. 이 장대한 요새에 관광차 온 것입니까? 아니면 따로 볼일이 있어 온 것입니까?"
rows["129:633820465"]="사냥꾼을 찾으신다면 다잘라를 찾아가 보셔야 할 거예요. 보통 돌라나르 여관 바깥에서 시간을 보내곤 하지요."
rows["129:776608543"]="잊혀진 땅의 북쪽 살데리스 해안 수역이나 황야의 땅에 있는 고통의 요새로 가면 자물쇠 따는 연습을 할만한 잠겨진 금고들이 있을 겁니다."
rows["129:79911590"]="베마린은 페어스트라이더스 광장에서 금수업을 가르치고 있지만, 다소 더러운 직업이지만,"
rows["129:819103094"]="고르스는 가끔 혼란스럽다. 고르스는 사람을 아주 잘 죽여서 부대장이 되었다. 그런데 이제는 고르스가 죽이러 나갈 일이 없다!"
rows["129:868131954"]="이곳은 카라잔의 탑으로 저의 주인이신 메디브 님의 거처입니다. 한낱 문지기에 불과한 제가 설명할 수 있는 것은 여기까지입니다."
rows["129:912860511"]="그분께서 알을 구해오라고 하셨다. 다른 세계에 있는 불의 부화장에 쓸 알들을.$B$B그중에서도 특별한... 특별한 알 하나를... 찾으셨다."
rows["12:1106565000"]="무슨 일이십니까, 필멸의 존재여?"
rows["12:110909725"]="난 복종해야 해."
rows["12:1235039007"]="한 잔 걸치자고!"
rows["12:1575371632"]="제 도움이 필요하십니까?"
rows["12:1732653236"]="뭐야? 이 멍청한 녀석아"
rows["12:1742803257"]="실종된 문장"
rows["12:1912597556"]="일어나요 일어나요!"
rows["12:1927311569"]="묻지 말게..."
rows["12:201207537"]="- 그리고 당신은?"
rows["12:520578454"]="날 놔두시오."
rows["12:989513323"]="- 누구신?"
rows["130:1082327986"]="마직 쿼터, 상단층의 포털룸, 니르메도르미가 그 곳에서 크론오마저와 벨리나로스 시케로스 피 마법사를 가르치고 있습니다."
rows["130:1129587984"]="우와! 탄자르가 풀려났다!$b$b어찌나 다행인지! 게다가 송곳니에 흠집도 안 났군요.$b$b불사신이라고 들어 보셨습니까? 그게 바로 접니다. 부정할 생각 마세요."
rows["130:1173524896"]="우리 상급 사제들은 빛의 전당에서 나루의 보좌로 나가는 길목에 있는 빛의 의회 회의실 안에 있습니다. 성스러운 빛이 함께하기를."
rows["130:1222885503"]="달라란 북서쪽, 마법사 교역소에 있는 반짝이 수집광에서 전문 광부와 채광용품 상인을 만나실 수 있습니다."
rows["130:1227594109"]="신비로운 마법의 추종자시로군요?! 흠, 그렇다면... 정기의 봉우리 아래 있는 예언의 웅덩이 근처로 가 보십시오."
rows["130:1289745779"]="여관주인 팔라가 몸과 마음, 그리고 당신의 영혼이 편히 쉴 수 있도록 해 줄 거예요. 봉우리 하층에 있는 은행 바로 남쪽에 여관이 있습니다."
rows["130:13657884"]="그래, 내가 기억할 수 있는 그 순간부터 여기 갇혀 있었네.$B$B전생에 난 대장장이였지. 자네가 가진 물건을 고쳐줄 수도 있을 거야."
rows["130:1370913141"]="절 우리에서 꺼내 주셔서 감사합니다. 이제야 머리가 좀 돌아가는 것 같군요. 볼진 님께 제대로 보고드릴 수 있을 듯해요.\010"
rows["130:1420511642"]="동부 역병지대에 있는 희망의 빛 예배당에서 은빛 여명회가 스컬지의 저항에 맞서고 있소. 그리로 가서 지시를 따르시오."
rows["130:1426756062"]="전 운이 좋아요. 이런 범선의 선장 급사는 아무 타우렌이나 하는 게 아니니까요! 그레직스 님은 이 끝내주는 전투 통나무배까지 몰게 해주셨다고요."
rows["130:1442528979"]="다르나서스의 전사의 정원에 있는 나이트 엘프 무기 전문가인 일예니아 문파이어가 활의 사용법에 대해서 가르쳐 줄 겁니다."
rows["130:1462713026"]="<에리스가 고개를 끄덕이며.>$B$B이 눈으로 수많은 죽음과 명예들을 봐 왔습니다.$B$B이것은 내가 이제껏 보고 싶었던 그것을 정확히 보여주는 듯 하네요"
rows["130:148950187"]="장가르 습지대에 사는 야생늪 일족에겐 정교한 자물쇠가 달린 광주리가 있답니다. 그 광주리를 여는 건 당신 정도의 솜씨라도 결코 쉽지 않을 겁니다."
rows["130:1495175859"]="그곳에서 나는 너무 오랜 시간을 보냈소. 아주 멋진 곳이고 거기서 봉사하는 일도 즐거웠지만, 이제는 여기 머무는 편이 좋을 것 같소."
rows["130:1606498488"]="그 빌어먹을 짐승들이 우리 배를 태워버리지만 않았으면 우린 지금쯤 집에 가 있을 텐데. 이제 일 좀 하게 저리 가세요!"
rows["130:165728563"]="우리랑 같이 있는 동안, 왕아, 네가 떠나면 다른 괴물이 널 대신할 거야."
rows["130:1751192058"]="이런 환경에서 어떻게 일을 하라는 말입니까?! 게다가 주위에는 역겨운 포세이큰 놈들이 득실대고 있습니다! 트랜퀼리엔과 쿠엘탈라스도 볼 장 다 봤군요!"
rows["130:1762868752"]="북쪽의 잿빛 골짜기로 가는 보급 짐마차들은 모두 이곳에서 휴식을 취하고 재정비하지요. 원활하게 보급이 이루어지도록 하는 건 정말 중요한 일입니다."
rows["130:1878710771"]="어? 음... 안녕하세요! 돈을 받으러 왔거나 뭔가를 소환하러 온 거라면 잘못 찾아오셨어요. 죄송하게 됐네요!"
rows["130:1969401425"]="<아크마지 바르고트가 미소를 짓고 당신을 선호합니다.>$B$B저 망할 바이올릿 타워에 충분한 공간이 있습니다.$B$B해마다 날 찾아볼 수 있어"
rows["130:247280687"]="상업 지구 위층의 여관 옆에 있는 안야 마울레이를 찾아가게. 나라면 안 그러겠지만, 자네 야수니 뭐."
rows["130:292239715"]="난 자네를 도와줄 수가 없겠군. 자넨 내 능력을 뛰어넘었어. 저기 저 관 앞에 서있는 아서 무어에게 가보게. 나보다 더 많은 걸 가르쳐 줄 거야."
rows["130:48971573"]="봉화가 켜졌으니 이제 공격할 때이다! 이 전투 깃발을 가지고 가서 얼라이언스의 무덤에 꽂아라!"
rows["130:632348379"]="최근에 살데릴의 안식처에 훌륭한 재봉사가 한 명 왔습니다. 바늘과 실을 다루는 그녀의 솜씨는 최고이니 그녀를 찾아가 보십시오."
rows["130:65120039"]="다시는 지름길로 가지 않을 것이네. 내 맹세하지! 지옥불 반도의 하늘이 그렇게 위험할 줄이야 누가 알았겠나?"
rows["130:72735574"]="매날개 광장의 여관 2층에 켈레오누스라는 악마 소환 전문가가 있습니다."
rows["130:736275005"]="하나시와 사요크에게 가면 한손 도끼는 물론 양손 도끼 사용법을 배울 수 있네. 오그리마, 명예의 골짜기로 가면 만날 수 있지."
rows["130:7399867"]="한 장소에서 이렇게 여러 종류의 버섯을 보기는 처음입니다. 시간만 충분하다면 이 버섯들의 사용법을 모두 알아낼 겁니다."
rows["130:764251314"]="우리 공동의 적인 그림토템 부족과 싸우는 높새바람 봉우리의 타우렌을 도우러 드루이드와 파수꾼으로 구성된 소규모 부대가 왔습니다."
rows["130:772785818"]="드루이드라고요? 이 근처에서 드루이드를 본 적은 없습니다. 하지만, 스톰윈드에 나이트 엘프들이 모여 사는 지구로 가시면 찾을 수 있을 것 같습니다."
rows["130:801420098"]="자꾸 얼쩡거리지 말게, 친구.$B$B왕관화학회사의 축제 용품을 사려거든, 도시 안으로 들어가 사랑의 상인을 만나 보게."
rows["130:801940781"]="와일드해머 드워프의 할빈 프로스트해머는 썬더브루 양조장에 있어요. 그가 주술사의 길을 가르쳐줄 거예요."
rows["130:85147461"]="식물학자 티니아렐보다 파티용 꽃을 잘 가꾸는 사람이 있을까요? 분명 살데릴에게 포도주를 대접받고 있을 테니 그리로 가보십시오."
rows["130:876807314"]="제가 가르치는 내용을 이해하기에 그대의 수준이 너무 낮군요. 물약 제조에 대해 배우고 싶다면 이곳에 있는 텔아실을 만나 보십시오."
rows["130:945218113"]="아서스는 언데드 벌레 몇 마리면 우릴 동부 왕국으로 돌려보낼 수 있다고 생각하나 본데... 그건 큰 착각이지."
rows["130:985237282"]="당신이 가져온 서판의 성각문자를 보면 이 장치를 다시 작동시키는 방법이 있다고 하오.$b$b그 방법만 알아내면 되는데..."
rows["130:996779017"]="어떻게 감히 우리 고블린을 좀비로 바꾼 다음 고블린한테 던질 수 있어!$B$B저 위로 올라가서 그놈들 엉덩짝을 걷어차기 전에 훈련을 받아야 하지 않아?"
rows["131:1050649803"]="사절 탈룬은 우리의 새로운 동지들에게 이 세계의 정령에 대해 가르치라고 절 여기로 데려왔지요... 하지만 아무도 제 말을 듣지 않는군요."
rows["131:105730649"]="내가 가진 것 중에는 너에게 도움이 될 만한 게 없구나.$B$B드롬이라면 네가 관심을 둘만한 것을 갖고 있을 거다."
rows["131:1068208934"]="은행을 찾으신다면 다르나서스 중심부로 가 보세요. 그곳이라면 그대의 귀중한 보물을 안전하게 보관할 수 있을 겁니다."
rows["131:1084332796"]="이 마을에 나름 스카이체이서라는 현자가 있습니다. 주술사의 길을 걸어가는 당신에게 그가 도움을 줄 수 있을 겁니다."
rows["131:1397046234"]="피즐과 포직의 쾌속선 좋아하시네! 이 녀석은 원래 제가 만든 작품이에요! 저들도, 래저릭도 아닌 바로 제가 만들었다고요!$B$B징키의 쾌속선이라 불리는 게 옳아요!"
rows["131:1551677459"]="정신이 나약한 자들이나 비전 마법에 압도되어 타락하는 거랍니다. 당신이 흑마법사의 길을 가지는 않을지라도 항상 이것을 기억하도록 하세요."
rows["131:1677971733"]="덩거는 무역 구역의 성벽에 새를 싣고 있어 "
rows["131:1770120887"]="워터로드 히드랙시스는 폭풍의 만의 섬인 아즈샤라에서 숨어 있습니다."
rows["131:1798010209"]="음, 앞으로 또 누가 합류할지, 그래서 다음엔 누가 죽게 될지 절대 모를걸.$B$B충고 한마디 해달라고? 한 사람에게 너무 달라붙지 말라고."
rows["131:1865669927"]="그 유물은 정말 거대한 신비가 아닐 수 없다. 주기적으로 그 유물에 대한 조사를 게을리하지 않으면 그들의 능력에 대한 더 나은 이해를 하게 될 거다."
rows["131:1887299690"]="우리 양떼가 성장하고, 희망도 함께 이 도시의 왜자들은 돌수건자라는 이름을 존중하고, 그들의 회귀는 다른 사람들에게 영감을 줄 것입니다."
rows["131:1888571196"]="이 어둠의 벽은 악마의 진군을 막아 우리가 길을 건널 시간을 벌어줄 것이다.\010$b너와 다른 엘프들이 건너가고 나면 나도 따라가지."
rows["131:190777650"]="이 위에서는 대격변의 파괴 현장을 모두 지켜볼 수 있다네. 우리 세상이 얼마나 깨지기 쉬운 존재인지 몸서리쳐질 정도라네."
rows["131:1916144441"]="우리는 수년간 가공을 불태웠지만 최근 계곡이 겪은 모든 것..."
rows["131:232167403"]="흐음... 글쎄, 나는 아직 당신에게 큰 도움을 줄 수 없겠네요! 당신은 우선 기본적인 것부터 배워야겠습니다. 스톰윈드로 가서 스프라이트 점프스프로켓을 찾아보시기 바랍니다."
rows["131:258467853"]="하이 엘프인 히라 스노우돈이 극지 비행 기술을 가르쳐 줄 겁니다.$B$B달라란 동쪽에 있는 크라서스 착륙장에서 용매를 탄 그녀를 만날 수 있을 겁니다."
rows["131:312117613"]="으으... 저 잡초들 때문에 밤낮으로 눈코 뜰 새가 없으니, 원! 당신도 보셨죠?$B$B그냥 수도관 같은 걸 타고 이 녀석들에게 멀리 좀 도망갔으면 좋겠다니까..."
rows["131:343199114"]="달라란 남쪽, 무어의 골동품점에 있는 여러 상인들이 모든 종류의 장신구, 유물, 계승품, 보조무기를 팝니다."
rows["131:517012650"]="바라딘 주둔지에 온 걸 환영하오. 지금은 보잘것없어 보이겠지만 우리가 조금만 노력하면 이곳을 멋진 주둔지로 만들 수 있을 것이오."
rows["131:669957966"]="동물들을 돌보고 훈련하려면 많은 일을 해야 하지만, 그만한 가치가 있지요.$B$B그렇지만 도움의 손길이라면야 언제든지 받을 수 있답니다."
rows["131:755192501"]="이렇게 봉사 활동을 하는 것도 의술사 수련의 일부라네. 자넨 날 도와줬으니 공짜로 도와주지. 어딜 고쳐 줄까?"
rows["131:771461039"]="리 브라운은 수정 호수에서 낚시로 하루 일과를 다 보낸답니다. 찾아가보면 분명 재미있는 이야기도 듣고 몇 가지 요령도 배울 수 있을 겁니다."
rows["131:99646304"]="안녕하십니까?! 성함이 어떻게 되시나요?$B$B그건 그렇고, 아름다운 푸른 초원 위의 그림 같은 우리 집에는 무슨 일로 오셨습니까?"
rows["132:1162047949"]="물론 궁금하긴 합니다. 하지만 이미 엎질러진 물이잖아요.$b$b괜히 사람들을 동요시키고 싶지 않습니다. 그건 신중하지 못한 일이라고요!"
rows["132:1231683421"]="좌초된 얼라이언스 선원들은 죽을 것을 알면서도 필사적으로 저항하고 있어요.$B$B나름 감동적이긴 해도 한편으로는 한심하군요."
rows["132:1235086271"]="그렇습니다. 이 상점을 운영한 지는 꽤 됐지요. 요즘 들어서는 장사도 아주 잘 되는 편이랍니다. 새로운 모험가들이 많이 지나다니고 있거든요."
rows["132:1305606999"]="세나리온 의회는 현명한 판단력으로 이 세계의 많은 비밀을 밝혀냈습니다. 장인들은 이 드루이드들의 말에 귀를 기울여야 할 것입니다."
rows["132:1411330592"]="소용돌이가 몰아치는 걸 보십시오. 이리 와서 앉아 편히 쉬십시오. 이곳에서 휴식의 대가는 당신이 쉽게 제공할 수 있는 겸손함 뿐이랍니다."
rows["132:1470154094"]="내 지식을 전수받기 전에 먼저 다른 이에게 배워야 할 게 아직 남아 있군요. 부지런히 노력하고 희망을 잃지 마세요."
rows["132:1632682402"]="우리가 원하는 것은 단지 거인들과 조화롭게 사는 것뿐이라는 사실을 저들이 알아준다면 생존을 위해 싸우지 않아도 되지 않겠어요?"
rows["132:1638689250"]="핌블 파인스핀들이 대용광로 북서쪽에 가게를 차렸습니다. 그 친구라면 가죽으로 제법 쓸만한 방어구를 만드는 방법을 알려줄 겁니다."
rows["132:1640034657"]="세세비를 찾으시는군요.$B$B나무 아래에는 낚시꾼인 늙은이 움베토가 있는데, 보통은 그 곁에서 잠을 잔답니다. 나이 많고 덩치 큰 호랑이처럼 생겼지요."
rows["132:1660843038"]="아킨둔은 우리 선조에게 영혼의 고향입니다. 그곳은 제쳐놓고라도 모든 뒤틀린 드레나이는 한때 드레나이였죠... 우리는 모두 같은 영혼을 갖고 있습니다."
rows["132:1719707242"]="전쟁이 단지 생명을 보호하기 위해서일 뿐일까요? 씨앗이 땅 위로 솟아오르려고 애쓰는 것처럼, 우리 역시 존재하기 위해 싸우는 거죠."
rows["132:1724461349"]="얼라이언스의 우리 동료가 은빛날개 파수대와 힘을 합쳐 싸우고자 전쟁노래 협곡에 집결하고 있습니다. 그리로 가서 그들을 도와주시겠습니까?"
rows["132:1738824448"]="저는 아직 계속 배우는 중인데 그대가 저보다 한 수 위군요. 더 배우고 싶거든 메린과 얘기해 보시면 그대를 가르쳐줄 겁니다."
rows["132:1838435493"]="이 얼음 조각에서 빙하가 마구 몰려오며 부딪치는 장중한 소리가 울려 나옵니다. 또한, 그 한기 때문에 머릿속에는 생명도, 끝도 없는 겨울만이 떠오릅니다."
rows["132:199806907"]="밖에 있는 그런트들뿐만 아니라 내 형제들과 나도 하이잘 산 전투에 참가했었습니다. 은행에서 돈을 훔치려는 자들은 먼저 우리를 쓰러뜨려야 할 겁니다."
rows["132:2005352117"]="동물을 보살피는 사람을 찾으신다고요? 그렇다면 돌라나르의 여관 밖에 있는 세리아드네를 찾아보십시오. 그녀가 도와줄 수 있을 겁니다."
rows["132:201956234"]="지극히 평범하고 세속적인 방법으로 상처를 치료하는 것을 좋아하는 이들을 위해 카나리아가 매날개 광장 여관에서 깨끗한 진료소를 운영하고 있으니 그리로 가보십시오."
rows["132:2086576851"]="실바나스 여군주님의 재가로 죽음추적자의 수가 늘어나고 있소. 이제 적이 눈치채지 못할 때 더욱 치명적인 공격을 감행할 수 있을 거야."
rows["132:216726251"]="아, 보관해 둘 물건이라도 있나보군. 길을 따라 북쪽으로 오그리마까지 가게. 그곳 그런트 중 한 명에게 다시 물어봐."
rows["132:236481229"]="힘의 골짜기 중앙 요새에 블러드 엘프가 있네. 벨록이라고 실버문 대표단의 한 명이지. 그가 바로 자네가 찾는 자일세."
rows["132:345359874"]="공성 전차들이 다 완성되어 가니 조금 지루하군요!\010혹시 기계공학자 아니세요? 저랑 설계도를 비교해 보는 건 어때요...?"
rows["132:516895108"]="<고대정령이 고개를 돌려 당신의 머리보다 큰 눈으로 당신을 응시합니다. 그 눈을 들여다보니 마치 깊은 바닷속으로 빠져드는 것 같습니다.>"
rows["132:588756548"]="보급의 중요성을 무시하지 말게. 전투를 승리로 이끄는 건 전사들이지만, 전쟁을 승리로 이끄는 건 보급품이라네."
rows["132:591186627"]="나도 재봉에 대해서 꽤 알긴 하지만 전문가는 아닐세. 자네가 얘기해야 할 사람은 바로 리안논이지! 멀리 있지 않으니 언더시티에서 그녀가 어디 있는지 물어보게나."
rows["132:724611671"]="불타는 군단과의 싸움을 도와주신다면 정말 고맙겠습니다. 여군주 제이나 프라우드무어가 전방에서 그대와 같은 용사들의 도움을 기다리고 있습니다."
rows["132:839838744"]="보석 상인은 두 명 있습니다. 한 명은 점술가 길드와, 다른 한 명은 알도르 사제회와 손을 잡고 일하고 있지요. 어느 보석 상인을 찾습니까?"
rows["132:85113640"]="와이번 조련사는 오그리마에서 찾을 수 있지. 길을 따라 북쪽으로 가서 오그리마 그런트에게 물어보면 더 자세히 가르쳐 줄 거야."
rows["132:944893637"]="기회가 생길 때마다 찌른다네. 운동도 될뿐더러 노움 녀석들이 무슨 연구를 하고 있나 알아내는 데는 제격이라네. 뭐 지난 경험한 바에 비추어 얘기하자면, 좋은 연구는 아니더군."
rows["133:1084040914"]="난 준비됐네. 자네만 준비되면 결혼식을 시작하지! 황혼의 망치단 놈들이 무슨 짓을 벌일지 모르니 신랑과 신부는 내 곁에 두겠네.$B$B준비됐나?"
rows["133:1107099460"]="원하는 게 있다면 브레이지 게츠를 찾으세요! 아셨죠?$B$B\"합법적인\" 무언가만 말하는 게 아니랍니다. \"원하는 건 뭐든지\"라고요, 친구! 뭐든지요..."
rows["133:1127694740"]="아이언트리 대장님은 절대 포기하지 않으셨소. 놈들이 더럽힌 우리 땅을 보며 반드시 되갚아 주겠노라 말씀하시곤 했소. 아직 저 아래 어딘가에 살아계실지도 모르오!"
rows["133:1393659364"]="다크문 축제 카드? 그거라면 여기 있는 학자에게 가봐. 골동품이나 유물을 거래하고 싶다면 나를 찾아오도록."
rows["133:1467872877"]="충직하고 성실한 수습생이 이렇게 많으니, 전 정말 복 받은 사람입니다. 제 연구 업적도 충분한 실험 대상 없이는 불가능했을 겁니다."
rows["133:16283020"]="먼지진흙 습지대의 담쟁이 마을에 있는 발라이 로크웨인이 당신의 기술을 향상시키는 데 필요한 서적을 팔고 있소."
rows["133:1664557566"]="내겐 별다른 임무가 부여되지 않았다는 걸 알 거요. 그래서 그런지 전선 가까이에서 임무를 수행하는 게 기분 전환하기에 딱 좋지."
rows["133:1788703140"]="모루에다 망치만 휘두른다고 대장장이는 아니지. 누가 보고 비웃기 전에 그 망치를 이리 주게. 내가 제대로 가르쳐 줄 테니까."
rows["133:1808899257"]="다른 애완 동물을 훈련시키는 동안 애완 동물을 보관해야 한다면, 왜 왜지 구역에 있는 제노바 스톤스힐드와 얘기해야지?"
rows["133:1839708436"]="토쉴리의 연구기지는 최고예요! 이상한 물자가 풍부하고 한적한 아웃랜드의 힘의 원천은 극한의 실험을 하기에는 최적의 조건이랍니다!"
rows["133:197843012"]="보라타안 아쉬먼틀은 도금과 엔지니어링 벤치 사이에 있는 트레이더의 하층의 도금당에 열차한다."
rows["133:2023961789"]="아이고!$b$b그래, 이제 올 때가 됐다고 생각했습니다.$b$b벌써 며칠째 기다리고 있었으니까요.$b$b이런 무더위 속에 늙은 드워프를 남겨두다니... 저 녀석을 이렇게 가르치진 않았는데..."
rows["133:253287286"]="썬더브루 양조장에 새로운 마법 몇 가지를 가르쳐 줄 만한 마법사가 하나 살고 있습니다. 이름이 마지스 스파크맨틀인 걸로 기억합니다만."
rows["133:273171041"]="원자들은 침묵을 깨고 있지만, 그들은 모두 당신을, 안자리, 마녀에 대해 이야기합니다."
rows["133:373457790"]="나의 사랑스러운 칼리 얘기를 하려고 온 것 같진 않군. 그렇다면 좋아, 물약에 대해 얘기를 하지. 당신은 너무 융통성이 없다고 누가 말해주지 않든가?"
rows["133:405149101"]="오랫동안 기다렸던 날이 찾아왔네, 용사여. 그대와 동료들은 리치 왕에게 정의의 심판을 내릴 준비가 되었나? 그대의 지휘에 따라 진격해 나가겠네!"
rows["133:407429221"]="<복원의 비약의 약효가 퍼지자 기침을 심하게 하는 바르니스>$B$B구해 주셔서 감사합니다. 저는 당장 트랜퀼리엔으로 돌아가야겠습니다!"
rows["133:444147100"]="그대를 던홀드로 데려다 주기 전에 에로지온에게 화염 폭탄 자루를 받으라. 시간을 낭비하기 싫은 건 결국 그대도 마찬가질 테니..."
rows["133:455414087"]="이런 버림받은 땅에서 그대 같은 영웅을 만나면 언제나 기쁘답니다. 제가 어떤 식으로라도 도와드릴 일이 있나요?"
rows["133:500238243"]="<공포에 질려 눈이 휘둥그레지는 일꾼>$B$B안 돼! 사우라노크 님이 오그리마의 새로운 이교도 지도자라는 걸 알아내셨다고요? 저한테는 아무도 모른다고 말씀하셨는데!\010"
rows["133:550380412"]="우리가 이곳 나가를 제대로 판단하지 못했나보군요.$b$b저렇게 조직적이고 잘 훈련된 나가는 이제껏 본 적이 없습니다."
rows["133:594758743"]="당신처럼 많이 알고 있는 이에겐 나는 더 이상 가르칠 게 없소! 당신은 호드 일원이니까 오그리마에 있는 노그를 찾아가야 하오!"
rows["133:678649395"]="공무를 담당하는 이들은 모두 아이언포지에 살고 있습니다. 길드를 창설하기 위해 서류가 필요하다면 아이언포지 사무소로 가보는 게 좋겠군요."
rows["133:687386371"]="장군 블러드힐트? 가로쉬의 졸개 말인가?$B$B그가 여기에 올 이유가 없는데. 보다시피, 어, 여기 상황은 내가 잘 통제하고 있다 전하게."
rows["133:793378204"]="그대를 던홀드로 데려다 주기 전에 에로지온에게 화염 폭탄 자루를 받으라. 시간을 낭비하기 싫은 건 결국 그대도 마찬가질 테니..."
rows["133:892332624"]="이 거대한 친구들은 걸어서는 갈 수 없는 길을 잘 알고 있지요. 신속하게 목적지에 모셔다 드리겠습니다. 가시는 동안 주위 경관이나 천천히 둘러보십시오."
rows["134:1034797035"]="아우버다인이나 용맹의 성채로 가려면 스톰윈드 항구에서 배를 타는 게 가장 빠릅니다. 대성당 광장과 스톰윈드 공원 사이로 운하를 따라가면 항구에 도착합니다."
rows["134:1070894667"]="드루이드들과 파수꾼들은 따로 있는 걸 선호합니다만, 항상 함께 일을 잘 해왔답니다.$B$B사생활을 중시하는 것일 뿐 서로 질색하는 건 아니랍니다."
rows["134:111964796"]="대지 고리회가 자네를 보냈나?$B$B대지를 치유하려는 우리의 노력은 바로 여기, 세계수에서 시작될 걸세. 자네가 직접 보러 와줘서 기쁘군."
rows["134:1130173704"]="그래요. 내 기꺼이 당신에게 대장기술을 가르쳐주겠소. 가서 작업복과 망치를 가져오시오. 뭘 만들 수 있을지 한번 보자고."
rows["134:1191921649"]="마법사 세단나는 현재 연습생들을 받고 있다고 생각합니다."
rows["134:126205173"]="저 사악한 트롤들이 영원히 평화롭게 지낼 거란 기대를 해서는 안 되는 거였습니다. 호드와 동조하는 자들은 믿을 수 없습니다."
rows["134:132270035"]="봉우리 하층에 있는 스톤후프 지질연구소로 가십시오. 브렉 스톤후프가 귀한 광석이나 보석을 캐내는 방법을 가르쳐 줄 겁니다."
rows["134:1407144148"]="릴리 제트, 준비해줘요, 뭔가 만들어야 해, 뭔가 고쳐야 해,"
rows["134:1559729895"]="순찰대원 바커스를 본 적 있나요? 얼마나 용맹스러운지...$B$B그가 모든 어둠의 순찰대원 중에서 제일 힘이 센 것 같아요. 내가 주변에 있다는 걸 그가 알기라도 할지 모르겠네요..."
rows["134:1633834213"]="사냥꾼의 홀에 가라.  ⁇ 코르 갈란트후프가 야만족을 훈련시키고 고호크 빅후프가 수호자들을 훈련시킵니다."
rows["134:1702707691"]="피부 벗기는 사람들은 보통 모든 피부를 아이언포지 가봐, 훈련할 수 있는 사람을 찾아봐"
rows["134:1749237902"]="그런 공적인 업무는 다르나서스에서만 취급합니다. 길드 창설이라면 그곳에 가서 알아보셔야 할 겁니다."
rows["134:1797260696"]="아주 간단해. 라스 프로스트위스퍼라는 강령술사에게서 그의 마력을 빼앗는 거지. 녀석을 다시 평범한 생명체로 되돌려 놓은 후에 영원히 처치해 버리는 거야."
rows["134:1835385800"]="래드날은 다르나서스로 가는 길에 집을 짓고 살고 있어요. 그 집 바깥에서 무두질을 하고 있는 그를 보실 수 있을 겁니다. 가르침을 받을 수 있을지 알아보세요."
rows["134:1874448016"]="주인님을 배신한 것은 라그나로스의 부관인 게돈과 가르였습니다. 썬더란께서는 영문도 모르고 변을 당하셨습니다."
rows["134:1926176712"]="그대가 충분히 주의하고 있으리라 믿는다...$b$b이곳은 위험한 곳이고, 만약 그대에게 무슨 일이 생겼더라면 난 자신을 용서하지 못했을 것이다."
rows["134:1950821973"]="어두운 시대는 이상한 우정을 만들어 냅니다. 로데론 이 포세이큰 그들의 작은 빗자루를 태워라"
rows["134:1991278861"]="웰던은 벼락 맞을 겁쟁이에 지나지 않소. 그 녀석은 스컬지에게서 도망치더니 영웅인 양 감히 이곳으로 왔단 말이지?$B$B흥!"
rows["134:2006559898"]="우리는 호드 고대 유수의 비밀들을 우리한테 반도할 수 있게 해"
rows["134:2034676612"]="가만히 앉아 기다리고 있어서야 전쟁에서 이길 수 없습니다. 거칠고 빠르게 밀어붙여야 합니다. 그렇지 않으면 아라시 분지를 영원히 되찾지 못할 것입니다."
rows["134:2057741342"]="당신은 바취로, 반타르, 굶주린 검은갈고리, 심지어 강력한 뿔엄니까지 모두 무릎 꿇게 한 장본인이오! 당신은 내가 알고 있는 최고의 사냥꾼이오!"
rows["134:2090510573"]="산들바람 마을이 아직 건재하다는 사실은 우리 종족의 근성이 강력하다는 증거입니다. 우리가 스컬지에게 또다시 패하는 일은 절대 없을 겁니다."
rows["134:2121482114"]="처음에 나무보다 큰 버섯을 봤을 때는 이곳을 꼭 집으로 삼아야 하나 싶었지. 하지만, 조금만 지나면 당신도 그냥 넘기게 될 거요."
rows["134:2141793040"]="오그리마에 한 명 있지. 그곳에 있는 그런트가 길을 더 자세히 가르쳐 줄 거야. 여기서 길을 따라 북쪽으로 가기만 하면 바로 보여."
rows["134:235843418"]="대장기술을 배우고자 한다면 불타는 모루에 있는 사루 스틸퓨리와 얘기해 보게. 명예의 골짜기로 들어가 붉은협곡 광부조합에서 오른쪽 길을 따라 끝까지 가."
rows["134:30487577"]="돌라나르 주변에는 그대에게 가르침을 드릴 상급자들이 여럿 있습니다. 그들은 오랜 경험을 가지고 있지요. 어떤 직업 상급자를 찾으시나요?"
rows["134:365310131"]="아, 사제라고 했습니까? 훈련이 필요하다면 인심 좋은 막산을 찾아가 보십시오. 지금쯤 썬더브루 양조장에서 한잔 하고 있을 겁니다."
rows["134:403693714"]="쉽게 끝나지는 않을 것 같군. 스트라솔름이 불타고 있다. 말가니스와 마주하려면 불길과 스컬지를 뚫어야만 해. 준비해라."
rows["134:41804932"]="돌라나르 근처에 사는 이들은 라우르나 모닝라이트에게 가서 치유를 받습니다. 사제의 길을 가신다면 그녀를 찾아가 보시는 게 좋을 것 같네요."
rows["134:486818329"]="길드를 창설하려고 하십니까? 아이언포지 사무소에 들러 필요한 서류 업무를 보셔야겠군요."
rows["134:491234792"]="자네는 나보다 더 많이 아는 자에게 배워야 하네. 언더시티로 가서 조셉 그레고리안과 얘기해 보게나. 아니, 어서 가지 않고 뭐 하는 건가?"
rows["134:536762297"]="내 작업장에 뭘 찾으러 온 건가? 훈련을 받고 싶나? 아니면 강철의 비밀이라도 캐러 왔나? 아니면 가열로의 신비를 파헤치러? 어서 말해 보게나!"
rows["134:555293005"]="저 소리 들리세요? 날이 갈수록 윙윙거리는 소리가 점점 커지고 있어요. 아무래도 수정이 벌레들을 흥분시키는 것 같아요."
rows["134:596696211"]="아, 정말인가?$b$b좋네. 자네와 함께하거나 자네가 속한 포세이큰의 일원이 되고 싶지는 않네. 직접 이끌 포세이큰을 내가 만든다면 모를까! 팔꿈치 살도 제대로 붙어 있는 포세이큰으로 말이야!"
rows["134:617650780"]="적의 도시로 순간이동하려 하진 마세요. 작동하지 않을 겁니다. 여기선 모두들 사이좋게 지내지만 그렇다고 해서 오랜 원한이 사라진 건 아니지요."
rows["134:617907581"]="저기요, 저기요! 적개심을 버리세요! 전 자주 마주치고 완전히 무해한 중립적인 고블린 중 한 명이란 말이에요! 호드네 고블린 아니거든요!"
rows["134:693277434"]="오늘날의 마법은 천 년 전의 마법에 비하면 보잘것없을지도 모릅니다. 하지만 우리 명가는 여전히 마법에 대한 방대한 지식을 보유하고 있습니다. 가르침을 받을 준비가 되셨습니까?"
rows["134:739766674"]="은행 말씀이십니까? 은행 업무를 볼 수 있는 곳이라면 스톰윈드 회계사무소지요. 그래도 이 부근에서 제일 가까운 곳일 겁니다. 스톰윈드에서 들어가서 조금만 길을 따라가다 보면 나오는데, 성문에서 그리 멀지 않습니다."
rows["135:1031845376"]="반갑습니다, 용사 여러분! 도저히 저놈을 끌어내릴 수가 없군요. 작살포로 놈을 끌어내리게 좀 도와주세요."
rows["135:1111939001"]="벨가리스트라즈 말이 맞아요. 시간이 부족해요! 당신 비룡은 이제 최고의 힘을 사용할 수 있어요. 그 힘을 사용해 에레고스를 물리쳐 줘요!"
rows["135:1142990934"]="마법부여사 에레다니아를 찾는다면 멀리 갈 필요 없이 살데릴이 축하 파티를 여는 장소로 가십시오. 며칠 전에 초대장을 받았다고 자랑했으니까 분명 그곳으로 갔을 겁니다."
rows["135:1151616219"]="인간들이 먼지진흙 습지대의 많은 부분을 점령했지만 돌망치 일족은 우리의 도움으로 그들을 몰아낼 수 있었소."
rows["135:1229630875"]="하지만 크로스로드 이 지역은 불모의 땅타우라조 캠프의 조용함을 선호합니다."
rows["135:1238145397"]="몽술사 하자라$B$B악몽의 힘은 그의 것, 그의 적들이 영원한 잠에 빠지기를.$B$B이제 하자라는 광란의 경계에서 꿈꾸고 있다."
rows["135:1266554287"]="정기의 봉우리 아래 예언의 웅덩이로 가서 마틴 린지를 찾아보십시오. 아라시 분지로 가는 걸 도와 줄 겁니다."
rows["135:1297742016"]="옷이라고!? 도끼와 검 앞에서는 무용지물일 텐데! 참, 나... 뭐, 재봉사가 되고 싶다면 골목길에 있는 마가르의 의류점에 가보게."
rows["135:1431870276"]="책들이 사라지고 있습니다. 로리키퍼와 그의 부하들은 광기에 빠져 있습니다. 그들은 엘드레'타라스 안에서 악행을 의심합니다."
rows["135:1437641287"]="당신을 보니 기쁘기 그지없군요! 이 녹슨 쇠구슬과 사슬을 끊어버리려고 했지만 전 힘이 없어서 말이에요.$B$B아니, 멀뚱멀뚱 보기만 할 거예요? 이것 좀 풀어주시죠!"
rows["135:1709159688"]="내가 마지막으로 들은 바로는 평온초는 $2020w개가 필요한데 $2021w개를 모았고, 화염초는 $2051w개 중 $2050w개, 보라 연꽃은 $2055w개 중 $2054w개를 모았다고 한다."
rows["135:174793057"]="필멸의 존재여, 용언을 배우려는 너의 노력은 헛수고로 돌아갔다. 도대체 왜 고대 언어를 배우려고 하느냐? 정말 이해할 수가 없구나..."
rows["135:178856411"]="자극적이고, 축축하고, 푸드덕거리는 못생긴 물고기와 시간을 보내는 게 그대가 찾는 즐거움이라면... 이 도시에 낚시꾼 한 명이 있긴 합니다."
rows["135:1909435398"]="숲은 변화의 씨앗과 함께 노래한다. 그렇지만 고통에 빠져 울기도 한다.$B$B우리의 새로운 동료인 드레나이도 그대와 같이 우리를 도우려고 이곳으로 왔다. 형제와 자매의 나무들이 종말을 맞고, 잿빛 골짜기가 사라지기 전에 이 파괴적인 행위는 종식되어야 한다."
rows["135:198919501"]="저는 마법에 대해서 잘 모르지만, 사자무리 여관에서 지내는 잘디마르라는 마법사가 당신을 도와 줄 수 있을 겁니다."
rows["135:203458186"]="넌 스티드 타운에 있는 사이먼 테너와 얘기해봐"
rows["135:2070159916"]="자네가 만드는 검날이 적의 복부를 꿰뚫기에 부족함이 없겠나? 무기의 날을 더욱 날카롭게 다듬는 법을 가르쳐주지."
rows["135:278046651"]="당신 내가 누군지 알고 있을 텐데요. 그런데도 날 귀찮게 한단 말입니까?$b$b무슨 일로 이 나를 귀찮게 하는 겁니까?"
rows["135:440582492"]="안녕하신가, 여행자 양반. 난 오로노크라고 하네. 여기 모닥불 근처로 와서 몸 좀 녹이게나.$B$B우리 아래 파괴된 대지 밑에 있는 탐욕스러운 짐승들을 조심하게!"
rows["135:534619062"]="역병지대의 참상과 희망의 빛 예배당 전투보다도 끔찍한 꼴을 보게 되리라곤 상상도 못 했어요.$B$B그런데 제 생각이 틀렸더군요."
rows["135:566319399"]="그렇게는 할 수 없소. 위험에 처한 타레사를 남겨두고 나 혼자 산으로 달아날 수는 없는 일이오. 나는 겁쟁이가 아니오. 자, 그녀는 어디 있소?"
rows["135:598642168"]="세 가지 장벽 모두 완전히 작동합니다. 선의 리치 항구에서 네툴 아치마지와 협의해 문의 잠금을 풀 수 있도록 도와주세요."
rows["135:700982648"]="그가 벌꿀술도 갖다 주고$B맥주도 갖다 줄 것이라네.$B입이 귀에 걸리도록 히죽대고 있는 얼굴$B해마다 변함없이 우리를 기쁘게 한다네.$B우리는 그를 유쾌한 짐이라 부른다네."
rows["135:703243253"]="원소의 정령들이 우리를 둘러싸고 있습니다. 우리는 언제나 귀 기울여야 합니다. 그들의 경고를 무시하면 어떤 일이 벌어지는지, 저는 경험으로 잘 알고 있습니다..."
rows["135:772727305"]="크아, 나도 한잔 들이켜면서 쉬고 싶군. 칼바위 언덕 북서쪽으로 가보게. 도착하면 여관주인 그로스크에게 내 안부나 전해 주게."
rows["135:777306117"]="<종소리처럼 은은히 마음속에 울려 퍼지면서 안도감을 주는 아달의 음성>$B$B열쇠를 그대의 가방 안에 넣어놓을 테니 아무 걱정하지 마시오."
rows["135:818288335"]="<종소리처럼 은은히 마음속에 울려 퍼지면서 안도감을 주는 아달의 음성>$B$B열쇠를 그대의 가방 안에 넣어놓을 테니 아무 걱정하지 마시오."
rows["135:981821208"]="필멸의 존재여, 난 네가 나를 조롱하고 있다는 것을 모를 정도로 어리석지는 않다. 그러나 사실이다. 너의 말은 대부분 맞다만 옷은 아무리 많이 입어도 상관없느니라."
rows["136:1092962959"]="렘트래블 님께서는 거의 40여 년간 고고학계에서 영웅이셨어요. 그분이 일화들을 기억하실 수 있다면... 오, 그분이 얘기해 주셨을 이야기들..."
rows["136:1106504461"]="아델 필더는 엘윈을 둘러싼 가죽 노동자로 이름을 알렸다."
rows["136:1152824410"]="자네가 데리고 있는 야수라면 손차가 잘 돌봐줄 걸세. 명예의 골짜기에 가면 용맹의 투기장과 사냥꾼의 전당이 있는데 그 사이에 있는 우리에 있지. 그럼 어서 가보게!"
rows["136:1195649688"]="은빛 서약단에서는 이번 마상시합에 참여하는 당신을 환영하는 바입니다. 은빛십자군에서는 우리 서약단에서 이번 시합에 흥미가 있는 자들의 신청을 받고 훈련을 맡아 달라고 요청했답니다."
rows["136:1323615741"]="태양샘을 통해서 킬제덴이 되돌아온다면 우리는 지난 만 년 동안 겪어본 적이 없는 전쟁에 직면하게 될 거요!"
rows["136:136181655"]="매타조는 고귀한 생물입니다. 언제나 성심을 다해 다뤄야 합니다. 화난 매타조보다 위험한 것도 없으니 말입니다."
rows["136:1383090365"]="역병이 오기 전에는 가죽의 가라는 글자도 몰랐답니다. 이젠 다른 이들을 충분히 가르칠 수 있을 정도로 알고 있지요. 죽으니 할 일이 없더라고요."
rows["136:1422739082"]="샤프비크는 에리 피크에서 가장 훌륭한 기리폰이야 지нта'알로르의 정상까지 데려다 줄 거야"
rows["136:1442625526"]="이 먼 곳에서 알도르의 친구를 만나다니 정말 반갑습니다. 이 엘프들이 건방지게 떠들어 대는 소리를 참는 것도 곧 한계에 도달할 것 같군요."
rows["136:1470669574"]="절대로 얼라이언스가 아라시 분지에서 세력을 확대하게 내버려둬선 안 돼! 저 조그마한 임시 주둔지가 커져서 훗날 우리 목숨을 위협할 수도 있는 일 아닌가!"
rows["136:1475299431"]="Zipgear Zoombang는 기술공 타운에서 문에서 동쪽에 있습니다."
rows["136:1537849166"]="드루이드라고요? 이곳에는 상급 드루이드가 없습니다만... 엑소다르 근처에 가면 당신의 설명과 일치하는 이가 있다는 말을 들은 것 같습니다. 샬란니우스라는 이름의 나이트 엘프입니다."
rows["136:1644142182"]="썬더마는 와일드해머 부족의 마지막 보루입니다. 이 작은 마을이 피난민으로 가득 차는 사이, 우리 형제들은 계속해서 싸워나가고 있어요."
rows["136:1672472282"]="이 분야에서 나를 능가하는 실력을 갖춘 이가 하나 있지. 자네 그 여자의 지식을 전수받을 준비가 됐군. 안노라라고 하는데, 울다만...에서 만날 수 있을 거야."
rows["136:1695181962"]="내가 알고 있는 한 가지 분명한 사실은, 좋은 친구는 언제나 믿을 수 있다는 것이지. 그대에게도 이런 사람이 있다면, 항상 아껴줘야 하네."
rows["136:1814971117"]="어서 오세요! 노움 기계공학 설계도를 이용하려고 오셨다면, 잘 오신 겁니다. 우리 측정기 결과로는 당신이 인증된 노움 기술자시니까요!"
rows["136:1901093998"]="동부에서 은행을 찾고 있다면 왕립 거래소에서 더 이상 찾지 마세요."
rows["136:1907845369"]="아아, 그거 말이군. 보자, 요즘은 야영지 주변에 있는 오크 그로그주 말고는 아무것도 없더라고.$B$B내 입맛에는 좀 안 맞는 것 같지만 말이야. 내 말이 무슨 뜻인지 알겠지..."
rows["136:1994764380"]="이 분야에서 나를 능가하는 실력을 갖춘 이가 하나 있지. 자네 그 여자의 지식을 전수받을 준비가 됐군. 안노라라고 하는데, 울다만...에서 만날 수 있을 거야."
rows["136:201265363"]="이 도시는 전쟁에서 탈출하기 위해 세워졌어요. 이 땅을 순찰하는 경비자들은 요새일 뿐이죠. 하지만, 예, 저는 그들의 장군입니다."
rows["136:2018132471"]="뭐가 어떻게 된 건지 모르겠군. 원한의 초소에 도착했다고 생각했는데 막상 깨어나 보니 이 철창에 갇혀 있었지 뭔가!$B$B날 구해주러 왔나?"
rows["136:2032066924"]="영웅들이여, 용서하세요. 우서 경의 말을 들었어야 했는데. 직접... 확인해야만 했어요. 마지막으로 그의 눈을 들여다보고 싶었어요. 미안해요."
rows["136:2116020539"]="정말 대단하군요! 그런데 골짜기에서는 어떻게 빠져나왔죠? 누군가 당신을 찾으러 수색대를 보내기 전에 돌아가는 게 좋겠군요."
rows["136:221497439"]="피즐, 포직, 징키... 모두 자신이 우리를 살렸다고 생각하지. 하지만 진짜 구원자는 바로 나야! 내가 이 배를 만들었거든!$B$B이 배는 원래 래저릭의 쾌속선이라 불려야 한다고!"
rows["136:284492632"]="샤타르에서는 어둠달 골짜기와 일리단의 일에 집중하고 있지만 우리 알도르 사제회에서는 캘타스 선스트라이더의 위협을 무시할 수 없습니다."
rows["136:445520125"]="서둘러요! 멕카토크 님과 대화를 나누어야 한다고요! 공격을 빨리 시작하지 않으면, 우린 늦고 말 거예요.$B$B국왕 님은 늦는 거라면 질색을 하신다고요!"
rows["136:446949541"]="사막유랑단과 그들의 지도자인 칼리프 스콜피드스팅이 남쪽으로 가는 걸 봤어. 조심해야 할 거야. 놈들은 조금 더 강해진 것 같이 보이더라고!"
rows["136:568265225"]="우리의 뇌 해커가 경매에서 팔렸는지 확인해봐야 합니다."
rows["136:581070461"]="이곳을 드나드는 관광객들을 모두 돌봐줄 정도로 제가 시간과 정력이 남아도는 줄 아십니까? 어서 용건만 간단히 말씀해 보십시오."
rows["136:616091601"]="알렌 브라이트를 사설 근처 스파링 링에서 찾아라\013\010\013\010\013\010\013\010그는 과 박사 구스타프 반하우젠이 섬의 치료사들의 훈련을 감독합니다."
rows["136:629834377"]="마력 깃든 토륨은 많은 이들이 찾는 금속이죠. 그걸 찾으려면 대장장이나 광부에게 물어보는 게 가장 빠른 길일 것입니다."
rows["136:641823766"]="히포그리프를 타시려면 일단 다르나서스로 가신 다음, 텔드랏실의 숲 가까이 있는 루테란 마을로 통하는 문을 지나세요."
rows["136:70075256"]="확실히 이 지역 분은 아닌 듯한데... 뭐 어쨌든 상관없습니다. 누구든 간에 여기서 자기 역할만 확실히 해준다면, 전 기꺼이 그자를 위해 목숨을 걸 겁니다."
rows["136:713556734"]="두 사람은 달의 성전에서 환영받습니다. 코린티아 성전사와 달의 사제 타이러라는 별자리들의 하위 홀에서 가르칩니다."
rows["136:865921150"]="겨울발굽 야영지를 그리워하겠지만 애쉬토템 족장님께서 이런 결정을 내린 까닭은 이해한답니다. 고향이 주는 편안함을 죽을 때까지 누릴 수는 없는 법이지요."
rows["137:1043586437"]="우리 동족들은 얼마 전에 여기 왔답니다. 그들과 나의 연결 고리가 갈수록 희미해져 가고 있습니다. 안쪽에 있는 강력한 존재가 앞으로 나아갈 길을 수호하고 있으니 조심하십시오."
rows["137:1195777990"]="나 애완용 지옥사냥개 있으면 좋겠다. 먹을 거도 주고, 막대기 던지기 놀이도 하고, 잘 놀아줄 수 있는데. 흑마법사? 도시 외곽의 마법 지구에 있다."
rows["137:1234431400"]="모험가들은 은빛 자치구나 선리버 성소에서 정의로운 업적을 보상받을 수 있답니다."
rows["137:123888534"]="이 기지는 기어를 쓰지 않는 곳이지요. 기계 장치를 만들 때 기어를 사용하는 이는 계속 놀림거리가 될 걸요."
rows["137:157583755"]="꿈술사 하자라.$B$B악몽의 힘은 그의 것이니, 적들에게 영원한 잠을 안겨 주길.$B$B하자라는 이제 광기의 끝자락 가까이에 머물고 있다..."
rows["137:1618133342"]="주위를 둘러보라, 주술사여. 대지, 바람, 물, 불, 그리고 이 모든 것과 관계를 맺고 있는 정령들의 균형이 보이는가?"
rows["137:1640257789"]="우리 경주차의 행렬 열도계에 새로운 장치를 설치했소. 마하 15는 거뜬히 나올 거요!"
rows["137:1850021338"]="무기 기술을 향상시키고 싶으신가요? 우리의 무기 전문가들은 교역 지구의 최상층인 전사의 정원에 있습니다."
rows["137:1873407144"]="이거 소름끼치는군요.$B$B전 이곳에서 우리 자신의 불편에는 아무런 관심이 없습니다만 해골 무덤에 만연한 죽음의 공포를 완화하기 위해서 뭔가 해야만 합니다!"
rows["137:2048915944"]="저브 ⁇ 이 돌아왔을 때 너무 행복해 난 다크 아이언 맥주도 곧 끝나지 않길 바랄 뿐이야"
rows["137:2100371484"]="그건 당신이 소환해서 부하로 만들기를 원하는 악마의 종류에 따라 다르다오. 우리는 암흑의 마력을 이용하고 그에 따른 큰 대가를 치러야 하는 것이지."
rows["137:2135645655"]="구루바시 공격자들은 계속 들어오고 있습니다. 우리는 여기 갇혀 있고, 며칠 동안 외곽 포스트로부터 소식도 받지 못했습니다."
rows["137:2140210329"]="파수꾼들이 숲 속을 순찰하다가 다치면, 보통 비얀시에게 간답니다. 응급치료를 배우고 싶으시다면 비얀시를 찾아가 보세요."
rows["137:24519051"]="우리는 얼라이언스 고대 유수의 비밀들을 우리한테 반도할 수 있게 해"
rows["137:749352089"]="좋아. 표본에서 살점을 더 잘라내 보게. 자, 이제까지 배운 것을 시험해 볼까나. 시험을 기초로 더 많은 것을 배울 수 있을 걸세."
rows["137:793106345"]="아서스는 한 때 인간 왕자였어요. 그가 노스렌드로 끌고 온 군대는 끔찍한 운명을 맞이했지요.$B$B우리 오빠 타사리안도 그 군대의 일원이었어요."
rows["137:811321829"]="어떠한 위험이 있더라도 스승님의 명령을 수행하려고 이곳에 왔소. 어린 소녀의 목숨이 위태로운데 무슨 일이 이보다도 중요하겠소?"
rows["137:818688526"]="<투덜투덜> 비행선이 바다에 추락하는 건 있을 수 없는 일이라고 생각하시겠지요. 네 번이나 그랬다면 더 믿어지지 않으실 테고요!"
rows["137:957576861"]="안전보증 순간이동기가 당신을 떨어뜨리지 않기를 바랄게요! 물론 그럴 리는 없겠지만 만일을 대비해서 낙하산 망토를 가져가시는 게 좋을 거예요!"
rows["137:984188588"]="안녕하세요! 초특급 대포로 재빨리 순간이동할 방법을 찾고 있지는 않았겠죠?$B$B왜냐하면 그건 바로 제가 하는 일이니까요!$B$B물론 돈을 좀 주시긴 해야죠..."
rows["137:999110339"]="파티마는 우리 수도자로서 추락 사고로 다친 이들을 돌보는 데 큰 역할을 하고 있답니다. 그녀는 하늘 감시초소의 서쪽에서 일을 하고 있으니 그리로 가면 만날 수 있을 겁니다."
rows["138:1296745085"]="당연히 칭송받을 일입니다. 곧 티리온 님께서도 직접 여러분을 치하하실 겁니다. 어라, 갑자기 좀 추워지는 것 같지 않나요?"
rows["138:1367342701"]="어서 오게나! 고블린 기계공학 설계도는 허가 받은 고블린 기술자만이 이용할 수 있다네."
rows["138:1450590391"]="언더시티 병력 대부분이 노스렌드에 있는 복수의 상륙지로 배치된 상황이어서, 대족장님께서는 언더시티 방어를 지원하도록 우리를 보내셨네."
rows["138:1454656010"]="징검다리 거점은 더할 나위 없이 튼튼하니 걱정하지 마십시오! 그러나 만약의 상황에 대비하여 그리핀에 올라탈 준비를 하십시오. 이 땅이 조각날 수도 있으니까요..."
rows["138:1654776130"]="여분의 보급품이 거의 없소. 투쟁의 벌판으로 다른 지상 공격 부대를 보낼 수 있으려면 훨씬 더 많이 노력해야 할 거요."
rows["138:1742337357"]="저는 여기에서 지원군이 더 올 때까지 시간을 끌어 보겠지만, 그대들은 계속 움직여야 해요.$B$B우리가 여기 있다는 것을 아서스가 알아차릴 때까지 시간이 얼마 남지 않았어요."
rows["138:1754925046"]="해적과 켄타우로스, 그림토템 부족도 모자라서, 맙소사!$B$B어젯밤에 커다란 뭔가가 제 머리 위로 날아가는 걸 봤어요. 크기가 얼마나 어마어마한지, 달을 가릴 정도였다니까요!"
rows["138:1806673339"]="가죽세공인을 찾으신다면 아이언포지로 가보는 게 제일 좋을 겁니다. 제 기억이 정확하다면 대용광로 근처에 그런 상점이 하나 있답니다."
rows["138:1857897364"]="이거 정말 골치 아픈데요! 쓰레기 같은 놀들이 광산을 점령했는데 어떻게 마법학자께 광석 견본을 모아가죠?"
rows["138:1877082716"]="우리는 버림받은 자들에게 지나치게 자비를 베풀고 있습니다. 놈들에게 따끔한 맛을 보여 줘야 합니다.$B$B해돋이 부두에 있는 뻔뻔한 녀석들을 절대 용납할 수 없습니다."
rows["138:1922636416"]="우리 적이 한 발자국이라도 전진하도록 둬서는 안 됩니다. 저들이 어둠해안을 습격하면, 바로 반격하여 놈들이 공격한 곳이 다르나서스인지 의심하게 만들어줄 겁니다."
rows["138:1953123325"]="경매장 말입니까? 아이언포지 성문 근처에 있습니다. 아이언포지 사설금고 바로 맞은 편이랍니다."
rows["138:1971967933"]="붉은색 조각상이 당신이 가지고 있는 파수꾼의 졸과 많이 닮았습니다.$b$b조각상에는 당신의 졸과 크기가 똑같은 홈이 있습니다."
rows["138:2013309816"]="비코르 썬더 아이는 물과 공중에서 가까이 있고,"
rows["138:2133356892"]="그들은 너무 많더군요... 우리가 한 공격은 겨우 진형을 흐트러뜨렸을 뿐입니다. 많은 사람이 죽었어요! 일이 터지고야 말 거예요..."
rows["138:219963604"]="데스윙이 우리 세계로 들어오면서 아제로스와 심원의 영지 사이에 균열이 생겼다네.$B$B세계 기둥을 복원하는 것이야말로 균열을 안정시킬 유일한 방법이네."
rows["138:347027573"]="그런 것 같군. 너희와 친구들은 언제든지 와서 가져가도 좋아. 아마 꽤 단단할 거야. 자주 나오는 건 아니거든."
rows["138:39066524"]="전투장에서 경쟁자들을 물리쳐야 합니다. 승리에 따라 금메달이 보내질 가능성이 있습니다."
rows["138:414520168"]="또 다른 치명적인 적의 탄생을 축하하는 것은 이상하긴 하지만, 우리는 동맹국들과 함께 그들의 축제에 참여할 것입니다."
rows["138:415937221"]="케일스 다운브랜드는 템플러들을 훈련시키고 있습니다."
rows["138:591088001"]="이 유물은 여러 번의 풍파를 거친 듯 크게 파손되었습니다. 예전의 힘을 아직 담고 있지는 않을 것 같습니다."
rows["138:659243585"]="대지와 바다가 크게 변하고 있습니다. 당신도... 그들도... 많이 변하고 있지요.$B$B카마구아가 사는 방식도 이런 변화 때문에 위험에 처했습니다. 어떻게 하려고 하십니까?"
rows["138:720061259"]="아웃랜드의 모든 지역이 이곳처럼 황량하지는 않기만 바랍니다. 영원노래 숲의 녹색 초원과 숲은 확실히 변했습니다."
rows["138:831904784"]="전사의 역할 중 하나는 보호일세. 전장에서 전우를 보호하듯이 우리는 포세이큰의 이권을 보호해야만 하는 것이지."
rows["138:92228610"]="루퍼트 보흐가 있어요. 그랑 그의 동원은 브릴 남동쪽의 겔로우스 엔드 타버너에 있는"
rows["138:940470462"]="아... 또 한 명의 주술사가 지혜를 구하고 있군요. 영혼들의 말이 분명하게 들리지 않나요? 운명을 점쳐 드릴까요?"
rows["139:1065890487"]="가죽 세공인을 찾으신다면 아이언포지로 가보는 게 제일 좋을 겁니다. 제 기억이 정확하다면 대용광로 근처에 그런 상점이 하나 있답니다."
rows["139:1096841596"]="저주받은 잃어버린 드레나이를 도와준 점 다시 한번 고맙게 생각하네. 자네의 도움이 없었다면 내 연구를 계속 할 수 없었을 걸세."
rows["139:1238629644"]="제가 기술을 가르쳐 드리기에 앞서 마상시합 탈것을 타셔야 합니다.$B$B창을 착용하고 당신 진영의 막사 밖에 있는 마상시합 탈것을 찾아보세요."
rows["139:1240314878"]="몰래 좀비에 접근할 수 있겠어요? 가까이 가면 당신 뇌 냄새를 맡지 않을까요?$B$B이 근처에 있는 이들 절반에게는 걱정할 뇌가 아예 없지만요."
rows["139:1420761640"]="다른 데 찾아봤자 실속 없이 돈만 낭비할 뿐이지... 굴뚝나무 목장조합에서 맛있는 요리를 사서 즐거운 겨울맞이 축제 보내라고!"
rows["139:1437153447"]="심하게 부상을 당했지만, 나도 할 수 있는 데까지 해보겠습니다. 대마법 보호막 안에 있으십시오. 안 그러면 저 수행사제들의 마법이 그대를 갈가리 찢고 말 테니까요."
rows["139:1454729529"]="아직 모든 방법을 시도해본 것은 아닙니다. 이 상황을 벗어날 수 있는 방법을 한 번 생각해 봅시다."
rows["139:1526179436"]="흥, 그런 건 고블린이나 손을 대는 일인데! 뭐, 그래도 이 칼바위 언덕에도 그런 걸 가르쳐 줄 오크가 한 명 있긴 해. 가열로 근처에 있는 머크드락을 찾아보게."
rows["139:1667481174"]="여관에서 사탕이랑 맛있는 걸 준대요! 원장님이 그러시는데 우리한테 사탕 안 주면...장난을 쳐도 된대요!"
rows["139:178052517"]="여길 벗어나고 싶은 심정 이해하네. 꼭대기까지 올라가 지상으로 나가서, 폐허 북쪽으로 향하게. 거기 있는 두 개의 탑에서 비행선을 탈 수 있지."
rows["139:1797565340"]="반갑습니다, 용사 여러분! 도저히 저놈을 끌어내릴 수가 없군요. 작살포로 놈을 끌어내리게 좀 도와주세요."
rows["139:1854419885"]="<고개를 끄덕이는 에리스>$B$B어둠의 눈은 수많은 공포와 기적을 보아왔어요.$B$B어둠의 눈은 그것을 들여다보고 있는 자에게 가장 적합하다고 느끼는 것을 보여주죠."
rows["139:1978840191"]="목사가 되고 싶으세요? 이스트벨 목사 캠프에 목사가 있다고 생각합니다.  "
rows["139:2121571607"]="그대의 기술은 이제 내 기술을 앞질렀습니다. 길모퉁이 근처에 던컨의 옷가게의 주인인 조르지오 볼레로가 그대의 기술을 향상할 수 있도록 도와줄 것입니다."
rows["139:2140062047"]="네, 정말 멋졌어요!$b$b사령관님은 아주 자신감에 넘치시고, 그리고 그 말투는 또 어찌나 멋진지! 솔직히 말해서 정말 매력적인 분이세요.$b$b그 분 결혼하셨는지 혹시 알고 계세요?"
rows["139:215642181"]="골드린 님의 강인함은 전설 그 자체입니다.$B$B모든 지역의 전사들이 골드린 님 같은 힘을 얻길 기원하며 이 제단을 방문합니다."
rows["139:285055127"]="이 여신의 눈물은 엘룬의 축복을 받은 것으로 아키몬드의 사악한 마법에 대항할 힘을 드릴 것입니다. 잘 사용하십시오."
rows["139:295994359"]="자세를 낮춰! 내가 여기 있는 걸 놈들에게 들키기 싫단 말이다.$B$B우, 이거 정말 화나는데! 저 에테리얼들은 도대체 무슨 권리로 그런 생각을 하는 거야?$B$B이건 내 거라고!"
rows["139:328391990"]="여기 얼음왕관 성채 안에 있는 전쟁노래 공격대와 함께라면, 승리는 우리 손안에 있다! 리치 왕을 처치하고 호드에 영광을 안기리라!"
rows["139:457929411"]="뭐? 하지만 어떻게? 아냐! 그럴 리가 없어! 그렇게 주의를 했는데... 알 수 있을 리가 없잖아!$B$B네 말은 거짓이다! 거짓말로 속이려 들다니 죽여 주마!"
rows["139:478729664"]="원래부터 카라잔이 그렇게 불길한 느낌이 들만큼 조용한 곳은 아니었답니다. 카라잔의 운명에 암흑이 드리운 것은 메디브가 죽고 난 이후부터였습니다. 우리는 메디브가 죽었다고 믿었지요."
rows["139:483850696"]="우리 히포그리프 조련사는 스테파노스입니다. 그는 엑소다르의 중심지에 있습니다. 당신의 여행에 성스러운 빛이 함께하기를."
rows["139:508935281"]="뒤틀린 황천이 꽈배기같이 매듭지어진 모양인가요? 그리고 그 황천이 뭔가요? 보육원 원장님이 말씀하시길 사람에게 황천에 대해서 물어봐서는 안 된다고 하셨긴 하지만..."
rows["139:528996192"]="눈치가 좀 느리군? 흠, 자네가 만약 야수 관리인이라면 어디에 있겠나? 마구간 근처로 가서 모르가누스를 찾아보게."
rows["139:571845365"]="시간제 직원이라도 고용해야겠어요. 온종일 여기 앉아 낚시용품이나 파는 건 정말 지겹군요. 장사보단 낚시가 제 적성에 맞습니다."
rows["139:586208698"]="전투장에서 경쟁자를 물리쳐야 합니다. 승리에 따라 금메달이 보내질 확률이 높습니다."
rows["139:680349409"]="마법사의 길을 가는 것은 정말 험난합니다. 많은 사람이 우리를 이해하지 못하니까요. 우리와 같은 마법사들조차도 그 능력을 받아들이려고 많은 노력을 기울인답니다."
rows["139:705965554"]="지팡이 사용법이라면 하나시가 잘 알지. 좀 더 엄한 스승을 찾는다면 썬더 블러프로 가보게. 그곳 중앙의 하층 봉우리에서 안세크화가 제자들에게 가르침을 내리고 있으니까."
rows["139:754000955"]="<혼자 힘으로 일어나는 것은 무리인 듯 얼굴을 온통 찡그린 채 바닥에 누워있는 포세이큰 여인>"
rows["139:772364075"]="오랜 기다림 끝에 겨우 이곳에 흩어진 폐허들을 연구할 수 있게 되었습니다... 돈에 미친 이 조그만 작자들이 그곳을 망쳐 놓지만 않는다면 말이죠."
rows["139:820190763"]="이 얼라이언스 놈들, 끈질긴 것만은 인정해야겠어! 포세이큰 병사가 가득한 구축함에 뛰어들다니... 이건 자살행위나 마찬가지야."
rows["139:886974455"]="저는 고르목 대신에 이 생명체들을 돌보고 있습니다. 전 이런 학살에 동의하지 않습니다만, 어쨌든 고르목은 자기가 원하는 대로 싸울 수 있을 겁니다."
rows["13:1077178813"]="그렇게 빨리 돌아왔어?"
rows["13:1206334169"]="멀록들이란, 흥!"
rows["13:123574028"]="원하는 게 뭐야?"
rows["13:153664524"]="무적이라고요?"
rows["13:1741730394"]="안녕하세요 친구"
rows["13:1827402853"]="안녕하십니까!"
rows["13:1931245964"]="저리 가라고요, 친구."
rows["13:1934630729"]="임시"
rows["13:2139281337"]="안녕, 안녕하신가!"
rows["13:268298032"]="이거 놀랍군!"
rows["13:281124763"]="실바나스를 위하여!"
rows["13:920103877"]="내 길을 가고 있어?"
rows["140:1055866151"]="드디어 기다리던 지원이 왔군요! 스내글볼트가 요청한 서류는 준비해놨어요. 이제 남은 일은 서류를 전달하는 분 몫이지요."
rows["140:1138565205"]="자, 자, 어서 들어오세요. 난로에는 너무 가까이 앉지 않는 게 좋습니다요, 손님. 오늘은 아직 불이 나지 않았지만 제 생각엔 다른 곳에 앉으시는 게 안전할 거 같습니다."
rows["140:1166184356"]="자네가 내 형제들에게 갈 길을 열어 주었다는 게 느껴지는군. 내 형제들과 사원으로의 내 연결은 아직 강하다네. 사원 내부의 더 깊숙한 곳을 탐험하고 싶은가?"
rows["140:1211740685"]="두그루 고어러스트는 마을 동쪽에 있는 병영 뒤편에 숨어 있지. 그는 왜 찾는가? 당신 혹시 불타는 군단과 한통속이야? 그런 일은 없길 바라네. 그렇다면 내 손으로 당신을 체포해야 하니까 말이야."
rows["140:1242817675"]="화강암 웅덩이에 어서 오시오.$b$b얼음 트롤을 생포하거든 내게 꼭 알려주시오. 현상금을 두둑하게 드릴 테니."
rows["140:1247237769"]="거대한 새를 타고 하늘을 날아오르는 건 참으로 멋진 일이지요. 와이번 횃대 꼭대기에서 탈을 찾으십시오. 당신이 가고자 하는 곳으로 보내 줄 겁니다."
rows["140:1249666162"]="여기 빅시가 투척 무기를 던지는 방법에 대해서 알려줄 겁니다. 다르나서스가 더 가까우시다면, 그곳의 전사의 정원에 있는 일예니아 문파이어를 만나보십시오."
rows["140:1311318404"]="스톰윈드에 사냥 기술로 명성을 떨친 드워프가 한 명 있다고 들었습니다. 그를 찾아가면 될지도 모르겠군요."
rows["140:1403737145"]="교대하러 왔소? 시간이 다 된 것 같은데... 혹시 교대해 줄 마음이 들면 내게 말해 주시오. 술이나 몇 잔 마시게."
rows["140:1438230370"]="그 대왕 오징어 녀석, 어림도 없었죠. 베른호는 벌써 재무장을 하고 다시 나갈 준비를 마쳤어요... 지금은 기다리죠.$B$B녀석은 돌아올 거예요.$B$B두고 보자고요."
rows["140:1469629671"]="그냥 일반적인 호박 조각도 역병 가마솥에 들어가면 부패와 역병의 원천이 되지!"
rows["140:1567071408"]="이 보급품이 어디서 오는지 도무지 모르겠어요. 어찌 됐든 황혼의 망치단이 산 전체를 한번에 공격할 방법을 찾은 것 같군요..."
rows["140:1626375619"]="진흙 구덩이 바닥 따위를 청소하지는 않겠어. 이 점은 분명히 해 둘 테야!$B$B저 쥐새끼는 당신이 좀 처리해 줘. 무역왕 말이야!"
rows["140:1691871391"]="얼라이언스 증기 쇄빙선 북해의 창날호는 이곳에서 동부 왕국에 속한 바다를 지나 저습지에 있는 메네실 항구까지 항해합니다."
rows["140:1754772625"]="마상시합 탈것을 타지 않고서는 내 조언은 자네에게 쓸모없네.$B$B창을 착용하고 자네 진영의 막사 밖에 있는 마상시합 탈것을 잡아타게나."
rows["140:1790510609"]="이게 마지막입니다! 놈들이 최후의 공격을 벌이고 있습니다. 이젠 도망갈 곳도 없습니다. 우리는 썬더마를 지켜내거나, 아니면 망치를 손에 쥔 채로 전사할 것입니다.$B$B와일드해머를 위하여!!"
rows["140:1877283913"]="제발 내 상태 좀 배려해주게나. 지난 며칠간 힘든 나날을 보냈으니 다른 말은 하지 않았으면 좋겠군."
rows["140:1909969605"]="뭘 원하는 거요? 말해보시오. 우리 종족에 대한 당신의 헌신과 우정을 증명할 때까지는 내 엘레크를 내놓을 수 없소."
rows["140:2113244658"]="마법사 지구에 있는 마법사의 성소로 가면 스톰윈드의 저명한 마법사들이 모여 있습니다. 그 멋진 곳과 비하면 우리 경비병 거처는 완전히 돼지 우리나 다름없어요."
rows["140:2113510870"]="봉우리 중간층에 있는 베나의 연금술점에 가서 베나와 얘기해 보도록 하십시오. 그녀가 물약 제조 기술을 완벽히 터득할 수 있도록 도와줄 겁니다."
rows["140:285154358"]="이곳이 어둠의 의회의 작전 기지가 되었으면 좋겠어요. 이상하게 들리실 테지만 어둠의 미궁이 그립네요."
rows["140:345231911"]="진짜 머리 좋은 기술자가 누군지 아나? 바로 노그지! 나보다도 머리 회전이 빠르다니까. 노그에게 가서 선드가 보냈다고 하게! 바로 저기 기계 장치 제어판 앞에 서있으니까..."
rows["140:34538153"]="도와주시오! 나는 일행과 함께 트롤들에게 붙잡혔소. 놈들은 우리를 희생 제물로 바치려 하고 있소!$B$B여기서 빠져나가게 해주면 당신이 원하는 것은 뭐든지 해주겠소."
rows["140:511427574"]="매날개 광장의 남동쪽 모퉁이로 가면 델라니엘이 운영하는 좋은 여관이 있소. 따뜻한 음식과 숙성된 포도주, 그리고 포근한 침대... 이 정도면 충분하지 않겠소?"
rows["140:513213240"]="마른땅 동쪽에 뭔가 큰 게 만들어지고 있어.$B$B그게 뭔지는 모르겠지만, 빨리 끝나서 더 나은 곳으로 재배치됐으면 좋겠군."
rows["140:68924970"]="텔드랏실의 해안에서 잡히는 물고기는 매우 크고 기운차답니다. 소문에 따르면 우리 세계수가 빨리 자라는 것이 그 원인이라고 하는군요."
rows["140:740218364"]="이렇게 싸움을 많이 하는데 칼바위 언덕에 응급치료사가 없겠나? 동쪽에 있는 병영 안에서 로울크를 찾아보게."
rows["140:749496555"]="저는 이 글은 '이탈주민의 요새'로 번역될 수 있을 것 같습니다.$b$b다른 사람들은 다른 이름으로 알고 있습니다. Erenjhol, 즉  ⁇  기적. ⁇ "
rows["140:812105290"]="그렇소, 그 녀석들을 직접 본 적은 없지만 가끔 멀리서 녀석들의 소리가 들리오. 안으로 들어가게 된다면 녀석들을 조심하시오."
rows["140:837291945"]="내가 전에 껍질 한 덩어리를 줬지?$B$B어쨌든, 그 악의  ⁇ 돌이 똥구리의 무자비한 손목에서 구출되어서 기쁘네요!"
rows["140:909115876"]="감히 우리 국왕 폐하를 포로로 삼다니!$B$B돌난로를 되찾은 다음, 전초지를 가로질러 적진에 있는 바위 트로그들을 쓸어 버리겠다!"
rows["140:980389821"]="이건 당신한테나 나한테나 시간 낭비야! 훈련을 시작하고 싶거든 그레이엄 반 탈렌을 찾아가 보게! 그 친구는 저기 내 왼쪽에 서 있으니까 말이야."
rows["141:1004664925"]="망치와 모루를 잡고 뜨거운 용광로에서 일하는 법을 배우고 싶으시군요? 그렇다면 봉우리 하층의 연못가에서 대장간을 하고 있는 카른 스톤후프가 잘 가르쳐줄 수 있을 겁니다."
rows["141:117536037"]="밖에 일은 잘 돼 가나요? 풀려난 노예들과 대화하려고 하는데 정말 머리가 아프네요.$B$B다들 정신이 오락가락해요.\010"
rows["141:1188665059"]="월 축제의 가장 큰 축제는 무롱라드에서 열립니다. 드루이드는 썬더 블러프의 고령 상승에서 당신을 데려갈 것입니다."
rows["141:1485322050"]="이제 당신은 내게 배울 수 있는 걸 다 배웠습니다. 당신은 오그리마에 있는 마가르를 찾아가야 할지도 모르겠군요. 성질이 불같은 게 탈이긴 하지만 당신을 도와주기는 할 겁니다."
rows["141:1491987558"]="당신은 아직 준비가 덜 됐군요. 저기 계단 옆에 서 있는 베티 퀸과 얘기해 보도록 하고 좀 더 실력을 쌓은 후에 내게 다시 오도록 하십시오."
rows["141:1594384367"]="일단 주술사가 되면, 주술사가 얼마나 좋은지 알게 되지.$B$B불의 정령이 이렇게 유용할 줄은 몰랐어. 벌주기도 쉽고 말이야. 그냥 물만 좀 부으면 되니까."
rows["141:1730203765"]="여기서 나간다는 것은 겁도 없이 아라 마나괴철로 근처에 간다는 뜻이겠군요.$B$B죽기 전에 먼저 사거나 팔 물건은 없습니까?"
rows["141:1803629208"]="전 이 숲을 제 몸의 한 부분처럼 속속들이 다 알고 있답니다. 하지만, 아직도 숲에는 배워야 할 것들이 더 많고 수많은 위험 또한 도사리고 있습니다."
rows["141:1966693071"]="여긴 참 특이한 곳이에요.$B$B지맥을 바로잡으려고 제가 지금 사용하는 마법은 원래는 절 갈가리 찢을 만큼 강력한 마법이거든요. 그런데 이렇게 몸이 가뿐하다니!"
rows["141:1977871387"]="당신은 이미 사랑을 찾은 것 같군요. 제게 사랑의 징표를 주신다고 해도 좋은 선물은 안 드릴 거예요. 전 특별한 누군가를 기다리고 있거든요."
rows["141:2003915017"]="당신의 가장 큰 도전은 앞으로 있습니다. 레이-수호자 에레고스는 엄청난 힘을 가진 파란 용입니다. 당신은 그를 가장 높은 반지의 위를 날아가는 것을 찾을 것입니다."
rows["141:2055310937"]="스톰윈드에는 상업 지구에 있는 스톰윈드 회계사무소와 드워프 지구에 있는 스톰윈드 왕실 은행, 두 곳의 은행이 있습니다."
rows["141:2143015686"]="이봐, 거기. 자네가 누구인지, 왜 나를 따라다니는지 모르겠지만, 하여튼 난 배에 오를 참이라고. 나 좀 내버려 두라고, 알아들었나?"
rows["141:423801306"]="알터랙 계곡으로 가려면 카르타 블러드스날과 얘기해보게. 명예의 골짜기에 있는 용사의 전당에서 그녀를 찾을 수 있을 걸세."
rows["141:509546079"]="당신이 현재 가지고 있는 재능은 제 능력을 한참 웃도는군요. 아이언포지에 있는 내 노움 친구 트리시 퀵스위치에게 더 자세히 물어 보세요!"
rows["141:512407567"]="전장에는 적의 피가 흐르고 위대한 정령들이 우리의 부름에 응하여 호드의 앞을 가로막는 이들은 모두 쓰러뜨릴 것입니다."
rows["141:666723865"]="그대의 솜씨는 내가 닿을 수 없는 곳에 있군요. 이제 새로운 도전을 할 때입니다. 저기 탁자 옆에 서 있는 탈라단을 찾아가면 그대가 준비하는 걸 도와 줄 겁니다."
rows["141:717599561"]="그 엘프에게 축복해줘! 내 위가 이미  ⁇ 고 있었고, 여기 너무 편안해졌어요."
rows["141:848975507"]="당신은 이미 사랑을 찾은 것 같군요. 제게 사랑의 징표를 주신다고 해도 좋은 선물은 안 드릴 거예요. 전 특별한 누군가를 기다리고 있거든요."
rows["141:909382216"]="왕이 제대로 이겨버렸네?! 어떻게 슬립킥을 속였담?? 하지만 슬립킥은 똑똑하니까 다음번엔 어림없어! 하하!$B$B이제 아무도 슬립킥 못 속여. 슬립킥 약속해!"
rows["142:1079974270"]="저희는 용기호의 승객 여러분을 목숨 걸고 지키겠다고 맹세했답니다. 루테란 마을과 스톰윈드 항구를 잇는 항로를 안전하게 지켜야지요."
rows["142:1255118744"]="아, 여관 말씀이십니까? 쉴 곳으로는 썬더브루 양조장만한 데가 또 없지요. 휴식이 필요하다면 쉬었다 가십시오. 가신 김에 에일 맥주 한두 잔 정도는 꼭 드셔 보시기 바랍니다."
rows["142:1337375778"]="수습생 가리온과 대화를 나누셔야 한다면, 타베사 님의 오두막 안으로 가보시지요. 적어도 그 안에서, 약재를 전부 슬쩍할 수는 없을 테지요."
rows["142:1337917128"]="지난날 신도레이는 너무나 많은 것을 잃었습니다. 우리의 땅, 고향, 심지어 정체성까지도...$B$B이제 우리가 잃은 그 모든 것을 되찾을 시간이 됐습니다."
rows["142:1367459270"]="마법사들은 어둠의 틈에서 찾을 수 있을 걸세. 어둠의 틈으로 가는 입구는 두 개가 있네. 하나는 힘의 골짜기와 지혜의 골짜기 사이에 있고, 다른 하나는 골목길에 있다네."
rows["142:1393730631"]="매날개 광장에 있는 델라니엘의 여관에 가면 우리의 전문 보석세공인인 알레이니아를 찾을 수 있습니다. 그녀가 수습생을 구하는 것 같았으니 그리로 가보시지요."
rows["142:1408631259"]="이 발굴현장은 위험해요. 탐험가 연맹에선 우리에게 가치가 있을 만한 걸 챙기고 이곳을 정리하길 바라죠. 말은 쉽지만 하긴 쉽지 않아요."
rows["142:1497949167"]="그림자 땅은 갈 곳이 있어$B$B작물꾼에게 오래 기다리지 않을 거라고 말해"
rows["142:1519083671"]="정신은 돌아왔지만 기뻐해야 할지 모르겠군요.$B$B그 사실을 알아버렸으니... 우리에게 일어날 일을 말입니다...$B$B<몸서리를 치고는 말을 잃은 황혼의 복종자>"
rows["142:1561685528"]="알터랙 계곡에서 보초탑과 참호는 전술적으로 아주 중요한 곳입니다. 우리가 보초탑을 점령하면 아주 멀리 있는 곳까지 공격할 수 있습니다."
rows["142:1570163946"]="이 발굴현장은 위험해요. 탐험가 연맹에선 우리에게 가치가 있을 만한 걸 챙기고 이곳을 정리하길 바라죠. 말은 쉽지만 하긴 쉽지 않아요."
rows["142:1573716762"]="우리 빛의 결사단은 세계에 해악을 끼치는 자를 심판할 때 다른 형제들만큼 자비롭지 않소."
rows["142:1596021946"]="마법으로서, 당신은 이 곳으로 다시 데려갈 포털을 불러올 수 있는 선택된 집단의 한 명입니다."
rows["142:174210428"]="철혈의 그리렉$B$B방랑자. 그의 힘과 전투에 대한 갈증이 길이 기억되기를.$B$B이제 그리렉은 광란의 경계에서 배회하고 있다..."
rows["142:1748544093"]="우리 갈퀴발톱의 드루이드는 최전방 임무를 수행하는 데는 그다지 익숙하지 않아요. 공중 관측이나 은밀 침투가 주 임무니까요...$B$B그렇지만 가끔 이렇게 직접 발톱을 사용하는 것도 좋아한답니다."
rows["142:1836175617"]="칼이라는 드루이드가 돌라나르의 달샘에서 시간을 보내곤 하죠. 분명 그대에게 필요한 가르침을 줄 수 있을 거예요."
rows["142:1881733763"]="...베인할로우 님이 내게? 무슨 얘기지? 그분의 훌륭한 조언가이자 신하인 이 울라텍을 필요로 하시나? 나더러 오라고 하시는 건가?"
rows["142:1924268383"]="야단법석에 건방지다! 망할 녀석, 날 화나게 하겠다 이거?$B$B그럼 잘해봐, 겁쟁이 악당. 그럼 내일 보자!"
rows["142:1959289632"]="불루그의 도움이 필요하신 거로군요. 봉우리 하층에 있는 여관과 썬더 블러프 은행 사이에 있을 겁니다."
rows["142:1982741270"]="도망갈 생각을 하다니 용감하군, 오간아카.$b$b떠나기 전에 이빨로 트롤의 그물을 뜯고 나가는 방법을 가르쳐주지."
rows["142:2018884204"]="최근 알아메스 호수 주변이 공격을 당하는 바람에 낚시꾼들이 모두 다르나서스로 옮겨 갔답니다. 낚시를 배우시려면 다르나서스로 가보셔야 할 거예요."
rows["142:2090423766"]="난 자넬 도와줄 수 없어. 자넨 나보다 물약에 대해 더 많이 알고 있네. 게다가 난 이 냄비들을 계속 쳐다봐야 한다고. 저기 있는 옐마크에게 가 보게. 저 친구는 물약에 대해 많이 알고 있으니까 말이야."
rows["142:2120184565"]="더 가까이 오게, 젊은이. 한창때는 사냥감의 심장 뛰는 소리도 들리더니만 지금은 큰 소리로 말해야 겨우 알아들을 수가 있다네, 허허."
rows["142:2124952158"]="수사 빌헬름은 보통 대장간 뒤에서 리리아와 얘기를 주고받고는 하더군요. 그는 항상 동료 성기사에게 새로운 기술을 가르쳐 주지요."
rows["142:304383700"]="가깝고 먼 땅을 누비는 모험길 $b별나고 수상한 이들을 만나지 $b하지만 내게 묻고 싶은 게 있다면 $b먼저 간단한 일을 하나 끝내야 한다네!"
rows["142:320801581"]="도적이라고요? 뭐, 케린 실비우스가 그런 음침한 부류와 어울려 다닌다는 소문은 들었습니다. 케린을 찾아가서 배울 게 있는지 한번 알아보십시오."
rows["142:502104593"]="거기요! 노스렌드로 가실 생각이면 질풍호를 타시죠. 북풍의 땅에 있는 전쟁노래 요새로 한 번에 갈 수 있답니다."
rows["142:54591383"]="내 도끼를 매료시킬 수 있어? 영구적인 도끼를 원해. 나중에 찾을 수 있어."
rows["142:554004848"]="난 이미 모든 문명을 파괴하는 걸로 내 할 일을 다했소... 그런데 저주받은 자들의 교단 따위를 상대하려고 몸을 낮추어야 한다니, 정말 역겹소."
rows["142:796025390"]="광란심장 일족은 광포할지 모르나, 우리는 좋은 자들이다. 오래 머문다면 우리가 현명하고 강인한 이들과 사이좋게 지내는 것을 볼 수 있다.$B$B우린 그저 멍청이들이 싫을 뿐이다."
rows["142:911767268"]="이름이 뭐지요?$B$B당신 같은 떡대가 말을 할 수 없다는 게 참 다행이에요. 말을 할 수 있었다면, 아마 전 무역왕에게 당신이 얼마나 절 귀찮게 하는지 일러야 했을 테니까요.$B$B자, 비켜요!"
rows["142:946433054"]="저희 비행선이 소나무 가지에 별로 상하지 않았다는 게 정말 놀랍군요.$b$b그렇다고 저희가 세 번이나 숲에 떨어진 적이 있다는 게 용서되는 건 아니지만요."
rows["142:966895846"]="빛의 성당은 스톰윈드의 모든 치유의 중심지입니다. 그곳에서 이 공예를 배우는데 도움을 줄 샤이나 풀러를 찾을 수 있습니다."
rows["143:1034041216"]="*말하기 전에 티라시스는 당신을 위로 내려다보며*$b$b 내가 누군지는 중요하지 않습니다. 우리가 협상할 수 있다면 중요한 것은...$b$b 여길 좀 둘러봐요"
rows["143:103419469"]="태양샘으로 진입하지 못하도록 막던 모든 관문이 파괴되었습니다. 태양샘으로 들어가 킬제덴이 이 세계로 오지 못하게 막아야 합니다!"
rows["143:1241480922"]="매리언 콜이라고 하는 상급 도적이 있긴 하네. 마을 남동쪽 가장자리에 있는 교수대끝 선술집 위층 서재로 가보게."
rows["143:1625211092"]="돌라나르 요리사가 한 명 더 있었으면 좋겠어요. 자린의 요리 솜씨가 부족하다는 소리는 아니고요. 매일 같은 요리만 먹으려니... 자린을 찾아가서 무얼 배울 수 있을지 한번 알아보시지요?"
rows["143:1670869593"]="아니, 아니, 하지만 많은 사람들이 사랑을 찾고 있어. 당신은 내 사랑 토큰을 사서, 콜론이나 향수를 입고,"
rows["143:1674243163"]="연금술 가르쳐주는 데를 찾으세요? 저도 방금 다녀왔는데. 노움들이 모여있는 땜장이 마을에서 베리피즈 양을 찾아보십시오."
rows["143:1823616494"]="이건 모두에게 비밀로 해야 해요. 나까지 포함해서 말이에요!$B$B날 찾아줘서 기뻐요. 내가 수풀 속이나 바위 밑에 숨어 있지 않아서 다행이지 않나요?"
rows["143:1842841428"]="나는 머리 위에 튼튼한 화강암 천장이 없으면 편히 쉴 수가 없답니다. 머리 위에 별이 어찌나 많은지 등골이 서늘할 정도라니까요."
rows["143:185282217"]="아, 그대는 물질적인 부유함에 대해 지나치게 신경을 쓰시는군요. 재물운이 따르는 분이라면 이곳 상인의 정원에서 경매장을 찾으실 수 있을 겁니다."
rows["143:1879861393"]="오크릴라는 오크가 아닌 우리가 마을에 들어가는 걸 반기지 않네. 하지만, 그렇다고 우리에게 일을 안 시키지는 않아. 상관없네... 어쨌든 난 이 바깥쪽을 더 좋아하니까."
rows["143:2013086504"]="한 알케미스트가 산맥에서 북녘골 그리고 스톰윈드 좀 도와줄 수 있겠네요. 왜 가서 그를 방문하지 않는가?"
rows["143:2052983229"]="이넷세라는 보석세공 도구와 다양한 보석을 취급하는 똑똑한 여자입니다. 알도르 마루의 북쪽으로 가면 그녀의 상점을 찾을 수 있을 겁니다."
rows["143:2068849781"]="우리가 운고로에 온 이유는 단 한 가지, 바로 돈 때문이야. 나와 내 동료들은 늘 새로운 사업 동반자를 구하고 있어. 관심 있다면 합류하는 건 어때?"
rows["143:2085016427"]="저 지바루스는 그대에게 진심으로 감사합니다, 영웅이여. 그대가 아니었다면 전 이미 죽었거나, 아니면 그놈들 중 하나가 되었을지도 모릅니다..."
rows["143:306270195"]="칼 쓰는 솜씨라면 키라 윈드블레이드가 일품이죠. 돌라나르 여관에서 찾아보세요. 키라가 뭔가 가르쳐 줄 수 있을 거예요."
rows["143:336098377"]="스컬지와 드라카리의 의식 때문에 이 땅은 오염되고 말았다네.$B$B그럼에도 우린 굳게 버티고 있지."
rows["143:414115441"]="당신 대체 여기서 뭘 하는 거요?$B$B내게 거치적거리지 않도록 조심하시오. 당신 같은 사람한테 방해나 받으려고 붉은돌격대를 떠난 게 아니니까!"
rows["143:512609251"]="전날은 폭포 옆에 누워서 물의 소음과 강이 태어나고, 떨어지고, 호수에서 죽고"
rows["143:547354578"]="군대는 물자의 힘으로 움직인다고 하는데, 정말 맞는 말이오. 어떤 공격이든 성공하려면 반드시 병사들을 잘 먹이고 보급품을 충분히 지급해야 하오."
rows["143:605765757"]="달 축제의 가장 놀라운 파티는 무롱라이드에서 있습니다. 하지만 거기 걸지 마세요. 지혜의 계곡의 드루이드는 여러분을 운반할 수 있습니다."
rows["143:665551220"]="오늘 보여주신 실력이 사람들에게 깊은 인상을 줬을 겁니다. 이제 모든 이에게 마상시합의 용사로 인정받을 시간이군요."
rows["143:719122997"]="고맙소, 친구들. 그대들에게 나의 자유를 빚졌군. 그런데 타레사는 어디 있소? 산 속으로 떠나기 전에 마지막으로 그녀에게 감사의 인사를 전하고 싶은데..."
rows["143:856295517"]="달라란 북서쪽, 마법사 교역소에 있는 농업공학 연금술점으로 들어가는 물약 모양 문을 찾아보십시오. 지나칠 수가 없답니다!"
rows["143:95028639"]="벌써 이곳의 일을 돕고 있다는 얘기는 들었소.$B$B잘하셨소. 우리 일을 도와달라고 당신을 설득해야 하나 걱정하던 참이었는데 말이오."
rows["143:998139853"]="요즘 모두가 한창 얘기하는 저 D 구역을 나는 썩 좋아하지 않소. 우리가 저곳을 사용하려면 먼저 처리해야 할 일이 있소."
rows["144:1039698563"]="제발... 도와 주십시오...\010저주받은 기사를... 막아야만 합니다...\010그에게 목숨을 잃은 자가 한둘이 아닙니다... 아직도 달이 뜨는 밤이면 그의 사냥은 어김없이 계속됩니다."
rows["144:1066178438"]="대장기술이 무슨 어린애들 장난인 줄 아는가! 밖에 나가 스날하고나 얘기하게. 능구렁이 같은 놈이긴 해도 그래도 모루 다루는 법은 제대로 아니까."
rows["144:1105641556"]="무슨 소리야? $T 엄마를 원하시나요? 아쉽네요."
rows["144:1114492048"]="요새 그런 공적인 일들은 모두 스톰윈드에서 처리한답니다. 길드를 창설하고 싶다면 스톰윈드 사무소로 가보십시오."
rows["144:1246399044"]=" ⁇ -그놀은  ⁇ -그놀의 재미있고 재미있는 게임입니다.$b$b우리들 사이에서 꽤 인기 있는 새로운 매력입니다."
rows["144:1273521631"]="당신과 모험가 친구들은 계속할 준비가 되었나요? 여기 활성화 수정의 마력을 발포하여 제 경비병들의 후퇴 길을 엄호하겠습니다."
rows["144:1359926003"]="마을 남동쪽 가장자리에 교수대끝 선술집이라는 곳이 있네. 그곳 위층으로 올라가면 서재 안에 있는 어둠의 사제 베릴을 찾을 수 있을 걸세."
rows["144:1539675973"]="지금도 괜찮긴 한데, 좀 걷어차 주면 왠지 더 타우렌 털처럼 보일 것 같긴 하네요. 음, 저처럼 거칠고 야성미 넘치는 타우렌의 머리카락처럼 말입니다. 어떻게 생각하십니까?"
rows["144:1675432339"]="믿어지세요? 이 에테리얼에게는 바실리스크 눈이 하나도 없네요!$B$B그리고 그의 지도자는 뻔뻔스럽게도 스스로 '밀수왕'이라고 부르고 있습니다!"
rows["144:1877044588"]="잠깐 네가 내 사랑하는 시프인지 알았다... 그 머리카락 한올... 하지만 아니지 않은가! 이럴 수는 없다... 시프는 죽었어...$B$B내... 내 형제가... 그녀를 죽였단 말이다!"
rows["144:1897373749"]="힘의 골짜기에 있는 하늘탑 꼭대기로 가게. 와이번 조련사, 도라스가 곧장 전장으로 데려다 줄 거야."
rows["144:427732701"]="불타는 군단이 우리를 강력하게 압박하고 있지만 우리 방어선은 견고하네. 우리 호드가 세계수에 접근하려는 아키몬드를 막고 있는 매 순간 우리는 승리에 조금씩 가까워지고 있는 것이라네."
rows["144:51941954"]="돌아왔어!$b$b<엘프의 표정은 당신의 얼굴의 시골적인 모습을 볼 때 조심스러운 미시로 변한다.>$b$b그리고 나쁜 소식을 가져오죠?"
rows["144:75222031"]="분노의 관문에선 아주 의기양양했겠지, 안 그런가? 하지만 좋은 시절은 다 갔네. 우리가 와 있으니 쓸데없는 짓은 꿈도 꾸지 말라고."
rows["144:758539173"]="베이린 펠쉬루드는 살인 줄 아래의 성당에서 공부하고, 마법사들이 소환을 하는 동굴을 보관하고 있다. 그는 동쪽 연구의 조용함을 선호한다."
rows["144:765404923"]="명예의 골짜기에 있는 용사의 전당으로 가서 그레즈 레이지피스트를 찾게. 여기서 근무가 끝나면 내가 보고하러 가겠다고도 전해 줘."
rows["144:967081054"]="스톰윈드 내에서 출발하는 그리핀은 조련사가 감독하고 있지요. 그리핀을 타시려면 그를 찾아가 보셔야 합니다."
rows["145:1064179334"]="은행 말입니까? 아, 사설금고 말씀이시지요? 귀중품을 보관할 장소로 그 만한 데가 없지요. 아이언포지 입구에서 북동쪽으로 가면 있습니다."
rows["145:1076711893"]="포세이큰을 도와 아라시 분지에서 인간들과의 한판 벌이고 싶은 건가? 용사의 전당으로 가서 데제 스노우베인과 얘기를 해 보게."
rows["145:1276271107"]="이 피조물은... 꽤 나이가 들었소. 그리고 아주 현명하오. 네스피라와 이야기할 수만 있다면 바쉬르와 나가에 대해 많은 것을 알 수 있을 것 같소."
rows["145:1391443045"]="음, 좋은 생각. 나도 가서 꿰맨 데 좀 봐달라고 할까? 조셉 그레고리안 바느질 잘한다. 마법 지구 내곽에 있다."
rows["145:1461279978"]="골드샤이어의 라이온 프라이드 인은 이 곳 근처에서 찾을 수 있는 모든 인인만큼 좋습니다. 들어와서 인지퍼 파리에게 집에서 느낄 수 있도록 하세요."
rows["145:1486051774"]="벨가리스트라즈 말이 옳습니다. 상황이 매우 심각해요. 그대의 비룡은 이제 최고의 힘을 사용할 수 있습니다. 그 힘을 사용해 에레고스를 격파하세요!"
rows["145:1544280936"]="나그란드의 평화를 되찾으려면 날카로운 검과 강한 갑옷이 필요할 겁니다. 당신이 정의를 실천할 수 있도록 장비를 손봐 드릴까요?"
rows["145:1571607912"]="카테달라 광장에서의 빛의 성당으로 향합니다. 페렌 형제는 천주교와 십자군 나탈리 태양 성직자들을 훈련시킵니다."
rows["145:1939895572"]="이런, 이런. 울두아르를 제 두 눈으로 보게 되리라고는 꿈에도 생각 못 했답니다. 그래서 브란이 제게 이 원정을 좀 지원해달라고 했을 때 도저히 거절할 수가 없었죠!"
rows["145:1947890917"]="시작하기 전에 적에 대해 이야기를 들어라. 저기 나가서 스컬지를 밟아줄 때 정신없는 상태로 있고 싶진 않겠지?"
rows["145:1983357946"]="그림토템 부족 놈들은 물이 밀려들어 오자마자 우릴 공격했습니다! 마치 이 일을 예상했다는 듯이 말이죠.$b$b놈들은 자신의 악행에 대한 응징을 받게 될 것입니다."
rows["145:2034351735"]="채광을 배우려면 스톰윈드에 있는 드워프 지구로 가보십시오. 그곳 드워프 중 하나가 채광 기술을 가르쳐 줄 수 있을 겁니다."
rows["145:2097575150"]="달의 신전 1층으로 가시면 드레나이 한 쌍이 마법 차원문을 관리하는 인간 마법사 엘리사 뒤마와 이야기를 나누고 있을 겁니다.$B$B그들이라면 그대를 도울 방법을 알고 있을 것입니다."
rows["145:403842305"]="스컬지의 역병을 스컬지에게 역이용하기 시작했지만 아직은 미약한 수준입니다. 녀석들의 가마솥을 전복시켜 우리를 도와 주십시오!"
rows["145:42974098"]="<안도감에 빠져 한심한 짓만 하는 오릭에게 신경 쓰면 오히려 부추기는 꼴이 되기 때문에 전혀 그럴 필요가 없다고 느낍니다.>"
rows["145:46620612"]="아직도 어떻게 우리는 그립 없이 천개의 바늘을 통과할 수 있었는지 모르겠지만, 그늘이 없는 곳에서  ⁇ 고 타버렸어요!"
rows["145:486153151"]="엘룬께 영광을! 전쟁노래 협곡 전투모병관을 찾는 건가요? 그녀의 이름은 애살라스이며 상급 전사들 곁에서 그대를 기다리고 있을 겁니다."
rows["145:492515647"]="검은 사원에 진입할 수 있는 열쇠인 카라보르의 메달을 소지품에 넣어 드렸습니다. 준비가 되셨으면 검은 사원으로 바로 순간이동시켜 드리도록 하겠습니다."
rows["145:614113697"]="자네 솜씨가 나보다 훨씬 뛰어나구먼, 젊은이. 이제 썬더 블러프의 중앙 고원에서 가게를 운영하고 있는 우나를 찾아가보게. 그녀라면 자네가 원하는 것을 가르쳐줄 수 있을 걸세."
rows["145:622518700"]="이 차원문은 머나먼 타나리스 땅 아래 깊숙이 있는 시간의 동굴로 이어지지요.$B$B바라신다면, 제가 그곳으로 보내드릴 수 있어요."
rows["145:666793967"]="왕, 나 얼마나 똑똑한지 보여주지! 이제 왕은 강력한 마법 모조로 더욱 똑똑해질 거야!$B$B엄... 어쩌면 마법을 슬립킥한테 써 볼까? 그것 참 좋은 생각이네..."
rows["145:715958075"]="로얄 엑스체인 경매소는 동부에서 발견될 수 있습니다."
rows["145:762683956"]="그대를 도울 수 있는 아르넬이라는 학자가 있답니다. 달의 신전에서 그를 찾을 수 있을 겁니다. 그는 돌아온 명가의 일원들과 자주 담화를 나눈답니다."
rows["145:805812268"]="그레크가 가지고 있소.$b$b그를 도와준다면 하나쯤 줄지도 모르지. 나중에 푸른 하늘 벌목장에 갈 일이 있으면 꼭 물어보시오."
rows["145:851072063"]="걱정하지 마세요. 진홍빛 덩굴손은 제가 안전하게 돌볼 테니까요. 우리가 덩굴손의 습성을 알기 전까지는 덩굴손은 아무래도 여기 불의 땅에 머물러야 할 것 같아요."
rows["145:865531873"]="<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B보호모를 안 쓰셨네요. 지적 능력이 떨어진다는 의미인가요?"
rows["146:116984514"]="오, 당신이 바로 편지를 발견한 분이군요. 소식을 전해 주셔서 감사합니다. 아마도 가족에 대한 소식이겠죠. 음식과 음료를 드릴 테니 마음껏 드세요."
rows["146:1377590804"]="배가 꾸르륵거린다면 주방장인 스틸벨리한테 가보게나. 하지만 우리끼리 이야기인데, 그냥 항구에 도착하길 기다리는 게 나을 거라고. 요리할 때 남의 위장을 생각해 주는 사람이 아니라서 말이야."
rows["146:1590586790"]="지금과 같이 힘든 시기에 드루이드는 주위 동료에게 아주 절친한 친구가 되어줄 수 있답니다. 세나리온 자치령에 있는 어느 드루이드에게 물어도 같은 대답을 할 겁니다."
rows["146:1663623489"]="이 땅에 벌어진 일을 목격하니 가슴이 아프네. 우리 세나리온 원정대는 그 피해를 파악하고 복구하기 위해 할 수 있는 일은 무엇이든 할 것이네."
rows["146:1688181071"]="샤트라스의 여관은 부상당한 난민들로 꽉 차 있답니다. 하지만, 각각 알도르 마루와 점술가 언덕에 있는 알도르 사제회와 점술가 길드로 가면 묵을 곳이 있을 겁니다."
rows["146:177504811"]="이 성원은 여행자를 거의 수용하지 않지만, 그렇게 되면 그 경험은 당신과 함께 남아 있습니다.$b$b네마리엔에 오신 것을 환영합니다."
rows["146:1995384392"]="샤트라스에는 은행이 두 개 있는데 둘 다 도시 중앙의 원형 지구 외곽에 있습니다. 하나는 알도르 사제회의 드레나이들이, 또 다른 하나는 점술가 길드의 블러드 엘프들이 운영하고 있지요."
rows["146:2131071342"]="선리버를 대표하여, 이번 마상시합에 참가하시는 당신을 환영하는 바입니다. 은빛십자군에서는 우리 선리버에게 이번 시합에 흥미를 가진 자들의 신청을 받고 훈련을 맡아 달라고 요청했답니다."
rows["146:331674738"]="야만인도 전쟁에서 이길 수는 있습니다. 하지만 진정한 영웅은 전장에서 승리만을 노리지 않고, 마지막 공격이 끝난 뒤 평화가 유지되도록 힘쓰는 법입니다."
rows["146:409149851"]="<잠시 살펴본 다음 미소 짓는 대수도원장>$B$B알겠소. 대화를 나누기에 적당한 곳을 알고 있소이다. 준비가 되면 내 반지에 입을 맞춰 알려주시오."
rows["146:435072609"]="난 배포에서 일했고, 수년간 새끼를 훈련시켰어요. 집에 있는 건 좋죠. 무슨 일이 벌어졌든, 이건 내 집입니다."
rows["146:609878327"]="망치와 모루를 다루는 솜씨가 좀 있긴 하지만 아직은 부족하오. 가서 데인 린드그렌과 얘기를 해 보시오. 내게 가르침을 얻을 수 있도록 준비를 제대로 시켜 줄 테니까."
rows["146:659508493"]="내가 어떻게 생겼나, 마법사의 큰  ⁇ ? 당신의 능력은 공예의 지도를 필요로 한다! 아조라 타워에서 Kitta Firewind를 찾아라."
rows["146:712424201"]="전 오빠와 마찬가지로 선조의 은혜를 기리는 분들을 높이 삽니다. 특히, 달의 축제의 대의를 충실히 따르는 분들에게 저의 기술을 전수할 수 있다는 것은 커다란 기쁨이지요."
rows["146:83377598"]="여기 있는 거미들은 크기가... 저만해요! 들끓는 거미들을 어떻게 없애야 하는지 아세요?$B$B예, 그렇죠. 다이너마이트를 쓰면 돼요. 아주 아주 많이 말이죠."
rows["146:845484105"]="세계로 진출하고 있는 건데? 당신은 챔피언스 홀을 찾고 있고, 당신은 구도시 남동쪽 끝에 찾을 것입니다."
rows["146:872633531"]="불타는 군단에 대한 당신의 지속적인 도움은 여전히 감사 할 것입니다."
rows["146:963986813"]="저 아래가 죽음의 괴철로인데 이름 하나는 정말 잘 지었더군요. 장비만 제대로 갖춰지면 어둠의 의회는 불타는 군단에게 지옥불정령을 무한대로 공급할 겁니다."
rows["146:987462806"]="우리 맥주가 탐나서 오신 게 아니라면 좋겠군요. 나눠줄 생각은 추호도 없을뿐더러 이게 마지막이라서요!$B$B아웃랜드로 맥주를 가져올 좋은 생각을 한 자가 우리 말고는 아무도 없는 게 내 잘못은 아니지 않아요?"
rows["147:1071297892"]="아제로스의 드루이드들이 달숲에서 멋진 축제를 열고 있습니다. 도시 내에서 축제 구경꾼을 찾아보시면 당신을 달숲으로 순간이동시켜줄 것입니다."
rows["147:1071952057"]="이방인이여, 자네가 본 사실에 어리둥절 하겠지?$B$B우리는 선조께서 남긴 기억의 불꽃을 유지하고 찬양함으로써 그분들의 업적을 기린다네."
rows["147:111366632"]="운고로 분화구의 수정탑에 숨겨진 비밀을 발견했습니다. 언제든지 수정탑에 가서 수정탑의 힘을 얻고 유용한 자원을 얻을 수 있습니다."
rows["147:1172359080"]="두 개의 기둥 역할을 하는 뼈 사이에 팽팽하게 펼쳐진 가죽은 서쪽에 있는 얼라이언스의 실바나르와 생명의 숲의 주요 수호자를 대비하라는 신호입니다."
rows["147:1179725761"]="불쌍한 언데드들의 운명을 생각하면 아주 슬퍼지지요. 정기의 봉우리 밑에 있는 예언의 웅덩이에서 명상에 잠겨 있는 대마법사 심을 찾아가 보십시오."
rows["147:1206878654"]=" ⁇ 스키드 지대의 제노바 스톤스키드는 당신이 찾고 있는 사람입니다."
rows["147:1315314179"]="방 안에 한 줄기 밝은 빛이 나타나더니 곧 사라집니다. 또 다른 빛 줄기가 나타났다 사라지기를 반복합니다.$B$B어떤 순서를 보여주고 있는 듯합니다."
rows["147:1430459497"]="그리핀 조련사를 찾으신다면 아이언포지의 대용광로 근처로 가십시오. 그래도 가장 가까운 곳이니까요. 아이언포지로 가면 그리핀을 타고 날아갈 수 있을 겁니다."
rows["147:144916668"]="당신은 그동안 많은 훈련을 쌓아 왔군요. 수련을 좀 더 쌓고 싶다면, 사막으로 여행을 떠나야 할 겁니다. 가젯잔으로 가서 부젝 브라켓스윙을 찾아보세요!"
rows["147:1610990467"]="1만 년간의 기록된 지식이 모여 있다 보니 도서관에 쓸데없는 것들이 몰려오곤 한다니까. 책을 도난당하고, 회수하고, 다시 도난당하고 하는 건 매일 있는 일이라오."
rows["147:1626006253"]="우리 둔왈트 드워프는 돌처럼 굳건합니다. 문제는 몸만 그런 게 아니라 머리도 그런 경향이 있다는 거죠. 제 형제들이 종종 이 명성을 드높이려 들어서 골치가 아파요."
rows["147:1769058528"]="골목길 위층의 보르스탄의 아궁이에 있는 잠자를 찾아가게. 힘의 골짜기에서 골목길로 들어가면 왼쪽으로 보이는 계단을 따라 올라가."
rows["147:182880327"]="셸렌 로바트 말이로군. 브릴에서 나가는 길을 따라 남동쪽으로 가다가 교차로를 만나면 동쪽으로 가보게. 길가에서 야영을 하고 있을 거야."
rows["147:2066219220"]="아니, 이건 평범한 사막유랑단 약탈자들 짓이오.$B$B놈들이 서쪽에서 더 조직화된 단체를 꾸리고 있다는 소문이 돌더군. 놈들은 정말 야만적인 폭력을 저지르고 있소."
rows["147:2091005003"]="내가 모르는 걸 가르쳐 줄 수는 없잖나! 나보다 더 많이 아는 누군가가 있다면 모를까... 잠깐, 그렇지! 가젯잔에 있는 부젝 브라켓스윙을 만나 보게!"
rows["147:29313014"]="신드라는 만드는 물약만큼 똑 소리가 나지는 않지만 친절하니까 연금술 가르치는 데는 적격이죠. 돌라나르 여관 바로 동쪽에 있을 겁니다."
rows["147:324084097"]="이 근처에 낚시터는 별로 없지만 그나마 낚시를 할 수 있는 장소는 죄다 팩스턴이 차지하고 있답니다. 지금도 얼음 호수에서 낚시를 하고 있을 겁니다."
rows["147:490123927"]="당신이 사냥해 죽인 짐승의 숭고한 죽음을 조금이라도 기리고 싶다면, 그들이 남긴 몸을 의미 있게 사용하게. 골목길 중앙에 있는 코도 가죽용품점에서 투워드와 얘기해 보는 게 좋겠군."
rows["147:573805859"]="그대를 더 가르치는 것은 제 능력 밖입니다. 다르나서스 장인의 정원에 있는 텔로니스를 만나 보십시오. 그는 재능 있는 학생이라면 항상 가르치고 싶어한답니다."
rows["147:688642738"]="접근 중...\010\010무효 -- 기술자 <기술 난이도 == 초급>\010 \01001000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010\010\010접근이 거부되었습니다!"
rows["147:698030766"]="응? 나? 당연히 대장장이지. 가만, 그러고 보니 자네 지금 드워프만 쇠를 다룰 줄 안다고 생각하는 게로군? 그럼 맘대로 하게. 가서 드워프한테나 도움을 청하라고!"
rows["147:80669485"]="이 지역은 세상을 찢어발긴 대격변의 진원지 중 하나입니다.$b$b만약 우리가 살아남는다면, 원인을 파악해 봐야 할 겁니다."
rows["147:861194535"]="피비 레이크워더는  ⁇ 스키일드의 창당 근처에 있는 사냥꾼들의 사옥 앞 광장에서 레인저를 훈련시키고 있습니다."
rows["147:950422633"]="마법부여를 배우기로 마음을 굳혔다면 아이언포지로 가보십시오. 지난번에 제가 그곳에 갔을 때 그리핀 조련사 옆에 상점이 하나 있는 걸 봤습니다만."
rows["148:1112985208"]="스피릿스밸리에서 호수 옆에 있는 다크브라이어 로지에 가서"
rows["148:1138431511"]="바람의 돌로부터 맑은 목소리가 들려옵니다...$B$B신도 계급장은 어디에 있나? 네 녀석의 신분을 증명하지 못하면 군주님과 대화할 수 없다..."
rows["148:1143765899"]="이제 생명의 탄생을 기념하는 시간입니다. 그리고 계란은 봄과 재탄생을 상징합니다."
rows["148:1157791874"]="음유시인 칼라나로스는 수호자의 길을 가르치고 있습니다."
rows["148:1190453335"]="<희미하게 빛나는 영혼은 당신의 존재를 눈치채지 못합니다. 그녀는 자신만의 세계에서 길을 잃고, 이미 수천 년 전에 있었던 일들에 반응하고 있습니다.>"
rows["148:1206471469"]="<오타 원이 일어서며 하늘을 향해 울부짖자 그의 눈에서 불가사의한 빛이 불타오릅니다.>$B$B그렇소! 우리는 일어날 것이오! 일어나서 우리를 가둔 자들을 파괴할 것이오!"
rows["148:1215884348"]="연금술을 배우러 왔다고? 아주 좋아. 자네를 가르친다고 우리 동맹에 해가 되지는 않겠지. 자네가 우리의 적들에게 피해를 줄 수 있는 한은 말이야."
rows["148:1217347868"]="샤트라스의 지도자들은 뭐 하나 하는데도 너무 느리게 반응합니다. 그래서 고난의 거리의 위대하신 분들께서는 어둠의 미궁 문제를 우리에게 맡기신 겁니다."
rows["148:1284509371"]="연합왕자 하라매드는 우리가 샤파르의 방을 빨리 찾아내지 못하면 내가 다음 실험 대상이 될 거라고 말하곤 했었다.$B$B농담이 아니었지."
rows["148:1301188365"]="정령들이 그렇게 불안해해서야 제 동족이 어떻게 마음 놓고 싸우겠습니까? 정령들의 도움이 없으면 이 세계가 존재할 수 없다는 사실을 그들은 모르는가 봅니다."
rows["148:1315248731"]="스컬지는 이 순수한 대지에 존재하는 한 점 흠이다. 내 창조주들의 힘으로 놈들의 묵은 뼛조각 하나까지 짓밟아 뭉개 버리겠다."
rows["148:1383484014"]="아라소르 연맹은 스트롬가드의 인간들과 얼라이언스 전체를 위해 아라시 분지를 되찾겠노라 맹세했소. 이번 전투가 결코 만만치는 않지만 싸울 가치는 충분할 것이외다."
rows["148:1519095962"]="누구 시죠?$B$B저리 가십시오... 항구에서 일을 너무 많이 했더니 지쳐버렸습니다. 드워프 맥주를 마시면서 신세 한탄 좀 하다가, 낮잠이나 자야겠습니다."
rows["148:1560504173"]="마라우돈으로 통하는 문 근처에 있는 주황색 길과 보라색 길 사이에 세 번째 길이 보일 걸세.$B$B자네가 손에 들고 있는 그 홀이 바로 열쇠인 것이지."
rows["148:1680451207"]="하늘 높이 날아오르는 것처럼 신나는 일도 없답니다.$B$B아, 하늘 높이 날아오르면서 전투를 벌이고는, 끝난 뒤에 한잔하는 건 빼고 말이죠!"
rows["148:2072691682"]="미친 드라카리 트롤들이 우리 뒷마당에 스컬지 죽음의 요새를 떨어트릴 줄은 꿈도 못 꿨습니다.$B$B대체 어떻게 한 걸까요?!"
rows["148:2141313647"]="돈을 조금 지니고 계신다면 그대의 식욕을 돋울 만한 음식과 음료를 드릴 수 있습니다. 코퍼만이 이곳 산장을 최고의 모습으로 유지해 드리지요."
rows["148:327255260"]="우리는 베스틸락의 번식지 한가운데에 서 있습니다. 이 기둥들 너머 북쪽에는 베스틸락의 일족들이 기다리고 있습니다. 놈들은 베스틸락의 새끼들을 기를 쓰고 지키려들 것입니다."
rows["148:339072729"]="어서 오세요! 여기는 빌지워터 무역회사와 남쪽 바다 상인 은행의 자회사인 케잔 일등 은행입니다.$B$B무엇을 도와드릴까요?"
rows["148:380039034"]="제정신이오? 주위를 둘러보시오, 필멸의 존재여. 그대가 갈라진 대지 위에 서 있는 게 보이지 않으시오? 우리 종족이 겪었던 고통을 경험하고 싶지 않다면 그냥 이곳을 떠나시오..."
rows["148:458649786"]="세계의 자연적인 과정을 축하하는 것은 어리석은 일입니다. 우리가 축하하든 그렇지 않든, 그것은 일어날 것입니다. 하지만 그것은 설탕에 대한 훌륭한 변명입니다."
rows["148:473015512"]="왜 다른 무기를 배우려고 하시는지 이해가 가지 않는군요... 하지만, 정 고집을 피운다면 길 정도는 알려드릴 수 있습니다. 어떤 무기 훈련을 받고 싶은지 꼭 집어서 말씀해 보세요."
rows["148:503326245"]="먼저 리스리드가 약간... 무서운 여자라는 점부터 말씀드려야겠네요. 하지만, 당신이 필요한 물건은 모두 가지고 있을 겁니다. 그녀는 점술가 언덕의 동쪽에서 상점을 운영하고 있습니다."
rows["148:683541595"]="성공할 확률이 얼마나 낮은지는 상관이 없네. 이 숲 속에서 벌어지고 있는 끔찍한 난리 통에 늑대인간을 단 한 명이라도 구할 수 있다면, 우리의 노력도 헛되지는 않겠지."
rows["148:783820888"]="이곳에 케른이 산다고 하더군. 그의 고귀한 성품과 심오한 지식에 걸맞은 선물을 완성하면 그를 찾아 떠날 거야. 내게 지혜로운 말 한마디쯤은 들려주실지도 모르지."
rows["148:879994894"]="접근 중...\010무효 -- 기술자 <기술 난이도 == 초급>\010 \01001000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010\010접근이 거부되었습니다!"
rows["148:929523996"]="나는 자네가 이미 알고 있는 것 이상을 가르쳐 줄 수 없네. 하지만 우리 아버지께서 나보다 훨씬 더 많은 것을 알고 계시니 안에 들어가서 우리 아버지와 얘기를 나눠 보게나. 행운을 빌겠네!"
rows["148:942272529"]="나무괴물 때문에 돌라나르 근처에서는 낚시하기가 너무 어려워졌어요. 낚시를 가르쳐 줄 이를 찾으시려면 다르나서스로 가보시는 게 제일 좋을 거예요."
rows["149:1015870883"]="이 세상에서 나의 시간은 얼마 남지 않았지만, 성스러운 빛이 허락한다면 충분히 나의 숙명과도 같은 임무를 완수할 수 있소. 당신이 리븐데어 남작과 맞설 때 나도 함께하겠소."
rows["149:1062694103"]="난 수습생은 가르치지 않아. 이곳 불모의 땅에 있는 통곡의 동굴에서 왈도르라는 타우렌을 찾아가게. 자네를 도와줄 수 있을 걸세."
rows["149:1142566018"]="스팀휘들 무역회사는 달라란의 중앙 하수도에서 전 투기장 협회를 주관하고 있습니다.$B$B그곳에서 의지의 투기장이라는 결투장도 찾으실 수 있답니다."
rows["149:1220077551"]="<거수경례를 하는 스톰파이크 하사관>$B$B성명, 계급, 그리고 군번! 그것들만이 자네가 저 더러운 서리늑대 개들에게 넘겨 줄 수 있는 유일한 정보다!"
rows["149:1351345344"]="원소의 정령들은 현명하다오. 그들은 우리보다 훨씬 앞서 존재했으며, 우리보다 훨씬 오래도록 존재할 것이오. 그들이 말을 걸면, 우리는 귀 기울여야만 하오."
rows["149:1472366398"]="지체할 시간이 없습니다. 승전의 요새를 완성하고 병력을 강화하지 않는 한, 이 대륙에서 영원히 정착하리라는 희망은 버려야 합니다."
rows["149:1546288092"]="부족에게 옷을 제공하는 것은 다른 어떤 일보다도 중요하죠. 썬더 블러프 갑옷 상점에서 테파를 찾아보십시오. 바느질에는 선천적인 소질이 있지요."
rows["149:1616883299"]="인상적이야, 안 그런가? 이 거인들은 훌륭한 총알받이... 아니, 동맹이 될 거라고. 저기 있는 친구가 녀석들의 지도자인데, 내 얘기는 들은 척도 않는 게 흠이지."
rows["149:1727151605"]="내 도움이라? 정말 다급했긴 다급했나보군.$B$B<블랙혼의 잔인하고 어두운 눈 깊은 곳에 번뜩이는 불길>$B$B내가 네놈들의 세계를 태우지 말아야 할 이유를 대 봐라."
rows["149:1745794877"]="대지감시자들은 이곳에서 알력 다툼으로 옥신각신하며 대지 고리회의 임무를 방해하는 것을 허용하지 않을 것입니다.\010평화를 위협하는 자들은... 단호한 처벌을 받을 것입니다."
rows["149:1749145897"]="눈은 별로 내리지 않지만, 이곳의 밤은 대번에 코가 얼어버릴 정도로 춥다네. 침대는 뒤쪽에 있네. 다른 이들을 방해하지만 말게."
rows["149:179157907"]="돌 그 자체와 놓인 받침대 주변으로 냉혹한 한기가 뿜어져 나옵니다. 돌의 단면 안쪽 깊숙이 푸른 빛이 조용히 고동칩니다."
rows["149:190862980"]="우리는 바시르 영지를 급습하여 그들의 수정괴철로를 조사해 볼 계획입니다. 시간이 되면 도와주셔도 좋습니다! 하늘경비대 에테르 기술단은 대략 $4581d 후에 출발합니다."
rows["149:2091919765"]="저는 교활하지도 음흉하지도 않습니다. 그런 발언은 상당히 불쾌합니다.$B$B등에 막대기를 꽂아 버리기 전에 제 앞에서 사라지십시오."
rows["149:2094066872"]="구입하려는 하시는 물건이 있거나 팔려고 하시는 물건이 있습니까?$B$B우리가 하는 일이 바로 그런 것이지요.$B$B자, 뭘 도와 드릴까요?"
rows["149:280801521"]="매날개 광장의 북동쪽에 건물이 하나 있는데... 안에 탄나리아라고 소멸 솜씨가 기차게 뛰어난 여성 도적이 있습니다."
rows["149:288564697"]="의술사 움부는 골짜기를 돌아다니며 정령이나 생명체나 가리지 않고 전부 돌보지요.$B$B중앙 건물 근처에서 움부를 찾을 수 있습니다."
rows["149:310898004"]="산 꼭대기 바이트 앤 타클의 카 미스트런러는 다음 식사로 낚시하는 동안 내면의 평화와 평온함을 찾을 수 있는 방법을 알려줄 것입니다."
rows["149:343013180"]="발밑에 있는 대지가 신음하며 몸서리치고 있습니다. 하늘에서는 불의 비가 내리고 있습니다. 대기는 모든 생명체를 질식시키고 있지요. 이곳이 바로 진정한 불의 군주의 왕국입니다."
rows["149:427420169"]="내가 곧 유행이라고, 친구! 정령을 이용한 첨단 기술이지. 잃어버린 지식과 새로운 자원을 찾아 아제로스 깊숙이까지 탐험하는 멋쟁이!$b$b샘비노를 기억하라고."
rows["149:437836659"]="고작 이것 때문에 날 성가시게 한 거요? 이 쓰레기를 입고 다니느니 토끼 가죽을 걸치고 트롤의 소굴을 뛰어다니는 것이 낫겠군."
rows["149:626123557"]="저는 이 포세이큰 매일 밤 큰 비커 조각상을 태우고 있지만 우리 의식은 그들에게 이상해 보일 것입니다."
rows["149:646482675"]="스톰윈드에 릴리암 스파크스핀들이라는 영리한 노움 기술자가 체류하고 있습니다. 드워프 지구의 안쪽으로 가면 만날 수 있을 겁니다."
rows["149:649207352"]="어서 오십시오, 영웅이여. 당신의 공적에 대한 이야기가 세대에 걸쳐 전해질 것이라 믿습니다. 아마 언젠가, 당신의 동상이 저 스톰윈드의 영웅들 사이에 세워질 날이 있겠군요."
rows["149:718257887"]="타우렌 족장들이 정시마다 이 무대에서 공연을 펼칩니다. 그들의 활기찬 공연을 즐겨보십시오. 공연의 강렬함에 흠뻑 빠져들어 보고자 하신다면 우리의 멋진 공연단에 응원의 박수를 보내 주시기 바랍니다!"
rows["149:800067280"]="약초채집에 대한 지식과 기술이라면 피로드렌 문콜러가 전문입니다. 다르나서스 남서부에 있는 신전 정원으로 가보십시오."
rows["149:804318901"]="빌어먹을! 지금쯤 알터랙 계곡에서 신나게 싸우고 있어야 하는데 여기서 안내나 해야 하다니... 자네! 얼라이언스와 싸우러 왔나?"
rows["149:805265691"]="내 평생 이렇게 장엄하고 새로움으로 가득 찬 곳은 처음 보는군.$B$B악마에게 오염되지 않고 고급 지식이 숨겨진 채였다면 좋았을 텐데 말이야."
rows["149:89342287"]="고블린 스팀휘들 결투 대회가 곧 시작될걸세. 현재 투기장에서 연습 경기가 벌어지고 있는데 본선 전투는 $4262d 후에 시작될 게야."
rows["14:1048127127"]="계속 말씀해 주시지요."
rows["14:1241711741"]="여행자여, 무슨 일이오?"
rows["14:1345218358"]="뭘 원하나!?"
rows["14:1817468142"]="거기 있었군요!"
rows["14:1974470614"]="무슨 일이십니까?"
rows["14:2091361425"]="이리 와!"
rows["14:466261303"]="<흐느끼는 카우렌>"
rows["14:499517620"]="여! 어서 와, 얼간이!"
rows["14:590517526"]="- 뭐하고 싶은데?"
rows["14:6265897"]="가망이 없어..."
rows["14:633958867"]="준비됐나요?"
rows["14:645115938"]="도전하겠다는 거냐?"
rows["14:948787531"]="내가 당신을 알아?"
rows["150:1047925435"]="무두장이라면 오그리마에 있네. 칼바위 언덕에서 나가는 길을 따라 북쪽으로 가. 도착한 후에 오그리마 그런트에게 물어봐."
rows["150:1103475232"]="근육만 있고 뇌가 없는 자들, 그게 바로 일꾼들이지! 저들에게 동기를 유발한다면 일을 매우 잘하게 될 게야. 내 말이 무슨 뜻인지 이해했다면 그들을 발로 '차야' 할 것이네."
rows["150:1238302118"]="정말 반가군! 낚시 기술을 한 번 겨뤄 보고 싶나? 딱 좋은 곳을 하나 추천하지! 이번 일요일에 가시덤불 골짜기에서 낚시왕 선발대회가 열린다고!"
rows["150:1398825796"]="<당신이 다가가자 일어나려고 애쓰다가, 심하게 다친 듯한 옆구리를 움켜쥐고 비틀거리며 땅에 다시 주저앉는 서릿결 정찰병>"
rows["150:1495104209"]="매년 저는 하로우 윈드 수도원에 순례하여 성 빛에 대한 경의를 표합니다. 저는 그 의무를 이행하지 않고 다시 북녘골로 돌아오지 않을 것입니다."
rows["150:1573281711"]="뭐지? 왜 날 귀찮게 하는 건가? 자네는 고품질의 로브도 만들지 못할 것 같은데 말이야! 가서 스낭하고나 얘기해 보게. 내 가르침을 받을 자격이 되면 그때 다시 찾아오라고!"
rows["150:1627266487"]="그렘록이 만드는 음식은 썬더브루 에일 맥주와 정말 잘 어울립니다. 요리사가 되고 싶다면 꼭 그에게 배우십시오."
rows["150:1706843095"]="우리는 비전과 자연의 힘의 연구를 실천하는 자들로서 끝없이 새로운 것을 발견하고자 노력합니다. 바로 이 때문에 절 찾아오신 것 아닙니까? 좀 더 훈련을 받고자 하십니까?"
rows["150:175833522"]="미치고 폴짝 뛸 노릇이군! 힘들게 심원의 영지를 구원하고 왔더니, 이건 또 뭐냐고?$B$B고약한 황혼의 망치단을 상대해야 한다니!$B$B그래도 자네가 일을 바로잡으러 왔으니 참말 다행이군!"
rows["150:1788391828"]="몽술사 하자라$B$B악몽의 힘은 그의 것, 적들이 영원한 잠에 빠지기를...$B$B하자라는 지금 먼 곳에 있지만 언젠가는 돌아올 것입니다..."
rows["150:2124642102"]="우리에겐 피부  ⁇ 이 있어요. 켈리안 헤이지한테서 배웠어요. 피부  ⁇ 을 가르쳐줬어요."
rows["150:2127267276"]="오버딘이나 발리언스 포항을 찾으려 한다면, 캐서럴 구역과 공원 사이에 있는 운하를 지나면 항구 스톰윈드을 찾을 수 있습니다."
rows["150:283782518"]="아, 사냥꾼의 전당 쪽으로 가 보셔야 하겠군요. 수렵의 봉우리로 가시면 홀트 썬더혼과 같은 훌륭한 사냥꾼들을 만나볼 수 있을 겁니다."
rows["150:297479145"]="학자 허버트 핼시가 바로 자네가 찾는 사람일세. 하지만 그와 농담을 주고받을 생각은 말게. 그자가 역병이 어쩌고저쩌고하며 떠들면 손이 저절로 도끼로 향할 테니."
rows["150:297997057"]="이 표기판의 표기에는 고대 다이어그램이 있고 강력한 단어들이 있습니다.$B$B당신은 그것이 알케미컬 레시피라고 믿지만, 그것은 당신의 능력보다 더..."
rows["150:38870409"]="마법에 대해 약간만 알고 있으면 이런 일을 할 때 편리하지. 환상이 모두를 완벽하게 속일 수 있는 것은 아니지만, 보통 일 처리하는 데 별문제는 없소."
rows["150:427781529"]="낚시는 당연하게 우리 집안 가업으로 이어져 왔네. 자네가 좀 도와줄 수 있어 보이는군. 낚시왕을 위해 몇 가지 일 좀 처리해주겠나?"
rows["150:46220114"]="당신도 웬만한 기술을 지닌 재봉사이므로, 제가 아는 특별한 재봉 도안 몇 가지를 알려 드릴 수 있습니다. 저는 위습망토와 죽음의 한기 망토 만드는 법 둘 다를 압니다."
rows["150:517508772"]="드루이드들이 달숲에서 멋진 달의 축제를 열고 있지요. 먼 곳에 계신 분들을 위해 드루이드들이 대도시에서 순간이동하는 데 도움을 받을 수 있는 거 아시나요?"
rows["150:597071694"]="꼭 노리고 알아낸 거라고는 할 수 없지만, 어쨌든 제가 정말 대단한 사실을 발견했답니다. 저 야수는 뭘 집어삼켜도 전혀 탈이 안 나는 것 같아요."
rows["150:640699740"]="좋습니다, 그럼 시작해 볼까요? 하핫! 속았죠! 나한테서 배우기가 그리 간단할 줄 알았나요? 다른 이들과 마찬가지로 당신도 실력을 증명해 보여야지요!"
rows["150:74012232"]="오셨군요! 선리버 놈들한테 당한 건 아닌가 걱정하던 참이었습니다. 얼음왕관에 있는 우리 대표자에게 고서를 가져갈 준비는 되셨습니까?"
rows["150:752723474"]="마지스퀘어에서 탑 포털을 타고 마법사의 성당으로 내려가야 한다. 이스도르미는 그곳에서 크론오마저와 발타자르 마론 루네마스터를 가르친다."
rows["150:777477421"]="황금골에 있는 사자무리 여관이 딱 좋지요. 다양한 종류의 에일 맥주에다 푹신한 침대까지, 쉴 곳이라면 그만한 곳이 없답니다."
rows["150:890904416"]="초보자치고는 말이야... 나쁘지 않군! 게다가 나랑 실력도 비슷하고. 더 배우고 싶거든 언더시티에 있는 조셉 그레고리안을 찾아가야 할 걸세."
rows["150:90773011"]="아! 투기장에서 사람들이 죽을 때까지 싸우는 것을 보는 것보다 좋은 건 없지. 자네가 제때에 여기 있다면 아마도 그중 하나가 될 수 있을 거라고!"
rows["150:930787501"]="바쁘냐고? 무슨 질문이 그래? 내가 하루종일 발가락이나 꼼지락거리면서 빈둥거리는 줄 알아? 뭘 사러 온 거라면 한도르에게나 가보게."
rows["151:1000817696"]="쿠엘탈라스의 수호자이자, 캘타스 왕자의 충실한 종, 그리고 성스러운 빛의 진정한 주인인 혈기사의 본부에 오신 것을 진심으로 환영하오."
rows["151:1026711409"]="마음을 편히 가지거라, 필멸의 존재여. 이곳에서 그대와 나누는 시간에는 결실이 있어야 하며, 섣부른 생각으로 마음을 흐려서는 안 된다..$b$b합당한 이유를 알고, 명료한 생각을 할 수 있는 그대의 능력에 많은 것이 달렸다."
rows["151:1087635309"]="아이언포지의 미스틱 워드에 가서 야간 엘프 드루이드들과 이야기해봐요. 그들은 당신을 무롱레이드로 데려가 달 축제 축하에 참여하게 할 수 있습니다."
rows["151:1129191470"]="델라니엘이 쿼렐레스트라라는 훌륭한 요리사를 데리고 있습니다. 그녀에게 요리를 배우는 게 좋을 겁니다. 매날개 광장 여관에 가면 찾을 수 있습니다."
rows["151:1180643999"]="심지어 지금 이 순간에도 아라시 분지에서는 자유 의지를 지닌 언데드들이 아라소르 연맹과 전투를 벌이고 있습니다. 포세이큰 파멸단이 인간과 얼라이언스 동맹을 물리칠 수 있도록 도와주시겠습니까?"
rows["151:1353656361"]="아! 그거 알아둘 만한 기술임에 틀림없지요. 토그너스는 보기 드문 열정으로 모루를 때린답니다. 그를 찾아가서 당신이 배울 수 있는지 한번 보는 게 어떻겠습니까?"
rows["151:1359250948"]="흑마법사라고요? 글쎄... 소문에 듣기로는 마법사 지구에 있는 어둠의 희생양이라는 선술집에 그런 족속이 모인다고 합니다. 제가 이런 얘기를 해드린 것은 비밀로 해주십시오."
rows["151:1492766413"]="엘드레탈라스를 구하는 데 열중하고 있기에, 지금은 다른 일에 신경 쓸 겨를이 없습니다. 전쟁, 다툼, 충성 따위는 이 도시가 안전해지기 전까지는 아무 의미도 없습니다."
rows["151:152798878"]="적들이 사방에서 몰려오고, 장로들은 야영지를 떠나자는 이야기만 하고 있소. 하지만 난 우리의 본래 모습인 전사답게 녀석들과 맞서 싸워야 한다고 생각하오."
rows["151:1593827604"]="왕궁은 스톰윈드의 북쪽에 있습니다.$B$B북쪽 운하를 따라가면 왕궁의 마당으로 이어지는 도개교를 발견할 겁니다."
rows["151:1651124635"]="비안시의 초등병 능력은 여러 번 유용하다는 것을 증명했습니다."
rows["151:165122085"]="네? 아, 제가 좀 정신이 없어서 죄송합니다. 북부감시 요새에 계신 분들이 걱정돼서 말입니다. 제자들을 좀 보내 드릴 걸 잘못했어요. 자, 무엇을 도와드릴까요?"
rows["151:1664971776"]="이 땅을 지배했던 위대한 우르속의 아들로서 나도 한때는 회색 구릉지를 활보했다.$B$B하지만 이제는... 여생을 이 동굴에서 지낼 수밖에 없는 처지가 되었지."
rows["151:1668806228"]="제가 알기에는 앨드윈 래프린이 여전히 스톰윈드 길드 사무관으로 주재하고 있다고 합니다. 스톰윈드 성문을 지나면 왼쪽 건물에 있을 겁니다."
rows["151:1727727678"]="이곳의 기술병인 다엘로라면 당신에게 기계공학의 기초를 가르쳐 줄 수 있을 겁니다. 아마 당신이 우리 기술자가 고장 난 통신 장비를 고치는 일을 도와줄 수 있겠군요!"
rows["151:1828896084"]="검을 내리고 투구를 벗어라. 칼을 맞대기 전에, 먼저 두 귀로 내 열변을 감당해야 할 것이니.$b$b준비되었느냐?"
rows["151:1836148042"]="지옥불 반도는 철저하게 파괴되었습니다. 그곳의 주민들에게는 무자비하고 용서받지 못할 일이지요. 여정을 떠나기 전에 장비의 정비를 마치고 물자를 챙기는 걸 잊지 마십시오."
rows["151:263967010"]="전투의 전당으로 가면 이 지역 야수 관리인 울브렉 파이어핸드가 있어요. 동물을 맡기면 잘 먹이면서 정성껏 보살펴줄 겁니다."
rows["151:37388896"]="우리 보석사들이 에크소다르에 있어 발견한 자료를 이용해 기적을 만들어내야 돼"
rows["151:422636995"]="우리의 새로운 동맹 너울소나무 펄볼그는 우리가 어떤 가죽을 사용하는지에 관심을 보이더군요. 저는 북쪽에 살고 있는 그들에게 가죽세공을 배울 작정이랍니다."
rows["151:424063475"]="어머, 그럴 리가요! 우리 페이페이는 절대 남의 물건을 가져가지 않는다고요! 아주 착한 녀석이에요... 가끔 관심만 보여주면 돼요. 맛있는 먹이를 한번 던져줘 보세요. 찾는 물건이 어디 있는지 알게 되실 걸요!"
rows["151:806297014"]="지옥불 반도의 먼지와 열이 상당히 자극적이라고 들었지... 잘은 모르겠지만 난 아직 살아 있고 존경하는 내 동맹들을 믿을 걸세."
rows["151:810702922"]="옥테온은 우리의 전문 추적자이자 좋은 친구입니다. 그가 입고 있는 가죽을 보면 그의 사냥 실력을 알 수 있지요. 그의 야영장은 하늘 감시초소의 남동쪽에 있으니 그리로 가 보십시오."
rows["151:851393265"]="먼저 리스리드가 약간... 무서운 여자라는 점부터 말씀드려야겠네요. 하지만, 당신이 필요한 물건은 모두 가지고 있을 겁니다. 그녀는 점술가 언덕의 동쪽에서 상점을 운영하고 있습니다."
rows["151:875278098"]="아, 재봉술을 배울 생각이라면 아이언포지로 가서 스톤브라우를 만나 봐야 할 겁니다. 요즘에는 아이언포지를 떠나는 일이 별로 없다고 하니 다행이군요."
rows["151:88787597"]="대지모신은 여러 가지 비밀을 간직하고 있는데, 브렉 스톤후프의 도움을 얻으면 일부라도 발견할 수 있을 것입니다. 봉우리 하층에 있는 스톤후프 지질연구소로 가 보십시오."
rows["151:908211440"]="\"...\"$B$B이 타우렌 드루이드의 몸에 움직임이 없습니다. 마침내 이승을 떠나 뒤틀린 황천으로 간 모양입니다."
rows["152:1073380929"]="운고로의 수정탑들은 모두에게 수수께끼 같은 존재입니다. 이곳의 몇 안 되는 거주자에게 수정탑은 전설의 근원으로, 그 용도에 관해서는 많은 추측이 있습니다."
rows["152:116319189"]="보웬 브리스부아즈를 찾아가게. 그의 집은 브릴에서 남서쪽에 있는 버려진 장원 부근에 있어. 다리 건너면 바로 옆에 있는 건물이라네."
rows["152:1188565268"]="아슬아슬했군! 데스윙이 우릴 하늘에서 떨어뜨려 버렸네! 어쨌든 목적지에 거의 다 왔군. 고룡쉼터 사원을 향한 마지막 여정을 떠날 준비가 됐나?"
rows["152:1527881373"]="고난의 거리에 있는 우리들은 최근까지 어둠의 미궁에 훨씬 광범위한 첩보망을 구축했었다네.$B$B이제 비밀요원들은 모두 죽고 나와 토군만 남았군."
rows["152:1555049424"]="먼저 리스리드가 약간... 무서운 여자라는 점부터 말씀드려야겠네요. 하지만, 당신이 필요한 물건은 모두 가지고 있을 겁니다. 그녀는 점술가 언덕의 동쪽에서 상점을 운영하고 있습니다."
rows["152:1617590282"]="아르세스! 지원을 보내 줘! 광산 안에 꼼짝 못 하고 갇혔어. 나... 정확히 어디인지 모르겠지만 정신 차리고 뒤쪽 땅에 추적 신호를 떨어뜨리면서 왔어."
rows["152:1621640577"]="당신은 그동안 많은 훈련을 쌓아 왔군요. 수련을 좀 더 쌓고 싶다면, 사막으로 여행을 떠나야 할 겁니다. 가젯잔으로 가서 부젝 브라켓스윙을 찾아보세요!"
rows["152:1643328206"]="\"빛에서 태어난\"는 샤타르의 직역어인데, 이리던의 요원으로부터 샤트라트 도시를 되찾은 나라루에게 붙여진 이름입니다."
rows["152:1709829047"]="저희는 용기호의 승객 여러분을 목숨 걸고 지키겠다고 맹세했답니다. 루테란 마을과 스톰윈드 항구를 잇는 항로를 안전하게 지켜야지요."
rows["152:1715792526"]="모든 게시물은 교도관 불로크를 만나 허가를 받아야만 붙일 수 있습니다.$B$B만일 무단으로 게시물을 붙이다 적발되면 벌을 받게 됩니다.$B$B게시물을 붙이는 것은 무료입니다."
rows["152:1832790670"]="우리 모두를 위해 볼바르 폴드라곤 대영주님이 싸우고 계세요. 그분이 아니었다면 지금쯤 스톰윈드의 왕좌에는 아서스가 앉아 있을 거라고요."
rows["152:1875888705"]="이 징표는 존경의 표시로, 오직 전장에서 흘린 피로만 살 수 있다. 우리가 전쟁에서 승리하려면 이 징표를 얻는 게 아주 중요하지."
rows["152:1898050299"]="전사의 정원을 지키고 있는 파수꾼들 사이에서 실단나이르를 찾으십시오. 그녀는 혹시라도 적이 도시로 침입할 때를 대비해 텔드랏실의 숲 속을 감시하고 있습니다."
rows["152:2117336696"]="모이라 공주는 이제 제왕 타우릿산 옆에서 지내고 있소. 무슨 세뇌 마법을 걸어 놓은 것 같은데... 그런데도 난 여기 앉아서 아무런 일도 할 수가 없으니."
rows["152:260997297"]="이렇게 와 줘서 고맙습니다, 친구여!$B$B야생동물들이 불길을 피해 이 숲까지 왔습니다. 이제 더는 도망갈 곳이 없습니다. 살아남은 동물들을 보호해야 합니다!"
rows["152:473356942"]="저는 최신형 자동 로봇 상인입니다. 언젠가는 우리가 세계를 지배할 것입니다. 제가 돈을 떼먹고 있다고 주인님에게 이르거나 하지는 마십시오."
rows["152:832398013"]="록타르. 여기선 주의를 끄는 행동은 자제하게. 호드의 일원이 되길 원한다면, 이 언데드 녀석들은 항상 우리가 지켜보고 있다는 걸 마음에 새겨야 할 게야."
rows["152:859321969"]="스컬지의 역병이 거의 전환 단계에 이르렀습니다. 조금만 더 가마솥 전복을 시도하면 우리가 우세해지게 될 겁니다! 당신도 도와 주십시오!"
rows["152:957112845"]="이 전초기지에 있는 모든 친구들의 입에 당신의 이름이 오르내리는 것 같군요. 너무 자만하지 않는 게 좋을 겁니다. 당신이 더 잘할 수 있다는 걸 알고 있으니까요!$B$B풋내기씨, 내가 지켜보고 있을 거예요."
rows["153:1052125778"]="티르스에 내가 아직 여기 있다고 말하지 마 내가  ⁇ 은 방을 떠나지 않았다는 걸 알면 내가 그의 일들을 계속하고 그의 더러운 빨래를 영원히 청소할 거야"
rows["153:127746222"]="자네가 올 거라고 영혼들이 말해주었다네. 어떤 이유로 날 찾아오긴 하는데 그 이유는 자네도 모를 것이라고 하더군. 그래, 이곳에 온 이유는 알고 있나?"
rows["153:1284491935"]="나루는 우리의 상상을 초월할 정도로 현명하다오. 난 수년 동안 달라란의 도서관에서 배운 것보다 지난 5개월 동안 아달에게 더 많은 것을 배웠소."
rows["153:1416259244"]="시지 미카일라는 레인저스, 피네아스 열렬한 마녀 사냥꾼과 해롤드 가렛 폭풍우가 오는 사람들을 훈련시켜서"
rows["153:1493086305"]="지팍 코그웨이트, 작은 기둥이 썬더브레 디스틸리에서 동쪽의 신기한 무덤을 감시하고 있습니다."
rows["153:1653149373"]="노인당 앞에 있는 노인당을 찾아라. 이리 스톤호프는 원리주의자들을 가르치고, 조나 스타콜러와 선워커 모다이 는 태양 신자들을 가르치고 있다."
rows["153:174238703"]="눈 속 깊은 곳에 고대의 마법이 소용돌이치고 있습니다. 마치 그 눈 속으로 한없이 빠져드는 듯 현기증을 느낍니다."
rows["153:1787462760"]="아담 호새크를 찾나 보군. 남쪽 마법사 지구 내곽에 있는 사무실로 가면 만날 수 있네.$B$B발굴하러 가지 않았다면, 틀림없이 거기 있을 걸세."
rows["153:1804828592"]="어서 오세요! 노움 기계공학 설계도를 이용하려고 오셨다면, 잘 오신 겁니다. 우리 측정기 결과로는 당신이 인증된 노움 기술자시니까요!"
rows["153:1898081623"]="겔만 스톤핸드를 만나보시는 게 좋겠군요. 드워프 지구에서 대성당 광장으로 나가는 통로 부근에 있던 어떤 집 안에 살고 있던 걸로 기억합니다. 정확히는 모르겠습니다. 우선 그쪽에서 이층집을 찾아보시기 바랍니다."
rows["153:1967268880"]="케린 실비우스라면 당신이 찾는 그런 부류에 대해서 알고 있을 겁니다. 케린은 좀 음침한 이들과 잘 어울려 다니거든요. 사자무리 여관에 있을 테니 찾아가 보십시오."
rows["153:1974145515"]="이 근방에서 리리아 뒤 라크만큼 칼 솜씨가 뛰어난 이는 없습니다. 대장간 뒤로 가면 리리아가 있을 겁니다. 당신에게 뭔가 새로운 걸 가르쳐 주고 싶어할 분위기인지 눈치를 한번 살펴보십시오."
rows["153:1988559073"]="이곳의 트롤은 우리 종족을 꽤 잘 받아주는 것 같네. 따지고 보면 포세이큰이 탄생하기 수세기 전부터 죽은 자와 대화해 온 자들 아닌가?$b$b이런 점이 사업에 도움이 된다네."
rows["153:2029561774"]="다른 것들과 마찬가지로 금속도 자연과 균형을 고려해서 사용해야 합니다. 카른 스톤후프가 봉우리 하층에서 대장간을 하고 있으니 가서 그로부터 지혜를 구하십시오."
rows["153:2073228027"]="제이우스와 그의 사제들이라면 정기의 골짜기에 있는 정기의 오두막에 있지. 힘의 골짜기에서 서쪽으로 올라가면 있는 웅덩이로 가보게."
rows["153:2094716842"]="현재 달숲에서 달의 축제가 한창 열리고 있습니다. 직접 찾아갈 수도 있고 세나리온 자치령의 드루이드들을 만나시면 순간이동하는 데 도움을 받으실 수 있습니다."
rows["153:238523609"]="제가 알기에는 이곳 던 모로에 마법부여사는 없습니다. 마법부여에 대해 배우고 싶으세요? 그렇다면, 아이언포지로 가보는 게 좋겠습니다."
rows["153:239489974"]="경매장은 썬더 블러프 중앙에서 찾을 수 있습니다. 와이번 조련사의 탑 맨 아래층을 찾아보십시오. 선조님의 영혼이 당신을 보살피기를."
rows["153:279187262"]="하늘 감시초소에는 재봉사가 없습니다만 해변에 있는 야영지에 가 보시는 것도 괜찮을 겁니다. 바다 건너에서 온 상인들이 많은 것 같았으니 말입니다."
rows["153:285457036"]="네, 네, 압니다... \"하수도에서 낚시라니?!\"라고 생각하시는 거죠? 하지만 여기서 뭐가 잡히는지 알면 놀라실 겁니다. 믿으실지 모르겠지만, 저는 상어를 잡았다는 얘기도 들어 봤거든요."
rows["153:301573225"]="모르겠어요. 그래서 더 걱정되는군요. 난 어떤 수단을 써서든 무한의 용군단을 찾겠어요.$B$B당신은 아서스의 부대에 합류해서 그의 곁에 가까이 있으세요."
rows["153:312944866"]="빛의 감시자의 임무는 두 가지입니다. 첫째로, 모든 힘을 다하여 사제회를 지키는 것... 두 번째는 곳곳에 숨어 있는 성스러운 빛의 적을 추적해 제거하는 것입니다."
rows["153:332343471"]="<단순간, 짐승의 눈에는 인식의 반짝이 보이실 수 있습니다.>\010\010줄리... 도망...\010\010<인식도 사라지고,  ⁇ 은 다시 네 얼굴을 비추고 있다.>"
rows["153:363131557"]="말로리라는 은둔자가 인근 주민들에게 이따금 물약을 조제해 준다고 알려져 있지요. 스톰윈드와 북녘골 사이에 있는 언덕에 그의 오두막이 있습니다."
rows["153:397513358"]="뭐라 말씀드리기 어렵군요. 하뮬 님은 심각한 부상을 당했습니다. 물론, 강인한 드루이드시지만, 다시 온전한 상태로 회복하시려면 긴 시간과 인내가 필요합니다."
rows["153:621375594"]="이 고서의 페이지에 적힌 내용은 끊임없이 변하는 것처럼 보입니다. 자신의 생각이 머릿속에서 빨려 나가 책에 먹히는 듯한 느낌이 듭니다."
rows["153:757413898"]="그 안에  ⁇ 이 있을 거야 스톰윈드 그 직업에 대해 배울 수 있습니다. 스톰윈드 경비원들이 당신을 올바른 방향으로 인도할 수 있습니다."
rows["153:900160919"]="검은무쇠 부족 전체에서 저보다 더 기술 좋은 장인은 찾을 수 없을 겁니다!$b$b망치질, 단조질, 채광질 다 빌어먹으라죠! 내게 필요한 금속이라곤 바늘과 골무 하나씩뿐입니다!"
rows["153:985770782"]=" ⁇  카자드의 야크들은 누구에게도 굴복하지 않는다. 제 공예는 그들을 길러주고 있지만, 그들을 타는 것은 다른 문제입니다. 첫째, 그들은 당신을 가치 있는 사람으로 인정해야 합니다."
rows["154:1023861307"]=" ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은  ⁇ 은"
rows["154:1060239704"]="<아라코아 유령이 손을 뻗어 당신의 얼굴을 만져보지만, 누구인지 알아보지 못한다는 느낌이 듭니다.>$B$B로카람, 너냐?"
rows["154:1152437787"]="당신은... 스라이어스 계층의 시술관 도서관에서 고마마마마 바르도란을 그 사악한 피의 엘프들과 함께 찾을 것입니다."
rows["154:1264210248"]="철혈의 그리렉$B$B방랑자. 그의 힘과 전투에 대한 열망이 오래 기억되기를...$B$B그리렉은 지금 먼 곳에 있지만 언젠가는 돌아올 것입니다..."
rows["154:1484531744"]="아즈샤라에 스컬지의 수가 점점 늘고 있습니다. 신체 건강한 자들은 모두 나아가 그들의 침략을 막아야 합니다.$B$B남아 있는 죽음의 요새: $2279W개"
rows["154:1484968060"]="가까이 오게나, 친구여. 내 눈을 보고 놀라지 말게.$B$B난 오래전에 시력을 잃었으나 정작 중요한 것을 보는 데 눈은 필요가 없다네."
rows["154:1489441066"]="비밀결사대가 동부 고원 지대의 한 동굴에서 은밀히 움직이고 있다는 보고가 들어왔소. 제군, 녀석들이 무슨 수작을 부리려는 것인지 알아오시오! 가는 길에 서리늑대 부족을 조심하도록!"
rows["154:1715138299"]="아, 가시덤불에 돌아가고 싶군. 꽥꽥대는 랩터들, 트롤 전쟁, 끝도 없는 정글 생명체들, 그저 죽여 달라는...$b$b<한숨 쉬는 보트>"
rows["154:1790704533"]="세계를 구하러 온 것이라면 제대로 찾아왔군. 얼굴 없는 자, 혈신 학카르가 다시 나타났다네!"
rows["154:1803790377"]="마그나타우르는 생긴 것처럼 멍청하진 않습니다. 순서가 올 때까지 고르목을 보살피는 건 퍽 어려운 일이지만, 꽉 묶어 놨으니 위험할 건 없습니다."
rows["154:1814645858"]="알기 쉽게 수학적으로 가르쳐드리지. 고블린 + 기계공학 = 전문 지식이란 말이오, 젊은 친구. 그걸 부인하는 자는 덧셈도 할 줄 모르는 거라고."
rows["154:1892593303"]="비록 이 황무지에서 우리가 겪은 시련은 이루 말할 수 없지만, 난 왕자님이 우리를 승리로 이끌어주시리라 믿소. 매일 밤 그분이 무사하시기만을 기도한다오."
rows["154:2000420350"]="대장장이가 되고 싶나? 단숨에 적을 가를 만큼 날카로운 검을 만들고 싶은가? 살짝 대기만 해도 목표물을 완전히 부숴 버릴 망치를 만들고 싶은 게로군. 도와주지. 그 무기로 갚아야 할 원한이 있다면 더더욱!"
rows["154:206172136"]="이 바람꽃은 어둠에 잠긴 악령의 숲에서 한 줄기 빛처럼 건강하게 자라고 있습니다. 통통하고 즙 많은 열매가 가지마다 주렁주렁 열려 있어 금방이라도 따 먹을 수 있겠군요."
rows["154:263235346"]="자연에서 사냥한 동물은 한 군데도 버릴 곳이 없습니다. 그러므로 우리는 동물의 혼을 존중해 주어야 합니다. 아스카 미스트러너가 그 방법을 가르쳐줄 수 있습니다. 봉우리 상층에 있는 그녀의 주방을 찾아가 보십시오."
rows["154:382618934"]="자네 능력은 이미 나를 앞섰네. 이곳에 있는 타른을 만나 보게나. 가죽에 대한 그의 지식은 나를 압도하니까. 자네라면 흔쾌히 제자로 받아줄 걸세."
rows["154:458080124"]="안녕하세요, 여행자님. 저 끔찍한 생물들을 물리쳐 줘서 뭐라고 감사의 말을 전해야 할지 모르겠네요! 평생 숨어 지내야 할지도 모른다고 생각하고 있었거든요!"
rows["154:477431548"]="갑자기 '얼라이언스의 수호자'라도 되기로 결심하신 겁니까?! 아무래도 구 시가지 안에 용사의 전당으로 가보셔야겠군요."
rows["154:530223132"]="헬렌 펠트스키너는 오랜 세월 동안 무두질을 해 왔습니다. 아델레 필더가 방어구를 만들 수 있도록 가죽을 공급해왔죠. 수정 호수 옆에 있는 헬렌의 집으로 가보십시오."
rows["154:534740058"]="다르나서스로 가면 재봉술을 가르쳐줄 수 있는 재봉사가 분명 있을 거예요. 다르나서스에 도착하면 파수꾼을 하나 붙잡고 다시 한번 물어보도록 하세요."
rows["154:564219925"]="이 오크들은 아웃랜드에 자신들의 영토를 갖고 싶어합니다! 그들이 제게 얼마나 충성했는지를 듣고 나면 질투심에 절 죽이고 싶을지도 몰라요!"
rows["154:611141822"]="헤우르는 우리가 이곳에 도착한 이후로 줄곧 이 지역의 식물을 연구해 왔으니 그라면 당신에게 약초채집의 길을 가르칠 수 있을 겁니다. 하늘 감시초소의 서쪽 끝에 가면 대달과 함께 일하고 있는 헤우르를 찾을 수 있을 겁니다."
rows["154:650542597"]="우리에겐 불의 땅으로 진군할 힘이 아직 없어요. 우선은 병력과 보급품을 확보해야 해요. 이번 작전에 힘을 빌려주시겠어요?"
rows["154:668138192"]="도적의 길을 걷겠다면 시우르나를 찾아가십시오. 그녀는 세나리온 자치령 서쪽 끝에 있는 나무 안의 소용돌이 모양의 길에서 기거하고 있습니다."
rows["154:669119111"]="망치로 모루를 죽이는 게 아니라, 적을 죽일 무기를 만드는 거요. 당신이 지금 뭘 잘못하고 있는 건지 보여 주리다."
rows["154:734327842"]="블러드 엘프의 보물은 다른 것들과는 달라. 금이나 비단, 보석으로 만들어져서가 아니라 그 안에 녹아든, 그리고 그 자체인 신도레이의 장인정신이 귀한 것이기 때문이지."
rows["154:740007225"]="저주받은 기사가 만드는 공포에서 벗어났군요, 당장은요. 이제 좀 살 것 같네요. 하지만 머리가 있을 때 해치우지 않으면 다시 돌아올 거예요."
rows["154:811751835"]=" ⁇ 셔 광산에서 온 광물 운송품은 아직 도착하지 않았는데 직접 가서 답을 요구하고 싶지만,"
rows["154:930994996"]="잘했네! 자네 눈빛이 예사롭지 않군... 그런 눈빛을 잘 알고 있지. 나도 마법부여를 막 시작했을 때 그런 눈빛을 하고 있었으니까! 자, 이제 당신에게 가르쳐줄 만한 게 뭐가 있나 한번 보세나."
rows["154:952497135"]="정말? 멋지다. 여기 있는 모든 사람들이 한 잔 먹도록 하겠습니다. 하지만 여전히 따뜻합니다. 냄새가 나면 제 정신을 고취하는 것 같습니다."
rows["154:993662157"]="그렇게 쳐다보지 마시오! 당신과 같은 모험가는 아니어도 근육정도는 있다오. 물약을 휘저으면 팔이 이렇게 강해지지."
rows["155:1036856776"]="경험 보너스와 오픈 월드 스케일링을 활성화하거나 비활성화하려면$B$B장소는 빨간 깃발로 표시되어 있습니다."
rows["155:1376442978"]="그 악마들을 많이 처치했으니 불타는 군단도 우리 벌목기지를 공격하는 것을 다시 생각하게 될 걸세. 하지만, 아직도 사악한 악마가 꿈틀대는 것이 느껴지는군."
rows["155:1383635180"]="조금 전 새로운 우편물이 배달되는 것을 본 것 같습니다. 우체통은 봉우리 하층에 있는 썬더 블러프 은행 바로 밖에서 찾을 수 있습니다."
rows["155:1385101821"]="우리에겐 직면한 위험은 많습니다만, 필요한 때에 자연이 우리를 도외시하지 않도록, 우리도 자연을 도외시하면 안 됩니다. 우린 예전에 이런 교훈을 배웠지요."
rows["155:1393563864"]="자기랑 나 사이니까 말인데요. 난 이렇게 막중한 임무를 짊어지기에는 부족한 인물이랍니다. 한 달 후에 죽을지도 모르죠.$B$B이미 한 번 죽었는걸요. 두 번째는 아무 의미 없어요."
rows["155:1479115538"]="당신의 기술이 저보다 뛰어나군요. 무법항에 있는 헤밍이라는 노인이 \"고급 낚시정보\"라는 책을 가지고 있답니다. 분명 그 책이라면 당신에게 도움이 될 겁니다."
rows["155:1495564382"]="왕자님께서 왜 이렇게 늦으시는 건지 모르겠지만, 여기선 더 오래 버티긴 어려울 것 같네. 병사 몇몇은 벌써 추위에 나가떨어지고 있던데."
rows["155:1497164519"]="달라란의 얼라이언스와 호드 지구인 은빛 자치구와 선리버 성소에서 스톰윈드와 오그리마, 그리고 여러 전장으로 갈 수 있는 차원문을 찾을 수 있답니다."
rows["155:1519960939"]="저도 계속 배우고는 있지만 제 지식에는 아직까지 한계가 있어요. 이제 당신은 다른 사람을 찾아가야 합니다. 언더시티에 있는 조셉 그레고리안을 찾아가 배울 준비가 됐다고 말하세요."
rows["155:1538010423"]="자네한테 나쁜 감정은 없지만, 다른 곳에서 밤을 보내는 게 좋을 것 같네. 그 연약한 피부가 멍들고 싶지 않다면 말일세."
rows["155:1721172597"]="이 나락은 실로 악몽이에요.$B$B저 아래 틈에서 벌어지려 하는 전투에 대면 이것도 애교로 보이겠지만요."
rows["155:1723124982"]="그 미친 조나 스털링이 제게 날이면 날마다 시키는 일이라곤 그저 갑판 걸레질뿐이에요.$B$B갑판 청소라니?!$B$B전 마법사라고요! 걸레질 따윈 안 해요! 그저 평범하게 쓸고 닦는 방식으로는 말이죠."
rows["155:1761961331"]="야심만만한 낚시꾼이라... 뭐, 딕티나는 암멘 여울의 해안에 살고 있는데 그물과 막대기로 고기를 잡아 우리 모두에게 생선을 공급하고 있답니다. 그녀에게 가면 도울 일이 있을 겁니다."
rows["155:193938504"]="셸비 스톤플린트가 이 지역 사냥꾼들의 동물을 꽤나 많이 보살피고 있지요. 당신도 도움이 필요하다면 썬더브루 양조장 쪽에 있는 셸비를 한번 찾아가 보세요."
rows["155:2015263255"]="말똥말똥한 눈과 무성한 수염을 보고 착각하지 말라고요. 보수르는 유능한 수습생이자 좋은 친구랍니다. 얘기할 때 목에 쥐가 날 것 같기는 하지만..."
rows["155:2082261528"]="어이, 당신은 새로 온 친구가 틀림없군요! 만나서 반갑습니다!$B$B아킨둔의 어둠의 미궁에서 울림의 통제권을 회복에 대해서 들려온 소식 없나요?"
rows["155:456543893"]="이 근방에서 사냥꾼을 찾으신다면 찾아갈 만한 이가 딱 하나 있습니다. 바로 그리프 와일드하트인데, 카라노스에 있는 대장간 바깥에 서있을 겁니다."
rows["155:522053736"]="아주 실력이 뛰어난 무두장이 하나가 수정 호수 옆에 집을 짓고 살고 있지요. 그녀를 찾아가면 분명 무두질의 기초를 배울 수 있을 겁니다."
rows["155:54545579"]="이 지저분한 꼴을 좀 보십시오. 불모의 땅은...메말랐다고 들었습니다만.$B$B밤 사이 밀림이 나타나 제 야영지를 덮어버리고, 길도 전부 막아버리지 않았겠습니까!"
rows["155:596150087"]="보주의 표면에 커다란 인간의 손자국이 새겨져 있습니다. 끊임없는 조작과 처리에 시달려 보이지만 보주는 전혀 손상되지 않았습니다."
rows["155:649768853"]="이런 황천의 용은 처음 봤습니다. 선조의 기질을 그대로 물려받은 것처럼 보이지만 전혀 다른 존재가 되었으니까요."
rows["155:662235640"]="뭐, 이 정도 해 냈으니... 저기 책장 옆에 있는 라비니아 크로를 만나 보게. 너무 서투르게 굴지만 않으면 좀 더 배울 수 있을 걸세."
rows["155:682208667"]="보르그림의 말이 맞을 수도 있어요. 우리 부부에게는 휴식이 필요할 수도 있겠지요.$B$B하지만 여기 온 이상, 이 땅에서 뭘 얻을 수 있을지 열심히 연구해 보고 싶단 말이에요."
rows["155:69395326"]="크레스타른으로 가는 건 뭐지?$b$b예쁜게 들리세요 크레스타른에 오신 것을 환영합니다"
rows["155:77990279"]="살덩이작업장은 스컬지가 구울, 누더기골렘, 살덩이 구울을 만들어내는 본거지지요. 우리가 살덩이작업장을 처리한다면, 리치 왕은 크게 약해질 거예요."
rows["155:818079131"]="저는 지혜를 찾아 이곳에 오는 주술사들을 안내하는 스칼테쉬라고 합니다... 하지만 다른 길을 걷는 자들에게도 한두 가지 정도는 보여줄 수 있습니다. 알아보고 싶으신가요?"
rows["155:927820548"]="우리의 형제가 도를 넘어섰습니다. 그는 땅을 불태우고, 물을 증발시켜 버리고, 또 너무 많은 공기를 집어삼키고 있습니다.$B$B그가 균형과 조화로움을 되찾을 수 있도록 우리를 도와주십시오."
rows["155:947591191"]="당신은 이제 제 실력 밖에 있는 것들을 배우기 시작해야 해요! 저쪽 천막 앞에 있는 릴리암 스파크스핀들과 얘기해 보세요. 그가 필요한 내용을 가르쳐 줄 수 있을 테니까요!"
rows["156:1083778658"]="전문 기술 상인들은 언제나 각 기술 전문가들 근처에서 만날 수 있습니다. 다른 상인들은 스톰윈드 전역에 흩어져 있습니다.$B$B어떤 물건을 찾으시나요?"
rows["156:1147765156"]="오크를 처치하는 일이 즐겁고 말이 별로 없는 분이라면, 잘 오셨어요!$B$B그렇지 않다면 동쪽으로 조금만 가 보세요. 매년 이맘때 아주 예쁜 차원문이 열린다고 하더라고요."
rows["156:1206975428"]="마칸 앤볼이 썬더브루 디스틸러리에서 몇 개를 다시  ⁇ 을 거면 안되니"
rows["156:1260928078"]="잘했네! 자네 눈빛이 예사롭지 않군... 그런 눈빛을 잘 알고 있지. 나도 마법부여를 막 시작했을 때 그런 눈빛을 하고 있었으니까! 자, 이제 당신에게 가르쳐줄 만한 게 뭐가 있나 한번 보세나."
rows["156:1314327126"]="그대를 도울 수 있는 싫증난 해몬이라는 학자가 있답니다. 달의 신전에서 그를 찾을 수 있을 겁니다. 그는 돌아온 명가의 일원들과 자주 담화를 나눈답니다."
rows["156:1338959275"]="우리는 지금 이곳에서 황혼의 망치단, 라그나로스, 심지어는 데스윙을 뛰어넘는 존재를 상대하고 있다. 만약 우리가 패배하면 이 세계도 존속할 수 없을 것이다."
rows["156:1382302861"]="이 요새는 단단히 방어되고 있지만, 우리 적이 사방에서 다가오고 있네. 고원 안쪽으로 진군하기 전에 해변을 더 확실히 확보하는 게 좋을 것이야."
rows["156:1443146533"]="달라란에는 3개의 은행이 있습니다. 달라란 북쪽에 있는 달라란 은행, 남쪽에 있는 달라란 상업 은행, 달라란 지하 하수도에도 있습니다."
rows["156:1577666411"]="돌무더기가 되어 버린 저 집은 다섯 세대 동안이나 우리 가족의 보금자리였습니다.$B$B반드시 되찾고 말 겁니다.$B$B수적으로 열세이긴 하지만... 우리는 와일드해머니까요! 저희와 함께하시겠습니까?"
rows["156:1601063842"]="아, 귀족의 정원 축제라. 품위를 내팽개치고는 알록달록한 알을 찾아다니는 꼴을 보고 있노라면 어찌나 우스운지... 하지만, 그 알에 어딘가 마법적인 분위기가 감도는 건 사실입니다."
rows["156:1638679133"]="붉은돌격대 놈들 때문에 몇 년 동안이나 겪어야 했던 고충을 모두 생각해 보십시오. 고문, 광기, 심지어 살인까지.$B$B그런 일을 계속 두고 볼 수는 없습니다. 당신은 어떻게 생각하십니까?"
rows["156:1652381991"]="새로 온 제자인가? 멋지군. 이래서 라이던은 관리자로 칭송받고 난 여기 처박혀서 교습이나 하는 거겠지. 또다시 올해의 최우수 강사로 선정되는 날에는 민망해서 얼굴도 못 들고 다닐 거야!"
rows["156:1676448601"]="캘타스를 떠난 것은 우리가 한일 중 가장 잘한 일입니다. 캘타스의 부하들은 너무 맹목적이거나 겁이 많아서 캘타스가 자신을 어디로 데려가고 있는지도 모른답니다.$B$B하지만 우리는 그렇지 않지요."
rows["156:1795985456"]="그 시로나스라고 하는 자는 사루안에 대한 계획을 세웠다... $B$B<여기에서 갑자기 중단된 기록은 일지를 가로지른 한 획으로 끝납니다. 이 드레나이는 기록을 하던 중 사망했습니다.>"
rows["156:1904577217"]="글쎄, 여기서는 재봉사를 찾기 어려울 겁니다. 아이언포지로 가면 솜씨 좋은 재봉사들이 꽤 있지요. 그곳에 도착하면 경비병에게 다시 한번 물어보도록 하십시오."
rows["156:1921086724"]="안녕하세요. 제 상점에 오신 걸 환영해요.$B$B어유, 참 멋지시네요! 하지만 모습을 좀 바꿔보실 생각이라면, 아무 의자에나 그냥 앉으시면 된답니다."
rows["156:1938466408"]="검프 언니 오빠가 저더러 상점 운영을 도와달라고 했어요! 전 꽃을 정말 좋아한답니다.$B$B<갑자기 심각한 얼굴로 눈을 가늘게 뜨고 당신을 쳐다보는 어린 아델라인>$B$B꽃 좋아하세요?"
rows["156:2057901834"]="멋지군요. 여러분이 위대한 용사임을 오늘 여기서 잘 보여주셨습니다. 여러분께서 은빛십자군과 함께 싸워 주신다면, 스컬지에게 이기는 것도 식은 죽 먹기죠!"
rows["156:2106521684"]="알란나 레이븐아이는 신탁의 숲에 있는 영혼들과 교제한 이후 마법부여 능력을 얻었다고 하더군요. 지금 그곳에 가보시면 알란나를 만날 수 있을 거예요."
rows["156:346822781"]="우리를 여기에서 벗어나게 해줄 방법이 있다고는 생각하지 않는 데 말이지? 없다고?$B$B아 그렇다면, 용암이 천천히 이 구덩이 안으로 쏟아질 때 너무 고통스럽지는 않으리라고 상상하겠어."
rows["156:501608629"]="영원노래 숲에서 사시인이 완벽한 스라소니 가죽을 찾고 있으니 찾아가 보십시오. 마법학자의 관문 남서쪽에 마스레인과 함께 있습니다."
rows["156:50736207"]="이봐요! 동부 왕국이 그리운가요? 돌아가고 싶어 몸이 근질근질하다면 크라켄 호를 타고 스톰윈드로 돌아가면 돼요. 아, 따뜻한 공기가 그리워라!"
rows["156:613840916"]="사람들이 내 일을 과소평가하지 않았으면 하는 소망이 있소. 내가 직접 상어를 고꾸라뜨리고 장어를 비틀지 않는다고 해서, 내가 하는 일이 보잘것없는 건 아니지 않소?"
rows["156:835935447"]="황혼의 망치단에서 탈영한 자가 운이 없었던 것일까요? 산맥 남동쪽을 샅샅이 조사해 주셨으면 합니다. 그곳에 신비에 싸인 은둔자가 살고 있다는 소문이 무성합니다."
rows["156:956201839"]="내가 가르치는 것을 배우기에 당신의 기술은 아직 설익었소. 대신 저쪽에 있는 마크를 찾아가보시오. 고급 기술을 배울 수 있을 때까지 당신을 도와줄 테니까."
rows["157:1020056869"]="... 흠, 좋습니다. 그걸로 제가 어찌어찌 둘째 소절을 지을 수 있을 겁니다. 온 와일드해머를 하나로 묶는 아름다운 사랑을 축복하는 내용이지요!$B$B\"결합\"와 어울리는 말만 찾으면 되는데..."
rows["157:1036625478"]="스컬지가 오기 전까지만 해도, 나도 정말 잘 나갔는데 말이야. 뭐든지 사고 팔았지. 뭐든지!$B$B정말 말도 안 되게 가격도 높게 불렀는데도 말이야!$B$B살아있는 자라면 다 알 테니 아무나 붙잡고 물어보라고."
rows["157:1038644144"]="저희 하늘경비대 에테르 기술자와 그 호위대가 바시르의 수정괴철로를 조사하고 있는데 도움이 필요합니다! 바시르 영지로 가서 그녀를 보호해 주십시오!"
rows["157:1114202718"]="모든 게시물은 교도관 모입프 질을 만나 허가를 받아야만 붙일 수 있습니다.$B$B만일 무단으로 게시물을 붙이다 적발되면 벌을 받게 됩니다.$B$B또한, 이곳에 청구서를 붙이지 마십시오."
rows["157:1285089259"]="재봉사가 되어 보시겠다면 꼭 메린을 찾아가 보십시오. 다르나서스 북동부에 있는 장인의 정원에 살고 있습니다."
rows["157:1327378759"]="천천히, 마치 몇 년 만에 눈을 뜨고, 앨레나는 얼굴을 돌려 웃는다.$b$b이 모퉁이에서 묵상하는게 좋죠. 아름답지 않나요?"
rows["157:1356749125"]="정신을 집중하라, 필멸의 존재여. 그대가 경험한 어떤 전쟁과도 다른 전쟁이 이곳에서 벌어질 것이다.$b$b여기서 조금이라도 도움이 되려면 그대가 지닌 능력을 모두 발휘해야 함을 명심하라."
rows["157:1386406695"]="린링은 총기술관을 운영하고 있습니다.$b$b세가지 목표가 있을 뿐이고, 더 빨리 할수록 더 잘할 수 있습니다.$b$b개인적으로, 이건 제가 좋아하는 게임 중 하나입니다."
rows["157:1681419622"]="아니에요. 나는 오그리마로 돌아가지 않겠어요. 가족들에게는 슬픈 일이겠지만, 가족은 가족만의, 나는 나만의 선택을 한 거예요. 내 미래를 여기, 바로 내가 선택한 형제들과 함께하겠어요."
rows["157:1881037736"]="전투에서 경쟁자들을 만나야 한다. 승리하든 패배하든 전투 기간 동안 남아 있으면 경쟁자 타바드라는 우편을 보내야 한다."
rows["157:1943453407"]="달라란 북서쪽, 마법사 교역소에서 농업공학 연금술점 부속 온실이 있습니다. 그곳에서 달라란 최고의 약초채집사들을 만나실 수 있습니다."
rows["157:2073033155"]="시선을 너무 많이 끌지 않도록 하세요. 저는 의회에서 찾아뵐 기회를 주시길 기다리고 있답니다. 기다리는 일만 아니라면 주위에 듬직한 경비병들이 있으니 꽤 안전하다는 생각이 드네요."
rows["157:317964208"]="그 인장을 더 가까이 가져오지 마십시오, 필멸자여. 여기서도 그 인장을 감싸고 있는 악을 느낄 수 있군요.$B$B제가 조사를 하는 동안 잠깐만 기다리십시오. 꽉 쥐고 계셔야 합니다."
rows["157:544841095"]="포크 포크는 호드과 거래를 하지 말라고 명령했다.$B$B<상가가, 분노하여 땅에 뱉어내지만 더 이상 이 문제에 대해 말하지 않음>"
rows["157:633954543"]="왕, 나 얼마나 똑똑한지 보여주지! 이제 왕은 강력한 마법 모조로 더욱 똑똑해질 거야!$B$B엄... 어쩌면 마법을 슬립킥한테 써 볼까? 그것 참 좋은 생각이네..."
rows["157:682819663"]="알케미스트들은 태양의 궁전에서 위치하고 있습니다. 당신은 캠베론을 발견할 것입니다. 당신이 맥주 조션의 예술에 대해 알고 싶은 모든 것을 가르쳐 줄 것을 간절히 바랍니다."
rows["157:686582760"]="테룸 딥포지라는 드워프를 찾아가보십시오. 제가 아는 한 최고의 대장장이입니다. 드워프 지구 중앙에서 만나실 수 있을 겁니다."
rows["157:754190624"]="텔드랏실의 숲 가까이 있는 루테란 마을에 가면 아우버다인으로 떠나는 히포그리프를 타실 수 있습니다. 다르나서스에 있는 문을 지나시면 루테란에 갈 수 있어요."
rows["157:82365249"]="루아다는 하늘 감시초소의 동쪽에서 초년병 전사들을 가르치고 있습니다. 전투에서 도움이 되는 실용적인 기술을 배우고 싶다면 그녀에게 배우는 게 좋을 겁니다."
rows["157:991488729"]="훈련이 필요하시다면 리리아와 얘기해 보셔야 할 겁니다. 보통 대장간 뒤에서 자기 무기가 완성되기를 기다리고 있지요."
rows["158:1238818380"]="전투에서 경쟁자들을 만나야 한다. 승리하든 패배하든 전투 기간 동안 남아 있으면 경쟁자 타바드라는 우편을 보내야 한다."
rows["158:1289032525"]="문 동쪽에 있는 군부장관의 무장실로 가서 마도르 타르문트가 야만인들을 훈련시키고, 다그난 블레이드는 경호자들을 훈련시킵니다."
rows["158:1310632289"]="저 흑마법사가 소환한 건 파멸의 수호병이 아니군요! 다음 도전에서 여러분은 은빛십자군 기사들을 상대로 전투를 벌이게 됩니다. 도전할 준비가 되셨나요?"
rows["158:1312199878"]="이 탑은 완전히 미쳐서 돌아가고 있습니다. 여기는 도서관이 아니라 책으로 쌓은 거대한 건초더미입니다. 아마 바늘이나 찾을 수 있을는지 모르겠네요! 그건 그렇고, 제가 뭘 하고 있었죠?"
rows["158:1312397305"]="마을의 북서쪽 구석에 있는 커다란 천막 안으로 가보십시오. 초우 스트롱하이드를 만나 가죽세공에 대해 가르쳐 달라고 청해보십시오."
rows["158:1314700711"]="구 시가지의 스톰윈드 병영이나 돼지와 휘파람 선술집에 강인한 전사들이 모여 있습니다. 모르긴 몰라도 지금쯤 선술집에 모여서 왁자지껄 술잔을 기울이며 시간을 보내고 있을 테니 그리로 한번 가보십시오."
rows["158:1318663066"]="빌헬름 형제 는 종종 리리아 두 라크 와 함께 골드샤이어아마 그에게서 paladin가 되는 것에 대해 배울 수도 있을 겁니다."
rows["158:1602379967"]="은빛 여명회 형제들의 희생을 잊어서는 안 됩니다. 그들은 여명이 찾아올 것을 믿었습니다. 안타깝게도 이 땅에 빛이 돌아오는 모습을 볼 때까지 살아남은 사람은 없었지만..."
rows["158:1635905797"]="크로스로드에 또 다른 드러머가 있다는 걸 몰랐어요$B$B내가 덤스틱을 가지고 있어 파티 후에 소개하겠다고 약속하면 가져갈 수 있어"
rows["158:1642980392"]="오스틸 드 몬이시죠. 그는 항상 남동쪽 끝의 타버너에서 놀고 있어요."
rows["158:1715846058"]="저는 세이블메인 남작님의 명령에 따라 고룡교단 때문에 어려움을 겪고 있는 세나리온 원정대를 돕고자 여기 왔습니다.$B$B이런 일은 제 전문이죠."
rows["158:1734912065"]="$4262d 후에 투기장 순위 경기가 다시 시작된다네. 자칭 우승을 노리고 몰려든 용사들이 이미 몸을 풀며 기술을 가다듬고 최상의 장비를 갖췄다고. 자네도 대전에 참여할 준비가 됐나?"
rows["158:1836921099"]="바자르 토큰은 당신이 죽인 생물과 당신이 완료하는 임무에서 나온다. 더 많은 것은 감옥과 침략 상사에서 나온다. 다른 여행자들은 경매장에서 판매합니다."
rows["158:1940557659"]="내가 처음 물약을 만들기 시작했을 때 약병을 수도 없이 깼지. 내 서툰 손놀림에 유리 약병이 너무 쉽게 깨진 걸세. 자넨 나보다는 조심성이 있기를 바라네."
rows["158:2004155859"]="이 탈영병들은 수치스럽기 그지없는 일을 저질렀네. 눈으로 직접 봐야 믿을 법한, 정말로 수치스러운 짓이지. 그래서 우그소르를 여기 데려왔네... 이 아이도 알아야 하지 않겠나."
rows["158:2030589512"]="야생의 마법인 뮤세크 영혼의 방식을 연구하려고 이곳에 왔습니다. 의술사 우제리 님께서는 숲에 사는 작은 생물들로 연습을 시작할 수 있도록 저를 보내셨답니다."
rows["158:327370516"]="당신의 불규칙 전이 영역에서 전하가 감지되는군요! 최근에 돌개바람 축전장치를 사용한 게 틀림없어요. 전하가 완전히 사라지기 전에는 다시 사용할 수 없습니다..."
rows["158:398642464"]="소환 주문을 외울 준비는 되어 있지만, 주문에 사용할 힘의 원천인 나즈샤린의 도가니가 관건입니다. 반드시 유물을 되찾아야만 합니다."
rows["158:423482476"]="사업이 엉망입니다!$b$b끔찍하게 으르렁거리는 소리가 이 지역 전체에 울려 퍼지고 있어요.$b$b불쌍한 사람...$b$b실례하겠습니다. 정말 한잔 마셔야겠네요."
rows["158:526391185"]="놀라지 마십시오... 제 그리핀이 온전한 상태는 아닐지 몰라도 당신을 목적지까지 안전하게 데려다 줄 겁니다. 어느 탑으로 가실 것인지 말씀해 주시겠습니까?"
rows["158:527874568"]="붉은십자군에서는 대부분의 모임에 제 동생 록시를 보냈습니다. 하지만, 록시는 붉은십자군을 대표하기는커녕 자기 사냥개를 돌보는 일조차 할 줄 모르는 녀석이죠."
rows["158:577453865"]="저를 찾아 주시니 감사하지만 그대는 제 능력을 능가하시는군요. 바로 저쪽 편에 있는 실반나 포레스트문을 만나 보세요. 그녀가 제자로 삼을 만한 이를 찾고 있더군요."
rows["158:631407023"]="우린 맨주먹으로, 그리고 피와 눈물로 이 항만을 이룩했습니다, 친구여.$B$B절대로 발가드를 포기하지 않을 거라는 내 말을 믿어도 좋습니다."
rows["158:689042453"]="이 관문은 캘타스의 군대가 태양샘으로 후퇴할 때 사용하던 겁니다. 그의 추종자들 일부가 아직 여기 남아 있지요. 불타는 군단은 그들에게 정말... 이상한 방법으로 보상했었지요."
rows["158:718049201"]="동족의 원한을 갚기 위해, 우리의 땅을 집어삼킨 파멸의 역병을 몰아내기 위해... 나는 맹세합니다. 내가 가진 모든 것을 호드에게 맡기겠습니다."
rows["159:1190635507"]="노인들의 시선은 지평선에 있으며, 멀고어 리그를 위해 롤, 급격한 프로필에 의해 먼 거리에 깨진 썬더 블러프.>"
rows["159:1222013308"]="멋진 분, 안녕하세요. 여기에 들리는 비행선이 당신을 썬더 블러프로 곧장 모시고 갈 거예요. 공짜로요. 고블린이 여기 있는데, 누가 와이번이 필요하겠어요? 제 말이 맞죠?"
rows["159:1234005198"]="오그릴라의 확고한 친구분, 철은 단단하지 않답니다. 우리와 같은 생물체가 더 강인하지요. 철은 그걸 휘두르는 자의 힘을 얻지요. 휘두르는 자의 힘을 얻는 건 좋지만... 확고한 친구분께 뭘 도와드리면 될까요?"
rows["159:1239121062"]="저는 농민, 귀족, 상인의 아들과 거지를 치료했습니다. 이 보잘것없는 지식을 당신과도 나눌 수 있게 해 주십시오. 죽음 앞에서 우리는 모두 같은 존재입니다."
rows["159:1460215083"]="저는 비행 조련사들을 돕고 있습니다. 이 땅이 갈가리 찢어졌을 때 기지에서 달아날 히포그리프들을 모으고 있지요. 심지어 지금도 우리 히포그리프들은 상당히 불안해하고 있답니다."
rows["159:1583779661"]="오누준 브리쿨에 도전하고 용사 명단에 이름을 올리려 오누준 여기 왔다.$B$B오누준이 발할라스에서 싸워 이기면, 오누준 리치 왕께 충성하게 된다!"
rows["159:1591689478"]="에메랄드의 꿈은 위험한 곳이 되었다. 에메랄드의 꿈을 구할 수 있다는 희망 때문에 아제로스에서 누릴 수 있던 평범한 삶을 희생하고 에메랄드의 꿈에서 잠든 이들에 대한 걱정이 날로 불어나고 있도다."
rows["159:1888470345"]="이 차원문은 머나먼 타나리스 땅 아래 깊숙이 있는 시간의 동굴로 이어지지요.$B$B힘을 충분히 키우기 전에는 그곳으로 갈 생각도 하지 말라고 말씀 드려야겠네요."
rows["159:263911913"]="그대는 약초채집가 지망생이시로군요? 그렇다면 신전 정원으로 가서 피로드렌 문콜러를 만나 보십시오. 몇 가지 요령을 가르쳐 줄 겁니다."
rows["159:407315781"]="이 현상 수배 전단에 붙은 다양한 양피지 중 하나가 특별히 눈에 띕니다. 해골 무덤에 있는 해골채찍 독수리를 처치하라는 내용입니다."
rows["159:432101057"]="인간과 그 동맹들의 껍질을 벗길 수 없다니 정말 유감이네요. 그 껍질을 다 허비하다니... 하지만 누가 그런 껍질로 만든 보잘것없는 가죽을 입겠어요?"
rows["159:666921984"]="그림토템 부족의 공격을 받아주는 것도 이번이 마지막입니다. 놈들이 잘못을 뉘우칠 줄 모르니 짐승 다루듯 처치해야겠지요.$b$b대지모신이시여, 우릴 용서하소서..."
rows["159:895259111"]="간병소 바깥에서 야수 관리인 아르세이드를 만날 수 있을 겁니다. 그는 엑소다르의 주 출입구 근처, 중심지의 위층에 있습니다."
rows["15:1234797068"]="안녕, 뽀송피부."
rows["15:1269174007"]="뭐 필요해?"
rows["15:1316238363"]="미국 영어 텍스트 누락"
rows["15:1593538328"]="으... 저리가!"
rows["15:159386007"]="내가 도와 줄 일이라도 있소?"
rows["15:1804386058"]="$950w명 살아있습니다."
rows["15:354604868"]="캬, 이 술 맛있다!"
rows["15:414735334"]="뭔가, 육체의 소유자여?"
rows["15:858095957"]="무엇을 도와드릴까요?"
rows["15:882371597"]="고마... 워..."
rows["15:914298109"]="$962w명 살아있습니다."
rows["15:973783550"]="어서 오너라, 후손이여."
rows["160:1086041402"]="에라카 노 킴블$B호랑이의 신이자 야수의 제왕, 고양이의 왕으로 모든 사냥감을 파멸로 이끄시는 분$B$B부에타이 노 무에잘라$B$B죽음의 신이시며 영원한 잠의 아버지, 시간의 아들이자 어두운 밤의 절친한 벗"
rows["160:1147690809"]="시선을 너무 많이 끌지 않도록 하세요. 저는 의회에서 찾아뵐 기회를 주시길 기다리고 있답니다. 기다리는 일만 아니라면 주위에 듬직한 경비병들이 있으니 꽤 안전하다는 생각이 드네요."
rows["160:1203983158"]="가서 역병에 오염된 곡식을 발견해 마력 분열기를 사용하세요!$B$B그래야만 아서스가 증거를 발견하고 스트라솔름을 칠 테니까요."
rows["160:1347930706"]="볼진 님께서 말씀하시길 자기가 돌아올 때까지 북을 치고 있으라고 하시더군요. 볼진 님을 기다리나요? 금방 돌아오셔서 섬을 되찾으실 겁니다.$B$B여기서 기다리면서 음악이나 감상하시지요!"
rows["160:1419048817"]="달라란 동쪽에 있는 큰 건물에서 달라란의 마법사들과 순간이동 전문가들을 만날 수 있습니다. 바로 크라서스 착륙장과 달라란의 심장부에 있는 룬위버 광장 사이랍니다."
rows["160:1419478860"]="연말연시엔 포장지 구입하는 것을 잊지 말라고! 친구들에게 방어구와 무기를 예쁘게 포장해 선물하는 것만큼 겨울맞이 축제의 따뜻한 정을 잘 전달할 수 있는 방법도 없지!"
rows["160:1505805409"]="명예의 계곡의 용감한 사람들의 홀에 가자. 즈라카진은 스파링  ⁇  옆에 야생들을 훈련시키고, 남쪽 가장자리에 있는 경호자들을 거꾸로  ⁇ 니다."
rows["160:151008691"]="상급 드루이드를 찾으려면 스톰윈드 공원으로 가셔야 합니다. 공원 중앙에 있는 달샘에 가면 맬드린과 세리단을 만나실 수 있습니다."
rows["160:1642372846"]="물약의 재료를 조금만 바꿔도 완전히 다른 물약이 된답니다. 인내와 정확성이 필요한 것이지요. 이 두 요소는 삶의 모든 영역에서 도움이 될 겁니다."
rows["160:1681225497"]="난 탐험가 연맹의 일원으로서 유물을 찾아다녔소. 여명의 설원에 신비한 마법이 걸린 물건이 있다고 하는데... 대부분은 감시가 철저하지."
rows["160:1759995815"]="기계가 이쪽을 돌아봅니다.$B$B기계 뒷면에는 이상한 형태로 뒤틀린 홈이 있고 '겔카크 자이로마스트 선장의 물건'이라는 글귀가 새겨져 있습니다."
rows["160:1764534481"]="네? 그럴 리가요! 이런 간단한 기계 장치 따위에서야 쉽게 벗어날 수 있지만 제가 너무 바빠서 말이죠. 아세요? 일전에 제가 야수의 뱃속에서 몇 달을 보냈는데..."
rows["160:1825326775"]="가죽세공에 관심이 있으시다면 제대로 찾아오셨습니다. 팔드론과 텔로니스는 진정한 예술가들이죠. 저도 그들에게 많은 것을 배우고 싶습니다."
rows["160:1835755223"]="미친 열렬한 사람들의 마지막 성지입니다. '그곳에서 그들은 그들의 적색 유니폼을 만들어, 마법의 적색 끈에 의해  ⁇ 어!$B$B스트라톨메, 모험가!"
rows["160:1836092642"]="가을 축제는 첫해 이후로 조금 달라졌지. 지금은 상품권 대신 가을 축제 상품 교환 동전을 발급하고 있거든. 옛날 상품권을 아직 가지고 있다면 새 동전으로 교환해 주지."
rows["160:2034000476"]="모두 다 음모야. 내가 하는 일이 어떤 것인지 제대로 파악할 재량도 없으면서 날 어둠 속에 가둬 놓으려는 자들이 있단 말이오!$B$B아! 거기 흙 밟지 않게 조심하시오."
rows["160:472679016"]="수정 전당에 가면 상급 주술사들이 많이 있을 겁니다. 그곳에서 선견자 노분도 님을 찾아가 뒤틀린 드레나이들에게 약간의 동정 어린 눈길을 보내 주십시오. 성스러운 빛이 함께하기를."
rows["160:544714060"]="이곳으로 오는 중에 발목을 삐끗하지만 않았어도 내 동료와 저 안에 들어가는 건데... 흠, 생각해 보니 전 여기서 나가는 게 더 좋을 것 같군요."
rows["160:576749667"]="이 에테리얼 기술은 정말 놀랍지 않나요?!$B$B그들이 절 이곳에 머물도록 허락해 줘서 정말 기쁘답니다. 열심히 배울 겁니다... 그러다 보면 기술의 일부를 내 것으로 만들 수 있을지도 모르니까요!"
rows["160:792052398"]="이 전단에는 거대한 늑대를 처치하는 임무에 대해 자세히 적혀 있습니다. 그 늑대의 은신처는 호드 요새 근처 뾰족 마루의 남쪽에 있다고 합니다."
rows["160:806265840"]="잎과 가지가 붙어 있는 것으로 보아, 이 물체는 어떤 생물의 둥지 일부였을 것이 분명합니다. 그 밖에는 주목할 점이 없습니다."
rows["160:86361865"]="스틸그릴의 정비소로 가서 브론크를 찾아보십시오. 기묘한 장치를 뚝딱거리고 있거나 증기 전차 조종사들과 떠들고 있을 겁니다."
rows["160:958013262"]="볼진 님께서 말씀하시길 자기가 돌아올 때까지 북을 치고 있으라고 하시더군요. 볼진 님을 기다리나요? 금방 돌아오셔서 섬을 되찾으실 겁니다.$B$B여기서 기다리면서 음악이나 감상하시지요!"
rows["160:967972960"]="제 도움을 받기 전에 먼저 기본적인 것들을 배워야 합니다. 제 수습생인 반과 얘기해 보세요. 친절하고 인내심이 강한 친구라 당신이 배워야 할 것들을 잘 가르쳐줄 겁니다."
rows["161:1040792610"]="그댄 망상에 빠진 집정관과 대다수가 더위로 고생하고 있을 하층민 야영지를 달래기 위해 우리의 전체적인 방어력을 낮추려는 것이겠지요."
rows["161:1059602240"]="치즈는 기억과 토양입니다. 모든 지역은 그 안에 영혼을 담고 있습니다. 풍수 치즈는..."
rows["161:1104769530"]="미안하지만, 당신은 팩 코도의 넓은 측면을 쏠 수 있는 것 같지 않아요.$B$B우리끼리 시간을 낭비하지 말고, 당신은 올바른 트레이너를 찾아가"
rows["161:1512177409"]="이 부두에서 테라모어로 가실 수 있습니다. 제 말 잘 들으세요. 그곳은 얼라이언스들이 여행하기에 안전한 곳이 절대 아니니 항상 조심하시고 뒤를 살피세요."
rows["161:1875139938"]="당신이 절 위해 한 일에 대해 다시 한 번 감사를 드리고 싶었습니다. 당신은 저에게 숲의 짐승들로부터 고향을 되찾을 수 있는 용기를 주셨습니다. 그 과정에서 저는 마그윈을 찾았습니다!"
rows["161:1895580246"]="아우슈나이족의 영혼결합자 카라운은 안코리트족으로부터 떨어져 있습니다. 그는 나아루의 좌석에서 빛의 구석으로 가는 길에서 그들의 방 밖에서 서 있습니다."
rows["161:2092706940"]="검 제작 기술을 취소하는 것은 그리 간단한 일이 아닙니다. 검 제작 기술을 취소하면 검 제작 기술과 관한 제조법도 모두 사라집니다!"
rows["161:2137541747"]="리셰아나라면 까다로운 길드 창설 서류를 올바르게 지도해 줄 겁니다. 다르나서스 북동부에 있는 장인의 정원에 있으니 그곳으로 가보십시오. 그대와 그대의 동료가 나이트 엘프에게 영광을 가져오기를!"
rows["161:270017650"]="원정대 거점은 얼라이언스에서 군단 전초지와 가장 가까운 연락 지점입니다. 이곳의 북쪽에는 온통 악마들뿐이니 동료와 함께 여행하도록 하십시오."
rows["161:37022984"]="우리들 중 가장 민첩한 사람은 가끔은 알아보기 힘들지만 그럼에도 불구하고, 당신은 아마도 살인 줄 안에 있는 악당인 셀라니스와 그의 동족들을 만날 것입니다."
rows["161:578505504"]="날 귀찮게 하지 마라, 성가신 녀석아. 소위 전투원이라는 녀석들의 서투른 솜씨를 연구해 보는 중이니 말이다.$B$B나는 놈들을 능가할 것이고, 그러면 리치 왕께서 날 뽑아 주시겠지."
rows["161:715156065"]="평화롭다 해도 전쟁은 있게 마련이오. 아직도 여러 부족이 대족장님의 깃발 아래서 싸우고 있소이다. 당신의 부족도 오그리마를 위한 전투에 가담할 생각이오?"
rows["161:840534440"]="전방 지휘소와는 아직 단절된 상태지만, 당신이 가시멧돼지와 '협상'해준 덕에 팔만 좀 더 휘두르면 길이 다시 뚫리겠습니다."
rows["161:861880758"]="이쪽 길로는 가지 마십시오. 정령들이 불안정하게 날뛰고 있습니다.\010혹시 당신이 고대 유물에 대해 잘 알고 있다면, 정령들을 안정시킬 방법을 찾을 수 있을지도 모릅니다."
rows["161:895404081"]="엘윈 숲에서 재봉사라고 불릴 만한 이는 엘드린밖에 없습니다. 재봉술을 익히시려면 동쪽계곡 벌목지에 있는 그를 찾아가 보십시오."
rows["162:1072396275"]="자네는 이 아웃랜드를 달리는 녀석들을 다루는 법을 알고 있는 것 같군. 하지만 자네가 날고 싶다면 말이야, 훈련과 헌신은 물론이고 돈도 좀 필요할 것이야. 자네 돈 좀 있지 않나?"
rows["162:1250097944"]="바쁘다, 바빠! 할 일은 많고 시간은 없구나!$B$B불꽃 스패너를 어디에 뒀더라? 금방 쓰고 어디다 놨지... 이 근처 어딘데... 분명 좀 전에 손가락을 데었었는데!"
rows["162:1317385754"]="이 세상에 광부가 한 명도 없는 마을이 있겠습니까? 카라노스 바로 외곽에 있는 스틸그릴의 정비소로 가보십시오. 얄이 기다리고 있을 겁니다."
rows["162:1531276953"]="아뇨, 안 되겠어요. 나한테서 배우려면 그 전에 한참 더 훈련을 해야겠군요! 저 무뚝뚝한 초심자 말콤 린한테 가서 얘기해 보세요. 저쪽에 책에 파묻혀 있는 이가 말콤이에요."
rows["162:1587768681"]="아, 무두질 말씀이시군요. 손칼 쓰는 법은 욘 디프컷의 실력이 단연 최고랍니다. 마을의 북서쪽 구석에 있는 큰 천막에서 만날 수 있을 겁니다."
rows["162:1635876458"]="저 좀 도와주세요. 여기 이 게을러터진 드워프들 중 한 명에게라도 일을 시킬 수 있다면, 다른 이들을 시퍼렇게 멍이 들도록 두들겨 패는 일을 시킬 거예요!$B$B지금 할 일이 산더미란 말이에요!"
rows["162:1834638297"]="루막 그 친구... 전투는 아랑곳 안 하고 늘 낚시질만 한다니까. 명예의 골짜기 호수에 있는 부두에서 찾아보게. 간 김에 샨키스에게 안부나 전해 주고."
rows["162:1882115577"]="잠시 쉬면서 지친 몸을 회복하고 싶으시다면 돌라나르에 최고의 여관이 있죠. 여관주인 켈다미르가 그대를 잘 보살펴 줄 겁니다."
rows["162:1900206941"]="이방인 친구, 자네의 솜씨는 내가 가르칠 수 있는 정도를 초월했군. 돌발톱 산맥으로 가서 해바위 야영지에서 하가스와 얘기해 보게나. 나보다 더 많은 걸 가르쳐 줄 테니까."
rows["162:1950190639"]="나는 저들의 감시자이자 복수의 주먹... 저항 세력을 진압하는 자이니라. 감히 이 대군주에게 덤빌 자가 누구냐? 나의 무자비한 심판에 맞설 자가 누구란 말이더냐?"
rows["162:305333466"]="제가 보기에 여긴 폐허만큼 멋지지도 않고, 공기도 약간 축축하군요. 그렇지만 편안하고 내 집 같은 느낌은 드네요.$B$B안 그런가요?"
rows["162:324068673"]="우리가 붉은용군단의 환심을 살 만한 기회를 얻을 입장은 아니라고 봐요. 앞으로 있을 전투를 생각하면 그들은 값진 동맹이 되어줄 수 있을 거예요."
rows["162:476565777"]="호그럴을 찾고 계시다고 했습니까? 그럼 선술집부터 들르셨어야죠. 허허! 도적을, 그것도 드워프 도적을 찾는다면 맥주가 있는 여관부터 찾아봐야 할 겁니다. 어서 가서 찾아보십시오."
rows["162:545558909"]="어이, 난 스팀휘들 결투 대회의 공식 투기장 사무관 빅스톤 핀치휘슬이라고 하네. 관심이 있다면 군침이 돌만한 상품들을 보여주겠어."
rows["162:631605677"]="연구에 결정적으로 중요한 순간에 찾아오셨군요! 그래도 괜찮습니다. 저와 함께 '조용히' 명상을 하신다면... 얼마든지 환영입니다."
rows["162:665289099"]="준비가 되면 내게 이야기하면 된다. 그럼 널 내 머리 꼭대기에 앉혀 주지. 그러곤 줄드락의 스컬지를 향해 진군하는 거다. 어떤 놈을 해치워야 하는지는 네가 알려 줘야 한다."
rows["162:727989688"]="전 매년 이맘때쯤 실리더스를 찾습니다. 발가락 물집에는 이런 날씨가 아주 딱이거든요.$B$B저랑 산책이나 합시다, 친구. 멋진 경치와 이것저것 구경해보자고요."
rows["162:769724580"]="이 도시에서 가장 뛰어난 요리사인 실란을 만나려면 나그네의 쉼터 위층으로 가보십시오. 그녀의 조수에게서 요리 재료를 구입할 수도 있습니다."
rows["162:83259499"]="보아 밴스 언더글룸은 남동쪽의 갈로우스 엔드 타버너에 상층에 상주 방을 들어갔다고 합니다."
rows["162:924903427"]="내가 이 결투장을 관리하지. 돈을 걸고 싶다면 마음 놓고 걸게. 승부를 조작하는 놈이 있으면 바다로 향한 널빤지 위에 세워 버릴 테니까.$B$B빈말이 아니라네!"
rows["162:950474418"]="애가마스, 첫 번째 문이 침범됐습니다. 킬제덴의 두 명의 가장 강력한 부교수인 사크로라쉬 여신과 대마술가 알리테스는 공격에 취약합니다."
rows["163:1050645777"]="나는 이번 원정에서 무법항의 이익을 대변하고 있다고.$b$b이번 일이 잘못되면, 무법항에는 심각한 문제가 생길거야.$b$b아직 대격변으로 입은 피해도 다 복구하지 못했으니까."
rows["163:1165183008"]="오염된 노움들이 뒤집어질 일이로군요! 정말 눈물 나게 반갑네요. 입구 쪽에 있는 용암 벌레 때문에 아무도 여기 못 들어올 줄 알았는데. 여기까지 오셨으니 절 좀 도와주실 수도 있겠죠?"
rows["163:1171713300"]="세상에서 하늘을 누비며 적 머리 위에 폭탄을 꽝꽝 떨어뜨리는 것만큼 기분 좋은 일도 없지!$B$B아, 100킬로그램짜리 오크를 적의 머리 위에 떨어뜨리는 건 빼고 말이야. 안 그런가, 친구?"
rows["163:1245362189"]="방금 약초에 대한 보고를 받았네. 필요한 평온초는 모두 $2020w개인데 현재까지 $2021w개를 모았고, 화염초는 $2051w개 중$2050w개, 보라 연꽃은 $2055w개 중 $2054w개를 모았다고 하네."
rows["163:1280618311"]="- 그래, 그래, 그래...$b$b새우들이 너한테 말을 걸었을 때 난 그들을 거론자라고 비난했지"
rows["163:1356813905"]="가죽세공의 감을 잡았군요. 저는 더 가르칠 것이 없으니 언더시티의 도적 지구에서 일하는 아서 무어라는 포세이큰을 만나서 제가 보냈다고 하면 될 겁니다."
rows["163:1420102885"]="이 도시에서 가장 뛰어난 요리사인 실란을 만나려면 나그네의 쉼터 위층으로 가보십시오. 그녀의 조수에게서 요리 재료를 구입할 수도 있습니다."
rows["163:1458313855"]="자, 그럼 내가 제시한 과제를 수행할 준비가 되었소? 영혼들의 이야기로는 당신이 이 시험에 통과할 것이라고 하는군. 영혼들과 자신의 힘을 믿고 있소?"
rows["163:1547983763"]="아, 그 용의 안식처에서 있었던 \"오해\" 때문에, 다 쓰러져 가는 이 성으로 우리 시설을 옮겨야만 했다네.$B$B그래도, 이제 시간과 공간이 충분하니 작업을 시작할 수 있을 거야... 사랑스러운... 신제품 개발을..."
rows["163:1552705178"]="마법과도 함께 도자기 작업이 피곤하고, 여기 있는 사람들은 거의 그것을 깨닫지 못합니다."
rows["163:1606258975"]="잠자는 오그리마에서 제일 뛰어난 요리사입니다.$B$B골짜기의 가운데에 있는 건물 남쪽으로 가면 만날 수 있습니다. 바탐시에게서도 잠자가 만드는 음식을 살 수 있으니 출출할 때 확인해 보십시오."
rows["163:1619453603"]="난 스톰윈드의 재건 사업을 도우러 아이언포지에서 왔지만 우리 얼라이언스 친구들에게 내 기술을 충분히 전수하고 난 후에는 이곳 일을 맡겨버리고 고향으로 돌아가고 싶어..."
rows["163:1676566495"]="융합 핵의 안정된 상태를 유지하는 데 제 처리 능력을 모두 동원하고 있습니다.$B$B부동 소수점 오류가 지난번 정비 기간에 처리되었길 바랍니다."
rows["163:1711704545"]="지금 안심해서는 안 됩니다. 하이잘은 아직 건재하지만, 우리가 불의 군주 앞에서 나약해진다면 모든 것을 잃게 될 것입니다. 고대정령의 힘이 우리와 함께하기를."
rows["163:2093522295"]="날쌘그림자 결사단의 셴툴을 찾는 거로군. 골목길에 있는 드로퍼스 부자 고물상 맞은 편에 있는 지하도를 따라 어둠의 틈으로 내려가 보게."
rows["163:239267420"]="사실, 드루이드의 길은 주술사와 같은 뿌리를 가지고 있습니다. 지금 제니아 룬토템이 드루이드의 유래를 연구하는데 전념하고 있습니다. 블러드후프 마을 동쪽에 있는 커다란 천막 안에서 그녀를 찾아보십시오."
rows["163:248868325"]="아, 한때는 경험 많은 노련한 분이셨군요. 이 킬램이 다시 노련한 제작자로 만들어 드리지요. 당신은 재능이 있어 보이니 요청만 하시면 도끼 제작자의 길을 가르쳐 드리겠습니다."
rows["163:33573424"]="그렇군... 볼드랏실의 마력을 느낄 수 있소... 타락한 기운은 느껴지지 않는군.$B$B부탁이오! 내가 그대를 돕겠소. 운명이 날 이곳으로 이끌었소. 어쩌면 내가 할 수 있는 일이 아직 남았을지도 모르오!"
rows["163:36270367"]="황혼의 망치단이 이런 차원문을 아제로스 전 지역에 열게 놔둔다면, 제 아무리 강력한 군대도 이 세계를 구할 수 없을 겁니다. 이 차원문 연결망을 끊어야 합니다!"
rows["163:37983559"]="나는 해골채찍 독수리를 증오하네!$B$B내가 한쪽 눈을 잃지 않았고 가끔 정신을 잃지만 않아도 매일 가서 놈들을 쏘아 죽였을 것이네!"
rows["163:416060729"]="훈련이 필요하십니까? 아자르 스트롱해머는 늘 젊은 성기사들에게 한 수 가르쳐 주는 걸 즐기는 편입니다. 썬더브루 양조장으로 아자르를 한번 찾아가 보시는 게 어떨지요?"
rows["163:547931934"]="유후, 사랑스러운 당신!$B$B오늘은 우리 날이야, 알겠지만... 해적의 날이라고!$B$B노장 첨버킷이랑 내가 생각해낸 건데, 공포의 선장이 그걸 듣더니... 진짜 이렇게 만들어버렸지 뭐야!"
rows["163:61497799"]="<털썩 무릎을 꿇는 데미트리안>$B$B당신이 우리 주인님을 가둔 끝없는 감옥을 찾아내셨습니다!$B$B아! 그토록 오랜 세월을 기다려온 꿈이 드디어 현실로 다가왔군요.$B$B반드시 주인님을 풀어드려야 합니다!"
rows["163:703823853"]="덩가르 롱드링크를 찾고 있어요. 카즈 모단 이쪽에서 가장 빠른 그리폰들을 가지고 있어요."
rows["163:81832935"]="비록 응급치료가 사제의 치유만은 못하더라도 위급한 상황에서는 아주 유용합디다. 썬더브루 양조장에 있는 탐네르를 찾아가서 뭐든 배워 보는 게 좋을 겁니다."
rows["163:852127057"]="아! 저와 뭔가 통하는 분이시군요! 틀림없이 그라니스 스위프트액스라면 강철 무기를 휘두르는 법을 가르쳐 줄 겁니다. 지금 카라노스에 있는 썬더브루 양조장에 머물고 있지요."
rows["163:880314413"]="저는 한때 메디브 님을 모셨습니다... 적어도 저는 그렇게 생각한답니다. 저는 보랏빛 눈의 감시자들을 도와 주인님을 감시했습니다.$B$B하지만, 지금 제가 할 수 있는 일은... 하루종일 편자를 만드는 것뿐이랍니다."
rows["163:998037834"]="이 일의 배후에 나이트 엘프가 있는 건 아닐까요? 그런 의심이 드는군요. 사실 우리가 이곳 서부 성소에 더 부하를 주었기 때문에 문제가 터지는 것은 시간문제지요."
rows["164:1006097447"]="$c|1이여;여;, 어서 상황을 파악하고 정신 차리는 게 좋을 겁니다. 이곳은 스케티스에 있는 멋진 뒤뜰이 아니라 칼날 산맥이란 말입니다! 경솔하게 행동하면 추락하고 불에 탈 겁니다!"
rows["164:1179943271"]="부족 가죽 을 만드는 일 을 잊는 것 은 가볍게 하는 일 이 아닙니다. 만약 그것 을 포기 하기 를 선택 한다면, 부족 가죽 을 만드는 일 을 필요로 하는 모든 요리법 을 잊을 것 입니다."
rows["164:1248439758"]="전쟁노래 협곡에서 호드와 벌이는 싸움은 절대 질 수 없는 전투입니다. 은빛날개 파수대에서는 파수대의 명예와 우리의 땅을 지키기 위해 싸우고 있습니다. 저 오크들이나 잘못된 길을 가고 있는 우리의 동맹도 이러한 우리의 의지를 앗아갈 순 없을 것입니다!"
rows["164:1281573069"]="마법부여 지식이 정말 뛰어나군요. 원한다면 더 많은 것을 배울 수 있답니다. 다르나서스 장인의 정원에 있는 탈라단과 얘기를 나눠 보세요."
rows["164:135910937"]="내가 널 보냈다고 말하지 말고 중앙탑의 지하층에서 붉은 옷을 입은 여자를 찾아라\013\010\013\010\013\010\013\010레디아 뱅트라는 이름이 있지만 날 언급하지 마!"
rows["164:1583056582"]="나는 바다제왕들의 군주인 히드락시스다. 너는 정령이 아니므로 우리의 전쟁을 이해하지 못할 것이다... 어쩌면 우리 모두에게 이득이 될 거래를 할 수 있을 것도 같군..."
rows["164:1585907095"]="나보다 더 많이 알고 있는 이가 있소. 이제 당신은 그를 찾아갈 때가 된 것 같소. 돌발톱 산맥에 있는 해바위 야영지로 가시오. 하가스를 만나 계속 훈련을 받도록 하시오."
rows["164:1740345997"]="$6318d 후에 투기장 순위 경기가 다시 시작된다네. 자칭 우승을 노리고 몰려든 용사들이 이미 몸을 풀며 기술을 가다듬고 최상의 장비를 갖췄다고. 자네도 대전에 참여할 준비가 됐나?"
rows["164:1866489234"]="당신이 최고의 자리에 오를 그날이 정말 기다려져요. 생각해 보세요. 전 무역왕비가 될 거예요.$B$B당연히 그동안 사고 싶었던 것들도 모두 사야죠!!!"
rows["164:220067069"]="잠자를 찾아가보게. 힘의 골짜기에서 골목길로 들어서면 왼쪽에 있는 계단을 따라 위층으로 올라가. 보르스탄의 아궁이에 있을 걸세."
rows["164:254333925"]="마법부여 지식이 정말 뛰어나군요. 원한다면 더 많은 것을 배울 수 있답니다. 다르나서스 장인의 정원에 있는 탈라단과 얘기를 나눠 보세요."
rows["164:369607617"]="무얼 하고 있겠나. 당연히 생각하고, 한탄하고, 증오하고, 음모를 꾸미고 있지. 다 끝나면 다시 생각하고 한탄하고... 원하는 게 뭐냐? 생각할 것도 많은데."
rows["164:53933500"]="신드라의 알케미학 지식이 다소 제한적이지만, 시작하기에 충분할 것 같네요."
rows["164:543576374"]="우리 선조들은 개개인의 힘도 강해야 하지만 힘을 합칠수록 더욱 안전하다고 가르치셨지. 길드를 조직해 썬더 블러프의 명예를 수호할 생각이 있나?"
rows["164:666292499"]="스컬지의 침습은 불어난 땅에서 증가합니다. 모든 능력 있는 전사들은 그들의 침략의 물결을 막기 위해 필요합니다.$B$B남아있는 네크로폴리스의 수는: $2280W"
rows["164:666919380"]="아직도 중립을 지키는 유명한 스팀휘들 무역회사를 대표해 이곳에 머무는 동안 즐겁게 지냈으면 좋겠군.$B$B기억하라고, 가젯잔은 누구든 환영이야! 물론 해적만 빼고 말이야."
rows["164:72713960"]="망할 타우렌 같으니. 요리란 어떻게 하는지 제대로 아는 것 같습니다. 타우렌이 날라오는 음식 보셨습니까?$B$B배 터질 때까지 먹어보렵니다... 그다음에는 무덤에서 나와서 더 먹겠습니다!"
rows["164:902260054"]="그  ⁇ 은 동굴을 제외하고는 다른 어디로 모을 수 있겠죠? 바랄로 서약절자는 네크로맨스들에게 가르치고 디포 더오머는 종파를 가르치고 있습니다."
rows["165:1058880008"]="제 말은, 운명을 알리기 위해 세이지를 방문해 주시기 바랍니다.$b$b난 알아, 난 알아... 그는 괴짜이지만, 그는 당신의 미래를 예측할 수 있는 특별한 괴짜야!"
rows["165:1067751110"]="달의 신전은 엘룬의 사제들에게 집과 같은 곳입니다. 그곳으로 가시면 잔드리아와 라리아가 사제의 길에 대해 자세히 안내해줄 것입니다."
rows["165:1156963907"]="암흑 신부 베릴을 찾고 있어요. 그는  ⁇ 로우스 엣 타버너의 독서실에서, 읽고 기도하고 있어요."
rows["165:1204906452"]="이렇게 봉사 활동을 하는 것도 의술사 수련의 일부라네. 자넨 날 도와줬으니 공짜로 도와주지. 어딜 고쳐 줄까?"
rows["165:1218098948"]="방문하는 울리부시 왜성 중 한 명은 고고학자라는 걸 알아요\013\010\013\010\013\010\013\010아내 페나라고 생각하니 둘 다 탐험가야"
rows["165:1262147893"]="어서 오십시오, 고난의 거리의 자유인들의 친구여. 하지만 오래 머무실 수는 없습니다.$B$B내부에서 싸움이 벌어지고 있습니다. 우리는 당신의 도움이 필요합니다!"
rows["165:1277534189"]="안녕하십니까. 저는 입구를 지키는 문지기입니다. 원반 세트에 울둠의 원반을 결합하지 않으면 울둠으로 들어갈 수 없습니다."
rows["165:1408541707"]="새해를 맞이하여 새롭게 나온: PX-238 겨울맞이 원더볼트를 소개하지! 자자, 부끄러워 말고 어서 올라가 보라고.$B$B아, 해 보기 전에 이 양식에 서명하라고. 우린 아직 이 기계에서 몇 개의 작동 오류를 수정하려고 작업하고 있는 중이거든."
rows["165:1656257373"]="자네에게 더는 가르칠 것이 없으니 이제 가 보게. 사루에게 갈 생각인가? 꿈도 야무지군. 자네처럼 보잘것없는 자가 찾아가면 피에다가 쇠를 담금질하고 말걸."
rows["165:1799335950"]="무료 사탕은 나쁜 사업일 수도 있고, 아니면..."
rows["165:182679445"]="미치지 않고서야 그런 나쁜 모조에 손대지는 않겠지요. 어쨌든, 전 막지 않겠습니다.$B$B운자리 펠텅은 남동쪽의 큰 건물 안에 있습니다. 어둠사제의 제단을 지나가십시오."
rows["165:1943062172"]="여기 오크가 있는 게 놀라운가? 그럴 것 없네.$b$b우리는 포세이큰을 감시해야만 해. 애초에 주의를 늦추지 않았더라면, 분노의 관문 사건은 없었을지도 모르지."
rows["165:2056168688"]="그대는 아주 뛰어난 마법부여사로군요. 스승인 나의 재능보다도 뛰어난 것 같습니다. 이제 아조라의 탑에 있는 키타 파이어윈드를 찾아가 보십시오. 그대의 스승이 될 만한 이는 이제 그 친구뿐입니다."
rows["165:2095355586"]="요리 기술이라면 자린이 아주 박식하죠. 찾아가면 조리법 몇 가지 정도는 가르쳐 줄 거예요. 그는 보통 돌라나르 여관 옆에서 요리를 하며 시간을 보내지요."
rows["165:33233646"]="현명한 사람에겐 한 마디면 충분하다는 말이 있지. 집으로 돌아가게.$b$b근심 걱정 없는 명랑한 여행자가 나설 자리가 아니야. 자네 같은 이가 여기 발을 들였다간 뼈와 살이 분리되고 말 걸세."
rows["165:50190513"]="뭐, 거의 가깝긴 하지만 아직은 안 되겠네요. 아무래도 먼저 제 여동생 젬마와 얘기를 나눠 보셔야 할 것 같군요. 젬마한테서 기본기를 배운 다음 절 찾아오시면 아주 끝내주는 것들을 보여 드리죠!"
rows["165:548891720"]="아, 스톰윈드 사무소를 찾으시는군요. 영웅의 계곡에서 성문을 지나 바로 왼쪽에 있는 첫 번째 건물입니다. 그리로 가보십시오."
rows["165:720552678"]="태양너울 성소를 점령하는 일은 우리 계획의 첫 단계였습니다. 다음 임무는 무기고를 차지하는 것이지요.$B$B현재 $3233w 퍼센트 정도 진행된 상태입니다."
rows["165:722927669"]=" ⁇ , 악당들은 여기서 우리의 일을 해내지 못해 스톰윈드 오스본과 마티아스를 구시가지에서 바로 스톡데드로 끌어내면 좋겠어요"
rows["165:738139675"]="도적이라고요? 그런 부류에 관한 일에 엮이는 건 그다지 좋아하지 않습니다. 분명 잔노크를 찾으시는 거겠죠. 돌라나르 여관으로 가보십시오."
rows["165:852962726"]="한때 풍부한 물량을 자랑했던 엑소다르의 직물 공급량이 위험 수준으로 떨어졌습니다. 옷감을 기부해 주신다면 이곳에서 드레나이에 대한 당신의 명성이 높아질 것입니다."
rows["166:1138888416"]="책 의 페이지 에서 수백 가지 의 여러 가지 도표 와 스케마 가 형성 되고 있습니다. 일부 도표 는 인식 할 수 있지만, 다른 도표 는 낯선 것 이지만 익숙 합니다."
rows["166:1185802510"]="가라다르는 아수라장입니다, 이방인이여. 대모께서 병에 걸린 이후 가로쉬는 심한 우울증에 빠졌습니다. 아버지를 닮은 것 같지는 않아요.$B$B<한숨을 쉬는 쿠르쿠쉬>"
rows["166:1231086373"]="실버문의 마법 재연마사인 여마력사 피라가 그대를 도와줄 수 있을 거요. 그녀는 그녀의 마법부여 수습생들과 세다나와 함께 태양 궁정 멀리에서 찾을 수 있을 거요."
rows["166:1244740406"]="바람의 돌로부터 천둥 같은 고함 소리가 들려옵니다...$B$B대체 무슨 일이냐? 애송이 이교도 놈이 달아나고 있구나! 그래, 도망쳐라, 벌레 같은 놈. 아니면 심연의 군주로부터 진노를 사게 될 것이다!"
rows["166:148666087"]="안녕하신가. 나는 드레나이 수도자 아분이라고 하네. 잃어버린 드레나이의 상태를 치유할 방법을 찾을 수 있다는 희망을 품고 여기서 드레노어 성역의 잃어버린 드레나이를 연구하고 있다네."
rows["166:1815660617"]="예전에 한 번 키라 윈드블레이드가 싸우는 모습을 지켜 본 적이 있습니다. 정말 멋져서 탄성이 저절로 나오더군요. 키라가 그대를 잘 가르칠 수 있을 거예요. 돌라나르 여관에서 찾아보세요."
rows["166:198662732"]="이곳 잿빛 골짜기에서 보급품을 비축하는 우리의 노력을 지켜내는 임무는 쉽지 않다네. 그러나 우리는 절대로 전투를 피해 꽁무니를 빼지 않지! 나이트 엘프와 녀석들의 동맹은 우리 앞에 무릎 꿇게 될 것이야!"
rows["166:269453616"]="자네에게 더는 가르칠 것이 없으니 이제 가 보게. 사루에게 갈 생각인가? 꿈도 야무지군. 자네처럼 보잘것없는 자가 찾아가면 피에다가 쇠를 담금질하고 말걸."
rows["166:293814908"]="버드네 패거리, 말이야?$B$B이런, 버드는 다른 사람을 눈곱만치도 존중 안 하지. 삽질만 할 수 있다면, 아무나 데려다 쓸걸.$B$B...언데드는 빼고 말이야. 버드가 엄청 싫어하는 종족이거든. 개인적인 생각인데 말이지, 좀 무서워하는 게 아닌가 싶어."
rows["166:368975919"]="보물 얘기를 해보자면, 다른 사람이 쓰레기 같은 물건을 줍는 모습을 곁눈질하지 마십시오. 훔친 물건이 훨씬 짜릿합니다. 그죠? 어떻게 손에 넣었든 간에 공짜는 공짜인 법입니다!"
rows["166:455949410"]="최고의 솜씨를 가진 장인을 찾아다닌 것이라면 제대로 오셨소!$B$B그리만트 엘모어라고 하오. 뭐든지 주문만 하시오!"
rows["166:631299240"]="유명한 노겐포저의 비약 팔아요!$B$B천연 재료로 만들어 직접 발효시킨 뒤 병에 담았답니다! 이곳 가젯잔에서만 구하실 수 있어요. 맛있는 건 두말할 것도 없답니다!"
rows["166:659474641"]="가죽세공을 배우려면 북쪽에 있는 오그리마로 가야 하네. 오그리마 그런트에게 물어보면, 가죽세공을 어디서 배울 수 있는지 가르쳐줄 걸세."
rows["166:91975198"]="다르나서스의 전사의 정원에 있는 일예니아 문파이어와 아이언포지의 잘나가는 무기 상점에 있는 빅시 워블봉크가 당신에게 어떻게 투척 무기를 사용할 수 있는지 알려줄 수 있습니다."
rows["166:953569821"]="하룻강아지들 만날 우리 공격한다. 그래도 거대한 번개 바위 아직 안전해.$B$B수홀루 전에 그랬던 것처럼 우리 도와주러 온다... 하룻강아지들은 큰일 났다."
rows["167:1234407382"]="우체통이요? 보낼 편지가 있거나 받을 편지가 있습니까? 뭔가 좋은 소식이었으면 좋겠군요! 다르나서스의 중앙에 은행 바로 밖에 우체통이 있습니다."
rows["167:1271762696"]="전투장들은 파스트라이더스 광장에서 있는 블러드 라이트의 한반도의 거리에 편안하게 싸우고 있습니다."
rows["167:1320895095"]="절 찾아오는 분들을 전부 가르칠 여유가 있다면 좋겠죠. 안타깝게도 그건 보석세공을 가르치는 순서가 아니랍니다. 파다르가 가르치는 것을 전부 배우기 전까지는 당신을 도울 수 없습니다."
rows["167:1330247282"]="이 세계를 우리 것으로 만들려면 전투로 지친 몸을 쉬게 해줘야 할 곳이 필요하답니다. 불 옆에 도끼를 내려두고 당신의 멋진 무용담을 들려주시기 바랍니다."
rows["167:1345421313"]="테라모어 경비병들은 칼림도어에 주둔하고 있는 얼라이언스 병사 중 가장 뛰어난 집단이지. 우리 고향에서 이렇게 멀리 떨어진 곳에서도 얼라이언스의 법을 수호하는 것이 우리의 임무라네."
rows["167:1650637470"]="우리의 가두에 앉아 있는 눈은 거의 없고 냄새를 맡은 호흡은 거의 없다.$b$b당신들이 누리는 특권을 이해하셨나요?"
rows["167:1841231743"]="여어, 안녕하신가! 새로운 친구를 만나게 되어 반갑군. 이곳에 오는 친구들이 그리 많지 않아서 말이야. 게다가 여기 기술자 친구들은 그리 화술이 뛰어난 친구들이 못 되거든.$B$B52번 구역으로 가는 거 같은데, 맞나?"
rows["167:1903716774"]="그대는 제 능력을 벗어나셨으니 좀 더 숙련된 스승을 찾아가시는 게 좋겠습니다. 이곳에 있는 릴리시아 나이트브리즈를 만나 보시면 배울 것이 많을 겁니다."
rows["167:1930696346"]="스컬지를 상대로 한 싸움의 첫 단계가 성공적으로 진행되고 있습니다. 우리는 이미 몇 번의 성공을 거두었습니다. 저의 지원으로 앞으로 전투에서도 승리를 가져오기를 바랍니다."
rows["167:2080686465"]="제로드 님과 일하는 건 나쁘지 않아요. 가끔 화를 참지 못하고 이성을 잃으시기도 하지만, 돈은 꼬박꼬박 주시고, 높은 곳의 물건에 제 손이 닿지 않을 때는 번쩍 들어주시기도 하거든요."
rows["167:342316819"]="토마스는 동부 왕국 최고의 요리사라고 하기는 좀 부족하지만 몇 가지 요리만큼은 누구 못지않게 잘한답니다. 지금 사자무리 여관에서 일하고 있을 테니 요리를 배우고 싶으시면 한번 찾아가 보십시오."
rows["167:391553067"]="폭풍의 눈의 마나 저장고는 매우 귀중한 자원이오. 드레나이에게 뺏길 수는 없지! 거기, 잠시만! 우리의 싸움에 동참해서 그대의 가치를 증명해 보이시오!"
rows["167:458748548"]="아서스의 약점은 오만함이다. 놈의 힘이 강해질수록 약점도 커지지. 칠흑의 기사단이 그 반역자 왕자 놈을 공격할 기회가 분명히 있을 것이다. 내 장담하지."
rows["167:494672651"]="아저워치에는 화공이 없는데, 하지만 남해안의 이상한 캠프에서 몇 명의 젊은 화공이 왔을 거 봤어요."
rows["167:579850962"]="바늘은 작지만 실은 강하며 이 실로 맺은 바늘 땀은 촘촘한 것입니다. 스랄 님과 다른 이들과 맺은 조약은 유효하니 호드를 이 땅에서 몰아낼 수는 없을 것입니다."
rows["167:596673919"]="전 무역회사 전쟁 이후로 물약을 만들고 있어요. 조만간 그만둘 계획도 없고요.$B$B이 세상에 구매자가 남아 있는 한, 이 늙은 바바는 언제나 물약을 팔 준비가 되어 있어요."
rows["167:905786930"]="우리끼리만 하는 얘긴데, 저도 모든 걸 다 아는 건 아니랍니다! 계속 배우고 싶으시다면 가게 주인인 스프링스핀들 피즐기어와 얘기해 보셔야 할 거예요."
rows["167:933375154"]="<묘사 의 피곤 한 모습 은  ⁇  에서 긴 하루 를 이야기 한다. 그  ⁇  은 그 깊이 에 의해서만 아니라 흙 벽 의 깨끗 하고 닦아진 완성 으로서도 인상 을 준다.>"
rows["168:1015233034"]="주제도 모르는 바보 멀베릭에게 격추당했소. 요새로 돌아가지 못하면 모든 게 끝장일까 두렵소! 멀베릭과 그 전투와이번 부대를 막아내야 하오!"
rows["168:1078419201"]="어떻게 그렇게 잘해내는지 모르겠지만 말로른은 아주 섬세한 약초도 다치지 않고 뽑을 줄 안답니다. 약초채집이라면 그에게서 배워야 할 거예요. 돌라나르 여관 바로 동쪽에 살고 있으니 그쪽으로 가보시지요."
rows["168:1209772126"]="대모께서는 우리 모두를 기르셨지요. 당신이 만난 모든 마그하리의 삶에는 대모의 손길이 닿아있어요. 아주 특별한 방법으로 말이죠. 대모께서 돌아가신다면 우리는 그분을 정말 많이 그리워할 거예요."
rows["168:1214292460"]="벌목기 녀석들?! 벌목기들이 더는 벌목을 하지 않으려고 하지. 어제도 그랬다니까!$B$B로켓을 완성하려면, X-52를 발사하려면 더 뛰어난 기술이 필요하다네!"
rows["168:1236074220"]="스톰윈드에서 연금술을 배워보려고 하신다면 연금술 소품점을 권해드리고 싶군요. 마법사 지구에 들어서서 왼쪽 길을 따라 가시면 연금술 소품이라고 쓰인 간판이 걸린 상점을 찾으실 수 있을 겁니다."
rows["168:1309085918"]="아라시 분지에서 포세이큰과 전쟁을 벌이고 있는 인간들이 지원을 요청하고 있습니다. 전투의 전당으로 가서 인간 대표 도날 오스구드를 만나 보십시오."
rows["168:1359697408"]="난 두 가지 특기가 있어. 작은 물건을 가져다가 크게 만들거나, 큰 걸 아주 작은 장소에 끼워 넣을 수 있다고.$b$b오늘은 어떤 게 필요한 거야?"
rows["168:1604716689"]="그 말이 맞아. 버드는 이 종족 저 종족 가리지 않고 어중이떠중이 다 긁어 모았다고.$B$B보아하니 술 좀 공짜로 돌리니까 개나 소나 잔뜩 몰려온 거지."
rows["168:1868233758"]="<기묘한 표정으로 당신을 쳐다보더니 고민하면서 잠시 머뭇거리는 교도관 트리로스.>$B$B장가르 습지대... 진실에 너무 가까이 접근했습니다.$B$B<다시 정신이 나간 교도관 트리로스>$B$B아직도 그가 지켜보고 있는 겁니까!?"
rows["168:1921967531"]="다르나서스의 장인들에게는 그대에게 도움이 될 만한 지식이 수천 가지는 있을 겁니다. 자, 말씀해 보십시오. 어떤 기술을 익히고 싶으세요?"
rows["168:1923349354"]="이제부터 당신은 나보다 더 높은 기술을 쌓게 되는 겁니다! 아이언포지에 있는 스프링스핀들 피즐기어를 찾아가서 나보다 더 잘할 수 있다는 걸 보여주십시오!"
rows["168:1933186429"]="그 사악한 짐승은 물리쳤지만, 소중한 물이 오염되고 말았다! 즉시 정화해야만 한다.$b$b이곳에 계속 머무르려거든, 스스로 방어할 마음의 준비를 해라."
rows["168:1939136123"]="뭘 부탁하시든 이 배의 기술자이자 배급담당인 코움스 씨가 가져다 드릴 겁니다. 게다가 무엇이든 척척 고칠 수 있으니, 손볼 게 있으면 말씀하십시오."
rows["168:1970894468"]="그룸누스를 만나고 싶으면 먼저 아이언포지로 가십시오. 그 도시 한복판으로 가서 대용광로를 둘러보면 그를 찾을 수 있을 거요."
rows["168:1986016056"]="이제부터 당신은 나보다 더 높은 기술을 쌓게 되는 겁니다! 아이언포지에 있는 스프링스핀들 피즐기어를 찾아가서 나보다 더 잘할 수 있다는 걸 보여주십시오!"
rows["168:348713285"]="테라모어의 수강장 밖에서 왜리한테 조심해\013\010\013\010\013\010\013\010그는 술에 취하고 폭발물도 가지고 있지만 충분히 친절하고 광산을 잘 알고 있습니다."
rows["168:400512911"]="드라카리들은 죽기 직전 상태인 내 육신을 제단 건물에 가둬놓았다. 하지만, 놈들은 내 영혼을 볼 수 없지.$B$B우리가 힘을 합쳐야 놈들이 내 힘을 악용하는 것을 막을 수 있다."
rows["168:441235037"]="아악... 두통 때문에 미쳐버리겠소.$B$B날 구하라고 그들이 보냈겠지? 왜 이렇게 오래 걸린 거요! 놈들이 포로에게 어떤 짓을 저지르는지 알기나 하시오?"
rows["168:465579831"]="여군주 프라우드무어의 군대는 아키몬드와 그의 불타는 군단을 막으려고 피를 흘렸다. 그리고 이제 우리가 아키몬드의 악마군에 맞서야 한다. 그대는 나와 함께 적의 맹공격에 맞설 각오가 되었는가?"
rows["168:586702684"]="악마들을 불러내는 것은 위험한 관행이지만 그 결과의 힘이 엄청나게 될 수 있습니다."
rows["168:958658526"]="도살자? 아, 응급치료사 말인가! 뭐, 결국 똑같은 거지. 마을 남동쪽에 있는 교수대끝 선술집에 있는 간호사 닐라를 만나 얘기해 보면, 금방 무슨 뜻인지 알게 될 거야."
rows["169:1035648676"]="이제 내 아기 멀록들을 데려가는 게 어떻겠나?! 나에게는 매처럼 날카로운 눈과... 뭐더라... 그러니까, 청력이 뛰어난 어떤 동물과 같은 귀가 있네!"
rows["169:1124555683"]="윌프레드 솔캐처는 도시 묘역에서 빛의 대성당 옆에 죽은 사람들과 함께 서 있습니다. 그는 대성당에서 내려오는 계단 밑에서 기다리고 있습니다."
rows["169:1203052813"]="쓰러진 티탄의 타락, 파괴자의 타락을 뜻하는 겁니다. 결국, 그 지팡이는 증오의 씨앗으로부터 탄생한 것이죠. 제가 여기 온 것도 바로 그 때문이고..."
rows["169:1412298618"]="여기 암흑갈기 일족과 피비늘 일족의 나가 지도자들에게 현상금이 걸려 있음을 알리는 벽보가 붙어 있습니다. 그 둘은 극히 위험한 놈들이므로 나중에 다시 확인하는 것이 좋을 것 같습니다."
rows["169:1427318428"]="제 물약 제조술은 그대에 비해 수준이 낮습니다. 이제 저기에 있는 에이네실을 만나도 되겠군요. 그녀도 그대가 좀 더 수준이 높은 교육을 받을 시간이 되었다는 것을 알아볼 것입니다."
rows["169:147685206"]="내가 할 수 있다면 훈련해 주겠는데, 하지만 좀 더 누군가의 도움이 필요해요. 아이언포지브론크가 보낸다고 말해!"
rows["169:158585868"]="지하수렁에서 연구하고 배우는 건 인생에 한 번 올까 말까 한 기회입니다.$B$B방금 전까지 강제 노역소의 상자에 갇혀 있을 때는 죽은 것과 다름없었던 것 같네요..."
rows["169:1707433633"]="고블린 기계공학의 핵심은 무조건 터뜨리고 보는 거야. 원하는 곳에서 펑펑 터지도록 하는 게 바로 우리의 장기라고."
rows["169:184829248"]="사절 탈룬은 우리의 새로운 동지들에게 이 세계의 정령에 대해 가르치라고 절 여기로 데려왔지요. 하지만 이들은 제 말을 들으려 하지 않는군요. 당신은 어떻습니까?"
rows["169:2023980386"]="당신처럼 조심성이 부족한 이가 이만큼 해냈다는 게 놀랍군...$B$B좋아, 부적을 하나 더 주겠어. 기분은 좀 나쁘군!$B$B어서 가보게."
rows["169:2050841312"]="강인한 성기사가 되기 위한 가르침을 받으려면 그레이슨 섀도브레이커 경만한 스승도 없을 겁니다. 그분은 대성당 광장에 있는 빛의 대성당에서 만나실 수 있습니다."
rows["169:2138463048"]="드레드 캡틴 데메자는 부티 베이에 진입해 해적의 날이라고 선언했습니다!$B$B그녀는 그녀와 함께 술을 마실 용기가 있는 모든 사람을 명예 승무원으로 만들려고 합니다."
rows["169:343346405"]="용아귀 부족한테 군사 용어를 설명하기가 얼마나 어려운지 모른다고. 왜 있잖아, \"전천후 사격\"이라던가 \"제압 사격\" 같은 거.$B$B다행히 \"사망자 집중 지역\"에 대해서는 설명할 필요가 없더군... 그러니까... 알아서 잘 해치우더란 말이지."
rows["169:501400901"]="전투에서 승리했습니다! 스컬지의 침공은 당분간 주춤할 것입니다. 고마움을 표시하고 앞일을 대비하는 의미에서 우리가 가진 것을 나눠 드리겠습니다."
rows["169:560997922"]="베스프리스투스가 조련한 히포그리프가 그대를 목적지까지 신속하게 데려다 줄 수 있습니다. 다르나서스 서쪽에 있는 문을 지나면 루테란 마을이 있는데 그곳에서 베스프리스투스를 찾아보십시오."
rows["169:73110654"]="알게르논이 물품을 다 대주니 나는 약초 하나 안 캐고 여기서 작업을 할 수 있다네. 앞으로도 계속해서 약초를 직접 캐지 않아도 된다면 멀지 않아 할 수 있을 걸세."
rows["169:779029907"]="엘룬께서는 나이트 엘프들에게 많은 재능을 부여하셨습니다. 그에 대한 보답으로 호드의 마력으로부터 숲이 오염되는 것을 막는 것이 저희의 의무입니다."
rows["169:898323683"]="지금 전운의 그림자가 최고조로 짙어지고 있지만 우리에게는 호드와 얼라이언스의 뛰어난 전사들이 많이 있기 때문에 아무 걱정이 없소.$B$B단, 이들이 서로 위협하지만 않는다면..."
rows["169:941391010"]="더는 가르쳐 줄 게 없소. 당신의 가죽세공술은 이미 나와 대등하니까. 저쪽에 있는 우나에게 가도록 하시오. 필요하다면 당신의 실력은 내가 보증하도록 하겠소이다."
rows["16:1065098919"]="무엇을 도와드릴까요?"
rows["16:1092107728"]="들어오는 건가 아니면 나가는 건가?"
rows["16:1098007182"]="우린 망할 처지에 처해있어요!!"
rows["16:1398443524"]="만나서 반갑습니다."
rows["16:1517902990"]="가고 싶은 곳이라도 있나?"
rows["16:1520533938"]="별일 없지?"
rows["16:1633317"]="그래서... 목마른..."
rows["16:1647096387"]="오우거는 웃기게 생겼다."
rows["16:1688352460"]="즐거운 하루 되시기를!"
rows["16:1688352473"]="안녕하십니까?"
rows["16:173682830"]="명령만 하십시오!"
rows["16:1865653672"]="이런, 좀비라고?"
rows["16:1870938291"]="안녕하십니까."
rows["16:1952756047"]="아옳아옳 글르글!"
rows["16:1954632403"]="어디로 갈 거야?"
rows["16:2075455054"]="뭐 잘못됐어?"
rows["16:269181982"]="전 여기서 요리를 하고 있단 말입니다!"
rows["16:340298528"]="<신음하는 퓨리엔>"
rows["16:516184198"]="자그마한 존재여, 무슨 일인가?"
rows["16:632476452"]="반갑네, 젊은이..."
rows["16:863052970"]="아, 겨우살이..."
rows["170:1007500619"]="당신이 우리의 골칫거리를 날려줄 수 있길 바라오. 우린 10명의 아들을 데리고 있으려 했으나, 녀석들 모두가 하지 말아야 할 것을 하고 싶어하지 뭐요!$B$B그래도 아버지로서, 해야 할 도리는 다하는 것이오."
rows["170:1098602510"]="조세타는 정말 이 마을에 축복과 같은 존재랍니다. 우리 경비병들까지 도와 주고 있으니까요. 그녀에게 사제 훈련을 받으려면 사자무리 여관으로 가보십시오."
rows["170:1285763653"]="전쟁의 혼란이 당신을 미치게 했습니까? 내 도움으로 승리가 다가오고 있습니다. 내 도움 없이는, 당신의 싸움은 어려울 것입니다."
rows["170:1306525340"]="유리부시 왜성 중 한 명이 보석공자라는 걸 확신합니다.\013\010\013\010\013\010\013\010남편인 것 같아요, 둘 다 탐험가예요."
rows["170:1368069876"]="사실, 엘드레탈라스의 마당과 전당을 배회하고 있는 명가의 영혼들은 고르독 오우거나 사티로스의 침략으로 살해된 것이 아닙니다. 바로 토르텔드린 왕자에게 죽임을 당한 것이지요!"
rows["170:1403000110"]="아주 많은 것을 알고 계시군요, 여행자님. 당신은 나보다 더 현명한 사람에게 배워야 해요. 조셉 그레고리안이라는 자의 지혜에 대해서 많이들 얘기하니 언더시티로 한번 가보도록 하세요."
rows["170:1436933359"]="달라란의 얼라이언스와 호드 지구인 은빛 자치구와 선리버 성소에서 스톰윈드와 오그리마, 그리고 여러 전장으로 갈 수 있는 차원문을 찾을 수 있답니다."
rows["170:1559097535"]="한디르와 우 핑이라는 두 도검 전문가가 있습니다. 한디르는 엑소다르의 교역 지구에서 만날 수 있으며, 우 핑은 스톰윈드 내에 있는 웰러의 무기고에서 만날 수 있답니다."
rows["170:1595238972"]="종파의 솔리라스 다크웨븐과 수확자의 투랄렌 다크비스퍼는 세나리온 앙클라브에 거주하고 있으며, 악당들이 모여있는 아래 동굴의 나선 경로로 내려간다."
rows["170:1636156292"]="이 황혼의 망치단 자식들, 조금은 인정해 줘야겠습니다... 기술은 없어도 머릿수를 믿고 끈질기게 밀어붙이더군요. 마지막으로 우리와 한바탕 할 땐 봐줄 만했습니다."
rows["170:170928857"]="동부 역병지대에 스컬지의 수가 점점 늘고 있습니다. 신체 건강한 자들은 모두 나아가 그들의 침략을 막아야 합니다.$B$B남아 있는 죽음의 요새: $2282W개"
rows["170:176490680"]="안녕하세요, 그리고 Darkmoon Faire Staging Area에 오신 것을 환영합니다.$b$b이 포털은 당신을 암흑달의 요정으로 데려다 줄 것입니다.$b$b하지만 떠나기 전에 질문이 있다면, 제가 대답할 수 있습니다."
rows["170:179391341"]="월 축제의 가장 큰 축제는 무글라데에서 열리고 있습니다. 여행하기 너무 멀리 있다면, 지혜의 계곡에서 운송을 제공하는 드루이드가 있습니다."
rows["170:1807520965"]="이보시오! 틸스의 심부름을 온 거요? 내가 당신이라면 그자를 가까이하지 않을 거요. 술에 절어 제정신이 아니지... 하지만 마법만은 여전히 강력하다오!"
rows["170:1878667791"]="스스로 호드를 위한 무기와 방어구를 만들기 위해, 단단한 금속을 두드릴 힘이 있다고 생각이 들거든, 칼바위 언덕의 북서쪽으로 가게. 가열로 옆에 있는 드우크를 찾아가."
rows["170:2027468813"]="황혼의 망치단은 나에게 조직 그 이상의 의미가 있다. 가족이나 다름없지.$B$B자격 미달인 지원자가 훈련 과정을 통과하지 못하도록 내가 각별한 주의를 기울이는 것도 다 이런 이유 때문이다."
rows["170:2070821742"]="흠, 물약 만드는 소질이 좀 있으시군요. 그렇다고 제자로 받아들이겠다는 건 아닙니다. 전 아주 바쁜 몸이니까요. 저를 만족시킨다면 또 얘기가 틀리지만. 당신에게 맡길 일이 있습니다."
rows["170:2073674947"]="섬세하게 짜인 시간과 공간 사이에 난 이 틈은 불길하게 느껴집니다. 다양한 장면이 무시무시한 속도로 스쳐 지나갑니다. 진정 용감한 자만이 감히 이곳을 통과하려고 할 것입니다..."
rows["170:2084120549"]="물 원자체는 불 원자와 전쟁을 벌이고 있어, 이는 그들이 우리와 전쟁을 벌이고 있다는 뜻입니다."
rows["170:231075586"]="원소 가죽세공을 취소하는 것은 그리 간단한 일이 아니랍니다. 원소 가죽세공을 취소하면 원소 가죽세공의 제조법 또한 모두 사라집니다!"
rows["170:39100232"]="레더볼 리그에 참가하고 싶으세요? $B$B이 셔프 후 우리로 가자"
rows["170:407495371"]="북쪽의 우리 큰 집 썬더 블러프 에 한 수강자 가 있다. 그러한 지식을 찾고 있다면 그곳으로 가서 블럭워치 중 한 명에게 방향을 물어보십시오."
rows["170:500241613"]="난 해변을 방어하는 데 필요한 지원군을 요청했소. 그랬더니 호드가 이 조그만 난쟁이들과 이들이 만든 자그마한 금속 기계를 보내 주더군.$B$B<무시하는 눈초리로 주변의 고블린들을 바라보는 그랄록>"
rows["170:515851317"]="그 어떤 오크도 나처럼 전투에서 도망쳐서는 안 되오. 결코 씻어낼 수 없는 불명예를 지고 말았소. 이 탑에서 죽음을 맞이하면 좋겠지만 선조께서 겁쟁이인 날 어떻게 여기실지 두렵소."
rows["170:592114913"]="스코른이랑 지평선 너머 여기저기로 신나게 쏴대고 나니 돌아온 일이 뭔지 아십니까?$B$B포탄 회수 임무란 말입니다!$B$B전 이런 일을 하자고 입대한 게 아니란 말입니다. 무슨 말인지 아시겠습니까?"
rows["170:627949951"]="<서투른 공용어로 말하는 회색의 검투사> 뭐라고? 나한테 볼일이라도 있나? 그렇다면, 투기장으로 와라. 너 같은 풋내기 '호드'나 '얼라이언스'에게 낭비할 시간 따위는 없으니까."
rows["170:672473826"]="자네에겐 더 가르칠 게 더 없군. 하지만 자네를 가르칠 만한 나이트 엘프를 하나 알고 있다네. 에이네실이라고 다르나서스 장인의 정원에 살고 있으니 그리 가 보게."
rows["170:760583031"]="가시덤불의 트롤들은 우리 검은창 부족을 매우 싫어하지. 붉은머리 부족이나 백골가루 부족 따위는 두렵지 않지만, 그래도... 그롬골의 높은 벽을 보면 안도감이 느껴진다네."
rows["170:772973991"]="전쟁의 기운이 또다시 흐르고 있습니다. 차가운 북쪽으로부터 리치 왕이 보낸 죽음의 요새가 우리 땅을 포위해 공격하고 있습니다. 리치 왕은 공중을 나는 죽음의 요새를 보내 세계를 정복하려 합니다."
rows["171:1069271941"]="그래요! 모두 지하철을 타보고 싶어 하지요. 정말 재미나거든요. 깊은굴 지하철은 아이언포지 성문에서 바로 동쪽에 있는 땜장이 마을에 있습니다."
rows["171:1249212045"]="꽤 괜찮은 실력이지만 모서리 둘레가 좀 거칠군요. 그건 연습하면 나아질 테니까 걱정하진 마세요. 말이 나와서 말인데 요즘 당신이 만들고 있는 거나 한번 보도록 하죠."
rows["171:1622433665"]="어느 날 밤 거장 오마리온이 홀연히 사라졌네. 마치 바람에 실린 방귀처럼... 휙 하고 사라졌지! 흥, 이제 최전선의 병사들에게 필요한 물건을 만들어 줄 수 있는 건 이 몸밖에 없단 말일세."
rows["171:1647473223"]="순례자의 보너스는 자신의 행운을 생각해보고 주변 사람들과 공유하는 시간입니다.$B$B우리는 우리의 귀족 동맹국들이 함께 축하하고 축하하기를 바랍니다."
rows["171:1735478124"]="우리가 고통받고 있을 때 등을 돌린 드레나이와 교섭을 하라는 말입니까? 나는 그리 생각지 않습니다.$B$B진정한 새의 영혼이라면 그런 말을 할 수 없다! 정체를 밝혀라, 이 사기꾼. 누가 보내서 왔느냐?"
rows["171:1791196457"]="그대는 저의 능력을 능가하시는군요. 다르나서스의 장인의 정원에 있는 에이네실이라는 나이트 엘프를 찾아가 보시면 그녀가 더 많은 것을 가르쳐 줄 것입니다. 저도 그대와 함께 가고 싶을 뿐입니다."
rows["171:1855829888"]="나는 고통을 받는 영혼을 정화하고자 이 땅에 왔지만, 공격을 받은 이후론 내 임무가 실패할까 봐 걱정일세. 너무나 많은 이들이 이 무덤에서 희생되었어. 제발 그들을 도와주게나."
rows["171:1860313852"]="그건 나도 모르지, 친구. 나도 새로 왔거든.$B$B난 할당 받은 만큼 트롤 사냥을 끝내 놓고 그로그주를 마시고 있을 뿐이야, 암 그렇고말고. 이제 남은 볼 일은 버드가 계속 약속하는 그 보물뿐이지..."
rows["171:1903925596"]="훈련을 받고 싶으시다고요? 저한테서요? 아주 좋죠! 탄환이랑 폭발 장치를 조립하는 것보다 더 나은 유일한 일은 바로 그 지식을 다른 이와 나누는 거니까요! 어서 시작해요!"
rows["171:1916870035"]="<상간의 시선은 불꽃에 달려있는데, 그는 생각에서 길을 잃어 버린 것처럼 보입니다. 당신은 그의 옆에서 불꽃이 더 활발하게 불고 있음을 알 수 있습니다. 마치 오크를 만져보고 만 ⁇ 을 위해 노력하는 것처럼.>"
rows["171:1936372073"]="이 아이들은 살 겁니다. 사랑과 애정 속에서 그들은 호드의 강한 일원으로 성장할 것이고, 끔찍했던 어린 시절의 기억은 시간이 지나면서 점차 바래겠지요."
rows["171:1950864549"]="꽤 괜찮은 실력이지만 모서리 둘레가 좀 거칠군요. 그건 연습하면 나아질 테니까 걱정하진 마세요. 말이 나와서 말인데 요즘 당신이 만들고 있는 거나 한번 보도록 하죠."
rows["171:1987262809"]="저기 좀 봐, 칭구! 저 천박 바보 완전 끝났어. 저 저속한 녀석 바닷물 실컷 마시다 배 밑바닥 끌려가 곧 귀신 된다."
rows["171:2003469139"]="시험의 골짜기에서는 칼림도어에서 가장 허약한 자라도 호드와 어깨를 나란이 하고 싸울 수 있을 만한 강력한 전사로 단련시켜 주지. 우리의 시험을 통과하지 못한 자들은 이글거리는 사막의 태양 아래서 타죽게 된다고."
rows["171:2030580905"]="이 숨겨진 통로 쪽에서 아래쪽의 적에게 기습 공격을 퍼부을 수 있소.$B$B기습 작전에 정의 따위는 없지만 훌륭한 전사라면 적의 허를 찌를 줄도 알아야 하는 법이오."
rows["171:2065786653"]="우리 모두 끔찍한 비극을 경험했지만, 결코 절망하지는 맙시다.$B$B다만, 빚을 갚아줄 그날까지는 그 기억을 잊어서도 안 되오."
rows["171:230045188"]="저희는 보통 노움들에게 그런 일을 맡깁니다. 기계공학을 익히고 싶으시다면, 스톰윈드에서 지내는 노움들이 가르쳐 줄 수 있을 겁니다."
rows["171:282745098"]="어서 오세요! 저희와 함께 순례자의 감사절을 즐기러 오셨나요? 자, 푸짐한 잔칫상에 앉으세요.$B$B일단 전부 맛을 보세요! 분명히 맘에 드는 게 있을 테니까요."
rows["171:574876235"]="선스트라이더의 블러드 엘프와 사이가 좋아졌기에 난 아웃랜드에서만 찾을 수 있는 이 피실험자와 함께 실험을 진행하려 하오. 그들은... 내 훌륭한 인격과 남자다운 외모에 감탄할 것이 분명하오이다."
rows["171:589763796"]="유행 스타일에 대해서는 이미 충분히 알고 있습니다. 이젠 가죽 다듬는 법만 통달하면 되죠. 사이먼이 흔쾌히 도와줘서 정말 다행입니다."
rows["171:621258926"]="시험의 투기장은 한때 매우 영광스럽고 명예로운 곳이었네. 하지만 그때 스팀휘들 무역회사가 도착했지. 황금과 오크의 도끼보다 날카로운 깃펜을 가득 실은 마차와 함께..."
rows["171:646508517"]="이봐요, 사람들이 알록달록한 알을 찾으러 사방을 뛰어다니며 흙 속을 뒤지고 싶다는데, 제가 뭐라 하겠어요? 어쨌든 전 물감 값으로 좀 버는 데다가 올해는 닭에도 투자했다고요."
rows["171:83365060"]="여기서는 적이 수적으로 우세한데다, 십자로와 듀로타와의 연결망은 차단된 상태라네. 하지만 얼라이언스 열 놈이 우리 오크 한 명을 못 당해내지 않겠나.$B$B이 통로에서 저들의 세력을 억제하고 돼지 멱 따듯이 끝장내 버리세."
rows["171:892920232"]="<서투른 공용어로 말하는 회색의 검투사> 뭐라고? 나한테 볼일이라도 있나? 그렇다면, 투기장으로 와라. 너 같은 풋내기 '호드'나 '얼라이언스'에게 낭비할 시간 따위는 없으니까."
rows["171:9344574"]="바람의 돌로부터 천둥 같은 고함 소리가 들려옵니다...$B$B반갑네, 지휘관. 심연의 군주님께 전할 실리더스에 관한 새 소식이란 게 뭔가?"
rows["171:9404332"]="어이! 오늘은 해적의 날이라는 것, 알고 있겠지... 내일 해가 뜰 때까지 무법항은 바로 내 것이라고."
rows["171:979840278"]="주.정.뱅.이.는 그냥 맥주잔 던지는 표적이 아니라 정말 귀중한 훈련 도구라고. 주.정.뱅.이.를 맞힐 수 있다면 세상에 못 맞힐 게 없을걸!$B$B그렇다고 나한테 시험해 볼 생각은 말라고."
rows["172:1133228123"]="야수의 지혜와 지식을 보면 자신을 볼 수가 있소. 올빼미와 같은 관찰력을 기르고, 퓨마의 영리함을 배우며, 늑대의 강한 영혼을 몸에 담도록 하시오."
rows["172:1366816043"]="여기 이 좁은 곳에 이 흑마법사 녀석들하고 갇혀 있는 건 참을 수가 없군. 녀석들 관리는 자이룬의 일이지 내 일이 아니란 말일세!$b$b전투가 시작되기까지 기다릴 수가 없군. 내 용들과 밖으로 나가야겠어."
rows["172:1586968214"]="피알 시일렌트스트라이드는 블러드하프 마을의 최고의 요리사입니다."
rows["172:1706226956"]="야수 카드를 모아 한 벌이 되면 푸른용의 상급 다크문 카드를 보상으로 받게 될 겁니다. 이 카드는 마법의 힘을 회복하는 데 아주 유용하지요."
rows["172:2052350247"]="자연에서 구한 약초는 그것을 존중하는 마음으로 대할 때 우리의 강력한 동지가 되어 줄 것입니다. 봉우리 중간층에서 연금술 가게를 운영하고 있는 베나를 찾아가서 훈련을 더 받도록 하십시오."
rows["172:25429468"]="이 버섯은 보통 버섯과는 달라요. 이걸 먹는 자에게 엄청난 지혜와 청명함을 선사한다고 하죠.$B$B스포어가르로 몇 개 가져갈 겁니다."
rows["172:64277122"]="알렉스투스는 상처를 치료하는 데 능숙해 보니까 첫 번째 도움을 받는 것이 목표라면 왕실 교역 입구 근처의 노인도에서 찾아봐"
rows["172:698985834"]="미안하지만 당신을 가르치는 것은 제 능력 밖입니다. 더 많은 것을 배우고 싶다면 다르나서스 장인의 정원에 있는 텔로니스를 찾아가 보세요. 듣기로는 아주 실력파라고 하더군요."
rows["172:887794348"]="프리즘 내에 불타는 눈들이 당신의 마음을 불안함으로 뒤덮고 있습니다... 이 프리즘의 악마를 소환할 수 있는 35개의 에펙시스 결정이 충분치 않다는 사실을 알고 나니 불안한 마음이 특히나 더 가득해집니다."
rows["173:1068536003"]="오그리마로 가야겠군. 칼바위 언덕에서 나가는 북쪽 길로 곧장 가게. 그곳 그런트에게 물어보면 길을 더 자세히 가르쳐 줄걸."
rows["173:122038061"]="전설의 팔 안에 사요크와 한아시를 찾아라. 아니면 사요크가 너한테 한 조각을  ⁇ 거리는 개에게 줄 수도 있다."
rows["173:1301459163"]="아뇨, 도와 드릴 수가 없네요. 이미 저를 능가하셨거든요! 더 배우고 싶으시다면 다르나서스 장인의 정원에 있는 텔로니스라는 나이트 엘프에게 가 보세요. 정말 훌륭한 분이죠!"
rows["173:1354585187"]="<얘기를 시작하는 추알로르의 왼쪽 머리>$B$B우리 도우려고 하는 당신의 열의 매우 호소적이고... $B$B<말을 맺는 추알로르의 오른쪽 머리>$B$B... 우리가 당신의 노력에 매우 감사하고 있다는 거 알아줬으면 한다!"
rows["173:1633446747"]="오그리마에 무슨 일이 벌어지고 있는 게 분명하네. 왠지 느낌이 안 좋아. 이 여성들은 가족이 사라졌다고 걱정하고 있고, 또 다른 이들은 세상이 멸망할 거라고 말하네. 대체 무슨 뜻이지?"
rows["173:1788407240"]="공원 의 달수리 근처 에 테리든 이나 말드린 을 찾을 수 있습니다. 마지 구역 북쪽 에 있는 스톰윈드 서쪽 지역 으로 향 해 보세요."
rows["173:18631632"]="불타는 군단에게 사로잡히면 그들에게 \"자르 일 로마스 다 티데스비\"라고 하십시오. 자기들의 신을 모독했다는 이유로 그 자리에서 당신을 죽일 겁니다. 그러면 적어도 끔찍한 고문을 받는 일은 면할 수 있겠지요..."
rows["173:1885882843"]="저에게 그분이 환생할 수 있는 결정이 있습니다. 이 임무를 맡을 각오가 되었다면 결정을 강하게 만드십시오. 궁극적으로 라그나로스의 마수로부터 벗어나야 합니다!"
rows["173:1894789496"]="아스타이아는 오랜 세월 동안 낚시를 하면서 희한한 보물들도 많이 낚아 올렸답니다. 상인의 정원으로 가세요. 그 보물 몇 개만 한번 보여 달라고 청해 보십시오."
rows["173:1925811607"]="그냥 변해야 돼... 아니, 그런게 아니야.$B$B아, 안녕하세요, 내가 당신을 보지 못했습니다! 아니, 난 완벽하게 괜찮아요, 감사합니다!"
rows["173:2056413195"]="달라란을 방문한 호드들은 달라란의 북동쪽에 있는 선리버 성소에서 주로 지내고 있습니다.$B$B성소에는 여관도 있고 오그리마와 여러 전장으로 갈 수 있는 차원문이 있답니다."
rows["173:207657891"]="아니요, 괜찮습니다. 이런 경험이 많으니까요...$B$B<재미있어 하면서도 짜증나는 듯한 표정을 짓는 타엘라>$B$B저는 하이 엘프이지, 블러드 엘프가 아니랍니다. 그러니 당신 마법을 빨아들이진 않을 테니 걱정하지 마세요."
rows["173:244964534"]="즐겨 마시는 술이 뭔가? 의자에 편히 앉게나.$B$B나는 B.O.O.M. 밑에서 일하는 선임 바텐더 부츠라고 하네!$B$B진정 효과가 좋고 강한 술 한잔을 원한다면 이 부츠가 만들어 줄 수 있지."
rows["173:291331352"]="말한 대로 건방진 참견이 사라지니 쿠아그미란이 가까이 왔군요!$B$B약속드린 대로 그와 싸우는 데 도움이 되는 신비의 은혜로 그대를 강하게 해드리지요."
rows["173:359560543"]="우리는 한동안 이 벌레들을 돌봤지. 이 단체에서 행사를 시작할 때까지 벌레들이 다 컸으면 좋겠군. 그대들은 요르문가르 하나가 아니라 둘과 맞서야 하니까 말일세."
rows["173:372213993"]="캘타스의 추종자들은 이제 겸손이란 게 뭔지 배울 것이오. 우리가 이제 새벽칼날단을 쳐부수고 태양너울 항구를 되찾을 테니.$B$B임무는 지금 $3238w 퍼센트까지 달성한 상태요."
rows["173:440275001"]="오래된 선택이지만 내가 판단할 수 있는 사람이 아니지 모르겠지만, 당신은 댄웨를 쫓고 있는데, 그의 엔지니어링 텐드는 태양의 궁전 근처에 있습니다."
rows["173:678172568"]="아레나 배틀마스터를 찾고 있어요?$B$B여기 묶어줄 수 있고, 수도권으로도 이동할 수 있습니다."
rows["173:723371107"]="오그리마 외곽에는 두 개의 비행선 탑이 있네. 동쪽 탑은 티리스팔 숲과 가시덤불 골짜기로 가고, 서쪽 탑은 노스렌드와 썬더 블러프로 가지."
rows["173:986971444"]="아즈샤라 님께서 여왕이시던 시절, 이곳은 엘프 왕족의 도시였어요. 이 도시에는 오래전에 사라진 전설을 찾아 줄 열쇠와 엄청난 역사적 가치를 지닌 유물이 숨어 있죠."
rows["174:1007467802"]="북녘골과 스톰윈드 사이의 언덕에 사는 약초상 포메로이가 연금술사에게 약초를 제공하는 일을 하지요. 언덕 위 오두막으로 찾아가서 그녀에게 가르침을 구해 보시죠."
rows["174:1353108380"]="흑마법사라고요? 만약에 제가 흑마법사였다면 틀림없이 이 부근에서 제일 어두운 곳에 있을 겁니다. 그렇다면 사자무리 여관의 지하실이 딱 좋겠지요. 먼저 그곳에 가 보셔야 할 겁니다."
rows["174:1548280703"]="오, 정말 굉장하군요! 정말 재미있었지 않나요? 그 역겨운 잃어버린 드레나이들에게 조금씩 조금씩 저주를 걸고 있었는데 조만간 드레나이에게 시험해 볼 생각이랍니다!"
rows["174:1569708826"]="징징대는 얘기는 별로 듣고 싶지 않으신 게로군요. 좋아요.$b$b그냥 당신이 얼마나 행운아인지만 잊지 말아 주세요. \"바다 걸음\"도 있고 \"위쪽이 아닌 다른 방향으로 헤엄칠 수 있는 능력\"도 있으니까요."
rows["174:1642858437"]="나보다 재봉술 솜씨가 좋은 자가 아제로스에 있다면 딱 하나뿐입니다. 마지막으로 들은 소문에 의하면 테라모어 섬에 있다고 하던데, 바로 그분을 찾아가야 할 겁니다."
rows["174:1677586493"]="주.정.뱅.이.는 그냥 맥주잔 던지는 표적이 아니에요. 정말 귀중한 훈련 도구이지요. 주.정.뱅.이.를 맞힐 수 있다면 세상에 못 맞힐 게 뭐가 있겠어요!$B$B그렇지만 저한테 시험해 볼 생각은 마세요."
rows["174:1770760714"]="문에서 북쪽으로 미스터리 홀로 향하고, 예야 플린스탬머는 홀 바닥에서 템플러들을 훈련시키고, 선배드 신자는 갤러리에서 태양 성직자들을 가르치고 있습니다."
rows["174:1800605196"]="발굴현장을 포기하자고요? 웃기는군요! 제가 근면하고 성실하게 일한 오랜 경력을 통틀어 현장을 포기한 적은 없습니다. 고의적으로 말이에요. 잘못 판 적은 몇 번 있을 테지만요. 근데 당신 누굽니까? 우리 여기서 뭐 하는 거죠?"
rows["174:1954653935"]="열광 카드 한 벌을 완성한다면, 광기의 다크문 카드를 보상으로 받게 될 겁니다. 당신이 적을 처치하면 언제든 광기의 힘이 당신을 채우게 될 겁니다."
rows["174:275103562"]="드래곤 스칼라 가죽 을 만드는 일 을 잊는 것 은 가볍게 하는 일 이 아닙니다. 만약 그 일 을 포기 하기 를 선택 한다면 드래곤 스칼라 가죽 을 만드는 일 을 필요로 하는 모든 요리법 을 잊을 것 입니다!"
rows["174:414548305"]="당신도 주술사입니까? 흠, 어떤 길을 선택할지는 모르겠지만 그 선택은 당신이 하는 것이겠죠... 상급 주술사인 툴룬은 하늘 감시초소의 북서쪽 외딴 곳에 작은 야영지에 있습니다."
rows["174:51488792"]="남쪽 원정순찰대 초소에 순찰자 살리사, 서쪽 트랜퀼리엔에 순찰자 레스발린을 보낸 지 하루가 넘었습니다! 그들을 보신 적이 없습니까? 혹시 그들의 부탁을 받고 오신 분입니까?"
rows["174:598540822"]="말도 안 되는 소리. 내가 눈먼 종자를 고용했더냐? 사방이 용 천지이지 않으냐.$b$b내 이웃 스파크는 이놈들을 \"공룡\"이라고 부르지만 내 눈에는 엄연히 용으로 보이느니라. 이놈들을 반드시 처단해야 한다."
rows["174:602675855"]="달라란의 투기장과 투기장 관련 인물들은 달라란의 아래쪽 하수도에서 찾을 수 있습니다.$B$B투기장으로 가는 길은 적어도 3가지가 있답니다. 바로 동쪽, 서쪽 입구와 북쪽에 있는 우물입니다."
rows["174:610939387"]="우리 아버님께서 항상 말씀하셨듯, 성공적인 투자가가 되기 위해서는 기민한 두뇌와 날카로운 본능, 그리고 한결같은 용기가 필요합니다.$b$b전 틀림없이 이 발굴 작업에서 풍기는 성공의 향기를 맡았었지요."
rows["174:884950225"]="그대의 기술을 보면 물약 제조술에 대해 상당한 애정이 있음을 알 수 있습니다. 하지만 그것으로는 조금 부족합니다. 그런 의미로 임무를 하나 드리도록 하겠으니 이를 완수하신다면 저도 만족할 수 있을 겁니다."
rows["174:919459544"]="지팡이 사용법이라면 스톰윈드 웰러의 무기고에 있는 전문가인 우 핑이나 다르나서스의 전사의 정원에 있는 나이트 엘프 일예니아 문파이어에게서 배울 수 있을 겁니다."
rows["175:113845915"]="아름답지 않나요? 우리는 크나큰 희생이 치러진 지난 세월을 반드시 기억해야 해요. 그리고 승리한 전쟁일지라도 우리가 치른 대가를 잊어서는 안 된답니다."
rows["175:1212436603"]="드레나이다... 그런 이유로 나는 이도 저도 아니지. 오크도 아니고 드레나이도 아니란 말이다. 나와 같은 종족은 극히 드물다. 수십 년 전 대부분 살해되었지... 나는 강인한 의지 덕분에 지금까지 살아 있는 것이다."
rows["175:1341524374"]="조카스테는 전성기에 동부 왕국에서 가장 뛰어난 사냥꾼이었습니다. 요즘에는 세나리온 자치령에서 사냥꾼의 길을 걷기 시작한 새내기들을 가르치고 있지요."
rows["175:1364947911"]="그라니스 스위프트액스는 끝도 없이 술을 퍼마시곤 하지만 도끼 하나는 정말 제대로 휘두를 줄 압니다. 훈련을 받고 싶은 거라면 그가 너무 취해 곯아떨어지기 전에 찾아가 보는 게 좋을 겁니다."
rows["175:1540338985"]="꼭 그런 건 아니다. 사실, 이 분화구의 많은 생물체는 주인님이 오시기 전부터 존재했다... 하지만 어떤 생물체는 주인님이 만드셨지.$b$b하지만 우린 모든 생물체를 아무 편견 없이 관찰한다."
rows["175:1560270910"]="아, 진작 얘기하지 그랬나? 황혼의 망치단 놈들에게 몇 방 먹여주고 돌아오거든 나랑 잔치를 벌이자고!$B$B나는 해변에 있는 작고 사랑스러운 오두막에서 우리 마나님이랑 오순도순 살고 있다네. 일 끝나면 들르게!"
rows["175:1567500991"]="아라시 분지에 사는 인간들이 지금 필사적으로 도움을 청하고 있습니다. 전사의 정원으로 가서 케라스 울프하트라는 자와 얘기해 보십시오. 그대가 오기를 기다리고 있을 겁니다."
rows["175:1586999961"]="이 아래에 묻혀 있는 것들에 대해 불평할 수는 없어. 모두 대체품뿐이거든. 대체품도 대체할 것들. 며칠만 시간을 주면 해초와 조개껍데기를 벗어날 고성능 수중 유영기를 만들어 보겠어!"
rows["175:205378191"]="보조 방어 시스템을 활성화하면 권한 없는 생명체는 궤도적 방어 장치를 통해 모두 제거될 것입니다.$B$B당신은 권한 없는 생명체입니다. 확인해 주십시오."
rows["175:237145887"]="드레네이 샤만은 '파크 썬더하프'가 '테임플 가든' 섬에 위치해 있습니다."
rows["175:376897427"]="로얄 거래소 에 위치한 실버문 시티 인은 벨라드라라는 재능 있는 여성 이 운영 하는 곳 이다. 유명 포도주 관리자 는 때때로 그 곳 에서도 발견 될 수 있다고 알려졌다."
rows["175:407064647"]="시험의 골짜기에서는 칼림도어에서 가장 허약한 자라도 호드와 어깨를 나란이 하고 싸울 수 있을 만한 강력한 전사로 단련시켜 주지. 우리의 시험을 통과하지 못한 자들은 이글거리는 사막의 태양 아래서 타죽게 된다고."
rows["175:481859216"]="고릴라는 환상적인 생물체입니다. 도박에 돈을 모두 탕진하고 \"바다늑대\" 맥킨리의 명단에 오르는 바보 같은 나이트 엘프보다 훨씬 똑똑하죠."
rows["175:675040743"]="티인은 재능 있는 스킨러입니다. 제가 본 최고의 린크스피드를 만들어냅니다. 만약 그녀로부터 배우고 싶다면,"
rows["175:73710818"]="비록 자네가 우리를 구해내는 데는 성공했지만 크툰을 꺾지는 못했다. 우리 모두 힘을 모아 그 괴물을 지옥으로 다시 추방해야 한다. 어떤 대가를 치르더라도!"
rows["175:75406243"]="다들 나보고 멍청하다고 했지만 그들에게 보여주고 말겠어. 여기 있는 모든 냄비를 쳐다보고 있다가 그래도 물약이 끓는다는 것을 증명해 보이겠어! 꼭 성공할 거야! 이제 누가 진짜 멍청한지 말해봐! 말해보라고!"
rows["175:925130305"]="흠, 그런 부류를 찾으시는군요. 글쎄, 이 근처에서 흑마법에 대해 알만 한 이라면 맥시밀리언밖에 없습니다. 사자무리 여관의 어두컴컴한 지하로 내려가면 그를 찾을 수 있을 겁니다."
rows["175:934483348"]="아, 그래서... 당신은 그것을 찾았어.$B$B<Mathredis는 당신 손에 있는 책을 가리키고 있습니다.>$B$B필요한 부품들을 수집했나요?$B$B이리브람에 기록된 표면, 멍청이!"
rows["175:947521304"]="당신과 당신 부족이 우리의 동맹으로서 함께하겠다고 하시니 우리도 이 섬에 계속 남아 재건하기로 결정했습니다. 엘룬의 가호가 있기를, 영웅이여.$B$B슬픔은 왔다가 사라지지만 우리는 살아남을 겁니다."
rows["176:1159380926"]="모르겠습니다...$b$b나가들은 매일 새로운 포로들을 데려왔으니까요. 호드든 얼라이언스든 가리지 않았죠.$b$b어떤 포로들은 데려온 날 바로 어디론가 끌고 갔고... 또 어떤 포로들은 저처럼 일주일쯤, 아니면 그보다 더 오래 붙잡아 놓기도 했습니다."
rows["176:1192374830"]="그렇소. 베네딕투스는 고룡쉼터 사원에 있는 위상들을 도우려고 갔소. 그는 데스윙의 위협에 빠진 아제로스를 정화하고자 그들을 돕고 싶어 했다오.$b$b베네딕투스의 앞길에 성스러운 빛의 가호가 함께하기를."
rows["176:1237271658"]="이건 마구잡이로 하는 공격이 아닐세. 정령과 거인들이 힘을 합쳐 우리를 노리는군. 뭔진 몰라도 우리가 바위 어머니, 테라제인 님의 노여움을 산 모양일세."
rows["176:1247359120"]="위대한 전사가 되고 싶으십니까? 전쟁은 전사를 위대하게 만들어주지 않지요. 그래도 교역 지구의 나머지 부분이 내려다보이는 전사의 정원에 가면 위대한 상급 전사들을 만날 수 있을 겁니다."
rows["176:1304469343"]="처음으로 언데드를 봤을 땐 그들의 공포와 외로움이 너무 커보였기에 눈물을 흘릴 수밖에 없었습니다. 그때 대지모신께서 제게 말씀하셨지요. 그분께서는 제 핏속에서 노래하셨습니다. 그러시면서 \"그들을 구하라.\"고 말씀하셨답니다."
rows["176:1356334545"]="내가... 죽었단 말이오?$b$b그렇소, 당신 말이 맞소. 나는 죽었소. 오크 때문이었다오... 그 오크가 내 손을 자른 뒤에 죽도록 놓아두었지.$b$b<손을 내려다보는 발드레드>$b$b...이건 내 손이 아니잖아! 내 손이 아니라고!!!"
rows["176:1392569540"]="오래전에는 우리는 하나로 된 낙하복을 입었지요. 우리의 혁신적인 재봉사들 덕분에 더는 그렇게 비실용적인 의복을 입지 않아도 되게 되었답니다. 교역 지구에 가면 이 의복의 선구자들을 만날 수 있을 겁니다."
rows["176:1484215302"]="잔자에게 알맞은 재료만 주면 고대 트롤 주술을 사용할 수 있소. 그 마법은 학카르와 그의 부하들을 무찌르는 데 큰 도움이 될 거요.$B$B자, 두 가지 물건만 가져다주시오."
rows["176:15867532"]="\"강철의 독수리호\"라. 흠. 이건 군용 항공기가 아니고 여객선이라고요! 하지만, 이봐요, 일은 일이잖아요? 월급만 제대로 준다면야 얼마든지 \"봄블라스트\" 선장님께 맞장구쳐 드리죠 뭐.$b$b어쨌든, 저희 비행선에 오신 걸 환영해요."
rows["176:1682365238"]="달라란을 방문한 호드들은 달라란의 북동쪽에 있는 선리버 성소에서 주로 지내고 있습니다.$B$B성소에는 여관도 있고 오그리마와 여러 전장으로 갈 수 있는 차원문이 있답니다."
rows["176:1949888372"]="전 대해에서 들려오는 소리를 들으며 여기 앉아 있는 것을 좋아한답니다. 오, 뭐라고 하셨죠? 네, 메네실 항구로 가는 배가 있죠. 이곳에 가끔 정박한답니다."
rows["176:1976451058"]="안녕, 내 불에 나눌래?\010\010여기서는 꽤 어두워지고 이상한 소리들이 내 척추를  ⁇ 어 내 척추를 떨게 해줍니다.\010\010...이건 정말 멋지진 않나요?"
rows["176:2112468798"]="드레나이 군대와 동맹인 얼라이언스가 아웃랜드의 폭풍의 눈에서 호드와 전투를 벌이고 있습니다. 폭풍의 눈에서의 전투를 얼라이언스에게 유리한 방향으로 이끌 수 있도록 도움을 주시겠습니까?"
rows["176:297709995"]="이 근처는 인적이 정말 드물지요? 마법학자들이 직접 하기 싫은 위험한 일은 죄다 우리에게 떠넘기는 것 같다는 생각이 들기 시작했습니다."
rows["176:367428648"]="연대장님은 우리가 최근에 입수한 실리시드의 지하 둥지 지도를 연구하시느라 지금 바쁘십니다. 돕고 싶다면 여기서 기다리세요. 금방 오실 겁니다."
rows["176:560199013"]="달라란 남서쪽에 있는 은빛 자치구 바로 옆에 영웅의 쉼터 여관이 있습니다.$B$B영웅의 쉼터 여관 부엌에는 달라란 최고의 전문 요리사 중 한 명이 있으며, 떠들썩한 분위기로 유명하답니다."
rows["176:609366026"]="내 작업장에 온 걸 환영하네, 대장장이 친구. 한 가지 작은 비밀을 가르쳐 주지. 이 세상에 어느 누구도 믿을 자가 없다는 거야. 남자든, 여자든, 동물이든지 할 것 없이 모두... 하지만 단 한 가지 믿을 게 있다면, 바로... 강철이라네."
rows["176:624063555"]="저희 파수꾼들도 대부분 일예니아 문파이어에게 무기 훈련을 받았습니다. 새로운 무기의 사용법을 배우고 싶다면 전사의 정원으로 일예니아를 찾아가보십시오."
rows["176:729489658"]="앨나는 오라클 글레이드에서 대부분의 시간을 보낸다. 그 곳에서 그녀의 직업을 연습합니다. 마법사의 직업을 배우고 싶다면 그녀를 찾기 위해 그곳에 가야 합니다."
rows["176:834947735"]="날 용케도 찾았구려. 내게 억제와 지배에 대해 배우려고 온 거겠지.$B$B그보다 더 많은 기술도 가르쳐주리다... 희생에 대해서도 가르쳐주겠단 말이오.$B$B<씩 웃는 다이오.>"
rows["176:841809443"]="최근에 우리는 강력한 힘을 가진 생물이 벡터 코일 근처에 소환되었다는 얘기를 들었습니다. 그러나 두려워하지 마십시오. 마을을 위협하는 존재가 있다면 우리는 목숨을 바쳐 마을을 지켜야 합니다."
rows["176:856906446"]="이런 종류의 일은 담이 약한 이는 할 게 못 돼요. 한쪽 손을 잃어 버린 삼촌도 있다니까요! 불쌍한 스텀피 삼촌... 어쨌든 그래도 관심이 있다면 제가 몇 가지 가르쳐 드릴 수 있을지도 모르겠네요."
rows["176:914873925"]="아덴 부관은 항상 성문을 지키는 임무에 자원하지. 잘 된 일이야.$B$B난 내 자리가 마음에 드오. 부하 경비병들 감시하기에도 좋고, 상인 딸내미들도 잘 보이니까 말이오."
rows["176:919041552"]="마직 쿼터. 티마크리아 딜라노레는 동쪽 램프 인 트레이너의  ⁇ 에서 지옥서약자를 훈련합니다. 코비두스 리치, 강령술사,  ⁇ 의 가장자리에 걸어서 서 있습니다."
rows["176:964942009"]="우리 말에서 \"우나페\"는 \"피난처\"란 뜻입니다. 더는 어울리지 않는 이름이지요. 야영지를 세운 후부터 저 이상한 밀림이 이곳을 집어삼키려는 듯 위협하고 있습니다."
rows["176:973881413"]="오늘은 이미 승자가 모두 나왔지만, 낚아 올린 맛둥어는 전부 장에게 팔 수 있습니다!\010\010잊지 마세요! 일요일엔 언제나 낚시 기술을 뽐낼 기회가 있습니다."
rows["177:1135858541"]="재조조를 하고 싶었소?\013\010\013\010\013\010\013\010오그리마의 에테레알은 당신을 도울 것입니다.\013\010\013\010\013\010\013\010도시의 경비원이라면 누구나 안내를 줄 수 있습니다."
rows["177:1154619976"]="동물 친구들의 안녕에 그렇게 신경을 쓰이시나요? 당신은 참 좋은 분이시군요. 봉우리 하층에 있는 불루그가 도와드릴 수 있을 겁니다. 은행과 여관 사이에 있으니 한번 찾아보십시오."
rows["177:1184149322"]="미안해, 내가 손님들을 가지고 있다는 걸 알아차리지 않았어.$b$b<왜란은 손 뒤쪽을 이용해 눈앞에서 땀을 지우고, 그 후 그 잔뜩은 회색  ⁇ 에 건조합니다.>$b$b죽은 사람을 알고 있었나요?"
rows["177:1288193668"]="우리는 호드를 섬기는 최후의 숲트롤 부족이라는 사실을 자랑스럽게 생각한다네.$b$b결국에는 우리가 다른 부족과 드워프를 물리치고 동부 내륙지를 차지하게 될 걸세."
rows["177:1427725795"]="오크의 무작위로 움직이는 것은 그의 소박한 힘을 드러내고 있습니다. 그는 모든  ⁇ 에서 땀을 흘리고 있지만, 광산 내부의 열은 너무 뜨겁습니다. 땀은  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이"
rows["177:1767896653"]="이 화약통들을 발굴현장으로 배달하는 것은 힘든 일이네. 하지만 그곳에는 화약을 얻으려고 우리에게 의지하는 이가 너무 많다네.$B$B검은무쇠 부족에 대항하기 위해 우리가 할 수 있는 일은 다해야 하네!"
rows["177:1907753886"]="죽음의 흉터로 끊임없이 밀려오는 정신 나간 스컬지들을 상대하느라 정말 힘든 하루였습니다. 우리를 돕기 위해 오셨기를 바랍니다. 쓸데없이 잡담이나 하고 있을 시간이 없습니다."
rows["177:1961143714"]="응급치료는 아주 값진 기술이오. 우리의 전문 응급치료사, 니사 파이어스톤이 잘 가르쳐줄 겁니다. 대용광로 남쪽에 있는 아이언포지 치료소에서 그 친구를 찾아보십시오."
rows["177:21450467"]="스랄을 여기서 구해내려면 모든 원소의 도움이 필요합니다. 라그나로스의 부관들은 사이클로나스나 하이드리우스는 물론, 테라제인만큼도 협조적이지 않을 테니까요."
rows["177:329421071"]="내 얘기 제대로 듣고 있는 건가? 그럼 내가 대체 누구 얘기를 하고 있겠나? 그래, 맞아. 여군주 마랄리스였네. 어쨌든 우리를 찾아왔는데 기분이 썩 좋아 보이지 않았네. 그러더니 부탁을 하더군."
rows["177:350637962"]="눈의 호기심이 좋죠. 그것은 지적 불안의 전초입니다.$b$b테렌 디온의 기사에 어떤 질문을 하시겠습니까?"
rows["177:384976565"]="저 망할 조나 스털링이 우릴 이 꼴로 만들었어요. 그가 동굴 안에 죽치고 있지만 않았더라면 전쟁 중에 해군을 습격하는 게 바보짓이라는 것 정도는 알았을 텐데 말이에요."
rows["177:413066170"]="우리 앞 협곡에 있는 저 태고의 신은 고레크라 합니다. 뭔가가 저기 기생하고 있군요.$B$B결판을 내지 않으면 우리 모두 파멸할 것입니다!"
rows["177:495470974"]="귀여운데, 그롬골로 갈 수 있어?"
rows["177:645205136"]="폭풍칼날 레나타키$B$B고통은 그의 혈액이요, 공포는 그의 동지일지니. 언젠가 살육의 기쁨과 함께 돌아오기를.$B$B이제 레나타키는 광란의 경계에 살고 있다."
rows["177:708869627"]="씩씩이는 자신이 아직 소금 평원에 있다는 사실을 틸스에게 들키고 싶지 않아서 닭으로 변신했지요.$B$B혹시라도 씩씩이를 찾거든 '/손짓'을 해보십시오. 모습을 드러낼지도 모릅니다."
rows["177:714206040"]="진정 연금술을 배우고자 하신다면 다르나서스 북쪽, 장인의 정원으로 가서 뛰어난 실력을 지닌 에이네실이라는 연금술사를 찾으십시오."
rows["177:822423857"]="대단하군! 그 카즈로갈이 죽으면서 내지른 비명에 불타는 군단의 수뇌부가 겁먹은 게 분명하네. 이제 그대의 군대가 지닌 힘에 대해 저들도 알게 되었으니 불타는 군단이 어떻게 도발해 올지 기대해 보세."
rows["177:862125482"]="보안 재정의가 허가되었습니다. 보조 방어 시스템이 활성화되었습니다.$B$B광장에 있는 각 발전기에 직접 접속함으로써 보조 시스템을 비활성화할 수 있습니다."
rows["178:1019616850"]="라자크 기병대와 함께 일해 보면 명령을 따른다는 것이 무엇인지 배울 수 있어요.$B$B첫 번째, 죽을 때까지 싸워라. 두 번째, 동료가 죽을 때까지 싸우는 모습을 구경해라..."
rows["178:1158408434"]="설마 스팀휘들 무역회사의 배에 기술자가 없겠나? 톨크스핀들이 다양한 물건을 팔고 있네. 수리가 필요하면 물건도 재빨리 고쳐 준다고."
rows["178:1179165398"]="가시멧돼지들은 항상 야영지 주변의 음식이나 보급품을 뒤지며 먹을 것을 찾아 돌아다녔지만, 그놈들이 우리 농장이나 집을 직접 공격한다고요? 최근에 무언가가 가시멧돼지들을 미쳐 날뛰게 한 거예요."
rows["178:1234902795"]="나디아는 오랜 기간 동안 가죽 작업에 뛰어들었습니다. 다르나서스로 서쪽으로 가서 그녀를 방문해 보세요."
rows["178:1317028577"]="날아서 어딘가로 가야 하시나 보군요. 스톰윈드에 그리핀 조련사가 한 명 있지요. 영웅의 계곡을 지나자마자 오른쪽에 그리핀이 착륙하는 게 보일 겁니다."
rows["178:134862716"]="버드네 패거리, 말이야?$B$B이런, 버드는 다른 사람을 눈곱만치도 존중 안 하지. 삽질만 할 수 있다면, 아무나 데려다 쓸걸.$B$B...언데드는 빼고 말이야. 버드가 엄청 싫어하는 종족이거든. 개인적인 생각인데 말이지, 좀 무서워하는 게 아닌가 싶어."
rows["178:1383216891"]="으윽... 저쪽에 있는 게으른 주방장이 특별 요리를 권하면, 부디 자기 자신을 위해서 그냥 바닷속에 던져버리시오. 마크루라 몇 마리를 죽이는 게 살고자 하는 의지를 잃는 것보다야 낫지 않소?"
rows["178:142126841"]="잘디마르라면 새로운 마법 몇 가지는 가르쳐 줄 수 있을 겁니다. 요새 사자무리 여관에서 지내는 걸 즐기는 모양이니, 그곳으로 가서 그가 있는지 둘러보십시오."
rows["178:1547738755"]="이 호드 이 대량차원의 개입을 허용하지 말아야 합니다. 얼라이언스 모든 마나 세포 아웃랜드당신은 폭풍의 눈에 대한 공격에 피 엘프와 함께 할 것인가?"
rows["178:1947218381"]="하파나가 살짝 툴툴거리면서 공포의 선장 드메자에게 가보라고 손짓합니다.$B$B\"마가타\"라는 단어와 화살에 찔린 하트 모양 문신이 그의 커다란 팔에 새겨져 있습니다."
rows["178:1958217961"]="구 시가지에서 돼지와 휘파람 선술집이나 스톰윈드 병영을 찾아보시기 바랍니다. 아, 선술집에 들르시면 꼭 그곳 맥주를 맛보십시오. 드워프가 만든 맥주와는 비교도 안 될 겁니다."
rows["178:444148020"]="이 노래꽃은 타락으로 뒤덮인 악령의 숲에서 바다 한가운데 솟은 바위처럼 홀로 건강하게 자라고 있습니다. 꽃잎의 강한 향기는 기운을 북돋우고 결의를 굳게 해 줍니다."
rows["178:457835679"]="엘리사라 선스트라이커는 믿기지 않을 만큼 용기 있는 여인입니다. 그녀가 살데릴 경의 눈에 들 수 있을까요? 그런데 엘리사라의 옷 차림새는 유행에 한참 뒤떨어져 있더군요. 정말 안 된 일이죠."
rows["178:520661864"]="고통에 참을 수 없는 사람들을 위한 치유입니다. 하지만, 당신이 해야 한다면,"
rows["178:578807323"]="페어웨더와 저는 이곳에서 실바나르의 권리를 대변하고 있습니다.$B$B이곳 드루이드들은 호드들이 이곳을 통과하도록 허락할 뿐만 아니라 편의를 봐주고 있어 소름이 끼친답니다."
rows["178:814527674"]="나는 당신을 도와 줄 수 없소! 당신은 나보다 더 오래 이 일을 해 온 이를 찾아갈 때가 된 거요! 보자... 아무래도 당신은 얼라이언스 일원이니 스톰윈드에 있는 릴리암 스파크스핀들과 얘기해 봐야 할 거요."
rows["178:887091390"]="어둠의 불에 있는 칸클라브를 보세요. 그 아래는 그림자의 틈입니다. 제바로스는 제로스의 기사들을 입구실에서 가르치고, 죽음의 마고스 고라트는 네크로맨스들을 주방에 가르치고 있습니다."
rows["178:920167950"]="감옥이라고요? 왜 그곳으로 가고 싶어 하는 겁니까? 지하감옥은 스톰윈드의 중앙에 있습니다. 바로 마법사 지구의 북동쪽이지요.$B$B정말로 그곳으로 가려는 거라면, 조심하십시오. 폭동이 일어났다는 얘기를 들었습니다."
rows["179:1033434570"]="마스레인은 야만적인 무두질에 능숙하지요. 진정 그런 일을 원한다면 그가 어디에 있는지 말씀드리겠어요. 마법학자의 관문 남서쪽에서 사시인에게 가죽을 공급하고 있으니 그리로 가보십시오."
rows["179:1052442756"]="랜달은 멋 부리기를 지나치게 좋아하는 것이 사실이지만 제가 가르치는 어떤 학생들보다 믿음직스럽죠. 모험을 좀 좋아한다고 뭐라고 할 수는 없는 일이니까요."
rows["179:1082273099"]="우린 저 바깥의 어둠 속에 얼마나 사악하고 끔찍한 존재들이 떠돌아다니는지 알고 있다네. 자네의 영혼을 미치게 할 그런 존재들 말이야.$b$b우린 알고 있고, 자네는 우리가 알고 있는 사실을 배우러 온 거겠지?"
rows["179:111828425"]="우리 중 일부는 천둥의 힘을 활용하기도 한다. 그 힘으로 인간, 오크, 공룡과 같은 침략자들로부터 우리를 지키곤 하지.$b$b우리의 번개는 그 어떠한 공룡도 기절시킬 수 있다."
rows["179:112990818"]="때가 되면 나한테서도 배울 수 있게 되겠지만 아직은 이릅니다... 이곳 내 오른편에 있는 스프라이트 점프스프로켓과 먼저 얘기를 나눠 보십시오. 기본기를 다지거든 날 다시 찾아오시기 바랍니다!"
rows["179:1173159926"]="페어웨더와 저는 이곳에서 실바나르의 권리를 대변하고 있습니다.$B$B이곳 드루이드들은 호드들이 이곳을 통과하도록 허락할 뿐만 아니라 편의를 봐주고 있어 소름이 끼친답니다."
rows["179:1323857444"]="여기 이 부두 말인가요? 이곳을 운항하는 배는 그 나이트 엘프들이 있는 곳으로 출항하죠. 이름이 뭐더라? 아마도... 아우... 아우버다인일 거예요. 정확하게는 모르겠어요. 전 단지 짐만 싣고 내릴 뿐이거든요."
rows["179:1358887839"]="길드를 만들고자 하신다면 길드 사무관, 리셰아나를 만나셔야 합니다. 다르나서스 북동쪽에 있는 장인의 정원에 가면 그녀를 만나실 수 있을 겁니다."
rows["179:1498784846"]="연금술사를 하나 아는데 이름이 아마 셰이나스렌일 겁니다. 마지막으로 봤을 때는 살데릴의 안식처로 가고 있었는데 보나 마나 그 우스꽝스러운 파티에 갔겠죠."
rows["179:1910817115"]="켈렌의 믿을 수 있는 재봉술 상점에 온 것을 환영하오. 여기라면 그대가 필요로 하는 것을 찾을 수 있을 거요. 배우고 싶은 기술이 있거든 말만 하시오. 기꺼이 가르쳐 드리리다."
rows["179:1945707248"]="안녕하십니까. 가을 축제에 오신 것을 환영합니다! 머리가 뒤죽박죽으로 복잡해질 만큼 즐길 거리가 너무 많아서 궁금한 점이 생겼다면, 저에게 말씀하세요. 질문할 게 없는 분들은 가서 맥주와 프렛첼이나 사드세요!"
rows["179:1949110358"]="마법사의 직업은 자연의 중심에 있는 파괴와 창조의 순환을 보여줍니다."
rows["179:2003651779"]="지팡이 사용법은 오그리마, 명예의 골짜기에 있는 트롤 무기 전문가인 하나시, 아니면 썬더 블러프 중앙의 하층 봉우리에 있는 타우렌 무기 전문가인 안세크화에게 가서 배우게."
rows["179:2105367873"]="최근 이 근처를 데피아즈단이 습격한 적이 있었습니다. 그때 상처입은 경비병들을 미셸 벨르가 아주 신속하게 치료해 주었지요. 그녀는 사자무리 여관에 있으니 찾아가서 뭔가 배울 수 있는지 한번 물어보십시오."
rows["179:2144261561"]="연금술사는 평범한 약초로 기적을 만들 수 있소. 치유 물약에서부터 수중 호흡이 가능한 물약까지 약초로 만들지 못하는 것은 없지."
rows["179:431915813"]="알터랙 계곡의 무덤은 망자들의 영혼이 휴식을 취하고 구원을 받는 곳입니다. 만약 당신이 장렬히 전사하면 그 영혼은 우리가 점령한 무덤 중 가장 가까운 곳으로 이동할 겁니다."
rows["179:481498447"]="정말 빨리 배우는군요! 제가 달리 가르쳐 드릴 게 없네요. 하지만 스프링스핀들 피즐기어라면 틀림없이 더 많은 걸 가르쳐 줄 겁니다! 그 친구를 만나려면 아이언포지로 가세요. 행운을 빌어요!"
rows["179:494138226"]="재봉사들이 필요로 하는 물품은 대부분 다르나서스에서 공급되고 있습니다. 그러니 재봉사들이 모두 그곳으로 옮겨 간 것도 놀라운 일이 아니지요. 그대도 재봉사가 되고 싶으시면 다르나서스로 가 보시는 게 좋을 거예요."
rows["179:652085369"]="일예니아 문파이어는 지난 천 년 동안 수많은 무기를 익혀왔습니다. 지금은 다른 이들에게 그 기술을 전수하고 있지요. 훈련을 받고 싶으면 전사의 정원으로 가서 일예니아를 찾아보십시오."
rows["179:672556606"]="이 세계를 구성하는 구조물은 아주 섬세하기 때문에 약간의 지식을 응용하는 것만으로도 상처를 낼 수 있답니다. 그리해서 균열이 생겨나는 것이지요."
rows["179:706646559"]="연금술사를 하나 아는데 이름이 아마 셰이나스렌일 겁니다. 마지막으로 봤을 때는 살데릴의 안식처로 가고 있었는데 보나 마나 그 우스꽝스러운 파티에 갔겠죠."
rows["179:715802970"]="준비가 다 됐군요. 지금 그대와 그대의 공포마 앞에 놓인 일은 대소환진과 공포마의 영혼을 봉인하기 위한 의식입니다."
rows["179:72038844"]="드루이드들의 주최로 달숲에서 달의 축제가 열리고 있습니다. 먼 곳에 계시는 분들을 위해 스톰윈드 바로 바깥에서 이동 서비스를 제공하고 있습니다."
rows["179:813504345"]=" ⁇  카자드의 오븐과 비교할 수 없지만, 이 도시의 사람들의 기대를 충족시키고, 심지어 뛰어넘는 것입니다.$b$b말해봐, 뭔가 필요해?"
rows["17:1047553916"]="그러그 븜르글 그르그!!"
rows["17:1063918191"]="제가 갑판을 청소했어요!"
rows["17:1162415709"]="저랑 싸우시려고요?"
rows["17:1210424612"]="해냈군, 영웅들이여!"
rows["17:1263500099"]="지금 뭐하고 싶어?"
rows["17:136083815"]="나 모래 안 좋아한다."
rows["17:1412518208"]="어떤 직업?"
rows["17:142060194"]="저리 비켜, 촌뜨기..."
rows["17:151261430"]="그리고 당신은?"
rows["17:1543124250"]="- 뭐야?"
rows["17:177943298"]="술을 마시던지 저리 가 주세요!"
rows["17:2023478928"]="무슨 일이에요?"
rows["17:2037304073"]="- 뭐하고 싶은데?"
rows["17:205955808"]="아직 도착했나요?"
rows["17:2112802123"]="아글르글글르글그르르르!"
rows["17:2131559926"]="영웅의 부름 게시판"
rows["17:254303740"]="트롤의 힘을 보여드리죠, 친구!"
rows["17:271447456"]="페어가 오고 있어!"
rows["17:882442289"]="저기 매복이 있네."
rows["17:986466196"]="<신음하는 콜티라>"
rows["17:995900634"]="잘 만났어 친구"
rows["180:1082685840"]="제대로 된 교육도 받지 않고 나에게 왔단 말이오? 머리보단 행동이 앞서는군. 당신 수준에 맞는 자나 찾아가 보십시오. 오그리마 골목길에 있는 카마리 같은 오크 말입니다."
rows["180:1082813391"]="저 랩터들로부터 겨우 도망쳤나 했는데, 이곳 상황은 더 악화되기 시작했어요.$B$B불평해봤자 무슨 소용이 있나요. 진정한 드워프의 자세로 이놈들을 상대해줘야겠군요!"
rows["180:1215748503"]="사시사철 혹한의 날씨인 이곳 던 모로에도 작은 들꽃들이 자라난다는 게 정말 신기하지 않습니까? 하지만 이곳에 약초채집가는 없답니다. 그 기술을 배우려면 아이언포지로 가보는 게 좋을 겁니다."
rows["180:1306331904"]="풀밭은 부드럽고 폭신합니다. 공기는 상쾌하고 밝은 빛과 노랫소리로 가득 차 있습니다. 제가 보는 모든 것들이 텔드랏실은 꿈의 장소라는 것을 말해줍니다. 그런데 왜 제 마음은 이리도 불길한 예감으로 가득할까요?"
rows["180:1363047158"]="전투의 전당으로 가 보게. 브락굴 데스브링어가 전쟁노래 협곡으로 가는 자들을 돕기 위해 기다리고 있지. 이런 얘길 나누게 되어 아주 뿌듯하군. 명예의 골짜기로 가서 찾아보게나."
rows["180:1454023862"]="튼실한 녀석들이죠, 그렇죠? 이곳에서 우리가 키우는 와이번들은 드레노어의 위험한 혹한의 날씨에도 견딜 수 있도록 훈련되었답니다. 이 와이번들에게서 믿음과 강한 체력을 느끼실 수 있을 겁니다."
rows["180:1482840634"]="저들이 콜링우드 호를 완전히 가라앉혔지만, 간신히 대포를 끌고 나오는 데 성공했소.$B$B짐승같은 놈들이 더러운 녹색 발을 해변에 딛게 놔둘 순 없지! 내 손에 화약이 있는 한은 절대로!"
rows["180:1488781983"]="수많은 전투에서 나와 함께한 이 도끼를 항상 옆에 두고 싶소. 적군이 우리 수도로 쳐들어온 게 한두 번은 아니지만 두려워할 필요는 없지. 그들을 막지 못한 적은 한 번도 없었으니까."
rows["180:1508823026"]="흠... 당신이 이제부터 배워야 할 것은 제 한계를 넘는 것들입니다. 이제 여기서 나가 골목을 오른쪽으로 틀면 있는 라슨의 옷가게로 가십시오. 거기서 일하는 셀란두스와 의논하셔야 합니다. 사실은 제 모든 기술도 그 나이트 엘프에게 전수 받은 것이랍니다!"
rows["180:1635161396"]="그렇습니다. 여명의 설원의 언덕에서는 새롭게 시작된 스컬지의 침공을 방어하고 있습니다. 당신이 도와준다면 그들에게 큰 힘이 될 겁니다.$B$B남아 있는 죽음의 요새: $2284W개"
rows["180:1645646165"]="내가 들고 있는 도끼만큼이나 좋은 무기를 만드는 법을 사루 스틸퓨리라면 가르쳐 줄지 모르지. 명예의 골짜기로 들어가 붉은협곡 광부조합에서 오른쪽 길을 따라 끝까지 가면 불타는 모루가 있다네."
rows["180:1726993638"]="<아렌도르의 칼의 금속 가장자리는 붉은 색 아래에서 거의 보이지 않습니다.>$B$B한 발걸음, 한 발걸음 너무 갑자기, 당신은 울기 전에 목이 열릴 것입니다"
rows["180:1818740286"]="나는 람카헨의 왕자 나둔이오. 네페르세트 부족은 나머지 톨비르 부족을 배신했소.$B$B내가 탈출할 수 있게 도와주시오. 람카헨의 국왕인 내 형을 설득하여 이 배신자들과 전쟁을 치러야 하오!"
rows["180:1881922866"]="내 양심상 우리 동맹인 언데드들이 고통을 겪고 있는 상황에서 초보자를 가르칠 수는 없습니다. 나 대신 저기 있는 크레이에게 부탁하면 당신을 도와줄 수 있을 겁니다."
rows["180:1952643887"]="영웅들이여, 또다시 큰일을 맡기게 됐군. 우리가 영혼에 아제로스 위상의 힘을 불어넣는 동안, 자네들은 데스윙의 병력으로부터 우릴 보호해야 하네."
rows["180:222131020"]="그대가 여기서 나의 시간을 뺏는다면 세나리온 의회 전체의 시간을 빼앗는 것과 같아. 무슨 일로 왔는지는 모르겠네만, 그대가 귀중한 시간을 축낼 만큼 어리석지 않다는 희망을 주게."
rows["180:350054211"]="안타깝게도 그대와 같이 경험 많은 이에게 제가 할 수 있는 일은 거의 없습니다. 다르나서스 장인의 정원에 거주하는 나이트 엘프 실반나 포레스트문을 찾아가 보십시오."
rows["180:359405935"]="울브렉 파이어핸드는 다른 일이라면 몰라도 동물 보살피는 일이라면 아주 진지하게 생각하죠. 울브렉은 전투의 전당에서 사냥꾼들과 자주 어울리는 모양이니 동물을 돌봐줄 자가 필요하다면 그를 찾아가 보십시오."
rows["180:405360541"]="지옥불 반도에 있는 우리의 적군 중에 지옥불 성채의 오크도 끼어 있다는 것은 유감스러운 일이 아닐 수 없네.$B$B하지만... 그 누가 오크보다도 우리 호드를 더 만만한 상대라고 생각하겠나?"
rows["180:700907037"]="죄송하지만 제가 아는 것은 이미 배우셨군요. 하지만 팔드론이라는 나이트 엘프는 그대를 도와줄 수 있을 것입니다. 다르나서스에 있는 장인의 정원에서 그를 찾아보도록 하세요."
rows["180:857953570"]="정말 빨리 배우는군요! 제가 달리 가르쳐 드릴 게 없네요. 하지만 스프링스핀들 피즐기어라면 틀림없이 더 많은 걸 가르쳐 줄 겁니다! 그 친구를 만나려면 아이언포지로 가세요. 행운을 빌어요!"
rows["180:941906501"]="우리가 불의 땅 침공을 준비하는 동안, 불의 군주는 부하들을 보내 우리 부대의 접근을 막아내려 하고 있어요. 우리는 이곳에서 물러설 수가 없어요. 적의 세력과 세계수 사이에 남은 건 우리뿐이니까요."
rows["181:1047415218"]="나도 인정해야겠습니다. 이 야심 차고 건방진 녀석에게 흥미를 느꼈었다는 사실을요.$b$b뭐랄까, 성급히 결론을 내리고 싶지는 않지만, 꺼림칙한 소문을 들었습니다.$b$b하지만 그가 다른 꿍꿍이가 있는지 없는지, 시간이 지나면 자연히 알게 될 겁니다."
rows["181:1267304598"]="도시 정문 바로 바깥에 다레스라는 늑대인간 드루이드가 있는데, 그가 당신을 도와줄 겁니다.$B$B털이 북슬북슬하고 하얀 가죽옷을 입은 커다란 야수 친구죠. 워낙 눈에 띄니 찾기 쉬울 겁니다."
rows["181:1411210264"]="지혜의 계곡에 있는 그로마시 홀드의 입구로 가세요. 샤맨들이 불을 지르는 곳이죠. 다락카 스톰스워런은 스톰브레이더를 훈련시키고, 타코 마즈는 프림ালি스트들을 훈련시킵니다."
rows["181:1509232291"]="데스윙은 세계 기둥을 파괴하면서, 자네의 세계와 우리 세계 사이에 균열을 발생시켰네. 이 포자와 곰팡이들도 그 결과로 생겨난 것들이지.$B$B우리가 어떤 조치를 취할 수 있을지 한번 보세."
rows["181:1657306113"]="달라란 북서쪽, 마법사 교역소에는 거대한 용광로와 대장간이 있습니다.$B$B도끼와 방패 형태를 한 마법부여된 육중한 모루와 얼룩진 유리창들을 찾아보십시오."
rows["181:1816687009"]="저희 쪽 사람들이 와일드해머 드워프들과 좋은 관계를 유지한 지도 꽤 긴 시간이 흘렀습니다.$B$B이 땅이 지킬 가치가 있는 땅이라 판단한 소수는 이곳에 정착했지요."
rows["181:1913363491"]="모트가 아직 준비가 안 된 당신을 내게 보낼 정도로 바보는 아닌데... 당신은 아직 내가 가르칠 내용을 전부 이해할 수 없소. 바로 저 바깥에 있는 내 아들 모트에게 가서 남은 훈련을 마치도록 하시오."
rows["181:2023146951"]="금속 조각을 잘만 활용하면 낭비가 적어지고 대지모신에게 더욱 가까워질 수 있습니다. 무란타가 그 비법을 알려 줄 겁니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점 앞에서 찾아보시기 바랍니다."
rows["181:345693633"]="색깔 보는 법처럼 자잘한 사항 외에는 더는 당신에게 가르쳐 줄 게 없습니다. 저기 있는 사이먼 태너에게 가보십시오. 숙련된 가죽세공 기술을 가지고 있는 사람입니다."
rows["181:664279452"]="이제 지긋지긋하군! 수가 너무 많아!$b$b<잠시 한숨 돌리기 위해 말을 멈추는 시혼 함장>$b$b내가 무슨 말을 하는 거야? 별로 안 남았잖아! 이거나 먹어라, 더러운 똥개들아!"
rows["181:682172943"]="이제 우리 불에 대해 알고, 그들을 존중하고, 우리의 적의 불에 대해 알고, 그들을 끄는 것을 알고, 당신은 그에게 돌아와 보상을받을 수 있습니다."
rows["181:684052571"]="드루이드들이 말하길 자연 스스로 호드를 칼림도어에서 밀어내는 것은 시간문제라고 하더군요. 하지만 우리의 대지는 계속 오염되고 있고 여기 텔드랏실도 마찬가지입니다."
rows["181:796448628"]="고 마법사 바르도란은 스라이어 계층의 시어 도서관에서 발견 될 수 있습니다. 예술의 위대한 마스터, 그는 그의 학생들: 마스터, 수련자, 전문가, 여행자들로 둘러싸여 있습니다."
rows["181:849180061"]="흑마법사라... 별로 마음에 들지는 않습니다만. 제 말은 바로 썬더브루 양조장 밖에 노점상을 열어 놓고 있는 김리즈 녀석 말입니다. 그 녀석 때문에 그곳 에일 맥주는 몽땅 김이 새버릴 걸요! 흑마법사라... 흥!"
rows["181:869097412"]="태양의 궁전으로 올라가라. 카레스트 나이트글로우는 열린 상반 광장에서 스타콜러들에게 가르치고, 이트리엔 글리프워든은 룬마스터들이 마법과 표기판 가게 앞에 있다."
rows["181:900830423"]="우리가 함께 일할 수도 있겠지만, 더욱 신중해져야 할 것이네. 다시 한번 강조하지만 말과 행동을 주의하도록 하게.$B$B장담하건대, 이곳에는 우리만 있는 게 아니니 말이야."
rows["181:908124254"]="때가 되면 나한테서도 배울 수 있게 되겠지만 아직은 이릅니다... 이곳 내 오른편에 있는 스프라이트 점프스프로켓과 먼저 얘기를 나눠 보십시오. 기본기를 다지거든 날 다시 찾아오시기 바랍니다!"
rows["181:94655115"]="어둠의 세력이 국경을 잠식하고, 오래된 타락이 다시 고개를 들며, 새로운 악이 땅의 위태로운 균형을 무너뜨리려 하고 있습니다. 이런 암흑의 시대일수록 모두가 경계를 늦춰서는 안 됩니다."
rows["181:970167780"]="만약 불방습을 연습하고 싶다면 여기서는 눈이 많이 올 수도 있지만 스틸그릴이나 그 거미들이 언제 폭발할지 알 수 없죠"
rows["181:977960456"]="우리는 안전하다... 당분간은 말이지. 마지막으로 싸웠을 때보다 아서스는 열 배나 강해졌다. 리치 왕을 물리치려면 강력한 군대가 필요하다. 호드가 모을 수 있는 것보다 더 강력한 군대 말이다."
rows["181:984163411"]="이름에서 추측할 수 있는 것처럼 파멸의 버섯은 폐허 근처에서 찾을 수 있소. 로레스아란에 해답이 있소이다.$B$B사실 이 버섯의 이름에 진짜로 그런 의미가 있는 것은 아니고, 그저 괜찮은 이름을 붙이려고 고민을 좀 했을 뿐이라오."
rows["182:1062483199"]="달라란 북서쪽, 마법사 교역소에는 거대한 용광로와 대장간이 있습니다.$B$B도끼와 방패 형태를 한 마법부여된 육중한 모루와 얼룩진 유리창들을 찾아보십시오."
rows["182:1095013088"]="나보다 훨 낫군! 나보다는 경험이 풍부한 스승이 필요하겠는걸? 그렇다면 아마 다르나서스의 장인의 정원에 사는 나이트 엘프 에이네실 정도가 되겠지."
rows["182:110643759"]="내가 소질이 없다고 했나요? 왈트는 뭘 몰라도 한참은 모른다니까요! 내가 얼마나 손쉽게 저 무쇠 드워프들을 쓸어내고 이 야영지를 만들어 발굴현장의 동태를 살피고 있는지 몰라서 하는 소리라니까요."
rows["182:1214611751"]="언더시티에서 찾아봐야 할 걸세. 여기 남쪽에 있는 로데론의 폐허에 가면, 아래로 내려가는 승강기가 있지. 일단 거기 간 다음, 언더시티 수호병에게 다시 한 번 길을 묻게."
rows["182:1243380220"]="안녕하십니까, 친구. '쿠키'는 제 이름이고 요리는 제가 좋아하는 일이랍니다. 맥위크소스는 섬세한 감각을 가진 고객들을 만족시키고자 봉사하는 요리사와 상인을 배출한 유서 깊은 가문이랍니다."
rows["182:1336890193"]="한 번만 더 그런 형편없는 솜씨를 가지고 날 찾아오면 염소 오줌에 절인 조그만 상자에 집어넣어 집으로 보내버리겠어. 오그톡 같은 얼간이한테나 가봐. 자네 수준에는 그런 자가 딱 맞으니까."
rows["182:1505618768"]="제 생각에 그리프는 동물들과 너무 많은 시간을 보내는 것 같습니다만, 뭐 그래도 사냥에 대해서라면 그보다 더 잘 아는 이는 없지요. 카라노스의 대장간 바깥에서 찾을 수 있을 겁니다."
rows["182:154532313"]="내가 아는 게 좀 있긴 하지만 전문가는 아니오. 다행히도 마가르는 전문가지. 상점 뒤편에 있으니 가서 도와줄 수 있는지 한번 물어보시오. 성질이 불같으니 화나지 않게 조심해야 할 거요."
rows["182:1864021065"]="언데드들은 종족이 겪고 있는 비극적인 상황에도 불구하고 여기까지 와서 우리를 돕고 있습니다. 우리도 그만큼 그들에게 도움이 되었으면 좋겠군요. 정기의 봉우리 밑에 있는 예언의 웅덩이 근처에서 신부 콥을 찾아보시기 바랍니다."
rows["182:1883944288"]="내가 설명할 시간도 없고, 욕도 없어요. 이제 중요한 말이 있으세요?"
rows["182:1967588736"]="카플라크는 왜 찾는 겐가? 뭐, 그야 내가 신경 쓸 일은 아니지만. 칼바위 언덕 남서쪽에 있는 지하실 위를 찾아보게. 그를 만나면 가방 단속은 단단히 하도록 하게."
rows["182:232446171"]="상급 마법사 케인 파이어송은 교수대끝 선술집 위층에서 찾을 수 있지. 브릴 남동쪽 끝으로 가보게. 그 마법사, 너무 늦게 가서 방을 구하지 못한 것 같아."
rows["182:279024284"]="우리 마을은 저 빌어먹을 바다 밑에 있고, 우리의 요새는 검은무쇠 부족 배신자들로 가득합니다. 그리고 저는 이렇게 상처를 입어 뭐 하나도 제대로 할 수 없는 상태입니다.$B$B그러니 메네실 항구에 오신 것을 정말 환영하는 바입니다!"
rows["182:4293691"]="요르문트 스톤브라우라는 친구가 실과 바늘을 다루는 요령을 잘 알고 있지요. 재봉술을 배우고 싶다면 대용광로 북쪽에 있는 스톤브라우의 의류점으로 가보십시오."
rows["182:602798792"]="사실이다, 칭구! 이 일대에서 북쪽바다 약탈자만큼 강한 해적 없다!$B$B열 받게 안 하는 게 좋다. 웃기지도 않지! 그래도 미련한 녀석 매 맞게 마련!"
rows["182:697872311"]="쌍둥이 제왕이 죽어 신전 안의 순간이동을 막고 있던 마력이 크게 약해졌습니다. 원하신다면 당신을 제왕의 은신처로 보내 드릴 수 있습니다."
rows["182:764391800"]="그대가 좋아할 만한 작은 노래 책입니다. 명가의 애가라고 하는 노래의 가사도 들어 있습니다. 실바나스 여군주께서 하늘에서 불렀던 노래죠."
rows["182:990560801"]="스컬지 군대가 타나리스에 도착한 것 같습니다. 엄청난 수의 죽음의 요새와 군대가 그곳에 파병됐습니다.$B$B남아 있는 죽음의 요새: $2283W개"
rows["183:1047004613"]="우리 앞에 놓인 길은 그리 쉽지 않소. 팔이 튼튼하다고 자신한다면 우리 부대원 하나가 이미르하임으로 오를 준비가 될 때까지 좀 기다려 보시오. 부대원들은 어떤 도움이라도 환영할 테니까 말이오."
rows["183:1350632931"]="이 전선을 관리하라고 크로그 장군님께서 날 여기로 보냈소. 하지만 병사는 아직 하나도 보내 주지 않았다오.$B$B여길 좀 둘러보시오! 오우거도 있고, 황혼의 망치단도 있지. 하지만 내겐... 아무것도 없소."
rows["183:1468864167"]="네 마음이 가죽 작업에 있다면, 그레이트 포지의 북서쪽에 있는 그의 가게에서 피블 핀스핀드에게 얘기해봐"
rows["183:1694141"]="우리 안에 갇힌 나이트 엘프를 보니 왠지 모르게 전에 어디에서인가 본 듯한 느낌이 듭니다. 어떤 이유에선지 이 나이트 엘프는 당신과 눈을 맞추려고 하지 있습니다. 마치 당신이 우리 앞에 서있는 게 보이지 않는 것처럼 말입니다."
rows["183:1699414298"]="그대를 가르치기에 제 능력이 모자랍니다. 이제 동부 내륙지에 있는 맹금의 봉우리로 가서 드라크 스톤핸드라는 드워프를 만나 보십시오. 그의 작품은 제 것과는 비교조차 안 될 정도로 훌륭합니다."
rows["183:1854054211"]="어떻게 풀려났는지는 모르겠지만, 한 병사가 풀려나서 진주를 깨고... 우리를 구해냈습니다.$b$b그래서 생존자 몇 명은 물 위로 헤엄쳐 올라갔고... 몇 명은 이 동굴을 발견해 헤엄쳐 온 거죠.$b$b그렇지만 끝까지 살아남은 건 저뿐입니다..."
rows["183:1931362774"]="내 시야는 이 세계 전역에서 일어나고 있는 사건과 언젠가는 일어날 일들의 환영으로 가득 차 있다네. 이 환영의 대부분은 불길하네만 바꿀 수 없는 일이라고 믿을 필요는 없는 것이야."
rows["183:1965566406"]="저는 어린 타우렌이었는데 그 당시 겨우 십대기를 맞이했지만, 자유를 위한 전투를 용납하는 사람들은 제 이름의 의복으로 잘 보호받았다는 것을 알고 있었습니다."
rows["183:2026184466"]="아이언포지의 최고 흑마법사이신 라고 블랙렌치께서 당신을 찾고 계시오. 즉시 그분께 가서 보고를 드리는 게 좋겠소. 아이언포지의 쓸쓸한 뒷골목에 가면 그분을 만날 수 있을 거요."
rows["183:2028508751"]="아파티카에 안신다고 해서, 그 작은 공물이 통로를 순찰하지 않길 바라며, 우린 안전하기 위해 왔어."
rows["183:2103635099"]="이 연회는 무의미하오. 저 바보 귀족들은 결코 메디브를 만나지 못할 것이오. 그들은 진정 모르고 있는 걸까? 여기서 시간을 낭비하느니 가족들과 함께 어둠골에 있을 걸 그랬소이다."
rows["183:317116134"]="가죽세공을 배우고 싶다면 아이언포지로 가보십시오. 대용광로 근처에 괜찮은 가게가 하나 있다고 들었습니다."
rows["183:427153979"]="이런, 미안해요. 제가 가르쳐 드릴 게 없네요. 스톰윈드 구 시가지에 있는 사이먼 태너를 만나 보세요. 그는 멋진 근육을 가지고 있고 붉은색 머리를 한 친구랍니다."
rows["183:589360387"]="이 물체에는 이상한 무늬가 여럿 새겨져 있습니다. 어쩌면 이 물체의 기원을 알아내려고 한 트롤이 그 분석 과정을 새겨놓았는지도 모릅니다. 하지만 이 물체가 원형을 유지하고 있는 것으로 보아, 트롤들은 성공하지 못했을 것입니다."
rows["183:607418304"]="그 머리를 가져가면 다릴 녀석, 겁 좀 먹을 거예요. 당해도 싸지, 못된 녀석. 호호! 이걸 보고 어떤 표정을 지을지 기대가 되는걸요."
rows["183:861897507"]="왕립 연금술 학회는 어리석은 자를 기다려 주지 않으며 나 또한 마찬가지일세. 다음에 내가 타고 다니는 녀석에 대해 우리가 대화를 나눌 때쯤이면 자네가 언더시티의 친구로 인정받게 될지도 모르겠군. 그럼 그때까지 안녕히..."
rows["183:917178892"]="늙은 개에게 새로운 트릭을 가르쳐주지 못해. 적어도 누군가 한 번 내게 말했죠.$b$b자, 애완동물이 재능들을 배워내기를 원하십니까?"
rows["184:1005133779"]="뭐, 뭐라고?! 아, 저는...$b$b이렇게 흥미로운 발굴 작업이 이루어지고 있는 와중에 그런 문제에 초점을 맞추는 게 과연 적절할지 모르겠습니다.$b$b당신도 알다시피 꽤 불쾌한 이야기가 될 테니까요."
rows["184:119228367"]="똑똑히 들으시오. 우리는 암호 조각을 전달하고 안전하게 보관하는 임무를 맡고 있소. 사절은 일리단 님께서 직접 봉인하신 서한을 가져와야 하오. 서한이 없으면 조각을 전달할 수 없소."
rows["184:1256109235"]="김블의 가게에서 마법 재연마사를 찾을 수 있을 거예요. 대용광로에 있는 그리핀 조련사 바로 오른쪽에 시슬퍼즈의 신비한 이야기에서 말입니다.$B$B그가 당신을 잘 가르쳐 줄 겁니다."
rows["184:1282232167"]="아! 전사의 무예를 배우시려고요! 켈스트럼 스톤브레이커가 아주 잘 가르쳐줄 겁니다. 아이언포지 성문 동쪽에 있는 전투의 전당으로 가십시오."
rows["184:1405393978"]="내가 여기서 뭘 하고 있는지 모르겠어. 난 협상가의 경험은 없거든.$B$B옛날에는 술집에서 일했는데, 예쁜 데이지가 등장하면서 자리를 뺏겼지. 새로운 직업을 찾아야 할 때인 것 같아."
rows["184:1459350452"]="굴은 마법과 까마귀 선술집의 바로 북쪽, 하수도 서쪽에 있는 달라란의 아래쪽으로 이어집니다.$B$B약간의 모험을 더하는 방법으로는 날아서 달라란을 오가는 방법이 있지요."
rows["184:1536515836"]="녀석에게 악마의 룬을 가르쳐주는 대신 녀석의 영혼을 받기로 했어. 사실, 검은바위일족 오크의 영혼은 별 가치가 없지만 요즘처럼 어려운 시기에는 어떤 영혼이든 없는 것보단 낫거든."
rows["184:1570283158"]="대드루이드 룬토템 님이 이런 폐허 한가운데에 야영지를 만드시는 게 무모하다 생각하긴 했지만, 그래도 이곳에 혼자 오시게 할 순 없었어요.$B$B룬토템 님께서는 뭔가를 계획하고 계신 것 같아요. 뭔가 거대한 계획 말이에요."
rows["184:1657934713"]="마지노르 두마스랑 얘기하고 싶네 마지노르 두마스랑 얘기하는 거 같네 마지노르 두마스랑 얘기하는 거 같네 마지노르 두마스랑 얘기하는 거 같네 마지노르 두마스랑 얘기하는 거 같네 마지노르 두마스랑 얘기하는 거 같네 마지노르 두마스랑 얘기하는 거 같네 마지노르 두마스 도마스의 마지노르의 사당에서 만나보실거 같네"
rows["184:1823227798"]="저는 푸른용군단의 일원인 칼렉고스입니다.$b$b태양샘에서 스며 나오기 시작한 에너지를 한동안 지켜봤지요. 그 무서운 에너지는 이 세계에 종말을 불러올지도 모릅니다!"
rows["184:1901158222"]="하루에 한 가지 일만 골라 할 수 있다는 걸 잊지 마시오. 그 일은 제쳐놓고, 우리 용아귀 부족은 항상 더 많은 수정을 찾고 있다오. 보잘것없는 일꾼이라도 이 주둔지로 수정을 가져올 순 있으니 말이야."
rows["184:1925176832"]="그렇다네, 리치 왕은 우리 앞에 무릎 꿇을 것이야. 우린 마지막 복수를 해낼 걸세.$B$B그전에, 붉은돌격대라 알려진 골칫거리를 반드시 끝장내고 말겠네!"
rows["184:2009717436"]="내가 할 수만 있다면 가르쳐 주겠지만 너무 벅차군. 그러지 말고 썬더 블러프 중앙에서 북서쪽 상점에 있는 우나라는 타우렌을 찾아가 보시오. 정말 유능한 타우렌이지."
rows["184:277659198"]="똑같은 재료를 쓰는데도 제가 만든 물약을 사용하면 상처가 덜 아무는 것 같아요. 식물들이 변하고 있다는 한 가지 결론이 나오네요. 하지만 식물들이 무슨 이유로 무엇으로 변하고 있는지는 말씀 드릴 수가 없군요."
rows["184:288581913"]="아라소르 연맹이 포세이큰 파멸단을 상대로 힘겨운 전투를 벌이고 있는 아라시 분지로 가려면 스톰윈드 왕궁의 국왕 알현실에 있는 영주 하티셈을 찾으십시오. 그녀가 도와 줄 겁니다."
rows["184:368804450"]="왜 순례자의 상을 축하하는 거냐는 건 누가 알 수 있겠지?$B$B감자파티, 독성성 전염병... 우리가 무엇을 요리하는지는 정말 중요하지요?"
rows["184:541664702"]="자, 80번 고리를 79번 구멍에 끼우면 쾅! 당연히 폭발하죠! 자, 내 물건들을 보여줄 테니, 구입하면 일단 릴리암에게 가서 사용법을 제대로 배워요. 폭발해서 눈썹 태워 먹지 않도록!"
rows["184:59802129"]="우리를 위협하는 저 마법은 황혼의 망치단이 사용하는 것이다.$B$B우리는 놈들을 우리 고향에서 싹 쓸어버리기를 간절히 원하고 있지.$B$B하지만 우리의 분열 때문에 그리할 수가 없다.$B$B그래서 난 지켜보고...$B$B기다린다."
rows["184:749961422"]="부끄럽게도 우리 신도레이는 고향이라 부르던 곳을 너무 많이 잃었소. 머지않아 우리는 힘을 회복하고 스컬지로부터 우리 남쪽 영토를 되찾을 것이오!"
rows["184:792791992"]="젊은이, 당신은 영혼의 말에 좀 더 귀를 기울일 필요가 있소. 당신의 운명은 썬더 블러프에 있는 트라그 스톤후프라는 자에게 향해야 하오. 서로 가르침을 줄 수도 있을 거요."
rows["184:802912533"]="로켄?! 이거 정말 귀찮아졌군... 무쇠 드워프는 무찌른 것 같습니다만, 아직 저 어딘가에 무쇠 브리쿨을 대량으로 뽑아내는 기계가 있나 봅니다!"
rows["184:90549578"]="그대의 힘든 여정을 돕고 싶은 마음은 굴뚝같습니다. 하지만 푸른용군단은 지금 혼란에 빠져 있고, 이곳 세계수에도 제가 조사해야 할 시급한 사안들이 많습니다..."
rows["185:1046556952"]="오, 꽤 튼튼해 보이는군? 몇 가지 일을 도와줄 수 있겠어. 여기엔 풋내기 견습생밖에 일손이 없는데, 그 애들도 신경 쓸 일이 따로 많거든."
rows["185:1074735229"]="<왜성의 시선은 먼 벽에 있는 어느 지점에서 있다. 가끔씩 그의 입술은 숫자를 속삭이는 동안 움직인다. 그는 머릿속으로 합을 하는 것 같다.>$b$b미안해, 뭐 필요해?"
rows["185:1092717363"]="저 앞에 있는 얼간이가 노움 군대를 데리고 갑자기 나타나기 전까지는 정말 쉬운 일이었어요. 이 기분 나쁜 꼬맹이들이 우리보다 앞서나간다면 푸직 갤리윅스 님에게 제 목을 내놓아야 할지도 모르겠어요."
rows["185:1165635207"]="끝내주는 가을 축제 산양 경주는 모두 다 좋아하는 것이죠. 더 자세히 알고 싶으신가요? 산양 우리 옆에 있는 드리즈 텀블퀵에게 가보세요. 즐거움을 만끽하세요. 그리고 산양 경주를 즐기면서 가을 축제 상품 교환 동전도 타세요!"
rows["185:1302439631"]="요전 날 전투의 전당에 갔다가 레그누스 썬더그래니트가 자신의 동굴에 박제해서 놓을 새로운 전리품을 잡아왔다고 자랑을 늘어놓더군. 솜씨 있는 사냥꾼에게서 훈련을 받을 생각이라면 레그누스를 찾아가보시죠."
rows["185:1524556207"]="비록 부의 획득이 더는 우리 삶의 목표는 아니나 우리는 세상을 움직이는 것은 돈이라는 사실을 잘 알고 있습니다. 나루의 보좌로 가면 경매장에 가실 수 있습니다."
rows["185:1526257085"]="자네 나보다 훨씬 낫군! 자넨 나보다도 경험이 풍부한 이가 필요하겠는데... 그런 이라면 아마 언더시티 연금술 실험실에서 일하는 언데드 학자 허버트 핼시 정도가 되겠군."
rows["185:1533577951"]="잃어버린 섬을 거닐다가 새 동맹인 고블린이 만든 작품들을 보았네. 하지만 아직은 저들의 재주를 시험하는 중이라네. 여기서는 적의 요새를 제압해야 하는 상황이지."
rows["185:1568065795"]="이 생기 넘치는 어둠용은 악령의 숲을 갈라놓은 악마의 타락과 선명한 대비를 이룹니다. '어둠용의 숨결'이라 불리는 희귀하고 탐스러운 열매가 무겁게 매달려 있습니다."
rows["185:1644463234"]="여태껏 살면서 별별 광경을 다 봤지만 속삭임 협곡의 탐험가 연맹에 일어난 변화는 그중에서도 으뜸이지요.$B$B목숨을 부지하고 빠져나온 것만도 천만다행으로 여긴답니다!"
rows["185:1734872283"]="수년 동안 명예의 요새는 지옥불 반도의 두려운 존재들과 맞서 왔습니다. 이제 차원문이 다시 열리고 아제로스에서 지원군이 도착할 테니 이 지긋지긋한 교착 상태에 종지부를 찍을 수 있을 겁니다."
rows["185:1849980230"]="이 부근에서 낚시터는 아주 드물답니다. 팩스턴은 낚시를 할 만한 곳을 죄다 알고 있지만 아마 비밀로 하고 있는 장소도 좀 있을 겁니다. 얼음 호수로 가서 한번 얘기를 나눠 보시겠습니까?"
rows["185:1970460304"]="스톰윈드 회계사무소는 스톰윈드 상업 지구의 성문 옆에 있습니다. 돈을 세는 게 지겨워질 때는 꼭 황금 장미 여관에 들러 한잔 하시기 바랍니다."
rows["185:20313870"]="아직 쌍둥이 첨탑 폐허는 안전하지 않습니다! 2개의 봉화가 켜지고 그 지역의 안전이 확보되면 전투 깃발을 꽂으십시오. 자, 그곳으로 가서 어서 봉화를 접수하십시오!"
rows["185:2070241513"]="내 얘기를 들으면 좀 슬퍼질 거야. 예전에 나는 한 배의 선장이었다고.$b$b그런데 지금은 한 번만 더 강등당하면 다시 수병으로 추락할 위기에 놓였지. 과연 내가 그런 치욕적인 일을 참아낼 수 있을지 모르겠어."
rows["185:281071520"]="미안합니다만, 친구, 나는 보기보다 바쁜 사람이오.$b$b보시다시피 사령관님이 이 지역에서 발굴하신 내역을 문서로 만드는 임무를 맡았거든.$b$b정말 깊이 있는 고고학 자료가 될 거요."
rows["185:418719758"]="우리 군대는 폭풍의 눈을 차지하고자 여기 아웃랜드에서 호드를 상대로 전투를 벌이고 있습니다. 물론 격렬한 황천의 에너지 속에서 싸우는 일은 위험하지요. 당신은 우리와 함께할 자질을 갖추고 있습니까?"
rows["185:451788762"]="흙을 파는 것이 즐거워하는 취미라면, 파스트라이더스 스퀘어에 있는 벨리랑 함께 미친 짓을 하거라."
rows["185:509070852"]="상처를 치유해 줄 자가 곁에 없을 때, 응급치료법을 알고 있으면 목숨을 구할 수 있지요. 장인의 정원에 있는 단넬로르에게서 배워 보시죠."
rows["185:633168347"]="감시자 쟝의 드루이드 동료 중 한 명이었던 약초학자인 그린썸의 시체가 여기 있습니다. 그의 모습으로 보아 강제 노역소에서 탈출하던 중 재빠르고 깨끗한 솜씨를 가진 자에게 살해당한 것 같습니다."
rows["185:678222075"]="제 육신과 영혼에는 역겨운 저 호드 놈들에 얽힌 기억이 가득하지요. 슬픔, 좌절, 희생만이 가득하던 시간은 지나갔어요. 분노가 제 마음에서 떠나지 않은 채 싸움을 갈망하고 있어요!"
rows["185:77652561"]="아주 오래전에 여행을 다니다가 누군가를 만났는데 그 사람이 이런 말을 했었어요. \"그걸 사용하는 법을 통달하면 이걸 주겠소\"라고.$B$B그게 무슨 뜻인 것 같아요? 그때 나는 몰랐어요. 실은 지금도 여전히 모르겠고요..."
rows["185:81733833"]="나그란드를 지나서 숲에 도착하기 전까지 우리의 전통문화가 많이 사라지지 않았을까 걱정했습니다. 제 걱정이 기우였다는 것을 알게 되어 얼마나 다행인지 모릅니다.$B$B숲은 아직 그대로네요!"
rows["186:1116705993"]="<당신과 눈을 맞추지 못하는 켈수와>$B$B전투 도중에 도망치고 말았지만 야수를 풀어주는 일은 잊지 않았소.$B$B계속 데리고 있을 수가 없었다오. 모두 연기 속으로 뿔뿔이 흩어졌지..."
rows["186:1128451377"]="지금 보시는 건 다크문 사투장입니다. 다른 참가자들을 모두 때려눕히고 상품을 차지할 힘과 의지가 있습니까?$B$B격투는 매일 밤 자정에 시작되며, 그 후 3시간마다 한 번씩 열립니다."
rows["186:1225668514"]="오늘은 이미 승자가 모두 나왔지만, 낚아 올린 맛둥어는 전부 장에게 팔 수 있습니다!\010잊지 마세요! 일요일엔 언제나 낚시 기술을 뽐낼 기회가 있습니다."
rows["186:1252409583"]="반나르 스톰파이크는 알테락에 있는 얼라이언스 군대의 장군이며,  ⁇  발다르에서 그의 군대를 지휘한다.$B$B만약 그가 패배한다면 얼라이언스은 확실히 알터랙의 전투를 잃게 될 것입니다."
rows["186:1323896168"]="<고개를 끄덕이는 넬타라쿠>$B$B카리나쿠... 그녀는 용아귀 요새 꼭대기에 갇혀 있다. 난 여러 차례 그녀를 구하려고 시도했지만. 모두 실패했다. 그대는 그 괴물들과 싸운 경험이 있는 걸로 아는데... 내 말이 맞나?"
rows["186:1659089082"]="드루이드들의 주최로 달숲에서 달의 축제가 열리고 있습니다. 먼 곳에 계시는 분들을 위해 스톰윈드 바로 바깥에서 이동 서비스를 제공하고 있습니다."
rows["186:1719706941"]="그리고 그는 정말로 영생을 얻었어. 저주받은 자들의 교단에서 서열이 빨리 오른 라스에게 리치 왕이 직접 영생을 주었지. 그리하여 리치로 변한 라스 프로스트위스퍼가 탄생한 것일세.$B$B이제 무슨 말인지 이해가 가는가?"
rows["186:2085377101"]="당신이 한 가지 알아두어야 할 것은 1만 년 동안의 삶을 기록할 수 있다 보니 삶에 대해서 좀 독특한 관점을 갖게 되더라는 거요. 오늘날 당신의 고난과 시련은 무의미하오."
rows["186:2099530428"]="내가 무덤 속에서 기어 나왔을 때 가족들이 나를 두 팔 벌려 반겨줄 것만 같았소. 환대는커녕 이제는 더 이상 이해할 수 없는 언어로 소리를 고래고래 지르며 나를 마을 밖으로 쫓아내더군."
rows["186:2118727218"]="이 모피는 아직 손을 더 봐야 할 거 같군요. 가죽 만드는 데 오래 걸리지 않으면 좋으련만... 이렇게 오래 기다리지 않아도 될 방법이 있을 거예요! 건강에도 안 좋잖아요, 그렇죠?"
rows["186:249661577"]="그렘록이 언제나 최고의 요리를 만들어낼 만큼 운이 좋은 건 아니지만, 그래도 배워둘 만한 맛 좋은 조리법을 꽤 알고 있습니다. 썬더브루 양조장에서 일하고 있는 그를 찾아보십시오."
rows["186:33003753"]="글쎄, 엘윈 숲에는 마법부여사가 있는 것 같지 않지만, 스톰윈드에 루칸이라는 이가 가게를 하나 운영하고 있지요. 그를 찾아가서 훈련을 받을 수 있는지 한번 알아보십시오."
rows["186:396143225"]="당신은 분명 나보다 솜씨가 더 좋은 대장장이요. 내가 그렇게 말한 사실을 다른 이에게 말한다면야 당연히 부인할 테지만 말이오. 가서 테룸 딥포지와 얘기를 나눠 보시오. 당신에게 뭔가 더 가르칠 수 있는 이가 있다면 바로 그 친구니 말이야."
rows["186:503499974"]="그 머리를 가져가면 다릴 녀석, 겁 좀 먹을 거예요. 당해도 싸지, 못된 녀석. 호호! 이걸 보고 어떤 표정을 지을지 기대가 되는걸요."
rows["186:628040869"]="이 조그만 집 안에서 전 성벽 밖에서 한창 벌어지고 있는 전투에 참가하는 꿈을 꾸곤 합니다. 하지만 지금으로서는 의무감에 저를 대신해서 싸움터로 나가는 이들에게 지식을 나누어줄 수밖에 없답니다."
rows["186:662195826"]="낯선 사람, 서둘러 레이디 제인 프라우드무어와 연락하십시오. 그녀의 작은 얼라이언스 세력은 용감하게 불타는 군단의 초기 공격을 완화하고 아치몬드의 접근을 늦추려고 노력하고 있습니다."
rows["186:700817365"]="제 임무는 딱 하나입니다. 서부 성소가 아무런 이상 없이 돌아가도록 하는 것이죠.$B$B제 용건부터 말할 수밖에 없는 상황을 이해해 주십시오. 보다시피 여기 상황이 걷잡을 수 없이 돌아가고 있습니다."
rows["186:750651774"]="이제 혼자서도 요새로 돌아갈 수 있소. 당신이 시간을 벌어 주었으니 여기서 몰래 빠져나갈 수 있을 거요. 뉘신지는 잘 모르겠지만 어쨌든 고맙소이다. 언제나 엘룬의 축복이 함께하기를!"
rows["186:827277030"]="지금 날 놀리는 거야? 맞지?! 놀리는 게 아니라면 나를 어릿광대 정도로 생각하는 거겠지. 그런 거야? 내가 광대처럼 보여? 나 원 참, 맞지?! 지금 내가 광대라고 생각하는 거지!"
rows["186:90268251"]="마가타 그림토템을 여기 포로로 붙잡아두고 있다니, 뭔가 이상하지 않아? 마가타의 토템이 모두 파괴됐다는 건 다행이지만.$B$B케른 블러드후프를 중독 시킨 게 그녀라는 말까지 들었어... 마가타가 우리 편이었으면 좋겠군."
rows["186:91616340"]="얼라이언스의 방문 멤버들은 주로 남서쪽 달라란의 실버 앙클라브에 머물고 있다.$B$B그곳에는 숙소가 있고, 다양한 얼라이언스 도시와 전투장으로 가는 문도 있다."
rows["186:983400010"]="길드를 창설할 생각이라면 아이언포지 사무소에 있는 욘도르 스틸브라우를 찾아가세요. 아이언포지 성문에서 남동쪽으로 가면 됩니다."
rows["187:1484460778"]="아주 오래전에 여행을 다니다가 누군가를 만났는데 그 사람이 이런 말을 했었어요. \"그걸 사용하는 법을 통달하면 이걸 주겠소\"라고.$B$B그게 무슨 뜻인 것 같아요? 그때 나는 몰랐어요. 실은 지금도 여전히 모르겠고요..."
rows["187:1747429101"]="나무구렁 일족과 적대적인 관계가 아니라는 것을 증명한 자만이 공격을 받지 않고 무사히 요새를 통과할 수 있소. 이방인이여, 당신은 우리의 신뢰를 얻기 위해 어떠한 노력을 했소?"
rows["187:1754522960"]="여행자, 환영해! 니벨란에 오신 것을 환영해 주세요. 작고 차가운... 하지만 매우 편안한! 따뜻한 것을 드릴 수 있나요? 제 부엌은 낯선 사람들에게 관대합니다. 특히 불확실한 시기에..."
rows["187:1820659364"]="아, 내가 외딴 곳에 있다는 건 나도 알고 있소. 알고 있다니까!$B$B사실 내 집은 톱니항에 있는데 비행선이 이곳에 불시착해버린 거요. 여기 떨어진 김에 눌러앉아 그동안 해보고 싶던 연구나 해 볼까 하오!"
rows["187:1967179575"]="오그리마에서 못생긴 오크 사요크가 단검 쓰는 법을 가르쳐주지. 다른 도시에서 배우고 싶다면 실버문의 원정순찰대 광장에 있는 일레다나 언더시티의 군사 지구에 있는 아키발드에게 가서 얘기해 보게."
rows["187:2088973867"]="이 미지의 땅을 탐험하는 것도 중요하지만 아제로스를 버려서는 안 됩니다! 파멸단과 싸움에서 승리하려면 그 어느 때보다도 당신의 도움이 절실하게 필요합니다. 아라시의 자원들을 안전하게 지켜야 합니다!"
rows["187:245195471"]="여행자여, 중앙 생태지구에 온 것을 환영합니다. 숄리라는 고블린을 상대할 때는 아주 조심해야 합니다. 지금까지 '친구'라는 단어를 마침표 대신 사용하는 자는 그자밖에 없었던 것 같습니다."
rows["187:346921282"]="환영합니다, 친구! 가을 축제 광장에 잘 오셨습니다! 가을 축제엔 즐길 거리가 아주 많지요. 양조장끼리 경쟁하는 걸 지켜보는 것도 재미있답니다. 궁금하신 게 있으면 언제든 절 찾으세요!"
rows["187:555472225"]="저희는 하이잘 산의 전투에 대한 시험용를 집중적으로 하고 있습니다. 시험용에 참여하시려면 보랏빛 눈의 감시자에 대한 평판이 우호적 이상이어야만 합니다.$B$B보랏빛 눈의 감시자의 평판은 카라잔의 몬스터 처치 혹은 관련된 퀘스트로 얻으실 수 있습니다."
rows["187:562551206"]="일리단의 부하들을 처치하는데 가장 숙련된 용사들만이 내 물건을 가질 수 있네.$B$B샤타르, 세나리온 원정대, 그리고 알도르 사제회에 확고한 동맹이라면 다시 고려해 보겠네."
rows["187:583744773"]="그대는 저의 제자가 되기에는 물약 제조 기술이 부족합니다. 저기 있는 실반나 포레스트문이나 밀라 페어랜코라가 그대를 도와줄 수 있을 듯싶군요."
rows["187:584310064"]="<엘프는 웃음을 내뱉고, 그녀의 미소만큼이나 끔찍한 것, 날카로운 노란색 치아로 가득하다.>$b$b운명은 아이러니가 없는 것 같네."
rows["187:695165576"]="<죽음의 풀을 씹고 있는 듯한 에랄란>$b$b사랑의 묘약을 만들 작정이라면 잘못 찾아오셨습니다. 실명, 신경 마비, 그리고 숨통 끊기가 제 전문이니까요."
rows["187:852187141"]="드렉타르는 서리늑대 부족의 군사적, 정신적 지도자로서 서리늑대 요새에서 군을 지휘합니다.$B$B그를 처치하면 알터랙의 호드군은 무너질 것입니다."
rows["187:949392623"]="식물학자 나테라는 초신을 찾는 데 관심이 많고, 그녀는 당신의 지혜를 여러분들과 공유할 수 있을 것 같습니다."
rows["188:1090564800"]="제가 며칠 전 고약한 트로그와 싸울 때, 탐네르 그 친구가 붕대를 감아 주더군요. 지금은 씻은 듯이 나았답니다! 분명 탐네르라면 당신에게 좋은 붕대 만드는 법을 기꺼이 가르쳐 줄 겁니다."
rows["188:1293054817"]="이 유물은 손상되지 않은 듯이 보이지만, 먼지와 진흙이 두텁게 덮여 있어 분명하지 않습니다. 마법의 힘은 전혀 담겨 있지 않은 것 같습니다."
rows["188:1374668168"]="자네는 순위 경기에 참여할 만큼 강하지 못하군그래. 하지만 투기장 사무관에게 가서 연습 경기에는 참여할 수 있다네. 훈련을 시작하는 건 빠를수록 좋은 거라네."
rows["188:157287576"]="내가 레네 숙소관이라면 어디 있겠지? 아마 그로우스 엣 테버너 안에 있을지도 몰라요. 그래, 그게 다지 확신합니다."
rows["188:1674919819"]="난 오그리마와 오크 종족에게 확고한 동맹인 자들에게만 탈것을 판매하네. 가서 우리 오크족에게 자신을 증명해 보이게나. 그럼 내 힘센 늑대들을 살펴볼 수 있게 해 주겠네."
rows["188:1705415946"]="태양너울 통제권은 이제 거의 우리 손 안에 있습니다. 지금 이대로 항구에서 증원군이 올라오지 못하도록 막아낸다면 반드시 성공할 수 있을 겁니다.$B$B목표는 $3238w퍼센트 만큼 달성했습니다."
rows["188:2009735119"]="이런 범죄는 반드시 해결해야만 합니다. 여관 위치도 그렇고 파괴된 상태도 심각해서 이번 사건이 아주 까다롭게 됐습니다. 현장을 조사할 때 최대한의 주의를 기울여 주십시오."
rows["188:2074658456"]="구루바시 부족은 학카르와 함께 사라졌습니다. 우리 잔달라 부족도 대부분 고향으로 가버렸고요.$b$b이제 줄구룹을 감시하는 건 저, 차발, 그리고 밤발라의 검은창 부족의 몫입니다."
rows["188:2080380605"]="글쎄요... 인정하고 싶진 않지만 계속해서 훈련을 받으실 거라면 제 언니를 찾아가 보셔야 할 것 같군요. 저는 언니만큼 많이 알지는 못하거든요. 아직까지는 말이에요! 언닌 로켓 자동차 옆에 서 있을 거예요."
rows["188:325371291"]="당신에게 차원문을 이해할만한 정신적 능력이 있는 것 같지는 않군요.$B$B그래도 제 뒤에 있는 수정을 사용하면 수정노래 숲의 달라란 아래에 있는 폐허로 순간이동할 수 있으니 알아두세요."
rows["188:329967666"]="나는 잔달라의 로아, 잔자라오. 동족을 돕기 위해 잔달라에서 이 에테리얼 형상을 하게 됐소이다. 학카르는 결코 내 영혼을 지배하지 못하오.$B$B난 잔달라 부족을 돕는 이들을 돕는 일을 하고 있소."
rows["188:44129756"]="고블린 스팀휘들 결투 대회가 시작되었네. 가젯잔이나 나그란드, 그리고 칼날 산맥의 투기장 밖에서 투기장 팀 창단허가서를 파는 투기장 조직위원을 찾을 수 있을 것이야."
rows["188:563282739"]="대장군 카드를 모아 한 벌이 되면 영웅심의 상급 다크문 카드를 보상으로 받게 될 겁니다. 이 카드는 간혹 당신이 근접전을 펼칠 때 치유를 해 주기도 하지요."
rows["188:666085658"]="또 방해로군. 이런 식으로 나오면 대체 나보고 어떻게 일을 하라는 거요? 대답할 필요 없소. 변명 따위 듣자고 한 말이 아니니까. 만약 이곳을 청소하고 우리 제국의 영토를 확장할 생각이라면 날 좀 가만히 놔두시오!"
rows["188:695153048"]="드워프 지구를 방문한 와일드해머 주술사들이 몇 명 있다고 들었으니, 그곳에서 운을 시험해 보시는 게 좋겠습니다.$B$B영웅의 계곡에서 빈둥거리던 드레나이 선견자도 그들을 만나러 갔답니다."
rows["188:776594491"]="헤멧이 지상에서 사냥을 할 때 보조 날개를 관통시키지만 않았어도 우리는 추락하지 않았을 걸세!$B$B하지만, 금방 고쳐 놓을 테니 너무 걱정하지 말게."
rows["189:1084491477"]="안녕하십니까, 여행자여. 전 카라잔의 열쇠를 소지한 분을 주인님의 귀한 손님으로 모시도록 교육받았습니다. 뭐든지 궁금하신 게 있으면 물어보십시오. 무엇을 도와드릴까요?"
rows["189:1091336333"]="일리단의 부하들을 처치하는데 가장 숙련된 용사들만이 내 물건을 가질 수 있소.$B$B샤타르, 세나리온 원정대, 그리고 점술가 길드에 확고한 동맹이라면 다시 고려해 보겠소."
rows["189:1149265379"]="좋소. *딸꾹*... 근데, 당신 낯이 익어. *딸꾹* 나하고 윈저가 수 처... 으... 처... 수 백만이나 되는 오크를 물리친 얘기를 들려줬던가? 꺼억!$B$B좀 앉아 보시오, 친구. 아주 멋진 얘기니까!"
rows["189:1206571416"]="저희는 원소의 힘을 빌려 스톰윈드에서 높은 둑으로 통하는 차원문을 열기로 약속했습니다. 하지만 황혼의 요새에서 원소의 흐름을 어지럽혀 일이 제대로 진척되지 않고 있어요.$B$B대체 저기서 어떤 미친 짓을 벌이고 있을까요?"
rows["189:1211050440"]="그런 종류의 마법은 결코 좋은 게 못 됩니다. 김리즈 녀석, 다른 곳을 놔두고 왜 하필 썬더브루 양조장 바깥에다 노점을 차린 건지... 누구 허가를 받았는지도 모르고 있단 말입니다! 그 녀석은 가까이하지 않는 게 좋을 겁니다. 제 말 아시겠습니까?"
rows["189:1563305435"]="메인위버 부부는 다르나서스로 가는 길에 집을 짓고 살면서 가죽세공술을 연구하고 있답니다. 가죽세공이라면 나디야가 아주 잘 가르치지요. 배울 것이 있는지 가서 한번 보세요."
rows["189:1749444228"]="복창하게! 나는 못났다. 못났어도 싸움에는 소질이 있을 거라 믿네.$B$B내 분대 하나가 곧 행군을 떠날 걸세. 그 굼뜬 엉덩이 바짝 잡아 들고 그 행군에 합류하게!"
rows["189:1772396022"]="보통 제 신분으로는 그대와 직접 대화할 수 없습니다. 그분에게 알현을 요청해야 합니다. 하지만, 제가 직접 일을 맡겼으니... 그래, 의논할 내용이라는 게 뭡니까?"
rows["189:1843416541"]="첫 번째 고대 생물인 네스피라의 일을 처리하는 건 꽤 힘겨웠습니다. 우리 앞에 있는 또 하나의 고대 생물, 고레크는 죽어가고 있습니다.$B$B고통에 겨워 울부짖는 것이 느껴집니다. 무언가가 고레크의 생명력을 빼앗아 가고 있습니다. 무엇 때문일까요?"
rows["189:1852957877"]="자네가 본 벌레 중 가장 거대한 벌레가 저 실리시드 곤충집 한쪽을 돌아다니는 걸 봤어. 아니면 양쪽이거나 말이야. 아무래도 열사병이 오나봐... 저기 있는 모래 고양이가 자네도 보이나?"
rows["189:1870648226"]="안드라스트레에서 국경을 지키기 위해 남편을 모집한 이후로...$b$b그늘샘에 가야 하지만 혼자 갈 용기가 없어"
rows["189:2061250641"]="대족장님께서는 얼라이언스를 처리하는 데 도움을 준다면, 우리가 고블린을 구해내고 갤리윅스를 처치할 때 돕겠다고 약속하셨어요.$B$B제게는 꽤 공정한 제안 같아요. 내 친구의 적은 나의 적이다. 맞죠?"
rows["189:263398788"]="띠리릿... R-3D0는 드워프어와 노움어 그리고 인간의 공용어에 능통합니다. 그런데 $c님께서 하는 말은 제 프로그램으로 이해할 수가 없습니다!$B$BR-3D0 부품의 소음 때문에 말씀이 잘 들리지 않으니 크게 얘기해 주시기 바랍니다!"
rows["189:432286089"]="트롤 부두술사 그 중간에 스톰윈드위대한 유무바보는 공원에서 자택을 찾았습니다."
rows["189:449645505"]="마리온 콜은 브릴 남동쪽 끝의 갈로우스 엣 타버너의 독서실에서"
rows["189:602125087"]="바로 그거죠. 실험 삼아 저놈이 흘린 담즙을 이 방열복에 발라 봤는데...\010<목소리가 잦아드는 핑클>\010저기, 혹시 제 무두질용 손칼 어디선가 못 보셨나요? 제가 어디 이상한 데 놔뒀나 봐요."
rows["189:611251281"]="현재 우리가 이 땅에 설 자리는 별로 없지만 언제나 인간들이 이기란 법은 없지 않소. 그때가 되면 우리를 노예로 만든 대가를 치르게 될 거요. 그들의 기만에 대한 대가로 거짓말만을 내뱉는 그 혀를 잘라버리고 말겠소."
rows["189:644905987"]="귀족의 정원 축제는 아제로스의 드루이드들이 생명의 재탄생을 축하하는 시간이랍니다. 알은 생명의 탄생을 상징할뿐더러, 모든 이에게 축제 정신을 불러일으키기에도 제격이죠. 그렇지 않습니까?"
rows["189:811860086"]="저 망할 스컬지에게 쫓겨난다면 우린 끝장이에요! 여기 정착민은 노스렌드에서 새롭게 출발하려고 모든 걸 바쳤단 말이에요!$B$B차라리 목숨 걸고 싸우는 쪽을 택하겠어요."
rows["189:966784970"]="지옥 수정괴철로로 당신의 에펙시스 결정을 불안정한 야수의 영약으로 변환할 수 있습니다. 이 영약은 더 민첩하고, 강해지면서 체력이 좋아지게 합니다.$B$B아래 목록에서 선택하시기 바랍니다."
rows["18:13910092"]="반갑소, 친구."
rows["18:1411880117"]="필요한 거라도 있소?"
rows["18:152787048"]="여기 일하고 있어요"
rows["18:15560428"]="직무를 맡고 있어, 가자, 가자"
rows["18:1602850788"]="- 사라졌어?"
rows["18:1671532605"]="밤에게 찬사를!"
rows["18:1728393950"]="아... $b$b여기는 어디지?"
rows["18:1791256246"]="이거 보세요, 지금은 쉬는 시간이란 말이에요."
rows["18:1976007674"]="프쉬쉬쉬쉬쉬?"
rows["18:299897298"]="개구리가 달아나려 해요!"
rows["18:336026608"]="안녕하신가!"
rows["18:381406489"]="비그르름 비르금 비름!"
rows["18:403977203"]="할 말이 있거든 빨리 하게."
rows["18:522482328"]="반갑다, 필멸의 존재여..."
rows["18:552313266"]="네, 여전사님?"
rows["18:704008132"]="<크리스토프가 끙끙댑니다.>"
rows["18:72626976"]="뭐하고 싶니?"
rows["18:819609686"]="내가 화려하고, 심하게"
rows["18:912046079"]="- 여기 뭐가 있어?"
rows["18:913157835"]="날 내버려두십시오, 어리석은 자여!"
rows["18:926223506"]="공격받고 있네!"
rows["190:1012984322"]="당신 새 왕이지? 새 왕 만세!$B$B이 크리그 고르독 술 보게 해 준다. 술 하면 오우거 술, 오우거 술 하면 고르독 술! 나한테서 좀 살 생각 없어, 왕?!"
rows["190:1166439104"]="모험을 찾고 있는 게로군. 나도 말이야... 우리 트롤이 이곳으로 왔을 때 지겹게 모험을 찾아 다녔지. 이제는 하루하루를 다른 이들을 가르치면서 그들의 모험담을 듣는 낙으로 살지."
rows["190:1253058391"]="<고대정령의 눈빛은 광대하고 깊습니다.>$B$B<이 생명체가 당신이 이해할 수 없는 말로 천천히 말합니다. 서늘한 느낌이 등줄기를 타고 흐릅니다. 당신은 공포와 혼란에 압도됩니다.>"
rows["190:1291587280"]="빈 비커 옆에 기름 표본 몇 개가 놓여 있습니다. 비커를 보니 표본 다섯 종을 담을 수 있을 듯합니다.$B$B어떤 기름을 먼저 넣겠습니까?"
rows["190:1313857001"]="음, 이제 다 된 것 같군요. 필요한 아서스의 눈물을 모두 모았습니다. 주위에 도움이 필요한 곳은 없는지 알아보세요. 어딘가 전쟁 물자 수집에 도움을 바라는 이가 분명히 있을 테니까요."
rows["190:1648995307"]="여기 내 친구인 불리위프가 장착 무기 사용법에 대해서 알려줄 것입니다. 혹은 원하신다면 다르나서스 전사의 정원에 있는 나이트 엘프 무기 전문가인 일예니아 문파이어에게서도 배울 수 있을 겁니다!"
rows["190:2009460148"]="나머지 아군이 어떻게 되었는지는 모르겠네.$b$b호드든 얼라이언스든 가리지 않고 계속해서 포로들이 끌려왔으니까. 모두 간신히 숨만 붙어서 말이야.$b$b아마 협곡 너머로 끌려갔거나, 아니면 죽었을 거네."
rows["190:238200930"]="마법봉 때문에 왔나? 아니면 단지 룬을 사 모으기 위해?$B$B잠깐! 혹시 어떻게 한 번 쓰레기 같은 물건이나 처분해 볼까 하고 온 건 아니겠지?! 내 끊임없이 네게 물건을 사라고 강요할 테니 두고 봐. 어서 물건을 사, 사, 사란 말이야!"
rows["190:270398738"]="그대의 도움이 정말 큰 힘이 되었습니다.$B$B세나리온 원정대는 앞으로 일리단이 절대 하늘에서 오염된 수정을 떨어뜨리지 못하도록 온 힘을 다해 저지할 것입니다."
rows["190:288310353"]="내 생각에는 말이지, 해군에서 이 쌈박질을 해결해야 한다고 보오.$B$B우리 모두가 죽기 전에 밖에서 춤이나 출 때라는 거라오.$B$B내 말 무슨 뜻인지 알겠소, 친구?"
rows["190:593112207"]="미셸 벨 의 침대에 있는 태도 는 놀라운 것 이다! 그 는 그 를 가르쳐 줄 수 없겠지만, 그 는 분명 히 적절한 초상급 을 가르쳐 줄 수 있을 것 이다. 현재 그녀는 라이온 프라이드 인 에 거주 하고 있다."
rows["190:700456909"]="훈련이 거의 절정에 다다랐군요. 더 나은 실력을 갖춘 마법부여사가 되려면 찾아가야 할 스승이 또 있습니다. 그녀의 이름은 안노라라고 하며, 울다만으로 가면 만날 수 있을 겁니다."
rows["190:744773660"]="빅스톤의 허풍 따윈 잊어버리라고. 좋은 물건을 찾고 있나? 이 크릭셀에게 알아보게나. 원하는 물건이 있을 거야, 물론 그에 걸맞은 위치에 있다면 말이야. 그 뭐냐, 투기장 말이야. 겁쟁이들에겐 어울리지 않는 일이지만 말이야, 친구."
rows["190:817253493"]="타이진이라고 하는 여자를 찾아가보게. 칼바위 언덕 동쪽에 있는 병영 안에 있을 게야. 당신에게 신을 공경하는 법을 가르쳐 줄걸. 단, 당신이 그녀를 공경하는 태도를 보일 때의 얘기지."
rows["191:1312274209"]="설인은 사납고 교활한 생물이라네. 그리고 이놈은 설인 중에서도 가장 강한 놈이지. 우리는 음식에 약초를 섞어서 녀석이 계속 잠을 자게 한다네.$b$b그렇다고 이놈이 투기장에서 둔하리라 생각하지는 말게."
rows["191:1385622757"]="<얼빠진 표정으로 당신을 맞이하며 위아래로 훑어보는 아라코아>$B$B우리의 노력이 결실을 거둔 것 같기는 한데 우리가 막으려는 것보다 훨씬 끔찍한 생물인가요?"
rows["191:1444319901"]="자네가 이제 나를 능가하다니 정말 기쁘군. 이제 길을 떠나야 해. 음, 썬더 블러프 중앙에서 북서쪽 상점에 있는 우나라는 타우렌을 찾아가보게. 내가 보장하건대 그녀는 아주 실력 있는 스승일세."
rows["191:1493491223"]="약초니 씨앗이니 하는 것들 말씀입니까? 그런 거라면 레이나 스톤브랜치가 전문이지요. 레이나는 대용광로 남쪽에 있는 아이언포지 치료소에서 식물을 돌보고 있답니다."
rows["191:1625634053"]="쓸데없는 수다나 떨면서 낭비할 시간이 없소. 사냥거리를 찾고 있다면 강가에 있는 딕티나에게 말해 보시게. 분명히 그녀에게 도움이 필요할 테니, 여기서 동쪽으로 가서 그녀를 만나보시오."
rows["191:1639471101"]="내가 하는 모든 말을 명심하게. 적의 뿌리를 뽑을 때까지는 절대 배움을 게을리해서는 안 돼. 방어구도 열심히 갈고 닦아놓고. 경비도 소홀히 해서는 절대 안 되지."
rows["191:1707849532"]="전투는 아주 성공적이며 스컬지 세력이 약해진 것 같습니다. 우리 해안에서 스컬지를 몰아내는 것은 이제 시간문제일 뿐입니다. 이 전투에 도움이 되도록 당신에게 마법을 걸어 드리겠습니다."
rows["191:1779385263"]="카라노스로 가면 토그너스가 힘차게 모루를 때리는 소리를 틀림없이 들을 수 있을 겁니다. 귀를 후빈 지가 오래돼서 잘 들리지 않는다면, 더 자세히 알려드리지요. 대장간으로 가보십시오."
rows["191:182465143"]="빛의 전당에 가면 우리의 투기장 사무관을 찾을 수 있을 겁니다. 그리고 간병인 브릴과 함께 지내는 \"미글릭 블롯스트롬\"이라는 고블린이 있는데, 자신을 세계 투기장 결투 대회 대표라고 주장한다고 하더군요."
rows["191:195327909"]="아이언포지 성문 북쪽의 신비의 전당에 가면 마법 기술을 배울 수 있습니다. 그곳에서 늘 책 속에 파묻혀 사는 율리 스톰케틀을 찾으십시오."
rows["191:2006097862"]="이 게시판에는 위험한 임무를 완료한 대가로 받는 보상에 대해 다양한 공지 사항이 적혀있습니다. 특별히 눈에 띄는 내용은 없습니다. 나중에 다시 확인하는 것이 좋겠습니다."
rows["191:2082876183"]="으으, 운도 되게 없으시네요! 제 기술은 당신에게 도움이 될 만큼 뛰어나지 않아요. 음... 저기 베틀 옆에 있는 핌블 파인스핀들에게 가 보세요. 저보다 훨씬 더 오래 가죽세공을 했으니까요."
rows["191:2090881236"]="오, 이 푸른 가죽은 정말 매력적이군. 알다시피 이 근방에는 호드의 신병이 되고 싶어서 지혜보다 열정만을 앞세워 사냥을 하는 이들이 아주 많네. 그러니 누구나 조심해야 하지."
rows["191:2113083976"]="전 기초 기술을 습득한 이들만 가르치고 있습니다. 다르나서스 장인의 정원에 있는 다리안나라는 나이트 엘프를 만나 보십시오. 당신의 기술을 보완하는 데 그녀가 적격일 겁니다."
rows["191:279976142"]="살데릴의 안식처에서 요청한 물품 목록입니까? 그분이라면 제가 가진 최고급 제품을 요청하실 만합니다. 아, 살데릴 경의 친구분들께도 최고급 포도주를 특별 가격에 드리겠습니다."
rows["191:361792155"]="무두질을 배우고 싶은 거라면 발투스 스톤플레이어를 찾아가십시오. 가죽을 깔끔하게 벗겨내는 방법이라면 그 친구가 잘 가르쳐줄 겁니다. 대용광로 북쪽에 있는 파인스핀들의 가죽 상점으로 가면 됩니다."
rows["191:391450359"]="보르구스에게 훈련을 받고 싶다고요? 어디 있는지 가르쳐 드리겠어요. 내 대장간에서 북서쪽에 있는 사거리를 지나 서쪽 길로 가십시오. 오른쪽 두 번째 건물에 있을 거요."
rows["191:447284260"]="육안으로는 볼 수 없지만 우리의 성소는 대지를 가로지르는 지맥에서 비전 마력을 빨아들입니다.$B$B태양샘이 사라진 후 성소는 우리에게 안정적으로 마력을 공급해주는 원천의 역할을 하고 있습니다."
rows["191:503194466"]="호그럴 바칸을 찾고 있는 모양이군요. 마침 저도 몇 가지 절도 사건으로 그를 찾고 있었습니다. 그 드워프, 분명 에일 맥주를 마시러 썬더브루 양조장에 조만간 들를 겁니다. 어쩌면 지금도 거기 있을지도 모르겠군요."
rows["191:518489173"]="보면 모르나? 땅이 바위처럼 얼어붙었잖나!$B$B시체마차 바퀴는 기껏해야 진흙탕이나 지나갈 정도밖엔 안 되지. 마차를 끌어내려면 누더기골렘과 사슬이 있어야 하네."
rows["191:859145549"]="깨끗하기 그지없던 이 호수와 주변의 땅에 얼마 전 황혼의 망치단이 침범했다.$B$B놈들은 호수를 오염시켰지. 내 놈들을 몰아내고 다시 호수를 정화할 것이다."
rows["191:868323046"]="결혼이 성사됐군! 행복한 연인에게 줄 결혼 선물을 준비해야겠어. 뭔가 중요한 걸로 말일세.$B$B이 결혼식은 마지막 기회일세. 온 와일드해머 드워프의 미래가 이 단 한 번의 기회에 달렸다네!"
rows["192:1205188256"]="노움의 옆구리를 여러 번 찔러대면 얼마나 유용한 정보를 얻어낼 수 있는지 알면 아마 놀랄 걸세. 묶인 상태를 벗어나는 꼼수나 맛있는 과자를 굽는 비법, 심지어 하늘을 나는 기계를 만드는 비법까지 말이지."
rows["192:1411288272"]="하루에 두 번, 아침 6시와 저녁 6시에 땜장이왕 멕카토크께서 직접 가을 축제 광장으로 나오셔서 맥주통 따기 의식을 거행하신답니다. 절대 놓치지 마세요!"
rows["192:1505742537"]="안녕하시오. 당신도 샤타리 하늘경비대에서 더 높은 지위를 얻으면 칼날 산맥의 하늘경비대 전초기지까지 이어지는 직항로를 이용할 수 있을 것이오."
rows["192:1712269869"]="아... 신기하고 진귀한 물건 말이로군. 우린 안목 있는 여행자들을 위한 아제로스의 희귀한 물건들을 전문으로 취급하지.$B$B이렇게 나를 찾아온 걸 보니 자넨 찾는 물건이 있는 게로군."
rows["192:1751955663"]="이봐요, 슈바이처랑 로이타우한테 여기 일이 다 잘 돌아가고 있다고 전해 주세요. 굳이 여기까지 와서 확인할 필요가... 뭐라고요?$B$B그들이 보낸 게 아니라고요? 그럼 왜 절 귀찮게 하는 거죠?$B$B전 할 일이 많다고요!"
rows["192:1848012157"]="우리는 눈 폭풍의 덮개로 공격했습니다.$b$b스컬지군들은 경비에서 벗어나지 못했고 우리의 승리는 확실했습니다$b$b그리고... 우리 뒤에서... 호드은 아무데서나 찾아왔다.$b$b그들은 우리에게 모든 것을 지불했습니다."
rows["192:1976915556"]="파스트라이더스 스퀘어의 블러드 기사들은 실버문의 무기 마스터인 이레다에게 그들의 홀 안에 공간을 허락합니다. 그녀의 훈련은 저렴하지는 않지만, 당신은 그녀의 전문성을 높이 평가할 것입니다."
rows["192:247268074"]="전 경주장에서 일하는 평범한 상품권 교환원이었어요. 헌데, 경주장이 사라졌으니, 백수가 돼버렸죠.$B$B이제 협상가가 되어보는 수밖에 없겠군요. 제 일을 좀 도와주실 수 있나요? 그들은 원유를 가지고 있어요!"
rows["192:252256864"]=" ⁇ 셔는 유명한 케이스로 전 지방에 유명하지만, 이 도시는 여전히 가장 먼저 광산 도시입니다. 광산이 무너지면, 이 도시의 경제는 곧 고통받을 것입니다."
rows["192:337293517"]="대의원회의 투표에서 만장일치로 찬성이라는 결과가 나와야만 람카헨은 네페르세트에 전쟁을 선포할 것이오.$B$B지금으로서는 가능성이 희박하오. 하지만 형도 이제 데스윙의 부하들과는 이성적인 대화가 불가능하다는 사실을 알아야 하오."
rows["192:37061688"]="폭풍술사 우슐레이$B$B그 힘은 곧 하늘, 비, 그리고 산산이 부서진 대지의 힘일지니. 다시 한번 구루바시의 아버지로 군림하기를...$B$B이제 우슐레이는 광란의 경계에서 격노하고 있다."
rows["192:468943831"]="그렇습니다. 지금은 당신의 앞에서 당신이 이해할 수 있는 형상으로 제가 서 있는 것입니다, 필멸자여. 밸라스트라즈라는 이름으로 알려진 용 앞에서 서 있을 용기가 있으십니까?$B$B<크게 웃는 밸란>$B$B그럼 계속 얘기를 할까요?"
rows["192:612330574"]="바로 여기 다크문 페이리가 있을 거야 내가 그 거대한 바그런을 풀고, 모든 텐트를 세우고, 동물원을 세우고, 술들을 쏟아부어 주면, 돌아와!"
rows["192:712866099"]="우리 동료가 지금 줄드락에서 일어나는 문제에 당신을 끌어들이기는 했지만, 근본적으로 우리 잔달라 부족이 여기 있는 주된 이유는 어떤 일이 일어나는지 관찰하고 제국의 멸망을 기록하고자 함입니다."
rows["192:799828481"]="우리는 세 자매입니다. 우리는 나무가 뿌리 내리기 전에 여기 있었고 돌이 던지기 전에 여기 있었고, 산이 먼지로 무너지고 바다가 건조되기도 전에 오래 남아있을 것입니다."
rows["193:1064725223"]="끔찍해... 아주 끔찍해!$B$B황천의 폭풍의 52번 구역에서 오고 있었는데 아무런 이유없이 녀석들이 우릴 격추했지 뭔가! 테로카르 숲으로 빨리 가려는 욕심에 그 지름길로 가는 게 아니었는데!"
rows["193:119530487"]="제 남편이 전쟁터에 나가 있기 때문에 헬렌이 저에게 힘이 돼주었답니다. 그녀의 고운 심성과 뛰어난 검술 실력으로 힘든 시기를 견디도록 도와주었죠. 전 헬렌이 없었으면 어떻게 되었을지 정말 모르겠어요."
rows["193:1366797804"]="<가지고 있는 에펙시스 결정을 바시르 수정괴철로의 움푹 패인 곳에 놓고 레버를 당기자, 장치가 수정을 분해합니다. 몇 분이 지난 후에, 당신의 발 앞에 영약이 나타납니다.>"
rows["193:1416036074"]="적의 피드라임이 당신을 보호한다는 생각에는 대칭이 있습니다. 당신의 가죽 작업 기술을 발전시키기 위해 중간 상승에 있는 썬더 블러프 갑옷병 안에 Una를 찾으십시오."
rows["193:1437476011"]="이 지역에는 아직도 스컬지의 역병이 만연해 있고 역병을 변형시켜 스컬지에 영향을 주기까지는 아직 한참이나 남았습니다. 필요한 재료를 모아 전쟁에 도움을 주십시오!"
rows["193:1509606204"]="아라시 분지에서 포세이큰 파멸단을 도와 아라소르 연맹에 맞서 싸우고 싶으십니까? 좋습니다! 그럼, 마틴 린지에게 도움을 청해야겠군요. 예언의 웅덩이로 가서 찾아보십시오."
rows["193:1522825540"]="롤로가 자신의 소중한 에일 맥주를 흘리거나 옷을 더럽히고 싶어하지 않을 때면 내가 등장하지. 암, 그렇고 말고. 정의를 실현하고 누군가를 응징해야 할 때는 이 노병 한셀을 부른다네."
rows["193:1975961564"]="텔드랏실을 뒤덮고 있는 촉촉한 풀밭도 아주 훌륭한 침대가 될 수 있겠지만 좀 더 편안한 잠자리를 원한다면 장인의 정원에 있는 다르나서스 여관 침대가 제격일 것입니다. 가서 셀리에네를 찾으십시오."
rows["193:232090473"]="<가지고 있는 에펙시스 결정을 바시르 수정괴철로의 움푹 패인 곳에 놓고 레버를 당기자, 장치가 수정을 분해합니다. 몇 분이 지난 후에, 당신의 발 앞에 영약이 나타납니다.>"
rows["193:417787471"]="당신에게 기술을 가르쳐달라는 말입니까? 왜 이러십니까? 안 된다는 거 알면서... 제 기술이 부족해서 가르칠 게 없습니다. 언더시티 연금술 실험실에 있는 포세이큰 학자 허버트 핼시를 찾아가보십시오."
rows["193:579135862"]="자네의 능력이 나를 능가했군. 더 많은 것을 배우고 싶다면 저기에 있는 베나 윈터후프에게 가는 것이 좋을 걸세. 하지만 베나도 쉬어야 하니까 시간을 너무 많이 뺐지는 말게나."
rows["193:76872725"]="멀리 북쪽에 있는 썬더 블러프까지 가셔야겠습니다. 그곳에 도착하면 썬더 블러프 경비병에게 문의하십시오. 당신이 찾는 곳이 어디인지 정확히 알려 줄 겁니다."
rows["193:845777497"]="수없이 많은 곳을 돌아다녀 봤지만 겨울맞이 축제처럼 흥겨운 축제는 본 적이 없습니다. 드워프들의 위대한 도시 아이언포지로 가서 직접 확인해 보십시오."
rows["194:1114731314"]="탐험가 연맹의 배려로 여기 따라올 수 있었어요. 비틀린 숲과 주변 지역이 이렇게 위험한 것을 보니, 도움 없이 혼자 왔다가는 큰일이 날 뻔했군요."
rows["194:1384304988"]="이제, 여러분은 소속 기일을 만들기 위해 서류가 필요할 것이고, 조ンド르 스틸브로는 이 과정을 시작하는데 도움을 줄 수 있습니다. 아이언포지 초보할 준비가 되면 방문객 센터로"
rows["194:1502272987"]="그녀는 내가 같이 가고 싶어했다는 걸 모르는 겁니까? 난 아직 젊습니다. 죽기 싫단 말입니다. 앞으로도 계속 행복하려면 이 방법밖에 없습니다. 그녀에게 이 말을 전해 주십시오. 그리고 알아듣도록 해 주십시오."
rows["194:1626129274"]="탐험가 연맹은 이 세상의 숨겨진 비밀을 밝혀내기 위해 존재해왔다. 대격변은 대부분의 사람들에게 엄청난 피해를 입혔지만, 우리에겐 지금껏 알려지지 않았던 정보와 부를 가져다주었다."
rows["194:1632597206"]="톨 바라드의 바라딘 요새에 있는 우리 형제들은 무척 바빠서 항상 자네를 도울 수는 없네. 그들이 자네에게 준 임무를 언제든지 도울 수 있도록 내가 여기에 배치되었네."
rows["194:1781483431"]="동족과의 우정은 아주 강력한 힘이 될 수 있습니다. 이런 일은 크룸이 도와 줄 수 있지요. 봉우리 하층, 승강기 옆에 있는 썬더 블러프 길드 사무소를 찾아가 보십시오."
rows["194:1902621865"]="뛰어야 벼룩인 게 누구더냐? 물론 너는 우리가 말퓨리온 님에 이어 너까지 소환할 거라고는 생각도 못했겠지? 자, 구원받을 시간이다, 에라니쿠스. 너의 광기와 타락을 정화하도록 하마."
rows["194:1904256260"]="얼라이언스는 이 외딴 오두막을 한동안 지원해 왔소. 우리 사냥꾼과 벌목꾼들이 이용하는 장소였지.$B$B하지만 전쟁이 계속되고 있는 이상, 이제 이곳은 지원 대상이 아니라 군에서 관리하는 곳이라고 생각하는 게 좋소."
rows["194:331175257"]="서풍호에 탄 여러분 모두 환영한다고. 불모의 땅을 가로지를 때 가장 편안하게 여행할 수 있는 비행선이지. 자리에 앉아서 항해를 즐기는 게 어때? 기름 냄새와 기분 좋고 건조한 공기가 이렇게 어우러지는 느낌은 어디에도 없으니까."
rows["194:466446797"]="<초초초에 보면 중년 여성을 볼 수 있습니다. 하지만 그녀의 눈과 그 눈은... 데어드레는 수십 년의 연구와 경험에 의해서만 얻을 수 있는 지혜를 얻었습니다.>"
rows["194:576663324"]="더 이상 가르칠 게 없네. 자네의 기술이 이미 나를 능가했기 때문이야. 썬더 블러프 중앙에서 북서쪽에 있는 상점으로 우나라는 타우렌을 찾아가게. 고급 기술을 가르쳐줄 테니까."
rows["194:634340395"]="네, 정령 넷을 처치하면 문이 열릴 겁니다. 확실해요. 트로그를 조심하세요. 더럽고 짜증 나는 족속입니다. '육체의 저주'에 굴복하지 않았대도 말이죠."
rows["194:651559975"]="이번 명절이 지나가면 분명 이 겨울 할아버지는 다음 해를 위해 새 술을 빚을 준비를 할 거예요. 그러니 여기 이 가방 안에 있는 겨울맞이용 술은 한 방울도 남김없이 모조리 마셔 버려야겠어요."
rows["194:665769838"]="탐험가 연맹은 이 세상의 숨겨진 비밀을 밝혀내기 위해 존재해왔다. 대격변은 대부분의 사람들에게 엄청난 피해를 입혔지만, 우리에겐 지금껏 알려지지 않았던 정보와 부를 가져다주었다."
rows["194:983428967"]="내 작품을 사려면 직접 나를 찾아와야 합니다. 올윈은 종종 다시 생각해 보라고 하지만 아쉬운 건 내가 아닙니다. 주위를 둘러보십시오. 많은 전사들이 내 갑옷에 의지하고 있습니다."
rows["195:1027863831"]="도대체 어디로 갔을까요? 서쪽에 있는 미명 광산에 제 수습생 샤샤리아를 보낸 지 한참 됐습니다. 광석 견본을 빨리 받아야 합니다. 그렇지 않으면 우리 실험은 실패하고 말 것입니다!"
rows["195:1037101536"]="러닝마스터들은 힘을 얻기 위해 피부에 룬을 조각합니다.$B$B이론적으로 멋지지만, 썩는 육지에 넣어야만 합니다!$B$B우리에겐 운이 좋게도 여전히 뼈에 조각을 할 수 있습니다."
rows["195:1058494946"]="음... 제가 가르칠만한 것은 이미 다 아시네요. 이제 다른 스승을 찾아갈 시간입니다. 다르나서스 장인의 정원에 있는 나이트 엘프 에이네실을 한 번 찾아가 보세요. 정말 유능한 나이트 엘프랍니다!"
rows["195:1124600947"]="그래, 성난모래 부족 전설 속의 칼을 찾고 싶다고?$B$B술트라제를위해 피를 묻힐 준비가 되었나? 사막을 가로질러 그 피를 뿌릴 준비도? 강력한 힘이 담긴 보물을 찾아 헤맬 수 있단 말이지? $B$B그렇다면... 사막에 온 것을 환영하네, 친구."
rows["195:1127057832"]="낚시왕 선발대회를 위해 낚시의 대가이신 바스베이트 님이 이곳 수역에 질 좋은 맛둥어를 잔뜩 풀어놓으셨어요!\010\010참, 낚시왕이 뽑힌 후에 맛둥어를 제게 가져오는 분에게는 5마리당 적당한 가격을 쳐 드리지요!"
rows["195:1232296192"]="낚시는 느긋하게 할 수 있다는 점이 장점인 것 같습니다. 지난 일들을 회상한다든가 장래 계획을 세운다든가 생각할 시간이 생기니까 말이에요.$B$B아, 그리고 술 마시기에 아주 좋은 핑곗거리이기도 하지요. 아주 코가 비뚤어지도록 말입니다, 하하."
rows["195:1382922775"]="만사에는 때가 있게 마련입니다. 휴식도 마찬가지입니다. 적절한 시기에 휴식을 취하고자 하는 이들을 위해 여관주인 카우스가 블러드후프 마을 서쪽에서 여관을 하나 운영하고 있습니다. 그곳으로 가보십시오."
rows["195:1568703149"]="자네가 내 앞에 있는 걸 보니 기적이 벌어진 모양이군! 이곳에 감금된 천 년 동안 살아 있는 생명체가 이 방에 들어온 것은 타락한 퀴라지와 실리시드 외에는 본 적이 없다네."
rows["195:1601704217"]="영웅이여, 이 저주받은 신전에서 무슨 일이 있었는지는 모두 알게 될 것입니다. 그리고 모든 사실은 역사에 기록될 것입니다. 아제로스에서 머나먼 황천에 이르기까지 위대한 전설로 사람들의 입에 오르내릴 것입니다!"
rows["195:161627171"]="그대는 재능이 아주 뛰어나군요! 정말로 영감이 좋은 분이에요. 계속해서 더 배울 생각이라면 스톰윈드에 있는 조르지오 볼레로를 찾아가 보세요. 아주 유명하신 분이라 그대를 잘 가르쳐주실 거예요."
rows["195:1763585737"]="그림자가 주장 한 이래로 그늘숲 나는 잠을 못 수 있습니다. 나는 바람에 소리 지르는 유령 소리 때문에 깨어 있습니다. 거의 양떼의 소리처럼 들립니다. 그들은 멈추지 않을 것입니다."
rows["195:1917616353"]="스랄은 자신의 영지에서 머물 수 있게 해 주며 큰 자비를 베풀었다. 나도 언제까지고 그의 환대를 당연하게 여기고 싶지는 않다. 우리 지도자에게 문제를 끌고 온다면 크나큰 불명예일 테니까."
rows["195:1941656245"]="좋은 에르마, 그녀는 몇 년 동안 지역 동물을 돌봐주었고, 당신이 원하는 모든 동물을 돌보는 것을 기쁘게 생각합니다."
rows["195:2038878187"]="가죽에 대한 자네의 지식이 나보다 깊어졌군. 불모의 땅 타우라조 야영지에 있는 크룰무 풀문이라는 타우렌을 만나보는 것이 좋겠네. 자네처럼 재능이 있는 자에게 전해줄 지식이 많으니까."
rows["195:2107281405"]="나와 내 동료는 우리가 아는 가장 치명적인 물질들을 모아 적에게 그 효과를 시험해 보고 있습니다. 필요한 걸 모두 알아내면, 여태 본 적도 없는 무시무시한 역병을 만들어낼 수 있겠지요."
rows["195:235697945"]="세나리온 원정대는 저곳에서 목숨을 잃어가는 날 구해주었답니다. 그들에게 내 생명을 빚진 것이지요! 그래서 전 세나리온 원정대의 친구들에게 마법 용품을 지원하고 수리를 해 드리고 있습니다."
rows["195:303401581"]="근처 오우거들로부터 천둥군주 요새를 빼앗은 지 얼마 되지 않았소.$B$B요새 방어를 도우려고 왔소? 고르드렉이 일손을 구하고 있으니 가보시오."
rows["195:352097686"]="함부로 남의 물건에 손을 대는 건 좋지 않아! 셴툴과 날쌘그림자 결사단이라면 지하에 있는 어둠의 틈에서 찾을 수 있을 거야. 지혜의 골짜기 남쪽에서 그곳으로 내려가는 지하도를 찾게."
rows["195:63304456"]="이 알은 검은용군단의 알에 걸맞게 탄력 있어 보입니다. 많은 수의 에펙시스 결정을 알 옆에 놓는다면, 결정의 진동으로 이 알이 깨질지도 모르겠습니다."
rows["195:656156441"]="악마의 돌진이 점점 질리진 않으신가요? 좀 더 마음에 드는 소환수 이름을 갖고 싶진 않으시고요?\010일정 금액을 지불하시면 제가 당신의 소환수 없애는 일을 도와 드리겠습니다. 새 소환수를 만들 수 있도록 말이죠..."
rows["195:690827386"]="자연을 훼손하는 건 이단이다. 자연의 힘이 파괴적일 때라 할지라도 말이야.$B$B어둠해안을 파괴한 힘은 자연적인 게 아니다. 난 이 땅이 산산이 흩어지도록 두지 않을 것이다."
rows["195:817272263"]="네더스톰은 항상 지금처럼 아니었습니다.$B$B이 무너지는 땅이 파라홀론 평야라고 알려진 시절이 있었습니다. 그 시절 중 거의 이 땅은 악의 지배를 받지 못했습니다."
rows["195:912165809"]="으스러진 손은 검은바위 요새 위쪽 곳곳에 첩자들을 파견할 수 있었지. 정보 수집 절차가 느리긴 했지만 보고 그냥 넘길 수 없는 발견을 했다."
rows["196:1154188181"]="<한숨을 쉬는 카란>$B$B그... 그건 맞는 말인 것 같군.$B$B고르샤크가 말하기를 당신네 대족장이 어떤 큰 계획을 세우고 있다고 하더군. 얼라이언스와 호드 간의 관계를 바꿔 놓을 그런 계획 말이오. 혹시 당신은 알고 있소?"
rows["196:1172607439"]="제 시간을 뺏지 마십시오. 제겐 당신이 살아온 시간보다도 더 오래 연구해 온 과제가 있단 말입니다. 언더시티 연금술 실험실에 있는 박사 마틴 펠벤을 찾아가보십시오. 그 포세이큰이라면 기초부터 가르쳐줄 수 있을 테니까."
rows["196:1202632540"]="질기고 좋은 붕대라면 아르녹이 잘 만들지. 정기의 골짜기, 정기의 오두막 옆 웅덩이에 적자 생존이라는 가게가 있네. 힘의 골짜기에서 위로 이어지는 길을 따라 서쪽으로 가게."
rows["196:1247873501"]="낚시왕 선발대회를 위해 낚시의 대가이신 바스베이트 님이 이곳 수역에 질 좋은 맛둥어를 잔뜩 풀어놓으셨어요!\010참, 낚시왕이 뽑힌 후에 맛둥어를 제게 가져오는 분에게는 5마리당 적당한 가격을 쳐 드리지요!"
rows["196:1349831912"]="내가 초보자였던 것이 까마득한 옛날이기에 당신을 제대로 가르칠 수 없을 것 같습니다. 바로 저기에 있는 타른이나 마크에게 가면 둘 중 하나는 당신에게 도움을 줄 겁니다."
rows["196:1542798209"]="초보자까지 전부 받아들이면 너무 시끌벅적해질 거야. 저쪽에 있는 단 골다스에게 가보게. 좀 감정적이기는 하지만 다 좋은 뜻으로 그러는 걸세. 게다가 아주 잘 가르친다네."
rows["196:1761771133"]="이 드워프는 첩자 임무를 수행하던 중 정체가 발각되어 살해된 것 같습니다. 죽음의 괴철로 수행원들이 모두 볼 수 있는 곳에 시체를 둔 것으로 봐서 침입자들에 대한 경고의 의미로 보입니다."
rows["196:2119574336"]="실버문에 옷감을 기부하시겠다고요?$B$B매타조를 타려고 하시는군요. 잘됐군요... 누이 좋고 매부 좋은 일이죠. 이 도시를 위해 옷감을 좀 가져다주십시오. 제가 그대의 평판이 올라가도록 힘쓰겠습니다."
rows["196:378572581"]="폭풍술사 우슐레이.$B$B하늘과 비, 갈라진 대지의 힘이 그녀의 것이다. 언젠가 다시 구루바시의 어머니로 군림하기를.$B$B우슐레이는 이제 광기의 끝자락 가까이에 머물고 있다..."
rows["196:631634519"]="그레이스키에 오신 것을 환영합니다.$B$B이런 도시가 거의 없죠. 필요한 만큼 머물게 되죠. 우리는  ⁇  카자드의 최고의 윈드스웨이프 치즈와 염소 고기를 가지고 있습니다."
rows["196:719671828"]="흐음... 당신은 꽤 실력이 있는 것 같군요. 정말로 배우고 싶으시다면 넘지 못할 벽이란 없겠죠! 앞으로 길고도 보람으로 가득 차게 될 여행의 첫걸음은 제가 안내해 드리겠어요."
rows["197:1231075678"]="이제 그대는 좀 더 숙련된 스승에게 배울 때가 되었습니다. 페랄라스의 페더문 요새에는 킬란나 윈드위스퍼라는 나이트 엘프가 살고 있답니다. 그녀는 지력이 대단하니 그대에게 많은 것을 가르쳐 줄 수 있을 것입니다."
rows["197:1303069588"]="우리는 드루이드로서 자연의 조화를 지킬 임무가 있습니다. 제 삶은 이를 거역했지요. 저의 어리석음이 혼돈을 자아내었으니, 더 널리 퍼지기 전에 돌연변이 작물을 거둬들여야 합니다."
rows["197:1328615272"]="첫 번째 도전에 임하려면 은빛십자군 전투마에 올라야 합니다. 이 원형경기장의 벽을 따라 서 있는 은빛십자군 전투마들이 보이실 겁니다.$b$b자, 전투마에 오르세요. 그리고 제게 말을 거시면 도전을 진행할 수 있습니다."
rows["197:1387823766"]="만약 당신이 정말로 그 후진들과 대화를 나누고 싶으면,"
rows["197:1422667943"]="<고개를 돌리며 미소를 짓는 알트루이스>$B$B보지 못한다네.$B$B<비룡 네스란다무스를 가리키는 알트루이스>$B$B저 괴철로 기지에서 저들이 만들고 있는 물건이 완성되기 전에 막아야 하네."
rows["197:1625579058"]="이곳에 여러 개의 전단이 붙어 있는 것이 눈에 띕니다.$B$B하지만, 자세히 보니 당신이 직접 이 일을 맡기에는 무리가 있는 것 같습니다. 나중에 다시 확인하는 게 좋겠습니다!"
rows["197:19887001"]="우리는 원래 그렇게 무례한 사람들이 아닙니다. 모두 우서 경의 도착에 맞춰 모든 걸 완벽하게 준비해 놓으려고 바삐 움직이다 보니 그런 것뿐이죠. 빛의 수호자 우서 경이 마을에 오는 게 자주 있는 일은 아니거든요."
rows["197:2029758034"]="어둠을 사랑하여 도적의 길을 가려는 자들도 있지만, 진정으로 밤의 품에 안길 수 있는 건 우리 나이트 엘프뿐이랍니다. 그늘진 길을 걸어나가실 생각이시라면 세나리온 자치령에 있는 시우르나를 찾아가십시오."
rows["197:2042858053"]="우리는 모든 연령대의 사람들이 게임을 즐길 수 있도록 하고 싶습니다.$b$b링 투스는 움직이는 거북이의 뒷면에 반지를 내리는 간단한 게임입니다.$b$b내가 좋아하는 게임 중 하나죠."
rows["197:389413383"]="달라란 북동쪽, 선리버 성소의 호드 지구에 있는 불결한 야수 여관을 찾고 계시군요.$B$B약간 소박한 곳이지만 부엌에 대단한 전문 요리사들이 있다고 들었습니다."
rows["197:636231997"]="이 차원문은 아제로스로 연결된 다른 문과는 다릅니다. 차원문을 유지하려면 더 많은 마나 저장기가 필요하지요.$B$B마나 저장기를 계속 보충하지 않으면 쿠엘다나스 섬과 태양샘으로 가는 길을 포기할 수밖에 없습니다."
rows["197:815530990"]="어떤 사람들은 타우렌이 별명이라고 불릴 자격이 없다고 생각하지만 타우렌은 밤 엘프들이 엘우네를 부르는 것과 같은 존재를 숭배한다는 것을 이해하지 못합니다."
rows["197:898920057"]="박사님 걱정은 하지 마세요. 그냥 지금 잠깐 풀이 죽어 있는 것뿐이니까요.$B$B대격변이 왜 하필 지금 찾아왔을까요? 호바트 박사님이 불쌍해요. 저 멋진 초소형 기계닭을 완성하기 직전이었거든요."
rows["198:1280789648"]="노움 녀석들이 아니었다면 이런 난장판이 벌어지지 않았을 거야!$B$B노움들이 만든 영토 확장 장치를 비롯한 말도 안 되는 기기들이 대격변의 원인이란 건 이미 기정사실이지!"
rows["198:130381507"]="오그리마, 명예의 골짜기에 사는 사요크와 하나시라는 무기 전문가들에게서 활 쏘는 법을 배울 수 있지. 실버문의 원정순찰대 광장에 있는 무기 전문가, 일레다가 활쏘기라면 둘째 가라면 서러운 실력을 자랑하지."
rows["198:1735931452"]="우리가 스컬지를 제압하고 있습니다. 변형된 역병의 효과는 적어도 만 하루 동안 더 지속될 것입니다! 하지만 계속해서 우세를 유지해야 하니 기회가 오면 꼭 가마솥 하나를 파괴해 주십시오."
rows["198:1864349228"]="라그나로스는 썬더란 님의 남은 정기를 정령을 봉인하는 부적에 넣은 다음 완벽하게 이등분했습니다. 그러곤 그 조각들을 자기 부관에게 나누어 주었습니다."
rows["198:1936663408"]="오우거들은 호드와 한편이 돼서 우리와 함께 일할 수도 있을 텐데 왜 그렇게 사막에 주저앉아서 허송세월만 보내는 건지 도무지 모르겠어요.$B$B제 말은, 이 오우거들을 보세요! 우리가 저 친구들을 이용하지 않으면 누가 하겠어요?"
rows["198:315103837"]="가죽에 그대의 의지를 강요하려고 하지 마십시오. 대신 가죽의 자연적 성향을 판단해 어떤 형태로 만들어 어떤 기능을 하도록 할지 생각해 보십시오. 가죽을 세공하는 일은 전쟁이 아닙니다. 가죽을 이기려 들지 말고 가죽과 함께하십시오."
rows["198:350232164"]="토륨 대장조합 가을 품목:$B$B이 시대의 모험가를 위한 각종 용품을 아주 저렴한 가격에 제공하고 있습니다! 찾기 힘든 재료를 어디서 구해야 하는지도 설명해 드립니다."
rows["198:412835683"]="세 명의 무기 전문가에게서 단검 사용법을 배울 수 있지. 언더시티의 군사 지구에 있는 아키발드, 오그리마 명예의 골짜기에 있는 사요크, 실버문의 원정순찰대 광장에 있는 일레다 중에서 마음에 드는 스승을 찾아가게."
rows["198:527199645"]="여기 블러드하프 마을에는 알케미 트레이너가 없지만 북쪽에는 썬더 블러프에 있는 트레이너가 있습니다."
rows["198:540173257"]="침착하시오, 친구. 지금 장군이 온다고 했소?$B$B드디어 전리품을 챙길 기회가 왔군! 난 경비병들을 혼란에 빠뜨리겠소. 하지만 호손을 처치하는 건 당신의 몫이오. 공격할 준비가 됐소?"
rows["198:57075883"]="같이 지내게 된다면 좋겠지만 현실을 직시하자고. 자넨 나보다 물약 제조 경험이 더 많잖나. 더 많은 것을 배우고 싶으면 언더시티 연금술 실험실에 있는 포세이큰인 학자 마쉬를 찾아가게."
rows["198:653173879"]="실버문의 원정순찰대 광장에 사는 블러드 엘프, 일레다가 제자들에게 한손 검과 양손 검 쓰는 법을 가르치지. 언더시티의 무기 전문가, 아키발드한테 가도 배울 수 있어. 군사 지구로 가보게."
rows["198:695466004"]="아티쉬, 수호자의 지팡이 말이오. 그 지팡이는 수 세대에 걸쳐 티리스팔의 수호자에게 전해져 왔소. 그 지팡이가 살게라스에게 오염됐소이다. 최후의 수호자, 메디브의 지팡이가 말이오."
rows["198:92013091"]="실버문의 원정순찰대 광장에 사는 블러드 엘프, 일레다가 제자들에게 한손 검과 양손 검 쓰는 법을 가르치지. 언더시티의 무기 전문가, 아키발드한테 가도 배울 수 있어. 군사 지구로 가보게."
rows["199:1094214951"]="거기! 스팀휘들 결투 대회라고 들어는 봤나?\010\010가젯잔이나 나그란드, 그리고 칼날 산맥의 투기장 밖에서 투기장 팀 창단허가서를 파는 투기장 조직위원을 찾을 수 있다고."
rows["199:1104769133"]="발린다 스톤하스 부대장은 투쟁의 벌판 북쪽에 있는 돌난로 전초기지를 본거지로 최전선에서 얼라이언스 군을 지휘하고 있습니다.$B$B발린다 부대장은 현재 돌난로 전초기지에 있습니다."
rows["199:1162897361"]="오그리마에 있는 명예의 골짜기로 가시오. 그곳에서 그녀는 남편과 두 딸이 함께 살고 있소. 실력이 뛰어난 대장장이는 많지만, 정령들이 말하길 당신을 가장 잘 지도할 사람은 그녀뿐이라는군."
rows["199:1291257705"]="예, 얼마나 신중한지, 빵 한 잔 먹은 후 항상 기분이 좋아지죠. 그 빵은 그가 만든 게재 때문이라고 생각합니다."
rows["199:1549188630"]="난 관찰 중이다. 여기서 운고로를 감시하는 게 내 일이지.$b$b그와 동시에 실험을 하고 그 결과를 기록하기도 한다. 이 실험을 통해 내 흥미를 끄는 걸 관찰할 수 있지."
rows["199:1712933627"]="가시덤불 골짜기의 네싱워리라는 친구 이야기는 들어본 적이 있지. 재미로 모든 동물을 잡는다는 그 친구 말이야.$B$B단지 재미로라... 이 친구 진짜 멍청하지 않나? 안 그래? 이익을 모두 땅바닥에 내버린다고 생각해 보라고!"
rows["199:1752543179"]="이시엘은 아웃랜드로 진출하는 과정에서 적의 저항이 있을 거라 예상했습니다. 그래서 우리 감시자들이 함께 원정에 참여한 것이지요.$B$B우리는 나가가 그 정도의 힘과 숫자로 우리에게 맞서리라고는 예상도 못했습니다."
rows["199:1854379550"]="비행 조련사를 찾을 수 있는 상업 지구 끝자락의 그리핀 횃대를 아십니까?$B$B와일드해머 드워프 둘이 그곳에서 모여 그리핀 비행 요금을 받습니다. 게다가 그들이 당신에게 짐승을 탈 수 있도록 훈련시켜줄 수도 있지요."
rows["199:1935088076"]="우리 상황이 그렇게 나쁘다고는 생각 안 해요. 조만간 전부 나아질 것이고 태양샘의 힘도 회복될 겁니다. 모두 입을 모아 말하는 나쁜 일은 없을 거예요."
rows["199:2080266794"]="이곳 숲의 노래에서 다른 이들의 목소리를 다시 듣게 되어 기쁘군요. 제가 후손들이 타락하기 전 이 땅을 처음 발견했던 칼도레이의 마지막 종족이 되는 것은 아닐까 하고 걱정했었습니다."
rows["199:448680032"]="자네에겐 더 이상 가르칠 지식이 없네. 아치길을 지나 동남쪽 경사로 밑으로 가서 학자 허버트 핼시를 만나 보게. 그 친구가 자네에게 전문 기술을 가르쳐 줄 포세이큰일세."
rows["199:808775233"]="당신, 무슨 일을 꾸미고 있기에 그런 작자의 도움이 필요한 건가? 그렇지 않아도 저 건너 쓸쓸한 뒷골목에 있는 훌프단 블랙비어드란 도적 때문에 골치를 앓고 있는데 당신도 내 감시 대상에 추가해야 하나?"
rows["19:1125580008"]="오, 예언의 영웅께서 제 가게에 들려주시다니 영광이네요! 뭘 도와드리면 될까요?"
rows["19:112990958"]="투덜 투덜..."
rows["19:1193733923"]="절 찾고 계셨습니까?"
rows["19:1232966243"]="이제 다 끝났어?"
rows["19:1309613724"]="... 항상 지켜본다고!"
rows["19:1422662663"]="어떻게 도와드릴까요?"
rows["19:1506970197"]="대장기술로 처리해야 할 거라도 있으신가?"
rows["19:1579951873"]="보급품이 필요하십니까?"
rows["19:1606464270"]="호드의 영광이 있으소서"
rows["19:1611385671"]="어떤 종류의 방어구 상인을 찾으시나요?"
rows["19:249401383"]="지금 바쁘네요"
rows["19:437379656"]="스톰파이크에 죽음을!"
rows["19:49178456"]="네? 무슨 일이라도?"
rows["19:545746627"]="크레스트가 보낸 거요?"
rows["19:645055071"]="우리 아빠 알아?"
rows["19:668910532"]="즐거운 시간 보내고 계신가요?"
rows["19:669976810"]="블러르그 아우러르글 므르르?"
rows["19:671388087"]="그쪽은 잘 되어 가오?"
rows["19:72362129"]="넌 드루이드 아냐!"
rows["19:783081346"]="서리늑대 부족에게 죽음을!"
rows["19:818928817"]="무엇을 도와드릴까요?"
rows["19:840130850"]="여기 좀 쌀쌀하다."
rows["19:846540426"]="여기 있습니다, 사령관님."
rows["19:87311858"]="이동 수단을 찾고 계십니까?"
rows["200:1140339622"]="자네는 이미 내 능력을 능가하는군. 대지모신의 축복을 등에 업고 전진하게. 썬더 블러프 중앙에서 북서쪽에 있는 갑옷 상점으로 가서 타른이라는 타우렌을 찾아. 그의 지혜의 인도를 구하게나."
rows["200:1354374362"]="산양 경주는 가을 축제의 멋진 전통 행사랍니다. 더 자세히 알고 싶다면 산양 우리 옆에 서 있는 폴 앰버스틸과 얘기해 보시죠. 흥겨운 시간이 되실 겁니다. 게다가 말입니다, 산양 경주는 가을 축제 상품 교환 동전을 구할 수 있는 절호의 기회거든요!"
rows["200:1484348538"]="<가지고 있는 에펙시스 결정을 지옥 수정괴철로에 놓고 레버를 당기자, 괴철로의 장치가 이 세상의 것이 아닌 소리를 내면서 결정을 갈아 가루로 만듭니다. 몇 분이 지난 후에, 장치의 기계 입에서 영약이 튀어나옵니다.>"
rows["200:1636529351"]="자넨 어떨지 몰라도, 난 폐허 밑에 묻힌 무한한 원자재가 정말 너무나 아깝다고!$B$B이 동굴에서 허접스러운 폭탄이라도 만들어 뭘 좀 뜯어낼 수나 있을지!"
rows["200:176993046"]="조상님께서 무덤 속에서조차 편히 쉬지 못하시는 걸 보니 참으로 괴롭습니다.$B$B전투사령관 스틸조의 저주받은 유령은 반드시 물리쳐야 합니다. 이 성스러운 땅에 짐마차를 끌고 들어온 어리석은 자의 유령 말입니다."
rows["200:1825224562"]="장비를 만드는 실력이 꽤 쓸만하군. 훌륭해... 오크의 고향, 오그리마로 가서 사루 스틸퓨리라는 대장장이를 찾게. 오크에게도 한 가지 인정할 게 있다면, 바로 죽음의 도구를 썩 잘 만들 줄 안다는 거지."
rows["200:1896160671"]="방사선?!$B$B아니, 자넨 그 일에 신경 쓸 거 없다고! 젠장, 요즘은 다들 그렇게 믿고 있더군.$B$B그건 그렇고 여기 공정에 대해 어떻게 생각하나? 그럼, 최신식이지! 믿어도 좋아."
rows["200:2022407060"]="놀라워. 자네의 물약은 내 물약과 비교해도 손색이 없군. 더 가르칠 것이 없네. 하지만 슬픔의 늪, 스토나드로 가서 최신 실험으로 유명한 로그바라는 오크를 만나 보게."
rows["200:2063045653"]="나가들이 물을 사적인 용도로 쓰기 위해 모조리 뽑아내고 있습니다. 그 여파로 수많은 생명체들이 멸종하고 있죠.$b$b우리가 손을 쓰지 않는다면 이 죽어가는 땅에 생명이라곤 영영 찾아볼 수 없을 것입니다."
rows["200:210796840"]="그림누르 스톤브랜드는 타우렌만한 물고기를 낚았다고 허풍을 곧잘 늘어놓곤 하지만, 그래도 낚시 솜씨 하나는 알아준답니다. 그 친구, 쓸쓸한 뒷골목에서 여행용 낚시용품점이라는 가게를 하고 있습니다."
rows["200:240253917"]="<대대 타우런은 당신 을 향해 뒤돌아 가는데, 그 의 거대한 팔 은 순진 히 일 하고, 흰 옷 의 커튼 을  ⁇ 고 있다. 그 의 손가락 은 그 크기에 있어서 놀랍도록 능숙 하 고, 거미 의 다리 처럼 그 에  ⁇ 다.>"
rows["200:250236519"]="주의해야 합니다, 필멸자여. 이 요새의 하급 부족이 그런 물건을 가지고 있는 경우는 매우 드물기에 수십 년 동안 탐색을 해야 할지도 모릅니다. 인정사정 볼 것 없이 이 야수들을 처치하는 것이 좋을 것입니다."
rows["200:289795140"]="첫 번째 도전에 임하려면 은빛십자군 전투검은늑대에 올라야 합니다. 이 원형경기장의 벽을 따라 서 있는 전투검은늑대가 보이실 겁니다.$b$b자, 전투검은늑대에 오르세요. 그리고 제게 말을 거시면 도전을 진행할 수 있습니다."
rows["200:484714315"]="여기에는 악명 높은 범죄자들과 사악한 생물들에게 현상금이 걸려 있다는 게시물이 붙어 있습니다. 이 현상금을 노리기에는 지금 당장은 너무 위험한 것 같습니다. 나중에 다시 확인하는 게 좋겠습니다."
rows["200:510599071"]="전쟁에서 죽은 이들을 추모할 기념비를 세울 자금을 마련하고 있어요. 승리를 위해 목숨을 희생한 이들을 잊어서는 안 되죠.$B$B현재까지 총 자금의 $3275w 퍼센트를 모금했답니다."
rows["200:605773725"]="거기! 스팀휘들 결투 대회라고 들어는 봤나?\010가젯잔이나 나그란드, 그리고 칼날 산맥의 투기장 밖에서 투기장 팀 창단허가서를 파는 투기장 조직위원을 찾을 수 있다고."
rows["200:692709058"]="내 애완 개구리 줍줍이 사라졌어. 검은무쇠 맥주를 정말 좋아해서 그거만 마시는 녀석인데... 그런데 그 맥주는 정말 구하기가 너무 어려워! 맥주가 다 떨어지니까... 그 맛을 찾아서 도망친 게 틀림없다고!$B$B꼭 다시 돌아왔으면 좋으련만..."
rows["200:723184379"]="<나루에게 다가가자 부드러운 빛이 당신의 온몸을 감쌉니다. 나루는 아무 말도 없지만 당신의 마음속에서는 천천히 음악이 울려 퍼지고 안전함이 느껴집니다. 샤트라스에서 당신을 환영하고 있음을 알 수 있습니다.>"
rows["200:768984813"]="어떠세요? 이 방어구가 제 짙고 서글서글한 눈매를 더욱 돋보이게 하는 것 같지 않습니까? 저를 척 보면 몇 가지 기술 정도는 가르쳐 줄 만큼 솜씨가 뛰어나다고 생각이 안 드십니까? 그러니 제 말을 귀 기울여 잘 들어 보십시오. 아셨죠?"
rows["200:790549304"]="빛의 결사단이 뭐냐고? 음... 우리는 뼛속까지 철저한 은빛십자군의 일원이오. 모두 도덕이나 죄의식, 쓸데없는 인간의 감정 따위에 결코 흔들리지 않소이다."
rows["200:917837061"]="글릭스와 난 서로 이해관계가 있지. 글릭스는 나에게 물품을 공급해 주고 나는 글릭스를 부자로 만들어 주거든. 농담은 그만하고! 그 해적놈이 쭈글쭈글한 왕꽃잎풀을 쥐방울만한 주머니에 넣어 주면서 돈을 얼마나 많이 달라고 하는지... 다 큰 고블린도 울 정도라니까."
rows["200:944841025"]="매우 친절한 분이시군요. 그런데 우리에게 필요한 비단 붕대는 모두 모은 것 같군요. 이 근처에서 다른 물자를 수집하는 곳에 도움이 필요한지를 알아보시는 것도 괜찮을 것 같습니다."
rows["200:953426855"]="<가지고 있는 에펙시스 결정을 지옥 수정괴철로에 놓고 레버를 당기자, 괴철로의 장치가 이 세상의 것이 아닌 소리를 내면서 결정을 갈아 가루로 만듭니다. 몇 분이 지난 후에, 장치의 기계 입에서 영약이 튀어나옵니다.>"
rows["201:1017516030"]="나를 찾아와 가르쳐 달라고 하다니 뻔뻔스럽기 짝이 없군. 아치길을 지나 동남쪽 경사로 밑으로 가서 박사 마틴 펠벤을 만나 보게. 그 친구가 자네를 기초부터 가르쳐 줄 포세이큰이라네."
rows["201:1106827039"]="새로 온 제자인가? 멋지군. 이래서 라이던은 관리자로 칭송받고 난 여기 처박혀서 교습이나 하는 거겠지. 또다시 올해의 최우수 강사로 선정되는 날에는 민망해서 얼굴도 못 들고 다닐 거야!"
rows["201:1167918098"]="처음 상점을 연 게 마법 지구였는데 그쪽은 좀 시끄럽더군. 그래서 자리를 옮겼는데도 끈질기게 나를 쫓아다니며 제자로 받아달라는 이들의 발걸음은 끊이질 않았어. 어쩔 수 없이 그들을 막아야 했지. 이제는 아주 조용해진 편이라네."
rows["201:1440882587"]="안녕하세요. 저희 하늘경비대에서 좋은 평판을 얻으면, 스키실 산맥에 있는 저희 기지인 검은바람 비행기지로 바로 보내드릴 수 있답니다.$B$B제 어여쁜 황천의 가오리가 맘에 드시나요? 사랑스러운 녀석이죠."
rows["201:1443587000"]="이 마을을 보호하는 돌벽과도 같이 차가운 벽 안에서도 평온을 찾을 수는 있답니다. 마음의 균형을 찾아 자신의 내면을 살펴본다면 사실 어디에서나 평온을 찾을 수 있습니다."
rows["201:1599372990"]="자신이 좀 멋지다고 생각하죠. 안 그래요, 풋내기씨? 투기장에서 실력을 발휘했다면 제가 드릴 게 좀 있죠. 좋은 물건이고 말고요, 크릭셀씨 물건하고는 차원이 다르단 말이에요. 크릭셀씨 물건은 한물갔다는 거, 알고 있죠?$B$B아, 어쨌든 오늘 하루 득템하시라는 말이에요."
rows["201:1788538567"]="남편이 며칠째 행방불명입니다. 저희는 성지를 순례하던 중이었는데 함께 순례를 마칠 계획이었지요.$B$B제가 너무 걱정한 나머지 마나 수정을 지나치게 자주 사용했군요."
rows["201:1832136744"]="2년마다 경쟁의 영들이 더욱 열렬해지고... 그리고 지금 그 시간입니다! 우리는 이 타바드를 싸움을 위해 대전 현장에 입습니다."
rows["201:1858518275"]="우리가 운고로 분화구에 머무르기 시작하면서, 다단가는 이곳에서 자라나는 붉은꽃잎덩굴손 씨눈에 맛을 들였어요.$B$B누군가 좀 모아서 가져다주면 우리 다단가에게 좋은 간식이 될 텐데..."
rows["201:1864234165"]="마법불꽃 재봉술을 취소하는 것은 그리 간단한 일이 아니랍니다. 마법불꽃 재봉술을 취소하면 마법불꽃 재봉술에 관련된 모든 제조법 또한 사라집니다!$B$B정말 취소하시겠습니까?"
rows["201:1879930263"]="당신은 아주 괜찮은 마법부여사로군요! 이제 실력을 더 발전시킬 때가 됐습니다. 위층으로 가서 김블 시슬퍼즈와 얘기해 보는 게 좋겠군요. 좀 괴짜 같은 친구지만 지금부터 당신을 제대로 가르쳐 줄 겁니다!"
rows["201:1895811398"]="안녕하십니까, 여러분! 로데론 최고 악단의 공연을 감상하십시오. 주인님과 주인님의 손님들을 위해 공연을 하게 된 것을 대단한 영광으로 생각합니다. 자, 곧 공연이 시작된다고 하니 관람석에 자리를 잡아 주시기 바랍니다."
rows["201:1899077253"]="내게 배울 건 별로 없을 걸? 이미 많은 걸 알고 있잖아. 더 많이 배우고 싶다면 썬더 블러프 중앙에서 북서쪽 상점에 있는 우나라는 타우렌을 찾아가 봐. 가는 김에 내 안부도 좀 전해주고. 알았지?"
rows["201:329696955"]="우리의 소중한 도시를 지키는 용맹한 파수꾼들은 대다수가 실단나이르로부터 훈련을 받았습니다. 그녀라면 틀림없이 그대를 전사로 키워줄 수 있을 테니, 도시의 입구 부근에 있는 전사의 정원에서 그녀를 찾아보시기 바랍니다."
rows["201:34030956"]="<노예가 되어 이미 무감각해진 오타 원의 눈이 당신의 제안에 더욱 거슴츠레해집니다. 당신은 다르톨의 마법봉의 힘이 당신을 통해 펄볼그에게 세차게 흐르기 시작하는 것을 느낍니다.>$B$B일어나다니?"
rows["201:477257989"]="아, 네, 그... 그 이름요. 글쎄요... 사람들 말로는, 명성은 선의와 마찬가지로, 쌓을 때는 노력을 많이 해야 하지만 무너지는 건 한순간이라고 하더군요. 어떻게 그런지, 또 왜 그런지까지 아실 필요는 없겠지요. 제가 그런 이름을 갖게 된 사연은 그냥 이 정도에서 끝냅시다."
rows["201:699040064"]="이곳 아즈샤라에서 보낸 날들이 그렇게 영광스럽고 좋았던 것만은 아니지만, 우린 아직 젊고 몸속에는 아직도 뜨거운 피가 흐르고 있소. 그러니 우리는 꼭 승리할 수 있을 거요. 승리는 시간문제일 뿐이오."
rows["201:791743428"]="화산이 폭발할 때 무역왕 갤리윅스가 그대 친구들을 포로로 데려갔지.$B$B그들을 구출해서 이 섬을 떠나려면 얼라이언스를 빨리 처리해야 해."
rows["201:820676851"]="정말 전장에서 몸을 부딪치며 싸우기가 싫습니까? 뭐, 그편이 안전하긴 하겠지만, 정녕 손가락이나 까딱 까딱거리는 법을 배우고 싶다면 썬더브루 양조장에 있는 마지스 스파크맨틀과 얘기해 보는 게 제일 나을 겁니다."
rows["201:829528148"]="<산악인  ⁇ 의 집중은 그의 총의 시야에서 흔들리지 않는 상태로 남아 있습니다. 진지한 가혹한 마스크, 그의 움직임의 측정된 평온과 함께, 그의 공예의 진정한 전문인으로서 그를 나타냅니다.>"
rows["201:842725147"]="마법의 뒤안길에서 나가는 방법은 세 가지가 있답니다. 동쪽과 서쪽 위로 이어지는 경사로로 올라가거나, 달라란의 아래쪽에서 벗어나는 굴로 가는 방법입니다.$B$B물론 굴로 가기 전에 날아가도 된답니다."
rows["201:895822848"]="우리를 옭아맨 족쇄를 부수고 다시금 자유로운 오우거로 살아가려면 반드시 그룰의 아들들을 없애야만 하네.$B$B우리의 비밀 저항 운동이 성공하려면 조용하지만, 신속하게 모든 일을 처리해야 해."
rows["201:916731676"]="이 숙녀분께 말을 걸어보려고 애쓰던 중이었는데 안 보이셨나요? 뭐, 괜찮습니다. 어차피 오늘 밤 선약이 있는 듯하니까요.$B$B저는 국산과 수입품 포도주를 모두 판매하는 데 최고급이 아니면 취급하지 않습니다. 한 번 보시겠습니까?"
rows["202:1151541519"]="검은용과 같이 있어 불편한가요?$B$B좋아요. 그래야 정상이지요. 이 용들도 불편해하기는 마찬가지예요. 그러면서도 과거의 미덕에 매달리느라 여기서는 감히 날 공격하지 못하고요.$B$B우둔한 것들."
rows["202:1329327677"]="톨그림, 네 서비스로 가 봐요, 니벨란에서 더 좋은 가격을 찾을 수 없을 거라고 확신합니다.$b$b다른 상인들이 문을 닫거나 떠나서도  "
rows["202:144093445"]="스윙워터는 그늘샘어, 어, 어, 그 물고기는 맛이 좋고, 희귀하고, 매우 소중합니다."
rows["202:1573129760"]="힘이 최고조에 달한 루비 비룡은 희생을 사용하여 잠시 동안 적의 모든 마법을 자신에게 향하도록 하여 아군을 보호할 수 있습니다. 교묘한 회피는 희생을 사용하는 중에도 계속 사용할 수 있지요.."
rows["202:1639278198"]="<길가에서 발견한 불행한 병사는 긴 칼로 난도질당한 모습입니다. 당신은 시체를 이리저리 살펴보다가 이빨 자국을 발견합니다.>$B$B<야생 동물의 소행일까요?>"
rows["202:1808372919"]="나도 많은 것을 알고 있지만 그대의 지식 수준은 나와 견줄 만하군요. 기술을 더 연마하고자 하는 마법부여사들은 아조라의 탑으로 간다고들 하죠. 그곳에 키타 파이어윈드라는 대가가 살고 있어요."
rows["202:2072090032"]="아, 조카스테처럼 훌륭한 사냥꾼이 있는 다르나서스로 오셔서 다행이군요. 그녀는 세나리온 자치령에 있으니 찾아가서 사냥꾼의 기술을 배우시기 바랍니다."
rows["202:24251643"]="북쪽에 있는 거대한 도시 썬더 블러프에 와이번 조련사가 한 명 있습니다. 썬더 블러프 밑에서 승강기를 타고 꼭대기로 올라가 썬더 블러프 경비병에게 더 자세히 길을 물어보십시오."
rows["202:404053245"]="원한 카드 한 벌을 완성한다면, 앙갚음의 다크문 카드를 보상으로 받게 될 겁니다. 이 카드를 착용하고 있는 동안은 당신을 공격하는 누구든 성스러운 복수로 고통받게 될 겁니다!"
rows["202:423511682"]="블러드 엘프들이 살아남으려면 그대가 계속 우리를 도와주셔야 합니다! 다 같이 전력을 쏟아야 우리가 처한 어려움을 타개할 수 있습니다.$B$B일할 준비가 되었으면 시작해 봅시다."
rows["202:464076542"]="한때 안전한 타우라조 야영지에서 젊은 사냥꾼들에게 야생의 방식을 가르친 적이 있네.$B$B지금은 그와 같은 사치를 누릴 수 없네. 문 앞에 진을 친 적과의 전투, 그 열기 속에서 기술을 계속 익혀야 할 것이네."
rows["202:500763173"]="이런 속담이 있지. \"물고기를 잡아주면 하루밖에 못 먹이지만 낚시하는 법을 가르쳐 주면 평생을 먹일 수 있다.\" 물론 당신은 그 생선을 요리하고 싶겠지? 요리야말로 내 전공이라고 할 수 있소."
rows["202:505668773"]="너랑 의논을?$B$B<로락스가 껄껄 웃습니다.>$B$B네가 도움이 되리라고는 생각하지 않아.$B$B나는 이 폐허 속에 서서 꿈을 꾸지. 언젠가 고랄루크 앤빌크랙이라는 비열한 도둑놈을 잡는 꿈.$B$B우린 계약을 맺었지. 그런데 녀석은 약속을 깨뜨려버렸어."
rows["202:620904297"]="아에시나 님은 우리의 기도에 아무 대답이 없으세요. 라그나로스의 불타는 하수인들은 우리를 벼랑까지 내몰았고요. 여기서 그들을 멈추지 못한다면, 세계수는 큰 불길에 휩싸인 한낱 그루터기와 다를 게 없어요."
rows["202:739703566"]="샤렌은 도시 안에서 동물들을 돌보고 그들의 주인들이 그들의 삶을 계속 망쳐가는 동안 그들을 미쳐버리는 것을 막고 있습니다. 그녀는 포경관의 홀 바로 바깥에 있는 파스트라이더스 광장에서 서 있습니다."
rows["202:771018115"]="어느 안전에서 감히 가르쳐 달라는 겁니까? 뭘 바라고 온 거예요? 이 답답하고 얼빠진 촌놈 같은 양반. 은엽수 덤불 사용법이라도 배우겠다는 겁니까? 당장 나가요! 아까운 시간을 낭비하게 한 대가로 신나게 두들겨 맞지 않은 것만 해도 다행인 줄 아십시오!"
rows["202:839355997"]="제 능력을 인정하시니 기쁘지만 당신은 이미 제 능력을 앞질렀습니다. 다르나서스 장인의 정원으로 가셔서 나이트 엘프인 에이네실을 만나시면 그녀가 당신을 도와줄 것입니다."
rows["202:932077990"]="내가 모는 비행선은 아제로스에서 제일 근사한 거야. 예전엔 쌍등포에다 도시 하나쯤은 가루로 만들만한 폭탄까지 싣고 다녔었단 말이지... 이 비행선 그림자가 비치기만 해도 적군들은 혼비백산해서 도망갔을 정도라고.$B$B뭣이라? 당연히 사실이고 말고!"
rows["202:985142836"]="스컬지와 아마니 트롤 같은 외부의 문제를 극복하려면 먼저 내부의 문제부터 해결해야 하오. 버림받은 자들 때문에 아주 오랫동안 골머리를 앓고 있었지. 이제 놈들을 정리할 때요."
rows["203:1148988454"]="데스윙이 돌아왔습니다. 그는 그림 바톨과 고원의 여러 지역을 손에 넣었지요. 데스윙을 막기엔 제가 너무 약하다는 자괴감이 들 정도입니다.$B$B곧 우리 여왕님께서 도착하실 겁니다. 그리고 우리는, 한때 대지의 수호자였던 그자를 물리칠 것입니다."
rows["203:1232372846"]="다르나서스의 전사의 정원에 있는 나이트 엘프 무기 전문가인 일예니아 문파이어나 아이언포지의 잘나가는 무기 상점에 있는 드워프 무기 전문가 불리위프가 장착 무기의 사용법에 대해서 가르쳐 줄 겁니다."
rows["203:126967225"]="던 발다르는 알터랙 계곡에서 얼라이언스의 위력이 가장 강한 지역입니다. 계곡의 북쪽에 자리 잡고 있는 던 발다르는 남쪽으로 진격하기 위한 중간 거점이라고 할 수 있습니다.$B$B던 발다르는 안전합니다."
rows["203:1415761307"]="약초, 약초라. 어디 봅시다. 오, 그렇군요. 여기 있네요. 지금까지 모은 것을 보면 갈래물풀은 $2048w개 중 $2047w개, 보라 연꽃은 $2055w개 중 $2053w개, 그리고 아서스의 눈물은 $2058w개 중 $2057w개입니다."
rows["203:1473193733"]="강철의 영혼은 나보다 당신을 더 마음에 들어 하는 것 같소. 나는 아직도 그들의 소리를 듣지 못했지만 당신은 잘 배운 모양이오. 가서 카른과 얘기를 해 보시오. 자기처럼 영혼의 소리를 들을 줄 아는 이를 만나면 기뻐할 거요."
rows["203:1799335305"]="저 용들은 빠릿빠릿하게 잘들 하는군요. 어중이떠중이들이 잔뜩 모여서 자기들이 뭘 해야 하는지나 제대로 알까 싶었는데 말입니다.$B$B뭐, 어쨌든 상관없습니다. 제 부하들이 밀고 나가서 뭐든 처리할 수 있으니까요. 그냥 일할 곳만 좀 있으면 됩니다."
rows["203:455015134"]="훈련이 거의 절정에 다다랐군요. 더 나은 실력을 갖춘 마법부여사가 되려면 찾아가야 할 스승이 또 있습니다. 그녀의 이름은 안노라라고 하며, 울다만으로 가면 만날 수 있을 겁니다."
rows["203:691470246"]="하루에 두 번, 아침 여섯 시와 저녁 여섯 시에 어둠사냥꾼 볼진 님이 직접 가을 축제 광장에 나와서 맥주통 따기 행사를 진행합니다. 이런 구경거리를 놓치는 바보는 아니시겠죠?"
rows["203:710793738"]="데스윙이 돌아왔습니다. 그는 그림 바톨과 고원의 여러 지역을 손에 넣었지요. 데스윙을 막기엔 제가 너무 약하다는 자괴감이 들 정도입니다.$B$B곧 우리 여왕님께서 도착하실 겁니다. 그리고 우리는, 한때 대지의 수호자였던 그자를 물리칠 것입니다."
rows["203:918214917"]="오, 내게 신경 쓸 것 없네. 난 그저 전령일 뿐이니까. 죽음추적자 무리의 지도자라면 이렇게 눈에 띄는 곳에 우두커니 서서 날 잡아 드슈 하고 있을 리가 없잖나. 굳이 역사를 반복할 필요는 없지."
rows["204:1059328986"]="지배자의 관문에 뭐 그리 중요한 게 있는지 알아보려고 해요.$B$B그 황혼의 얼간이 녀석들, 분명히 뭔가 쓸데없는 짓을 벌이고 있을 거라고요. 불공평해요! 단서를 따라 여기까지 왔는데 가까이 가지도 못하고 있으니."
rows["204:1097539099"]="오그리마의 길이 구불구불 굴곡이 많은 것은 침입자의 이동을 방해하기 위함이지. 조그만 노움들이 그 짧은 다리로 여기서 길을 잃고 헤매는 걸 상상해 봤나? 하하! 운만 좋으면 하나 잡아서 애완동물로 키우면 딱 좋겠는데 말이야."
rows["204:1125440780"]="여행자님, 켄라리온 포드의 벽 안에 있는 한,$B$B지체 보호 구역을 떠날 때 조심하세요. 최근에는 실리티드가 몰려오고 있습니다."
rows["204:1265530677"]="이 전쟁에서는 한 조각의 가죽도 허비하지 말아야 합니다. 난 밤낮으로 새 갑옷을 만들어 내지만 헌 갑옷도 최대한 수선해서 다시 입을 수 있게 합니다. 난 다른 임무를 할 시간이 없습니다. 그래서 말인데 내 부탁 하나 들어주시겠습니까?"
rows["204:1334850440"]="최종 집계 결과를 알려드릴게요.$B$B스랄: $2200w$B$B케른: $2201w$B$B실바나스: $2202w$B$B호드 전체: $2207w$B$B$B볼바르: $2203w$B$B마그니: $2204w$B$B티란데: $2205w$B$B얼라이언스 전체: $2206w$b$b가장 인기 많은 영웅은 얼라이언스에 있네요!"
rows["204:1608645887"]="정령 카드를 모아 한 벌이 되면 혼돈의 소용돌이의 상급 다크문 카드를 보상으로 받게 될 겁니다. 이 카드는 간혹 당신이 맞서 싸우고 있는 적에게 커다란 피해를 주기도 한답니다."
rows["204:1782922981"]="<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B손끝이 뭉툭하고 둥그스름하군요. 그래서 별도의 장비를 들고 전투를 하는 건가요?$B$B재미있네요."
rows["204:2111857346"]="구리 주괴는 $1998w개 중 $2018w개를 모았네. 주석 주괴는 $2006w개가 필요한데 $2005w개를 모았네. 그리고 이번 전쟁에서 승리하려면 제련된 미스릴 주괴 $2009w개가 필요한데 지금까지 $2008w개를 모았다네."
rows["204:247673599"]="상당히 늘었군. 스날에게 가서 얘기를 해 보게. 사루의 슬하에서 수련을 받으러 오그리마로 갔으니, 전사 지구에 있는 불타는 모루 부근에서 찾을 수 있을 거야. 참, 그 친구 분명 당신을 시험하려 들 테니 준비 단단히 하는 게 좋을 걸세."
rows["204:411591860"]="이 물체에서는 마른 핏자국이 몇 군데 보입니다. 트롤들이 이 유물을 차지하려고 다투는 과정에서 생겼을 것입니다. 하지만 물체 자체는 상당히 평범해 보이며, 그렇게 서로 다툴 만한 물건은 아닌 듯합니다."
rows["204:532893989"]="달라란에는 경매장이 없답니다. 그러니 다른 대도시로 가는 차원문을 타셔야 한답니다.$B$B달라란에 있는 얼라이언스와 호드 지구인 은빛 자치구와 선리버 성소에서 차원문을 찾을 수 있을 겁니다."
rows["204:554820573"]="카른은 강철과 가열로의 영혼이 우리를 인도하는 소리에 들어야 한다고 하는데, 나는 아무리 귀를 기울여도 쇳소리밖에 들리지 않더군. 자, 나와 같이 망치를 들고 영혼의 소리를 듣도록 노력해 봅시다."
rows["204:598235532"]="피버섯은 다른 버섯보다 훨씬 평범하여 핏빛안개 섬 주변의 숲 속의 거의 모든 지역에서 찾아볼 수 있소. 목숨을 소중하게 생각한다면 핏빛안개 섬을 가르는 길의 남쪽을 계속 찾아보시오."
rows["204:671457185"]="이 전쟁 중 스컬지 이 낙스라마스, 만약 당신이 불성스러운 전사장과  ⁇ 돌판 잔해를 발견하면, 내게 돌려주면 영웅들이 착용하는 이 갑옷의 조각을 만들게 될 것이다."
rows["204:761689110"]="아! 새로운 학생이로군요! 기술을 조금만 더 익혀오시면 제가 아는 것을 기꺼이 가르쳐 드리죠. 저쪽에 있는 그레타 파인스핀들에게 가 보세요. 당신이라면 아마 금방 배우실 수 있을 겁니다."
rows["204:986100725"]="그걸 물어보다니 참 재미있군. 가죽에 대한 정보를 방금 받았거든. 지금까지 얼라이언스는 얇은 가죽 $2061w개 중 $2060w개, 일반 가죽 $2064w개 중 $2063w개, 두꺼운 가죽 $2071w개 중 $2069w개를 모았네."
rows["205:1025500066"]="듀로타에는 채광을 하기 좋은 곳이 많다고 하더군. 그래서, 이 칼바위 언덕에도 광부가 하나 머물고 있지. 북서쪽에 있는 가열로 옆에서 크룬을 찾아보게."
rows["205:129212023"]="어떤 이들은 군대의 성공은 힘과 용기가 좌우한다고들 하는데, 그 말도 맞소! 하지만 군대를 제대로 유지하기 위해서는 보급품이 반드시 필요하지. 그런 보급품을 공급하는 게 바로 내 일이오."
rows["205:1342584955"]="당신이 알고 싶어하는 걸 당장 가르쳐 줄 수도 있지만 인내심을 갖고 참아야 하오. 천천히 강철을 달구면서 망치로 두드릴 때마다 변화하는 형태를 몸과 마음으로 느끼도록 하시오. 강철과 당신이 하나가 되면 그제야 내 말을 이해할 수 있을 거요."
rows["205:140470212"]="축복 카드 한 벌을 완성한다면, 성전의 다크문 카드를 보상으로 받게 될 겁니다. 이 카드를 착용하면 적에게 피해를 줄 때마다 전투력과 주문력이 증가하는 효과를 얻게 된답니다."
rows["205:1503378099"]="약초라... 골목길에 있는 수목원으로 가서 잔디와 얘기해 보게. 지혜의 골짜기, 아스란의 상점 뒤에는 나무 계단이 있네. 그 계단을 따라 골목길의 위로 올라가면 찾을 수 있을 거야."
rows["205:1838758607"]="달라란 남동쪽, 영광의 일용품점에 있는 빨간머리가 대부분의 직업용품을 제공합니다.$B$B좀 더 특수한 물건을 찾으신다면, 마법사 교역소로 가보시는 게 좋습니다. 그곳에 있는 보급품 상인들을 만나 보십시오."
rows["205:1870366324"]="전쟁의 기운이 또다시 흐르고 있습니다. 차가운 북쪽으로부터 리치 왕이 보낸 죽음의 요새가 우리 땅을 포위해 공격하고 있습니다. 리치 왕은 공중을 나는 죽음의 요새를 보내 세계를 정복하려 합니다."
rows["205:1996184661"]="내가 죽기 전에는 사서를 했었지. 전쟁이나 역병과는 아무 상관이 없는 일이었다고. 이렇게 되고 싶은 적은 단 한 번도 없었네... 이제 정신을 되찾았으니 한번 제대로 싸워보지도 않고 항복하는 일은 절대로 없을 거야."
rows["205:2061618547"]="자넨 나에게 배우기에는 아직 기술이 부족하군. 저기 있는 마틴 펠벤 박사에게 가 보게나. 아니면 동남쪽으로 경사로를 올라가서 학자 마쉬에게 가던가. 그들은 자네에게 필요한 기술을 가르쳐 줄 수 있는 포세이큰들이야."
rows["205:261027246"]="피요른의 모루가 던 니펠렘에서 피요른과 그의 군대가 이뤄낸 승리의 상징으로서 두드러진 모습으로 서 있습니다.$b$b당신의 행동이 이 세계에 영속적인 효과가 있었다는 사실에 미소가 지어지는 걸 어쩔 수 없습니다."
rows["205:45966595"]="<땅이 울리고 멀리 있는 바위가 굴러떨어질 정도로 깊고 길게 웃는 고르문간>$B$B아, 하! 하루 하 하룸! 미안해, 작은 친구. 우린 너희처럼 흘린 걸 깨끗이 치우지 못해."
rows["205:468244757"]="아니면 어떻게 그런 일이 있을 수 있었겠소? 누군가가 검은무쇠 녀석들에게 정보를 흘린 게 분명하오.$B$B<주먹을 흔들어 보이는 카란>$B$B그러니 날 도와주시오. 여기서 빠져나가면 내 나머지 일생을 그 배신자를 찾으며 보낼 참이오."
rows["205:591305514"]="지금껏 저 사람이 발굴한 보물을 한 번 보십시오!$b$b그가 사용하는 방법은 딱히 마음에 들지 않을 때도 있지만, 결과만큼은 부정할 수 없습니다...$b$b우울한 생각은 하지 말아야지요. 그건 신사에게 적합한 태도가 아니랍니다."
rows["205:662512773"]="전사의 길을 갈망한다면 크랑 스톤후프를 찾아가 보십시오. 마을의 남동쪽 구석에 있는 동그란 마당에서 종종 풋내기 전사들을 가르치고 있으니까요."
rows["205:744649150"]="어둠이 우릴 잘 숨겨줄 것이다.\010$b난 어둠장막으로 몸을 숨길 수 있지. 그리고 너한테도 이 마법을 걸어줄 수 있다.\010$b어둠장막이 있다고 아예 안 보이게 되는 건 아니지만, 적과 적당한 거리만 유지한다면 들키지 않는다."
rows["205:922177812"]="황천의 폭풍의 52번 구역에 있는 빅스톤 핀치휘슬에게 가보십시오. 그는 스팀휘들 결투 대회의 공식 투기장 사무관으로서, 투기장 점수가 높은 이들에게 온갖 종류의 좋은 물건을 팔고 있습니다."
rows["206:110059629"]="전쟁노래 협곡에서 나이트 엘프들과 그들의 겁쟁이 동료를 없애 버려야 하네. 호드의 일원으로서 돕고 싶다면 명예의 골짜기에 있는 용사의 전당으로 가서 브락굴 데스브링어와 얘기해 보게."
rows["206:1418466223"]="크고 순진해 보이는 그녀의 눈을 보고 착각하지 말게나. 탈리는 대단한 전문가야. 매일 새로운 것을 배우곤 하지. 내가 왜 땜장이 마을에 있다고 생각하나? 내가 기술자로 보이나? 그래, 당연히 아니지."
rows["206:1427756204"]="와일드해머 용병들과 함께 승전의 요새 방어 임무에 고용되었을 땐, 호드와 싸우게 되리라 예상했지.$B$B하지만 온갖 적들이 기습해 왔네! 고블린 폭파병과 땅속을 파고드는 벌레, 전기를 내뿜는 도마뱀까지..."
rows["206:1981602665"]="박쥐 가죽 벗기는 일 같은 건 랜드 로바트가 아주 능숙하지. 일단 길을 따라 브릴에서 남동쪽으로 쭉 가면, 야영지에서 서있는 그를 만날 수 있을걸. 무슨 말인지 모르겠나? 마을에서 나가는 길을 따라 남동쪽으로 가다가, 교차로에서 동쪽으로 가면 된다고."
rows["206:304610524"]="검은용군단의 세력이 불타는 평원의 경계를 넘어 스톰윈드 왕국까지 퍼져나갔던 것 같아! 그 찬탈자가 발각되어 축출된 것이지."
rows["206:537905325"]="리는 수정 호수에서 별의별 희한한 것들을 다 낚아봤다고 합니다. 몇 달 전에는 이상하게 생긴 투구를 건져 올린 얘기도 해주더군요. 그날 밤 사자무리 여관에서 술이 좀 과했던 것 같긴 하지만요."
rows["206:647864082"]="이 건강한 채찍뿌리는 악령의 숲을 뒤덮은 병든 타락과는 정반대의 모습입니다. 부드럽고 튼튼한 뿌리에서 맛좋은 덩이줄기가 자라나 식물 옆 땅에 놓여 있습니다."
rows["206:709071690"]="대사가 자신이 흘린 피의 웅덩이 안에 시체가 되어 누워 있습니다.$b$b대사의 찢어진 옷을 통해 크고 깊은 이빨 자국을 여럿 볼 수 있습니다.$b$b비전문가의 눈으로 봐도 그 상처는 불에 그슬린 듯 보이고, 일부는 검게 탄 곳도 있습니다."
rows["206:841399254"]="없는 게 없습니다! 큰놈, 작은놈, 원하는 건 뭐든지 이 하진이 책임지고 구해드리겠습니다.$B$B울트리스 마나괴철로로 가시는 여행자 여러분, 목숨이 아깝다면 짐을 단단히 꾸려가십시오. 물건을 살 수 있는 곳은 여기가 마지막입니다."
rows["206:957365137"]="한가하게 잡담이나 하면서 낭비할 시간은 없으니 어서 말하도록. 포세이큰이 무시 못할 세력으로 성장하긴 했지만 주어진 날까지 할 일이 아주 많다. 이 거대한 도시는 그냥 돌아가는 게 아니란 말이다.$b$b원하는 게 무엇인가?"
rows["206:994858203"]="왕자는 애쉬브링거의 이야기를 거부했나요? 그것은 그의 이야기 중 가장 좋아하는 이야기입니다. 그의 가장 좋아하는 이야기는 애쉬브링거의 후속입니다. 물론, 아무도 그 이야기를 그에게서 꺼낼 수 없었습니다."
rows["207:1009545803"]="용은 소나 돼지 같은 평범한 동물이 아니오. 용은 자연의 힘이요. 강력하고... 원초적인.$B$B용을 자신의 의지로 제어하는 것은 세상을 길들이는 것과 같지.$B$B그리고 그들의 고삐를 손에 쥐는 것은 운명을 손에 쥐는 것과 같소."
rows["207:1274325136"]="베나는 마치 신들린 것처럼 일을 한다네. 잠도 안 자고 밥도 안 먹고 밤낮으로 물약 제조에만 파묻혀 있었지. 나도 언데드 동맹들이 도움을 필요로 한다는 것을 모르는 건 아니지만 저러다가 쓰러지고 말지."
rows["207:164343070"]="우리 부대원 중 하나가 그 감옥에서 빠져나와 다른 포로들을 풀어주었네... 우리는 자유였지... 잠깐 동안은 말이야.$b$b어떤 이들은 물 위로 헤엄쳐 올라가고... 어떤 이들은 이 동굴을 발견하고 이리로 왔네.$b$b그렇지만 결국엔 나 혼자만 살아남았어..."
rows["207:175282856"]="할머니의 치료소에 오신 것을 환영합니다. 그곳에서 다양한 약초와 기름들을 찾을 수 있습니다.$B$B저는 힐다이고, 저게 제드라 자매입니다."
rows["207:1878239870"]="황새에게 물고기를 줘 하루 동안 먹여라 황새에게 낚시를 가르치고 평생 먹여라 우탄 스틸워터도 낚시를 가르쳐 줄 수 있어"
rows["207:2002292533"]="공식적으로는 그렇습니다. 하지만 그런 칭호는 나에게 아무런 의미가 없습니다. 빛 그 은혜로 우리에게 주는 모든 것은 이기적인 방해입니다."
rows["207:214588507"]="이렇게 다르나서스의 유능한 이들에게 둘러싸여 있다니 너무 흥분되지 않나요? 가족들이 저를 자랑스러워할 겁니다. 정말 운이 좋으면 파수대에서 입대해 전방에서 싸워 달라는 부탁을 받게 될지도 모른답니다!"
rows["207:249254131"]="고기, 뼈, 그리고 가죽... 훌륭한 사냥꾼이라면 아무것도 버리지 않는다네. 가죽을 깨끗이 벗겨 동지의 방어구를 두껍게 만들어 줄 수 있지. 즉 혼자서도 독야청청 강할 수 있겠지만 힘을 합치면 무적이 되는 법이야."
rows["207:61385867"]="이 작전은 제가 지휘합니다.$B$B우리 비행선이 잘 폭발한다느니 적이 우리보다 키가 크느니 하는 소리는 집어치우십시오. 우린 전문가고, 아무 문제 없이 일을 처리할 겁니다."
rows["208:1023941977"]="<쉿 소리를 내며 저지하는 카이드>$B$B조용! 오크와 얼라이언스를 끌어들이고 싶은 거야, 이 둔하고 한심한 녀석 같으니!$B$B그래, 그렇게 고개만 끄덕이라고. 얘기가 끝나면 자네는 곧장 여길 뜨고 여기서 나를 본 사실은 잊어버려."
rows["208:121921959"]="놈리건 작전이 끝난 후, 대부분의 사람들은 쉴 시간을 갖게 되었죠. 그렇지만 저와 제 조수는 안심지대 동료들이 도시 안에서 구출해온 생존자들과 부상자들을 돌봐오고 있었답니다."
rows["208:1255294530"]="빅시와 불리위프는 별별 무기를 다 써서 오크를 때려잡은 경험이 있소. 그들은 언제나 잘나가는 무기 상점에 머물고 있으니까 훈련을 받고 싶으면 가보시오."
rows["208:1635539230"]="폭풍술사 우슐레이$B$B그 힘은 곧 하늘, 비, 그리고 산산이 부서진 대지의 힘일지니, 다시 한번 구루바시의 아버지로 군림하기를...$B$B지금 우슐레이는 먼 곳에 있지만 언젠가는 돌아올 것입니다."
rows["208:183233581"]="이 고원의 나무들은 무진장 튼튼하지. 어떤 건 말 그대로... 돌덩이라고. 도무지 이해할 수가 없어.$B$B나무를 베려고 다이아몬드톱니 벌목기를 보냈는데, 얼라이언스가 벌목기를 계속 때려 부수고 있어."
rows["208:1886195249"]="물론, 해결해야 할 문제는 있지만요. 초소형 전차는 정말 경이로운 기술이라고요.$B$B만드는 데 필요한 재료는 일반 공성 전차의 4분의 1에 불과하고, 누구든지 대량 생산할 수 있어요! ...손이 아무리 작아도 문제없어요!"
rows["208:2066499904"]="수년 전, 그림토템 부족이 우리 마을을 침략했네. 고통과 노여움, 상실감이 아직도 내 마음을 짓누르고 있네.$B$B지금은 흉포한 공격으로 마을을 잃은 다른 이들에게 위안과 도움을 주고자 노력한다네."
rows["208:2103826251"]="재조조를 하고 싶었소?\013\010\013\010\013\010\013\010하지만 스톰윈드의 성당 구역에 있는 \"삼풍\"의 이성들은 도움이 될 것입니다.\013\010\013\010\013\010\013\010도시의 경비원이라면 누구나 안내를 줄 수 있습니다."
rows["208:2126147930"]="마치 내가 이런 물건을 처음 본 것인 양 행동하는군. 괜찮은 물건이긴 하지만 이런 \"괜찮은\" 수준의 물건은 매일 본단 말이야. 이렇게 하지. 나를 아주 놀라게 해주면 잠자던 드워프가 벌떡 일어나게 할 만한 것을 만드는 법을 가르쳐주겠어."
rows["208:421934812"]="싸움이란 얼마나 부질없는 짓인지... 하지만 은빛날개 요새의 나이트 엘프들이 우리와 평화롭게 대화할 의향이 없다면 다른 도리가 있겠습니까? 전쟁노래 협곡으로 가려면 수렵의 봉우리에 있는 케르굴 블러드액스에게 가서 도움을 청하십시오."
rows["208:6219584"]="분석하는 데 쓸 만한 스컬지 역병을 구하느라 우리 요원들이 얼마나 많이 실패했는지 몰라요. 제가 직접 최전방에 나가서 어떻게 하는지 지켜봤지요. 사람들 말대로, 일을 제대로 하고 싶다면 말이에요..."
rows["209:1028847084"]="깊은굴 지하철 개통 소식을 들으셨군요? 한번 타보세요. 아주 재미있지요! 드워프 지구 뒤편에 있습니다. 참, 지하철이 이동하는 동안에는 절대로 팔이나 머리를 바깥으로 내밀면 안 됩니다."
rows["209:1077057634"]="정기의 봉우리 서편 끝에 있는 비행선 탑승대 근처에 가보면 크렌들 빅포켓이 있습니다. 저는 고블린이 여기까지 날아오도록 만든 기묘한 발명품은 별로 좋아하지 않습니다... 하지만, 그럭저럭 참아내신다면 오그리마까지 바로 갈 수 있지요."
rows["209:1344558445"]="나가 놈들.$B$B<역겨워하며 바닥에 침을 뱉는 바일쏜>$B$B채찍으로 오크를 노예로 만들 수 있다고 생각하다니 정말 멍청한 놈들이군. 기회가 있을 때 우릴 죽이지 않았던 것을 뼈저리게 후회하게 해줄 걸세."
rows["209:1453843608"]="대지모신 앞에서 자연과 하나가 되는 법을 배우려면 강한 자신감이 필요한 법입니다. 사냥꾼의 길을 당당히 걸어가고 싶다면 블러드후프 마을 북쪽 끝에 있는 요 샤프메인을 찾아가보십시오."
rows["209:1561274353"]="스랄 님께서 직접 이곳으로 저를 보내셨습니다. 대족장님께 명령을 받은 것만으로도 영광스럽기 때문에 하나도 힘든 줄 모르겠습니다. 사실 스토나드보다 나은 곳도 없지요. 필요한 약초는 죄다 여기 이 늪지대 진흙탕에서 자라니까 말입니다."
rows["209:1845768943"]="지금 이 순간에도 최종 진격 준비가 진행되고 있네. 나머지는 자네가 루안 숲에서 얼마나 빨리 군대를 조직하느냐에 달렸네.$B$B빨리 끝낼 수 있을 것 같나?"
rows["209:2010567915"]="물약 제조 기술을 배우려고 이곳에 오셨습니까? 노력 없이 그런 특권을 주리라 생각했다면 오산입니다. 가서 기술을 더 익힌 후에 돌아오십시오."
rows["209:2071275002"]="어렸을 때 난 사제회의 수도자가 되려고 열심히 훈련을 받았소. 사실 여성 총독은 전례가 없는 일이었지.$B$B요즘은 성별이 거의 문제가 되지 않지만. 용기와 확신이야말로 모든 차이를 만드는 근원이라오."
rows["209:210294575"]="마지크네트에서 죽인 양은 그런 그림을 그린다. 소피아 테일러는 타프룸에서 블러드마지를 가르치고 있습니다. 강령술사그리고 지각된 게랄드 이교도."
rows["209:226941060"]="캘타스를 쓰러뜨리려면 그대들 모두가 각자 노력해야 합니다.$b$b능력이 된다면 군대를 소집해 태양샘에 산재하는 수많은 문제를 해결해 보는 것도 좋겠습니다.$b$b어쩌면 우리는 거기서 다시 만날지도 모르지요."
rows["209:317148674"]="응급치료라고요? 어디 다치셨나요? 그런 것 같지는 않은데... 아, 응급치료를 배우고 싶다고요. 니사 파이어스톤을 찾아가 보십시오. 대용광로 옆에서 아이언포지 치료소를 운영하고 있으니 그곳으로 가시면 만나실 수 있을 겁니다."
rows["209:476219034"]="세계주술사의 영혼이... 판드랄 스태그헬름의 손에 흩어지다니!$B$B배후에 더 큰 힘이 있는 게 분명하다. 라그나로스가 내가 상상할 수도 없을 만큼 널리 이 지역에 마수를 뻗쳤구나.$B$B불의 군주를 막아야만 한다!"
rows["209:480951425"]="베스프리스투스 (Vesprystus) 를 찾고 있습니다. 그는 테일드라실의 기지에서 오는 히포그리프들을 감시합니다. 당신은 그를 서쪽 다르나서스의 포털을 통해 찾을 것입니다."
rows["209:596071588"]="아, 마법부여 기술을 배울 생각이라면 김블 시슬퍼즈를 찾아가야 할 겁니다. 김블은 '시슬퍼즈의 신비한 이야기'라는 자기 가게에 있을 겁니다. 대용광로의 그리핀 조련사 바로 옆에 있죠."
rows["209:677309532"]="인간?$b$b<세 사람은 각각 달콤하고 깊고 험한 목소리로 함께 웃는다.>$b$b별들은 아직 깨어있지 않았죠. 우리가 눈을 뜨었을 때, 세상은 아직 둥근지 않았죠. 우리는 아직 세 살이 아니었습니다."
rows["20:1044617722"]="이건 시간 낭빈데..."
rows["20:1051470612"]="모그도르그를 보러 갔어?"
rows["20:105449818"]="안녕하세요 여행자"
rows["20:1097478534"]="어떻게 도와드릴까요?"
rows["20:1108067898"]="뭐라고요? 전 바쁘다니까요."
rows["20:1173035396"]="무엇을 도와주면 되겠나?"
rows["20:1177524816"]="저게 대체 뭐였지?"
rows["20:1239643170"]="무슨 일로 오셨습니까?"
rows["20:1254666790"]="저리 가라고, 신참!"
rows["20:1331219313"]="아... 우리 아는 사이였나요?"
rows["20:1368378563"]="나블리아 님, 당신이십니까?"
rows["20:1406414890"]="이제 네가 왕이야! 위대한 고르독의 멍멍이!"
rows["20:152512841"]="난 널 훈련시킬 수 없어"
rows["20:152513978"]="포세이큰 만세! 우리에게 축복을!"
rows["20:1962562473"]="여기가 아닌 그 어딘가로..."
rows["20:226279535"]="우린 도와줄 거야"
rows["20:328628075"]="여긴 아주 엉망이라네."
rows["20:40191190"]="새로운 왕 만세!"
rows["20:486306771"]="블름르르글 굴르글 그르르."
rows["20:534088655"]="러그를를를르를글를!!!"
rows["20:62021887"]="히드락시스와 얘기를 나눠 보도록!"
rows["20:641346586"]="동전을 넣으십시오."
rows["20:660387093"]="오우거들.$B$B난 오우거를 증오하오."
rows["20:762544602"]="물론입니다. 갑시다!"
rows["20:790077243"]="어? 뭐야?! 저리 가라고!"
rows["20:802002014"]="냄새가 좀 나오?"
rows["20:942570721"]="어디서 본 거 같은데..."
rows["20:962774998"]="이상!"
rows["210:1019782355"]="성소의 수호물을 가동하면 그곳을 빠르게 확보하는 데 도움이 될 거요. 불타는 군단과 캘타스에게 총공격을 가할 때 버림받은 엘프 녀석들의 방해를 받아 좋을 게 없지 않소.$B$B작업은 현재 $3244w퍼센트 정도 진행된 상태라오."
rows["210:1055282324"]="공물함 안에 있는 보상의 질과 양은 십자군 사령관의 시험에서 도전 기회를 몇 번이나 썼는지에 따라 다르다네. 더 적은 횟수의 도전으로 시험을 통과하면 더 좋은 보상을 얻을 수 있지."
rows["210:1063705302"]="폭풍술사 우슐레이$B$B그 힘은 곧 하늘, 비, 그리고 산산이 부서진 대지의 힘일지니, 다시 한번 구루바시의 아버지로 군림하기를...$B$B지금 우슐레이는 먼 곳에 있지만 언젠가는 돌아올 것입니다."
rows["210:1158252581"]="제대로만 길들이면 용매는 아주 유순합니다. 참 매력적이지 않나요? 잘 길들이면 아주 친근하고 좋은 친구가 되지만 야생에서는 난폭하고 위험합니다... 저는 그 녀석들이 정말 좋습니다."
rows["210:1645732905"]="아라시 분지의 전쟁은 곧 물자 전쟁이나 다름없다네. 목재, 광석, 식량... 이 모든 것이 전쟁의 승리를 위해 필수적이지.$B$B그러므로 전장에서 적의 물자 보급을 차단하는 일은 적장을 처치하는 것만큼이나 훌륭한 공을 세운 것일세."
rows["210:1805578025"]="저 유명한 \"용아귀 부족의 현자\"를 만나러 여기까지 먼 길을 왔다. 칼을 꽂기 전에 초갈의 검은 심장을 한번 들여다보고 싶었지.$B$B하지만 그녀는 아무 쓸모가 없군. 온통 수수께끼만 지껄여 대니... 어쩌면 네가 도움이 될지도 모르겠다."
rows["210:2000757888"]="라그나로스의 육신을 파괴하십시오. 그의 시체에서 정수가 나타날 것입니다. 그렇게 라그나로스가 약해지면 썬더란을 감옥에 가둬 놓는 힘도 느슨해 지겠지요. 정수가 바로 열쇠 역할을 하는 것입니다."
rows["210:2067724261"]="실버문의 원정순찰대 광장에 사는 블러드 엘프, 일레다가 제자들에게 한손 검과 양손 검 쓰는 법을 가르치지. 언더시티의 무기 전문가, 아키발드한테 가도 배울 수 있어. 군사 지구로 가보게."
rows["210:2129003344"]="제 생각엔 우리 형제들이 고블린들에게 조치를 취해야 한다고 봐요. 소문으로는 고블린 한 명이 축구탄으로 대격변을 일으켰다죠!$B$B더 늦기 전에 이 녀석들을 박멸해야 해요!"
rows["210:346352971"]="힘이 최고조에 달한 에메랄드 비룡은 꿈의 집중을 사용하여 비룡의 생명 에너지를 아군 대상에게 보내 치유할 수 있지요. 착취 독을 사용하면 잃은 체력을 회복할 수 있답니다."
rows["210:662351921"]="도대체 원하는 게 뭐요? 우리 훌륭한 지도자와 중요한 문제를 의논하느라 바쁜 것이 보이지 않소?$B$B썩 물러가지 않으면 흠씬 두들겨 맞을 줄 아시오!"
rows["210:748415987"]="저분들은 며칠 전 샤트라스에서 도착했는데 그 이후로 줄곧 논쟁을 하고 있지 뭡니까.$B$B당신이 저분들 때문에 발길을 돌리지 않아 정말 다행이랍니다. 저분들이 저러는 통에 손님이 떨어져 나가는 게 아닐까 걱정하던 참이었거든요."
rows["211:1094098418"]="무슨 말씀이신지 알겠습니다.$b$b있잖아요, 전 그저 시야를 조금 넓히고 싶어서 여기까지 왔을 뿐입니다. 세상을 두 눈으로 보고 뭐 그런 목적으로요.$b$b다른 사람들의 일에는 크게 신경 쓰고 싶지 않습니다.$b$b그래도 만나뵙게 되어 반가웠습니다.\010"
rows["211:1147720812"]="운이 날 웃고 있어 내가 이 겸손한 집에서 손님들을 받는 것을 사랑하니까$b$b들어와, 들어와, 전혀 방해가 되지 않아$b$b<눈이 죽일 수 있다면, 당신의 시체는 지금 문 매트 역할을 할 것입니다.>"
rows["211:1169378505"]="들리는 얘기로는 우리에게 필요한 모든 물자가 모였다고 하네요. 이제 호드 측에서 물자 수집을 완료하기만 하면 되겠어요. 호드의 준비가 끝나면 모든 물자를 실리더스로 옮기겠죠. 바야흐로 전쟁을 시작할 수 있는 겁니다."
rows["211:1220015425"]="아, 나도 그쪽으로 가는 길이라오. 주변 길에서 야생동물의 움직임이 심상치 않아서 여기 산마루 경비탑에 잠시 머무는 중이었지.$b$b이렇게 합시다. 이 부근의 길에서 야생동물을 처리해 준다면, 나도 당신과 함께 가겠소."
rows["211:1324024477"]="남편은 최근 오크 위협에 몰두해왔고... 우리 집 아래층을 임시 병역으로 바꾸어야 했습니다."
rows["211:1440096468"]="계속해서 비극적인 사건이 일어났어요. 아티쉬와 접촉한 키린 토의 모든 마법사가 죽게 된 거죠.$B$B그러니까 아티쉬는 지각이 있는 물건이었어요. 살게라스가 부여한 것이죠..."
rows["211:176124064"]="Quel'thalas의 물은 물고기로 가득합니다; 나는 그들이 당신의 눈을 사로 잡았을 것을? Drathen는 낚시 무역의 트릭을 꽤 경험하고 있으며, 왕립 거래소 근처에 노인 행보에서 찾을 수 있습니다."
rows["211:1833936920"]="오래전, 흑마법사 네크로스 스컬크러셔는 강력한 유물을 사용해 알렉스트라자와 붉은용군단 대부분을 노예로 만들었소. 줄루헤드와 네크로스는 이미 죽었지만, 붉은용군단에게 그 빚을 갚으려면 아직 멀었소."
rows["211:1841926293"]="온갖 끔찍한 것들에 둘러싸여 있지만, 최소한 물 밖으로 나와있으니 다행이야.$B$B그곳에 있었다면 어젯밤 날아다니던 그 무언가를 피할 수 없었을 거야. 엄청나게 큰 크기였어... 정말, 어마어마하게 컸다고!"
rows["211:254903704"]="아, 배우실 거야 아직도 잔뜩 있죠. 제가 할 수만 있으면 모두 다 가르쳐 드리고 싶지만 저도 아직 배우고 있는 입장이라서요. 아이언포지에 있는 트리시 퀵스위치를 한번 찾아가 보세요. 계속해서 훈련을 시켜 줄 수 있을 겁니다!"
rows["211:294753359"]="안드라스트 요새에 오신 것을 환영합니다.$b$b<호텔 주인 스스로 블랙록을 다루고 있는 것 같다. 피난을 원하는 술에 취한 군인들을 봉사하는 것은 전투에서 오크를 마주하는 것과 같이 피곤해야 합니다.>"
rows["211:38566786"]="날 도와주었으니 이 땅에 대해서 아는 대로 말해주겠소. 내 지식이 그리 깊지는 않지만, 어쩌면 당신 같은 이가 흥미를 가질 만한 사실을 몇 가지 알려줄 수 있지도 않겠소."
rows["211:481625119"]="안녕하세요! 저흰 저 아무짝에도 쓸모없는 해적 녀석들이 막고 있어서 완전히 발이 묶였어요.$B$B당신이 폭탄을 몇 발 떨어뜨려 주시면 도움이 될 것 같은데 생각 있으신가요?!$B$B도둑맞은 저희 비행선이 여기 도착했어요. 비행선이 떠나기 전에 어서 타세요!"
rows["211:482385789"]="한때 저는 어둠이 밤의 동생이기 때문에 어둠을 반겼답니다. 하지만 이제는 낮에도 어둠이 깔려 숲이 생명을 유지하기 위해 절규하고 있습니다. 우리가 즉시 행동하지 않으면 이 어두운 그림자는 곧 세상을 덮어버릴 것입니다."
rows["211:507762073"]="오그리마로 가야할 걸세. 칼바위 언덕에서 나가는 북쪽 길을 따라 협곡을 통과하면 오그리마에 이르게 되지. 그곳에서 그런트 중 한 명에게 길을 더 자세히 물어보게."
rows["211:684457964"]="진정한 프로는 자신의 한계를 아는 법이지요. 당신 실력이 나보다 뛰어나다는 것을 인정하는 데 전혀 부끄러움이 없습니다. 이제 아조라의 탑에 있는 키타 파이어윈드를 찾아가 보는 게 좋겠습니다. 키타는 아주 유명한데, 충분히 그럴 만한 이유가 있지요."
rows["211:75128580"]="처음으로 바다에 나가게 되면 더 평화롭고 배울 것이 많은 모험을 할 거라 상상했었지. 자연과 함께하는 그런 모험 말일세.$b$b이곳에서는 자연스러운 거라곤 거의 찾아보기 어렵군. 주변 곳곳의 정령들이 복수를 부르짖고 있네."
rows["212:1255573149"]="정다운 얼굴을 보니 좋군. 연금술사 요한은 뭔가 원하는 것이 있을 때만 잡담을 늘어놓지. 그는 무덤 밖에 너무 오래 있었네. 언젠가는 나도 그렇게 되겠지. 소름 끼치지만 그때쯤이면 별로 신경 쓰지 않을지도 모르겠군."
rows["212:1326705119"]="붕대 사용법을 아직 안 배우셨다면 기본적인 붕대 제조법과 사용법을 기꺼이 알려드리겠어요. 전투에서 적절하게 붕대를 사용하느냐 그렇지 못하느냐에 따라 생사가 결정되는 경우가 간혹 있죠."
rows["212:1704632548"]="응급치료는 배워놓으면 아주 좋은 기술이랍니다. 저도 전쟁 중에 그것 덕분에 여러 번 목숨을 건졌답니다. 정기의 봉우리에 있는 정기의 치료소에 가시면 판드 스톤바인더가 자신의 목숨을 스스로 구하는 방법을 가르쳐줄 겁니다."
rows["212:1744579929"]="펠 파워와 협상하는 사람들은 여기서 자세히 관찰됩니다. 지옥서약자를 훈련시키는 페리니오르 펠시티와 엑소로트 기사들의 교사가 된 망명자 젤투르타는 전사 테라스의 상단 걸음으로 계속합니다."
rows["212:2069082991"]="검은바위 나락에 있는 검은무쇠 놈들이 내게 트집 잡을 건 아무것도 없네. 여기 토륨 거점에 있는 이들도 그렇고 말이야.$b$b나는 가능하면 혼자서 일한다네. 그게 내가 좋아하는 방식이고 말이야. 물론 값을 올바르게 치러준다면야, 다른 쪽 이야기도 들어줄 용의는 있네만..."
rows["212:2075124945"]="나는 서리늑대 부족의 신병 모집을 담당하고 있네. 서리늑대 부족의 일원이라면 계급이 오를 때마다 나를 찾아와야 하지.$B$B명예와 존경은 이렇게 혹독한 추위 속에서 얻을 수 있는 것이야."
rows["212:2085646781"]="<발 디딘 땅이 흔들리고 귀가 아플 정도로 깊고 우렁찬 목소리로 말하는 고르문간>$B$B안녕, 말랑한 친구.$B$B너흰 항상 가만있질 못하고 이리저리 뛰어다니는군. 이리 와서 잠깐 쉬지그래."
rows["212:2088648904"]="우리는 그분의 종으로 헌신할 것을 맹세했고, 주인님의 철권 통치를 받들어 지시를 따르며 시행한다. 라그나로스 님이 현신하셔도 불의 세계로부터 정기를 받지 못하기 때문에 실체가 아닌 그림자에 불과하지만, 너 정도는 끝내고도 남을 만큼 강력하시다."
rows["212:514079858"]="저 너머에 부서진 함정이 보이나? 오우거들은 너무 멍청해서 부서진 함정을 고칠 생각은 꿈에도 못하지. 분명히 수선 작업이 필요하단 말이야. 함정을 고치면, 오우거 경비병 슬립킥을 그쪽으로 꾀어내어 사로잡을 수 있다고!"
rows["212:556017930"]="<개봉하지 않은 봉투를 이마에 붙이고 있는 나라인>$B$B뭘까... 으음... 벨벳!$B$B맞죠?$B$B배운 전문 기술을 취소하려고 이곳에 온 거라면, 저 위에 있는 책을 이용하도록 하세요...$B$B<'왕초보를 위한 예언 완전정복'을 가리키는 나라인>"
rows["212:563543292"]="우리 폭풍까마귀들은 이 고밀도의 대기 속에서 날아오르려고 애만 쓰고 있는데, 저 산등성이에 있는 불꽃매들은 손쉽게 날아오르는 것 같군요.$B$B불꽃매들은 불의 세계에 있는 다른 생물들처럼 사납기는 하지만, 그 모습 자체는 아름답기만 해요."
rows["212:653770347"]="성기사라고? 자네 연금술사의 혼합물 같은 걸 마신 건가? 뭐, 엘프 사절단이 언더시티에 계시는 어둠의 여왕님을 알현하고 있다고 하더군. 그들 중 한 명이 성기사가 어디 있는지 알고 있을 거다."
rows["212:729456901"]="당신의 물약 제조 기술은 나를 능가하는군요. 그렇다면 언더시티 연금술 실험실에 있는 언데드 학자 허버트 핼시를 찾아가도록 하십시오. 그 친구는 당신에게 더 많은 것을 가르칠 수 있는 기술이 있는데다가 당신 눈으로 직접 언데드들의 고통을 목격할 수도 있을 겁니다."
rows["212:752900474"]="난... 죽었는데...$B$B내가 왜 아직도 여기 있지? 이왕 이렇게 된 거 멋진 사냥터나 한번 찾아가 볼까?$B$B아니야... 먼저 임무부터 완수해야지. 이 세계를 떠나기 전에 파멸의 암호의 두 번째 조각을 찾아야 해."
rows["213:1215691240"]="갈반가르 부대장은 드렉타르가 신뢰하는 부하입니다. 투쟁의 벌판 남부에 있는 얼음피 주둔지에서 호드를 지휘하고 있지요. $B$B갈반가르 부대장은 현재 얼음피 주둔지에 있습니다."
rows["213:135680571"]="공원이요?$B$B거긴 폐허가 되었습니다. 못 들으셨나요? 거대한 용인 데스윙이 스톰윈드로 날아들어 와 도시를 파괴했습니다.$B$B솔직히 데스윙이 왜 모든 걸 파괴하지 않았는진 모르겠습니다. 하지만 우리는 모두 빛의 이름으로 그가 모두 파괴하지 않을 걸 감사하게 생각합니다."
rows["213:1507935528"]="득점도 해결해야 해, 제대로 된 전장에서 싸우라고 해줘, 누가 도전하고 있는지 말해줘, 그들이 동의하면, 양쪽 모두 데려가겠다."
rows["213:1672915079"]="잘 키운 바라크 토롤 산양을 타보기 전까지는 제대로 된 탈것에 올라봤다고 할 수 없지요. 이 훌륭한 놈들을 언제라도 어느 모험가에게든 자랑스럽게 보여주십시오. 그리고 어떤 상황에서든지 아주 유용할 테니까요, 제 말을 믿으십시오."
rows["213:1850245409"]="난 오래전에 저주받은 우리 형제들을 연구하고, 이들의 고통을 치료할 방법을 찾기 위해 이곳으로 왔네.$B$B막투르는 그런 나를 두 팔 벌려 환영했어. 이곳에 살면서, 그는 내 가장 친한 친구가 됐지.$B$B그리고 지금, 그런 막투르가 내 눈앞에서 죽어가고 있네..."
rows["213:1927733937"]="이 장치에 달린 여러 기계를 어떻게 작동시켜야 할지 전혀 모르겠습니다. 하지만 어딘가 익숙한 느낌이 머릿속을 가득 채워 떨쳐버릴 수가 없습니다.$B$B우선은 그냥 내버려 두는 게 좋을 것 같습니다."
rows["213:1929546989"]="미명 광석이 제때 도착하지 않았다면 우리 연구는 실패했을 것입니다.$B$B샤샤리아가 여기로 돌아올 때까지 기다려 봅시다. 그녀에게 맡길 재미있는 일이 있습니다. 기대해도 좋습니다!"
rows["213:324504196"]="다크문 카드를 누가, 무슨 목적으로 만들었는지는 아무도 몰라요. 제가 말씀드릴 수 있는 것은 아제로스 전역에서 종종 발견됐다는 것, 그것도 주로 카드의 비밀을 밝혀내려는 악당들이 가지고 있었다는 것뿐이에요."
rows["213:338906473"]="정말 흥겹지 않아요? 살데릴 경께서 이런 파티를 매일 밤 개최하신다니 정말 신납니다. 남쪽에서 벌어지는 역겨운 일을 생각하면 더욱 그렇죠. 이런 파티는 그런 일을 완전히 잊게 해주는 법입니다."
rows["213:450220913"]="에메랄드 의회에서는 상처받은 악령숲을 치유하기 위해 노력하고 있어요. 비록 이 땅을 타락시킨 것의 이름을 따서 악령숲이긴 하지만, 언젠가 이 땅에서 그 타락을 완전히 뿌리 뽑을 수 있는 날이 오기만을 바라요."
rows["213:541908913"]="이 책에는 데스윙이라는 보다 강력한 용에 맞서 다른 용들이 단결하는 내용이 나와 있습니다. 이해한 바에 따르면, 오색용군단이 이 세계에 풀려 날 뻔했었고 위상들은 단단히 준비를 하고 있었다고 합니다."
rows["213:585423301"]="아웃랜드에는 우리가 기존의 세상에서 보았던 그 어떤 존재보다 강력하고 사악한 존재들이 잔뜩 있습니다.$B$B그들을 피해 달아나지 않고 맞서는 자는 엄청난 힘을 얻게 될 것이지만, 그 힘을 이용하고 통제하는 법을 배워야 할 것입니다."
rows["213:742513993"]="심판관 마리엘 트루하트 님께서 저희에게 마상시합에 부족한 점이 없도록 조치해 달라고 말씀하셨습니다. 용사의 자격을 얻은 분들, 그리고 저희에게 능력을 인정받은 분들께서는 이 임무를 도와주셨으면 합니다."
rows["214:1019764620"]="달숲에서 이곳 레물로스의 제단은 우리 세나리온 의회가 모이는 성스러운 곳이니 방문객의 신분에 어긋나지 않게 행동해 주시기 바랍니다.$B$B제 시미터에 당해 숲에 묻히고 싶지 않다면 말이에요."
rows["214:1055948357"]="아웃랜드로 가시는 길인가요? 그렇다면 52번 구역에 있는 빅스톤 핀치휘슬에게 가 보십시오. 그는 스팀휘들 결투 대회의 공식 투기장 사무관으로서, 투기장 점수가 높은 이들에게 온갖 종류의 좋은 물건을 팔고 있다더군요."
rows["214:1202099328"]="<이 어린 바위웅덩이 멀록들은 여기에 버려진 듯합니다. 곤란한 상황에 부닥친 멀록들을 바다로 데려가면 나가에서 벗어날 기회가 생길지도 모릅니다. 넵툴도 당신이 그래주기를 바란다는 생각이 듭니다.>"
rows["214:1210607320"]="<고개를 끄덕이는 안젤라>$B$B그들의 죽음 이후 여섯 대마법사는 절대 뚫을 수 없는 마법 장벽 뒤에 지팡이를 봉인하고 감시자를 두는 것이 가장 좋은 방법이라고 결정했어요. 지팡이를 지키는 수호자 말이에요... 제가 바로 그 감시자였답니다."
rows["214:1420900677"]="안녕하세요. 무슨 일로 찾아오셨죠?$B$B이곳은 부모를 잃고 아무도 돌봐 줄 사람이 없는 불쌍한 아웃랜드의 고아들을 위한 보육원입니다.$B$B여기까지 발걸음을 하신 걸 보면, 혹시 입양을 고려하고 계신가요?"
rows["214:1769281358"]="네, 조만간 당신이 찾아올 거라는 소식은 들었어요. 하지만 난 아무나 제자로 받지 않아요. 당신에게 솜씨가 있다는 확신이 있어야 하죠. 내가 주는 시험을 치르면서 한번 확인해 보도록 하죠."
rows["214:1771078130"]="<울팡이 긴 울음소리를 내더니 당신의 냄새를 맡습니다. 그러자 당신은 울팡이 말하는 바를 이해할 수 있습니다.>$B$B이상한 흰 늑대 가르왈이 북쪽에서 와서는 내가 이끌던 무리를 빼앗았네. 내가 다시 우두머리가 되려면 놈의 목을 쳐야만 하네."
rows["214:443087867"]="좋아. 어차피 말퓨리온은 불의 땅으로 진군할 테니, 그곳에서 그를 상대해 주지. 그에 대한 심판은 며칠 정도 연기해도 좋다.$b$b<눈에 생기가 도는 레이아라>$b$b하지만 타우렌 대드루이드에게는 그런 운이 따르지 않을 것이다."
rows["214:506689272"]="학생들은 양떼와 어느 정도 비슷하지. 잘 지도하고 충분한 관심을 쏟으면 유용하고 만족스러운 존재가 된다네.$B$B하지만, 잠시만 내버려두어도 절벽에서 떨어지거나 얕은 강물에 빠져 죽고 말지."
rows["214:552502674"]="이 릴랜드는 하루 종일 무역 구역 밖에서 항구에 앉아 낚시만 하고 낚시하는 거야 낚시하는 동안 잘 할 수 있었으면 좋겠어"
rows["214:615955094"]="<재미있다는 듯 코웃음을 치는 고르문간>$B$B하룸! 생활 습관을 이렇게 자세히 생각해본 건 난생처음인걸. 너흰 정말 봐도 봐도 놀라운 종족이야. 잘 가라, 친구. 그리고 조사 중인 그거... 잘 되길 바란다."
rows["215:1131235506"]="전문 요리사 말입니까? 대용광로 북동쪽에 있는 놋쇠단지 제과점으로 가보십시오. 다릴 리크너선이 기운을 북돋아줄 맛깔스러운 음식을 만드는 방법을 가르쳐줄 겁니다!"
rows["215:145396077"]="식량! 드디어 내가 관심 있는 분야를 물어보는군! 보고받은 바로는 늑대 살코기 스테이크는 $2096w개 중 $2095w개, 점박이놀래기 구이는 $2103w개 중 $2102w개, 훈제 연어는 $2106w개 중 $2105w개를 모아서 냉장 창고에 저장해 두었다고 하네."
rows["215:147594752"]="돌려서 말하자면 원래는 백사장 야영지에 들를 계획이 없었습니다. 물건이 배달되기만을 기다리는 손님들이 있는데 이렇게 지체돼서야 제때 갈 수 있을지 의문이로군요."
rows["215:1479418273"]="우리가 항구를 장악했습니다. 그리고 이 배는 정말 괜찮은 전리품이죠. 아직 항해에 써먹을 수 없는 게 아쉬울 따름입니다.$B$B그나저나, 초록아가미 해안의 나가를 감시하라는 명령을 받았는데...$B$B그대가 좀 도와줄 수 있을까요?"
rows["215:1883454045"]="저들은 왜 이런 일을 하는 걸까요? 진주 때문에? 싸우기 위해서? 이 고대 생물 네스피라는 나가들이 알고 있는 것보다 훨씬 더 강력한 존재예요. 만약 저들이 네스피라를 굴복시킨다면... 막강한 힘을 손에 넣게 될 거예요."
rows["215:208704087"]="힘이 최고조에 달한 호박색 비룡은 시간의 균열을 사용하여 압축된 시간의 기포를 적 주변에 형성합니다. 이 기포를 통과한 마법은 대상에게 2배의 피해를 주고, 충격 충전까지 일으키지요."
rows["215:2127526482"]="다리안나에게 소질이 보이는 것 같기는 한데 활기가 넘쳐서 가만히 듣고 있지를 못합니다. 다리안나가 가진 힘과 민첩성이라면 곧 전투에 불려 나가게 될 텐데. 좀 더 빨리 가르쳐야겠습니다."
rows["215:419965943"]="쇠 우리 안에서 동전이나 물건을 내주는 일보다 호드의 은행과 보물을 지키는 일이 훨씬 맘에 든다네.$B$B저 연필이나 굴리는 고블린과 일을 바꿔 해보라면 아주 잠깐이라 해도 절대 응하지 않겠네."
rows["215:43821697"]="<투덜투덜> 호수에 추락하는 사태까지 생긴 적은 없다고 말씀드릴 수 있다면 얼마나 좋을까요. 아니면 호수에 추락한 적은 한 번밖에 없다고 말씀드릴 수 있다면 얼마나 좋을까요... 하지만 사실 저희는 네 개의 서로 다른 호수에 추락한 적이 있답니다. 그중에 하나는 로다미어 호수라죠!"
rows["215:736590887"]="달라란에 있는 직업 상급자는 마법사들 뿐입니다. 다른 직업 상급자를 찾으신다면 차원문을 통해서 대도시나 다른 곳으로 가야만 한답니다.$B$B차원문은 얼라이언스 지구의 은빛 자치구나 호드 지구인 선리버 성소에서 찾을 수 있습니다."
rows["215:941083764"]="그래, 항상 클라이드 켈런이 브릴 동쪽 브라이트워터 호수에서 낚시를 하고 있어 마스크를 입은 정신병자 조심해"
rows["216:1181299516"]="가끔은 하늘에 커다란 잿빛 구름이 떠서 우리 머리 위로 불운만 퍼붓는 것 같아. 고향에서 쫓겨난 것도 모자라 이제는 서부 몰락지대에서 빠져나가지도 못하고 있잖아. 전부 엉망이야. 누군가는 뭔가 해야 해."
rows["216:1839650207"]="벌써 해가 떴나요? 밤은 너무 짧아요! 흠, 다르나서스 북동부에 있는 장인의 정원으로 가 보십시오. 셀리에네가 투숙객들을 보살피고 있을 겁니다. 분명 그대도 잘 돌봐 줄 거예요."
rows["216:248943775"]="벨가리스트라즈가 하는 말은 사실이지요. 시간이 없어요! 당신에게 청동용군단의 비룡을 불러내는 권한을 허락해 드릴게요. 붉은용군단이나 녹색용군단의 힘을 원한다면 벨가리스트라즈나 베르디사와 이야기하세요."
rows["216:415705368"]="폭풍 카드 한 벌을 완성한다면, 진노의 다크문 카드를 보상으로 받게 될 겁니다. 이 카드를 착용하면 공격이 명중할 때까지 치명타 및 극대화가 증가하는 효과를 얻게 될 겁니다."
rows["216:740485691"]="나를 다른 고블린들이 상상도 못할 만큼 엄청난 부자로 만들어 줄 새로운 차원 내파기를 방금 완성했다고! 이제 차원 분할기를 만들 실력 있는 고블린 기술자를 찾아서 분할기를 이 내파기에 연결하는 시험만 해보면 되는데!"
rows["216:961634999"]="나는 사실, 민간요법에 쓰이는 전통적인 약제를 더 좋아하지. 거머리, 구더기, 아니면 지네 같은 것 말이야. 뭐, 각자 취향에 따라 다르긴 하지만. 우리 마을 약초채집가의 이름은 파루자야. 기억해두라고. 브릴의 마구간 근처에 서있을 걸세."
rows["217:1088347545"]="이 순록의 목에는 \"멧젠\"이라는 이름의 딱지가 굴뚝나무 목장조합 로고에 달렸습니다.$B$B멧젠이 당신을 슬프고 불쌍한 눈으로 쳐다봅니다. 이 순록은 어떤 보이지 않는 힘에 의해 움직일 수 없게 된 것 같습니다."
rows["217:118812534"]="의술사 토르가쉬를 만나면 그가 만들어준 물약과 부적이 아무 효과도 없더라고 전해 주시오! 그가 말한 그대로 했지만 마가샤는 여전히 주라이한테만 관심을 보이고 있소.$B$B그 엉터리 의술사가 하는 거짓말은 절대 믿지 마시오!"
rows["217:1223829811"]="킬드라스는 상황을 너무 부풀리는 경향이 있단 말이죠. 예를 들자면 \"가로나: 은신과 기만에 대한 연구\"는 400번 넘게 도난당했던 책이랍니다.$B$B책에는 도서관의 낙인이 있어서 허락 없이 아무나 읽을 수 없지요."
rows["217:1365603724"]="불타는 군단? 악마들이요? 당신들도 그자들에게 당한 건가요? 우리 종족도 불타는 군단한테 당했습니다. 그 어둠의 지배자들에게 저주를 받았지요.$B$B<눈물을 훔치는 카우렌>$B$B그런 이유로 저는 아주 오래전에 가족과 함께 이곳으로 왔습니다."
rows["217:1599248628"]="차원문 카드를 모아 한 벌이 되면 뒤틀린 황천의 상급 다크문 카드를 보상으로 받게 될 겁니다. 이 카드는 간혹 당신이 죽었을 경우 당신의 영혼을 바로 부활시켜 주기도 한답니다."
rows["217:185852279"]="저주받을 캘타스와 악마 놈들! 우리의 노력은 수포로 돌아갔지만, 그 얼간이들은 우리가 싸움을 포기한 거로 생각하지. 이미 여군주 리아드린 님께서 우리를 위한 새로운 힘의 근원을 찾고 있소. 우리는 그렇게 쉽게 무너지지 않을 것이오."
rows["217:1883890708"]="대격변이 일어났을 때, 아제로스의 정령들에 감겨 있던 연결고리들이 심각하게 약해졌지. 그 정령 중 하나인 아쿠에멘타스는 더는 속박받지 않고 있어. 아쿠에멘타스가 남쪽바다 해적단을 위해 중대한 문제를 일으키고 있다더라고!"
rows["217:2034286133"]="벨가리스트라즈가 하는 말은 사실이지요. 시간이 없어요! 당신에게 청동용군단의 비룡을 불러내는 권한을 허락해 드릴게요. 붉은용군단이나 녹색용군단의 힘을 원한다면 벨가리스트라즈나 베르디사와 이야기하세요."
rows["217:277219885"]="당신은 안전하고 '음악'하고 싶은 새로운 보물을 가지고 있습니까? 당신은 스톤맨틀과 함께 Vault에서 저장하고 싶어 할 것입니다. 당신은 아이언포지 입구에서 해마르 던진 북동에서만 Vault 찾을 것입니다."
rows["217:279047471"]="아, 알터랙 계곡이라... 아주 즐거운 추억들이 잔뜩 있는 곳이지요. <한숨> 당신과 함께 전투에 참가할 수는 없지만 제게 자랑스러운 얼라이언스의 일원으로서 기뻐할 경사를 가져다주십시오. 그곳에 가려면 이곳 아이언포지에 있는 전투의 전당에서 글로드룸 스틸비어드와 대화해야 할 겁니다."
rows["217:289289380"]="원정순찰대의 다양한 확인 목록과 정보가 포함된 여러 양피지 중에서 단연 눈에 띄는 그림이 있습니다. 바로 소름 끼치는 트롤, 아마 여태까지 당신이 본 것 중 가장 끔찍한 생물의 모습입니다!"
rows["217:422228580"]="배탕, 항독물 등은 평야에서 살기 위해 필수적인 것들이다. 비라 영하프가 이 지식을 가르쳐 줄 수 있습니다."
rows["217:616503977"]="우 핑의 체력은 정말 놀랍습니다. 몇 시간 동안이나 넋을 놓고 우 핑이 기술을 연마하는 걸 지켜본 적이 있는데 훈련용 허수아비가 불쌍하다는 생각이 들 정도였어요. 무기를 사용한 전투 기술도 일품이니 당신에게는 최고의 스승일 겁니다."
rows["217:764667329"]="물약에 대한 지식이 나를 능가했군. 하지만 자넨 아직도 더 배울 것이 많네. 동남쪽 계단을 따라 올라가서 학자 마쉬를 만나 보게나. 그가 진정한 고통을 가르쳐 줄 걸세... 에헴! 학자 마쉬는 포세이큰으로서 자네에게 많은 것을 가르쳐 줄 것이야."
rows["217:858054505"]="놀라운 가죽... 내장을 감싸 안아 주죠. 제 피부가 별로 안 좋은 걸 눈치채셨나요? 예전엔 저도 모공 관리를 했었다니까요. 요새는 피부가 거의 남아 있지도 않죠. 어떻게 생각하면 더 자유로워진 것 같아요."
rows["218:1090737440"]="덩셔에 오신 걸 환영합니다.$b$b이 땅을 조심스럽게 걷고 스카데알드는 긴장으로 끓이고 있습니다. 에일디르와의 갈등이 증가하고 있습니다. 그레이스키의 귀족 집안에서도 목소리가 높아지고 있습니다."
rows["218:126257690"]="대지 고리회가 스톰윈드 왕궁 북서쪽 호수의 작은 섬 위에 세계 곳곳으로 통하는 차원문을 만들었습니다.\010그곳에 가면 바라딘 집행단의 대표들이 톨 바라드로 가는 운송 수단도 제공할 것입니다."
rows["218:1331411268"]="나도 하루종일 이곳에 처박혀 있지만 않다면 당신 같은 이를 가르칠 수 있을 정도로 기술을 익힐 수 있었을 거예요! 하지만 유감스럽게도 그렇지 못하니 돌발톱 산맥의 해바위 야영지로 하가스를 찾아가 보세요."
rows["218:1370091250"]="야호! 얼라이언스 연합에서 필요로 하는 두꺼운 가죽을 모두 모은 것 같네요. 정말 빨리도 모았군요. 이 주변에 당신의 도움이 필요한 이들이 있을 겁니다. 물론 본인이 도와줄 마음이 있어야겠지만요."
rows["218:1609677070"]="놈리건 작전은 성공적이었네. 물론 그 비열한 텔마플러그가 뜻밖의 속임수를 가지고 있긴 했지만, 결국 그를 도망치도록 만들었지 않은가! 이제 놈리건을 깨끗하게 정화해 다시 우리 손에 넣는 건 시간문제일 뿐이네!"
rows["218:2012880160"]="이 근처는 골칫거리뿐이야. 살딘 그 바보한테 아직 기회 있을 때 떠나라고 했는데 들은 척도 안 하더군. 하지만 난 바보가 아니지. 마차만 고치면 버나랑 당장 여길 뜰 거야."
rows["218:2087518488"]="매주 낚시왕 선발대회가 열리는 무법항에 오신 걸 환영합니다!\010대회가 시작되면, 가시덤불 골짜기 전역의 낚시터에서 맛둥어를 낚을 수 있습니다."
rows["218:265545383"]="생선을 포함한 모든 물자들을 실리더스로 수송하는 중인데 $2113w일 내로 도착할 겁니다. 그런 다음 누군가 흐르는 모래의 홀로 징을 울리면 전쟁이 시작될 거예요."
rows["218:511821714"]="망할 거미들, 끊임없이 소리를 질러 대는 박쥐들, 그리고 그 저주받은 악마의 짐승들은 모두 하인 숙소에 살고 있어. 더는 안심하고 주변을 돌아다닐 수가 없단 말이지. 특히 큰 녀석들이 나오는 날에는 더욱 위험하오."
rows["218:952400187"]="저는 그저 재봉술을 조금 아는 평범한 사람에 불과합니다. 당신은 제가 지닌 기술보다 더 많은 것을 배워야 합니다. 스톰윈드 마법사 지구에서 상당히 솜씨 좋은 나이트 엘프 재봉사가 산다고 들었습니다."
rows["219:1430522744"]="심판관 마리엘 트루하트 님께서, 이제 원형경기장이 완성되었으니 마상시합을 운영하고 지키는 걸 도와 달라고 하셨습니다. 하지만 저 무능한 은빛 서약단과 함께 일하라고 하시더군요. 녀석들이 얼마나 방해가 되는지 모릅니다."
rows["219:1627397187"]="내가 더는 친절하거나 겸손하지 못할까 걱정이군. 세월과 끝없는 전쟁으로 내 몸뚱이와 영혼이 모두 굳어버린 듯하군. 어쩌면 그 때문에 케른 님께서 날 해바위 야영지로 보낸 것인지도 모르지... 부드러운 바람과 따뜻한 햇살이 고통을 덜어주는구려."
rows["219:1885136038"]="드루이드들은 엄청난 힘의 원천을 뽑아냈어요! 그들은 동물로 변신할 수 있고... 번개와 강렬한 달빛을 쏠 수도 있죠. 저는 그들이 가진 능력의 비밀을 밝혀내고야 말 거예요!$B$B혹시 로브 안에 충전지를 착용하고 있는지도 몰라요..."
rows["219:2087910810"]="남쪽바다 해적들이 요전에 부두에 나타났다고들 하더군요. 마을에 내려가실 땐 조심하세요!$B$B여자 해적들도 있답니다! 음, 아무래도 제가 직접 나서는 게 좋을까요? 당신의 안전을 위해서 말이죠."
rows["219:253786122"]="불타는 평원에 추가 지원군이 도착하지 않는다면 스컬지가 그곳에 작전 기지를 세우게 될 겁니다. 가능하다면 당신이 그곳으로 가서 수비를 도와주셨으면 합니다.$B$B남아 있는 죽음의 요새: $2281W개"
rows["219:272499379"]="분노. 지금 상황에서 내 감정은 그 단어로밖에 설명할 수 없소. 우리는 죽을 힘을 다해 숲을 헤치고 해변으로 나왔지만, 이미 때는 너무 늦어 있었소. 집으로 돌아갈 수 있는 유일한 수단이 파괴된 것이오."
rows["219:414266956"]="킬드라스는 상황을 너무 부풀리는 경향이 있단 말이죠. 예를 들자면 \"가로나: 은신과 기만에 대한 연구\"는 400번 넘게 도난당했던 책이랍니다.$B$B책에는 도서관의 낙인이 있어서 허락 없이 아무나 읽을 수 없지요."
rows["219:568382319"]="여긴 정말 끔찍한 땅입니다! 질척질척하고, 온통 나무 그루터기랑 바위 때문에 울퉁불퉁합니다. 새알심 넣은 팥죽처럼 말이죠. 진흙이 말 그대로 증기 전차를 삼켜 버린다고요.$B$B우리 장비가 전부 진흙탕 속에 빠져서는 호드한테 두들겨맞고 있단 말입니다!"
rows["219:590941391"]="<다시 한 번 손을 내려다보는 발드레드>$b$b아무래도 이게 내 운명인가 보군. 하! 언데드 군단의 일원이라니. 어쨌든 내가 포세이큰을 위해 싸우는 처지가 될 줄은 정말 생각해본 적도 없소.$b$b<당신을 되돌아보는 발드레드>$b$b이제 뭘 해야 하오?"
rows["219:955550934"]="놈리건 작전은 성공적이었네. 물론 그 비열한 텔마플러그가 뜻밖의 속임수를 가지고 있긴 했지만, 결국 그를 도망치도록 만들었지 않은가! 이제 놈리건을 깨끗하게 정화해 다시 우리 손에 넣는 건 시간문제일 뿐이네!"
rows["21:1123268456"]="라제에게 뭘 원하나?"
rows["21:1160477161"]="언제나 평정심을 잃지 마십시오."
rows["21:1188079440"]="타바드 찾고 있나요?"
rows["21:1244167165"]="어떻게 도와드릴까요?"
rows["21:1281246010"]="반갑습니다. 잘 지내고 계십니까?"
rows["21:1404131198"]="어떤 종류의 무기 상인을 찾으시나요?"
rows["21:1666657035"]="승강기를 보낼 곳을 선택합니다."
rows["21:1830243472"]="우리 숙성된 노른자위 먹으러 가?"
rows["21:1853260482"]="테라모어에 온 것을 환영하는 바이오."
rows["21:1972844029"]="중앙 링, 가!"
rows["21:257419074"]="개인 신화 정보:"
rows["21:388038742"]="무슨 일로 오셨나요?"
rows["21:543389112"]="*그르르르* *멍* *멍*"
rows["220:1447876497"]="타렌 제분소는 이 숲 바로 너머에 있소. 던홀드 요새에 소란을 일으키면 마을 전체에 인간 병사들이 넘쳐나기 전에 타레사를 구할 시간을 조금 벌 수 있을 것이오. 가까운 헛간을 수색한 다음 마을로 향하도록 합시다."
rows["220:426386168"]="<엘프는 불안해 보이는데, 그의 얼굴은 걱정으로 뒤덮여 있다. 긴장된 시선이 있고,  ⁇ 돌린의 조용한 모습은  ⁇ 돌린의 침묵과 대조적으로 나타난다. 그가 누구든, 그는 이 곳을 도달하기 위해 먼 길을 걸었다.>"
rows["220:527293202"]="언더시티의 왕립 연금술 학회는 이곳 아웃랜드의 오크 동맹들을 돕고자 하네. 우리 호드 연합의 결속을 강화하고 새로운 종족이나 혼합물 같은 연구 대상을 찾을 기회이지.$B$B예를 들면... 독 같은 거 말일세."
rows["220:588692507"]="빛 앞에 기원을 드리러 온 것이오? 아니면 신성한 능력을 훈련하러 왔소?$b$b대주교 베네딕투스 님과 이야기를 나누러 온 것이라면 미안하지만 그분은 지금 임무를 수행하러 떠났소."
rows["220:599937412"]="음... 머리가 아주 좋은 친구로군. 당신이 나보다도 많이 알고 있는 건 인정하지! 자만하라고 하는 말은 아니지만 계속해서 배우고 싶다면 스톰윈드에 있는 조르지오 볼레로와 얘기해 보시오. 재봉술만큼은 아주 제대로 알고 있는 친구니까!"
rows["220:60204934"]="아시디시피 갑옷 제작은 제 열정입니다. 살아 있을 때나 죽었을 때나 갑옷 제작은 제가 가장 좋아하는 일이지요. 부디 저를 살아 있는 드레나이라고 생각해 주십시오. 제가 다시 한 번 느낌이라는 게 뭔지 알 수 있도록 해주십시오... 당신의 물건을 수리할 수 있는 영광을 제게 주십시오."
rows["220:648872915"]="우리가 맞서 싸우는 생물체의 영혼, 즉 \"뮤세크\"에는 엄청난 힘이 담겨져 있지.$B$B자신을 돌아보고 자신의 고유한 영혼의 힘을 다루는 방법을 익히도록 하게. 그러면 자네는 자네가 상상했던 것 이상의 힘을 갖게 될 것이야."
rows["221:1247572034"]="내가 고대 드레나이 수정과 유물에 대해 알고 있기 때문에 일리다리 악마들은 내가 이곳에서 떠나지 못하게 하고 있소.$B$B녀석들은 우리 종족들을 노예로 부려서 강력한 수정을 찾는 데 동원하고 있소이다... 이곳에는 십중팔구 수정이 없을 것 같은데 말이오."
rows["221:1738331654"]="적들이 우리 마을을 둘러싸고 있네. 난 모크나탈을 위해 더 열심히 싸울 걸세. 그런데 우리와 싸우는 적의 군대는 다른 방법을 선택했지.$B$B자네가 모크나탈에 필요한 존재라는 걸 증명하고 싶다면 우리가 적을 물리칠 수 있도록 도와줘."
rows["221:1768115984"]="제목에 따르면 저는 붉은십자군의 암살자입니다. 저는 하루를 보내고 고위 우선순위 목표물을 멸하고 밤은 가젯잔 디스코테이크에서요. 춤은 저의 진정한 직업입니다. 암살은 단지 계산을 지불합니다."
rows["221:259731690"]="네파리안의 유적에 대해 마스터가 큰 관심을 갖고 있습니다. 만약 누군가가 용과 그의 하역들을 물리치고 왕자에게 이야기를 다시 말해준다면, 왕자의 입술이 느슨해질 것입니다."
rows["221:400436341"]="아, 우리 짝지는 그대를 해치지는 않을 테니 신경 쓰지 않으셔도 됩니다. 저 녀석은 그냥 여기저기 긁는 것을 좋아할 뿐이랍니다.$B$B우리 짝지는 단지 덩치 크고 사랑스러운 고양이일 뿐이죠.$B$B그렇지 않니, 짝지야? 물론이고말고. 너는 내 귀여운 고양이잖니. 너는 이 엄마의 사랑스러운 아기란다!"
rows["221:437256072"]="돌에서 울리는 거침없는 목소리...$B$B난 당신의 역의 메달리온을 감지하고 이교도당신은 정말 Twilight's Hammer의 지휘자입니까 아니면 단지 더 나은 사람들을 위해 일하러 다니나요?"
rows["221:737210113"]="로데론이 무너질 때 여기에 있는 친척을 방문하던 참이었다오. 그리고 그때... 글쎄올시다. 이제 서부 몰락지대로 돌아가지는 않을 것 같소.$B$B가끔 두고온 가족들이 아직 살아 있는지 궁금하기는 하오. 그것보다 더 자주 드는 궁금증은, 왜 내가 더는 신경조차 쓰지 않는 지라오."
rows["222:1138562504"]="마지스퀘어에서 숨겨진 작은 가게는 알케미 니즈라고 합니다. 마지스퀘어를 지나가면서 모든 종류의 이상한 가게를 보게 될 겁니다. 하지만 바깥쪽 면에 붙어 있으면 찾을 수 있을 겁니다."
rows["222:1186485200"]="다른 사람이 오기까지는 시간이 지나야 합니다.$b$b두려워하지 마, 나 아들라진, 부원사미의 사제입니다. 죽음의 왕이 직접 나를 보내서 히리크, 다ంబ라, 엘로타 노 샤드라의 위험한 야망을 해소하도록 보냈습니다."
rows["222:1225759315"]="늘 어둡고 사악한 생각에만 빠져 있는 패거리들을 찾으려면 아이언포지의 어두운 곳을 찾아가야지. 쓸쓸한 뒷골목이라고 이름도 아주 그럴듯하지? 그곳에 가면 시슬하트라는 녀석이 사악한 악마를 불러내어 부려 먹고 있을 거야."
rows["222:1504805381"]="오해하지 마십시오. 저도 실리시드가 우글거리는 터널에 온종일 갇혀 있고 싶지는 않지만, 여기 숨어서 이 벌레들의 움직임을 감시하는 것이 우리의 승리에 도움이 된다면 며칠이 걸리든 그렇게 할 겁니다."
rows["222:1605820656"]="믿어져? 드디어 이곳에도 승강장이 세워져 비행선을 운행할 수 있다고! 이제 비행 금지 구역은 안녕이야. 내 말이 맞지? 시험 운행을 하는 동안 벼랑에 추락한 비행선은 딱 한 대뿐이었어. 왜 그렇게들 걱정하는지 이해가 안 간단 말이야."
rows["222:172713747"]="가즈리디안이 더 있다고? 도대체 자네는 내가 왜 그 지긋지긋한 물건을 더 가지고 싶어한다고 생각하는 건가? 한 9,000개쯤 가지고 있는데, 전혀 안 팔린단 말이야! 왜 나는 커다란 뱀 동상이라면 누구라도 좋아할 거라고 생각한 거지? 쳇!"
rows["222:1759913445"]="출격실로 갈 수만 있으면 좋겠어요. 그 어여쁜 비행기가 정말 딱 한 대만 있으면, 제 손으로 놈리건을 되찾을 수 있어요! 물론 B.E 버랙허스가 눈알이 빠지도록 겁에 질리게 할 수 있고요!$B$B상상해 보세요..."
rows["222:2037248711"]="하로우의 끝에서 우리는 바시 여왕이 직접 우리를 리치 왕와 스컬지의 손잡기에서 구출한 날을 축하합니다. 매일 저녁 언더시티 밖에서 열리는 위커먼 페스티벌에 참석하는 것을 확인하십시오."
rows["222:2098802165"]="어떻게 하는지 모르겠지만, 그 우편 상자는 마법의 포털이거나 그런 거 같네요. 왜 전 하루 종일 은행 옆에 있는 우편 상자 주변에 모여있는 사람들을 보고 있는데요."
rows["222:302634468"]="달라란 중앙의 북쪽, 요술쟁이 휴게실이라는 달라란에서 가장 유명한 여관이 있습니다.$B$B얼라이언스와 호드 지구에도 여행자들이 이용할 수 있는 여관이 있지요. 또한 달라란 아래 하수도에 다른 여관이 있다고 들었습니다."
rows["222:698242605"]="죄송하지만 당신만큼 경험이 많은 분에게는 제가 가르쳐 드릴 게 없군요. 하지만 당신이 배워야 할 건 아직 더 남아 있으니 저기 카운터 뒤에 있는 루칸 코르델과 얘기해 보세요. 당신 여정의 다음 단계를 안내해 줄 거예요."
rows["223:1325002547"]="나는 무역연합의 대리인으로서 언제나 우리 사업의 추이에 대해 깊은 관심이 있소이다.$B$B블러드 엘프들이 협력 관계를 성실하게 수행하지 않아 정말 유감이오."
rows["223:1350529536"]="아, 저항할 수 없는 유혹이겠지. 그렇지 않나? 좀 더 빠르고 강해지고 싶겠지? 여기 이 아뮬렛을 하나 걸기만 하면 분명 그렇게 될 거야. 어서 이 신비한 물건을 하나 장만하게! 아주 싸게 줄 테니까!"
rows["223:1464367817"]="안녕하십니까, 이방인 친구. 야생이 살아 숨 쉬는 운고로 분화구에 온 것을 환영합니다! 저는 윌리덴 마샬이라고 합니다. 저와 제 여동생, 그리고 동료는 마샬 원정대를 구성하고 있습니다. 우리는 위대한 아제로스의 야생과 미지의 세계를 탐험하는 과학자와 탐험가들이죠."
rows["223:1686447371"]="샤트라스의 전투모병관들은 도시 상층부와 고난의 거리를 연결하는 계단에서 자주 모임을 한답니다. 얼라이언스 전투모병관들과 호드 전투모병관은 각기 다른 곳에서 모여 있으며, 투기장 사무관은 전투모병관들의 맞은편에 있습니다."
rows["223:1712817962"]="스랄의 탈출을 도와주셔서 감사합니다, 여러분. 이제 저도 좀 도와주실 수 있을까요? 오늘 아침에 일어나보니 이 마법 감옥에 갇혀 있는 것을 알게 되었습니다. 한 이상한 마법사가 한동안 여기 갇혀 있어야 할 거라고만 말했답니다."
rows["223:1952414088"]="검은바위 오크들하고 계약하긴 쉽지가 않다고. 이봐, 무슨 뜻인지 잘 알잖아! 검은바위 오크란 말이야! 그자들은 아그라마르보다 더 많은 전투를 치른 데다가 그것도 검은무쇠 부족이 만든 산에 진 치고 있다고! 와우!"
rows["223:365146073"]="넌 너의 능력을 증명했다. 아주 뛰어난 능력이지. 우리를 대신해 소용돌이벌레를 처리해다오. 무너지는 심연으로 들어가라. 우리는 심연으로 들어갈 수 없지만 너라면 가능할 것이다."
rows["223:497847642"]="야수를 다루는 방법에 대해서 한두 가지는 아는 것 같지만 말입니다, 하늘을 나는 녀석을 다뤄본 적이 있나요? 우리 와일드해머 드워프들은 누구에게도 뒤지지 않게 하늘을 나는 법을 알고 있지요. 당신 꽤나 기개가 있는 친구이니 약간의 수업료만 내신다면, 제가 하늘을 나는 좋은 방법을 정확하게 알려드리겠습니다."
rows["223:808392313"]="무기를 다루는 기술은 안세크화를 따라올 자가 없습니다. 우리 선조 중에서도 최고로 뛰어난 전사의 영혼이 안세크화를 이끌어 주고 있다고 합니다. 수렵의 봉우리에 가서 안세크화를 찾아보십시오. 당신이 알고 싶어하는 것을 가르쳐 줄 것입니다."
rows["224:1185400521"]="'젊은 형제'라고 말 할 때, 우리 는 쌍둥이라고 언급 하지 않습니다. 사실, 그는 몇 분 정도 더 나이가 들어 있습니다.$B$B그 '어림하는 별'의 속임수가 당신을 속이지 못하게 해"
rows["224:1335835878"]="<고등검찰 페어뱅크스 주관합니다>$B$B아, 저자 모그라인, 스카르렛 지휘관으로 알려진 그는, 내가 의심하는 것 처럼, 대 십자군의 대행을 통해"
rows["224:1697210978"]="황혼의 망치단은 무시할 수 없는 강력한 조직이다. 우리 덕분에 데스윙 님이 풀려나셨다. 우리 덕분에 고대 신들이 대지 깊은 곳에서 깨어났고, 또 우리 덕분에... 하이잘이 불타고 있지.$B$B넌 우릴 위해 뭘 할 수 있나?"
rows["224:1747902909"]="엄청난 도전이 눈앞에 닥쳐왔습니다. 지맥 수호자 에레고스는 막대한 힘을 가진 푸른용입니다. 가장 높이 있는 고리 위를 보면 그가 날아다니고 있을 겁니다. 그대의 비룡은 이제 최고의 힘을 사용할 수 있습니다. 그 힘을 사용해 에레고스를 격파하십시오!"
rows["224:1753487222"]="네싱워리 님께서는 큰 놈을 잡을 준비를 하고 계십니다. 사실 전 전투보다는 사냥 준비를 돕는 게 훨씬 더 마음 편하더군요... 가끔 전장의 영광스럽던 순간들이 그립긴 하지만 말입니다."
rows["224:2032403633"]="모험가들은 싸우고 죽고 파괴하고 부상을 하고, 꺾고 태우고 싶어합니다.$B$B당신을 싸우지 않고 여왕을 위해 적당한 전투를 하지 않습니다. 여왕은 감시하고 지휘하고,"
rows["224:20558965"]="다른 시대, 다른 곳에서 태어났다면 나는 아마 애송이 취급을 받았을 겁니다. 하지만 이곳에서는 나루의 영광을 위해 목숨을 바칠 각오가 된 숙련된 전투병이지요.$B$B우리 중 수십 명이 아라 마나괴철로 안으로 들어갔습니다. 그리고 다른 이들은 모두 불타는 군단에게 당했지요."
rows["224:229011283"]="낚시의 달인이여, 만나서 반갑습니다! 아제로스 최고의 낚시꾼들과 솜씨를 겨뤄 보고 싶다면 잘 들으세요! 바로 이번 일요일에 가시덤불 골짜기에서 낚시왕 선발대회가 열린다니까요!"
rows["224:3689772"]="알랏신은 수백 년 동안 사냥꾼이 길들인 야수를 돌봐왔습니다. 이 부근 사냥꾼들은 알랏신의 손길을 많이 찾지요. 그대도 알랏신을 찾는 거라면 세나리온 자치령으로 가보시기 바랍니다."
rows["224:46766181"]="거의 해냈습니다!$B$B저는 전설적인 곰팡이 거인, 쿠아그미란의 존재를 증명하기 위해 여기 왔으니 소원은 이룬 셈이군요.$B$B저 좀 풀어 주십시오! 풀어 주신다면 보답으로 쿠아그미란 처치를 도와드리겠습니다."
rows["224:485973491"]="오, 제가 요리를 잘한다고요? 그렇다고 할 수도 있겠지요. 선술집에서 일하다 보면 주방에도 때때로 들어가는 법이라서 수년간 꽤 여러 가지 조리법을 배웠답니다. 특이한 요리는 없지만 그록의 퉁퉁한 배를 채우기엔 충분할 테지요."
rows["224:687463859"]="서부 몰락지대에 사악한 타락의 기운이 스며들었습니다. 내가 로데론의 전장에서 임무를 수행하는 동안, 정직한 농부들의 터전은 악당과 살인마들의 소굴로 변하고 말았지요. 인민군에 당신의 도움이 필요합니다."
rows["224:947551400"]="오크와 타우렌은 서로 만나게 된 행운이 있습니다. 왜냐하면 각 민족의 강점은 다른 민족을 칭찬하기 때문입니다.$B$B심지어 포세이큰 참여, 하지만 어떤 목적을 위해 나는 확실하지 않습니다 ..."
rows["225:1092484784"]="황혼의 망치단은 무시할 수 없는 강력한 조직이다. 우리 덕분에 데스윙 님이 풀려나셨다. 우리 덕분에 고대 신들이 대지 깊은 곳에서 깨어났고, 또 우리 덕분에... 하이잘이 불타고 있지.$B$B넌 우릴 위해 뭘 할 수 있나?"
rows["225:156807034"]="이 사람에 대해 몇 가지 불만이 제기됐는데, 그는 좀 더 유연한 성격이라고 전해졌어요."
rows["225:1768116523"]="나는 수년 동안 우리가 실버문에서 옳은 일을 하고 있다고 확신했소. 우리는 아웃랜드에 도착해서 다시 캘타스와 합류하기 위해 열심히 일했지.$B$B우리를 위해 캘타스가 뭘 준비해 놓았었는지 알았더라면 난 매날개 광장에 머물러 있었을 것이오."
rows["225:1771633717"]="알다시피 토림은 저자들과는 다르다. 그분은 신과 같은 존재에 걸맞다.$B$B그는 창조주의 거처와 울두아르의 수호자로서 티탄을 위해 일했었다. 토림의 아내인 시프가 그의 형제에게 비겁하게 살해당하기 전까지 말이지."
rows["225:36294454"]="서리늑대 요새는 알터랙 계곡의 남쪽 구석에 자리하고 있으며, 오크족의 고향인 서리늑대 마을을 방어하고 있습니다. 알터랙 계곡의 모든 호드 영토는 이곳을 거점으로 뻗어나갑니다.$B$B서리늑대 요새는 안전합니다."
rows["225:375140596"]="내가 채널을 할 때마다 내 몸이 약해지는 것을 느낀다 빛하지만 이 모든 사람들을 보고, 땅 속에 있는 관에 갇혀, 죽은 자 가운데 살아서 얼마나 오랫동안 묻혔는지 누가 알겠어...$B$B조금은 고통은 그들의 마음을 진정시키는 가치가 있습니다."
rows["225:603144994"]="드라카리들이 자신들을 이렇게 파괴하는 걸 보면 안타까울 따름이네.$B$B이 땅에 깃든 자연의 신을 죽여 얻은 힘은 일시적인 것에 불과하지.$B$B그렇게 짧은 시간에 얻은 것은 결국 영원히 사라지고 말 걸세."
rows["225:623294623"]="자, 너  ⁇ 디의 아보레텀을 보고 싶어. 내가 방금 말했어? 글록타르 난 피곤해야 해. 지혜의 계곡에 있는 아소란 시장 뒤에 있는 나무 계단을 따라 드래그로 올라가면  ⁇ 디가 상단층에 있을 거야."
rows["226:1202658427"]="무슨 일로 오셨나요? 그대는 지금 수송관에서 작업을 하고 있어야 할 시간 아닌가요?$B$B폭풍우 요새로 보내는 에너지의 양을 두 배로 늘렸기 때문에 빈둥거릴 여유가 전혀 없단 말입니다. 이곳에서 또다시 울트리스와 같은 일이 벌어져서는 안 됩니다."
rows["226:1501658986"]="마법사 우롬은 세 번째 반지를 보호합니다. 그는 혼자와 무력으로 보일 것입니다. 그러나 외모로 속이지 마십시오! 우롬은 강력한 마법사입니다."
rows["226:1529972275"]="네페르세트는 요즘 움직이지 않고 있습니다. 하지만 최근 오르시스가 사상 최악의 거대한 모래 폭풍에 의해 피해를 입었다는 보고를 받았습니다.$B$B제가 직접 이 소식을 왕께 보고할 생각이었습니다만, 당신이 전해주실 수도 있겠군요."
rows["226:1637441990"]="자네가 '정식으로 수입된' 우리 경주용 산양을 살펴보는 걸 봤네... 산양 경주의 열정에 빠지고 싶어하는 거 다 보인다고... 하지만 놀고 싶으면 먼저 일을 해야지.$b$b한데, 이 산양을 탈 수만 있다면 일이나 노는 거나 비슷하다고."
rows["226:1857720321"]="만약 당신이 브루페스트 상권에 충분한 돈을 벌면, 브루페스트 캠프의 티켓 구상자는 당신에게 \"공예 브루어\"의 손표를 줄 수 있습니다.$b$b그 표지가 브루페스트 승마 양을 팔 수 있게 해 줄거예요"
rows["226:1966603276"]="최근까지 우리 오합지졸 병력이 여기에 있었다는 사실이 믿어지십니까? 대부분 도움이 되기보다는 문제를 더 많이 일으킵니다. 그대와는 매우 다릅니다.$B$B그런데 정말로 원정순찰대에 가입하지 않으실 겁니까?"
rows["226:205764334"]="벨가리스트라즈의 말이 옳아요. 상황이 매우 심각하답니다. 저는 그대에게 녹색용군단의 비룡을 불러내는 능력을 드릴 수 있지요. 붉은용군단이나 청동용군단의 힘을 원한다면 벨가리스트라즈나 이터노스와 이야기하세요."
rows["226:2109234305"]="<당신이 다가가자 이 나이트 엘프가 당신 쪽으로 몸을 돌려 손을 잡으려고 합니다.>\010이미 늦었어요. 우린 자긍심으로 우리 운명을 결정할 자격을 얻었어요. 가세요... 다른 이들을 살릴 수 있을지 몰라요. 구할 수 있는 자들을 구해주세요.\010<그녀에게서 생명이 스르르 빠져나가듯 당신을 움켜쥔 그녀의 손이 느슨해집니다.>"
rows["226:303602902"]="그롤다르와 검은불꽃 비밀집회를 찾는 건가? 어둠의 틈이라는 지하 동굴에서 찾아보게. 그 동굴로 내려가는 지하도는 두 개가 있는데, 하나는 지혜의 골짜기 바로 남쪽에, 다른 하나는 골목길에 있지."
rows["226:401304857"]="그립타로 알려진 상인이 사기 행위로 도시에서 쫓겨났습니다. 그자가 팔던 잡동사니를 자세히 조사해야 합니다. 이 물건들을 건드리지 마시고 저희가 조사를 계속하게 해 주십시오."
rows["226:560181027"]="내가 원했던 건 다시 한 번 내 왕을 섬기는 것뿐이었소. 인류를 위해, 인류의 공적에 맞서 싸우고 싶었지.$B$B하지만 우리는 이교도들에게 제압당했고... 이 타락의 근원이 되는 모든 징조가 낙사나르를 향하고 있소."
rows["226:758810999"]="당신에게 대장장이의 피가 흐르고 있다고 말한 적이 있었지. 역시 내 말이 옳았소. 아이언포지의 대용광로로 가서 벤구스 딥포지라는 이름의 드워프 대장장이를 한번 찾아보시오. 내 스승이자 내가 아는 한, 최고의 대장장이니까."
rows["227:1000527174"]="빠르고 안전한 이동 수단을 찾으신다면 제대로 찾아오신 겁니다! 올해 신형 기계타조 모델이 최근에 들어왔어요, 왔어. 전부 다 보여 드리도록 하죠!"
rows["227:1154306512"]="목걸이를 되찾은 여군주 실바나스가 자네에게 어떤 반응을 보였는지는 정보통을 통해 이미 들었네. 아직도 난 자네가 옳은 일을 했다고 믿고 있으니까 그녀의 반응에 너무 신경 쓰지는 말게.$B$B이제 용건을 말해 보게나."
rows["227:1210515491"]="장창 다루는 법이라면 포세이큰 무기 전문가, 아키발드가 최고지. 언더시티의 군사 지구에서 제자들을 가르친다네. 실버문의 원정순찰대 광장에 있는 블러드 엘프 무기 전문가, 일레다도 쓸만한 장창 기술을 알고 있지."
rows["227:1341810736"]="붕대라고 했나? 에... 그러니까, 마지막으로 들은 내용을 떠올려 보면 얼라이언스는 리넨 붕대 $2077w개 중 $2076w개, 비단 붕대 $2083w개 중 $2082w개, 룬무늬 붕대 $2090w개 중 $2088w개를 모은 것 같네."
rows["227:2008161370"]="한디르와 불리위프가 철퇴가 얼마나 크건 간에 상관없이 철퇴를 올바르게 휘두르는 법에 대해서 알려줄 것입니다. 아이언포지의 잘나가는 무기 상점에 있는 불스위프를 찾을 수 있을 겁니다. 한디르는 엑소다르의 교역 지구에서 드레나이들을 가르치며 그의 일과를 보내고 있습니다."
rows["227:264314730"]="제 잘못이 아닙니다... 제 잘못이 아니라고요!$B$B제가 하라는 대로만 했으면 괜찮았을 겁니다. 하지만, 그러지 않았죠! 제 말은 조금도 들으려 하지 않았습니다.$B$B결국 그들은 모두 죽었습니다.$B$B집으로 돌아가고 싶습니다. 실버문으로 돌아가고 싶어요. 너무 지쳤습니다."
rows["227:358476135"]="나가가 우리를 살려두다니 정말 이상한 일이었네.$b$b나가들은 신비한 진주 감옥을 만들어 우리를 가두었지. 그 안에서 숨을 쉴 수는 있었지만, 그것뿐이었다네.$b$b그 후 나가들은 포로를... 어딘가로 보냈지.$b$b그 포로들은 다시는 볼 수 없었네..."
rows["227:423507418"]="우리는 어느 정도 짐토르가에서 보호받을 수 있지만, 스컬지가 있고 드라카리는 각종 만행을 저지르기 때문에 크게 약해졌네.$B$B이제 나와 아훈네가 그 몫을 해내야만 하지."
rows["227:666302747"]="<당신을 바라보며 으르렁대는 랩터의 입에서 침이 흘러내립니다.>$B$B<9번 실험체는 그간의 행적을 은폐하고자 지능이 증폭되지 않은 자신의 복제 생명체를 남기고 간 것 같습니다. 영리한 친구 같으니! 당신은 우주로 내보낸 존재에 대해 다시금 깊은 생각에 잠깁니다...>"
rows["227:726125234"]="불타는 군단의 마수에서 벗어난 지 얼마나 지났다고 다시 악마들과 손을 잡으려는 건가? 흠, 어둠의 틈이라는 지하 동굴에 있는 검은불꽃 비밀집회를 찾아가보게. 골목길에서 그곳으로 내려가는 지하도가 있다네."
rows["227:756935068"]="알터랙 계곡은 오랜 세월 동안 서리늑대 부족의 고향이었습니다. 절대 드워프 놈들과 얼라이언스가 차지하게 둘 순 없어요! 전쟁을 벌여야 합니다!$B$B던 발다르에 있는 반다르 스톰파이크 사령관을 처치하면 알터랙 계곡은 우리 것이 되는 겁니다.$B$B호드를 위하여!"
rows["227:835452108"]="한 때는 아름다웠던 이 숲이 끔찍한 저주에 걸려 고통받고 있어요! 타락한 세력이 이곳 생명체들을 변형시키고 있답니다. 자신들의 모습을 닮은 어두운 그림자로 만들려는 것 같아요. 당신이 이 타락의 앞잡이가 아니라면 저를 도와 악령숲을 정화할 수 있을지도 모르겠군요."
rows["227:964990763"]="벨가리스트라즈의 말이 옳아요. 상황이 매우 심각하답니다. 저는 그대에게 녹색용군단의 비룡을 불러내는 능력을 드릴 수 있지요. 붉은용군단이나 청동용군단의 힘을 원한다면 벨가리스트라즈나 이터노스와 이야기하세요."
rows["228:1315563297"]="저도 모르겠어요. 아마 골밀도가 낮은가 봐요. 아니면 폐활량이 보통 이상이던가요. 어쩌면 점심으로 먹은 치즈 때문일지도 모르죠.$B$B어떻든간에, 이 조개껍데기는 제가 수면으로 튕겨 나가지 않는 유일한 이유랍니다."
rows["228:1401238474"]="이건 당신에게만 하는 얘긴데, 실은 여기 계신 장군님이 임무를 수행할 마음이 별로 없으신 듯합니다.$B$B우린 지금 호드를 상대하고 있지 않습니까? 역사에서도 평화는 찾아볼 수 없습니다.$B$B우리는 호드의 전멸을 목표로 해야 한단 말입니다."
rows["228:189084540"]="알레고른은 수백 년 동안 요리 기술을 갈고 닦았지요. 그런 노련한 요리사에게 기술을 배울 수 있다면 정말 축복이라 여기십시오. 만약 그대에게 그럴 자격이 충분하다고 생각하거든 장인의 정원으로 찾아가 보십시오."
rows["228:1989361317"]="일을 제때 마무리하려고 내가 여기 나와 있는거야.$b$b무법항은 해일에 입은 피해도 미처 다 복구하지 못했다고!$b$b사납게 날뛰는 트롤 패거리와 좀비 트롤만도 끔찍한데, 독사하고 미친 표범까지 우릴 공격하는 일은 없었으면 좋겠어."
rows["228:2064562785"]="이 책은 아웃랜드의 다양한 식물 종에 대한 정보를 담고 있습니다. 대부분은 장가르 습지대의 토착 식물입니다.$B$B도표와 그림은 당신이 이해하기에 다소 어렵습니다. 아마도 책의 저자가 당신에게 조언을 줄 수 있을 것입니다."
rows["228:576100609"]="혼돈을 위해 존재하는 그것의 아주 작은 속삭임은 온 세상에 파멸을 불러왔습니다!$B$B그럼에도 아무것도 개의치 않는 이 존재를 숭배하려는 자들이 있었으며, 이 존재를 자기 마음대로 조종하려는 미치광이들마저 나타났습니다."
rows["228:576100622"]="혼돈을 위해 존재하는 그것의 아주 작은 속삭임은 온 세상에 파멸을 불러왔습니다!$B$B그럼에도 아무것도 개의치 않는 이 존재를 숭배하려는 자들이 있었으며, 이 존재를 자기 마음대로 조종하려는 미치광이들마저 나타났습니다."
rows["229:1036410759"]="드워프 가열로의 그윽한 연기 냄새가 나지 않으세요? 대장기술을 배우고 싶으시다면 테룸 딥포지를 찾아가셔야 해요. 대성당 광장 바로 북쪽에 있는 드워프 지구에 있습니다."
rows["229:1189501514"]="네, 맞아요. 그 남자는 달라란의 마법사가 아니었어요. 그의 옷은 상당히 이국적이고 억양도 생소했답니다. 그가 중얼거리던 말이라고는 시간이 어쩌고저쩌고하는 것뿐이었어요. 그 마법사를 찾아서 절 풀어 주라고 설득해 주세요."
rows["229:1336806675"]="어머니를 대신해 복수하고 싶습니다!\010어머니를 해한 괴물의 주의를 끌고, 저희를 이 우리에서 풀어 주십시오. 그러면 당신의 곁에서 싸우겠습니다.\010적이 가하는 피해를 줄여 주는 저희의 능력은 원시거룡의 그을리는 숨결을 견디는 데 도움이 될 겁니다."
rows["229:1365557166"]="니비로 왔는데 지옥의 종을 몰아내는 비밀을 알아내려고요$B$B니비가 모든 걸 알고 있어$B$B니비는 그런 지식을 빨리 받아들이지 않아 먼저 니비에게 중요한 일을 도와줘야 해"
rows["229:1632129802"]="2년마다 경쟁의 영들이 더욱 열렬해지고... 이제 그 때가 되었습니다! 얼라이언스와 호드 모두 이 태블드를 전투장에 착용하여 영들을 기리기 위해 모든 적들을 물리치고 그들의 호의를 얻으려고 합니다."
rows["229:663912990"]="좋습니다, 친구! 빛은 가져오셨지요? 무슨 일이 생기든 간에 그걸 꽉 잡고 계셔야 합니다.$B$B준비됐다고 말씀만 하시면 영혼의 세계로 들여보내 드리지요. 거기 가시면 영혼들이 당신을 쫓으며 어둠 속으로 끌어들이려 할 겁니다.$B$B그런 고약한 영혼들에게는 빛을 비추세요!"
rows["229:766578587"]="안녕하신가! 가시덤불 골짜기에서 열리는 멋진 낚시왕 선발대회 홍보차 들렀네! 참가 자격은 가시덤불 골짜기에서 생존할 만큼 강하고 배짱 있는 자, 그리고 그곳 수역에서 낚시 좀 할 만한 기술을 갈고 닦은 자에게 주어지지.$B$B기량을 좀 더 닦거든 다시 오게나!"
rows["229:933344320"]="계곡에서 하피 무리가 내려왔다네. 시라나라는 큰 하피 하나가 무리를 이끌고 있었지... 도망갈 곳이 없었다네. 하피 무리가 이렇게까지 공격적인 건 오랫동안 본 적이 없어... 그래서 방심했네... 제대로 몸을 지키지 않았어... 내가 잘못한 걸세."
rows["22:1058950234"]="왜 나를 방해하는가?"
rows["22:1085872562"]="뭘로 드릴까요?"
rows["22:1114631781"]="[펄볼그어] 보로 곰쇼오!"
rows["22:1168076119"]="어디로 모실까요?"
rows["22:1436331277"]="누가 뭐라고 날 부르던데... 임프시라던가?"
rows["22:1441198712"]="뭘 도와드릴까요?"
rows["22:1576228138"]="더 이상 게임하지 마"
rows["22:1581151117"]="자, 이제 여길 벗어나세나!"
rows["22:1817766981"]="좋아요, 좋습니다. 또 다른 일 없습니까?"
rows["22:191925377"]="록타르 오가르, 병사여."
rows["22:205416550"]="다들 어디 갔습니까?"
rows["22:347481618"]="자, 이제 여길 벗어나세나!"
rows["22:415020194"]="길니아스 전투"
rows["22:465195851"]="상자 마을이라니. 멋져!"
rows["22:469080785"]="내 가이드가 되세요?"
rows["22:471029149"]="잘 됐어"
rows["22:50427063"]="시간만이 알려줄 것이다..."
rows["22:543184886"]="네? 무얼 원하시죠?"
rows["22:573817684"]="바퀴벌레 사시려고? 말도 잘 듣고 귀여운 놈으로 골라줄 테니, 한 마리 들여 가게."
rows["22:573846767"]="오, 네 개의 불빛이 보이는군요!"
rows["22:633663861"]="브웸바가 뭘 도와 드릴까요?"
rows["22:801015022"]="제게 무슨 볼일이신가요?"
rows["22:826022589"]="여기서 나가게 해 주게!"
rows["22:860189302"]="파멸의 시간이 임박했다!"
rows["22:865051"]="여자들이 데려갈 수 있을까요?"
rows["22:894929900"]="마오우르글, 거르글 루르!"
rows["230:1263410314"]="일부 랜저들은 스스로 그들의 야생적인 기세를 돌볼 수 없는 것처럼 보입니다. 만약 당신이 단순히 도시에서 어딘가에 이런 것을 보관해야 한다면, 아나토스는 당신의 손에서 그것을 빼앗을 것입니다. 그녀는 호네 밖에서 팔콘윙 스퀘어에서 기다리고 일하고 있습니다."
rows["230:14090953"]="아, 알겠소. 알았다고. 어쨌든 난 어두운 곳으로 살짝 빠져나갔지.$B$B윈저 님께서는 그렇지 않아도 화가 잔뜩 나있던 마당에, 그게 부아가 더욱 치미셨던 모양이오. 무쇠폭군을 마구 휘두르면서 오크 녀석들에게 미친 듯이 소리를 질러댔소."
rows["230:1553760630"]="그처럼 위험하고 예측 불가능한 기술을 우리 숲에서 사용하면 불행한 결과를 가져올 겁니다. 실버문의 성벽은 돌풍을 견뎌낼 만큼 튼튼하니까 실버문 안으로 들어가서 알아보십시오."
rows["230:1808236144"]="이 매혹적인 도시를 다 둘러보셨다면 우리와 함께 축제를 즐겨보는 건 어때요? 지금 달숲에서는 달의 축제가 한창입니다. 어떤 대도시에서나 축제 장소로 순간이동시켜 드리고 있죠. 참, 달숲으로 가면 구경꾼들과 신나는 춤 한판 잊지 마세요."
rows["230:1816776320"]="초창기에는 눈이 초롱초롱한 젊은 학생들로 가득했죠. 하지만, 첫 단계를 통과한 이들은 거의 없었습니다.$B$B\"내가 소멸이라고 외치면 사라져야지!\"라고 외치는 것도 포기했습니다. 좀처럼 제 말을 듣지 않더군요. 이제 시험은 단지 적성이 맞지 않는 이들을 걸러내는 형식에 불과합니다."
rows["230:2082563651"]="로스엘레스는 정말 멋진 여자랍니다. 제가 의복이나 모자를 찾으러 갈 때마다 로스엘레스가 윙크하는 걸 봤지요? 주변 상황이 좀 정리되면 그녀와 함께 숲 속을 산책하며 데이트를 할 생각입니다.$B$B이럴 때는 정말이지 스톰윈드의 멋진 선술집들이 그립답니다."
rows["230:259969215"]="이 책의 낡은 페이지들은 마법의 힘으로 필멸의 존재들이 감당조차 할 수 없는 참혹한 부분은 넘기고 안전한 내용이 있는 페이지로 당신을 안내합니다.$B$B어떻게 보면 옳고 또 어떻게 보면 아주 그릇된 느낌을 주는 페이지가 열립니다."
rows["230:522956635"]="드루이드는 이 세계의 자연을 보호하는 데 있어 결코 경계를 늦추지 않습니다. 세나리온 자치령에 사는 대드루이드 판드랄 스태그헬름이 이끌고 있으니 찾아가 조언을 구하시기 바랍니다. 다르나서스 북부에서 판드랄과 다른 상급 드루이드를 찾을 수 있습니다."
rows["230:721873295"]="가젯잔의 기술자인 랩포지의 도움으로 이곳 토쉴리의 연구기지에 강력한 노움 순간이동기를 만들었어요! 자신의 전용 순간이동기를 만들 수 있을 만큼 실력이 뛰어난 노움 기술자를 돕는 것이 제 행복입니다."
rows["230:964489949"]="<펄볼그 언어로 인사하자 미소 짓는 너울소나무 대사 프라사부>$B$B당신이 예언에서 말하던 그 사람이 틀림없군. 만나게 되어 크나 큰 영광이오.$B$B나는 대족장이신 너울소나무 님의 핏빛 감시초소의 대리인인 너울소나무 대사 프라사부라고 하오이다."
rows["231:1360728234"]="용맹스러운 호드의 병사여, 경의를 표하는 바이네. 자네와 함께 온 동맹이 아니었다면 우리는 분명히 얼라이언스 비행포격선에 끝장났을 걸세.$B$B성채의 상층 구역을 공격하기 전에 잠시 쉬게나."
rows["231:1425809788"]="이 순간이동기가 자네를 북부 가시덤불에 있는 그롬골로 순간이동시킬 거야.$B$B별 일이 없다면 말이지.$B$B내 말은 가끔 이 고물이 자네를 해체해버리거나 몸 안의 연조직을 악취가 나는 녹색 연기로 만들어버릴지도 모른다는 거지. 그렇지만 대체로 안전해!$B$B항상은 아니지만 말이야."
rows["231:1520673273"]="내겐 광산 훈련자가 있다고 들었어요 썬더 블러프 북쪽으로 가서 마을을 벗어날 수 있는 길을 따라 올라가면 엘리베이터를 타고 승강장 꼭대기에 올라갈 수 있습니다."
rows["231:1811939512"]="안녕하세요! 전 덜렁발 큐이피라고 해요! 저는 아제로스에 있는 모든 영웅 중에 가장 인기가 많은 분이 누구인지 알고 싶어요!$B$B많은 모험가들이 자신들의 지도자에게 존경을 표하는 걸 보면 제 마음도 무척 따뜻해진답니다. 하지만... 그 보다 더 절 벅차게 하는 게 뭔지 아세요?$B$B바로 /키스라고요!"
rows["231:444783972"]="또 방해로군. 이런 식으로 나오면 대체 나보고 어떻게 일을 하라는 거요? 대답할 필요 없소. 변명 따위 듣자고 한 말이 아니니까. 만약 이곳을 청소하고 우리 제국의 영토를 확장할 생각이라면 날 좀 가만히 놔두시오!"
rows["231:715289487"]="\"순례자의 보너스\". Hrm. 나는 Tauren의 그들의 감사의 감각을 표현하고 공감대를 이해할 수 있습니다 호드의 전쟁 대장, 하지만 포세이큰?$B$B저는 그들이 이런 감성적인 전통을 오래 전에 포기했을 것이라고 상상했습니다."
rows["231:741622570"]="호드와 얼라이언스 양 진영의 부대장이 모두 전선에 나섰습니다. 우리 갈반가르 부대장께서는 얼음피 주둔지에서 서리늑대 부족을 지휘하고 있고, 그의 경쟁자인 발린다 스톤하스 부대장은 돌난로 전초기지에서 숨어 있습니다.$B$B전쟁이 시작된 겁니다!"
rows["231:844518577"]="물어봐 줘서 고맙군요. 무기고 공략은 현재 $3233w 퍼센트까지 진행됐습니다.$B$B전투마법사 아린나와 선구자 이누로가 당신의 도움을 바라니 쿠엘다나스 섬에 있는 태양너울 성소에서 그들을 찾아보세요."
rows["232:1034626849"]="나는 나블리아, 카즈고로스 님의 제자이자 운고로 분화구의 사절이다. 감시자로도 알려져 있지.$b$b난 아제로스를 떠난 스승님을 대신해 여길 지키는 중이다. 여기 이 자리가 스승님이 수많은 창조물을 만드신 바로 그곳이지."
rows["232:1090680079"]="여기 뒤틀린 드레나이의 시체 한 구가 있습니다. 이상하게도 돌연변이 나방이 죽음의 원인으로 보이지는 않습니다.$B$B이 드레나이는 죽음의 순간 필사적으로 한쪽 손을 내민 것처럼 보이며 그 바로 옆에는 이상한 물체가 보입니다. 이것이 그의 죽음과 어떤 관련이 있지 않을까요?"
rows["232:1501493589"]="<하늘 쪽을 흘긋 올려다보는 모르디스>$B$B솔직히 루크와 코르백스가 누리는 자유가 좀 부럽습니다. 세속에 관한 책임에서 자유롭다는 건 진정 큰 축복이죠.$B$B미래에 다시 비상할 수 있겠지만 그에 앞서 끝마쳐야 할 일이 있습니다."
rows["232:2008846667"]="이것이 바로 진정한 결투라네! 격투는 피를 부르고, 피는 전쟁을 부르지. 모든 고객은 대부분 그런 방식으로 끝을 맺었고 말이야.$B$B이제 사람들은 싸울 일이 있으면 이곳에서 싸우고, 이곳에서 결판을 낸다네! 잠재력을 최고로 발휘할 수 있거든!"
rows["232:289247724"]="이곳 다르나서스에는 오랜 세월 동안 자신이 선택한 직업의 기술을 갈고 닦은 다양한 상급자들이 있답니다. 그대의 지도자가 될 분에게 가는 길을 가르쳐드리겠습니다."
rows["232:429236387"]="십자군 봉우리를 되찾은 건 앞으로 헤쳐나가야 할 길고 험한 여정의 시작일 뿐이네. 얼음왕관 성채를 공격하려면 앞으로도 극복해야 할 장애물이 한둘이 아닐 터.$B$B자네나 자네 같은 영웅의 도움이 반드시 필요하네."
rows["232:4369530"]="전설 속의 이야기죠. 되풀이해서 말할 시간도 없고 그러고 싶지도 않네요. 메디브가 마지막 수호자였다는 사실만 알아두세요. 아티쉬 - 수호자의 지팡이가 그의 힘과 타락의 근원이었답니다."
rows["232:541518388"]="거기 당신! 네, 당신 말예요!$b$b잠시 절 바라보며 이 순간을 음미하시죠. 곧 온 세상이 윌프레드 피즐뱅의 이름과 무시무시한 표정을 뇌리에 새기고 두려움에 떨 테니까요! 일단 웅장한 소환 의식을 끝내면, 아무도 제 능력을 의심하지 못할 걸요!"
rows["232:816658512"]="달라란의 멸망과  ⁇ 탈라스의 파괴 이후 이런 상품은 찾아보기 힘들었지만 루칸 코델과 다른 상인이 우리의 주문을 질 높은 상품으로 채우는 데 훌륭한 일을 해왔습니다."
rows["233:1365120022"]="<겉모습이 아닌 마음속을 꿰뚫어보려는 듯한 대마법사 바르고스의 환영>$B$B마치 이 지역이 마력의 바다라도 된 것처럼 이곳에서 비전 마력의 흐름이 밀려왔다가 밀려나가고 있소이다. 첫 번째 대재앙 때에도 이 정도로 큰 피해는 없었는데 말이오."
rows["233:1502429586"]="호드는 엄청난 양의 붕대를 모으고 있다. 지금까지 양모 붕대는 $2080w개 중 $2079w개를 모았다. 마법 붕대는$2086w개 중$2085w개를 모았고, 룬무늬 붕대는 $2090w개 중 $2089w개를 모았다."
rows["233:1507319219"]="잠시만 기다려 보게. 기억할 숫자가 뭐가 이렇게 많은지... 질긴 가죽은 $2067w개 중 $2066w개를 모은 것 같네. 그리고 두꺼운 가죽은 $2071w개 중 $2070w개, 튼튼한 가죽은 $2074w개 중 $2073w개를 모아서 쌓아 두었네."
rows["233:1796583168"]="용족이 아닌 자가 벼리지 않은 승천의 인장을 구해 보호막을 지나가는 것은 가능합니다. 저 같은 자가 그러한 물건을 지니면 저 자신이 파괴되어 버리겠지만 당신이라면 그 인장으로 보호막을 약하게 할 수 있을 것입니다."
rows["233:400160681"]="아, 방문객이로군! 모험가신 모양이군요. 관광객은 이쪽으로 잘 지나가지 않는단 말이야. 의자에 앉아 한잔 들이켜면서 편히 쉬십시오. 보아하니 힘깨나 쓸 것 같은데, 철창 경기에 나가보실 생각은 없으신가요?"
rows["233:867518907"]="<당신의 속마음을 꿰뚫어 보려는 듯이 쳐다보는 란트레서>$B$B어쩌면 다른 방법이 있을지도 모르지... 내가 말하는 그대로 행한다면 네 종족의 지도자가 요구하는 바를 들어주마.$B$B우리에게 도움을 준다면 서로에게 큰 도움이 될 수도 있을 것이다."
rows["234:1013665160"]="제일다는 자신의 생각에서 길을 잃어 버린 것처럼 보입니다. 때때로 그녀는 어떤 문장을  ⁇ 니다.$B$B\"멸망\" \"죽음\" \"희생\" \"아름다운 작은 잔의 와인\" \"독물\" \"굴에 오크\" \"안녕하세요\""
rows["234:1016664974"]="더크셔의 또 다른 얼굴이 오늘 3명이나 되는 거요\010\010용감하거나, 길을 잃거나 둘 다. 만약 숲으로 가는 계획을 세웠다면,\010\010밤 경비대는 사람들을 다시 데려오기 위한 기회를 늘 얻지 못합니다."
rows["234:1022831073"]="이제 확실히, 당신이 나보다 더 많은 걸 알게 되었군. 이제 우리 아버지와 얘기해 봐. 당신 솜씨부터 먼저 증명해 보여야겠지만, 인정만 받으면 정말로 좋은 스승이 되어 주실 거니까. 아버지 성함은 로트가스인데, 벤구스 옆에서 작업하고 계셔."
rows["234:1258248877"]="그들이 나를 피하고 있어 방어선 너머가 보이지 않는다네. 그들은 위치가 탐지되는 걸 막으려고 수호물을 설치했지.$B$B<서쪽을 가리키는 알트루이스>$B$B그들은 어떤 것도 두려워하지 않는 우리를 무서워하지. 그런 힘을 얻기 위해 치르는 대가는 엄청난 것이야... 많은 것을 희생해야 한다네."
rows["234:1482868529"]="이 세계에 사는 자들의 도움을 받아 불타는 군단과 맞서려면, 그들과 평화롭게 살아가는 방법 또한 배워야 하네.$B$B아제로스를 여행하는 동안 항상 이 점을 기억하시기 바라네. 성스러운 빛이 $g형제:자매;를 바른 길로 인도하길..."
rows["234:1705618689"]="내가 칭찬을 받았지만, 정말 관심이 없어요... 마법을 어디서 배울 수 있는지 알고 싶으세요? 어, 어색한 것 같아요."
rows["234:171368465"]="스톰윈드 에서 술 을 마실 수 있는 많은 곳 이 있지만, 그 중 한 곳 만 에만 밤 을 보낼 수 있습니다. 무역 구역 에 있는 골든드 로즈 로 이동 하십시오. "
rows["234:1755183950"]="호드, 특히 오크와 맞서 싸울 기회가 생긴다면 아주 잘 된 거라고 할 수 있소. 전쟁노래 협곡에서 당신이 원하는 전투를 무수히 많이 접하게 될 겁니다. 전투의 전당으로 가서 리란드리스와 얘기해 보시면 전쟁노래 협곡으로 이끌어 줄 겁니다."
rows["234:240566389"]="여보십시오, 전 호드에 필요한 전투 식량을 모으고 있습니다. 호드는 안퀴라즈의 사막에서 벌어질 대전쟁을 준비하고 있는데 내게는 점박이놀래기 구이 $2103w개를 모아달라고 했어요. 하지만 지금까지 우리가 모은 것은 $2102w개뿐입니다. 절 좀 도와주시겠습니까?"
rows["234:303479584"]="인생은 투쟁이고, 당신을 죽이지 않는 것이 당신을 강하게 해주는 말이 항상 사실이 아닙니다. 때로는 상처가 느리게 작용하는 것이 있습니다. 그래서 우리는 붕대를 가지고 있습니다."
rows["234:679436532"]="투척 무기라면 오그리마의 무기 전문가인 사요크와 하나시가 정말 예술로 다루지. 그들은 명예의 골짜기에서 제자를 양성하고 있다네. 아니면, 실버문의 원정순찰대 광장에 있는 일레다도 당대 최고의 투척 기술을 보유하고 있으니 찾아가 보게나."
rows["234:749527612"]="제가 여기에 있어서 놀라셨나요? 누구나 빨래는 해야 하죠. 그리고 물의 정령보다 더 좋은 빨래 방법이 있을까요?$B$B빨랫감과 아주 적은 요금만 가져오시면, 눈 깜짝할 사이에 전부 새 옷처럼 말끔해져 있을 거예요!"
rows["234:807637158"]="우리는 적들을 감시하고 있었습니다... 호드 함대 말이죠... 그런데 갑자기 어디선가 촉수가 올라와 아군의 배를 감싸더니... 정확히 두 조각으로 부숴버렸습니다!$b$b생존자들은... 물에 빠지자마자 나가에게 사로잡혔죠.$b$b그게 거의 일주일 전에 일어난 일입니다."
rows["234:869787633"]="스컬지가 패배했다는 말은 들을 필요도 없소. 보시오... 놈들이 아직도 역병숲을 돌아다니고 있지 않소? 마치 요람에 매달리는 어린아이처럼, 그들은 오염된 땅에 집착하고 있소.$b$b이제 싸울 수밖에 없소. 내 숨이 멎는 순간까지, 난 놈들과 싸우겠소."
rows["234:934802603"]="물어볼 게 뭐가 있겠습니까? 녀석은 말 그대로 원숭이일 뿐입니다. 그러니까 원숭이는 브란 님의 얼굴이 모래에 처박히는 걸 보더니 광분해서 그녀에게 달려들었습니다. 원숭이가 아니었더라면 그 나이트 엘프 여사제의 공격을 막아내지 못했을 겁니다."
rows["235:1326908221"]="보통 개는 이제 내 주위에 얼씬거리지 않는다오. 그걸 알았을 때는 얼마나 비참했는지... 난 개를 정말 사랑했소.$B$B지금은 역병사냥개들이 그 자리를 대신한다오. 보기에 썩... 좋은 녀석들은 아니지만 그건 나도 마찬가지 아니겠소!"
rows["235:1534605520"]="그다음은 말이죠... 그녀는 곤충 집으로 곧장 달리기 시작했습니다. 그런데 더 이상한 게 뭔지 아세요? 바로 그 저주받은 벌레들 중 단 한 마리도 그녀를 막지 않았다는 겁니다. 그녀는 수 세기동안 녀석들의 친한 친구였던 듯이 녀석들 모두를 지나쳐 들어갔습니다."
rows["235:1588860633"]="아주 제대로 배웠군요. 이제 언더시티로 가서 제임스 반 브런트라는 대장장이를 찾아보세요. 내가 가르치지 못하는 것들을 많이 가르쳐 줄 거예요. 전사를 양성하는 군사 지구 근처에서 무기와 방어구를 만들며 시간을 보내는 걸로 알고 있어요."
rows["235:1685240551"]="어서 행동에 나서야 하오! 타이리고사 님과 그분의 경비병들이 쓰러져서, 사원은 지금 무방비 상태요. 용의 영혼이 데스윙의 수하들에게 넘어가면 모든 게 끝장이니, 어떻게든 막아야 하오. 고룡쉼터 사원 용군단이 당신의 진격을 돕겠소. 적의 포위를 뚫어야 하오!"
rows["235:621421946"]="배우는 속도도 빠르고 솜씨도 좋은 대장장이로군. 내가 가르칠 건 다 가르쳤네만 당신은 아직 더 배워야 할 것이 많은 것 같소. 가서 벤구스 딥포지와 얘기를 나눠보시오. 어려운 숙제를 많이 내주긴 하지만 그래도 최고의 대장장이지."
rows["236:1588914842"]="카라잔이 멸망한 후 키린 토에서는 한 무리의 마법사를 보내 탑을 조사하고 그곳으로 반입된 모든 물건을 빼앗었어요... 연구를 핑계로 말이죠. 전설의 지팡이가 발견되어 달라란으로 옮겨진 것이 바로 그때였어요."
rows["236:29934621"]="내가 마법사처럼 보이시나요? 케인 파이어송이 남동쪽의 겔로우스 엔드 타버너의 상층 상륙에 걸렸다고 들었는데"
rows["236:360269828"]="창조주는... 말 그대로 창조주입니다.$B$B창조주는 자신이 계획하고 설계한 그대로 이 세계를 만들고 종족을 퍼뜨렸습니다. 이 세계가 존재하는 근원은 창조주입니다. 물론 다른 수많은 세계가 존재하게 한 장본인이기도 합니다. 즉 아제로스를 창조한 근원인 것입니다."
rows["236:450520236"]="악과 싸우는 전투에서 진정한 성전사는 영웅 이상의 존재요... 동족의 눈에 성전사는 타의 모범이 되는 자라오. 목표를 향해 달려가는 주자이며, 용사인 셈이란 말이오.$B$B고위 성전사로서, 그런 자에게 가치 있는 임무를 부여하는 것이 내 임무요."
rows["236:453516284"]="그 꼬마를 보면 한기가 느껴져. 소년은 하루종일 그곳에 서서 할아버지와 대화를 나누지. 할아버지에게 들은 얘기를 엄마에게 하면 소년의 엄마는 당연하다는 듯이 웃음을 띠면서 고개를 끄덕이겠지.$B$B양에 대한 얘기! 쥐에대한 얘기! 그런 얘기들 말이야!"
rows["236:545819864"]="쉽게 인정하기는 싫은 사실이지만, 당신은 나보다도 솜씨가 훨씬 좋습니다. 이제 내가 가르쳐줄 수 있는 건 보잘것없는 것들뿐입니다. 더 큰 배움을 얻으려면 스톰윈드에 있는 테룸 딥포지라는 드워프를 찾아가 보십시오. 드워프 지구에 있을 겁니다."
rows["236:999862143"]="오, 안녕하시오. 보아하니 돈 좀 벌 기회라면 마다할 얼굴은 아니군, 흐음? 눈빛만 봐도 알겠소. 나는 거물 케복, 아제로스 사업 총책임자요. 부를 원한다면... 내가 자리를 좀 마련해 줄 수도 있지."
rows["237:1152980895"]="스톰윈드 우리들을 버렸고 농민들이 포크를 키우고 있습니다. 희망이 없습니다. 우리는 모두 죽을 것입니다. 그리고 난 당신을 몰라요, 하지만 나는 승리하는 편에있을 계획입니다."
rows["237:336392297"]="식량을 얼마나 모았는지 알고 싶다고 했나? 좋아. 마지막으로 들은 바에 의하면, 늑대 살코기 스테이크는 $2096w개 중 $2095w개가 준비됐다고 한다. 그리고 필요한 점박이놀래기 구이는 $2103w개 중 $2102w개, 훈제 연어는 $2106w개 중 $2105w개를 포장해 두었다고 한다."
rows["237:433071456"]="뭣 때문에 말이오? 일리단의 악마들이 날 붙잡아서 노예로 삼지 않으면 장가르 습지대의 나가들이 그렇게 할 텐데 무슨 소용이 있겠소.$B$B뒤틀린 드레나이 일족들이 일리단과 그의 동맹들에게 가담해봤자 대부분이 다 노예가 될 뿐이오. 내 동족들에게는 아무런 희망도 없소이다."
rows["237:476523471"]="뛰어야 벼룩인 게 누구더냐? 물론 너는 우리가 말퓨리온 님에 이어 너까지 소환할 거라고는 생각도 못했겠지? 자, 구원받을 시간이다, 에라니쿠스. 너의 광기와 타락을 정화하도록 하마."
rows["237:554118130"]="브론크가 계속  ⁇ 어왔던 모든  ⁇ 이 있긴 하지만, 저한테도  ⁇ 어줄 수 있어."
rows["237:564916850"]="어서 오세요! 쑥스러워하지 마시고요.$b$b자, 제 자랑이자 기쁨인... 블라스텐하이머 5000 초특급 대포를 소개합니다! 정말 멋지지 않나요?"
rows["237:6735494"]=" ⁇  카자드 는 항상 외부인 들 에게 문 을 열고 있다! 우리가 그렇게 하지 않았다면 이 도시는 얼음 과 돌 이 될 것 이다.$b$b숙소에 정착해,  ⁇  카자드를 즐기세요!"
rows["237:812468872"]="그들은 말했소. \"전쟁 물자를 모으는 임무를 훌륭히 완수했군. 자네도 진급할 때가 된 것 같은데...\" 하지만, 이 말의 진짜 의미는 이거였소! \"칸스, 자네를 땀 냄새나는 드워프 무리와 함께 실리더스의 벌레집 외곽으로 전출하는 바이네.\"$B$B진급?! 훗, 정말 눈물 나게 고맙지 뭐요."
rows["238:1084327188"]="해골망치 초소는 우리 주둔지로 안성맞춤이라네! 기형을 일으키는 피눈물 부족 놈들과 아주 가까워서 놈들의 오염된 피 냄새를 맡을 수도 있지! 동족을 배반하고 악마와 계약을 맺은 일족에게 복수를 하기에 이보다 더 좋은 곳이 어디 있나?"
rows["238:1098807948"]="와일드해머를 생각하면 뭐가 생각나나, 응? 자네가 사리분별을 할 줄 아는 친구라면 그리핀 기수가 생각나겠지! 어둠달 골짜기에 맹금의 봉우리가 없긴 하지만 우린 아직 좋은 재고품이 있지. 그래, 좋은 재고 말이야. 내 예쁜 그리핀들을 쭉 둘러보고 자네의 눈길을 끄는 게 있는지 보라고!"
rows["238:1326348811"]="오우거들이 나를 목까지 묻고는 잊어버렸네.$B$B그래, 우습기도 하겠지. 마음껏 비웃게나. 머리만 남은 유령이 여기 있으니까.$B$B물론 도와준다면 보상을 줄 수도 있어.$B$B그치만 됐어. 계속 웃기나 하라고."
rows["238:1382779597"]="나가를 사냥하려면 이용할 수 있는 건 뭐든 이용해야 합니다. 물속 깊이 들어가면 거품 균열이 있는데, 거기서는 공기 방울이 많이 솟아나 물속에서도 숨을 쉴 수 있게 해줍니다. 균열 가까이 헤엄쳐 가서 그 공기 방울을 잘 이용하십시오."
rows["238:1864858140"]="대마법사 알바리욱스는 한때 흥미로운 이론을 연구한 논문을 썼다오. 그는 다른 세계에도 카라잔과 똑같은 곳이 있으며 같은 공간을 공유하고 있다고 주장했지.$B$B정말 안타깝게도 얼마 후 그는 정신병자가 됐다오."
rows["238:1884268790"]="당신은 호기심이 아주 강하군요. 보통 그런 호기심은 이해력의 부족에서 오는 것이긴 하지만 말입니다. 이곳에 오는 데 뚜렷한 목적이 있었다면 그런 질문은 애당초 하지 않았을 테지요.$B$B당신의 갈 길이나 가보도록 하십시오."
rows["238:1921500410"]="사냥꾼에게 애완동물 취급을 당하다니, 정말 창피한 일이야!$B$B목숨을 구해 준 건 고맙지만 이제 내 걱정은 그만해도 돼. 무셀레크에게서 풀려났으니 혼자서도 나갈 길을 찾을 수 있을 거야. 가는 길에 레이지도 데리고 갈 수 있으면 좋겠군."
rows["238:1923877673"]="우리가 이런 짓을 하고 있다니 믿기지가 않는군. 대공작 칼신더의 존재가 우리 모두를 위협하고 있다는 건 알지만, 그게 정말인지도 모르잖나? 그리고 이런 일은 대지 고리회인가 뭔가 하는 자들이 전문인 것 같은데. 안 그런가?$b$b왜 항상 토륨 대장조합이 나서야 하는 거지?"
rows["238:381865427"]="아, 갖고 있소... 크로미가 필요하다고 했소? 아무래도 그럴 것 같군.$b$b자, 가져가도 좋소. 물론 한 번 읽어봐도 좋고. 그 책을 보시면 다로우골의 역사와 함께 수많은 사람을 죽음으로 이끌었던 사건에 대해서도 자세히 알게 될 거요."
rows["239:1220094573"]="반가워요! 저는 여기 샤트라스에서 마법불꽃 재봉술을 전문으로 하는 기지라고 해요. 경쟁이 치열한 것은 아니지만 마법불꽃 재봉술에 관심이 있고 아직 전문화를 익히지 않으셨다면 제가 도와드릴 수 있어요."
rows["239:1229957752"]="당신은 이미 많은 것을 배웠지만, 영혼의 말에 의하면, 아직도 배울 게 많이 있다는 것 같소. 나는 가야 할 방향만 제시할 뿐이지. 당신을 직접 이끌어줄 수는 없소. 오그리마에 있는 사루 스틸퓨리를 찾아가도록 하시오. 당신의 다음 여정은 그곳에서 시작될 거요."
rows["239:1282360657"]="여관이요? 아, 아이언포지에서 최고로 맛 좋은 맥주를 한잔 걸치고 싶은 거로군요. 그렇다면 부싯돌 선술집으로 가보십시오.$B$B오시는 길이라면 아이언포지 정문에서 왼쪽, 가시는 길이라면 오른쪽에 있습니다."
rows["239:1445564188"]="호드와 얼라이언스 양 진영의 부대장들이 모두 전선에 나섰습니다. 우리의 발린다 스톤하스 부대장님께서는 돌난로 전초기지에서 스톰파이크 경비대를 지휘하고, 적군의 갈반가르 부대장은 얼음피 주둔지에서 명령을 내리고 있습니다.$B$B진격하십시오!"
rows["239:1463045048"]="이 전쟁에 대한 부담으로 마음이 무겁기만 하구나. 동료들을 죽음으로 몰아넣으니 말이다. 그러나 지금 우리가 라그나로스와 맞서지 않는다면 넬타리온은 어떻게 버텨낼 것이란 말인가?$B$B모든 것을 다 바쳐 전투에 임하지 않는다면 우리 세계가 멸망하는 것을 두 눈으로 보게 될 것이다."
rows["239:1552847634"]="대장장이의 삶이란 결코 쉬운 게 아니지만, 뼈에는 강철을 심어 주고 가슴에는 화염을 심어 준다오. 우리 아버지께서도 대장장이셨고, 조부님께서도 그림 바톨의 슬하에서 강철을 주무르셨지. 그리고 이제는 우리 아들 녀석도 가문의 발자취를 따르고 있소. 내 마음을 아주 뿌듯하게 하는 사실이지."
rows["239:2032924346"]="이 거점을 확보하려고 많은 것을 포기했으니, 이제 끊임없이 싸워 지켜내야만 한다. 아군의 수비가 취약하지만, 계속해서 전진하려는 노력은 앞으로 더욱 강력한 동맹군이 생기게 해줄 것이다.$B$B용사여, 바로 지금이야말로 용기를 가져야 할 때다."
rows["239:2108122262"]="아니요, 전 지적인 노움이라고요. 절 가볍게 보지 마세요. 구정물과 민들레만 가지고도 치유 물약을 만들어내는 능력자라고요! 그걸 보여드리려는 건 아니지만요!$b$b어쨌든, 물건을 사시려거든 패트리샤와 이야기하세요."
rows["239:77359682"]="이야기가 거의 끝나갑니다. 달라란은 아키몬드에 의해 거의 파괴됐고 지팡이는 사라졌어요. 아마도 방벽의 안전장치에 의해 부서진 것 같아요.$B$B어떤 이들은 그 지팡이가 아키몬드의 복수를 불러온 원인이라고 믿고 있답니다."
rows["23:1231292200"]="장비가 전부 망가지셨군요. 그렇죠?"
rows["23:1281551243"]="[펄볼그어] 야르 발트슬라프?"
rows["23:1288944377"]="이렇게 헛되이 생명이 사라지다니."
rows["23:1433797983"]="나 진짜 천재야, 천재!"
rows["23:1566581145"]="난 복수할 것이오!"
rows["23:156723444"]="나와 대화하고 싶나? 그럼, 돈을 내."
rows["23:1613911865"]="땜장이 마을에 잘 왔네!"
rows["23:2051026104"]="네, 네.$B$B뭡니까? 저리 가세요."
rows["23:2075643928"]="준비됐어?"
rows["23:2130216295"]="누가 파티라고 했나?"
rows["23:247978679"]="또 다른 배고픈 보충병이신가요?"
rows["23:274197180"]="르므무르프후므 므므프 흐므르프후므!"
rows["23:29807719"]="아옳롤로롤로... 롤로롤?"
rows["23:343677114"]="<가마솥이 부글거립니다.>"
rows["23:528388488"]="머핀 있습니다!"
rows["23:603353629"]="그냥 가이드를 기다려야지"
rows["23:630036290"]="[펄볼그어] 푸우루브타크흐!"
rows["23:891675389"]="바쁘니까 빨리 말하게!"
rows["240:1224526166"]="약초채집을 배우고 싶으시다면 썬더 블러프로 가셔야 합니다. 블러드후프 마을에서 북쪽으로 빠져나가는 길을 따라가다 보면 썬더 블러프 올라가는 승강기가 있습니다. 그걸 타고 올라간 다음, 썬더 블러프 경비병에게 더 자세히 물어보십시오."
rows["240:1334641560"]="구해주셔서 감사합니다!$B$B저는 스톰윈드에서 온 요리사 겸 연금술사예요. 앵거스 삼촌에게 갖다 드리려고 이 지방에서 나는 약초와 조리법을 찾다가 이 가시멧돼지들에게 붙잡혔답니다. 당신이 오지 않았다면 분명 녀석들의 스튜 냄비 속에서 끝장났을 거예요!"
rows["240:1551221290"]="예언의 현신이여, 우리와 쿠르즈의 예언을 기억하시오? 지금 이 순간은 이미 결정된 운명이었소. 당신은 이 세계에서 맡은 일을 모두 완수했소.$B$B<당신에게 고개를 숙이는 대족장 너울소나무>$B$B나의 백성들은 언제나 드레나이를 환영할 것이오."
rows["240:1594450977"]="연금술사들이 특정한 보석들을 변환할 수 있다는 걸 아십니까? 마르나와 이 문제에 대해 이야기를 좀 나눴죠.$B$B그녀의 솜씨는 정말 훌륭해요. 그러니 마르나의 실험실만 완성되면, 세월 속에서 사라졌다고 여겨지는 보석을 그녀와 제가 만들어낼 수 있을 겁니다."
rows["240:196695072"]="난 평생을 군대에서 보냈지. 수많은 깃발 아래에서 수많은 전투를 경험했지만, 언제나 다른 사람을 위한 전쟁이었어.$B$B이번에는 그렇지 않네. 여기 보이는 포세이큰 병사들은 모두 한 가지 목적을 위해 모였지. 바로 아서스의 죽음 말일세."
rows["240:2094045586"]="장창 다루는 법이라면 포세이큰 무기 전문가인 아키발드가 정통하지. 언더시티의 군사 지구로 가보게. 아니면, 실버문의 원정순찰대 광장에 있는 블러드 엘프 무기 전문가인 일레다에게 가도 쓸만한 장창 기술을 가르쳐 줄 거야."
rows["240:249399217"]="사랑 표지판은 사랑스러운 도시와 도시 사람들에게 줄 수 있는 작은 애정 메시지입니다. 그러한 사람들은 당신을 숭배 선물로 보상합니다.$B$B아니면, 다른 사람이 이미 당신을 숭배한다면, 적어도 그들은 당신에게 우정을 선물할 것입니다."
rows["240:655691274"]="또 자네로구만...내 영혼을 안정시킨답시고 쓸데없는 노력을 기울일 필요는 없네. 그녀 없이는 마음의 안정을 되찾을 수 없다는 걸 깨달았네. 안되고 말고.$B$B놈들의 서식지가 완전히 파괴되는 광경을 꼭 지켜보고야 말겠어. 역겨운 살인자들을 더 해치울 준비는 됐나?"
rows["241:1201916197"]="안녕하세요, 환영합니다, 내 상실은 열리지 않은 것 같아요.$B$B하지만 여전히 네 얼굴에 미소를 짓는 혈통의 맹세를 해야 돼."
rows["241:138558443"]="텔로니스만큼 가죽을 다루는 솜씨가 뛰어난 자가 이 동부 왕국에 있기나 할까요?! 그만한 수업료로 기술을 전수받을 수 있다는 걸 감사히 여겨야 합니다. 지금 다르나서스 북동부에 있는 장인의 정원으로 가서 그를 찾아보십시오. 쓸만한 가죽 방어구를 만들 수 있을 거예요."
rows["241:1489153779"]="제가 가르쳐 드릴 수 있는 한계에 도달하셨지만 아직 더 배울 게 남아 있답니다. 바다 건너 스톰윈드의 마법사 지구에 가면 훌륭한 실력의 재봉사가 살고 있지요. 이름은 조르지오 볼레로라고 하는데 이제부터는 그분이 당신을 훈련하시리라 생각합니다. 가서 그분과 얘기해 보십시오."
rows["241:1545417319"]="우리 역병인도자는 평범한 연금술사보다 조금 더 실용적인 편이지. 결국, 우리가 하는 연구는 역병을 어떻게 잘 퍼트리느냐 하는 것이니 말일세.$B$B그렇다고 우리의 이론적 기반이 부실하다는 말은 아니야. 단지 실무 작업을 더... 좋아할 뿐이지."
rows["241:1597500321"]="메아리 섬을 되찾을 준비를 시작할 걸세. 잘라제인은 부두 마법을 사용하여 마치 자신이 죽은 것처럼 사람들을 속이고는, 고대부터 내려오는 암흑의 의식을 거행하고 있지.$B$B녀석은 우리가 공격해 올 것을 알고 있네. 그러니까 우리도 단단히 준비해야지."
rows["241:2059300846"]="탐험가 연맹을 대표하는 브론윈은 얼라이언스의 명령을 받아 이곳에서 칼날 산맥을 연구하고 있다네.$B$B이건 우리끼리 얘긴데, 연구차 실리더스에서 너무 오래 머물렀더니 휴식이 필요하던 참이었어. 보아하니 이곳은 휴가를 보내기에 안성맞춤인 것 같군그래."
rows["241:2109232702"]="시내 밖으로 남동으로 가는 길에서 셰레네 로바트를 찾아서 동쪽으로 갈 때,"
rows["241:2111339876"]="누누이 말하지만 이 녀석은 절 미치게 해요! 설마 고블린이 정말로 쾌속선처럼 굉장한 배를 운항하는 데 도움이 될 거라 믿으시진 않겠죠?$B$B이 녀석들이 잘하는 거라곤 뭐든 폭파시키는 건데, 그조차도 한 절반의 경우엔 자신들을 날려버리는 녀석들이라고요!"
rows["241:411287967"]="그대는 가죽세공인이 맞으시죠? 그대에게서 경화 가죽 냄새가 나요. 그 냄새라면 어디서든 분간할 수 있죠.$B$B아버지 말씀으로는 수 세기 전 마파람 마을에 유명한 가죽세공의 장인이 살았었대요. 유감스럽게도 지금 그곳은 폐허가 됐지만..."
rows["241:620435175"]="이곳 토막나무 주둔지를 오가는 짐마차와 상인들에 대해 알고 싶은 거라면 운 좋게도 바로 내가 자네가 찾고 있는 오크라네. 하지만 유감스럽게도 난 사람들을 싫어하거든.$B$B필요한 게 있으면 얼른 말하라고!"
rows["241:684198885"]="톨핀 스톤쉴드가 아이언포지에서 이곳까지 와서 사냥을 가르치고 있습니다. 드워프 지구를 가득 채우고 있는 자욱한 연기 속을 헤치고 나갈 자신이 있으신가요? 드워프 지구 북동쪽에 있는 그의 집으로 찾아가보십시오."
rows["241:921553449"]="네, 그는 불가능하다고 생각했던 일을 했습니다.$B$B내 관점에서 보아도 고귀가 구신의 대리인과 대화를 나누는 것을 볼 수 있었습니다"
rows["242:1126064041"]="저 안에서 고대 신의 힘이 담긴 유물, 일종의 무기가 하나 제작되고 있습니다. 그게 무엇인지 정확히는 모르나, 초갈이 무기를 완성하기 전에 어떻게든 저지해야 합니다.$B$B이 일보다 중요한 건 하나도 없습니다. 어떤 희생이 있더라도 성공해야 합니다. 심지어 당신과 내가 희생된다고 하더라도요."
rows["242:1172598196"]="어이 몬, 당신은 연습을 위해 오래된 Mu'kaka '에 오는?$B$B네 모습이 맘에 들어요. 네 눈에는 어린 시절을 떠올리게 하는 불꽃이 있어요.$B$B내가 당신에게 그 힘을 어떻게 활용하는지 보여 드리겠습니다, 그리고 당신은 나만큼 강해질 것입니다!"
rows["242:1183823550"]="이 숲에 악이 만연하는 게 우리 명가 때문임을 잘 알아요.$B$B그러나 또한, 자신의 실수를 보상하려고 애쓴 명가의 일원이 저뿐이지는 않습니다. 제가 도울 수 있게 융통성을 발휘해준 에메랄드 의회에 감사드려요."
rows["242:1693743192"]="<머릿속에 울려퍼지는 고레크의 목소리>$b$b나...는 곧 죽을... 것이다. 도와 다오... 황혼의 망치단을... 멈추어 다오...$b$b그들이... 내 힘을... 빨아들여... 승천한 신도를... 창조하려 한다... 크나큰 위협이... 넵튤론과의... 전쟁이 닥쳐온다..."
rows["242:1807452909"]="저희가 데리고 있는 고아들은 숄라자르 분지를 뒤흔든 전쟁의 희생자들입니다. 당신은 점쟁이 조합 고아나 광란심장 일족 고아 중 하나를 골라 돌보실 수 있어요. 둘 다 새 친구가 생기면 좋아라 하겠지만, 안타깝게도 당신은 한 명만 고르실 수 있답니다."
rows["242:1823473837"]="한때 난 모든 걸 가졌었소. 부와 명성, 그리고 최고의 검투사 장비까지... 그리고 어느 날 모든 걸 잃었소.$B$B전투에서 부정행위를 하고 승부를 조작하다 무역회사에 들켜 그만... 끝장나고 말았소.$B$B이제 남은 건, 이 허름한 옷과 상한 간뿐이오."
rows["242:1949653873"]="모든 준비가 끝나고 이제 한판 붙을 일만 남았군요. 전쟁 물자를 모두 실리더스의 세나리온 요새로 수송 중인데 최소한 $2113w일 안에는 마지막 물자가 도착할 것입니다. 조만간 홀만 합쳐지면 드디어 전쟁이 시작되는 겁니다."
rows["242:2097930535"]="칼날 같은 바람이 이 봉우리를 가로지르는 가운데, 살아 있는 것들은 대부분 이 얼음왕관 구석을 떠난 지 오랩니다. 하지만, 어떤 것이든 계속해서 달래고 어르면 돌아오는 법입니다. 그게 바로 제가 이 광장을 걷는 이유이지요. 언젠가는 이 나무들이 우리 머리 위로 우뚝 솟을 겁니다."
rows["242:2133113741"]="땅은 내가 상상했던 것보다 더 나쁜 상태입니다. 만약 피해가 이 속도로 계속된다면, 파라홀론, 네더스톰은 곧 우주 진흙일 뿐일 겁니다.$B$B그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그, 그 때, 그 때, 그, 그 때, 그, 그 때, 그 때, 그, 그 때, 그, 그 때, 그, 그, 그, 그, 그, 그, 그, 그, 그,에, 그, 그,에, 그, 그,에,에, 그, 그,에, 그, 그,에, 그, 그, 그, 그"
rows["242:890956284"]="이 공격 작전이 톱니바퀴 돌아가 듯 딱딱 진행되도록 하는 게 제 임무예요.$B$B땜장이왕 멕카토크 님께서는 지금 전장에 계신데, 병력을 충원하러 조만간 돌아오실 거예요.$B$B멕카토크 님은 절대로 늦으시는 법이 없으시죠. 그러니까 멀리 가지 마세요. 금방 오실 테니까요."
rows["243:1481746610"]="나라인 사우스판시, 은퇴한 엔지니어이자 마이너스 마이너스,$B$B만약 당신이 여기 와서 재학에 대한 기술을 배우려고 한다면, 저 책으로...$B$B<나라인은 \"두미들을 위한 예언\"을 지적한다."
rows["243:1499288556"]="탐욕이 널 내게로 데려왔어$B$B<마트레디스는 웃는다>$B$B지혜로운 드레네이 한 사람이 제게 말했죠. 탐욕은 이 세상의 모든 인종들이 공유하는 유일한 특성이라고.$B$B리브람에 있는 구성요소를 수집하셨나요?"
rows["243:2042126732"]="악마의 에너지가 얼마나 멋진지 아나? 값싸고, 재생 가능하고, 폭발력도 대단하지.$b$b물론 시간과 공간을 초월한, 상상할 수 없는 공포 때문에 영원한 의지를 잃어버릴 위험도 있지만, 위험을 감수할 만한 보상이 뒤따르지 않나!$B$B자, 무슨 일로 왔다고 했지?"
rows["243:399210184"]="안녕하세요! 저흰 저 아무짝에도 쓸모없는 해적 녀석들이 막고 있어서 완전히 발이 묶였어요.$B$B당신이 폭탄을 몇 발 떨어뜨려 주시면 도움이 될 것 같은데 생각 있으신가요?!$B$B도둑맞은 저희 비행선이 도착하려면 $3078w분도 안 걸릴 거예요. 비행선이 떠나기 전에 꼭 타도록 하세요!"
rows["243:573685982"]="세이지를 만나서 운명을 점쳐보기를 권해드립니다. 그래요, 그래요... 세이지는 놀이죠. 하지만, 세이지는 미래를 점치는 힘을 지닌 아주 특별한 놀이랍니다!$B$B저희는 온갖 새로운 즐길 거리를 마련하여 그 능력을 더 널리 사용하고자 한답니다."
rows["244:1054099521"]="나는 \"항공 우주 공학 전문위원단\"의 단장을 맡고 있는 퓨즐라지라네. 줄여서 B.O.O.M. 이라 부르지.$B$B시스템은 모두 정상적으로 작동하고 있나?! X-52 황천 로켓은 아직 많은 연구가 필요한 것 같군!$B$B자자, 친구들... 발사 완료까진 할 일이 태산이라네!"
rows["244:1063830520"]="피 기사들의 주부인 리아드린 여신, 파스트라이더스 광장에서 기사들의 본부를 두고 있습니다."
rows["244:1177929406"]="그래, 나는 떠났네. 도저히 검은바위 부족과 함께할 수가 없었지. 아니. 그렇게 하면 내 아들들의 죽음이 헛되이 돼버리기 때문에 말일세. 렌드처럼 무능하고 권력에 굶주린 미치광이를 섬길 수가 없었지.$B$B나는 로데론의 숲으로 가서 하스글렌 근처에서 몸을 숨기고 살았다네."
rows["244:1427982137"]="우리 도시에 있는 연금술사 로로킴은 실험대를 직접 가지고 다닙니다. 당신에게는 좀 생소하게 들릴지도 모르겠지만 결국엔 그는 아라코아니까요. 하지만, 크게 문제 될 건 없을 겁니다. 그를 만나려면 고난의 거리의 북서쪽 지역으로 가시면 됩니다."
rows["244:1576722856"]="그러니까 내 가르침을 받을 만큼 솜씨가 있다고 생각하는 건가? 자네는 내 장화 밑의 벌레 정도밖에 되지 않아. 하지만 아랫 것을 받아주면 수미와 투미의 마음을 살 수 있을지도 모르겠군. 자네가 얼마나 실력이 있는지 한번 봐주지. 보잘것없을 게 뻔하지만!"
rows["244:1718819721"]="휴... 담배 한 모금 피운 후, 아리따운 노움 여성과 데이트라도 했으면... 아니, 데이트 먼저 하고 한 모금 펴도 좋겠지!$B$B전 저 녀석의 뱃속에 몇 달 동안이나 갇혀 있었답니다! 오늘이 무슨 요일이죠? 참, 나 방금 빠져 나왔지...$B$B얏호!"
rows["244:1963308896"]="이 숲은 점점 더 위험해지고 있는데 제 누이 실란나는 아무것도 모르고 있습니다. 하지만 어찌 됐든 이 마차에 짐을 다 실으면 도시 성벽 안으로 들어갈 겁니다.$b$b가방이 필요 이상으로 많은 것 같으니 필요하시다면 제 가방을 사용하셔도 좋습니다."
rows["244:2063257557"]="원 바깥에 서 있는 자들은 누구도 널 볼 수 없지만, 네가 누굴 공격하거나 피해를 입으면 마법이 사라진다.\010$b내가 신호를 주기 전까진 몸을 잘 숨기고 있는 게 좋을 것이다. 정면으로 상대하기엔 악마가 너무 강하고 수도 많으니까."
rows["244:321492763"]="오레보르 피난처에 온 것을 환영하오, 친구여. 여기서는 아무것도 두려워할 필요가 없소. 우리는 뒤틀린 드레나이지만 당신의 적이 아니오.$B$B나는 쿠레나이의 이쿠티라고 하오. 쿠레나이는 드레나이 형제들과 그들의 새로운 동맹 간의 관계를 다시 수립하고자 하는 뒤틀린 드레나이의 단체요."
rows["244:489585052"]="십자군의 시험을 통과했으니, 이제 십자군 사령관의 시험에 참가하는 걸 고려해 보게. 가장 강한 이들만이 감히 이 시험에 도전해볼 수 있지만, 시험을 통과하면 들인 노력에 합당한 보상을 얻는다네."
rows["244:55175516"]="리치 왕 따위는 별로 신경 쓰지 않습니다. 수많은 거물이 오고 가는 걸 보아왔는데, 항상 무언가 엉망으로 만들어 놓더군요. 그리고 얼마 지나지 않아 다른 무리가 들고일어나 그들을 역사의 저편으로 보내버렸습니다. 리치 왕이라고 별다를 바가 없지요."
rows["244:728051265"]="운고로 분화구는 타나리스의 버섯구름 봉우리 너머 칼림도어 남쪽 멀리 있네. 가거든 둥둥 떠 있는 커다란 바위를 찾게나. 그 바위가 분화구로 들어가는 입구니까 말이야. 하지만 조심하게... 결코 쉬운 길은 아니라네. 입구에서 그리 멀지 않은 곳에 랩터들이 살고 있을 게야."
rows["244:930238945"]="그렇다면, 자네가 그 아뮬렛 조각 세 개에 부여된 악마의 보호막을 제거할 무기를 만들기 위한 길고 험난한 임무를 수행한다고 치세. 그다음에는 어쩔 셈인가? 파멸자의 은신처에서 그와 맞서기라도 할 텐가?$B$B<큰 소리로 비웃습니다.>"
rows["245:1071553822"]="이상합니다... 나가들이 우리를 살려둘 것이라고는 생각하지 않았으니까요.$b$b나가들은 생존자들 하나하나에게... 진주 거품을 만들어서... 숨쉴 수 있도록 해 줬습니다.$b$b나가들은 매일 사로잡은 포로들을... 어디론가 보냅니다.$b$b그렇게 떠난 포로들은 다시는 볼 수 없었습니다..."
rows["245:1086995397"]="정말 운이 좋으시군요. 방금 슈퍼 판매기 680의 정비를 마쳤는데. 아주 저렴한 물건이 잔뜩 쌓여 있습니다. 가서 한번 보시죠. 제 동생 코르크는 자동판매기 1000이 물건을 더 많이 팔 거라고 했지만, 흥!"
rows["245:1299532723"]="동부 거점 보초탑은 남쪽의 호드 영토와 투쟁의 벌판 사이에 통로를 확보하고 있습니다.$B$B현재는 호드가 점령하고 있습니다. 동부 서리늑대 보초탑은 서리늑대 마을과 서리늑대 요새 사이의 관문을 방어합니다.$B$B현재는 호드가 점령하고 있습니다."
rows["245:1447815141"]="저는 낙스라마스에서 잃어버린 일부 불성스러운 마법의 장갑과 조각을 결합하여 매우 가볍고 매우 치명적인 장갑을 만들 수 있습니다."
rows["245:1698555430"]="제대로 된 재료만 구한다면 투자개발회사의 사업에 피해를 주는 동시에 시선까지 돌릴 만한 폭발물을 만들 수 있어.$B$B벌써 감탄한 거 알아. 그런데 더 좋은 것도 있지... 때가 되면 알려줄게."
rows["245:1758255466"]="내 백성에게는 네가 잘 알려지지 않는다. 코도 는 강력한 양떼이고, 내 백성의 사랑과 보살핌의 결과물이다. 이 같은 양떼는 낯선 사람에게 주어지지 않는다. 썬더 블러프의 장로들이 너를 높이 평가할 때까지, 나는 너에게 코도 판매를 제안할 수 없다."
rows["245:22487097"]="잃었던 과거와 권좌를 되찾고자 아제로스 전역을 누비며 싸우느라 너무 오래 자리를 비운 듯하구나. 내가 없는 동안 얼라이언스를 시험에 빠뜨렸던 그 모든 일들을 생각해보면, 우리 연합을 지켜내는 그대와 같은 영웅이 있어서 내 마음이 얼마나 훈훈해지는지 모른다."
rows["245:225227141"]="전사 훈련을 받으려고 하십니까? 시간만 있다면 제가 누구보다 잘 가르쳐 드릴 자신이 있습니다만, 경비병의 직무 때문에 그럴 수는 없겠군요. 구 시가지에 있는 돼지와 휘파람 선술집이나 스톰윈드 병영 근처에서 상급 전사분을 찾아보시는 게 좋겠습니다."
rows["245:402252007"]="<드레이윈 경의 시선은 테이블에 흩어져 있는 문서에 달려 있습니다. 그의  ⁇ 은 눈, 그의 전두엽에 있는 접착증, 그리고 그의 눈 아래의 무거운 그림자는 모두 그레이스키의 장군을 깨어있게 하는 긴 관심사의 목록에 증거합니다.>"
rows["245:541495846"]="금속 주괴들을 얼마나 모았냐고 물었나? 내가 마지막으로 확인한 결과는 다음과 같다. 호드에 필요한 구리 주괴는 $1998w개인데 $2018w개를 모았고, 주석 주괴는 $2006w개가 필요한데 $2005w개를 모았다. 그리고 미스릴 주괴는 $2009w개를 모아야 하는데 $2008w개를 모았다."
rows["245:786424336"]="우핑 마스터는 거의 모든 무기를 숙달해 왔고, 특히 검 기술을 통해 치명적인 무기를 가지고 있습니다."
rows["245:918831454"]="자연과 소통하는 것 같은 건 없어요. 적어도 밤 엘프들은 그렇게 말하죠. 나는 꽃과 나무와 대화하는 게 별로 좋아하지 않지만,"
rows["246:1248265069"]="별말씀을요. 그런데 동굴 깊숙한 곳에 가면 같은 방식으로 작동하는 더 작은 열기 배출구 몇 개가 보일 것입니다. 시간이 조금만 지나면 동굴 안에서 그 배출구들을 이용해 더 자유롭게 이동하는 법을 배우게 될 것입니다. 아니면 여기 있는 비열한 불꽃꼬리 일족들을 곯려 먹는 용도로만 쓸 수도 있고 말입니다."
rows["246:1270459611"]="우리 상점의 물건들은 텔드랏실에서 가장 솜씨 좋은 장인들이 만든 것들로, 세계수의 나이트 엘프들과 이 땅의 인간들이 영광스러운 얼라이언스의 동맹으로서 관계가 발전함에 따라 그 우호의 표시로 칼림도어에서 아제로스까지 직접 수송한 것들입니다. 둘러보시다가 필요한 게 있으시면 주저 말고 말씀하시기 바랍니다."
rows["246:1315960635"]=" ⁇ 匠 키렌은 항상 더 호기심이 많은 학생들을 찾고 있습니다. 그의 섬세한 공예를 가르치기 위해. 그의 가게는 처음에는 발견하기 다소 어렵습니다. 하지만 그것은 바자르의 경매 집 북쪽에 있습니다. 당신은 건물의 하층에서 그를 찾을 것입니다."
rows["246:1486184610"]="여기 바쉬르에 이런 꼴로 처박혀 있는 게 어떤 기분인지 상상도 못할 거예요! 나를 해초 조각으로 착각해서 발가락을 물어뜯거나 방어구 사이에 숨는 물고기가 몇 마리나 되는지 아세요?$b$b간지러운 것 하나만으로도 드워프는 미쳐버리고도 남을 정도란 말이라고요!"
rows["246:1854354809"]="푸른용군단의 새로운 위상으로 칼렉고스가 선택되었습니다. 그대들 중 한 명이 데스윙을 향한 아리고스의 배신을 좌절시키는 데 중요한 역할을 했으며, 따라서 끔찍한 위기를 막아낼 수 있었습니다.$b$b우리는 그들의 영웅적인 행위를 기념하기 위해 이곳에 왔습니다."
rows["246:379493665"]="회복의 수정은 구하기 쉽지 않은 물건입니다.$B$B운고로 분화구에서 구할 수 있을 것이니 그리로 가보는 게 제일 좋은 방법일 겁니다."
rows["246:430432268"]="안녕하십니까. 저의 역할은 아제로스 세계에 창조주가 행한 토석인 합성에 대한 정보를 이용할 수 있게 해주는 일과 권한이 허용된 분에게 이 정보에 대한 지식을 제공하는 것입니다. 원하면 언제든지 정보를 이용할 수 있습니다."
rows["246:526794486"]="그 방법을 알면 얼마나 좋겠나? 그는 자네의 말에도 나의 말에도 귀를 기울이려 하지 않을 거라네. 사실, 그게 내가 아직 여기 머무는 까닭이지. 그래서 대모 카슈르와 이곳을 떠나지 않았다네. 그는 다시 마음을 다잡아야 해. 올바른 지도자가 없이 우리 종족은 이 겨울을 무사히 넘기지 못할 것일세."
rows["246:988219081"]="좋아, 바로 그 자세야!$B$B오늘 우리 회의는 아주 유익했네. 이제 공격 준비에 대해 한결 안심이 되는군. 자네 같은 감독관이 최전선에 버티고 있는데 우리가 어떻게 질 수 있겠나?$B$B좋아. 진격 명령을 내리도록 하지. 루안 숲으로 돌아가서 만반의 준비를 하도록!"
rows["247:1199438373"]="가죽 말인가? 그래, 방금 가죽에 대한 보고를 받았다. 호드에 필요한 질긴 가죽은 $2067w개인데 $2066w개를 모았다. 그리고 두꺼운 가죽은 $2071w개 중 $2070w개를 모았고, 튼튼한 가죽은 $2074w개 중 $2073w개를 모았다."
rows["247:1305267278"]="피드백은 항상 다 필요해요. 특히 다른 사람들과 일하면서요.$B$B재료를 나눠주거나 가난한 자사자를 죽게 만들 때, 저는 대부분 도움을 주죠."
rows["247:1315634892"]="예, 고왕 모그라인: 붉은십자군무진히 믿음과 순결의 기사인 모그라인은 자신의 아들로부터 배신받아  ⁇ 토즈드의 세력으로부터 죽임을 당할 것입니다."
rows["247:142041832"]="절 트윈이라고 부르세요. 모위도 절 그렇게 부르죠.$B$B우리가 똑같이 생겼다니 무슨 말씀이세요. 시력이 안 좋으세요? 모위는 노움이란 말이에요, 노움! 우린 행동을 함께해요. 특히 싸울 때 말이죠.$B$B제 이름에 대해서는... 혹시 와일드해머 브루워 얘기 못 들어 보셨어요? 한잔하면서 얘기할까요?"
rows["247:1437132717"]="우리 오크들이 반드시 풀어야만 하는 비밀이 이곳에 있네. 우리의 과거, 미래, 그리고 우리 내면을 살펴볼 수 있는 비밀들 말일세.$B$B이 비밀을 푸는 것이 내 소망일세... 자네, 나와 뜻을 함께하지 않겠나?"
rows["247:1467979731"]="- 그래$b$b<왜란은 긴, 평가적인 모습을 보여준다.>$b$b네 장비는 몇 가지 조정을 요구하고 있어, 알아? 어서, 가까이 가. 난 널 해치지 않을거야."
rows["247:1641764431"]="낚시란 참 즐거운 거란 말이야. 자네도 아나? 내 스승이자 전 세계에서 가장 훌륭한 낚시꾼인 내트 페이글 님 덕분에 이런 큰 기쁨을 누리게 되었지. 그분에 대해 들어 본 적이 있나?$B$B깨달음을 얻고 싶다면 내트 페이글 님께서 길을 보여 주실 걸세."
rows["247:1820989307"]="그림 바톨이 무너진 이래, 우리 와일드해머는 진정 힘을 합쳤던 적이 없네. 저 다양한 가문들은 여기 고원에서 세상에 잊힌 채 모두 자기들 방식대로 살아왔지.$B$B저들이 협력하게 하는 건 쉽지 않을 걸세."
rows["247:1945876543"]="적절한 질문이로구나.$b$b먼저 온천 근처를 찾아보거라. 서쪽의 절벽에서 봉화를 찾아보는 것도 괜찮겠지. 마지막으로 먼 북쪽의 실리더스에서도 위험이 도사리는 곳이니라.$b$b이 장소들을 수색할 생각이다."
rows["247:299674183"]="한때 그림누르가 창을 낚은 적이 있다고... 아, 참치라고 그랬나? 그림누르 녀석! 낚시 얘기를 워낙 많이 늘어놔서 뭐가 뭔지 기억이 안 나는구먼. 쓸쓸한 뒷골목에 있으니 당신이 직접 찾아가서 창인지 참치인지 확인해 보십시오."
rows["247:333766890"]="축제에 오신 것을 환영합니다! 저희는 전 세계의 진귀한 물건들을 모아서 전시하고 있습니다. 혹시 일반 다크문 카드 한 벌을 모으거든 알려주십시오. 주인님이... 아니, 제가 그 카드에 상당히 관심이 많아서 말입니다."
rows["248:1028564478"]="또 다른 강령술사? 얼마나 즐거운 놀라움!$B$B네크로맨틱은 대중들에게 잘 안겨지는 않지만, 지금껏 잘 이해하셨을 겁니다.$B$B여기 배우는 게 좋겠군, 그러니 친절에 시간을 낭비하지 말자"
rows["248:1202571128"]="아는 게 좀 있나 보군...$b$b몇몇은 저것들이 그저 우리를 관찰하고 있을 뿐이라 말하고, 몇몇은 해양 생태계를 교란한다고 생각하지. 심지어는 그들이 아제로스를 정복할 거라고 말하는 이들도 있다고!$b$b언젠가 내가 로켓 추진 탄두로 저것들을 쓰러트린다면 모든 의문이 풀릴 거야. 장담하지!"
rows["248:1486958646"]="제발 엎드려서 빌기라도 할 테니, 이 몹쓸 땅에서 우리를 좀 구해 주게. 비록 내가 마샬 원정대 소속이긴 하지만, 자네 배낭 안에 숨어 이곳을 뜰 수만 있다면 내 금니라도 뽑아서 주지."
rows["248:1913113472"]="축제에 오신 것을 환영합니다! 저희는 전 세계의 진귀한 물건들을 모아서 전시하고 있습니다. 혹시 일반 다크문 카드 한 벌을 모으거든 알려주십시오. 주인님이... 아니, 제가 그 카드에 상당히 관심이 많아서 말입니다."
rows["248:2039765862"]="이 왕국, 스톰윈드,는 두 개의 기둥 위에 세워져 있습니다. 왕권과, 그것이 있어야 할 것 처럼, 신앙입니다.$b$b가끔은 잊어버리거나, 혹은 그냥 방해가 되는 것 같네요."
rows["248:241949578"]="안녕하세요, 친구여!$B$B제 이름은 러셀입니다. 음악가지요. 과거의 위대한 와일드해머 영웅들은 노래 안에서 여전히 살아 숨 쉽니다. 우리 전사들은 제 류트와 목소리를 빌려 불멸의 존재가 되지요.$B$B잠시 제 노래를 들어보세요!"
rows["248:470541422"]="요리사가 되고 싶다고? 마을 남쪽에 있는 언더시티로 가서 수련을 받는 게 어때? 로데론의 폐허 깊숙한 곳에 아래로 내려가는 승강기를 탈 수 있네. 내려가거든 덩치 큰 언더시티 수호병에게 더 자세히 물어보게."
rows["248:492451815"]="숲은 변화의 씨앗과 함께 노래한다. 그렇지만 고통에 빠져 울기도 한다.$B$B우리의 새로운 동료인 드레나이도 그대와 같이 우리를 도우려고 이곳으로 왔다. 형제와 자매의 나무들이 종말을 맞고, 잿빛 골짜기가 사라지기 전에 이 파괴적인 행위는 종식되어야 한다."
rows["248:625697253"]="가끔은 저 유독한 피 엘프들이 와서 미련한 반응물이나 독을 요구합니다.$B$B<  ⁇ 푸스는 열심히 삼키고 있다. >$B$B우린 그런 걸 원하지..."
rows["248:779620185"]="리치 왕의 잔인한 통치는 노스렌드 전역의 주민들에게 커다란 고통을 안겨 주었답니다. 특히 아이들에게요. 만약 당신이 숄라자르 분지에 있는 점쟁이 조합이나 광란심장 일족의 친구라면, 한 주 동안만 고아를 하나 보살펴 주는 걸 고려해 보시지요."
rows["249:1022630886"]="붕대 수집은 예정대로 잘 진행되고 있습니다. 리넨 붕대를 살펴보면 지금까지 $2077w개 중 $2076w개를 모았습니다. 그리고 비단 붕대는 $2083w개 중 $2082w개, 룬무늬 붕대는 $2090w개 중 $2088w개를 모았습니다."
rows["249:1165491114"]="<로켓을 보고는 신경질적으로 미소 짓는 스니블>$b$b그래, 좋아, 내가 누군가에게 로켓을 몇 개 만들어 줬을지도 모르지. 그래서 어쩌라고? 보수가 괜찮았기에 일을 하고 돈을 받았을 뿐이야. 그래서 누가 죽기라도 했나? 이보다 더 정직한 일도 없다고. 자네가 무슨 상관이야?"
rows["249:1341830829"]="가죽세공을 한번 배워보실 생각이라면, 수정 호수 너머에 살고 있는 아델레 필더를 찾아가 보시는 게 좋을 겁니다. 헬렌이란 무두장이에게 남는 가죽을 얻어서 인근 경비병들의 해진 가죽 방어구를 기워주는 자원봉사를 하더군요."
rows["249:1396872675"]="눈 안의 핏빛 액체가 소용돌이치며, 대규모 스컬지 군사의 모습이 비칩니다. 이 눈이 마음속을 파고들 듯 당신을 잡아끌자, 당신은 본능적으로 몸을 뒤로 뺍니다. 이 눈의 존재가 편치 않습니다."
rows["249:167013388"]="잿빛 선고단의 계속된 희생과 그대 같은 영웅들 덕에 최후의 승리가 눈앞으로 다가왔다. 이제 스컬지에 대항하여 싸우는 이들을 돕고자 얼음왕관 성채로 왔노라. 우리는 함께 리치 왕의 포악한 압제를 끝장낼 것이다!"
rows["249:1788186652"]="이 축제는 전형적인 인간행동과 매우 대조적이죠. 이토록 불쌍한 독자적인 사람들이$B$B다르나서스은 지원하고 격려하기 위해 최선을 다해야 합니다."
rows["249:1849682576"]="저는 그렇지 않습니다. 리મ્બ라트는 이미 새로운 생명체가 분해된 땅에서 성장할 수 있다는 것을 증명했습니다. 이제 우리는 번식을 할 수 있는 방법을 찾아야 하고, 더 중요한 것은 성장을 지속해야 한다는 것입니다.$B$B제가 여기 있는 동안, 저는 또한 낙스라마스에 들어오는 모험가들에게 제 서비스를 제공하고 있습니다."
rows["249:2112807441"]="용에 대해서는 아는 게 별로 없지만, 하루는 거대하고 무섭게 생긴 용이 저기 있는 시간의 동굴 입구 근처에서 나타나더라고. 그 용은 계속 어떤 것에 대해 고함을 질러댔는데... 그게 뭐더라... 우리가 알고 있는 시간에 종말 어쩌고저쩌고했는데? 그다지 신경 쓰이지는 않더라고."
rows["249:2137561918"]="당연히 울트리스 마나괴철로 말이지요! 당신, 어디 멀리 여행이라도 다녀왔나요?$B$B마나괴철로에 과부하가 걸려 엄청난 폭발이 일어났습니다. 그 일로 현실 세계에 균열이 생겼고 그곳을 통해 공허에서 온 생명체들이 쏟아져 나오고 있습니다. 북동쪽으로 가면 아무 데서나 그놈들을 볼 수 있습니다."
rows["249:270804220"]="에코란 초자연적 힘이 흩어져 있는 형태이고, 부적은 그 힘이 정기로 집중된 것이라네. 난 강력한 주문을 외워서 에코를 부적으로 만들 수 있지. 마우아리의 부적을 사용해 자연의 힘을 자기 자신에게 반사시킬 수 있는 거라네."
rows["249:672764203"]="토륨 거점에 온 것을 환영하네. 나는 감독관으로서 토륨 대장조합에서 일어나는 모든 일을 책임지고 있다네. 우리가 주로 하는 일은 채광과 대장, 그리고 가벼운 경계 임무지만, 최근 들어 우리는 부득이하게도... 군사조직에 더욱 가깝게 변모했다네."
rows["249:806821430"]="죽은 자들의 날 동안 사람들은 무덤에 모여서 죽은 사람의 영혼을 축하하고 소중히 여기는 것입니다.$B$B여러분은 어떤 주요 도시의 묘지에 축제를 찾을 수 있습니다. 요리, 춤, 드론 복장 등을 할 수 있습니다."
rows["249:955437699"]="저 같은 늑대인간이 스테이크를 잘 구울 수 있다고는 생각지 못하셨을 겁니다.$B$B제가 워낙 날고기를 즐기다 보니... 쫓기는 동물의 헐떡임과... 동맥에서 얼굴로 뿜어져나오는...$B$B무슨 얘기를 하던 중이었죠? 아, 그렇죠! 저도 길니아스에 있을 땐 나름 미식가였답니다."
rows["24:1115062549"]="넌 해냈어, 우린 구해졌어!"
rows["24:1151639299"]="므흐르루므프흐 루므므르후므 프후르르!"
rows["24:1194636910"]="빛의 축복이 있기를!"
rows["24:1246661390"]="제게 뭘 가져오신 겁니까?"
rows["24:1258985540"]="좋아, 보강!"
rows["24:1360479508"]="원크와 야영지에 온 당신을 환영합니다."
rows["24:1383933430"]="뭘 보고 있는 겁니까?"
rows["24:1489148568"]="<*우르르*우르르*우르르*>"
rows["24:1645011476"]="그래? 무슨 일이냐?"
rows["24:1658854793"]="테라제인과 관련하여 좋은 소식은 없습니까?"
rows["24:1680072793"]="<쿨럭>$b$b난... 죽은 걸까?"
rows["24:186016743"]="우린 토림 님을 위해 일한다, 자매여."
rows["24:1924894323"]="감독관님, 필요하신 거라도 있으신가요?"
rows["24:2019491052"]="톨로... 자네 톨로 맞나?"
rows["24:2061107950"]="워시프의 지휘 위원회"
rows["24:230328778"]="<퉁명스럽게 목례를 하는 상사>"
rows["24:269336529"]="죽음의 품에서 우리는 다시 태어난다."
rows["24:299802508"]="반드시 복수하고 말겠소."
rows["24:307151003"]="고맙습니다! 절 해방시켜 주셨어요."
rows["24:339731410"]="뒷주머니 선장님이 최고라고요!"
rows["24:375609912"]="누구를 찾으십니까?"
rows["24:394629110"]="무엇을 도와주면 되겠나?"
rows["24:460758538"]="네페르세트 도시는 무너질 것이다!"
rows["24:481386032"]="안녕, 자기! 이 옷 어때요?"
rows["24:63843365"]="그리 강해 보이진 않는군."
rows["24:638501718"]="좋아. 날아갈 준비는 됐나?"
rows["24:879714318"]="목적지를 선택합니다."
rows["24:89658729"]="안녕하세요, 잘 생겼어요."
rows["24:904575551"]="뭘 쳐다보고 있는 겁니까?"
rows["250:1570552898"]="세나리온 의회가 어딘가에 기록해 두었을 정보를 찾고 있는 거라면 제게 말해 보십시오. 그렇지만 제 도움을 받으려면 먼저 당신 스스로 무슨 정보를 찾고 있는지부터 확실히 알아야합니다.$B$B이제 이해가 가신다고요? 좋습니다!"
rows["250:1684658331"]="이 마법석은 영원노래 숲이 스컬지에 의해 오염되지 않도록 막아줍니다. 서부 마법석은 오래전에 파괴됐기 때문에 우리는 그 주변을 불태워야만 했습니다.$B$B내가 살아 있는 한 나머지 마법석이 파괴되도록 내버려두지 않을 겁니다. 맹세합니다."
rows["250:1802099645"]="늙은 미르신스씨가 당신을 해치지 않을 것입니다. 그녀의 부족에서 쫓겨나고, 네, 그녀에게 충성하지 않는 사람들에게 충성도 없습니다. 늙은 미르신스씨가 아주 오래 전에 소소한 적대와 피 흘리는 것에 대한 열정을 잃었습니다."
rows["250:2047535473"]="그래, 위대한 엑소다르의 재건을 기꺼이 돕겠다고요? 엑소다르가 다시 원래 기능을 되찾으려면 몇 년은 걸릴 거라고 들었습니다. 당신에게는 두 시간을 드리지요. 농담입니다. 우리 기술자들은 교역 지구의 아래층에 있으니 그리로 가 보십시오. 성스러운 빛이 함께하기를."
rows["250:2072451167"]="우리 새로운 손님들은 우리의 일을 제한하고 있지만, 집단살인 시도가 일어나면 조심해야 하는 것은 당연한 일이지만, 시간이 지나면 그들이 푸트레스가 불행한 이상이었다고 확신하게 될 수도 있고,"
rows["250:380383365"]="저야 언제나 슬쩍한 괜찮은 물건에 관심이 많지요. 훔치는 일은 전부 손목에 달렸습니다... 그렇게 실패하면 갈비뼈 사이에 무언가 날카로운 걸 밀어 넣으십시오. 그것도 다 손목에 달린 일이지만요.$B$B능숙한 손재주가 있다면 매달 받는 월급봉투보다 훨씬 수입이 좋기 마련이지요. 듣고 계십니까?"
rows["250:454296134"]="빛의 이름으로! 타인의 안녕에 관심을 가지는 자가 있다는 것은 축복 받은 일이지요. 이렇게 어려운 시기에는 받을 수 있는 도움은 모두 받아야 합니다. 수정 전당의 수정 동굴 근처에 있는 누스가 당신에게 응급치료법을 가르쳐 줄 수 있을 겁니다. 성스러운 빛이 함께하기를."
rows["250:65425641"]="우리의 이성 기술력은 미묘한 본질을 이전에는 상상할 수 없었던 방식으로 변형시킬 수 있습니다. 우리는 작은 수수료로 주머니 차원에서 물건을 보관할 수 있습니다.$B$B내가 조사할 게 없는 한?"
rows["250:862624728"]="파수대는 칼림도어 전 지역에서 호드를 저지하고 있습니다. 잿빛 골짜기와 돌발톱 산맥에서는 전투가 계속되고 있지요. 하지만 이곳에도 우리 파수대가 필요합니다. 남은 야생 동물들을 보호하고, 우리의 적이 더는 근거지를 마련하지 못하도록 막아야 하니까요."
rows["250:990567001"]="<포세이큰의 눈은 두 개의 작은 돌고래입니다. 그녀의 머리 각 회전과 함께 그들은 그들의 뼈의 소켓에 둥글고, 광신경과 상속된 지표 손가락으로 묶여 있습니다.$b$b<그녀의 관심은 테이블에 누워있는 책상에 있습니다.>"
rows["251:1696713972"]="역병, 역병, 역병... 어딜 가나 그 얘기뿐이야. 다양한 맛이 없단 말일세!$b$b그건 그렇고 자네, 애완동물이 있지 않나? 물론 데리고 있겠지. 조그만 녀석들 말일세. 내게 그 애완동물을 위한 특별한 혼합물이 있다네. 그걸 사용하면 녀석들이 끔... 아니, 똘똘하고 힘센 녀석으로 변할 걸세.$b$b한번 실험해 보게!"
rows["251:1912286430"]="이 멋진 상점에 있는 빅시 워블봉크가 당신에게 단검 사용법에 대해서 알려줄 것이오. 아직도 다른 무기 전문가를 찾고 있다면 다르나서스에 있는 일예니아 문파이어나 엑소다르에 있는 한디르, 스톰윈드에 있는 우 핑이 몇 가지 무기 사용법에 대해서 알려 줄 겁니다. 난 단검 사용법에 대해서는 모릅니다."
rows["251:403866963"]="세계 최고의 채굴 작업 현장에 잘 왔다고. 멍청이가 아니고서야 왜 힘들게 산 아래 굴을 뚫고 그 아래 광물을 캐겠어? 우린 산 전체를 옮겨버렸다고! 이제 값비싼 금속을 땅 밑에서 꺼내기만 하면 돼."
rows["251:515167241"]="이 세계의 모든 것이 연관되어 있다는 것을 잊지 마시오. 만일 이 대지에 짐승들이 사라진다면 우리 종족은 영혼이 메말라 죽어버릴 것이오. 짐승들에게 무슨 일이 생긴다면 우리 타우렌도 결코 무사할 수 없소. 아제로스의 대지와 그곳에 사는 생명들은 운명을 같이하는 법이지."
rows["251:573067040"]="토르텔드린 왕자는 거대한 마법진 안에 어마어마한 힘을 가진 악마를 가두려는 계획을 세웠지요. 그 마법진은 수정탑들이 전달하는 눈에 보이지 않는 어떤 마력에 의해 작동하는 것 같았어요.$B$B이몰타르는 그 안에 갇혀 있는 동안 엘드레탈라스 주민들에게 힘의 원천이 되었습니다."
rows["251:820298754"]="안녕하세요! 저흰 저 아무짝에도 쓸모없는 해적 녀석들이 막고 있어서 완전히 발이 묶였어요.$B$B당신이 폭탄을 몇 발 떨어뜨려 주시면 도움이 될 것 같은데 생각 있으신가요?!$B$B도둑맞은 저희 비행선이 이제 거의 다 왔어요... 이제 소리가 들리는 것 같네요. 비행선이 떠나기 전에 꼭 타도록 하세요!"
rows["251:987693959"]="로서의 후예들 중 한 명을 데려갈 수는 있지만 그에게서 로서의 후예들을 뺏어갈 수는 없소.$B$B<어깨를 으쓱하는 대장장이>$B$B설명하기는 어렵지만 내가 지금 명예의 요새에 있어서는 안 될 것 같다오.$B$B좀 더 큰 곳으로 가야 할 것 같군."
rows["252:1522287"]="멧젠의 눈이 기쁨으로 밝게 빛납니다."
rows["252:1758571757"]="<고개를 젓는 누아인 스톰윙>$B$B한쪽에는 불타는 군단, 그 반대편에는 일리단의 졸개들이 있으니 이 성채를 지키려면 모든 수단을 총동원해야 합니다. 우리는 반드시 해낼 겁니다! 진정한 와일드해머라면 고향을 내어주느니 차라리 죽음을 택할 테니까요."
rows["252:1810878043"]="전 신도들의 보상이 자신의 행운을 생각해보고 주변 사람들과 공유하는 시간이라고 들었습니다.$B$B우리는 이 세상과 그 용기 있는 주민들을 발견한 것이 행운이고, 우리가 우리의 지식과 힘을 새로 발견한 동맹국들에게 제공한다는 것은 적절합니다."
rows["252:1918380383"]="성 빛의 교회는 세 가지 덕목을 전파합니다.$b$b존중해, 왜냐하면 그것은 우주의 공통 언어이기 때문입니다.$b$b끈기, 왜냐하면 믿음처럼 삶은 모든 방향에서 우리를 시험해$b$b자비가 없다면 우리의 목적지가 어떤 의미일까요?"
rows["252:2127051961"]="그렇다, 나는 '뒤틀린 드레나이'이지. 내가 뒤틀린 드레나이라고 해서 너에게 피해가 되는 일이라도 있나? 우린 사회 일부에서 우리를 향해 던지는 멸시의 시선을 견뎌야 한다. 이 세계의 정령을 더욱 잘 이해하고 원활하게 교감하는 것이 가장 중요한 일이지."
rows["252:25654524"]="잘못한 투자에 대해 얘기해 보게!$B$B발타라크 군주의 암흑 마법책은 벌써 암시장에서 고가에 팔렸다고. 그런데 그는 자기 물건이 도난당했다는 사실을 순순히 받아들이지 않았지. 그 나쁜 녀석은 벌써 몇 달 전에 죽었으면서 아직도 우리를 괴롭히고 있다네!"
rows["252:67843514"]="이 정도는 돼야 입을 만한 쇳덩어리라고 할 수 있지. 모양새에 기능까지 골고루 갖추다니 놀랐습니다. 이만한 건 예전에 딱한 번 본 적이 있는데 대용광로에 있는 장인인 그룸누스 스틸셰이퍼가 만든 것이었지요. 분명 그 친구는 그때보다 솜씨가 더 늘었을 거요. 당신에게 한 수 가르쳐 줄 수도 있겠군요."
rows["252:906841710"]="이 책 은 피부 작업 에 대한 당신 의 기술 을 알고 있으며 선택 을 제안 합니다. 하지만 경고 를 해 보십시오. 한 가지 를 선택 할 수 있으며, 그렇게 한 후에는 당신 의 생각 을 바꾸지 않을 것 입니다!"
rows["253:1093320434"]="이곳에 자주 오신 것 같은데, 일을 마친 후에 만나지 못하고 서로 계속 엇갈린 것 같네요.$B$B저 때문인가요?$B$B<일부러 기운을 내는 카티에>$B$B어쨌거나, 제가... 우린 당신이 하늘경비대를 위해 해 준 모든 일에 정말 감사드린다고 얘기하고 싶었답니다!"
rows["253:147451062"]="가을 축제라면 무조건 맥주와 먹을 거리들이죠, 게다가 저희가 만드는 음식보다 더 좋은 건 없답니다. 제 말이 거짓말 같죠? 저희의 맛좋은 맥주와 소시지, 프렛첼과 치즈를 한번 드셔보세요. 깜짝 놀라실 겁니다. 근방에서 만날 수 있는 최고의 음식인데다 가격도 이보다 더 쌀 수는 없으니까요!"
rows["253:1504335108"]="고맙구나, 필멸의 존재여. 꿈속으로 돌아가기 전에 네게 해줄 수 있는 게 딱 한 가지 있노라.$B$B제브림의 주인인 알진에게로 통하는 문이 너의 길을 가로막고 있으니 내가 그 문을 파괴할 수 있도록 도와주겠다. 명령만 내리거라. 그리하면 문이 열리리라."
rows["253:1714610051"]="나의 빛나는 천재성이 고작 상자 안에 담길 수는 없다고!$B$B잠깐, 여기가 아즈샤라 아니야?! 여긴 어디지? 저건 휴화산이로군!$B$B지금 난 무역왕을 만나고 싶은 마음 반, 꼬꼬 알을 무기로 만들 마음 반이야!"
rows["253:1899346801"]="오! 안녕하세요! 당신은 모험가일 겁니다. 정말 흥미롭습니다. 아조라 타워에서 도움을 드리고 있습니다. 정말 연습생입니다. 하지만 마침내 진짜 임무가 있습니다. 아직 그 지역을 떠날 수 없습니다."
rows["253:1921846425"]="환영을 원하는 건가?$B$B임무 수행 도중에 환영의 효력이 사라지면 내게 돌아오게. 그러면 다시 환영 마법을 걸어주지.$B$B실패해도 절대로 포기하지 말게! 내게 돌아오면 일을 마칠 때까지 돕도록 하겠네."
rows["253:1970973415"]="많은 포세이큰하지만, 만약 당신이 축하에 참여하기로 결정한다면, 칼림도어- 위층의 왕좌실에는 드루이드들이 있을 겁니다 언더시티 그쪽은 당신을 데려다 줄 것입니다."
rows["253:2053125269"]="여기 광산 훈련자가 있나요?  $B$B왜 당신은 모든  ⁇  모로그에서 최고의 광부 중 하나를 찾을 수 있습니다. 대 포지의 북쪽에 있는 딥마운틴 광부 기ilde에서."
rows["253:577680162"]="만약 숙소가 필요하다면, 돌불 숙소는 여러분이 있어야 할 곳입니다. 아이언포지의 입구에서 왼쪽으로만 찾을 수 있습니다.  $B$B저쪽으로 가면, 텐카드 준비하라고 말해"
rows["253:688242929"]="우린 너희처럼 수명이 짧지 않아, 말랑한 친구. 건강한 거인은 10년에 세제곱미터만큼 먹지. 뭐, 난 2년 정도에 한 번씩은 간식도 먹지만 말이야. 화장실은 배탈이 났을 때 빼고는 아마 15년이나 25년에 한 번 갈 거야."
rows["253:928023734"]="응급치료를 배우려면 빛의 대성당에 있는 샤이나 풀러의 지도를 받는 게 최고지요.\013\010\013\010그곳에 가시려면 노란 지붕을 찾아보시든가 대성당의 높은 첨탑을 찾아보십시오. 대성당은 도시의 거의 모든 곳에서 알아볼 수 있으니까요."
rows["254:102294918"]="토림은 자제력을 잃었다. 그는 가장 사랑하던 동료인 서리 거인들을 거세게 공격했지.$B$B오늘날, 이 땅이 호디르의 후예들과 힐드니르 사이의 전쟁으로 분열된 이유이다. 그리고 토림이 폭풍의 신전에 자신을 유배한 이유지."
rows["254:1036325581"]="<웃는 젠타브라>$B$B우리가 그 소문을 퍼뜨렸네. 잘라제인과 다른 이들이 우리의 흔적을 놓쳐 찾지 못하도록 하는 거지. 자네가 듣는 모든 걸 믿지는 말게나.$B$B우린 기술을 배우기 시작한 지 몇 년 밖에 되지 않았다네. 하지만 여러 가지로 우린 부름에 답할 준비를 하는 데 평생을 보냈지."
rows["254:1249510120"]="재봉사라고요? 여기 오래 있다 보니, 조르지오 볼레로란 자에 대한 얘기를 듣게 되었지요. 벌써 여러 해 동안, 동부 왕국의 유행을 창조해, 선도해 가고 있는 최고의 재봉사입니다. 그에게 재봉술을 배우고 싶다면 마법사 지구 외곽에서 찾아보십시오."
rows["254:1430209729"]="응급치료를 배우려면 빛의 대성당에 있는 엔젤라 라이펠트의 지도를 받는 게 최고지요.\010그곳에 가시려면 노란 지붕을 찾아보시든가 대성당의 높은 첨탑을 찾아보십시오. 대성당은 도시의 거의 모든 곳에서 알아볼 수 있으니까요."
rows["254:1452596610"]="둔기라면 불리위크의 전문 분야지요! 그는 투덜거리며 이 상점을 돌아다닌답니다. 그의 훈련 기술이 맘에 들지 않는다면, 한디르라고 둔기에 관해서 잘 아는 엑소다르에 있는 드레나이 무기 전문가가 있다고 들었으니 그리로 가 보십시오! 그는 엑소다르에 교역 지구에서 만날 수 있을 겁니다."
rows["254:2110557637"]="수련 중이지요! 곧 다른 소환사들과 합류하여 아킨둔의 어둠의 미궁에서 명성을 날릴 만큼 실력이 향상될 것입니다.$B$B정말 큰 놈을 소환할 기회가 생기면 좋겠어요! 울림만큼 큰 녀석이든가 그렇지 않으면 전 녀석의 통제권을 잃게 될 거예요!"
rows["254:24269690"]="저들은 강한 전사들이 사냥 나간 틈을 타 공격해왔어요. 얼라이언스가 본격적으로 쳐들어오기 전에 기적적으로 몇몇 분들과 함께 이 아이들을 대피시킬 수 있었지요...$B$B<아이들 앞에서 울음을 참으려 목소리를 낮추는 타와네>"
rows["254:352635690"]="내 뒤에 있는 보주는 한때 아제로스에서 일어나는 사건을 볼 수 있는 능력이 있었소이다.$B$B캘타스의 저주를 받아 모든 능력을 상실하긴 했지만 갇혀 지낸 긴 세월 동안 많은 마법사가 보주의 영상에서 위안을 찾았소이다.$B$B잊고 싶지 않다고 부르짖는 마법사가 있는가 하면 잊고 싶어 하는 마법사도 있었지."
rows["254:379725365"]="<왜란자 는 너무 심하게 숨 쉬고 있어 입에서 나오는 증기가 거의 완전히 숨기게 된다. 자세히 살펴보면,  ⁇ 과 녹색 얼룩이 가득한 피부,  ⁇ 이  ⁇ 고 화려한 껍질과 염증된 띠가  ⁇ 어지는 머리카락이 드러난다.>$b$b여기서 뭔가 잃었나?"
rows["254:68265909"]="이달리들은 뿌리줄이랑 토테마인 블랙 염소로부터 두려워하지만 전쟁의 절망에 의해 이끌려들면서 숲의 신들을 버리는 만큼 미쳤고 그 사물의 호의를 얻으려는 희망이 있다."
rows["254:776650803"]="많은 이들이 피의 마법을 어두운 데다 기억에서 사라진 기술이라 여겨 피합니다. 그런 점이나 다른 여러 면에서 악마의 마법과 겹치는 뚜렷한 특징이 몇 가지 있지요. 여기, 검은늪의 남은 악마 스컬지 무리 가운데에서 우리 피의 학문이 꽃피리라 믿습니다."
rows["255:1296288193"]="뭘 해야 하냐고요?$B$B축제 기간에는 전 세계의 모든 여관주인들이랑 \"사탕 하나 주면 안 잡아먹지!\" 놀이를 할 수 있어요. 그리고 여러 마을에 예쁜 장식이 달리니까 구경하러 한번 가보세요! 그리고 매일 저녁에는 언더시티 밖에서 밀짚인형 축제가 열려요."
rows["255:1345933775"]="칼리스레쉬 장군에게 가려면 기계박사 스팀리거와 풍수사 세스피아를 쓰러뜨리고 주 저장실 접근 장치까지 가야 합니다.$B$B장치에 도착하여 단추 몇 개만 누르면 주 저장실로 가는 문이 열릴 겁니다!"
rows["255:1826986563"]="우리 군대가 태양너울 무기고를 점령할 수 있도록 죽음의 흉터에서 양동작전을 펼치라는 임무를 받았습니다. 악마를 직접 처치하는 것만큼 멋지지는 않지만, 우리가 이길 수 있다면 그것으로 족하답니다.$B$B이 임무는 현재 $3233w 퍼센트 진행된 상태입니다."
rows["255:1959926699"]="이놈이 코도요! 어렸을 때부터 멀고어의 황금 초원에서 훈련을 받으면서 자란 이 멋진 놈들은 정말 최고의 탈것이라고 할 수 있소! 코도들을 직접 한 번 보시오. 우리 타우렌이 이 멋진 친구들을 믿는 이유를 알게 될 거요!"
rows["255:1972685666"]="당신을 여기로 보내 주신 여신께 감사를! 클로와 나는 이곳을 조사하던 중 늪군주 뮤즐레크의 습격을 받았소.$B$B안타깝게도 클로는 곰으로 변신한 상태에서 붙잡혀, 뮤즐레크의 소환수 신세가 되었다오.$B$B클로를 구하려면 그와 싸워야 할 거요."
rows["255:390053935"]="안녕하신가! 나는 왕관화학회사를 대표해서 여기 나왔어.$B$B선물이 필요해? 아니면 일? 아마 작게라도 무언가 자신에게 도움이 될 거 말이지? 음. 그럼 제대로 온 거야, 친구.$B$B네가 필요한 물건은 나한 테 없어. 우리 귀염둥이 큐이피나 내 옆에 있는 사랑의 상인이 가지고 있을 거야."
rows["255:545731803"]="빛의 결사단은 감히 성스러운 빛을 모욕하는 자를 처단하는 데는 그 어떤 단체보다도 뛰어나오. 언데드 같은 더러운 야수들을 세상에서 없앨 수만 있다면 우리는 어떤 행동이라도 할 거요. 그 무엇도 우리를 방해할 수 없소.$B$B당신은 우리와 함께하겠소, 아니면 우리에게 맞서겠소?"
rows["255:558915039"]="그대가 세운 공 덕분에 우리는 가까스로 이 거점을 지켜냈다.$B$B그대는 우리 동족들에게 소중한 동맹군을 데려다 주었지만, 적군은 계속해서 우리를 가차 없이 공격하고 있다.$B$B우리는 이곳을 지켜내야만 한다. 그렇지 않으면 우리가 그토록 얻고자 했던 것을 잃게 될 것이다."
rows["255:881264926"]="훈련 외에도 여러분들의 재능에 대한 지식을 여러분 마음에서 지워버릴 수 있는 능력이 있습니다. 이 절차를 거치면서 더 어려운 일이 되고, 따라서 더 비싸게 된다는 것을 경고하세요."
rows["256:160580315"]="와일드 스트릭! 와일드 스트릭! <수레리온은 훈련에 너무 집중되어 있어 당신을 알아차리지 않는 것 같습니다.> HMPH! 너무 느려! 와일드 스트릭! FLANK! 와일드 스트릭! <그녀는 당신을 알아차리지 않을 것 같습니다.> <아마도 그녀가 훈련하는 동안 관찰하는 것이 현명할 것입니다.>"
rows["256:224745390"]="조금 전에 새로운 보고를 받았습니다. 얇은 가죽은 $2061w개가 필요한데 현재까지 모은 것은 $2060w개인 것 같더군요. 다른 가죽을 보면 일반 가죽은 $2064w개 중 $2063w개, 두꺼운 가죽은 $2071w개 중 $2069w개를 모았다고 되어 있습니다."
rows["256:329004947"]="제 가족은 지금은 서부 역병지대라는 곳에 있는 북마루 벌목지에서 일했었답니다. 제 가족은 두마 가문을 위해 헌신적으로 일했죠. 하지만 이제는 붉은십자군이 하스글렌의 모든 것을 통째로 집어삼켜 버렸어요!$B$B그 광신도 녀석들이 아제로스에서 완전히 제거될 때까지는 전 절대로 쉬지 않을 거예요."
rows["256:907712784"]="토리움 형제단의 핵심요소$B$B아칸이트 결정은 풍부한 토륨 덩어리로부터 추출되며 강력한 화학자들의 알케미컬 실력으로 아칸이트 바가 탄생합니다.$B$B만약 당신이 광주를 찾는 사람이 아니라면 좋은 수학자도 찾아라!"
rows["257:1336126673"]="<잔에서 눈을 떼는 블런디>$B$B네, 맞습니다. 고위주술사님은 썬더마 폐허를 되찾으려고 전쟁터에 나가서 싸우고 계시죠. 저는 \"하급주술사\"입니다.$B$B고위주술사님이 자기가 없는 동안 썬더마의 모든 주... 술을 책임지라고 저한테 말씀하셨죠."
rows["257:1633886897"]="마랄리스 지휘관님이 요즘 제정신이 아닙니다. 부인이 남부 사막의 고대 발굴지에서 흔적도 없이 실종되셨습니다. 정말 이상한 일이 아닐 수 없습니다.$B$B별다른 단서는 없지만 말입니다. 혹시 이 일을 맡으실 생각은 없습니까?"
rows["257:1728466617"]="전쟁 기계를 새로 만들 수만 있다면 분노의 관문으로 가져가서 꽤 큰돈을 벌 수 있을 텐데 말이에요.$B$B예전에 몇 번 만들어 봤던 건 뭐랄까... 안정성 면에서 부족했지요. 하지만 여기에 있는 제 비행기는 효과적인 폭탄을 달아주기만 하면 꽤 쓸모가 있을 거라고요."
rows["257:1910729980"]="이 파괴된 황무지에 갇힌 우리는 살아남고자 최선의 노력을 다했소. 그렇게 세월이 흐르던 중 우리는 뒤틀린 황천에서 새로운 악마가 다가오고 있다는 것을 감지했소. 사악한 오크들보다도 더욱 끔찍하고 이 아웃랜드를 점령하려는 야심을 품은 그들이 바로... 불타는 군단이었소."
rows["257:2006280065"]="약 20년 전 얼라이언스는 오크들을 완전히 뿌리 뽑을 생각으로 이 세계에 첫 번째 원정대를 보냈소. 정말... 끔찍한 싸움이었지. 수많은 영혼이 아제로스의 안전을 위해 용감하게 싸우다 사라져 갔소이다.$B$B하지만 일부 영혼들은... 영원한 전쟁 속에 갇혀 있다오."
rows["257:261535575"]="스톰윈드 장교들이 대부분의 병력을 외부로 파견했다니 믿을 수가 없습니다. 지금 고향 땅의 전선이 이처럼 위험한데 말입니다.$B$B서부 몰락지대에서 도적떼가 몰려오고 동쪽, 서쪽에서 놀의 무리가 침입해 오고 있습니다. 그런데도 스톰윈드가 아직 포위되지 않았다는 게 놀라울 정도입니다."
rows["257:290253718"]="메디브와 관련된 모든 질문은 집사인 모로스 님께 물어보십시오. 저는 주인님께서 하시는 일에 대해 아는 게 거의 없습니다. 몇몇 귀족들이 연회장에서 모로스 님을 알현하고 있으니 궁금한 점이 있으면 가서 물어보십시오."
rows["257:390376597"]="영혼이 당신의 눈을 뚫어져라 응시합니다. 손을 잡는 것이 느껴집니다. 당신의 온몸에 매우 따뜻한 온기가 퍼지면서, 거의 무릎까지 후들거릴 지경입니다.$B$B온기가 지나간 자리에 당신의 결의를 더욱 굳건하게 해줄 곰의 영혼이 존재하는 것이 어렴풋이 느껴집니다."
rows["257:391338004"]="구 시가지, 돼지와 휘파람 선술집에 훌륭한 요리사가 일하고 있습니다. 우리끼리니까 하는 얘기지만, 요리할 때 칼 놀리는 솜씨를 보아하니 전에 요리사 말고 다른... 일도 했을 것 같더군요. 뭐, 이상한 상상은 하지 마시고... 요리를 배우고 싶으시다면 여기서는 그가 최고니까 찾아가 보십시오."
rows["258:1179585139"]="바시르 수정괴철로는 에펙시스 결정을 불안정한 마술사의 영약으로 변환하는데 쓰입니다. 이 영약을 마시면 지능이 증가하고 원기가 왕성해지며, 공격력과 치유 능력이 증가합니다.$B$B아래 목록에서 선택하시기 바랍니다."
rows["258:1751049152"]="전투 후 누가 우리 전사들을 붕대시켜야 한다고 생각하니"
rows["258:1820866755"]="어릴 때 생각이 나는군요... 다른 애들은 모단 호수 바닥으로 헤엄쳐 간 다음 성게나 바닷조개를 집어오곤 했죠. 오스카 형님과 저는 호숫물 위에 떠있었을 뿐이었어요. 허공에 대고 허무하게 발장구를 쳐봤지만, 친구들 있는 곳으로 내려갈 수 없었답니다."
rows["258:1830192041"]="난 그런 내용을 말해줄 만큼 널 믿지 않는다.$b$b넌 우리 백성이 겪었던 시련과 우리가 지녀온 괴로움을 존중해야만 한다.$b$b네가 던 니펠렘에 거대한 영광을 가져온다면, 우리 백성의 지식을 네게 공유해 주도록 고려해 줄 수 있을 거다."
rows["258:1838252443"]="저들은 내 말을 두려워하지. 저들은 날 본보기로 삼았다. 이건 진정한 신이신 넵튤론 님을 조롱하는 일이다.$B$B<침을 뱉는 스카디스>$B$B필멸의 존재여, 저들은 천벌을 받을 거다. 언젠가 바다사냥꾼의 영광스러운 손이 낫으로 잡초를 잘라내는 듯이 신을 믿지 않는 자들을 쓸어버리리라."
rows["258:2146876152"]="우리 세나리온 드루이드는 자연의 균형을 지키는 수호자들이오. 핵심은 균형을 유지하는 것이지. 우리 드루이드는 어떤 일을 부탁받아도 결정적인 행동을 취할 때까지 오래 지체하지 않소. 다른 이들의 말은 듣지 마시오. 특히 우리 중에 여기저기 기웃거리기만 하는 자들의 말은 절대로!"
rows["259:1097209708"]="아웃랜드 전 지역에서 가장 위대한 전승의 보고를 내가 여기에 만들었소. 심지어 실버문의 웅장한 도서관들도 따라오지 못할 정도라오.$B$B자, 부디... 둘러보시오. 마음껏 열람하고 읽으시오. 모두 체계적으로 잘 분류되어 있다오."
rows["259:1227648837"]="북쪽에 아주 강력한 힘을 지닌 인간 마법사가 산다는 소문이 있소. 어째서인지 이 땅을 감시하고 있다더군. 나도 직접 만난 적은 없지만 들리는 바로는 누구든지 방문할 수 있고, 그자가 시키는 일을 좀 해주면 아주 친절하게 대해 준다고 하더이다."
rows["259:1756058352"]="<야스퍼는 의자에 앉아 있고, 그의 눈은 넓고 깜박이는 채 벽을 쳐다보며, 입은 약간 열려 있고, 시위는 갑자기 몸으로 흔들리는 귀가 들리는 콧물 발발로 깨질 뿐이다.>$B$B방해받지 않고 남긴 게 좋을 것 같아요"
rows["259:2000966071"]="저는 높은 둑 전진 부대에서 나왔습니다. 여기 썬더마의 와일드해머 드워프를 우리 편으로 끌어들이려고요.$B$B아마도 제가 이들에게 도움을 줄 수 있을 것 같은데요, 나 원 참 기가 차서... 이 친구들, 삼환식 재분극 장치도 하나 안 가지고 있다니까요? 단 한 개도요!$B$B대체 어떻게 지금까지 헤쳐나온 걸까요?"
rows["259:313532951"]="제 일은 이 가엾은 영혼들을 돌보는 것입니다. 도와주실 분이라면 알도르 사제회든 점술가 길드든 상관없이 환영합니다.$B$B일손이 너무 부족해서 붕대 감을 줄만 안다면 오우거라 해도 돌려보내지 못할 판이랍니다. 이 도시의 정치 문제야 제 알 바 아니죠."
rows["259:400071779"]="저주받을 용아귀 놈들!$B$B놈들이 우리 그리핀을 죽이고, 우리 가족들을 공격하고, 우리 땅을 빼앗았습니다. 세상이 무너져내리는 이런 때에도 놈들은 계속해서 우리를 공격하고 있어요.$B$B당신네 얼라이언스가 와일드해머를 돕고 싶다면, 우리 마음을 얻을 방법은 단 하나뿐입니다. 용아귀 부족을 저지해 주세요."
rows["259:50035629"]="새로운 식물 종에 대해 배우는 것은 우리 원정대에게 매우 중요한 일입니다. 의학용이나 식용이 아니라 해도 마찬가지이지요.$B$B식물은 다른 형태의 생명이 살아가는 데 필요한 초석이 됩니다. 식물을 이해하면 자연을 전체적으로 이해할 수가 있지요."
rows["259:985581874"]="참으로 놀라운 검입니다. 그렇죠? 드워프가 만든 건 아닙니다. 네. 훨씬 오래된 검이죠.$B$B선리버와 은빛 서약단의 대표자들은 이 수수께끼를 끝까지 파헤쳐 볼 모양입니다. 전 이미 브란에게 보낼 보고서를 작성하고 있지요."
rows["25:1207924838"]="응, 뭐야? 무슨 일이지?"
rows["25:1347933612"]="어떤 직업 상급자를 찾으십니까?"
rows["25:1385986640"]="므프흐므므 르므프흐히므므 르르후므그흐프흐?"
rows["25:1454702310"]="아빠, 뭔가 쏴버리고 싶어요!"
rows["25:1469243837"]="뭔가 좀 사고 싶으신가요?"
rows["25:1777357382"]="어둠의 여인이 널 지켜보고 있어"
rows["25:1881254758"]="코 속에 돌이 낀 것 같아요."
rows["25:1988230771"]="<화장실은 조용합니다.>"
rows["25:2111650936"]="아케이나이트 부표라는 말을 기억해라."
rows["25:256627176"]="일을 시작할 준비가 되었으면 좋겠군."
rows["25:280101703"]="구인광고/분실물센터/현상 수배:"
rows["25:398957990"]="뭐라?"
rows["25:64091823"]="그런데 \"저그 저그\"가 무슨 뜻이에요?"
rows["25:645187562"]="원하는 게 뭡니까?"
rows["25:812231498"]="누가 저를 찾으셨습니까...?"
rows["25:935338814"]="드디어 제 영혼이 해방되었군요!"
rows["25:962063054"]="음? 저한테 원하는 게 있나요?"
rows["25:963020387"]="물고기는 목마른 적이 있나요?"
rows["260:1273040097"]="메린이 만들어 내는 옷을 바라보면 마치 엘룬께서 그녀의 바늘에 축복을 내리신 듯하답니다. 그대에게 그런 축복받은 재능이 있지 않은 이상, 메린을 찾아가 가르침을 구하는 것이 좋을 겁니다. 다르나서스 북동부에 있는 장인의 정원에서 그녀를 만날 수 있습니다."
rows["260:1492682946"]="당신에게는 큰 잠재력이 있지만 먼저 이해심부터 키워야 하오. 영혼의 힘을 인정하고 그들의 부름에 귀를 기울여야 하지. 그제야 비로소 당신이 가야 할 길을 걸을 준비가 된 거요. 가서 트라그와 얘기를 나눠보시오. 어쩌면 당신 둘은 서로 많은 도움이 될 수 있을 것 같단 생각이 드니까."
rows["260:1794631050"]="아, 병을 치료하는 사제보다 더 좋은 것은 없습니다. 물론 좋은 높은 술은 많은 병을 치료합니다. 하지만 브레엔나 플린트크래그가 맥주 만드는 법을 가르치지 않는다고 생각합니다."
rows["260:253054746"]="내 말 들어 봐, 코렌 다이어브루는 미치광이야.\010\010그 녀석이 가을 축제에 초대받지 못한 건 내 탓이 아니라고! 그런데도 녀석과 그의 검은무쇠 일당은 막무가내로 내 직원들을 두들겨 패고는 내가 만든 맥주를 모두 마셔버렸어.\010\010누가 나서서 본때를 보여 줘야겠어!"
rows["260:332772346"]="잭의 부하들이 보는 앞에서 그에게 수작을 부리겠다고요?$B$B뭐랄까... 바보 같은 생각이네요. 혼쭐이 날 걸요. 난 금화 한 닢도 안 되는 돈에 목숨을 걸 생각이 없어요. 그러니 일을 저지를 거면 내가 이 자리를 피할 때까지 좀 기다려 줘요."
rows["260:749841373"]="무두질이라고요? 당신이 무두질을 할 수 있는 데라고는 자기 무릎뿐일 것 같은데요? 하하! 농담입니다. 발투스 스톤플레이어를 찾으세요. 짐승의 가죽을 제대로 벗기는 법을 가르쳐 줄 겁니다. 대용광로 북쪽에 있는 파인스핀들의 가죽 상점으로 가보십시오."
rows["260:932134494"]="내 말 들어 봐, 코렌 다이어브루는 미치광이야.\010그 녀석이 가을 축제에 초대받지 못한 건 내 탓이 아니라고! 그런데도 녀석과 그의 검은무쇠 일당은 막무가내로 내 직원들을 두들겨 패고는 내가 만든 맥주를 모두 마셔버렸어.\010누가 나서서 본때를 보여 줘야겠어!"
rows["260:966514751"]="바로 그때! 부인이 잠깐 정신을 차리는 것 같더니 바로 곤충 집으로 들어갔습니다. 브란 님이 말릴 새도 없이 말입니다! 전투가 시작되기 전에 그녀는 누군가와 이야기하기 시작했죠. 아니 물건이었던 것 같기도 하고... 어쨌든 대화를 했습니다. 그렇게 점점 미쳐가는 것 같더니 한 번도 들어본 적이 없는 언어로 주문을 외우기 시작했어요."
rows["261:1118881235"]="황혼의 망치단이 고원 전역에서 우리 고리회를 공격해 많은 지역을 손에 넣었네. 여기가 마지막일세. 놈들이 대지에서 어떤 무시무시한 것을 불러내도, 여기마저 내줄 수는 없네."
rows["261:1615038271"]="동물의 피부를 사용하면 먹이를 먹거나 보호를 위해 떨어져야 합니다. 우리는 지구 어머니를 존중하고 동물에 대한 존중을 제공합니다. Chaw Stronghide는 이런 것들을 가르쳐 줄 수 있습니다. 당신은 그를 볼 것입니다."
rows["261:1652343614"]="알려 드릴 게 뭐 있겠습니까? 이놈들은 거미입니다. 단지 당신이나 제가 보던 보통 거미들보다는... 화염 속성이 더 많을 뿐이지요.$b$b이놈들은 물기도 하고, 거미줄도 치고, 화끈거리는 독도 뱉고, 또 제 가장 친한 친구들을 사로잡아 타는 듯이 뜨거운 비단 고치로 만들기도 하지요. 아주 끔찍한 놈들입니다."
rows["262:1126434881"]="스톰윈드 장교들이 대부분의 병력을 외부로 파견했다니 믿을 수가 없습니다. 지금 고향 땅의 전선이 이처럼 위험한데 말입니다.$B$B서부 몰락지대에서 도적떼가 몰려오고 동쪽, 서쪽에서 놀의 무리가 침입해 오고 있습니다. 그런데도 스톰윈드가 아직 포위되지 않았다는 게 놀라울 정도입니다."
rows["262:1409947872"]="아담스 경비대장님께서 할그린드에서 벌어지는 일을 조사하도록 나를 여기 보냈소. 하지만 이 이상은 다가갈 수 없소. 그나마 이 버려진 브리쿨 탑 덕분에 감시의 눈길을 피하는 거라오.$B$B포세이큰이 저기서 뭔가 대단히 나쁜 일을 꾸미는 게 분명하오. 느껴진다고!"
rows["262:1428977282"]="불과 300년 전, 타우릿산이라는 무모한 드워프 하나가 주인님을 불타는 세계로부터 소환해냈다. 주인님께서 이 보잘것없는 작은 세계로 귀환하시는 것만으로, 땅이 파괴되고 화산의 심장부가 생겨났지. 그때부터 위대하신 라그나로스는 이 산 아래 잠들어 계신다."
rows["262:2017926545"]="이 지혜 는 위대한 썬더 블러프 에서만 발견 될 수 있는 신비 로  ⁇ 어 있다. 블러드하프 마을 에서 북쪽 으로 나가는 길 을 따라가며, 돌벽 아래 에 있는 엘리베이터 에 도착 할 때까지 그 위로 올라가서 블러프워치 의 한 사람 에게 추가 도움 을 요청 하십시오."
rows["262:2065867687"]="이곳 브릴에는 전문 기계공학자가 없지만 저 아래 언더시티에는 한 명 있지. 마을 남쪽에 있는 로데론의 폐허로 깊숙이 들어가서 승강기를 타고 내려가게. 그곳에서 언더시티 수호병에게 한 번 더 물어보게."
rows["262:412958817"]="맞춤형이라고? 어머. 아, 물론요. 썬더 블러프북쪽에서 마을 밖으로 나가는 길을 따라, 블리프 밑에 도착하면 엘리베이터를 타고 승강장 꼭대기에 올라 블리프워치 중 한 명과 이야기해 보세요."
rows["262:511151390"]="그렇지. 말가니스는 십자군 광장에서 스컬지들을 지휘하고 있는데, 도시 입구에서 그곳으로 가는 성문은 닫혀 있다.$B$B하지만 놈은 소규모 부대가 마을회관을 지나 광장에 들어갈 수 있다는 사실은 모를 게다. 귀관도 이 공격에 참여하겠나?"
rows["262:656082544"]="저도 검은용군단이 신 카르가스에 공격을 퍼붓고 있다는 소식에 당신만큼 많이 놀랐습니다. 고른은 고집이 세서 누구의 도움도 받지 않으려 합니다.$b$b그렇다고 해도, 고위 검사관 블러드워처 님은 제게 일이 지저분해지지 않도록 유심히 지켜보라고 지시하셨습니다."
rows["263:132494627"]="에테리얼 기술자 3인방이 스톰윈드에 가게를 열었습니다. 대성당 광장 남쪽의 대운하를 따라가면 찾을 수 있지요.$b$b세 바람의 마법상점이라는 가게입니다. 기묘한 기계들과 보라색 불빛을 찾아보면... 바로 찾을 수 있을 겁니다.$b$b그 3인방이 당신이 찾던 서비스를 제공해줄 것입니다."
rows["263:1432323155"]="놈리건으로 모험을 떠난 용감한 노움들이 가져온 기술 일부를 가지고 내가 물체 순간이동기라는 아주 엄청난 발명품을 만들어 냈죠! 이제 순간이동기에 맞게 조율된 강력한 유도장치를 만들 실력 있는 노움 기술자만 있으면 되는데 말이에요."
rows["263:1717247102"]="수많은 약점이라고요? 벡터 코일의 약점은 서쪽 구조물의 기반과 동쪽 구조물의 기반 두 곳밖에 없습니다. 이봐요, 잠깐. 벡터 코일에 대해 어떻게 알고 있는 겁니까? 당신은 완전한 형태를 갖추기도 전에 붙잡혔다고 말하지 않았습니까?"
rows["263:1924147342"]="내가 왜 그딴 걸 굳이 기억하고 있어야 하지? 좋아, 이렇게 하지. 내가 이런 일을 참고 견뎌야 할 만큼 돈을 많이 받은 것도 아니고, 계약서에는 그냥 비밀로 하라고만 적혀 있었어. 그러니 내가 여기 바닥에 장부를 떨어뜨리지. 그거 줍고 제발 날 가만히 내버려 두라고.$b$b알겠나?"
rows["263:5616109"]="리치 왕은 아제로스의 대도시를 상대로는 소규모 병력만 보냈고, 주요 병력은 다음 도시를 주기적으로 공격하고 있습니다.$B$B아즈샤라, 저주받은 땅, 불타는 평원, 타나리스 사막, 동부 역병지대, 여명의 설원"
rows["263:69320125"]="그렇게 작은 지역에 그토록 많은 죽음과 절망이 도사리고 있다는 게 상상조차 안 되겠지만, 저 늪에서 한 발짝만 넘어서도 혼돈과 파괴로 물든 땅이 있지.$B$B모험가 친구, 발밑을 조심하시오. 저주받은 땅은 당신보다 훨씬 강한 자들의 마지막 안식처니까 말이오."
rows["263:83535737"]="고향인 서부 몰락지대에 생긴 문제를 해결하려고 전선을 떠난 적이 있지. 참 아득하게 느껴지는군. 이제 데피아즈단을 걱정할 필요가 없다는 게 얼마나 다행인지 모르겠네.$B$B우린 지금 고향 서부 몰락지대에서 멀리 떨어진 곳까지 와 있네. 하지만 우리가 이 전쟁에서 이기지 못한다면 우리가 돌아갈 고향 따위는 없어질 걸세."
rows["263:844387276"]="저 거대한 흙더미가 모래언덕 아래 주변으로 움직이는 걸 본 적이 있나? 놈들은 아제로스에서는 보이지 않았던 땅굴 벌레와 같은 종에 속하는 것들이라고! 저 사나운 것들은 자네같이 노련한 모험가가 배움을 통해 경험을 쌓을 대상으로는 아주 적절하지."
rows["264:1207129892"]="이건 전문적인 장비야 조심하지 말고 너무 많이 롬을 먹었으면 안 써$B$B그 얘긴 할 때... 그런 거칠게 있는 건 없잖아?"
rows["264:133768463"]="이곳 상황을 볼 때 원정대 거점은 군대가 주둔하기 어려운 지역이지만 명예의 요새 방어를 위해 중요한 곳이오. 이곳에서 얻는 정보와 우리 병사들이 불타는 군단과 제스고르의 오크들을 상대로 벌이는 교전은 얼라이언스가 지옥불 반도로 출정을 하기 위해 매우 중요한 것이지."
rows["264:1526070438"]="이야, 이런 곳에서 다른 모험가를 만나리라고는 상상도 못 했군요!$B$B여기 계신 여러분은 제가 심판장에 가는 걸 도와주시겠지요? 이 장소에 대한 제 연구가 옳다면, 드워프 창조와 관련된 정보가 여기 있을 겁니다!"
rows["264:1626264614"]="이런 냄새 나는 구덩이에서 뱀 같은 놈들한테 둘러싸여 있는 것도 다 임무를 위해서요.$b$b퓨트리스가 분노의 관문에서 끔찍한 짓을 벌인 이래, 대족장님께서는 이 족속을 믿지 않으시오. 놈들을 내팽개쳐 버릴 수도 있을 정도지. 그래서 우리가 여기 있는 거요. 이제 연금술사들은 내 허락 없인 아무것도 할 수 없소."
rows["264:1942216890"]="늑대인간으로 바꿔줄 방법이 없음을 살스베리에게 몇 번이고 설명했소. 귓등으로도 들으려 하지 않더니 오히려 내게 신임을 얻으면 비밀리에 해주리라 생각하더군.$B$B노움은 참 이상한 종족이오."
rows["264:1980143055"]="이곳 브릴에는 은행이 없으니 언더시티로 가야 하네. 남쪽에 있는 로데론의 폐허로 깊숙이 들어가면 언더시티로 내려가는 승강기가 있지. 일단 언더시티로 가면, 수호병 중 한 명에게 좀 더 정확한 길을 물어보도록 하게."
rows["264:650389699"]="지옥 수정괴철로로 당신의 에펙시스 결정을 불안정한 야수의 영약으로 변환할 수 있습니다. 이 영약은 더 민첩하고, 강해지면서 체력이 좋아지게 합니다.$B$B그렇지만 1개의 영약을 만드는 데 필요한 10개의 결정을 지니고 있지 않아서 이 괴철로를 작동시킬 수 없는 것 같습니다."
rows["265:1447844075"]="리치 왕은 아제로스의 대도시를 상대로는 소규모 병력만 보냈고, 주요 병력은 다음 도시를 주기적으로 공격하고 있습니다.$B$B아즈샤라, 저주받은 땅, 불타는 평원, 타나리스 사막, 동부 역병지대, 여명의 설원"
rows["265:1686671327"]="이곳 브릴에는 은행이 없으니 언더시티로 가야 하네. 남쪽에 있는 로데론의 폐허로 깊숙이 들어가면 언더시티로 내려가는 승강기가 있지. 일단 언더시티로 가면, 수호병 중 한 명에게 좀 더 정확한 길을 물어보도록 하게."
rows["265:1705281627"]="흠... 당신 작품이 괜찮긴 하지만 아직까지 내가 바라는 기술에는 근처도 가지 못했군요. 황금골에 가서 대장장이 아르거스를 만나보세요. 그 친구가 기본기를 가르쳐줄 거예요. 기본기를 다 배우거든 다시 날 찾아오세요. 그러면 내게서 대장기술을 배울 준비가 됐는지 몇 가지 시험을 해보겠어요."
rows["265:17856200"]="얼음 늑대 영토로 들어가지 말고 군인, 이 망할 곳이 모두 폭탄에 갇혀 있어"
rows["265:393252059"]="안녕하십니까, 감독관님! 휴가라도 오셨나요? 다시 루안 숲으로 발령받으신 후로는 이 근처에서 거의 못 뵌 것 같은데...$B$B제가 물건 좀 봐주십시오. 마지막으로 뵀을 때와 비교해서 별로 바뀐 게 없을지도 모르지만 대신 양이 아주 많아요.$B$B그리고 앞으로는 아는 척이라도 좀 해주세요!"
rows["265:514361765"]="오크를 때려잡고, 트롤을 박살 내고, 오우거 옆구리에 이름을 새기는 것까지는 할 수 있습니다. 하지만 짐승의 가죽을 벗기는 건 정말 못 하겠어요. 생각해 보세요, 정말이지...\010무두질을 할 만큼 비위가 강하시다면 구 시가지에 있는 태너의 가죽용품점에서 매리스 그랑거를 만나 보십시오."
rows["265:551751467"]="오크를 때려 잡고, 트롤을 박살내고, 오우거 옆구리에 이름을 새기는 것까지는 할 수 있습니다. 하지만 짐승의 가죽을 벗기는 건 정말 못 하겠어요. 생각해 보세요, 정말이지...$b$b무두질을 할 만큼 비위가 강하시다면 구 시가지에 있는 터너의 가죽용품점에서 매리스 그랑거를 만나 보십시오."
rows["265:750035833"]="이 잔다이스 바로브의 일지는 언데드에 대한 욕설과 분노로 가득합니다. 책 뒷부분까지 읽어보니 어떤 가방을 만드는 도안이 그려져 있습니다. 하지만, 이 도안을 해석하기에는 당신의 재봉술에 대한 이해가 조금 부족합니다."
rows["265:846974265"]="고대의 학카르 제단이 방 입구 가까이 놓여 있습니다.$B$B제단 위를 살펴보니 커다란 뱀 모양의 석상이 놓여 있고 그 모양은 제단 위에 있는 모양과 굉장히 흡사합니다. 그 둘에는 뭔가 관련이 있는 듯해 보입니다."
rows["265:962101858"]="다 됐습니다. 양쪽 모두 물자 수집을 완료했어요. 현재 모든 물자를 실리더스로 수송하는 중이며 적어도 $2113w일 안에는 모두 보내야 한다는군요. 만반의 준비가 끝나고 누군가 흐르는 모래의 홀로 스카라베 제단의 징을 울리면 전쟁이 시작되는 겁니다."
rows["265:980727705"]="리치 왕의 침략에 대항하여 호드와 얼라이언스가 노스렌드로 전진할 때가 왔습니다. 최근 칼림도어와 동부 왕국의 여러 지역이 공격 받고 있다는 소식입니다. 놈들의 손에 파괴되고 있는 우리 땅을 지키기 위해 무기를 들 각오는 되어 있습니까?"
rows["266:1080631315"]="동료가 심연을 넘어 침입해온 악마들을 막는 동안 나는 마법을 사용하여 끝없는 어둠 너머에 도착했소. 그곳에서 나는 절대적인 성스러움과 순수함을 간직한 존재, 바로 거대한 빛 자체를 느꼈소.$B$B내가 발견한 것은 아달과 그의 나루였소. 그것은 한마디로... 기적이었소."
rows["266:1169725114"]="용아귀 부족은 타락했습니다. 그들은 이 섬의 모든 천연자원을 깡그리 캐내어 검은 사원의 밖에 있는 일리단의 군대를 지원하는데 사용하고 있지요. 그렇게 자신들을 위해 너무도 애를 쓰고 있음에도, 몰래 숨겨둔 것들을 최고 값을 부르는 자들에게 팔아버리고 있는 것입니다."
rows["266:1297030634"]="잘했어요! 이제 스트라솔름의 곡식이 오염됐다는 걸 알았으니 아서스는 마을을 파괴할 거예요.$B$B하지만 아직도 뭔가 잘못돼 가고 있어요. 이 시간대에 우리 이외의 다른 존재가 있음이 느껴지는군요. 무한의 용군단이 여기 어딘가 있다는 뜻이겠지요."
rows["266:1553670823"]="저 앞에 있는 식량을 보면 무지개날개다랑어 구이는 $2093w개가 필요한데 $2092w개를 모아서 보관해 둔 것 같습니다. 또, 랩터 숯불구이는 $2099w개 중 $2098w개, 점박이놀래기 구이는 $2103w개 중 $2101w개를 모아서 냉장 창고에 저장해 두었습니다."
rows["266:1585957714"]="그리핀을 타는 게 싫으신가 보군요. 다행히도 조금만 깊숙이 들어가시면 다른 방법으로 이동하실 수 있습니다. 깊은굴 지하철이라고 노움이 건설한 편리한 이동 수단인데, 드워프 지구 후미진 곳에서 탈 수 있습니다."
rows["266:187413252"]="보아하니 이교도들이 드루이드를 눈여겨보고 있던 것 같군요!$B$B소용돌이치고 있는 차원문을 통해 거친심장 거점이 보일 겁니다. 안으로 들어가면 야영지로 돌아갈 수 있죠.$B$B일단 이곳에서의 볼일이 끝나면 재빨리 탈출하는 게 좋을 겁니다."
rows["266:1997696067"]="환영하네, 이방인. 도와줄 곳을 찾는다면 제대로 찾아왔네.$B$B죽은 자들이 깨어나 땅 위를 걸어다니고, 또한 배를 타고 바다를 건너 속속들이 도착하는 중이네. 이 협만은 우리에게도 더는 안전하지 않네. 곧 안전한 곳을 찾아 북쪽으로 이동해야 하네."
rows["266:2032772072"]="이 땅은 신선한 피에 물들어 아직도 뜨겁다네. 아, 악마들이 어둠의 문을 부수고 아제로스의 영웅들과 싸웠을 때 내가 이곳에 있어 내 눈으로 볼 수 있었다면! 그 얼마나 장엄한 전투였더란 말인가!$B$B이제, 전투는 반대편에서 더 사납게 몰아친다네!"
rows["266:2112315798"]="그렇지. 이제는 데스윙의 자손인 네파리안이 검은바위 첨탑을 지배하고 렌드는 그 용의 명령을 따르고 있네.$B$B자네가 어떻게든 승천의 전당을 지나갈 수만 있다면 좋을 텐데.$B$B<한숨을 내쉬는 아이트리그>$B$B안타깝게도 검은용군단에 자신의 가치를 입증한 자만이 그곳에 올라갈 수가 있네."
rows["266:254028760"]="언제나 검은 더 날카롭게, 방어구는 더 단단해야 하는 만큼, 솜씨 좋은 마법부여사가 늘 우리 곁에 필요한 법이지요. 탈라단이 바로 그런 자입니다. 그라면 적절한 마법을 부여해 무기와 방어구의 성능을 향상시키는 방법을 알려줄 수 있을 테니, 장인의 정원으로 가서 그를 한번 찾아보십시오."
rows["266:283445219"]="그렇다. 내 말을 경청했구나! 나의 피조물인 이 작은 물고기는 정말 무섭고도 귀여운 녀석이지. 나는 휴식을 취할 때면 운 나쁜 낚시꾼들이 떠오르곤 하지.그들은 어쩌다 운이 나빠 이 작은 물고기를 만나 통째로 잡혀먹혔지. 모두 깜짝 놀랐을 것이다!$B$B<웃음을 터뜨리는 아주어고스>"
rows["266:504169217"]="게임 토큰을 줘서 10개의 반지를 줄게 $B$B반지를 던지면서 듀벤코 암흑성거북이... 그쪽의 듀벤코의 둥지를 보죠?$b$b만약 한번에 승리할 만큼의 링을 내리지 못한다면 다시 시도해 보세요."
rows["266:608387410"]="스톰윈드 웰러의 무기고에 있는 인간 무기 전문가 우 핑과 엑소다르의 교역 지구에 있는 드레나이 무기 전문가 한디르나 아이언포지의 잘나가는 무기 상점에 있는 노움 무기 전문가인 빅시 워블봉크에게서 석궁 사용법에 대해서 배울 수 있답니다."
rows["266:735721874"]="강철은 대지모신의 뼈와 다름없습니다. 뜨거운 강철과 씨름하여 호드에 도움이 될 도구를 만들고 싶으신가 보군요. 좋습니다. 블러드후프 마을에서 북쪽으로 나가는 길을 따라가다 보면 썬더 블러프 꼭대기로 가는 승강기가 있을 겁니다. 그 꼭대기에 있는 썬더 블러프 경비병에게 다시 한번 문의하십시오. 더 자세히 가르쳐 줄 겁니다."
rows["267:1035363175"]="그렇소. 하지만 내가 아는 그곳의 진짜 이름은 바로 엘드레탈라스요. 아주 오래전 나이트 엘프들의 마법을 간직한 보루였던 곳이지.$B$B엘드레탈라스에 대해 들어본 적 있으시오? 지금 내가 처한 상황과 우연히 맞아떨어진다고 할 수도 있겠지만... 나는 우연 같은 걸 믿지 않아서 말이오."
rows["267:1036478548"]="아, 황금 장미 여관 말씀이십니까? 푹신한 침대에 따뜻한 목욕물... 그 여관은 생각만 해도... 흐아암... 그곳으로 가신다니 여유가 있으신 분이로군요. 상업 지구 서쪽 부근에 있습니다. 푹신푹신한 베개에 포근한 이불... 아이고, 졸려라."
rows["267:1075039204"]="리치 왕의 침략에 대항하여 호드와 얼라이언스가 노스렌드로 전진할 때가 왔습니다. 최근 칼림도어와 동부 왕국의 여러 지역이 공격 받고 있다는 소식입니다. 놈들의 손에 파괴되고 있는 우리 땅을 지키기 위해 무기를 들 각오는 되어 있습니까?"
rows["267:1084728988"]="또 이렇게 되다니! 고엘이 살아 있는 돌이 되었습니다! 저 깊은 심원의 영지로 그를 쫓아가야 합니다.$b$b대지 고리회가 테라제인의 영지를 구했으니, 그녀는 당연히 고엘을 구출하는 일에 협력할 거예요. 만약 그러지 않으면 제가 바위 어머니를 가만두지 않을 겁니다!"
rows["267:1166976451"]="출격실로 갈 수만 있으면 좋겠어요. 그 어여쁜 비행기가 정말 딱 한 대만 있으면, 제 손으로 놈리건을 되찾을 수 있어요! 물론 B.E 버랙허스가 눈알이 빠지도록 겁에 질리게 할 수 있고요!$B$B낙하산이 더 필요하세요? 낙하지점 근처에 있는 상자에 몇 개 보관해 뒀어요."
rows["267:1436033226"]="변명은 필요 없네. 난 결과만을 원해!$B$B우리가 여기서 하는 일이 장난 같나? 이번 일을 제대로 하지 못하면 소위 사회 개혁론자라는 자들의 부름을 받게 될 뿐 아니라, 검은날개 소굴에서 진급하기도 어려워질 것이 뻔하단 말이야.$B$B그게 자네가 원하는 건가?"
rows["267:1912210281"]="수년에 걸친 품종 개량과 정성을 쏟은 결과로 탄생한 말들을 자랑스럽게 소개합니다! 타실 말을 천천히 골라 보세요. 말은 평생 친구죠. 오늘 여기서 멋진 녀석으로 한 마리 마련하세요! 당신은 소중한 분이시니까요!"
rows["267:291757881"]="<주위 환경과 동화되면서 머리 부분이 희미해지는 대마법사 바르고스의 환영>$B$B파랄론의 초원을 본 적이 있다면 이곳이 같은 장소라는 걸 믿지 못할 것이오. 몇 달 전만 해도 이 땅은 서부 몰락지대와는 전혀 다른 모습이었소이다.$B$B지금은 모든 게 사라졌지. 대체 어떻게, 왜 그런 것일까?"
rows["267:347569652"]="이것 참, 바보같이 굴지 마십시오! 제가 바로 그 버드 네드렉입니다!$b$b하이잘 산 정상에서부터 가라앉은 사원의 깊은 곳까지 안 돌아다닌 곳이 없지요. 사실은 말입니다, 그곳을 처음으로 가라앉은 사원이라 부른 사람이 바로 접니다!$b$b네, 바로 저라고요. 뭐, 그렇다고 미안해할 것까진 없습니다."
rows["267:698480474"]="순수한 견본이라면 어떤 영향에 의해서도 오염되지 않은 걸 말하는 거요. 가장 단순하고 정상적인 환경에서 이 생물들을 찾아야만 하오.$B$B그것은 곧 문명이 발달하지 않았거나 아제로스 주요 종족들의 영향을 받지 않은 곳을 말하는데, 어딘가... 천연 그대로의 장소라야 하오."
rows["267:855252401"]="잘 들으시오, 친구. 안퀴라즈의 벌레들과 목숨을 건 한판승을 하려면 준비를 해야 하오. 그래서 난 여기에서 철 주괴를 모으고 있소이다. 현재 얼라이언스에서 보유하고 있는 철 주괴는 $2002w개인데, 우리가 계획한 전쟁 물자를 생산하려면 모두 $2003w개가 필요하오."
rows["267:882816869"]="역병, 역병, 역병... 어딜 가나 그 얘기뿐이야. 다양한 맛이 없단 말일세!$b$b그건 그렇고 자네, 애완동물이 있지 않나? 물론 데리고 있겠지. 조그만 녀석들 말일세. 내게 그 애완동물을 위한 특별한 혼합물이 있다네. 그걸 사용하면 녀석들이 끔... 아니, 똘똘하고 힘센 녀석으로 변할 걸세.$b$b한번 실험해 보게!"
rows["268:1158159399"]="마상시합 사무장님께서, 이제 원형경기장이 완성되었으니 저희가 경기 진행을 함께 책임져 줬으면 한다고 말씀하셨습니다. 용사의 자격을 얻은 분들, 그리고 저희에게 능력을 인정받은 분들께서는 이 임무를 도와주셨으면 합니다."
rows["268:1173805419"]="내 오랜 친구인 프롱클이 가젯잔으로 왔어야 하는데, 그 친구와 나머지 빌지워터 승무원들이 탄 배가 도착하지 않았어. 어떤 정신 나간 고블린이 멀리 남쪽에 추락한 비행선 근처에 매달려 있다는 소문을 들었는데... 혹시...?"
rows["268:1722026387"]="대지의 수호자, 그리고 그의 아이들이 언젠가는 죄악에서 구원되리란 희망을 오랫동안 버리지 않았습니다. 하지만, 어느 순간 우리도 깨닫고, 인정할 수밖에 없었지요. 검은용들이 이 세상에 행한 파괴는 어떤 속죄로도 보상할 수 없다는 사실을 말입니다.$B$B그래서 어쩔 수 없이 이 일에 끼어들게 되었습니다."
rows["268:1742873827"]="언더시티에 상급 광부가 하나 있다고 들었네. 그곳에 가려면 일단 마을에서 나가서 남쪽에 있는 로데론의 폐허로 깊숙이 들어가 보게. 거기서 승강기를 타고 언더시티로 내려가. 언더시티 수호병에게 다시 한번 물어보게."
rows["268:233788101"]="영원처럼 느껴진 시간이 지났을 때 그 구원자는 의식을 잃었다. 아무리 그라 해도 견디기 어려운 고문이었다. 다른 이들이 마티스라고 부르던 잔인한 자가 병균이 득실거리는 물을 너덜너덜해진 사루안의 몸에 뿌려 깨우려고 했지만 사루안은 깨어나지 않았다."
rows["268:325891402"]="한때 난 모든 도전자들의 도전을 받아주는 일을 즐기곤 했지만, 그렇게 쉽게 이기는 싸움이 지겨워진지 오래입니다.$B$B이제는 시약 사업을 진척시키고 황혼의 망치단에서 겪은 일을 책으로 쓰면서 하루를 보내고 있답니다."
rows["268:435633941"]="전 너무 멍청해서 이교도 같은 건 못 해요. 비행선에서 떨어진 이래 쭉 그랬죠. 아, 떨어지면서 프로펠러에도 부딪혔어요. 바위 위로 떨어졌고요. 의사들이 금속 바가지로 머리를 고쳐 줬어요. 동그랗고 단단하라고요.$B$B<주먹으로 머리를 탁 치는 일꾼>$B$B그랬더니 어느 날 벼락이 떨어지더라고요."
rows["268:573259774"]="오래된 스팀 탱크를 찾고 있나요?$b$b네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네.$b$b보통은 2개의 토큰이 필요하지만 군 복무로 인해 1개의 토큰을 할인율로 받을 수 있습니다.$b$b우린 다크문 페어에서 봉사해주셔서 감사합니다."
rows["268:910779695"]="몇 년 전, 와이번을 연구하려다 이들에게 고립된 적이 있었습니다. 하지만 한 번 살아나간 후로, 전 이곳으로 돌아와 와이번들을 보호하기로 결심했죠.$B$B대격변이 닥치고 황혼의 망치단은 이 신성한 생명체를 모두 잡아들이거나, 심한 경우엔 죽이기까지 하고 있습니다."
rows["269:1014515451"]="고엘... 그대가 스랄이라 부르는 내 사랑의 영혼이 정령계에 흩어졌습니다.$b$b황혼의 망치단 놈들이 우리 의지를 뒤흔들려는 거예요... 하지만 약해져선 안 됩니다. 우리는 고엘을 포기하지 않을 겁니다.$b$b그는 이 세상을 구하려고 모든 것을 걸었습니다. 우리도 고엘을 위해 그렇게 해야 해요!"
rows["269:1505026330"]="거기 계셨군! 당신 몸이 더 좋아진 것 같은데... 남녘해안 방어를 좀 도와 주시오!$B$B저 악독한 포세이큰 놈들이 총공격을 감행할 것 같소. 바로 할로윈 축제가 돌아오지 않았겠소?! 놈들은 틀림없이 축제를 이용해 쳐들어올 거요. 그렇게 바쁜 일이 없다면 우리를 도와 주시오!"
rows["269:1987661841"]="이 견본들을 보시오! 이게 무슨 뜻일까? 이게 무슨 뜻일 것 같소? 시간이 필요할 거요. 이 모든 정보를 살펴 볼 시간이... 그리고 정보가 더 필요하오. 내가 얻을 수 없는 정보... 젠장! 머리를 써, 라리스! 머리를!$B$B어떻게 할 거야? 어떻게?$B$B해결책은 반드시 있을 거라고!"
rows["269:628449535"]="어디 한 번 보세나. 여기 어디에 적어놓은 게 있을 텐데... 아, 여기 있군! 지금까지 얼라이언스는 필요한 갈래물풀 $2048w개 중 $2047w개, 보라 연꽃은 $2055w개 중 $2053w개, 그리고 아서스의 눈물은 $2058w개 중 $2057w개를 모았네."
rows["269:67062989"]="놈들을 끝장낼 수 있었네!$b$b거의 조각난 얼라이언스 함선을... 스톰윈드로 향하는 항로를 차단할 수 있었단 말이지!$b$b...그런데 갑자기 어디선가 거대한 촉수가 올라와 우리 배를 감싸더니... 정확히 두 동강을 내버렸네!$b$b생존자들은... 우리들은 물에 빠지자마자 나가에게 생포되었고."
rows["26:110112077"]="무엇을 도와드릴까요?"
rows["26:1118810405"]="무슨 일이지? *딸꾹*"
rows["26:1226604364"]="뭐하고 싶은데?"
rows["26:1240847137"]="그런트, 차렷!"
rows["26:1254445823"]="그대를 기다리고 있었습니다. 잘 오셨습니다."
rows["26:134993047"]="여긴 아주 엉망이랍니다."
rows["26:1361243534"]="이방인 친구, 조심하는 게 좋을 겁니다."
rows["26:1424915746"]="이 멍청이들은 대체 어디로 갔을까요?"
rows["26:1477030663"]="그래, 문제가 있어?"
rows["26:1570891501"]="내게 메시지를 주고 있어?"
rows["26:1618049466"]="아... 전 큰 상처를 입었어요..."
rows["26:1650566576"]="<심각한 부상을 입은 타르시스>"
rows["26:1653394133"]="위대한 영웅에게 모두 환호를!"
rows["26:1897198781"]="뭘 도와드릴까?"
rows["26:193599704"]="빛의 가호가 있기를."
rows["26:205421771"]="어떤 트레이너를 찾고 있나요?"
rows["26:220139047"]="악, 속이 너무 안 좋아."
rows["26:22976486"]="이봐, 내게 작전이 있다고!"
rows["26:333565305"]="우리한테 이러는 이유가 뭡니까?"
rows["26:637478548"]="우리는 투어 가이드를 기다리고 있습니다."
rows["26:711112610"]="조심해, 불태워지지 마!"
rows["270:1235706394"]="안녕하세요$B$B저는 갈락 트위클럽입니다.$B$B내가 한 구슬만 들고 있다고?$B$B바람을 느껴서 총을 가까이 두고 있어 언제 쓸지 알 수 없어$B$B그 얘긴 할 때, 어떻게 하는지 가르쳐줄 수 있어요."
rows["270:307374466"]="정신 바짝 차리시오, 제군! 스톰파이크 첩보부의 보고에 의하면 고블린 수석 기술자 하나가 겨울도끼 부족에게 포로로 끌려갔다고 하오. 그런데 서리늑대 놈들이 그를 구출해서 기계를 만들게 해 우리를 치려고 하고 있소! 그런 일이 절대로 일어나서는 안 되지..."
rows["270:464827565"]="모두 노력해 준 덕분에 필요한 철 주괴를 모두 모았소. 이제 다른 곳에 가서 전쟁에 필요한 물자를 수집해 줄 것이 없는지 알아보시오. 나는 좋아하는 카드 게임이나 즐기게 이곳을 조금이라도 일찍 벗어날 수 있는지 알아봐야겠소이다."
rows["270:743301987"]="마법사인 당신은 바로 이곳으로 돌아오는 차원문을 열 수 있도록 선택받은 존재에요. 준비가 됐다면 가르쳐 드리지요.$B$B그리고 제 뒤에 있는 수정을 사용하면 언제라도 달라란 아래에 있는 수정노래 숲의 폐허로 순간이동할 수 있음을 기억해 두세요."
rows["271:1049556280"]="환생의 관은 반드시 엘레멘티움으로 강화해야 합니다. 그런데 그 광석이 나는 곳은 바로 우리 세계의 중심부에 있는 정령계, 한 군데뿐이지요.$B$B그토록 귀한 물건을 구하는 일이라면 저보다 대지창조자가 더 잘 알 테니 꼭 대지창조자를 찾으십시오!"
rows["271:1094895913"]="가능성은 아마 백만 분의 일 정도일 거요! 일생에 한번 볼까 말까 한 그런 가죽이지! 내로라하는 세공인들조차도 무두질 과정에서 수백 번은 실패한 후에 온전한 가죽을 얻을 수 있으니까 말입니다."
rows["271:1110318795"]="언더시티에 박쥐 조련사가 한 명 있다네. 브릴에서 빠져나가는 길을 따라 남쪽으로 가다가 T 자형 교차로가 나오면 서쪽으로 가게. 왼쪽으로 로데론의 폐허가 나올 거야. 그 안으로 들어가서 언더시티로 내려가야 해. 언더시티에 도착하면 수호병에게 더 자세히 물어보도록 하게."
rows["271:1142682299"]="은빛십자군이나 그 연합한 이들과 확고한 동맹을 맺고 성전사 칭호를 얻은 분께만 드리는 특별한 보상이 있지요.$B$B티리온 님께서는 그런 영웅을 찾아내어 알맞게 꾸며 드리는 임무를 제게 주셨답니다."
rows["271:129223583"]="<눈빛이 빛나는 타르시스>$B$B나는 한때 그 지팡이를 손에 넣었지... 키린 토의 경고에도 그것을 독차지했다오. 필멸의 존재여, 그 지팡이가 내 손에 있었단 말이오... 무한한 힘, 원하는 것은 무엇이든 할 수 있는 힘. 금세 다시 뺏기기는 했지만 난 힘의 맛을 보고 말았던 것이오... 그 힘이 가져다주는 거역할 수 없는 힘을 잊지 못해 이 모든 사태가 벌어진 것이오."
rows["271:1312502591"]="이거라면 어떤 배보다도 더 빨리 언더시티에 갈 수 있답니다. 경치는 또 숨이 막힐 정도로 아름답지요. 숨 얘기가 나와서 말인데, 비행선에서는 금연이에요. 화염 마법도 금지고... 사고라도 나면 헬륨 폭탄이 터지는 것에 비길 바가 아니니까요."
rows["271:1444627730"]="내가 자초한 상처지. 리치 왕의 손아귀에 잡힌 내가 끔찍스러운 일들을 저질렀던 세상을 감히 쳐다볼 수 없었다.$B$B구원을 받고자 하는 첫걸음인 셈이다. 만약 내 죄가 용서받을 수 없을 만큼 크다면, 남은 일생을 그들에게 속죄하며 살아가려고 한다."
rows["271:1721445914"]="로나는 정말 용감한 모험가가 그녀의 가족의 과목 정원 근처에 많은 말을 구해줬다고 말했습니다.\013\010\013\010바다를 건너간 사람들을 돌볼 수 있도록 제안했어요.\013\010\013\010좋은 길니안  ⁇ 에 관심이 있었나요?"
rows["271:1856235299"]="가을 축제는 최고의 먹을 거리와 마실 거리를 모두 즐길 기회랍니다. 뜬금없는 소리 아니라니까요! 기분을 상쾌하게 만드는 수제 맥주와 소시지, 프렛첼이 다양하게 갖춰져 있으니 그저 슬쩍 한번 둘러라도 보시기 바랍니다. 이보다 더 좋은 건 없을 걸요. 게다가 작은 동전 하나면 다 됩니다요!"
rows["271:1965051516"]="여보게! 나는 다른 누구보다도 산양을 잘 다루지만, 그렇다고 양조장이를 돕고 가을 축제에 협력하는 걸 등한시하지는 않는다고. 자네도 원한다면 참여할 수 있어.$b$b아직 할 말이 안 끝났으니 기다리게!$b$b가을 축제 일을 돕는다는 건 말이지, 세상에서 제일 빠른 산양을 타 볼 수 있다는 걸세!"
rows["271:2011033424"]="콩이나 향수를 입으면 누가 사랑에 빠진지 알 수 있을거야.$B$B하지만 기억하세요, 누군가에게 사랑의 표적을 주기 위해서는, 바로 냄새가 있어야 합니다. 남자들은 향기의 향을 좋아하지만, 여성들은 콩을 선호합니다."
rows["271:678207961"]="우리는 이 산맥의 균형을 회복할 수 있는지 확인하고자 이곳 루안 숲으로 왔소.$B$B그런데 아라코아와 고룡교단의 방해 때문에 일이 어렵게 됐소이다.$B$B그래도 당신과 사미아처럼 우리를 도와주려는 친구들이 있어서 얼마나 다행인지 모른다오."
rows["271:788393556"]="재니스의 영혼이 당신을 바라봅니다. 그녀의 눈에는 이전과는 달리 충만한 자각과 이해가 담긴 듯한 느낌입니다.$B$B\"마치 내 영혼에서 무거운 짐이 벗겨진 듯하군요. 저는 곧 영원한 안식을 취하게 될 거예요. 이제는 알아요. 그때를 침착하게 기다릴 겁니다.$B$B고마워요, 낯선 분이여.\""
rows["271:998587431"]="가장 강력한 말리고스 정예 요원들이 저 위의 고리를 보호하고 있습니다. 그대 혼자 힘으로는 그들을 처리할 수 없지요. 그대에게 우리 용군단의 비룡을 부를 권한을 드리겠습니다. 비룡의 등에 올라타면 이곳 마력의 눈을 날아다니며 용의 강력한 마법을 사용할 수 있을 것입니다."
rows["272:1254985625"]="이봐 거기, 잠깐만 있어봐. 보니까 지금 탄 나는 탈것은 자네 전용이 아니잖아.$B$B계속 이 주변을 돌아다닐 수 없다면 다른 고블린들에게 그리 쓸모있는 존재는 못 될 텐데 말이야. 다른 친구들이 자네 같은 사람한테 내가 타던 나는 탈것을 빌려주라고 돈을 좀 내놨는데 말이야. 자네는 돈 한 푼 안 내도 괜찮고 말이지.$B$B어때, 관심 있어?"
rows["272:1836782551"]="모든 것에는 영혼이 있소. 영혼의 소리에 귀 기울이는 법을 배우면 사물의 모습을 당신이 원하는 대로 바꿀 수 있지. 대장장이 일이란 금속을 쳐서 당신이 원하는 모양을 억지로 만들어 내는 게 아니오. 강철 속에 살아 숨 쉬는 영혼의 소리에 귀를 기울여 그 영혼이 취하려는 모습으로 인도하는 것이지..."
rows["273:1014075237"]="아, 은행 일을 보시려면, 저 높은 썬더 블러프까지 가셔야 합니다. 북쪽으로 길을 따라 블러드후프 마을에서 빠져나간 다음 썬더 블러프 밑에 있는 승강기를 타고 꼭대기로 가십시오. 썬더 블러프 경비병에게 다시 물어보면 더 자세히 길을 가르쳐 줄 겁니다."
rows["273:1877679668"]="그게요, 여기서 전투가 벌어지기 전에는 우린 그냥 벌목기를 고쳐서 이 일대에서 벌목 작업을 하는 데 썼지요.$b$b하지만 요즘에는 호드를 상대하는 데 벌목기를 사용해요. 전투 병기로 꽤 쓸만하다는 사실이 입증됐거든요. 열쇠가 있는데도 벌목기를 안 쓴다면 바보 같은 짓이죠!"
rows["273:19146097"]="재니스의 영혼이 당신을 바라봅니다. 그녀의 눈에는 이전과는 달리 충만한 자각과 이해가 담긴 듯한 느낌입니다.$B$B\"마치 내 영혼에서 무거운 짐이 벗겨진 듯하군요. 저는 곧 영원한 안식을 취하게 될 거예요. 이제는 알아요. 그때를 침착하게 기다릴 겁니다.$B$B고마워요, 낯선 분이여.\""
rows["273:1926896249"]="아르거스의 대리인에서 이 맥아리가 우리 도시에서 가장 열성적인 일원이었지.$B$B귀중한 광물로 도로를 깔고, 칠흑 같은 어둠 속에서도 강물이 빛났다고 한다면 믿겠소?$B$B아, 그 시절이 다시 왔으면 좋겠군... 얼마나 오래되었을까? 천 년? 만 년?"
rows["273:396595096"]="이봐요, 당신 알아보겠어요! 제가 여기 왔으니 감사해야 할 거예요. 그 순간이동 사고가 제 일생 중 가장 멋진 일이었어요. $B$B북풍의 땅으로 다시 돌아간다면 제 고집쟁이 바른 생활 짝꿍에게 나는 더 높은 세상으로 올라왔다고 전해주세요!"
rows["274:1143568531"]="최근 회의에 대해 알지 못해? 여배우의 요구에 대해? 개혁에 대한 그의 열정을? 그는 단 한 명만이 아니라, 그는 가장 큰 목소리입니다.$b$b교회에서 그에게 '좋은 밤'을 부탁한다면, 아모로드는 낮이 아닌지 확인하기 위해 창문 밖으로 바라보는 사람이죠."
rows["274:1230725733"]="여기 온 지 얼마 안 되는 분이시군요... 그렇다면, 우리 전통에 대해서도 잘 모르시겠군요? 달숲에서 굉장한 축제가 열리고 있어요. 해마다 우리의 선조를 기리는 시기가 바로 지금입니다. 당신도 초대를 받았어요! 축제를 함께 즐기고 싶다면 아무 대도시로나 가십시오!"
rows["274:1431908209"]="내가 죽었다고 생각해서 나를 꽉 차고 달릴 줄 생각하는 사람들을 좋아하지 않나? 그래요? 잘해요."
rows["274:168711473"]="이봐요, 당신 알아보겠어요! 제가 여기 왔으니 감사해야 할 거예요. 그 순간이동 사고가 제 일생 중 가장 멋진 일이었어요. $B$B북풍의 땅으로 다시 돌아간다면 제 고집쟁이 바른 생활 짝꿍에게 나는 더 높은 세상으로 올라왔다고 전해주세요!"
rows["274:331905039"]="여기 내 혈기 왕성한 친구인 빅시 워블봉크가 당신에게 석궁 사용법에 대해서 알려줄 것일세. 자네가 다른 무기 전문가를 찾는다면 다르나서스의 전사의 정원에 있는 일예니아 문파이어를 만나 보거나, 엑소다르의 교역 지구에 있는 드레나이 무기 전문가인 한디르를 만나 보게나."
rows["274:480442797"]="벽을 따라 설치된 대포 두 문 때문에 진격이 늦어집니다. 저 대포가 없다면 우리 군대는 아무런 손실 없이 그들의 요새로 돌격할 수 있겠지요.$B$B대포를 파괴하거나 포탄이 떨어질 때까지 기다리거나 해야 합니다. 안셀름님께서 결정하시겠지만요."
rows["274:654472100"]="다크월 페어에는 다양한 놀라운 볼거리가 있습니다. 우리는 예고꾼, 콘서트, 낚시 공모전, 그리고 많은 게임을 가지고 있습니다.$b$b우리는 끊임없이 다양한 새로운 볼거리로 페어를 확장하고 있습니다!$b$b더 많은 정보를 얻고 싶은 관광지가 있나요?"
rows["274:694442919"]="네, 네... 내 연구기지를 찾아 주셔서 감사합니다.$B$B둘러보시니 어떠신가요? 여기서 우리가 정말 멋진 일을 해낸 거 같지 않나요?$B$B그건 그렇고 실바나르의 저 꽉 막힌 엘프들을 없애 주면 정말 기쁘겠네요.$B$B여기 일을 좀 도와주십시오. 실험이나 그 밖에 도움이 필요한 일이 아주 많거든요."
rows["274:806400432"]="안녕하세요. 애석하게도 마본씨는 여기 안 계세요. 앞으로 한동안은 돌아오지 않을 거예요. 사실 좀 걱정되기는 해요...$B$B빨리 오셨으면 좋겠어요. 마본씨 앞으로 웬 커다란 궤짝이 하나 왔는데 도저히 제 힘으로는 안으로 가져올 수가 없어서 밖에 문 옆에다 뒀답니다."
rows["275:1012479288"]="정령계에 대전쟁이 벌어지던 시기에 불의 군주 라그나로스가 저의 주인이자 바람의 왕자이신 썬더란을 소멸시키려 했습니다.$B$B<분노로 얼굴이 일그러지며 고개를 떨구는 데미트리안>$B$B놈의 이름을 입 밖에도 내지 마십시오. 화가 치밀어 당신의 이빨로 이 황폐한 야영지를 장식해버릴지도 모르니까 말입니다. 조용히 듣기만 하십시오."
rows["275:1146452059"]="아주 오래전, 찬탈자들이 훗날 창세기라 부르던 시대에, 내 주인님과 그 형제들은 이 세상을 지배했습니다. 그들이 바로 이 세상을 창조한 고대 신들이셨지요.$B$B하지만, 결국 고대 신들은 창조주라고 자칭하던 놈들에 의해 밀려나고 말았답니다."
rows["275:1231308062"]="나는... 우리에게는 힘이 없다. 일리단은 줄루헤드를 찾아 용아귀 오크들의 지도자로 보냈다. 이 오크는 알렉스트라자를 사로잡아 감금했던 인물이다. 그런 힘을 가진 자에게 우리가 어떻게 맞서겠나? 위상을 사로잡았던 자에게!$B$B그리고 더더욱 그럴 수 없었던 이유는 놈이 그녀를 데려갔기 때문이다."
rows["275:1622903291"]="칼날 산맥은 엄청난 기회의 땅일세. 그런 기회를 이용하는 데 자기들이 다른 이들보다 우위에 있다고 생각하는 자들이 있다니 정말 유감스러워.$B$B세나리온 원정대는 얼마나 잘났기에 우리보고 이래라저래라 말이 많은 거지?"
rows["275:1737809700"]="천둥이는 사냥꾼 어튜멘의 전용 말입니다. 제가 본 말 중에 가장 빠르고, 강하며, 교활합니다. 심지어 말 주인은 그보다 훨씬 성미가 고약하답니다! 모두 천둥이의 발굽에 차이거나 어튜멘에게 얻어맞지 않기 위해 그들과 거리를 둔답니다."
rows["275:1970648926"]="그 용은 귀족의 가면 뒤에 숨어 있지만 이 서판으로 그 정체가 드러나게 될 거요... 내가 본 것이 진실이라면 난 이 전투에서 살아남지 못할 거요, 친구. 내가 시작한 일을 끝낼 자는 바로 당신이오. 당신 부대와 당신은 준비가 됐소? 당신이 준비가 되면 시작하도록 하겠소."
rows["275:225035528"]="스컬지는 하늘을 떠다니는 죽음의 요새로부터 신속한 연락과 각종 지원을 받으면서 공격 지역에 소규모의 집결지를 건설하고 있습니다. 단언컨대, 요새 아래 모인 지상 병력을 해치우면 스컬지를 몰아낼 수 있을 것입니다."
rows["275:729553313"]="당신은 배우는 속도가 빠르군. 나쁜 건 아니지. 다만 작업은 제대로 마무리해야 한다는 것에만 주의하시오. 자, 이제 당신을 스날에게 보내야 하겠소이다. 그에게 가르침을 얻되 화가 나서 내뱉는 말은 귀담아 듣지 마시오. 사루의 딸들이 자기를 비웃을 때마다 늘 그러니까."
rows["276:1390646942"]="로켓발사단장인 퓨즐라지가 X-52 황천 로켓을 건설하고자 지원자를 모집하고 있을 때 난 보안 부서에 이력서를 냈지.$B$B유감스럽게도 남은 자리는 선임기술자밖에 없었다네. 그나마 여기 자이롤이 있어서 어깨너머로 배울 기회가 있었지."
rows["276:179637631"]="어둠사냥꾼인 덴자이가 이 기지를 건설할 건축가와 병사들과 함께 절 여기로 파견했소. 우리는 가까스로 건설을 마쳤는데 그는 벌써 보고서를 요청하고 있소!$B$B물건이 필요하다면 약간은 제공할 수 있지만 아직도 첫 번째 보급품이 도착하기만을 기다리는 상황이오."
rows["276:1815568005"]="알렉시가 하는 말일랑은 듣지 마십시오. 그자는 역병이 닥쳐왔을 때 머무른 멍청이였습니다. 지금의 그를 보십시오. 그자는 이곳의 다른 누더기 녀석들보다 나을 게 없단 말입니다.$B$B속 태우지 마십시오. 우린 바로브 가문의 생존한 마지막 후손들을 위해 스칼로맨스와 그 주위 지역을 다시 차지할 겁니다. 정당한 후계자들을 위해 말입니다."
rows["276:1843076852"]="아주 난장판에 발을 들였지 뭐요. 안 그래도 얼음왕관의 아군과 합류할 때가 지났는데, 스컬지와 드라카리 사이에 옴짝달싹 못하게 끼여 이 난리통에 휘말리다니.$B$B대영주님께 여기 온 건 잘못된 판단이었다고 말씀드렸다오.$B$B가서 뭐 도와줄 일 없나 알아보시오."
rows["276:2052694539"]="눈망루 마을의 우리 형 잽의 도움을 받아 이곳 52번 구역에 차원 내파기를 만들었네. 고블린 기계공학으로 순간이동이 가능한데 누가 로켓을 사용하겠어?! 자네, 내파기 신호장치를 손수 제작하는 방법을 배울 수 있을 만큼 고블린 기계공학에 능통한가?"
rows["276:340995434"]="명예의 요새를 지키는 이들은 여기 이 끔찍한 땅에 모두의 피와 청춘을 바쳤습니다... 하지만 여전히 드높은 기개를 잃지 않았습니다!$B$B이제 당신과 당신 동료가 도와준다면 우리가 전세의 흐름을 바꿀 수 있을 겁니다. 당신은 우리에게 언젠가 고향으로 돌아갈 수 있다는 희망을 주셨습니다."
rows["277:1094170386"]="이제 전쟁에서 승리할 계획을 세워 볼까!$B$B동쪽 흉터의 땅에서 얼라이언스는 해안의 요새들을 육로로 연결하려는 심산이오. 이곳, 불모의 땅 가운데에 요새를 지으려 하고 있지. 바로 우리 불모의 땅에 말이오.$B$B어림없는 일이지."
rows["277:1442808325"]="이봐! 나는 빌지워터 세발차 영업사원 칼 워서톤이야. 자네 맘에 쏙 드는 세발차를 한번 골라 보라고!$B$B돌풍을 일으키며 달리는 세발차... 목숨을 걸어야 할 만큼 위험하게 빠른 세발차... 자네가 자랑스러워할 수 있는 세발차를 말이야! 맘에 드는 세발차를 찾았으면 거래를 시작해보자고."
rows["277:1503301240"]="눈망루 마을의 우리 형 잽의 도움을 받아 이곳 52번 구역에 차원 내파기를 만들었네. 고블린 기계공학으로 순간이동이 가능한데 누가 로켓을 사용하겠어?! 자네, 내파기 신호장치를 손수 제작하는 방법을 배울 수 있을 만큼 고블린 기계공학에 능통한가?"
rows["277:1586527871"]="대지의 수호자는 여기서 몸을 추스르면서 이곳의 고요함, 이곳의 평화를 탐탁지 않아 했다. 얼마 지나지 않아 놈은 바위용들이 우리에게 맞서게 만들었지.$B$B이제 데스윙이 가버렸으니 바위용이 우리와 싸울 이유도 없어졌다. 그러니 그들에게 우리의 힘을 보여주고, 바위 어머니의 품으로 돌아오게 할 수 있을 것이다."
rows["277:1768626585"]="<조용히 웃음 짓는 대모 게야>$B$B난 늙었다네. 갈 때가 됐지. 내가 죽으면 내 영혼은 영혼의 세계로 갈 걸세. 그곳에서 우리 선조와 함께 머무르면서 우리 종족을 보살필 것이야.$B$B가라드가 살아 있었을 때 대모 카슈르의 의무는 내가 지금 맡고 있는 일과 똑같았네."
rows["277:2132361557"]="이곳 여명의 설원에 사는 겨울눈 펄볼그는 한때 우리의 동맹이었지... 하지만 어느 날, 모든 게 변해 버렸소.$B$B그들은 대족장의 이상한 명령에 따라 우리 일족을 포함해 그들이 마주치는 모든 자들을 공격하기 시작한 거요. 이제는 자신들을 고립시키고 있소이다."
rows["277:356659983"]="우릴 이렇게나 도와주시다니 정말 대단하군. 당신이 아니었다면 우린 벌써 악마들에게 당했거나 검은용군단에 의해 바삭하게 익혀졌을 거라고 감히 말하고 싶소!$B$B이건 다른 얘긴데 우리 아이들을 싸게 팔 의향이 있다고 내가 말하지 않았소? 관심 없단 말이오?"
rows["278:1174225782"]="흠, 그래? 요새 젊은 언데드들 사이에는 검은색, 회색, 그리고 어두운 자주색이 유행하고 있으니 놓치지 않도록 하게. 보웬 브리스부아즈가 자네를 도와 줄 거야. 마을 남서쪽에 있는 버려진 장원으로 가보게. 다리를 건너야 할 거야."
rows["278:1318810900"]="흐음, 썬더 블러프로 가셔야 할 것 같군요. 블러드후프 마을에서 빠져나가는 길을 따라 북쪽으로 가십시오. 그러면 썬더 블러프 밑에 도착하게 되는데, 승강기를 타고 꼭대기로 올라가서 썬더 블러프 경비병들 중 아무에게나 물어보면 길을 더 자세히 가르쳐 줄 겁니다."
rows["278:1990557557"]="리테가 그늘 쉼터 여관의 화재와 무슨 관련이 있다면 그를 찾아서 심문해 봐야 할 거요.$B$B내가 오그론을 보내 그를 추적하도록 했는데 말이야. 그는 남동쪽으로 습지대를 가로지르는 주 도로쪽으로 갔으니 오그론과 만나 리테를 찾아보시오."
rows["278:516398053"]="막는다고? 그건 안 될걸. 속도를 늦추는 거야 할 수 있을지도 모르겠지만 말이야.$B$B스컬지들의 훈련과 교육의 주요 거점은 스칼로맨스라네. 바로 그곳으로부터 이교도들이 퍼져 나와 결국 우리 사회 속에 침투하게 되지.$B$B그렇기에 녀석들의 근원을 쳐야만 해. 저주받은 자들의 교단의 심장부를 말이지!"
rows["278:623128856"]="마을에는 그런 곳이 없습니다. 썬더 블러프의 높은 고도가 있습니다. 블러드하프 마을에서 북쪽으로 올라갈 때까지 블러프의 밑으로 오십시오. 엘리베이터를 타고 꼭대기에 올라가서 블러프워치와 이야기하십시오. 여러분의 조상들이 여러분을 지켜 주시기를 바랍니다."
rows["278:661322226"]="그래... 자네가 약초채집 기술을 익히면 좀 더 큰 보람을 얻을 수 있을 걸세. 조금 특별한 씨앗을 기르고 재배해야 해. 이 늘푸른 주머니만 있으면 아무리 초보자라도 뭔가 길러낼 수 있긴 하지만 약초학에 소질이 좀 있다면 더욱 풍성한 수확을 거둘 수 있을 걸세."
rows["279:138306958"]="전 J.D.라고 해요. 어떻게 이곳에 오게 됐는가는 자세히 말 못하겠지만 이제 이 야영지가 제 집이라는 것만은 확실해요!$B$B전 분화구 주변에 널려 있는 신기한 수정들을 조사하면서 지낸답니다. 이곳으로 오는 길에 분명 뭔가를 본 듯하신데요. 대체 뭘 보신 건가요?"
rows["279:1469891725"]="이 세계의 동물들은 숭고한 죽음으로 우리에게 생명을 주고, 보호해주기도 합니다. 가슴 속으로 그들의 희생에 경의를 표할 수 있다면, 그대는 무두질을 배울 자격이 있는 겁니다. 더 자세한 것을 알고 싶으시면 다르나서스 북부, 장인의 정원에 있는 엘라드리엘과 얘기를 나눠 보십시오."
rows["279:1531042036"]="밖에서 사냥을 즐기는 편이라면 악령숲에 사는 나무정령과 운고로 분화구의 덩굴손에게서 야생 잎사귀를 찾는 것이 좋습니다.$B$B좀 더 위험을 즐기는 편이라면 혈투의 전장으로 가십시오. 그곳 동쪽과 서쪽 전당은 거의 무한한 야생 잎사귀의 보고이니까요."
rows["279:1617569625"]="이 세계의 동물들은 숭고한 죽음으로 우리에게 생명을 주고, 보호해주기도 합니다. 가슴 속으로 그들의 희생에 경의를 표할 수 있다면, 그대는 무두질을 배울 자격이 있는 겁니다. 더 자세한 것을 알고 싶으시면 다르나서스 북부, 장인의 정원에 있는 엘라드리엘과 얘기를 나눠 보십시오."
rows["279:1933978858"]="그건 저희의 방식이 아닌데다 가능하지도 않습니다. 네파리안은 위상들만큼이나 오래된 고대 보호막의 보호를 받고 있지요. 그것 때문에 제가 이 요새의 내부 성소에 들어가지 못하는 것입니다. 암흑 마법 때문에 임명되지 않은용군단은 들어갈 수가 없어요. 하지만..."
rows["279:306130380"]="<앞에 서 있는 트롤은 방금 새로 생긴 상처로 입이 퉁퉁 부은 것을 포함해 머리부터 발끝까지 상처와 깊게 베인 자국으로 덮여 있습니다.>$B$B히유우!$B$B당신도 알돠시피 트롤은 앱터를 타쥐요. 야생 앱터를 잡아와 훈련시퀴는 게 어렵지만 말입니다! 그래서 줴가 여기 온 겁니다, 저는 앱터 덫사냥꾼이거둔요."
rows["279:422083399"]="나아루? 신화들은 우방적인 환상에 얽혀 있습니다. 저는 이 이야기를 알고 있지만, 사실이라면도, 그 이야기는 우리를 진실에 더 가까이 데려가줄 것이라고 믿지 않습니다. 빛 그 누구도 자신을 증명할 필요가 없습니다."
rows["279:593933057"]="<당신의 멱살을 힘겹게 잡는 타르시스. 비록 죽음을 눈앞에 두고 있었지만 그의 눈에서 상상조차 할 수 없는 힘이 느껴집니다.>$B$B그렇게 생각하시오? 그렇다면, 잘 들으시오. 지금부터 더욱 말도 안 되는 소리가 이어질 테니... 이 요새에는 내가 일생을 바쳐 이룩한 업적이 있소. 바로 부서진 지팡이 조각들의 정확한 위치 말이오."
rows["279:979057621"]="휴, 저 녀석은 아직 너무 멍청해서 수정의 영향이 충분치 않다고 말하고 다닌다오. 하지만 녀석도 그 영약을 가져다준 당신에게 고마워하고 있소이다.$B$B이제, 아홉 녀석만 남았군... 아윽!$B$B<한숨을 쉬는 토르커스의 양쪽 머리>$B$B우리 수중에 있는 영약을 원하는 거요? 좋아, 싸게 팔도록 하지."
rows["27:1081270723"]="정말 괜찮은 생각일까요?"
rows["27:1088921672"]="둔왈트다운 전투였습니다. 당신이 맘에 들어요."
rows["27:1134557494"]="전 몰라요.$B$B때리지 마세요!"
rows["27:1220426356"]="총이 좋습니까, 아니면 활이 더 마음에 드십니까?"
rows["27:1299154318"]="록타르! 도움이 필요하다!"
rows["27:1580681710"]="불 축제를 즐기고 있습니까?"
rows["27:1607821498"]="안녕하세요? 전 구버 블럼프라고 해요."
rows["27:1840447190"]="안녕하세요? 만나서 정말 반가워요!"
rows["27:2062812458"]="내게 들려줄 이야기가 있는가?"
rows["27:330316650"]="옷 멋진데요!"
rows["27:392938215"]="날 구하러 온 거야?"
rows["27:42282752"]="가우르그글! 블르글브르글 그르글!"
rows["27:548784899"]="붉은송곳니 일족은 승리할 것이다."
rows["27:567365104"]="어느 전장?"
rows["27:569753636"]="으으... 속이 거북한데요..."
rows["27:622360428"]="존. 여보, 어디 있어요?"
rows["27:691642012"]="그렇다면 임무를 받아들이겠다! 당연하지!"
rows["27:855222272"]="다시 만나 반갑군요."
rows["27:991481614"]="어서, 부끄러워하지 마$b말 좀 해"
rows["280:1604267312"]="이 잔다이스 바로브의 일지는 언데드에 대한 욕설과 분노로 가득합니다. 책 뒷부분까지 읽어보니 지옥매듭 가방을 만드는 도안이 나와 있습니다. 바로 흑마법사가 영혼의 조각을 보관하는 가방입니다. 당신은 이미 이 가방을 만드는 방법을 알고 있습니다."
rows["280:1667080393"]="카엘타스가 마을을 평평하게 만들었을 때, 저는 아무것도 할 수 없었습니다. 그의 마법은 이미 저를 탑에 봉쇄했고,$B$B그리고 여전히 그들의 목소리는 멀리서 부르고, 밤중에 날 깨우치고 있습니다. "
rows["280:1958840621"]="우리 원정대는 차원문을 안전하게 지나서 스랄마라 불리는 새로운 기지를 건설했네. 보다시피 불타는 군단은 우리의 방어선을 뚫고 우리를 우리 형제들로부터 격리시키려 하고 있네. 악마들은 분명 어둠의 문을 다시 차지하고 아제로스로부터 오는 지원군을 차단하려는 것일 게야."
rows["280:197829000"]="돈이 문제가 아니죠! 사실 상당한 액수의 기부를 받고 있거든요. 때론 정말 어마어마한 거액을 주는 분도 있지요. 저희 유랑단은 전쟁으로 피폐해진 이 세계에 밝은 웃음을 선사하고자 모였어요. 이러한 선의의 목적이 저희의 재능과 노력에 원동력이 되고 있으니 걱정은 마세요. 걱정은 우리가 할게요. 어떻게 하면 여러분을 최고로 즐겁게 해 드릴 수 있을까... 바로 이런 걱정요!"
rows["280:229249191"]="이 숙소는 지역 상품으로 인수된 상인들이 가득 차 있었지만 스카데일드의 도로는 더 이상 안전하지 않습니다.$b$b이제 안드라스테로 향하는 용병만 수용하고 있습니다. 안타깝게도... 하지만 요새의 불행은 우리의 구원이 되었습니다."
rows["280:357887916"]="아! 다릴 리크너선은 정말 탁월한 요리 솜씨를 자랑하지요! 칠리 요리를 얼마나 화끈하게 잘도 만드는지, 쇳덩이를 담금질하는 데 써도 될 정도랍니다! 아마 그 특제 칠리 조리법은 비밀로 하려 할 테지만 괜찮은 요리법을 가르쳐 주긴 할 겁니다. 대용광로의 북동부에 있는 놋쇠단지 제과점에 가 보십시오."
rows["280:496734278"]="아이언포지에서 드워프들이 채광 전문가랍시고 한 명을 보내서는 우리한테 채광이 이렇니 저렇니 하는데, 곡괭이 하나 들고 바위나 때리는 게 뭐 그리 어려운 일이라고 그러는지... 뭐, 그래도 여기 와 있는 이상 그를 찾아가 보는 게 좋겠지요. 겔만이라고 하는데, 드워프 지구에 살고 있습니다."
rows["281:1165344888"]="오,  ⁇ 글스톤의 아름다운 열대 우림으로 여행을 가세요. 네, 당신도 크리스탈 푸른 물에서 햇볕을  ⁇ 을 수 있을 겁니다. 제가 이 불타는 열 속에서 서서, 제 형제 프레즈 외에는 아무 것도 보지 않고 하루 종일 여행을 즐기세요."
rows["281:1469180818"]="전 하루 종일 제펠린의 부품들을 찾아다니는데 프레즈가 시간당 임금을 내는데도 괜찮지 않아요. 하지만 그 때문에 여기 있지 않나요?"
rows["281:1473834573"]="여기 현관문을 통해 손님께서는 세 방향 중 한 곳으로 탑에 들어갈 수 있습니다. 제 뒤쪽에 있는 계단을 따라가면 대무도회장이 나오는데 현재 손님들을 접대하고 있습니다. 아마 마구간이 있다는 걸 냄새로 아실 수 있을 것이며, 하인 숙소로 들어가는 입구는 이곳 현관문 옆에 있습니다."
rows["281:1972882045"]="어서 오십시오.전 줄다자르의 상인 린워쇼라고 합니다. 제 고향 남쪽 바다에서 여러 가지 이국적인 물건들을 가지고 왔지요.$B$B당신이 우리 부족에게 가치 있는 존재라는 걸 충분히 입증해 보인다면 나와 교환을 할 수 있을 겁니다. 그리고 잔달라 명예 징표를 손에 넣으면 우리 거래 얘기는 한결 쉬워질 거고요."
rows["281:290907942"]="공포마를 소환하려면 먼저 대소환진을 만들어야 합니다. 소로스로 가는 차원문을 그 안에서만 열 수 있기 때문이지요.$B$B대소환진을 만들려면 세 가지 강력한 도구가 필요합니다. 데스무라의 종, 어둠의 물레, 심판의 양초가 바로 그것입니다."
rows["281:410718245"]="그래, 회의를 해야지. 본론부터 말하겠어.$B$B감독관, 자네가 담당하는 루안 숲의 목재와 가축 수집 속도가 크게 떨어졌네.$B$B우리에겐 그 자원이 꼭 필요하다는 걸 알고 있겠지? 그런데 자넨 세나리온 원정대의 드루이드들이 우리 물자 수집을 방해하도록 놔두고 있어!"
rows["281:8736271"]="이 동굴은 저주받았습니다. 끔찍한 기운으로 가득 차 있어요.$B$B황혼의 망치단은 산꼭대기에 기지를 세우면서 자신들에게 쓸모없는 이들을 이 동굴에 몰아넣었지요. 한때 이곳에 거했던 검은 비룡의 먹이로 말입니다.$B$B그들은 절대로 동굴을 나오지 않습니다. 심지어 영혼 상태로도요."
rows["281:922108702"]="수년 전, 어느 멀록들의 문제를 도우려다 비참하게 목숨을 잃고 말았어요. 하지만 저는 여신께로 가는 대신에 남아서 제 가족과 친구들을 지켜보는 걸로 만족했지요.$B$B지금은 제 가족과 친구들도 모두 없거나 죽었고 제가 남은 이유라곤 하나뿐입니다.$B$B바로 복수에요."
rows["282:1216992193"]="우리가 마지막 힘을 다해 모은 전쟁 물자가 앞으로 $2113w일 내에 실리더스로 옮겨질 것 같아요. 물자 수송이 완료되면 누군가 안퀴라즈 밖에 있는 스카라베 제단에서 징을 울려 문을 열어야 해요. 바로 그때 우리 붕대가 필요할 때가 시작되는 거죠."
rows["282:1272593401"]="저 벽만 무너지면 스톰윈드 항구로 통하는 또 다른 길을 닦을 겁니다... 그런데 이 정신 나간 드워프가 마법사 지구 전체를 날릴 만한 폭약을 가져왔다고요!$B$B알렉스턴 씨가 무슨 생각으로 이 여자를 고용한 건지 도저히 모르겠습니다... 입버릇도 고약한 데다가 심술궂고, 게다가 완전히 황소고집이라니까요!"
rows["282:1598681619"]="여기 이 짐노새들은 하루에 두 번 나간다네. 그런데, 스컬지가 길을 비켜주지 않아 디디어와 노새들이 최전선에 보급품을 수송하지 못하면 난 끝장일세. 이렇게 환장할 노릇은 처음이군. 보급품 수송을 안전하게 지켜줄 영웅이 있다면 얼마나 좋겠나..."
rows["282:1754980417"]="상자 마을 안에 들어갈 때, 아즈샤라의 어딘가로 보내진다고 들었어요. 여기가 아즈샤라인가요?$B$B궁금한 게 있는데요. 상자 마을은 누가 준비했죠? 먹고 살 음식을 넉넉하게 공급하나요?! 달랑 닭고기처리기 하나만 있는데요!$B$B\"초소형\" 기계닭이 어떻게 만들어지는지 모두 다 안단 말이에요."
rows["282:605891639"]="이 신전에 대한 기억이 짙은 안개처럼 내 마음을 덮고 있지만 기억을 되짚어 조리 있는 이야기를 만들지는 못하겠습니다. 이곳이 다시 내게 무언가의 의미가 되었습니다. 기억을 되찾을 때까지는 내 일부가 없는 것 같은 느낌이 들 겁니다.$B$B아마 드레나이가 잃어버린 제 기억을 되찾도록 도와줄 수 있지 않을까요?"
rows["283:514107892"]="마법은 미묘한 악동보다 더 많은데... 하지만 이미 알고 있는 사람과 얘기하고 있어요.$B$B네가 내게 와서 배울 거야 내가 말하는 대로만 하면 네가 할 거야"
rows["283:857525415"]="어서 오게, 젊은 친구... 썬더 블러프에 온 걸 환영하네. 이곳에서는 세상 짐을 벗어버리고 편안하게 쉴 수 있을 걸세. 호드의 일원이라면 누구나 환영이지.$B$B이 성스러운 곳에서는 현재와 과거의 영혼들이 다시 살아난다네. 그들에게 예를 갖추게. 그리고 자기 자신에게 예를 갖추는 것도 잊지 말게나."
rows["284:1126358452"]="썬더란께서는 불의 군주가 다가오는 것을 전혀 모르고 계셨기 때문에 손쓸 겨를도 없이 라그나로스의 전설적인 망치인 설퍼라스에 의해 무자비하게 당하고 말았습니다. 썬더란께서는 참패를 당해 쓰러지셨지요.$B$B불의 군주가 탐욕스럽게 주인님의 정기를 빨아들였지만 그분을 완전히 소멸시키지는 못했습니다."
rows["284:1216655219"]="순례자의 보너스는 자신의 행운을 생각해보고 주변 사람들과 공유하는 시간입니다.$B$B내 멀고어 그리고 호드우리는 많은 열매를 함께 즐길 수 있는 집과 친구를 찾았습니다.$B$B우리의 동맹국들 모두가 함께 축하하고 축하할 수 있기를 바랍니다."
rows["284:1785882465"]="대격변은 던 모로에 혼돈을 창조해냈네. 이전에는 보지 못했던 막대한 양의 트로그들이 지상에 나타났고, 그 트로그 놈들은 우리의 오랜 적인 서리갈기 트롤을 우리의 정착지에서 정말 가까운 곳으로 몰아내 버렸지.$B$B이 문제를 해결하려고 아이언포지에서 내 산악경비대원들을 이곳에 파견해 주었네."
rows["284:1795960059"]="마치 저를 조롱하듯이 아름다운 광맥이 호수나 강 밑바닥에서 빛나는 걸 본 적이 한두 번이 아니랍니다. 광석 하나 건지지도 못하고 손에 채광용 곡괭이를 든 채, 망할 놈의 오크나 블러드 엘프가 물 밑으로 내려가 광석을 캔 다음 사라지는 모습만 하염없이 바라보며 그저 떠 있어야 했지요."
rows["284:843158445"]="이곳 시민들에게 사랑의 징표를 건네주면 답례로 다양한 선물을 받게 될 거예요. 그중 몇 가지는 손님께서 지니고 사용하고 싶어하실 테지만, 다른 것들은 한데 묶어서 당신이 좋아하는 영웅에게 바칠 수 있어요! 덜렁발 큐이피를 찾아서 선물세트를 주세요.$B$B큐이피는 볼바르 님, 마그니 님, 그리고 티란데 님 곁에서 찾을 수 있을 거예요."
rows["284:898887488"]="간신히 여기까지 왔네요. 예언자이신 레굴쿠트 님께서 경고했지만 제 부주의 때문에 결국 이런 꼴이 되었군요.$B$B저는 제스고르의 폐허를 연구하고자 이곳에 들렀다가 이동하는 도중 불타는 군단과 맞닥뜨렸답니다. 그 덕에 이제는 연구는커녕 다리에 깊은 상처만 남았군요."
rows["285:1483548428"]="우리 용아귀 부족은 너무나도 많은 고통을 겪었소... 그림 바톨에서 패배하고... 아웃랜드에서 수많은 전사들을 잃고... 지금은 황혼의 망치단이 갑자기 나타나 우릴 괴롭히고 있소.$B$B가끔은 우리 용아귀 부족이 다시 위대한 부족이 될 수 있을지 의심스럽다오. 하지만 잴라 같은 젊은이들이 이 늙은이에게 희망을 준다오."
rows["285:1782361362"]="나는 지도자의 책무와 역할에 아직 익숙하지 않네. 나크랄이 이렇게 반항할 줄 미리 눈치챘어야 했는데, 대비는커녕 그가 저지른 일을 수습하고 있다니.$B$B가로쉬 헬스크림은 어떻게 호드를 이끄는지 궁금하군. 호드처럼 다양한 세력이 모인 집단을 이끄는 걸 보면 엄청난 힘의 소유자일 테지... 그를 좀 더 자세히 알고 싶군."
rows["285:2139572201"]="내가 걱정하는 게 뭐냐고? 저 여자 늑대들과 서리 거인이 매일 서로를 죽인다면 어떨까?$B$B아니, 아니다... 난 토림께서 망연자실한 마음에서 벗어나와 울두아르를 다시 손에 넣는 일에 그의 동료들 모두를 규합해 주셨으면 한다.$B$B그분께서 이번 일을 해내지 못하시면 세상은 갈기갈기 찢어질 것이다.$B$B물론 이 일을 돕는다면 합당한 보상을 하겠다."
rows["285:52715337"]="하이 엘프 마법사이자 학자인 다리네스는 달라란의 가장 학식있는 고고학자에다가... 가장 사교적이랍니다.$B$B그녀는 달라란 중앙에서 바로 북쪽에 있는 요술쟁이 휴게실에서 자주 볼 수 있답니다. 그곳에서 분위기를 즐기거나 거친 여행자들에 대하여 고용자나 후원자들과 논하곤 한답니다."
rows["285:656429166"]="멀리 북쪽에 있는 우리의 위대한 고향, 썬더 블러프에 가면 당신에게 약초채집을 가르쳐 줄 수 있는 이들이 있습니다. 마을에서 북쪽으로 빠져나가는 길을 따라가면 썬더 블러프 꼭대기로 가는 승강기를 탈 수 있습니다. 도착하면 썬더 블러프 경비병들이 많이 있지요. 더 자세히 길을 가르쳐 줄 수 있을 테니, 붙잡고 한번 물어보십시오."
rows["285:736901369"]="길드에서 젊은 피를 보낼 때가 됐다고 생각하고 있었습니다! 어려운 발걸음을 하셨는데 헛수고가 되어 참 안타깝군요. 아직 허가를 받지 못해서 손님들 앞에서 공연을 할 수 없거든요. 모로스가 새로운 공연을 시작하지 못하게 막고 있어서 우리 후원자들도 미칠 지경이랍니다! 당장 모로스에게 모종의 조치를 취해야 합니다."
rows["286:241616235"]="우리 중 일부는 엘룬의 낫이 이 땅을 지나갔을 때부터 여기 살았소. 하지만 대부분은 길니아스의 몰락 때 고통받게 된 이들이지.$B$B우리는 자연의 길을 배우고 그 균형을 유지하기 위해 이 숲에 정착했소. 우리 저주받은 자들도 새롭게 살아가는 방법을 발견한 거요."
rows["286:485377315"]="\"오로기스트\"이란 무엇인가? 더 나은 질문은 \"오로기스트\"가 아닌 것\"이 아닐까? \"오로기스트\"라는 것은 모든 것을 연구한다는 뜻입니다! 사실, 저는 \"모든 것\"에 너무 잘 숙련되어 있습니다.$B$B미안해 내 내 내통자 말이지"
rows["286:651311757"]="빙... 뭐라고?$b$b뭐, 나는 저걸 그냥 '뭔지 모를 덩어리'라고 부르지. 우리 고향에 있는 자들은 대부분 저런 게 있다는 사실을 부정한다고.$b$b하지만 난 알고 있어! 가까이에서 본 적도 있고! 난 그것들을 탐색, 추적, 분석, 그리고 필요에 따라서는 파괴할 수 있도록 지난 수년 동안 이 배를 만들어 왔지!"
rows["286:874414792"]="이곳 시민들에게 사랑의 징표를 건네주면 답례로 다양한 선물을 받게 될 거예요. 그중 몇 가지는 손님께서 지니고 사용하고 싶어하실 테지만, 다른 것들은 한데 묶어서 당신이 좋아하는 영웅에게 바칠 수 있어요! 덜렁발 큐이피를 찾아서 선물세트를 주세요.$B$B큐이피는 케른 님, 실바나스 님, 스랄 님 곁에서 찾을 수 있을 겁니다."
rows["287:1107176117"]="제가 가르치는 도적들은 검, 단검, 하물며 손톱까지 모두 다룰 수 있도록 훈련시켰죠. 문제는 철퇴인데, 전 철퇴에는 손도 대기 싫고 철퇴를 쓰고 싶어하는 도적은 가르치지 않을 거예요.$B$B철퇴는 은밀한 구석이 전혀 없어요. 소리도 요란하고 뒤처리도 오래 걸릴 거예요."
rows["287:1695959909"]="우리 인생길에서 인연이란 아주 잠시 동안만 교차하는 것... 이제는 그 짧은 만남을 끝내고 각자의 길을 가야 할 때로군. 당신에게 가르침을 주고 그다음 스승에게까지 인도할 수 있음을 영광이라 생각하오. 오그리마에 있는 사루 스틸퓨리를 찾아가보시오. 당신이 배워야 할 것을 알 수 있을게요."
rows["287:174309465"]="오! 또 손님이군. 어서 오시게! 내 위대한 발명품, 자동판매기 1000을 한번 사용해 보는 게 어때? 필요한 건 다 있다고. 칼림도어의 온 상점을 다 뒤져도 못 찾을 희귀한 물건도 있다네! 참, 값을 깎지 못하도록 프로그램했을 거라는 건 말 안 해도 알겠지? 그냥 달라는 대로 내라고."
rows["287:1779281831"]="<엘프의 맹목적인 시선은 육지, 나무, 돌을 뚫고, 그 다음 무한히 떠 있는 어딘가에 남아 있다. 그의  ⁇ 은 얼굴은 감정이 드러나지 않는다. 그의 가슴의 미묘한 상승과 떨어지지 않았다면, 당신은 그가 그 뒤에 서있는 고대인과 같은 운명을 겪었다는 것을 생각할 것입니다.>"
rows["287:2073151649"]="그건 우리도 모릅니다. 검은용군단이 제3의 독립 세력과 연루되어 있다고 믿습니다. $r, 그것이 당신이 이곳에 온 이유이지요. 당신이 내부에서 이 수수께끼를 풀어내어 황천의 용군단에 구원을 가져다줄 것입니다.$B$B자... 여군주가 내 장갑을 가져오라고 했겠지요?"
rows["287:258384188"]="난 병참장교 러더퍼드 트윙이라고 하네. 이곳 아라시 분지에 주둔하는 파멸단에 물품을 보급하고 있지. 우리 파멸단으로부터 좋은 평판을 얻을수록 더욱 훌륭한 물건들을 살 수 있다네. 참, 수리할 물건이 있으면 고쳐줄 테니 가지고 오도록!"
rows["288:1283298080"]="어디까지 얘기했더라? 아, 맞아. 그 오크 녀석들이 윈저 님께 달려들었소. 윈저 님은 어땠느냐고? 그분은 그 자리에서 한 발짝도 움직이지 않았소. 오크 녀석들이 한꺼번에 열 놈씩이나 덤벼드는데도 홀로 우뚝 서 계시더군. 내 눈앞에 보이는 것이라고는 무쇠폭군에서 번득이는 불빛과 난무하는 선혈뿐이었소. 몇 시간, 아니 수일 동안 계속된 싸움으로 기억하오. 그랬을 거요. 기억도 잘 나지 않는군. 어쨌든, 결국에 가서 싸움은 멈췄지만..."
rows["288:1300968063"]="네 첫 번째 운동은 언더시티내... 상관없어 언더시티 헐적의 뒤쪽으로 가 로데론 브릴 남쪽에서 엘리베이터를 타고 내려가 언더시티 더 많은 도움을 요청할 수 있는 보호자들이 있습니다."
rows["288:1473318608"]="어디까지 얘기했더라? 아, 맞아. 그 오크 녀석들이 윈저 님께 달려들었소. 윈저 님은 어땠느냐고? 그분은 그 자리에서 한 발짝도 움직이지 않았소. 오크 녀석들이 한꺼번에 열 놈씩이나 덤벼드는데도 홀로 우뚝 서 계시더군. 내 눈앞에 보이는 것이라고는 무쇠폭군에서 번득이는 불빛과 난무하는 선혈뿐이었소. 몇 시간, 아니 수일 동안 계속된 싸움으로 기억하오. 그랬을 거요. 기억도 잘 나지 않는군. 어쨌든, 결국에 가서 싸움은 멈췄지만..."
rows["288:1575811542"]="<너 앞에 있는 이성적인 인물은 불꽃처럼 꺼질 뻔하고 있습니다. 그의 스펙트럼적 성격에도 불구하고, 눈의 로아는 겨울 경로에서 만난 모든 생물보다 더 무서운 것입니다.>$b$B<옛날의 트롤들이 그의 발 앞에 엎드려 신처럼 숭배하는 것은 놀라운 일이 아닙니다.>"
rows["288:1760608340"]="어머나, 안녕하세요! 저는 마샬 원정대의 수석 과학자 겸 생물학자, 홀라니에라고 합니다. 저와 오빠는 동료와 함께 온 아제로스를 여행하며 장엄한 야생의 세계를 탐험하지요. 참 재미있는 일인데... 이번에는... 그 재미의 도가 좀 지나쳤던 모양이에요!"
rows["288:2071768871"]="어디로 날아가려는 건가? 언더시티로 가게! 일단 마을에서 빠져나가는 길을 따라 남쪽으로 가게. 남서쪽 방향에 있는 로데론의 폐허로 가면 돼. 그 폐허로 깊숙이 들어가면 언더시티로 내려가는 승강기가 있지. 타고 내려가서 언더시티 수호병에게 길을 더 자세히 물어보게."
rows["288:406340839"]="이 알은 검은용군단의 알에 걸맞게 탄력 있어 보입니다. 많은 수의 에펙시스 결정을 알 옆에 놓는다면, 결정의 진동으로 이 알이 깨질지도 모르겠습니다.$B$B안타깝게도 이 일을 하는데 필요한 35개의 에펙시스 결정을 지니고 있지 않습니다."
rows["288:893934564"]="말루카즈는 이 숲의 역사적 중요성에 대해 끊임없이 떠들어 대더군. 하지만 난 당면한 문제가 해결될 때까지는 역사 따위를 생각할 정도로 사치를 부릴 여유가 없소.$B$B그가 이곳에서 하는 일이 중요하지 않다는 건 아니지만 누군가는 요새의 방어와 보급에 대해 걱정해야 한다는 거라오."
rows["288:951673045"]="아라토르 동맹이 아라티 계곡에서 해보고 있는 일은 존경할 만한 일입니다. 호드 친구들이 길을 막고 있어 스톰윈드 핫셰임 여인이 왕실에서 당신을 기다리고 있어 아라티 계곡으로 데려갈 수 있어요"
rows["289:1111234035"]="그게 뭘 말하는지 아는가? 바로 침략의 조짐이라네.$B$B그렇지, 주인님께서 차원문을 봉인하신 건 현명하신 판단이었어. 하지만 그 때문에... 이걸 어떻게 표현하면 좋나? 주인님께서는 초점을 잃으셨지. 그렇네... 주의력 말이야.$B$B그로 인해서 불타는 군단이 기회를 잡은 것이지. 이제 그들이 모습을 드러내고 나날이 숫자가 불어나고 있네."
rows["289:1484706881"]="아, 우리의 탈출을 자축하는 의미에서 한잔 마시고 있습니다. 지금까지 생각해 봤는데...$b$b우릴 공격한 그 난쟁이들이 죗값을 치르도록 해야 합니다!$b$b제대로 대응하지 못하면, 아무런 방어 태세 없이 이곳에 발을 들이는 모험가들이 모두 노예로 팔려갈지도 모릅니다. 물론 더 나쁜 일이 생길 수도 있고요!"
rows["289:1691821247"]="특허 출원 중인 센티파르 실리시드 과자의 잠재적 이윤 가치를 알아보던 도중에 모래 언덕 사이에서 부서진 짐마차를 발견했어. 나는 이렇게 생각했지. \"이야, 공짜로 짐마차가 생겼구나!\"라고 말이야. 적어도 자네가 이제껏 본 것 중에 가장 커다란 바실리스크가 나타나기 전까지는 그랬지. 그래서 나는 모든 걸 놓아두고 도망칠 수밖에 없었다고!"
rows["289:2022017328"]="지금 이 상황은 난장판이라는 말이 딱 어울리겠군요! 이 생물들은 도대체 어디서 튀어나온 거죠? 아무런 통제도 받지 않고 온 사방을 휘젓고 다니잖아요! 그리고 마법학자와 제자들은 어디로 도망간 거죠? \"빌리덴, 같이 가실래요?\"라는 말도 없이 나만 남겨두고 모두 없어지다니...$B$B이런 뻔뻔한 친구들 같으니라고!"
rows["289:2089579092"]="자네 손에 나가의 피가 묻어 있다면, 내 맹우라 할 수 있네.$b$b아주 오래전에, 다시는 누구의 노예도 되지 않겠다고 맹세했고, 이드라케스에게 붙잡히기 전까지는 맹세를 지켰지. 이제 분노를 억누르기 어렵군. 내가 원하는 건... 음식도, 잠도 승리도 아닐세. 피를 보고 싶을 뿐이야."
rows["289:346368844"]="잔자에게 알맞은 재료만 주면 고대 트롤 주술을 사용할 수 있소. 그 마법은 학카르와 그의 부하들을 무찌르는 데 큰 도움이 될 거요.$B$B자, 두 가지 물건만 가져다주시오."
rows["289:998260934"]="아, 안녕하세요? 호바트 박사님과 저는 요즘 카자마이트가 바닥났을 때를 대비해서 아주 혁신적인 신제품을 만들고 있어요.$B$B사실 저기 광산 안에도 카자마이트가 얼마 남지 않았잖아요? 그리고 안타깝지만 카자마이트가 떨어지면 카자콜라도 더는 없을 테고요."
rows["28:1013935765"]="내가 뭘 도와주면 좋겠나?"
rows["28:1014171979"]="친구여, 어떤 무기를 배우고 싶나?"
rows["28:1031742318"]="그런데, 무슨 일이오?"
rows["28:1051816865"]="라그나로스 님이 최고 지배자가 될 것이다!"
rows["28:1053590557"]="조금 도와주겠나, 작은 친구여?"
rows["28:1093019559"]="로봇전사 NX-01이 부셔졌습니다!"
rows["28:1267437970"]="뭐 필요한 거라도 있소?"
rows["28:128767489"]="우므프흐루므 므므프후르, 무르루프흐루..."
rows["28:1307581255"]="내가 목격자, 자란타우르일세."
rows["28:1375535314"]="날 구해줘, 마르텍!"
rows["28:1389049623"]="좀 맞고 싶으신 모양입니다만?"
rows["28:1393705397"]="팔을 움직이면 아프네요"
rows["28:1614237066"]="축하한다, 모험가들이여."
rows["28:1618394691"]="영이 함께해"
rows["28:1625096154"]="어허, 이 친구가... 바쁜 거 안 보이나요?"
rows["28:168270376"]="이런! 바위들이 가득하잖아!"
rows["28:1710562099"]="항해하기 좋은 날씨로군요, 그렇지요?"
rows["28:1766490134"]="나는 그다지 대화를 즐기는 편이 아닙니다."
rows["28:1782652580"]="<폭격기가 시끄럽게 덜거덕거립니다.>"
rows["28:1828183296"]="바엘 모단... 드워프..."
rows["28:185585891"]="험상궂은 주정뱅이 선술집에 오신 것을 환영합니다!"
rows["28:1927044902"]="여행 가이드가 영원히..."
rows["28:2003553651"]="배고파? 여기서 잠도 잘 수 있어."
rows["28:2020534892"]="<경례하는 대군주 모르고르>"
rows["28:2070987278"]="필멸의 존재여, 나의 감시는 영원할 것이다."
rows["28:2091964053"]="브르글브르글 아옳아옳!! 글럭!"
rows["28:229295647"]="싸움을 하고 싶니?"
rows["28:262376356"]="정신 바짝 차리게, 대장!"
rows["28:332794716"]="제가 요리를 가르쳐 드리죠!"
rows["28:501222333"]="쉬잇! 지금 여기 잠복한 거라네."
rows["28:565712791"]="- 여기서 뭐하는 거야?"
rows["28:605172472"]="자네 길을 잃은 것 같군..."
rows["28:619612260"]="너 뭔가 바라는 게 있다고 생각해."
rows["28:633770478"]="내가 말해 줄 것 같아?"
rows["28:688065444"]="내가 아는 데까지 최선을 다해 가르쳐주겠소."
rows["28:710862848"]="그렇게 울상만 짓지 말고 좀 웃어봐!"
rows["28:793388429"]="현장 물품 필요해요?"
rows["28:81179765"]="눈에 잘 띄지 않는 석판입니다."
rows["28:839227051"]="물론, 낚시하는 걸 가르쳐줄 수 있지."
rows["28:851770440"]="성스러운 빛을 받아들이시길, 어린 양이여."
rows["290:1737712853"]="정말로 자네가 부럽네. 호드의 이름으로 최전선에 나가 직접 적과 싸울 수 있으니 말이야. 내 역할은 지휘를 하는 것이지.$B$B나도 소싯적에는 내 꿈을 이루면서 살았기 때문에 이 늙은 나이에도 그나마 견딜 수 있는 것이라네. 이제는 승리의 영광도, 패배의 쓴맛도, 모두 내가 지휘하는 병사들을 통해 맛보고 있지."
rows["290:1962833003"]="미안하다, 얘야... 물어볼 수밖에 없구나. 시력이 예전 같지 않아서 말이지. 대신, 까마귀 신께서는 오랜 수명을 선물하셨지.$B$B머지않아, 네가 내 자리를 물려받을 때가 올 거란다. 내가 알고 있는 모든 걸 너에게 가르쳐 주었다. 내 단 하나 후회가 되는 것은 나에게 신성한 까마귀 경전을 찾을 자격이 있다는 것을 입증하지 못한 것이다."
rows["290:647411604"]="만약 우리가 생산량을 증가시키지 못하면, 호드가 이 전쟁에서 패배할 수도 있어요. 만약 호드가 전쟁에서 패배하면, 우린 길바닥에 나 앉게 될 거고, 최악으로는 목숨을 잃겠죠.$B$B이런 말을 하고 싶진 않았지만, 당신이 바람속삭임 숲에서 들었을 봉사활동이 우리 생명을 보장하진 않아요. 열심히 일해 호드가 승리하길 바라는 수밖에..."
rows["291:1643499909"]="오크들... 나는 한 평생을 오크들과 싸웠네.$B$B20년 전 우리는 호드를 제압하고 지옥불 성채의 성벽을 무너뜨렸네. 우리는 비열한 녹색 괴물들을 위기로 몰아넣었지! 그 일이 있은 후 우리는 몇 번의 사소한 충돌을 제외하고는 오크들로부터 별다른 위협을 받지 않았다네.$B$B현재까지는 말이야..."
rows["291:27605461"]="하늘을 날아오르는 것만큼 영혼을 자유롭게 하는 것도 없습니다. 우리 타우렌족의 위대한 중심지 썬더 블러프에 와이번 조련사가 한 명 있습니다. 블러드후프 마을에서 북쪽으로 빠져나가는 길을 따라가면 됩니다. 도시 밑에 도착해서 승강기를 타고 꼭대기까지 간 다음 그곳에 있는 썬더 블러프 경비병에게 물어보면 길을 더 자세히 알려 줄 겁니다."
rows["291:739006446"]="나 정도의 솜씨를 가진 이에게는 간단한 일이지만.$B$B짐승의 가죽으로 물건을 제작할 때 가장 힘든 부분이 바로 그 재료를 구하는 일이오. 내게 온전한 괴수의 가죽을 가지고 오면 강력한 물건을 몇 가지 만들어 줄 수 있소."
rows["292:1024698157"]="우리에게 생긴 그 재난 때문에 나더러 뭐라 하진 말라고... 어디로 가는지조차 볼 수 없었거든!$b$b하긴 어디로 가는지 보지 못했다고 나를 비난할 수도 있겠지만...$b$b안돼! 기다리라고! 난 이 배를 안전하게 댈 수 있단 말이야... 이건 선장님이 내리신 명령이 틀림없어! 아마 우리를 한계까지 밀어붙이고 어떻게 견뎌내는지, 어떻게 수리하는지 시험하고 싶은가봐."
rows["292:1522459099"]="저항이요? 군단의 선봉대에 맞서서요? 그럴 리 없죠!$B$B그 후로 그들이 어떻게 되었는지는 역사에도 남아 있지 않습니다... 생존자가 없었으니까요. 날뛰는 악마들이 지금 보시는 폐허만을 남겨 놓았고 학회의 비밀은 아즈샤라의 땅속에 아직 묻혀 있습니다."
rows["292:23127385"]="나는 병참장교 사무엘 호키라고 하오. 이곳 아라시 분지에 주둔한 아라소르 연맹에 물품을 보급하고 있소이다. 우리 연맹으로부터 좋은 평판을 얻을수록 더욱 좋은 물건들을 살 수 있소. 참, 부서진 장비가 있으면 수리해줄 테니 잊지 마시오."
rows["292:55615645"]="가젯잔 타임즈의 특파원이신가요? 절 따라오신다면 제 실험 기구들을 보여 드리도록 하지요...$B$B<자브라시스가 기다리던 그 기자가 아니라고 말하자...>$B$B이런, 아니라고요? 그렇다면 당신에게 필요한 물건을 찾아보세요. 시간 끌지 마시고요. 저는 기다리는 사람이 있습니다."
rows["292:579726784"]="페더문 수색선에 오른 것을 환영하오. 이 배는 페더문 요새와 잊혀진 해안 사이를 오가며 바다에서 실종된 이들을 찾고 있소. 제대로 준비하지 않으면 바다는 위험하기 그지없는 곳이라오.$b$b챙겨야 할 게 있다면 우리 배의 선창 담당자들과 이야기하시오. 그대에게 도움이 된다면 그들은 정말로 기뻐할 거요."
rows["293:1278434393"]="한때는, 숲이 우거진 쿠엘탈라스에 집이 있었지요. 한때는, 가족과 남편과... 아이들이 있었지요. 한때는, 생명이 있는 존재였고 세상 속에 살고 있었지요. 리치 왕이 눈 깜짝할 사이에 그 모든 것을 제게서 앗아가 버렸어요.$B$B비록 내가 직접 그를 칠 힘은 없지만, 반드시 세 배로 복수해 주고 말 거예요!"
rows["293:1479683309"]="엄... 죄송하지만 제가 당신을 그리 잘 알지 못해서 말이죠. 그게, 저는 공인 기계타조 상인으로서 확고한 노움의 친구로 간주되는 이들에게만 탈것을 팔 수가 있단 말이죠. 당신이 놈리건의 확고한 동맹이라고 인정받으면 기꺼이 제가 가진 것들을 보여 드리도록 하죠."
rows["293:1676305648"]="<그 작은 바그런의 바퀴에 기대고 있는 외로운 왜기는 그 칸의 주인일 것 같다고 생각하세요. 그 주변에는 열린 탄약 상자, 눈이 흩어져 있는 상자,  ⁇ 은 종이, 뒤집힌 배럴, 깨진 바구리들로 가득한 혼란스러운 카펫이 펼쳐져 있습니다.>"
rows["293:1961107762"]="말했듯이 나는 500년간 홀의 파편을 지켜 왔지만 홀의 파편은 한낱 골칫거리에 지나지 않았다. 그것은 모든 관심, 순수하지 않은 나쁜 의도를 지닌 자들의 관심을 끌었다. 내가 원하는 것은 조용히 혼자 연구하는 것이지 영웅이 되고 싶은 누군가가 그것을 훔쳐 가지는 않을까 감시하는 것이 아니었다. 그래서... 나는 홀의 파편을 물고기에게 던져 주었다."
rows["293:1985512675"]="안녕하세요, 제 이름은 페트라입니다. 오른쪽에 제 코도다가 있습니다. 우리는 마사셜 탐험대에 있습니다.$B$B만약 불꽃이나 불꽃의 원천이 있다면, 가능한 한 숨어서두세요."
rows["293:635954785"]="보나 마나 어둠의 여왕님께서 훈련을 시키라고 보내신 얼간이로군.$B$B<한숨을 쉬는 나타노스>$B$B이제까지 너 같은 놈들은 모조리 두 동강을 내서 여왕님께 돌려보냈지. 네놈도 같은 꼴이 될 거야.$B$B나야 뭐, 여왕님의 분부대로 할 뿐이니까 상관없지만 말이야."
rows["293:903207415"]="이제 헛것이 보이나? 이렇게 많은 시간이 흘러버렸는데... 진정 자네인가, 로카람?$B$B사이칼을 찾는다면 소용돌이 누각의 서쪽에 있는 수정들 틈을 걷고 있는지 살펴보게. 그는 그곳에 있는 원시적이고 야만적인 존재에 단단히 홀린 듯하네. 어떤 것도 잘못되어 보이진 않지만 말이야."
rows["294:1130268760"]="알터랙에는 두 개의 광산이 있습니다. 얼라이언스 영토인 깊은무쇠 광산과 호드 영토인 얼음이빨 광산이지요. 이 두 광산은 풍부한 자원의 보고이며 오래전부터 풍부한 보급품들이 비축된 것으로 알려져 있습니다.$B$B현재 이 광산을 차지하기 위해 호드와 얼라이언스는 물론 인근에 사는 생명체들까지 끊임없는 전투를 벌이고 있습니다."
rows["294:487030231"]="이 잔다이스 바로브의 일지는 언데드에 대한 욕설과 분노로 가득합니다. 책 뒷부분까지 읽어보니 지옥매듭 가방을 만드는 도안이 나와 있습니다. 바로 흑마법사가 영혼의 조각을 보관하는 가방입니다. 도안을 당신의 마법책에 옮겨 적겠습니까?"
rows["294:561344389"]="우리는 실험실을 지키고 약사가 일을 할 수 있도록 해$B$B하지만 그렇지 않습니다.$B$B십자군 전쟁은 계속 우리의 선을 시험해보고, 매주 더 강하게 밀어붙인 것처럼 느껴집니다. 우리는 붙잡고 있지만, 난 스트레스를 느낄 수 있습니다. 나는 얼마나 더 오래 더 많은 것을 줄지 모르겠어요."
rows["295:1540743744"]="강해지시오. 캘타스는 우릴 배반했고 우리가 아는 건 항상 변하고 있소. 하지만 낙담해서는 안 되오. 우린 항상 그래왔던 것처럼 이겨낼 거요. 아서스가 우리 땅을 휩쓸었을 때도 우리 영혼을 파괴하진 못했지 않소. 그리고 캘타스도 그러지 못할 거요. 번영하는 우리의 미래로 나아갈 수 있도록 모두에게 교훈이 되게 하시오."
rows["295:1660232611"]="섬을 돌아다니는 부서진 파수병들을 봤나요? 행동을 제어하는 수정을 약간만 개조하면 그 파수병들을 사용해서 전략 요충지를 방어할 수 있을 거예요.$B$B태양너울 성소는 머지않아 손에 넣을 수 있을 겁니다. 작업이 $3244w 퍼센트 정도 진행되었으니까요."
rows["295:1720724327"]="우선 내 신분을 솔직하게 밝히지 못한 것부터 사과해야겠군. 난 자네를 신뢰해도 되는지 확신이 없었다네. 누가 늙고 잊혀진 은둔자를 사심 없이 도와주겠는가?$B$B자네는 스스로 그걸 증명해 보였네. 자네는 청렴하고 명예를 아는 친구야."
rows["295:1738481855"]="우리 서버에서 가장 인기 좋은 영웅이 누구냐고요? 현재 순위를 알려드리죠!$B$B스랄: $2200w$B$B케른: $2201w$B$B실바나스: $2202w$B$B호드 전체: $2207w$B$B$B바리안: $2203w$B$B마그니: $2204w$B$B티란데: $2205w$B$B얼라이언스 전체: $2206w$B$B인기 투표에 당신의 소중한 표를 행사하고 싶은가요? 그렇다면, 저에게 선물세트를 내세요!"
rows["295:235881495"]="우리 서버에서 가장 인기 좋은 영웅이 누구냐고요? 현재 순위를 알려드리죠!$B$B스랄: $2200w$B$B케른: $2201w$B$B실바나스: $2202w$B$B호드 전체: $2207w$B$B$B바리안: $2203w$B$B마그니: $2204w$B$B티란데: $2205w$B$B얼라이언스 전체: $2206w$B$B인기 투표에 당신의 소중한 표를 행사하고 싶은가요? 그렇다면, 저에게 선물세트를 내세요!"
rows["295:348562157"]="유감스럽게도 이곳 블러드후프 마을에는 재봉술을 가르치는 이가 하나도 없습니다. 하지만 썬더 블러프에는 있을 겁니다. 마을에서 북쪽으로 빠져나가는 길을 따라가다 보면 여러 대의 승강기가 있는 곳이 나오는데, 그걸 타고 꼭대기로 올라가서 썬더 블러프 경비병 중 한 명에게 길을 물어보십시오."
rows["295:482550645"]="어서 오세요! 이곳은 바로 예브 네블기어의 다크문 별난 동물원입니다. 살아 있는 전설과 신비로운 것들이 모여 있는 곳이죠! 마음껏 즐기십시오!$B$B하지만 아무거나 함부로 만져서는 안 됩니다! 여기에 전시된 유물과 짐승들에는 신성한 것도 있고, 아주 무시무시한 것도 있으니까요! 과도한 호기심을 참지 못하고 함부로 만졌다가는 손이 불에 탈 수 있습니다..."
rows["295:790411391"]="내가 너라면 눈을 뜨고 귀를 기울일 거야 너 때문에 카자로 산과 잃어버린 섬 화산이 폭발했다는 소문이 퍼져나가고 있어$B$B미친 짓은 알아요 하지만 사람들은 뭐든지 거론하고 영웅들을 파괴하는 걸 좋아하죠"
rows["295:857716284"]="이곳에 푸른용혈족은 없지만, 말리고스의 추종자들은 있소. 정확한 이유는 모르겠지만 한 가지는 분명하오. 푸른용혈족이 있는 곳에는 비전 마법이 있게 마련이라는 것이지. 이곳에서 용혈족이 뭔가를 보호하고 있다고 해도 놀라운 일은 아니오... 어쩌면 엘프의 명가가 남긴 것을 보호하는 걸지도 모르오."
rows["296:1125900237"]="북쪽 부두에서는 루테란 마을과 다르나서스로 가는 배를 탈 수 있고 남쪽 부두에서는 대해를 건너 스톰윈드 항구로 갈 수 있네. 방파제의 맨 끝에 있는 서쪽 부두에서 엑소다르 근처인 하늘안개 섬으로 갈 수 있다네. 그럼, 편안하고 즐거운 여행이 되기를 빌지!"
rows["296:1266051271"]="이제 당신은 나보다 솜씨가 더 좋습니다. 내 오랜 친구인 로트가스 스톤비어드를 만나 보지 않겠소? 내가 제이나의 군대에 입대하기 전에 그 친구는 아이언포지에 남아 있었습니다. 그라면 당신에게 몇 가지 가르쳐 줄 수 있을 겁니다. 아니면 최소한 당신을 가르칠 수 있는 이를 알고 있을 거고. 아직 아이언포지에 있다면 대용광로에 살고 있을 겁니다."
rows["296:152239146"]="전 J.D.라고 해요. 어떻게 이곳에 오게 됐는가는 자세히 말 못하겠지만 이제 이 야영지가 제 집이라는 것만은 확실해요!$B$B전 분화구 주변에 널려 있는 신기한 수정들을 조사하면서 지낸답니다. 이곳으로 오는 길에 분명 뭔가를 본 듯하신데요. 대체 뭘 보신 건가요?"
rows["296:1549359436"]="나 봐 농민, 내 몸에는 머리부터 발끝까지 유물이 있어 아제로스 그 누구도 몰랐어요$B$B이제 자기 자신을 봐$B$B빨리, 날 돌아 봐$B$B이 말은 별으로 만들어졌습니다.$B$B정신적으로 결핍된 오크에게 어떤 무리한 임무가 준비됐을까요?"
rows["296:467817531"]=" ⁇ 리 가게에 오신 걸 환영합니다. 컷을 받으러 오세요? 색칠을 받으러 오세요?$B$B얼굴 머리카락을 잘라내며 피어징을 할 수 있고, 손톱과 뿔을 재구조할 수 있고, 심지어 죽은 자들의 특징을 수정할 수도 있습니다!$B$B앉으면 곧바로 일을 시작해줄게"
rows["296:873119342"]="\"비대\"라는 醜い 단어. \"비대\"라는 말. \"아니요\". 저는 그 를 비대 하지 않습니다. 그 의 약점 을 인정 하기 때문 입니다. 교회 는 인간 의 노력 이며, 사람 으로서 태어난 모든 것 처럼, 오류 에 유력 합니다. 오히려, 저는 그 를 아들 이 성숙 을 이루는 때 어머니 를 보듯이 보며, 그 는 최선을 다 하였지만, 종종 넘어진 실수 한 여자 입니다."
rows["297:1225237917"]="켈투자드는 지팡이를 복원하기 위해 엄청난 노력을 했소. 지팡이 조각들은 칼림도어에서 남쪽 바다에 이르기까지 아제로스 전 지역에 흩어져 있었지. 한때 나는 지팡이 조각을 20개나 가지고 있던 적도 있었소. 하지만 켈투자드의 부하들에게 도둑을 맞았지. 내가 여기 온 것도 바로 그 때문이오."
rows["297:1870872283"]="반갑습니다, 와일드해머의 친구여!$B$B영면의 안식처는 우리 동족에게 영적 수도입니다. 서로 다른 여러 가문이 평화롭게 한자리에 모이는 장소이고요.$B$B여기서 저희는 저 세상에 간 영웅들을 기리는 의식을 치른 후 천둥쐐기 산꼭대기에 영웅과 그의 그리핀을 함께 장사 지냅니다. 그들이 영원히 하늘을 누비게 해주는 거죠."
rows["297:1872604700"]="이곳의 모든 전쟁 물자가 실리더스 사막으로 옮겨질 테니 낚시를 할 수 있는 시간도 이제 $2113w일밖에 남지 않은 것 같군요. 물자를 모두 옮기고 준비를 끝내면 관문을 열고 전쟁을 시작하기 위해 누군가가 세나리온 요새 남쪽에 있는 징을 울려야 할 것입니다."
rows["297:2007415553"]="흐음, 어디 한번 보자... 저쪽에 있는 광산에서 노역꾼 몇 명이 뛰쳐나오는 걸 봤소. 거미에 대해 뭐라고 하더군. 새 손님이라고 했소? 아, 제랄리가 있었소. 아름답고 젊은 노움이지. 지난주에 자기 키보다 두 배는 큰 도끼를 사갔소. 아, 그리고 비스프 님께서 방어구를 구하러 오신 적이 있었소. 그분께서 왜 판금 갑옷이 필요한지는 확실히 모르겠다오..."
rows["297:347622428"]="크레나 님이 내 능력을 의심하고 있는 게 분명하네. 우리 정예병들이 얼라이언스와 그들의 덫사냥꾼 동맹을 상대하거나 트롤들을 쳐부수는 동안, 난 성가신 용약탈 브리쿨들을 쓸어버리라는 명령을 받았네.$B$B우리가 힘을 합친다면 정복자님께 우리 실력을 증명해 보일 수 있을 걸세."
rows["298:239846950"]="그곳은 한때 거대한 나이트 엘프 도시였소. 엘프의 명가가 군림하며 아주 강력한 비전 마법을 연마했지. 하지만 지금은 저주를 받아 유령처럼 그곳을 떠돌고 있지. 폐허가 되어버린 도시는 원한꼬리 나가들 때문에 더욱더 황폐해지고 말았소. 나가들은 그 폐허에 숨겨진 강력한 명가의 유물을 찾아다니는 걸로 알고 있소."
rows["298:844398002"]="지구 어머니 의 열매 를 사용 하여 우리 의 영원 한 투쟁 에 도움 을 주기 위한 약 을 만들어내는 것 은 영광 스러운 노력 이다. 이 점 을 배우기 위해 당신은 북쪽 으로 우리 의 위대한 고향 썬더 블러프 으로 여행 해야 한다."
rows["299:1492428330"]="식량을 포함해서 우리가 수집한 모든 전쟁 물자를 실리더스로 옮기는 중이에요. 모두 $2113w일 내로 도착할 거예요. 세나리온 요새 근처에 모든 물자가 모이면 누군가 스카라베 제단에 있는 징을 울려야 안퀴라즈 관문을 열고 전쟁을 시작할 수 있다고 들었어요."
rows["299:1760334934"]="<한숨을 쉬는 이스파르>$B$B나무 위에 지은 건축물 중에는 살기에 적합하지 않은 곳도 있습니다만, 세데크 전당 전체로 볼 때는 상당히 발전한 모습입니다.$B$B예전 샤트라스에 있었던 것처럼 편안하게 스케티스에 있는 내 진짜 집에 내 여동생과 함께 돌아가지 못합니다. 내 여동생은 우리의 오랜 형제들이 죄인을 관리하는 세데크 전당에 아직도 묶여 있어서 말입니다."
rows["299:1871382406"]="놀랍지 않소? 이 역사의 잔재들이...$B$B날 얼마나 더 놀라게 할지 가늠할 수 없소이다. 그 굉장한 크기? 아니면 유구한 역사? 조사할 게 너무나도 많소. 어떤 연관성이 있는지 알아내야지.$B$B그런데 혹시 여러 종족이 나이트 엘프와 같은 전통을 가지고 있다는 소문을 들어 본 적이 있소?"
rows["299:2134901081"]="불의 군주님은 한때 동지들과 함께 전 세계를 군림했었다. 그분은 고대 신의 신하로서 티탄들과 이 세계를 장악하기 위한 싸움을 벌였지. 하지만 승리는 티탄들에게 돌아갔고 주인님은 동지들과 정령계로 영원히 추방당했다. 그리고 티탄의 시대가 끝날 때까지 그곳에 갇히고 말았다."
rows["299:809477046"]="요르문가르는 눈 속에 숨어 있을 때만 움직일 수 있으며, 그 상태로는 적을 공격할 수 없습니다. 지상으로 나온 요르문가르는 강력한 독 공격으로 무쇠 거대괴수의 외피를 녹일 수 있지요. 무쇠 거대괴수의 가장 강력한 공격을 피할 수 있도록, 항상 땅속 숨기를 할 준비를 하고 계세요."
rows["29:1026994111"]="장군 칼리스레쉬는 쓰러질 것입니다!"
rows["29:1056077148"]="여름의 불꽃이 들어옵니다"
rows["29:1062377909"]="자네의 도움을 받아 다행이네."
rows["29:1193053963"]="가이드가 곧 도착하기를 바랍니다."
rows["29:1265506665"]="하찮은 일로 날 방해하지 말게!"
rows["29:126615899"]="수신 완료. 상태를 보고하라, 병사."
rows["29:1348194099"]="전 아주 아주... 아주 바빠요! 무슨 일인가요?"
rows["29:1352681257"]="난... 걱정하지... 마시오."
rows["29:1435635984"]="뭐 도와드릴 거라도 있습니까?"
rows["29:1497414076"]="너 사탕 좋아해? 난 좋아하는데..."
rows["29:1499966294"]="아조라의 탑에는 어쩐 일이세요?"
rows["29:1561286166"]="안녕하세요, 연습이 필요해요?"
rows["29:1794987895"]="뭘 보시오, 친구?"
rows["29:1817556788"]="무슨 일입니까, 이방인 친구?"
rows["29:1822646188"]="나 아무 말썽 안 부린다, 왕."
rows["29:1898774624"]="눈에 잘 띄지 않는 대리석 석판입니다."
rows["29:1953848341"]="이제 그 들이 들어갔어요!"
rows["29:2026650010"]="평범한 생명체여, 내 인내심을 시험하지 마라."
rows["29:248423503"]="<여군주 프레스톨이 노려봅니다.>"
rows["29:266452220"]="뭘 원하는지 말씀해 보시오."
rows["29:406449090"]="여기에서 벗어나야 합니다!"
rows["29:50283898"]="꽤액! 널빤지로 보내! 보내!"
rows["29:512955694"]="언젠가는, 저도... 승천할 거예요."
rows["29:694045333"]="어떤 목소리가 내게 말을 걸어와."
rows["29:779819828"]="실력 발휘하러 왔는가?"
rows["29:791246472"]="늑대를 찾아주어 고마워요."
rows["29:833020805"]="이 오크는 심하게 상처입었습니다."
rows["29:844556454"]="오늘은 어디로 보내 드릴까요?"
rows["29:908863527"]="좋아요. 어, 일할 준비가 됐어요!"
rows["300:1260867772"]="마지막 전쟁에서 타우렌은 싸웠고 샤만은 이 세상을 방어하기 위해 스컬지 침략으로 인해 많은 사람들이 목숨을 잃었습니다. 다른 방법으로는 많은 사람들이 찢어졌습니다. 그들의 신체 부위가 저주받은 성곽에서 불쾌한 실험을 위해 사용되었습니다."
rows["300:1565928471"]="달라란이 멸망한 후 저는 키린 토를 떠났어요. 아티쉬를 수호하면서 수년을 보냈지만 키린 토에서 제게 맡긴 중요한 임무가 한순간에 무너졌지요. 평생이 걸린다 해도 그 지팡이를 찾고 말 거예요. 제가 은빛 여명회에 합류한 것도, 여기 온 것도 바로 그 때문이에요."
rows["300:23540447"]="동료와 나는 인간 종족 중에 가장 위대하고 헌신적인 분을 기리는 의미로 우리 스스로 로서의 후예들이라 칭했소. 우리는 넬쥴을 꺾고 그 광기를 잠재우려고 사력을 다했소.$B$B이 세계가 운이 다해 붕괴했을 때 우리가 사랑하는 아제로스에 피해가 가는 일이 없도록 어둠의 문을 파괴했소."
rows["300:501038669"]="놀랍소! 이전에 보지 못하던 길이 이 안에 있다니. 당신이 이 길을 따라가 보려면 시간이 좀 걸릴 것이오. 이런 책을 더 찾으면, 즉시 알려주었으면 하오. 내가 데리고 있던 키린 토 지식의 전령 하나를 데려가시오. 우연히 뭐라도 발견할 때를 대비해서 말이오."
rows["300:75044619"]="이곳은... 오염되었어요.$B$B전 간신히 탈출했지만 도저히 다시 굴을 통과해서 내려가질 못하겠네요.$B$B제 형제와 자매들은... 운이 좋지 못했답니다. 내부에 있는 덫 때문에, 그들은 그곳에 자라는 악마의 정원에서 흘러나온 타락한 기운이 깃든 안개로 제정신이 아니에요.$B$B당신이 우리를 도와줘야만 합니다."
rows["300:782506948"]="지하수를 에메랄드의 꿈과 직접 연결하려는 계획을 세웠습니다. 믿음직한 신도들과 함께 통곡의 동굴 안쪽으로 깊숙이 탐험하여 명상을 시작한 후, 꿈속으로 들어갔지요. 제 몸을 통해 바깥 세계와 꿈이 연결되었습니다.$B$B그곳에서부터 모든 게 잘못되기 시작했습니다."
rows["301:1014196245"]="추락 사건 이후 지금까지 벌어진 모든 일은 단지 시작에 불과합니다. 엑소다르를 탄 것이 마치 전생의 일처럼 느껴지는군요.$B$B지금 제 현실은 돌연변이 생물들 그리고 수많은 블러드 엘프 첩자들과 함께 이 섬에 갇혀 있다는 것입니다. 조만간 저도 그들과 별반 다를 바 없는 처지가 될 테지요..."
rows["301:1908349122"]="최근, 검은무쇠 드워프들을 목격하는 사례가 늘어나고 있어요. 황야의 땅 곳곳에 요새를 세우고, 고대 지식을 구하기 위해 울다만 깊숙한 곳으로 대규모 탐색 부대를 보내고 있답니다. 심지어는 우리 본국에까지 침입해 모단 호수 근처 댐을 공격하기도 했답니다."
rows["301:406338977"]="그렇습니다. 이 물건은 결국 파괴되었고 데스윙도 다른 4명의 위상들이 모여 형성된 새로운 힘에 의해 거의 처치될 뻔했지요. 지금 데스윙이 어디에 있는지는 모르나 그의 자손인 네파리안이 이 요새를 지배하며 자신의 아버지가 남긴 업적을 마저 이루고자 한다는 것은 압니다."
rows["301:724212598"]="이런... 안됐지만, 자네는 최근에 내게서 점괘를 받았기 때문에 지금은 운명 상담을 받을 수 없어.$B$B점괘를 받은 지 몇 시간이 지난 후에 다시 오라고. 그러면 운명의 힘이 다시 원상태로 돌아오게 되니까 내가 자네의 미래를 예견할 수 있을 거야."
rows["301:813411713"]="군주 바일텅이 두 조각을 결합시키는 데 필요한 주문을 알지 못하니 그 홀을 사용할 수가 없었지. 하지만 이제 내가 바일텅의 타락의 저주로부터 해방됐으니 자네가 홀의 머리 부분과 자루 부분을 모두 가져오면 내가 자네를 도와 주도록 하겠네."
rows["301:835620661"]="이중 전문화란 두 개의 활성화된 특성 설정을 유지할 수 있도록 도와주는 기능입니다. 이중 전문화를 사용하여 두 특성을 손쉽게 전환할 수 있습니다. 1특성에서 2특성으로 전환하면 그에 따른 문양, 행동 단축바를 사용할 수 있습니다. 전투 중에는 특성을 전환할 수 없으며, 특성을 전환하면 사용할 수 있는 마나, 분노, 룬 마력, 기력 등이 소모됩니다."
rows["301:9048849"]="미안하지만, 이곳 브릴에는 없으니 언더시티로 가봐야 할 것 같네. 언더시티는 브릴 남쪽에 있는 로데론의 폐허 아래에 있지. 폐허의 뒤편에 아래로 내려가는 승강기가 있으니, 그걸 타고 가서 언더시티 수호병에게 더 자세히 길을 물어보도록 하게."
rows["302:1381625616"]="그들이 당신에게 초임자가 할 일에 대해 알려주지 않던가요? 이 마나괴철로는 폭풍우 요새의 부품으로 건설되었으며 황천으로부터 에너지를 흡수하도록 설계되었습니다.$B$B나루는 이 기술을 사용해서 여행하는 동안 그들의 비행선을 강화했지요. 이 기술이 지상에서 사용하기에 안전하지 않다고 주장하던 이들도 있었지만 그런 이들은 그 즉시 입막음을 당했습니다."
rows["302:1386183736"]="전부 왕의 부하다. 천둥발 크리그, 경비병 셋, 크롬크러쉬 대장, 그리고 정찰병이 새 왕에게 공물 바친다. 부하를 죽이면 공물 못 받는다! 부하 한 놈씩 살려둘 때마다 공물을 더 받는다. 모두 살려두면 아주 큰 공물 받을 거다!$B$B암, 그렇고말고!"
rows["302:1534574037"]="아, 그 친구들이야말로 비극의 주인공이지요.$b$b그들은 줄아만의 저 벽 너머에서 자취를 감췄습니다. 한동안 그들에 대한 소식은 듣지 못했지요.$b$b전 말입니다, 명성과 부에 대한 지나친 집착을 수백 번도 더 봐왔지요. 그들을 잡아두려고도 하고, 아직 준비되지 않았으니 무리라고 설득도 했지만... 결국 그 친구들은 위험에 뛰어들고 말았습니다..."
rows["302:198245812"]="은빛십자군 기수들은 균형과 정밀함, 공격과 방어의 절묘한 조합을 신조로 한답니다.$B$B하지만 그들은 당신을 상대로 거리를 잡느라 종종 돌진 기술에 노출될 거예요.$B$B당신이 당하기 전에 먼저 돌진해서 거리를 좁히시고, 찌르기를 위해 방향을 바꾸면서 방패 부수기를 사용하세요."
rows["302:244276504"]="당신의 솜씨는 그 어떤 말로 칭찬해도 모자라겠군. 망치와 모루로 이렇게 놀라운 일을 할 수 있다니. 이제는 고블린에게 가서 대장기술을 배우시오. 단 내가 그런 말을 했다고는 아무에게도 얘기하지 말고. 브리크 킨크래프트라고 하는 자를 찾아가시오. 일전에 듣기로는 무법항에서 상점을 하나 운영하고 있다고 하더군."
rows["302:702736203"]="전설에 의하면 현재 역병지대라는 지역에서 극심한 충돌이 있었던 장소에는 땅에서 깨끗하고 신성한 샘물이 솟아오르기도 한다고 전해진다. 전쟁에서 스컬지에 의해 쓰러진 자들을 기리는 뜻에서 대가와 일반인 할 것 없이 모두 이러한 샘에서 나는 물을 '영웅의 피'라고 불렀다."
rows["303:1119244185"]="텔사마에 온 것을 환영합니다! 모단 호수에서 집처럼 편히 지낼 수 있는 유일한 곳이지요.$B$B텔사마는 좋은 곳이지만 임무를 수행하고자 부름을 받은 자에게 항상 좋은 것만 있는 건 아니랍니다! 얼라이언스의 이름으로 목숨을 걸 생각이 있다면 탐험가 연맹 텔사마 지부 건물의 바깥에 있는 전단을 읽어 보시기 바랍니다."
rows["303:1784740303"]="농담이죠? 아닌가요? 알았어요, 알았다고요. 그만 진정하세요. 다행스럽게도 지난번에 당신이 되찾아온 물건들을 화로에 불어넣을 때, 나 자신을 그것과 맞추어 놓았답니다. 그래서 당신이 놔둔 장소에 상관없이 그 위치를 알아내서 소환할 수 있어요.$B$B그런데 잃어버린 것이 분명한가요? 소지품과 은행에 둔 물건들은 모두 확인해본 거죠?"
rows["303:2097998924"]="말퓨리온 스톰레이지 님을 찾고자 다르나서스에서 남쪽으로 날면서, 전 아우버다인 폐허에서 온 상처입은 난민들을 만났습니다.$B$B저들의 대의는 정당하기에 회복되는 걸 돕는 중입니다. 상처가 많아 회복하는 데 시간이 필요할 겁니다.$B$B그대도 저들을 도와줄 의향이 있으리라 믿습니다."
rows["303:210562815"]="양을 잡으면 배제도 받는데, 이건 할머니의 배제도 아니고, 꼭 써야지!$b$b몇 번  ⁇ 을 풀고 속도를 높여서 계속  ⁇ 고  ⁇ 고$b$b하지만 빨리 갈수록 더 빨리 피곤해지겠지$B"
rows["303:279052243"]="반갑습니다, 용사님! 십자군 사령관의 시험에 대비해 동료를 모으셨나요? 가장 강하고 뛰어난 용사만이 이 시험에 도전할 수 있습니다. 시험을 치르고 싶으시다면, 먼저 일반 난이도에서 십자군의 시험을 통과하셔야 합니다."
rows["303:306484335"]="<당신에게 고개를 돌리기 전에 지옥사냥개와 정답게 소곤거리는 안젤라>$B$B지르시는 항상 다른 지옥사냥개들보다 더 작았지만, 크기는 우리 지르시에겐 아무 걱정거리도 아니지. 그리고 아웃랜드는 그런 모든 걸 바꿔놓을 거야. 그렇지, 우리 지르시야?$B$B이 엄마의 작은 천사는 크고 사나운 사냥개로 자랄 거니까, 그럼 그렇고말고, 우리 예쁜 지르시!"
rows["303:518490655"]="놀랄 일도 아니군요.$b$b이상한 점이 너무 많아 도저히 모른 체할 수가 없습니다...$b$b고고학 유적지에 왜 이렇게 무기가 많을까요? 또 발굴한 유물은 어떻게 될까요? 누구의 허락을 받고 이렇게 발굴이 이루어지고 있을까요?$b$b빠른 시일 내에 답이 나올 것 같지는 않지만, 아무래도 내가 직접 알아봐야겠습니다."
rows["304:1185647094"]="난 리치 왕의 몰락을 직접 지켜봤다. 티탄의 창조물은 내 무적의 도끼 아래 무너졌고... 노스렌드의 야수들과 맞설 때는 은빛십자군의 선봉에 서서 홀로 승리를 이끌었지. 이제 난 궁극의 도전을 원해. 언덕마루 구릉지는 왕을 쓰러뜨린 자 오르쿠스에게 어떤 도전을 선사할 수 있나???"
rows["304:1252620415"]="으하하, 여기 보이나? 그립타가 돌아왔다고! 내 사랑스러운 노점에, 내 오랜 상품들 곁에 말이야! 장사할 준비도 마쳤지!$b$b더 나아지고, 강해지고, 빨라지고 싶나? 여기 있는 목걸이를 쓰면 그렇게 된다고. 검증된 작품이야! 어서 와서 가격까지 착한 기적의 목걸이 하나 사게! 내 반값에 주지!"
rows["304:1437525988"]="<싱긋 웃는 카드가>$B$B나는 아달과 그의 동족을 설득하여 이곳으로 돌아왔소. 이 우주에서 불타는 군단을 몰아낼 수 있는 것은 그들뿐이라고 믿고 있소. 하지만, 먼저 그들의 힘이 우리 가슴속에 자리잡아야 하오. 당신도 곧 알게 되겠지만...$B$B악에 맞서 싸우려면 우리 스스로 그들의 영원한 빛을 밝히는 봉화가 되어야 하오."
rows["304:262882237"]="우리는 모두가 가을 축제를 즐기기를 바랍니다. 몇 명이라도 가을 축제를 기억해준다면 힘이 될 거예요.$b$b이 고글을 쓰면 누구나 취한 것 같은 기분을 느낄 수 있습니다. 아무것도 안 마셔도요. 고글을 쓰기만 하면, 취한 거나 마찬가집니다! 벗으면 다시 말짱해지는 거고요!$b$b어때요, 갖고 싶지 않습니까?"
rows["304:526378359"]="이곳의 현역 작업반장으로서 이곳에서 일어나는 모든 형태의 사업, 노동, 휴식, 그리고 휴식에 일정 수준의 지루함이 포함되도록 하는 게 내 임무라네.$B$B자네에게 부탁한 일이 너무 쉽고 간단하다고 생각되면 즉시 내게 보고하라고."
rows["304:748324408"]="이제는 오히려 내 작품의 모서리 둘레가 거친 것 같군요. 솔직히 더 이상은 내가 가르쳐 드릴 게 없을 것 같아요. 아이언포지의 벤구스 딥포지라면 당신을 가르칠 수 있을 거예요. 금속에 관해서라면 모르는 게 없는 드워프거든요. 아이언포지의 대용광로로 가서 제자를 받는지 한번 알아보세요."
rows["305:1159951366"]="불타는 칼날단이 몰락한 이후, 우리 검귀들은 자신과 종족 모두를 악마의 지배에서 건져내겠다고 맹세했다네.$B$B그 일은 끝났을지 모르지만, 아직 난 충분한 명예를 얻지 못했지.$B$B호드를 위해 싸울걸세. 다른 전사들도 그리하도록 훈련할 테고. 전장에서 영광스럽게 죽는 그날까지 말이야. 이게 유일하게 내가 가고자 하는 길일세."
rows["305:1209284383"]="우린 윅과 일꾼들이 저 벽 너머에 새로운 항구를 지을 수 있게 벽을 무너뜨리려고 해요. 그런데 우둔한 윅 녀석이 폭약을 너무 많이 쓰는 게 아니냐며 징징대잖아요!$B$B쳇. 난 녀석이 기저귀 차고 겨우 기어다닐 때부터 이 일을 해왔어요. 녀석이 계속 시끄럽게 굴면, 운하에 내던져버리고 작업을 전부 내 손으로 해버리겠어요!"
rows["305:1240335614"]="<포세이큰의 면밀히 살펴보면, 그녀의 두 눈알이 땅에 떨어지지 않는 유일한 것은 그녀의 어두운 렌즈 안경입니다. 유리 안경에 밀려서 광신경에 의해 느슨하게 매달려있는 것은 넓은, 항상 경각심을 가진 눈을 가진 불안한 모습을 제공합니다.>$b$B안녕하세요!"
rows["305:1729015963"]="영광을 구하며 돌진하던 너는 만사가 네 행동에 의해 좌우된다고 믿었지. 나 같은 존재에게는 그게 얼마나 터무니없어 보이는 일인지 상상이나 할 수 있겠나? 나는 원한다면 네놈의 보잘것없는 생각이 네 머릿속에 떠다니는 땅콩만한 잿빛 덩어리를 짓뭉개 버리도록 할 수도 있는 존재란 말이다."
rows["305:1755424296"]="당신이 뭔데 여기 와서 나한테 이래라저래라 하는 거지? 이 마을에서 어둠의 의회의 지도자요. 내 눈앞에서 썩 꺼지라고!$B$B다시 내 눈에 띄는 날에는 세상 끝날 줄 아시오. 알아들었소?$B$B아마도 아킨둔의 어둠의 미궁에 묻히거나 울림에게 희생당하고 싶은 건가?"
rows["305:2050962949"]="이번 순례를 맡은 게 후회되기 시작하는군요. 저는 험난한 여정을 예상했고 여행에도 익숙합니다. 그런데 아웃랜드가 이렇게나 거친 곳인지는 미처 몰랐습니다.$B$B무엇보다도 저 탈레리스가 제가 완전히 회복하기도 전에 여기서 저를 쫓아내려고 하는 것 같습니다."
rows["305:873501175"]="이 기념비는 스톰윈드를 수호하다 쓰러져 간 모든 이들에게 바쳐진 것이다. 우리 종족은 자유를 지키고 스스로 운명에 대한 주도권을 잃지 않기 위해 믿을 수 없을 정도의 고난을 극복해 왔다. 바로 이곳에서 우리 종족을 휩쓸고 간 1차 대전쟁 중에 있었던 시민들의 모든 희생을 기념하는 것이다."
rows["306:1016528517"]="아, 지금 자네가 탄 배가 바로 그 배지. 정말 아름답지 않나? 남작님이 얼마 전에 날 여기 선장으로 임명했지. 내 배가 아니라서 이름을 붙일 수는 없었다네. 이름에 대한 내 의견이 궁금하다면, 젊은이, 이 배에 이름을 붙인 뱃사람은 원하는 만큼 항구에서 시간을 보내지 못하고 바다에만 너무 오래 있었던 듯하다고. 내 말이 무슨 뜻인지 안다면 말이지만."
rows["306:1019827957"]="그곳에 어떤 괴물이 사는지 알기나 하십니까? 최악의 경우에는 우리가 당신의 유해를 삽으로 퍼서 회수해내는 일이 생긴다고요. 벌써 그 끔찍한 괴물들에게 우리 착하디 착한 드워프 친구들을 얼마나 잃었는지 모릅니다.$B$B내 대답은 \"절대 안 된다\"예요. 이글거리는 협곡에 그렇게 들어가고 싶거든 다른 길을 찾아보도록 하십시오."
rows["306:1060239248"]="여기까지 오다니 제법이군, 오간아카. 넌 정말 재능이 넘치는 랩터야... 하지만 지금부터는 쉽지 않을 거야.$b$b저 앞의 다리에는 정찰임무를 수행하는 트롤이 있는데 주의를 끌기 힘들 거야. 하지만 저놈들의 이동 경로에 해골을 놓아둔다면 발에 걸려 다리 밑으로 떨어지게 할 수 있을지도 모르지..."
rows["306:177206664"]=" ⁇ 리 가게에 오신 걸 환영합니다. 컷을 받으러 오세요? 색칠을 받으러 오세요?$B$B얼굴 머리카락을 꾸미고 피어싱을 할 수 있고 잉크 나이트 엘프 문신도 할 수 있고, 심지어 드레네이 뿔과 톱니도 재구조할 수 있습니다!$B$B앉으면 곧바로 일을 시작해줄게"
rows["306:228923387"]="이 나그란드의 아름다운 주변 경관을 망치는 구조물을 부르는 이름이지. 불타는 군단은 그 이동식 괴철로 기지에서 대량 파괴 무기를 만들려고 모아그와 간아그를 고용했지. 그들이 이곳 나그란드에 그걸 지어서 뭘 하든 신경 쓰지 않도록 하세!$B$B그대는 내 눈이 될 것이며 그대의 무기에는 내 분노가 담길 것일세."
rows["306:375750460"]="이곳이 언제 무슨 목적으로 생겼는진 알 수 없습니다.$B$B아마도 병력의 이동 경로로 쓰인 것 같습니다. 그런데 이곳엔 새까맣게 타고 고문당한 시체도 곳곳에 널려 있습니다. 온전한 모양이 아닌 것들도 있고, 대부분은 짓뭉개지거나 구타당한 모습입니다.$B$B이곳은 불의 땅이지만, 왠지 지옥의 문턱을 넘어온 듯한 느낌입니다."
rows["306:589955955"]="시로나스 님께서는 어떤 에레다르가 자신의 종족을 만아리로 변하게 할 수 있는 능력이 있다고 주장하셨습니다. 드레나이는 한때 에레다르였고 시로나스 님께서도 강력한 에레다르입니다.$B$B<소리 내어 웃는 첩보원>$B$B저 불쌍한 짐승들이 한때 강력한 악마들이었다는 사실을 믿을 수가 있습니까? 어떤 바보가 그렇게 강력한 힘을 거부하겠습니까?"
rows["307:1255869800"]="거대한 곰이 당신을 침착하고 부드러운 눈길로 바라봅니다. 곰의 것이라고 생각되는 말소리가 들리지만... 이상하게도 곰의 입은 전혀 움직이지 않습니다.$B$B\"반갑다, 어린 친구. 내게 뭔가 청이 있어서 온 것인가? 그대가 원하는 것을 얻을 수 있을 것이다.\""
rows["307:2144954482"]="잘 들게. 자네는 이미 어둠의 의회에서 특출난 실력을 증명했기 때문에 부관으로 고속 승진이 가능할 정도야. 나중에 돌아온다면 임무를 맡기도록 하지. 어둠의 의회는 비전 마법에 능숙한 자를 유독 반기지만, 동지가 되고 싶다면 직업이나 종족에 상관없이 누구나 환영한다네."
rows["307:278103364"]="전 깡총 군이랑 산책하러 나왔는데 중간에 길을 잃어버렸어요. 게다가 늑대들이 막 쫓아와서 너무 무서웠어요. 다행히 이 탑이 보여서 저랑 깡총 군이랑 이 안에 숨은 거예요. 늑대들은 결국 다 사라졌는데, 정말 무서웠고요, 우린 이제 집에 돌아가는 길도 몰라요."
rows["307:335694893"]="제 친구, 저는 Kelm Hargunth입니다. 워스송 아우트라이더의 주요 공급자입니다. 당신이 워스송 골치에서 사용할 수 있는 훌륭한 상품을 제공합니다. 당신이 물건을 수리할 필요가 있다면, 저는 또한 그 서비스를 제공합니다."
rows["307:445301024"]="동전을 충분히 모으면 맥주 사랑 동호회 회원이 될 수 있지요. 맥주 사랑 동호회에 가입하면 일 년 내내 가을 축제를 벌이는 것이나 마찬가지랍니다!$b$b매달 소식지와 함께 시음용 맥주를 보내 드립니다. 맥주가 입맛에 맞으면 아이언포지에 있는 부싯돌 선술집으로 가서 더 사면 되는 거지요."
rows["307:515428199"]="안녕하세요! 저는 남서쪽에 있는 켈테릴의 폐허를 조사하고 돌아왔답니다. 지금은 이곳 올빼미날개 숲의 산마루 위에 있는 올빼미야수들을 조사하는데 집중하고 있지요.$B$B루테란 마을에 있는 에렐라스 앰버스카이와 얘기해 본 적 있나요? 그가 절 이곳으로 와달라고 요청했었답니다. 아마도 그가 당신에게 임무를 줄 거예요."
rows["307:791739307"]="왜 음식을 요리해야 할거야? 모든 것이 입에 먼지가 맛있는데? 언더시티 브릴 남쪽에서 언더시티 수호자 그 곳에 도착하려면 리프트를 내려가서 로데론."
rows["308:2106850852"]="아웃랜드의 분쟁은 그 어떤 곳보다 더 심각한 파국으로 치닫고 있네. 그 싸움의 가장 불쌍한 희생양은 바로 부모를 잃고 홀로 남은 아이들이지.$B$B스케티스의 아라코아들이 샤트라스를 크게 위협하고 있는 지금, 그 어느 때보다 도움의 손길이 필요한 고아들이 많다네. 밝은 미래에 대한 어떠한 희망도 없이 살아가는 아이들이지."
rows["308:471430750"]="돌망치 일족은 호드를 위해 일한다네!$B$B오그리마 건설 당시, 우리들의 고향으로 칼림도어에 적응하고 있었을 때, 영웅이신 렉사르 님께서는 돌망치 일족의 수장을 그의 발밑에 무릎 꿇리셨네.$B$B그 후로 그들은 호드를 위해 일하고 있네. 난 골두니 일족을 상대로 하는 힘든 싸움을 풀어내고자 이들을 여기로 불러들인 것이고 말이야."
rows["308:660335671"]="10년 전, 이곳 하이잘 산 정상에서 엄청난 전투가 벌어졌어요. 파멸자 아키몬드는 악마들을 이끌고 세계수로 진격하여 세계수의 힘을 자신의 것으로 만들려 했죠.$B$B아키몬드가 패배하면서 군단의 아제로스 침략도 막을 내렸지만... 아키몬드의 타락한 추종자들은 여전히 많이 남았어요."
rows["309:1596482016"]="북쪽 부두에서는 루테란 마을과 다르나서스로 가는 배를 탈 수 있고 남쪽 부두에서는 대해를 건너 스톰윈드 항구로 갈 수 있네. 방파제의 맨 끝에 있는 서쪽 부두에서 엑소다르 근처인 하늘안개 섬으로 갈 수 있다네. 그럼, 편안하고 즐거운 여행이 되기를 빌지!"
rows["309:279866989"]="나는 일만 년 동안이나 이 왕국을 다스려왔습니다. 그동안 셴드랄라 가문의 신성한 땅을 밟은 자들에게서 흥미로운 이야기를 많이 들었지요.$B$B여기 매인 몸인지라 이곳을 찾는 이들을 통해 바깥세상의 이야기를 듣는 것입니다. 그대는 내게 들려주러 오셨나요? 아니면 내 이야기를 듣고자 오셨습니까?"
rows["309:463353097"]="지금 아제로스에서는 달의 축제가 한창입니다! 이 흥겨운 명절에 아제로스로 돌아가서 조상을 기리는 시간을 가져보세요! 달숲으로 가면 축제를 가장 화끈하게 즐길 수 있죠. 스톰윈드, 아이언포지, 다르나서스, 썬더 블러프, 오그리마, 그리고 언더시티에서 눈만 깜짝하면 달숲으로 순간이동할 수 있어요. 그럼, 축제에서 뵙죠!"
rows["309:556160359"]="세바인, 알리스타즈, 그리고 그롤은 그들의 부하들처럼 땅에 묶일 수도 있단 사실을 깨닫지 못했고... 라젤리크는 그들에게 불멸을 선물한 대가로 구속시켜 영원히 봉사할 것을 명했네. 라젤리크의 잔인한 교활함이 다시 한번 승리를 거둔 셈이지."
rows["30:1036503991"]="얼굴에 뭔가가 있어?"
rows["30:1189878518"]="해마가 참을성 있게 떠 있습니다."
rows["30:1207640751"]="곧 다시 만나게 될 거야..."
rows["30:1241529664"]="시시하군요! 분명히 노움이 만들었을 겁니다."
rows["30:1275095841"]="무슨 방향이 필요해?"
rows["30:1302105682"]="어째 느낌이 좋지 않은데요."
rows["30:1334474051"]="내가 뭐 도와줄 거라도 있는가?"
rows["30:1369099425"]="제발... 그를 격려하지 마"
rows["30:1419909265"]="어머... 누구신가 했네요!"
rows["30:145348790"]="하! 이 타우렌이 뽀뽀를 원한다고!"
rows["30:1501897821"]="아니... 아무리 폭신해 보여도 그렇지, 제 무릎 위에 앉으면 안 되지요."
rows["30:156115537"]="제가 어떻게 도와드릴까요, 이방인이여?"
rows["30:160484121"]="몸이 안 좋아 보이시는군요, 감독관님."
rows["30:167966944"]="이 세우는 일은 정말 힘든 일이야"
rows["30:1815582647"]="어떻게 들어갔느냐고요? 흠... 얘기하자면 길지요."
rows["30:1905164921"]="난 우리 왕을 섬기기 위해 살아가야 해"
rows["30:1909412612"]="어떻게 지원을 해 드리면 될까요?"
rows["30:2040405442"]="그대는 누구지? 나를 귀찮게 하지 마시오."
rows["30:2146320990"]="말을 걸었을 때만 대답하게."
rows["30:248135103"]="장비를 잘 준비하려면 항상 물품을 구입해야 하오."
rows["30:26679214"]="<웅웅 소리를 내는 차원문>"
rows["30:34451474"]="비행하기 좋은 날씨지. 그렇지 않소?"
rows["30:349480610"]="타는 법을 배우러 왔나?"
rows["30:373918175"]="훈련받으러 오셨습니까, 사냥꾼님?"
rows["30:392491791"]="투어를 이끌러 왔어?"
rows["30:454717949"]="영혼이 되어 돌아다니는 일은 꽤 힘이 듭니다."
rows["30:470850975"]="혼자 슬퍼하도록 제발 절 내버려 두세요."
rows["30:496735369"]="죄송하지만, 전 당신을 가르쳐 드릴 수 없어요."
rows["30:622232153"]="너희의 종말이 다가오고 있다."
rows["30:646224223"]="좋은 술이란 바로 독한 술을 말하는 거랍니다."
rows["30:678698132"]="이런 젠장, 또 당신입니까! 갈길이나 가세요!"
rows["30:793262421"]="베크지크를 귀찮게 하지 마라."
rows["30:826286792"]="이놈의 원숭이는 진짜로 골칫거리라니까!"
rows["30:850108028"]="스틸그릴의 정비소에 온 것을 환영하오!"
rows["310:1215962261"]="야호, 끝났다! 모두 물자 수집을 완료했소. 그리고 일전에 말했듯이 수집한 전쟁 물자는 비행선에 실어 실리더스로 공수 중이지. 늦어도 $2113w일 안에는 마지막 물자가 도착할 거요. 수송이 완료되고 파편들을 모아 홀이 하나로 합쳐지면 더러운 벌레들과의 전쟁이 시작되는 거지. 병사들의 표현을 빌리자면 한마디로 이런 거요. '보내 버려!'"
rows["310:235416256"]="그대는 정당한 동기와 진실한 마음을 지니고 행동합니까? 그렇다면, 동물을 윤리적이고 따뜻하게 대하는 동물보호협회를 대표해 그대를 환영합니다. 어둠의 꼬임에 넘어가 동물과 공존하지 않고 그들을 해치는 무리가 있습니다. 그대가 그런 행동만 하지 않는다면, 동물보호협회는 그대를 동맹으로 여길 겁니다."
rows["310:831873804"]="후회... 그것이 지금 내게 남은 전부요. 잘못된 판단 하나가 끔찍한 결과를 낳고 말았소. 명령서를 기다렸더라면 좋았을 것을. 그랬더라면 저주받은 땅에서 우리를 기다리고 있던 공포에 대해 알 수도 있었을 텐데! 어쩌면 다른 곳으로 파견되었을지도 모르지. 결국 내 잘못이었소. 모든 게 내 잘못이었소."
rows["311:1176908076"]="가까이 다가가 보니, 장비 안에 이상한 액체와 혼합물이 거품을 내며 끓고 있습니다. 장비 옆에는 수액괴물 견본을 집어넣는 데 쓸 법한 집게가 놓여 있습니다.$B$B안전 장비 비슷한 게 있는 것 같지만 먼지가 쌓여 있고 오랫동안 사용되지 않은 듯합니다.$B$B아무래도 건드리지 않는 것이 나을 것 같습니다."
rows["311:1315952212"]="아웃랜드 최고의 쇼에 오신 것을 환영합니다!$B$B어서 오셔서 마음껏 즐기세요. 다크문 유랑단이 이 드넓고 신비한 세계를 유랑하며 발견한 온갖 놀라운 물건들을 구경하시라니까요! 다양한 연령층의 어린이들이 모두 좋아할 만한 것들을 아낌없이 준비해 놓았답니다!"
